	public class LevelLight
	{
		public Light light;

		public HDAdditionalLightData lightData;

		public float initialIntensity;

		public Func<float> levelLogicDefinedIntensity;

		public float getInitialIntensity
		{
			get
			{
				if (levelLogicDefinedIntensity == null)
				{
					return initialIntensity;
				}
				return levelLogicDefinedIntensity();
			}
		}
	}

