	public class RoomEditorSkyData : IReadWrite
	{
		public float transitionTime;

		public float currentTransitionTime;

		public EditorSkybox sourceSkybox;

		public SkyboxType skyboxType;

		public Color topColorStart;

		public Color topColorGoal;

		public Color midColorStart;

		public Color midColorGoal;

		public Color botColorStart;

		public Color botColorGoal;

		public float horizonSizeStart;

		public float horizonSizeGoal;

		public float exposureStart;

		public float exposureGoal;

		public float exposure2Start;

		public float exposure2Goal;

		public float rotationStart;

		public float rotationGoal;

		[DontSave]
		public Texture cubemapStart;

		[DontSave]
		public Cubemap cubemapGoal;

		public float aersolDensityStart;

		public float aersolDensityGoal;

		public float alphaMultiplierStart;

		public float alphaMultiplierGoal;

		public virtual void Write(FastBinaryWriter writer)
		{
			writer.Write(in transitionTime, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in currentTransitionTime, default(FastBinaryWriter.ForPrimitives));
			writer.WriteComponent(sourceSkybox);
			int value = (int)skyboxType;
			writer.Write(in value, default(FastBinaryWriter.ForPrimitives));
			writer.WriteColor(in topColorStart);
			writer.WriteColor(in topColorGoal);
			writer.WriteColor(in midColorStart);
			writer.WriteColor(in midColorGoal);
			writer.WriteColor(in botColorStart);
			writer.WriteColor(in botColorGoal);
			writer.Write(in horizonSizeStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in horizonSizeGoal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in exposureStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in exposureGoal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in exposure2Start, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in exposure2Goal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in rotationStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in rotationGoal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in aersolDensityStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in aersolDensityGoal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in alphaMultiplierStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in alphaMultiplierGoal, default(FastBinaryWriter.ForPrimitives));
		}

		public virtual void Read(FastBinaryReader reader)
		{
			transitionTime = reader.ReadSingle();
			currentTransitionTime = reader.ReadSingle();
			sourceSkybox = reader.ReadComponent<EditorSkybox>();
			skyboxType = (SkyboxType)reader.ReadInt32();
			topColorStart = reader.ReadColor();
			topColorGoal = reader.ReadColor();
			midColorStart = reader.ReadColor();
			midColorGoal = reader.ReadColor();
			botColorStart = reader.ReadColor();
			botColorGoal = reader.ReadColor();
			horizonSizeStart = reader.ReadSingle();
			horizonSizeGoal = reader.ReadSingle();
			exposureStart = reader.ReadSingle();
			exposureGoal = reader.ReadSingle();
			exposure2Start = reader.ReadSingle();
			exposure2Goal = reader.ReadSingle();
			rotationStart = reader.ReadSingle();
			rotationGoal = reader.ReadSingle();
			aersolDensityStart = reader.ReadSingle();
			aersolDensityGoal = reader.ReadSingle();
			alphaMultiplierStart = reader.ReadSingle();
			alphaMultiplierGoal = reader.ReadSingle();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("transitionTime: " + $"{transitionTime}");
			stringBuilder.AppendLine("currentTransitionTime: " + $"{currentTransitionTime}");
			stringBuilder.AppendLine("sourceSkybox: " + $"{sourceSkybox}");
			stringBuilder.AppendLine("skyboxType: " + $"{skyboxType}");
			stringBuilder.AppendLine("topColorStart: " + $"{topColorStart}");
			stringBuilder.AppendLine("topColorGoal: " + $"{topColorGoal}");
			stringBuilder.AppendLine("midColorStart: " + $"{midColorStart}");
			stringBuilder.AppendLine("midColorGoal: " + $"{midColorGoal}");
			stringBuilder.AppendLine("botColorStart: " + $"{botColorStart}");
			stringBuilder.AppendLine("botColorGoal: " + $"{botColorGoal}");
			stringBuilder.AppendLine("horizonSizeStart: " + $"{horizonSizeStart}");
			stringBuilder.AppendLine("horizonSizeGoal: " + $"{horizonSizeGoal}");
			stringBuilder.AppendLine("exposureStart: " + $"{exposureStart}");
			stringBuilder.AppendLine("exposureGoal: " + $"{exposureGoal}");
			stringBuilder.AppendLine("exposure2Start: " + $"{exposure2Start}");
			stringBuilder.AppendLine("exposure2Goal: " + $"{exposure2Goal}");
			stringBuilder.AppendLine("rotationStart: " + $"{rotationStart}");
			stringBuilder.AppendLine("rotationGoal: " + $"{rotationGoal}");
			stringBuilder.AppendLine("aersolDensityStart: " + $"{aersolDensityStart}");
			stringBuilder.AppendLine("aersolDensityGoal: " + $"{aersolDensityGoal}");
			stringBuilder.AppendLine("alphaMultiplierStart: " + $"{alphaMultiplierStart}");
			stringBuilder.Append("alphaMultiplierGoal: " + $"{alphaMultiplierGoal}");
			return stringBuilder.ToString();
		}
	}

