			writer.Write(in currentSpeedDirectionStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in currentSpeedDirectionGoal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in amplitudeModifierStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in amplitudeModifierGoal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in rippleSpeedStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in rippleSpeedGoal, default(FastBinaryWriter.ForPrimitives));
			writer.WriteColor(in refractionColorStart);
			writer.WriteColor(in refractionColorGoal);
			writer.WriteColor(in waterColorStart);
			writer.WriteColor(in waterColorGoal);
			writer.Write(in ambientIntensityStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in ambientIntensityGoal, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in heightStart, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in heightGoal, default(FastBinaryWriter.ForPrimitives));
		}

		public virtual void Read(FastBinaryReader reader)
		{
			transitionTime = reader.ReadSingle();
			currentTransitionTime = reader.ReadSingle();
			distantWindSizeStart = reader.ReadSingle();
			distantWindSizeGoal = reader.ReadSingle();
			chaosStart = reader.ReadSingle();
			chaosGoal = reader.ReadSingle();
			currentSpeedStart = reader.ReadSingle();
			currentSpeedGoal = reader.ReadSingle();
			currentSpeedDirectionStart = reader.ReadSingle();
			currentSpeedDirectionGoal = reader.ReadSingle();
			amplitudeModifierStart = reader.ReadSingle();
			amplitudeModifierGoal = reader.ReadSingle();
			rippleSpeedStart = reader.ReadSingle();
			rippleSpeedGoal = reader.ReadSingle();
			refractionColorStart = reader.ReadColor();
			refractionColorGoal = reader.ReadColor();
			waterColorStart = reader.ReadColor();
			waterColorGoal = reader.ReadColor();
			ambientIntensityStart = reader.ReadSingle();
			ambientIntensityGoal = reader.ReadSingle();
			heightStart = reader.ReadSingle();
			heightGoal = reader.ReadSingle();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("transitionTime: " + $"{transitionTime}");
			stringBuilder.AppendLine("currentTransitionTime: " + $"{currentTransitionTime}");
