	[Serializable]
	public class Hint
	{
		public static readonly Func<bool> DefaultIsSolvedCondition = () => false;

		public GameObject gameObject;

		[NonSerialized]
		public bool isFinished;

		[NonSerialized]
		public Func<bool> isSolvedCondition = DefaultIsSolvedCondition;

		public bool isDone()
		{
			try
			{
				return isFinished || isSolvedCondition();
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError($"Exception in hint solved condition for hint '{gameObject}': {ex.Message}");
				UnityEngine.Debug.LogException(ex);
				isFinished = true;
				return true;
			}
		}
	}

