	public class StateMachine<T> where T : Enum
	{
		public T current;

		public T newState;

		public T last;

		public float time;

		public bool changed;

		public Action onChange;

		public bool forceChange;

		public void update()
		{
			time += Time.deltaTime;
			changed = false;
			if (!EqualityComparer<T>.Default.Equals(current, newState))
			{
				last = current;
				current = newState;
				time = 0f;
				changed = true;
				onChange?.Invoke();
			}
		}

		public void changeState(T state)
		{
			newState = state;
			if (forceChange)
			{
				update();
			}
		}
	}

	public class LadderMovementRuntimeData : IReadWrite
	{
		public Ladder ladder;

		public Transform startEmpty;

		public Vector3 startExit;

		public Transform endEmpty;

		public Vector3 endExit;

		public LadderMovementStage stage;

		public bool jumpoffGoingToEndExit;

		public virtual void Write(FastBinaryWriter writer)
		{
			writer.WriteComponent(ladder);
			writer.WriteComponent(startEmpty);
			writer.WriteVector3(in startExit);
			writer.WriteComponent(endEmpty);
			writer.WriteVector3(in endExit);
			int value = (int)stage;
			writer.Write(in value, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in jumpoffGoingToEndExit, default(FastBinaryWriter.ForPrimitives));
		}

		public virtual void Read(FastBinaryReader reader)
		{
			ladder = reader.ReadComponent<Ladder>();
			startEmpty = reader.ReadComponent<Transform>();
			startExit = reader.ReadVector3();
			endEmpty = reader.ReadComponent<Transform>();
			endExit = reader.ReadVector3();
			stage = (LadderMovementStage)reader.ReadInt32();
			jumpoffGoingToEndExit = reader.ReadBoolean();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("ladder: " + $"{ladder}");
			stringBuilder.AppendLine("startEmpty: " + $"{startEmpty}");
			stringBuilder.AppendLine("startExit: " + $"{startExit}");
			stringBuilder.AppendLine("endEmpty: " + $"{endEmpty}");
			stringBuilder.AppendLine("endExit: " + $"{endExit}");
			stringBuilder.AppendLine("stage: " + $"{stage}");
			stringBuilder.Append("jumpoffGoingToEndExit: " + $"{jumpoffGoingToEndExit}");
			return stringBuilder.ToString();
		}
	}

