	private class InteractiveRaycastComparer : IComparer<RaycastHit>
	{
		private bool TryGetComponentInParent(Transform transform, out Interactive interactive)
		{
			Transform transform2 = transform;
			interactive = null;
			while (transform2 != null)
			{
				if (transform2.TryGetComponent<Interactive>(out var component))
				{
					interactive = component;
					return true;
				}
				transform2 = transform2.parent;
			}
			return false;
		}

		public int Compare(RaycastHit x, RaycastHit y)
		{
			float num = x.distance;
			float num2 = y.distance;
			if (TryGetComponentInParent(x.collider.transform, out var interactive))
			{
				num -= interactive.distanceExtender;
			}
			if (TryGetComponentInParent(y.collider.transform, out var interactive2))
			{
				num2 -= interactive2.distanceExtender;
			}
			return num.CompareTo(num2);
		}
	}

