	private readonly NonAllocSortBuffer<VRHit> vrHitBuffer = new NonAllocSortBuffer<VRHit>(256, delegate(VRHit hit1, VRHit hit2)
	{
		int num = hit1.isFromRaycast.CompareTo(hit2.isFromRaycast);
		if (num != 0)
		{
			return num;
		}
		if (!hit1.isFromRaycast)
		{
			bool value = isSmallItem(hit1.gameObject);
			num = isSmallItem(hit2.gameObject).CompareTo(value);
			if (num != 0)
			{
				return num;
			}
		}
		return hit1.distance.CompareTo(hit2.distance);
		static bool isSmallItem(GameObject go)
		{
			return false;
		}
	});

