	public void impostorCloneExplicitSync(Transform transform, float duration = 0f)
	{
		if (impostorContext.explicitSync.ContainsKey(transform))
		{
			impostorContext.explicitSync[transform] = Time.time + duration;
		}
	}

	public void impostorCloneOnChangeChildSync(Transform transform)
	{
		if (impostorContext != null && impostorContext.onChangeSync.Count > 0)
		{
			updateImpostorParent(transform);
		}
		void updateImpostorParent(Transform newParent)
		{
			if (impostorContext.onChangeSync.ContainsKey(newParent))
			{
				impostorContext.onChangeSync[newParent] = true;
			}
			else if (newParent.parent != null)
			{
				updateImpostorParent(newParent.parent);
			}
		}
	}

	public void addToImpostorCloneOnChange(Transform _transform)
	{
		if (!impostorContext.onChangeSync.ContainsKey(_transform))
		{
			impostorContext.onChangeSync[_transform] = false;
		}
	}

	private bool canExecuteLocalOnlyEvents()
	{
		if (luaLocalPlayerTriggerState == LuaLevelLogic.LocalPlayerTriggerState.NotProcessing)
		{
			return !isProcessingPacket;
		}
		return luaLocalPlayerTriggerState == LuaLevelLogic.LocalPlayerTriggerState.LocalPlayer;
	}

	public PineTweenSystemEnableNoHandles getGameplayTween()
	{
		if (!isProcessingPacket)
		{
			return gameplayTweenSP;
		}
		return gameplayTweenMP;
	}

	public void destroyGameplayTweens(GameObject gameObject, bool performEvents = true, bool performFinalUpdate = true)
	{
		gameplayTweenSP.destroyTweens(gameObject, performEvents, performFinalUpdate);
		bool flag = isProcessingPacket;
		isProcessingPacket = true;
		gameplayTweenMP.destroyTweens(gameObject, performEvents, performFinalUpdate);
		isProcessingPacket = flag;
	}

	public void destroyGameplayAnimations(GameObject gameObject, bool performEvents = true)
	{
		gameplayTweenSP.destroyTweens(gameObject, performEvents);
		bool flag = isProcessingPacket;
		isProcessingPacket = true;
		gameplayTweenMP.destroyTweens(gameObject, performEvents);
		isProcessingPacket = flag;
	}

