	}

	private void syncControlMode()
	{
		if (controlMode.changed)
		{
			if (controlMode.current == ControlMode.MouseAndKeyboard)
			{
				cursorVisible.changeState(CursorVisibleState.Hidden);
				syncInventoryForMouseAndKeyboard();
				if (pcSelectedItemScreenSpace != null)
				{
					pcSelectedItemScreenSpace.SetActive(value: true);
				}
				openMenuButton.SetActive(value: false);
				heightSlider.transform.localScale = Vector3.zero;
			}
			else
			{
				syncInventoryForOtherControlModes();
				if (pcSelectedItemScreenSpace != null)
				{
					pcSelectedItemScreenSpace.SetActive(value: false);
				}
				openMenuButton.SetActive(value: true);
				heightSlider.transform.localScale = Vector3.one;
				if (controlMode.current == ControlMode.AR)
				{
					PineAR.init();
					PineAR.setNearAndFarZPlanes(playerCamera.nearClipPlane, playerCamera.farClipPlane);
					PineAR.runSession(planeDetect: true);
				}
			}
			dragIcon.gameObject.SetActive(value: false);
			bool flag = controlMode.current == ControlMode.VirtualGamepad;
			analogueStick.gameObject.SetActive(value: false);
			OffscreenLocation component = heightSlider.GetComponent<OffscreenLocation>();
			component.alternateLocation = !flag;
			heightSlider.GetComponent<RectTransform>().anchoredPosition = component.calculateLocation(offscreen: false);
			heightSlider.gameObject.SetActive(value: false);
		}
		if (controlMode.current == ControlMode.MouseAndKeyboard)
		{
			EscapeSimulatorSteamInputActionSets set = EscapeSimulatorSteamInputActionSets.Game;
			GameState current = gameState.current;
			if (current == GameState.Menu || current == GameState.Zoom || current == GameState.FinishLevel)
			{
				set = EscapeSimulatorSteamInputActionSets.UI;
			}
			if (gameState.current == GameState.CustomMode && localPlayerData.customMode != null && localPlayerData.customMode.isUICustomMode)
			{
				set = EscapeSimulatorSteamInputActionSets.UI;
			}
			Controller.updateController(menuOptions, set);
			if (Controller.controllerModeChanged)
			{
				killAllPointers();
				syncControllerSpecificObjects();
				syncControllerInventorySlotPositions();
			}
		}
		controllerInventoryHints[1].anchoredPosition = new Vector3(inventoryCanvas.anchoredPosition.x + inventoryCanvas.rect.width + 20f, controllerInventoryHints[1].anchoredPosition.y);
	}

	private void syncControllerSpecificObjects()
	{
		bool flag = Controller.isActive();
		GameObject[] array = disableWhenControllerPresent;
		foreach (GameObject gameObject in array)
		{
			if (gameObject != null)
			{
				gameObject.SetActive(!flag);
			}
		}
		array = enableWhenControllerPresent;
		foreach (GameObject gameObject2 in array)
		{
			if (gameObject2 != null)
			{
				gameObject2.SetActive(flag);
			}
		}
		if (!Controller.isActive() && inSlotInventoryFocus)
		{
			exitFocusMode();
		}
	}

