	private void initLights()
	{
		Light[] componentsInChildren = levelContainer.GetComponentsInChildren<Light>(includeInactive: true);
		foreach (Light light in componentsInChildren)
		{
			if (light.bakingOutput.lightmapBakeType != LightmapBakeType.Baked)
			{
				HDAdditionalLightData hDAdditionalLightData = light.GetComponent<HDAdditionalLightData>();
				if (hDAdditionalLightData == null)
				{
					hDAdditionalLightData = light.gameObject.AddComponent<HDAdditionalLightData>();
				}
				levelLights.Add(new LevelLight
				{
					light = light,
					lightData = hDAdditionalLightData,
					initialIntensity = hDAdditionalLightData.intensity
				});
			}
		}
		ReflectionProbe[] componentsInChildren2 = levelContainer.GetComponentsInChildren<ReflectionProbe>(includeInactive: true);
		foreach (ReflectionProbe reflectionProbe in componentsInChildren2)
		{
			HDAdditionalReflectionData hDAdditionalReflectionData = reflectionProbe.GetComponent<HDAdditionalReflectionData>();
			if (hDAdditionalReflectionData == null)
			{
				hDAdditionalReflectionData = reflectionProbe.gameObject.AddComponent<HDAdditionalReflectionData>();
			}
			hDAdditionalReflectionData.lightLayers = hDAdditionalReflectionData.lightLayers | UnityEngine.Rendering.HighDefinition.RenderingLayerMask.RenderingLayer7 | UnityEngine.Rendering.HighDefinition.RenderingLayerMask.RenderingLayer6;
		}
		foreach (LevelLight levelLight in levelLights)
		{
			levelLight.lightData.lightlayersMask = levelLight.lightData.lightlayersMask | UnityEngine.Rendering.HighDefinition.RenderingLayerMask.RenderingLayer7 | UnityEngine.Rendering.HighDefinition.RenderingLayerMask.RenderingLayer6;
		}
		lightModifiers = levelContainer.GetComponentsInChildren<CharacterLightModifier>(includeInactive: true);
		CharacterLightModifier[] array = lightModifiers;
		foreach (CharacterLightModifier characterLightModifier in array)
		{
			if (characterLightModifier.TryGetComponent<Light>(out var component))
			{
				characterLightModifier.originalLight = component;
				characterLightModifier.originalLightHD = component.GetComponent<HDAdditionalLightData>();
				if (characterLightModifier.originalLightHD == null)
				{
					characterLightModifier.originalLightHD = component.gameObject.AddComponent<HDAdditionalLightData>();
				}
				characterLightModifier.originalLightHD.lightlayersMask = UnityEngine.Rendering.HighDefinition.RenderingLayerMask.RenderingLayer1;
				characterLightModifier.targetLight = UnityEngine.Object.Instantiate(component.gameObject, component.transform).GetComponent<Light>();
				characterLightModifier.targetLight.transform.localPosition = Vector3.zero;
				characterLightModifier.targetLight.transform.localRotation = Quaternion.identity;
				characterLightModifier.targetLight.transform.localScale = Vector3.one;
				UnityEngine.Object.Destroy(characterLightModifier.targetLight.gameObject.GetComponent<CharacterLightModifier>());
				characterLightModifier.targetLightHD = characterLightModifier.targetLight.GetComponent<HDAdditionalLightData>();
				if (characterLightModifier.targetLightHD == null)
				{
					characterLightModifier.targetLightHD = characterLightModifier.targetLight.gameObject.AddComponent<HDAdditionalLightData>();
				}
				characterLightModifier.targetLightHD.affectsVolumetric = false;
				characterLightModifier.targetLight.shadows = LightShadows.None;
				characterLightModifier.targetLightHD.lightlayersMask = UnityEngine.Rendering.HighDefinition.RenderingLayerMask.RenderingLayer6 | UnityEngine.Rendering.HighDefinition.RenderingLayerMask.RenderingLayer7;
			}
		}
		updateLightModifiers();
	}

	private void warmUpShaders()
	{
		HashSet<Material> hashSet = new HashSet<Material>(1024);
		Item[] array = allItems;
		Renderer[] componentsInChildren;
		for (int i = 0; i < array.Length; i++)
		{
			componentsInChildren = array[i].GetComponentsInChildren<Renderer>(includeInactive: true);
			for (int j = 0; j < componentsInChildren.Length; j++)
			{
				Material[] sharedMaterials = componentsInChildren[j].sharedMaterials;
				foreach (Material material in sharedMaterials)
				{
					if (material != null)
					{
						hashSet.Add(material);
					}
				}
			}
		}
		UnityEngine.Debug.Log($"Item Unique Material Count {hashSet.Count}");
		Material[] array2 = new Material[hashSet.Count];
		hashSet.CopyTo(array2);
		warmUpShaderState.itemMaterials = createMaterialStrip(array2);
		warmUpShaderState.itemMaterials.layer = LayerMask.NameToLayer("Zoom");
		warmUpShaderState.itemMaterials.transform.SetParent(playerCamera.transform);
		warmUpShaderState.itemMaterials.transform.localPosition = new Vector3(0.5f, 0f, 2f);
		warmUpShaderState.itemMaterials.transform.localScale = Vector3.one * 0.05f;
		warmUpShaderState.itemMaterials.transform.localRotation = Quaternion.Euler(-90f, 0f, 0f);
		hashSet.Clear();
		componentsInChildren = levelContainer.GetComponentsInChildren<Renderer>(includeInactive: true);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			Material[] sharedMaterials = componentsInChildren[i].sharedMaterials;
			foreach (Material material2 in sharedMaterials)
			{
				if (material2 != null)
				{
					hashSet.Add(material2);
				}
			}
		}
		UnityEngine.Debug.Log($"Scene Unique Material Count {hashSet.Count}");
		array2 = new Material[hashSet.Count];
		hashSet.CopyTo(array2);
		warmUpShaderState.allMaterials = createMaterialStrip(array2);
		warmUpShaderState.allMaterials.transform.SetParent(playerCamera.transform);
		warmUpShaderState.allMaterials.transform.localPosition = new Vector3(-0.5f, 0f, 2f);
		warmUpShaderState.allMaterials.transform.localScale = Vector3.one * 0.05f;
		warmUpShaderState.allMaterials.transform.localRotation = Quaternion.Euler(-90f, 0f, 0f);
		warmUpShaderState.frameWait = 5;
		warmUpShaderState.state = WarmUpState.Wait;
		if (isTestingPlaymodeInEditor)
		{
			warmUpShaderState.endCondition = LoadingCanvas.get().enqueueEndCondition("", "");
		}
		else
		{
			warmUpShaderState.endCondition = LoadingCanvas.get().enqueueEndCondition(Localization.lookupInDictionary("compilingShaders"), LoadingCanvas.get().getTopEndCondition().title);
		}
		static GameObject createMaterialStrip(Material[] materials)
		{
			int num = materials.Length;
			int num2 = Mathf.CeilToInt(Mathf.Sqrt(num));
			Vector3[] array3 = new Vector3[num * 4];
			Vector2[] array4 = new Vector2[num * 4];
			for (int l = 0; l < num; l++)
			{
				int num3 = l % num2;
				int num4 = l / num2;
				array3[l * 4] = new Vector3(num3, 0f, num4);
				array3[l * 4 + 1] = new Vector3(num3 + 1, 0f, num4);
				array3[l * 4 + 2] = new Vector3(num3 + 1, 0f, num4 + 1);
				array3[l * 4 + 3] = new Vector3(num3, 0f, num4 + 1);
				array4[l * 4] = new Vector2(0f, 0f);
				array4[l * 4 + 1] = new Vector2(1f, 0f);
				array4[l * 4 + 2] = new Vector2(1f, 1f);
				array4[l * 4 + 3] = new Vector2(0f, 1f);
			}
			Mesh mesh = new Mesh();
			mesh.name = "MaterialStrip";
			mesh.SetVertices(array3);
			mesh.SetUVs(0, array4);
			mesh.subMeshCount = num;
			int[] array5 = new int[6];
			for (int m = 0; m < num; m++)
			{
				array5[0] = m * 4;
				array5[1] = m * 4 + 2;
				array5[2] = m * 4 + 1;
				array5[3] = m * 4;
				array5[4] = m * 4 + 3;
				array5[5] = m * 4 + 2;
				mesh.SetTriangles(array5, m);
			}
			mesh.RecalculateNormals();
			mesh.RecalculateBounds();
			GameObject obj = new GameObject("MaterialStrip");
			MeshFilter meshFilter = obj.AddComponent<MeshFilter>();
			MeshRenderer meshRenderer = obj.AddComponent<MeshRenderer>();
			meshFilter.mesh = mesh;
			meshRenderer.sharedMaterials = materials;
			obj.layer = LayerMask.NameToLayer("Zoom");
			return obj;
		}
	}

	private void initTokensInLevel()
	{
		tokenCountTotal.text = tokens.Length.ToString();
		for (int i = 0; i < tokens.Length; i++)
		{
			if (!syncedFoundTokens.Contains(i))
			{
				continue;
			}
			Renderer[] componentsInChildren = tokens[i].GetComponentsInChildren<Renderer>();
			foreach (Renderer renderer in componentsInChildren)
			{
				Texture mainTexture = renderer.material.mainTexture;
				renderer.material = tokenGhostMaterial;
				if (tokens[i].overridePickedUpTexture)
				{
					renderer.material.mainTexture = mainTexture;
				}
			}
		}
		tokenCountCurrent.text = syncedFoundTokens.Count.ToString();
	}

