	private void syncWorkshopRate()
	{
		SteamAPICall_t userItemVote = SteamUGC.GetUserItemVote(new PublishedFileId_t(customRoomData.roomId));
		CallResult<GetUserItemVoteResult_t> callResult = CallResult<GetUserItemVoteResult_t>.Create(delegate(GetUserItemVoteResult_t t, bool failure)
		{
			if (workshopThumbsUpEnabled != null)
			{
				workshopThumbsUpEnabled.SetActive(t.m_bVotedUp);
				workshopThumbsUpDisabled.SetActive(!t.m_bVotedUp);
				workshopThumbsDownEnabled.SetActive(t.m_bVotedDown);
				workshopThumbsDownDisabled.SetActive(!t.m_bVotedDown);
			}
		});
		callResult.Set(userItemVote);
		gcDontKill.Add(callResult);
	}

