	private void translateScene()
	{
		allTranslatableTextures = levelContainer.GetComponentsInChildren<TranslatableTexture>(includeInactive: true);
		Language language = getLanguage();
		if (language == Language.English)
		{
			TranslatableTexture[] array = allTranslatableTextures;
			foreach (TranslatableTexture translatableTexture in array)
			{
				Renderer component = translatableTexture.GetComponent<Renderer>();
				if (component != null)
				{
					if (component is SpriteRenderer)
					{
						if (translatableTexture.originalSprite != null)
						{
							((SpriteRenderer)component).sprite = translatableTexture.originalSprite;
							if (translatableTexture.originalSpriteMaterialTexture != null && component.sharedMaterial != null)
							{
								component.material.SetTexture("_BaseColorMap", translatableTexture.originalSpriteMaterialTexture);
							}
						}
					}
					else
					{
						if (translatableTexture.originalTextures == null)
						{
							continue;
						}
						for (int j = 0; j < component.materials.Length; j++)
						{
							Texture texture = translatableTexture.originalTextures[j];
							if (texture != null)
							{
								component.materials[j].mainTexture = texture;
								if (translatableTexture.useCustomTextureKeyword)
								{
									component.materials[j].SetTexture(translatableTexture.customTextureKeyword, texture);
								}
							}
							Texture texture2 = translatableTexture.originalNormalMaps[j];
							if (texture2 != null)
							{
								component.materials[j].SetTexture("_BumpMap", texture2);
							}
							Texture texture3 = translatableTexture.originalEmissionMaps[j];
							if (texture3 != null)
							{
								component.materials[j].SetTexture("_EmissiveColorMap", texture3);
							}
							Texture texture4 = translatableTexture.originalMetallicMaps[j];
							if (texture4 != null)
							{
								component.materials[j].SetTexture("_MetallicGlossMap", texture4);
							}
							if (translatableTexture.originalEmissionOn[j])
							{
								component.materials[j].EnableKeyword("_EMISSION");
							}
							else
							{
								component.materials[j].DisableKeyword("_EMISSION");
							}
						}
					}
					continue;
				}
				Image component2 = translatableTexture.GetComponent<Image>();
				if (component2 != null)
				{
					if (translatableTexture.originalSprite != null)
					{
						component2.sprite = translatableTexture.originalSprite;
					}
				}
				else
				{
					UnityEngine.Debug.LogError("There is no component that could be translated. " + translatableTexture.name);
				}
			}
			return;
		}
		string text = (Is.Oculus ? Path.Combine("/sdcard/Android/obb/com.PineStudio.EscapeSimulator", SceneManager.GetActiveScene().name.ToLower() + language.ToString().ToLower()) : ((getDlc() != DLC.None) ? Path.Combine(Menu.dlcBasePath(), getDlc().ToString() + "_tt", SceneManager.GetActiveScene().name.ToLower() + language.ToString().ToLower()) : Path.Combine(UnityEngine.Application.streamingAssetsPath, "AssetBundles", "Translations", language.ToString(), SceneManager.GetActiveScene().name.ToLower() + language.ToString().ToLower())));
		UnityEngine.Debug.Log("Trying to translate with asset bundle: " + text);
		if (File.Exists(text))
		{
			UnityEngine.Debug.Log("Translating textures with ASSET BUNDLE:" + language);
			AssetBundle translationBundle = AssetBundle.LoadFromFile(text);
			translateTextures(allTranslatableTextures, (string x) => translationBundle.LoadAsset<Texture>(x));
			translationBundle.Unload(unloadAllLoadedObjects: false);
		}
		else
		{
			UnityEngine.Debug.Log("Failed to translate textures with asset bundle");
		}
	}

	private void translateTextures(TranslatableTexture[] allToTranslate, Func<string, Texture> loadAction)
	{
		Language language = getLanguage();
		foreach (TranslatableTexture translatableTexture in allToTranslate)
		{
			Renderer component = translatableTexture.GetComponent<Renderer>();
			if (component != null)
			{
				if (component is SpriteRenderer)
				{
					SpriteRenderer spriteRenderer = (SpriteRenderer)component;
					if (translatableTexture.originalSprite == null)
					{
						translatableTexture.originalSprite = spriteRenderer.sprite;
					}
					bool flag = component.sharedMaterial != null && component.sharedMaterial.HasTexture("_BaseColorMap") && component.sharedMaterial.GetTexture("_BaseColorMap") != null;
					if (flag)
					{
						translatableTexture.originalSpriteMaterialTexture = (Texture2D)component.sharedMaterial.GetTexture("_BaseColorMap");
					}
					string text = translatableTexture.ids[0];
					if (language != Language.English)
					{
						text = UnityUtils.addSuffixToFileName(text, "_" + language);
					}
					Texture texture = loadAction(text);
					if (texture != null && translatableTexture.getShouldTranslate(0))
					{
						Sprite sprite = spriteRenderer.sprite;
						Sprite sprite2 = Sprite.Create((Texture2D)texture, sprite.rect, new Vector2(sprite.pivot.x / sprite.rect.width, sprite.pivot.y / sprite.rect.height), sprite.pixelsPerUnit, 0u, SpriteMeshType.FullRect, sprite.border);
						if (flag)
						{
							component.material.SetTexture("_BaseColorMap", texture);
						}
						spriteRenderer.sprite = sprite2;
					}
					continue;
				}
				bool flag2 = translatableTexture.originalTextures == null;
				if (flag2)
				{
					translatableTexture.originalTextures = new Texture[component.materials.Length];
					translatableTexture.originalNormalMaps = new Texture[component.materials.Length];
					translatableTexture.originalEmissionMaps = new Texture[component.materials.Length];
					translatableTexture.originalMetallicMaps = new Texture[component.materials.Length];
					translatableTexture.originalEmissionOn = new bool[component.materials.Length];
				}
				for (int j = 0; j < component.materials.Length; j++)
				{
					string text2 = translatableTexture.ids[j];
					if (string.IsNullOrEmpty(text2) || !translatableTexture.getShouldTranslate(j))
					{
						continue;
					}
					text2 = UnityUtils.addSuffixToFileName(text2, "_" + language);
					if (flag2)
					{
						translatableTexture.originalTextures[j] = component.materials[j].mainTexture;
						translatableTexture.originalNormalMaps[j] = (component.materials[j].HasTexture("_BumpMap") ? component.materials[j].GetTexture("_BumpMap") : null);
						translatableTexture.originalEmissionMaps[j] = (component.materials[j].HasTexture("_EmissiveColorMap") ? component.materials[j].GetTexture("_EmissiveColorMap") : null);
						translatableTexture.originalMetallicMaps[j] = (component.materials[j].HasTexture("_MetallicGlossMap") ? component.materials[j].GetTexture("_MetallicGlossMap") : null);
						translatableTexture.originalEmissionOn[j] = component.materials[j].IsKeywordEnabled("_EMISSION");
						if (translatableTexture.useCustomTextureKeyword)
						{
							translatableTexture.originalTextures[j] = (component.materials[j].HasTexture(translatableTexture.customTextureKeyword) ? component.materials[j].GetTexture(translatableTexture.customTextureKeyword) : null);
						}
					}
					Texture texture2 = loadAction(text2);
					if (texture2 != null)
					{
						component.materials[j].mainTexture = texture2;
						if (translatableTexture.useCustomTextureKeyword)
						{
							component.materials[j].SetTexture(translatableTexture.customTextureKeyword, texture2);
						}
					}
					if (translatableTexture.clearNormalmapOnNonEnglish)
					{
						component.materials[j].SetTexture("_BumpMap", null);
					}
					if (translatableTexture.clearEmissionmapOnNonEnglish)
					{
						component.materials[j].SetTexture("_EmissiveColorMap", null);
						component.materials[j].DisableKeyword("_EMISSION");
					}
					if (translatableTexture.clearMetallicmapOnNonEnglish)
					{
						component.materials[j].SetTexture("_MetallicGlossMap", null);
						component.materials[j].SetFloat("_Metallic", 0f);
					}
					if (translatableTexture.useBaseAsEmission)
					{
						component.materials[j].SetTexture("_EmissiveColorMap", texture2);
						component.materials[j].EnableKeyword("_EMISSION");
					}
				}
				continue;
			}
			Image component2 = translatableTexture.GetComponent<Image>();
			if (component2 != null)
			{
				if (translatableTexture.originalSprite == null)
				{
					translatableTexture.originalSprite = component2.sprite;
				}
				string arg = UnityUtils.addSuffixToFileName(translatableTexture.ids[0], "_" + language);
				Texture texture3 = loadAction(arg);
				if (!(texture3 != null))
				{
					continue;
				}
				Texture2D texture2D = (Texture2D)texture3;
				Sprite sprite3 = null;
				try
				{
					sprite3 = Sprite.Create(texture2D, component2.sprite.rect, component2.sprite.pivot, 100f, 1u, SpriteMeshType.FullRect);
				}
				catch
				{
					UnityEngine.Debug.Log("Error creating sprite with sprite rect. Trying with tex rect " + component2.name);
					try
					{
						sprite3 = Sprite.Create(texture2D, new Rect(0f, 0f, texture2D.width, texture2D.height), component2.sprite.pivot, 100f, 1u, SpriteMeshType.FullRect);
					}
					catch (Exception)
					{
						UnityEngine.Debug.Log("Error creating sprite with tex rect. Trying with default settings " + component2.name);
						try
						{
							sprite3 = Sprite.Create(texture2D, new Rect(0f, 0f, texture2D.width, texture2D.height), component2.sprite.pivot);
							goto end_IL_0585;
						}
						catch (Exception)
						{
							UnityEngine.Debug.Log("Error creating sprite with any setting. " + component2.name);
							goto end_IL_0585;
						}
						end_IL_0585:;
					}
				}
				component2.sprite = sprite3;
			}
			else
			{
				UnityEngine.Debug.LogError("There is no component that could be translated. " + translatableTexture.name);
			}
		}
	}

