	private void Debug_drawBoundsLocal(Bounds bounds, Transform transform, Color colorBounds, Color colorCenter)
	{
		Vector3 vector = transform.position + Vector3.Scale(transform.rotation * bounds.center, transform.localScale);
		Vector3 vector2 = Vector3.Scale(bounds.extents, transform.localScale);
		Vector3 vector3 = new Vector3(0f - vector2.x, vector2.y, 0f - vector2.z);
		Vector3 vector4 = new Vector3(vector2.x, vector2.y, 0f - vector2.z);
		Vector3 vector5 = new Vector3(0f - vector2.x, 0f - vector2.y, 0f - vector2.z);
		Vector3 vector6 = new Vector3(vector2.x, 0f - vector2.y, 0f - vector2.z);
		Vector3 vector7 = new Vector3(0f - vector2.x, vector2.y, vector2.z);
		Vector3 vector8 = new Vector3(vector2.x, vector2.y, vector2.z);
		Vector3 vector9 = new Vector3(0f - vector2.x, 0f - vector2.y, vector2.z);
		Vector3 vector10 = new Vector3(vector2.x, 0f - vector2.y, vector2.z);
		vector3 = vector + transform.rotation * vector3;
		vector4 = vector + transform.rotation * vector4;
		vector5 = vector + transform.rotation * vector5;
		vector6 = vector + transform.rotation * vector6;
		vector7 = vector + transform.rotation * vector7;
		vector8 = vector + transform.rotation * vector8;
		vector9 = vector + transform.rotation * vector9;
		vector10 = vector + transform.rotation * vector10;
		UnityEngine.Debug.DrawLine(vector3, vector4, colorBounds);
		UnityEngine.Debug.DrawLine(vector4, vector6, colorBounds);
		UnityEngine.Debug.DrawLine(vector6, vector5, colorBounds);
		UnityEngine.Debug.DrawLine(vector5, vector3, colorBounds);
		UnityEngine.Debug.DrawLine(vector7, vector8, colorBounds);
		UnityEngine.Debug.DrawLine(vector8, vector10, colorBounds);
		UnityEngine.Debug.DrawLine(vector10, vector9, colorBounds);
		UnityEngine.Debug.DrawLine(vector9, vector7, colorBounds);
		UnityEngine.Debug.DrawLine(vector3, vector7, colorBounds);
		UnityEngine.Debug.DrawLine(vector4, vector8, colorBounds);
		UnityEngine.Debug.DrawLine(vector6, vector10, colorBounds);
		UnityEngine.Debug.DrawLine(vector5, vector9, colorBounds);
		UnityEngine.Debug.DrawLine(transform.TransformPoint(bounds.center - Vector3.up), transform.TransformPoint(bounds.center + Vector3.up), colorCenter);
		UnityEngine.Debug.DrawLine(transform.TransformPoint(bounds.center - Vector3.forward), transform.TransformPoint(bounds.center + Vector3.forward), colorCenter);
		UnityEngine.Debug.DrawLine(transform.TransformPoint(bounds.center - Vector3.right), transform.TransformPoint(bounds.center + Vector3.right), colorCenter);
	}

