	private void initSparkles()
	{
		Item[] array = allItems;
		foreach (Item item in array)
		{
			bool flag = item.itemType != ItemType.Undefined || item.sparkCalculation == ItemSparkCalculation.On;
			if (item.sparkCalculation == ItemSparkCalculation.Off)
			{
				flag = false;
			}
			if (flag && (!(computeLocalBounds(item.gameObject).size.magnitude > 0.2f) || item.sparkCalculation != ItemSparkCalculation.Automatic))
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(sparkleTemplate, item.transform);
				ParticleSystem component = gameObject.GetComponent<ParticleSystem>();
				gameObject.transform.localScale = Vector3.one;
				gameObject.transform.localPosition = Vector3.zero;
				gameObject.transform.localRotation = Quaternion.identity;
				ParticleSystem.ShapeModule shape = component.shape;
				shape.shapeType = ParticleSystemShapeType.Box;
				Bounds bounds = computeLocalBounds(item.gameObject);
				shape.scale = bounds.size;
				shape.position = bounds.center;
				item.sparkleActive = true;
				item.sparkle = gameObject;
			}
		}
	}

	public static Bounds computeLocalBounds(GameObject gameObject, bool overrideAcceptEditorSpecial = false, bool useZoomFocusZone = false)
	{
		Bounds result = default(Bounds);
		Transform parent = gameObject.transform.parent;
		Vector3 position = gameObject.transform.position;
		Quaternion rotation = gameObject.transform.rotation;
		Vector3 localScale = gameObject.transform.localScale;
		bool activeSelf = gameObject.activeSelf;
		bool flag = true;
		gameObject.transform.SetParent(null, worldPositionStays: false);
		gameObject.transform.position = Vector3.zero;
		gameObject.transform.rotation = Quaternion.identity;
		gameObject.transform.localScale = Vector3.one;
		gameObject.SetActive(value: true);
		Item component = gameObject.GetComponent<Item>();
		bool isSlotChild = component != null && component.slot != null;
		Renderer[] componentsInChildren = gameObject.GetComponentsInChildren<Renderer>(includeInactive: true);
		foreach (Renderer renderer in componentsInChildren)
		{
			if (rendererAcceptableForBoundsCalculations(renderer))
			{
				if (flag)
				{
					result = renderer.bounds;
					flag = false;
				}
				else
				{
					result.Encapsulate(renderer.bounds);
				}
			}
		}
		Vector3 center = result.center - gameObject.transform.position;
		result.center = center;
		gameObject.transform.SetParent(parent, worldPositionStays: false);
		gameObject.transform.position = position;
		gameObject.transform.rotation = rotation;
		gameObject.transform.localScale = localScale;
		gameObject.SetActive(activeSelf);
		return result;
		bool rendererAcceptableForBoundsCalculations(Renderer rendererCandidate)
		{
			int num = LayerMask.NameToLayer("RoomEditorSpecialObject");
			bool flag2 = rendererCandidate.gameObject.layer == num;
			ParticleSystem component2 = rendererCandidate.GetComponent<ParticleSystem>();
			LineRenderer component3 = rendererCandidate.GetComponent<LineRenderer>();
			SkinnedMeshRenderer component4 = rendererCandidate.GetComponent<SkinnedMeshRenderer>();
			MeshRenderer component5 = rendererCandidate.GetComponent<MeshRenderer>();
			Dial component6 = rendererCandidate.GetComponent<Dial>();
			Turnable component7 = rendererCandidate.GetComponent<Turnable>();
			MeshFilter meshFilter = ((component5 != null) ? component5.GetComponent<MeshFilter>() : null);
			Item component8 = rendererCandidate.GetComponent<Item>();
			bool flag3 = component8 != null && component8.slot != null;
			ZoomFocusZone component9 = rendererCandidate.GetComponent<ZoomFocusZone>();
			if (useZoomFocusZone && component9 == null)
			{
				return false;
			}
			if (flag2 && !overrideAcceptEditorSpecial)
			{
				return false;
			}
			if (component6 != null || component7 != null || (flag3 && !isSlotChild))
			{
				return false;
			}
			if (component4 != null || component3 != null || component2 != null)
			{
				return false;
			}
			if (component5 != null && component5.gameObject.activeInHierarchy && !component5.gameObject.CompareTag("IgnoreBounds") && meshFilter != null && (component5.enabled || component5.CompareTag("InvisibleBounds")))
			{
				return true;
			}
			return false;
		}
	}

