		playerCollider.height = playerHeightVector.y + num6;
		playerCollider.center = -Vector3.up * ((playerHeightVector.y + num6) / 2f);
		controlMode.update();
		if (gameState.current == GameState.CustomMode && localPlayerData != null && localPlayerData.customMode != null && localPlayerData.customMode.overrideCamera)
