			contestedFov.set(ContestedFov.CustomMode, Mathf.Lerp(playerCamera.fieldOfView, localPlayerData.customMode.cameraFOV, t), oneFrame: true);
			if ((int)localPlayerData.customMode.customCameraCullingMask != 0)
