			}
			else if (cutScene2.cutsceneStartTimestamp == 0f)
			{
				cutScene2.cutsceneStartTimestamp = Time.time;
			}
		}
		if (!disableLevelLogic)
		{
			if (foundCutScene != null)
			{
				if (topZoomContextSafe(out var _))
				{
					handleZoomLeave();
				}
				float num11 = Time.time - foundCutScene.cutsceneStartTimestamp;
				if (foundCutScene.useIntroTween && foundCutScene.introTweenDutation > 0f && num11 < foundCutScene.introTweenDutation)
				{
					float t2 = num11 / foundCutScene.introTweenDutation;
					float t3 = Mathf.SmoothStep(0f, 1f, t2);
					Vector3 newValue = Vector3.Lerp(contestedCameraPosition.value(), foundCutScene.eyePosition, t3);
					Quaternion newValue2 = Quaternion.Slerp(contestedCameraRotation.value(), foundCutScene.eyeRotation, t3);
					contestedCameraPosition.set(ContestedPose.Cutscene, newValue, oneFrame: true);
					contestedCameraRotation.set(ContestedPose.Cutscene, newValue2, oneFrame: true);
