				else
				{
					contestedCameraPosition.set(ContestedPose.Cutscene, foundCutScene.eyePosition, oneFrame: true);
					contestedCameraRotation.set(ContestedPose.Cutscene, foundCutScene.eyeRotation, oneFrame: true);
