				if (foundCutScene.useExitTween)
				{
					cutsceneEndTweenDuration = foundCutScene.exitTweenDutation;
					cutsceneEndTweenStart = new Pose(contestedCameraPosition.value(), contestedCameraRotation.value());
					cutsceneEndTweenTimestamp = Time.time;
				}
				if (foundCutScene.playerRotationFollowingCutscene && num11 > foundCutScene.introTweenDutation)
				{
					Vector3 eulerAngles = foundCutScene.eyeRotation.eulerAngles;
					targetRotation.x = eulerAngles.y;
					targetRotation.y = eulerAngles.x;
					currentRotation = targetRotation;
					headPov.rotation = foundCutScene.eyeRotation;
					contestedCameraRotation.set(ContestedPose.Game, foundCutScene.eyeRotation, oneFrame: true);
				}
				cursorVisible.changeState(CursorVisibleState.Hidden);
				pcCrosshair.gameObject.SetActive(value: false);
				if ((int)foundCutScene.customCameraCullingMask != 0)
				{
					playerCamera.cullingMask = foundCutScene.customCameraCullingMask;
				}
			}
			else if (isInExitTweenFromCutscene())
			{
				float t4 = (Time.time - cutsceneEndTweenTimestamp) / cutsceneEndTweenDuration;
				t4 = Mathf.SmoothStep(0f, 1f, t4);
				Vector3 newValue3 = Vector3.Lerp(cutsceneEndTweenStart.position, headPov.position, t4);
				Quaternion newValue4 = Quaternion.Slerp(cutsceneEndTweenStart.rotation, headPov.rotation, t4);
				contestedCameraPosition.set(ContestedPose.Cutscene, newValue3, oneFrame: true);
				contestedCameraRotation.set(ContestedPose.Cutscene, newValue4, oneFrame: true);
				if (t4 >= 1f)
				{
					cutsceneEndTweenTimestamp = -1f;
				}
			}
		}
		updateLevelPredicates();
