		if (timerCurrentTime > 0f && !isLevelCompleted)
		{
			timerCurrentTime = Mathf.MoveTowards(timerCurrentTime, 0f, Time.deltaTime);
			int num12 = Mathf.FloorToInt(timerCurrentTime / 60f);
			int num13 = Mathf.FloorToInt(timerCurrentTime % 60f);
			timerText.text = $"{num12:00}:{num13:00}";
		}
		UnityUtils.setCrashHandlerGame(this);
		optionDialog.update(gameInputDispatcher);
		updateAchievements();
		float modifiedExamineBlur()
		{
			if (!PlayerSave.getSettings().disableExamineModeEffects)
			{
				return Mathf.Max(this.examineBlur, finishLevelBlur);
			}
			return 0f;
		}
		float modifiedExamineBlurDirection()
		{
			if (!PlayerSave.getSettings().disableExamineModeEffects)
			{
				return examineBlurDirection;
			}
			return 0f;
		}
	}

	private bool isInExitTweenFromCutscene()
	{
		if (cutsceneEndTweenTimestamp != -1f)
		{
			return Time.time - cutsceneEndTweenTimestamp < cutsceneEndTweenDuration;
		}
		return false;
	}

	private void updateItemStates()
	{
		Item[] array = allItems;
		foreach (Item item in array)
		{
			if (item == null)
			{
				continue;
			}
			ItemState itemState = getItemState(item);
			bool flag = ((itemState == ItemState.World) ? item.hasRigidbody : (itemState == ItemState.SlotAnimation));
			if (flag && item.rigidbody == null)
			{
				item.rigidbody = item.gameObject.AddComponent<Rigidbody>();
				item.rigidbody.mass = item.mass;
				item.rigidbody.linearDamping = item.drag;
				item.rigidbody.angularDamping = item.angularDrag;
				item.rigidbody.collisionDetectionMode = item.collisionDetection;
				item.rigidbody.interpolation = RigidbodyInterpolation.Interpolate;
				if (itemState == ItemState.SlotAnimation)
				{
					item.rigidbody.detectCollisions = false;
				}
			}
			else if (!flag && item.rigidbody != null)
			{
				UnityEngine.Object.Destroy(item.rigidbody);
				item.rigidbody = null;
			}
			if (item.rbOverrides != null && item.rigidbody != null)
			{
				item.rigidbody.linearVelocity = item.rbOverrides.velocity;
				item.rigidbody.angularVelocity = item.rbOverrides.angularVelocity;
				item.rigidbody.AddTorque(item.rbOverrides.addTorque, item.rbOverrides.addForceMode);
				item.rigidbody.AddForce(item.rbOverrides.addForce, item.rbOverrides.addForceMode);
				item.rbOverrides = null;
			}
			updateTransformSyncIfNeeded(item.rigidbody, ref item.transformSync, itemState);
			if (item.sparkle != null)
			{
				bool flag2 = itemState == ItemState.World && item.hasRigidbody;
				if (flag2 != item.sparkleActive)
				{
					item.sparkleActive = flag2;
					if (flag2)
					{
						item.timeSparklesActivated = Time.time;
					}
					else
					{
						item.sparkle.SetActive(value: false);
					}
				}
				if (item.sparkleActive && Time.time - item.timeSparklesActivated > 2f)
				{
					item.sparkle.SetActive(value: true);
				}
			}
			setProbeAnchorOnItem((itemState == ItemState.Inventory || itemState == ItemState.Hand || itemState == ItemState.Zoom) ? itemProbeAnchorOverride : null);
			switch (itemState)
			{
			case ItemState.Hand:
			case ItemState.Zoom:
			case ItemState.ToolZoom:
				setLayerOnItem(LayerMask.NameToLayer("Zoom"), LayerMask.NameToLayer("ZoomTransparent"));
				break;
			case ItemState.Slot:
				if (item.slot != null)
				{
					int num = item.slot.gameObject.layer;
					if (num == LayerMask.NameToLayer("RoomEditorSpecialObject"))
					{
						num = LayerMask.NameToLayer("Default");
					}
					setLayerOnItem(num, num);
				}
				break;
			default:
				setLayerOnItem(item.defaultLayer, item.defaultLayer);
				break;
			}
			void setLayerOnItem(int layer, int transparentLayer)
			{
				if (item.gameObject.layer != layer && item.gameObject.layer != transparentLayer)
				{
					setLayerOnChildren(item.gameObject, layer, transparentLayer);
				}
			}
			void setProbeAnchorOnItem(Transform probeAnchor)
			{
				if (!(item.renderer == null) && !(item.renderer.probeAnchor == probeAnchor))
				{
					Renderer[] componentsInChildren = item.gameObject.GetComponentsInChildren<Renderer>(includeInactive: true);
					for (int j = 0; j < componentsInChildren.Length; j++)
					{
						componentsInChildren[j].probeAnchor = probeAnchor;
					}
				}
			}
		}
		Draggable[] array2 = allDraggables;
		foreach (Draggable draggable in array2)
		{
			if (draggable.draggableRigidbody != null)
			{
				draggable.draggableRigidbody.isKinematic = draggable.isKinematic;
			}
			updateTransformSyncIfNeeded(draggable.draggableRigidbody, ref draggable.transformSync);
		}
		TransformSync addTransformSync(GameObject go)
		{
			TransformSync transformSync = go.GetComponent<TransformSync>();
			if (transformSync == null)
			{
				transformSync = go.AddComponent<TransformSync>();
			}
			if (transformSync.GetComponent<CharacterJoint>() != null)
			{
				transformSync.sendPositionThreshold = 0f;
				transformSync.sendRotationThreshold = 0f;
			}
			transformSync.init(this);
			return transformSync;
		}
		void updateTransformSyncIfNeeded(Rigidbody rb, ref TransformSync transformSync, ItemState itemState2 = ItemState.World)
		{
			bool flag3 = transformSync != null;
			if (getPlayerCount() == 1 || itemState2 == ItemState.SlotAnimation)
			{
				if (flag3)
				{
					UnityEngine.Object.Destroy(transformSync);
					transformSync = null;
				}
			}
			else
			{
				bool flag4 = rb != null;
				if (flag4 && !flag3)
				{
					transformSync = addTransformSync(rb.gameObject);
				}
				else if (!flag4 && flag3)
				{
					UnityEngine.Object.Destroy(transformSync);
					transformSync = null;
				}
			}
		}
	}

	private void updateSwitch3DStates()
	{
		Switch3D[] array = allSwitch3Des;
		foreach (Switch3D switch3D in array)
		{
			bool hasRigidbody = switch3D.hasRigidbody;
			if (hasRigidbody && switch3D.rigidbody == null)
			{
				switch3D.rigidbody = switch3D.gameObject.AddComponent<Rigidbody>();
				switch3D.rigidbody.isKinematic = true;
				switch3D.rigidbody.collisionDetectionMode = CollisionDetectionMode.ContinuousSpeculative;
				switch3D.rigidbody.interpolation = RigidbodyInterpolation.Interpolate;
			}
			else if (!hasRigidbody && switch3D.rigidbody != null)
			{
				UnityEngine.Object.Destroy(switch3D.rigidbody);
				switch3D.rigidbody = null;
			}
		}
	}

	private void setLayerOnChildren(GameObject go, int layer, int transparentLayer)
	{
		Transform[] componentsInChildren = go.GetComponentsInChildren<Transform>(includeInactive: true);
		foreach (Transform transform in componentsInChildren)
		{
			if (transform.gameObject.layer != LayerMask.NameToLayer("RoomEditorSpecialObject"))
			{
				transform.gameObject.layer = (transform.gameObject.CompareTag("ExamineTransparentEffect") ? transparentLayer : layer);
			}
		}
	}

	private void updateLightModifiers()
	{
		if (lightModifiers != null)
		{
			CharacterLightModifier[] array = lightModifiers;
			foreach (CharacterLightModifier characterLightModifier in array)
			{
				characterLightModifier.targetLightHD.lightDimmer = characterLightModifier.originalLightHD.lightDimmer * characterLightModifier.lightMultiplier;
			}
		}
	}

	private float calculateLightIntensityAtPoint(Vector3 point, Light[] lights, uint lightLayers = uint.MaxValue)
	{
		float num = 0f;
		for (int i = 0; i < lights.Length; i++)
		{
			Light light = lights[i];
			HDAdditionalLightData component = lights[i].GetComponent<HDAdditionalLightData>();
			if (light == null || !light.enabled || light.intensity <= 0f || !light.gameObject.activeInHierarchy || light.bakingOutput.lightmapBakeType == LightmapBakeType.Baked || ((uint)component.lightlayersMask & lightLayers) == 0)
			{
				continue;
			}
			Vector3 vector = point - light.transform.position;
			float sqrMagnitude = vector.sqrMagnitude;
			float num2 = 0f;
			switch (light.type)
			{
			case LightType.Directional:
				num2 = 1f;
				break;
			case LightType.Point:
				if (sqrMagnitude > 0f && sqrMagnitude < light.range * light.range)
				{
					num2 = 1f / sqrMagnitude;
				}
				break;
			case LightType.Spot:
				if (sqrMagnitude > 0f && sqrMagnitude < light.range * light.range)
				{
					Vector3 normalized2 = vector.normalized;
					float num4 = Vector3.Angle(-light.transform.forward, normalized2);
					if (num4 <= light.spotAngle * 0.5f)
					{
						float num5 = Mathf.Clamp01(1f - num4 / (light.spotAngle * 0.5f));
						num2 = num5 * num5 / sqrMagnitude;
					}
				}
				break;
			case LightType.Area:
				if (sqrMagnitude > 0f && sqrMagnitude < light.range * light.range)
				{
					Vector3 forward = light.transform.forward;
					Vector3 normalized = vector.normalized;
					float num3 = Mathf.Max(0f, Vector3.Dot(forward, normalized));
					num2 = light.areaSize.x * light.areaSize.y * num3 / sqrMagnitude;
				}
				break;
			}
			num += num2 * light.intensity * component.lightDimmer;
		}
		return num;
	}

	private float modifyLightIntensityAtPoint(float maxTotalLux, Vector3 point, float lerp = 1f, uint lightLayers = uint.MaxValue)
	{
		float num = 0f;
		float[] array = new float[levelLights.Count];
		for (int i = 0; i < levelLights.Count; i++)
		{
			Light light = levelLights[i].light;
			HDAdditionalLightData lightData = levelLights[i].lightData;
			if (light == null || !light.enabled || light.intensity <= 0f || !light.gameObject.activeInHierarchy || light.bakingOutput.lightmapBakeType == LightmapBakeType.Baked || ((uint)lightData.lightlayersMask & lightLayers) == 0)
			{
				continue;
			}
			Vector3 vector = point - light.transform.position;
			float sqrMagnitude = vector.sqrMagnitude;
			float num2 = 0f;
			switch (light.type)
			{
			case LightType.Directional:
				num2 = 1f;
				break;
			case LightType.Point:
				if (sqrMagnitude < light.range * light.range)
				{
					num2 = 1f / Mathf.Max(0.0001f, sqrMagnitude);
				}
				break;
			case LightType.Spot:
				if (sqrMagnitude > 0f && sqrMagnitude < light.range * light.range && lightData.spotLightShape == SpotLightShape.Cone)
				{
					Vector3 normalized2 = vector.normalized;
					if (Vector3.Angle(light.transform.forward, normalized2) <= light.spotAngle * 0.5f)
					{
						num2 = 1f / Mathf.Max(0.0001f, sqrMagnitude);
					}
				}
				break;
			case LightType.Area:
				if (sqrMagnitude > 0f && sqrMagnitude < light.range * light.range)
				{
					Vector3 forward = light.transform.forward;
					Vector3 normalized = vector.normalized;
					float num3 = Mathf.Max(0f, Vector3.Dot(forward, normalized));
					num2 = light.areaSize.x * light.areaSize.y * num3 / sqrMagnitude;
				}
				break;
			}
			array[i] = num2;
			num += array[i] * levelLights[i].getInitialIntensity;
		}
		if (num > 0f)
		{
			maxTotalLux = Mathf.Min(maxTotalLux, num);
			for (int j = 0; j < levelLights.Count; j++)
			{
				if (array[j] > 0f)
				{
					float num4 = array[j] * levelLights[j].getInitialIntensity / num * maxTotalLux;
					levelLights[j].light.intensity = Mathf.Lerp(levelLights[j].getInitialIntensity, num4 / array[j], lerp);
				}
				if (levelLights[j].light.type != LightType.Directional && levelLights[j].light.type != LightType.Point && levelLights[j].light.type != LightType.Spot && levelLights[j].light.type != LightType.Area)
				{
					levelLights[j].light.intensity = 0f;
				}
			}
		}
		return num;
	}

	private void LateUpdate()
	{
		updateDistanceBasedOcclusion();
		lateUpdateNet();
		foreach (Action lateUpdateCallback in lateUpdateCallbacks)
		{
			lateUpdateCallback();
		}
		if (freeCamOn)
		{
			debugCharacterPresetRotation = currentRotation;
			contestedFov.set(ContestedFov.FreeCam, PlayerSave.getDebug().freeCamFOV, oneFrame: true);
			if (!PlayerSave.getDebug().freeCamUseEasing)
			{
				Vector3 newValue = (freeCamPrevPosition = Vector3.MoveTowards(playerCamera.transform.position, freeCamPosition, 2f));
				Vector2 vector = (freeCamPrevRotation = Vector2.MoveTowards(freeCamPrevRotation, freeCamRotation, 2f));
				contestedCameraPosition.set(ContestedPose.FreeCam, newValue, oneFrame: true);
				contestedCameraRotation.set(ContestedPose.FreeCam, Quaternion.Euler(vector.y, vector.x, 0f), oneFrame: true);
			}
			else
			{
				Vector3 newValue2 = Vector3.SmoothDamp(freeCamPrevPosition, freeCamPosition, ref freeCamCurrentPositionVelocity, PlayerSave.getDebug().freeCamEasingSpeed / 5f);
				Vector2 vector2 = Vector2.SmoothDamp(freeCamPrevRotation, freeCamRotation, ref freeCamCurrentRotationVelocity, PlayerSave.getDebug().freeCamEasingSpeed / 5f);
				Quaternion newValue3 = Quaternion.Euler(vector2.y, vector2.x, 0f);
				freeCamPrevRotation = vector2;
				freeCamPrevPosition = newValue2;
				contestedCameraPosition.set(ContestedPose.FreeCam, newValue2, oneFrame: true);
				contestedCameraRotation.set(ContestedPose.FreeCam, newValue3, oneFrame: true);
			}
		}
		int num = tokenAnimations.Count - 1;
		while (num >= 0)
		{
			TokenAnimation tokenAnim = tokenAnimations[num];
			float speed = 0.8f;
			int num2 = 800;
			float num3 = 0.08f;
			float num4 = 0.06f;
			Vector3 vector3 = new Vector3(0f, 0f, 0.3f);
			float radius = 0.08f;
			Vector2 vector4 = RectTransformUtility.WorldToScreenPoint(null, tokenCountPanelImage.transform.position);
			Vector2 vector5 = new Vector2(vector4.x / (float)Screen.width, vector4.y / (float)Screen.height);
			Vector3 position = new Vector3(vector5.x, vector5.y, 0.3f);
			Vector3 loopCenter = playerCamera.transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(tokenAnim.startPoint + vector3));
			Vector3 endPoint = playerCamera.transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(position));
			tokenAnim.timer += Time.deltaTime * speed;
			tokenAnim.directionTimer += Time.deltaTime;
			if (!tokenAnim.endLoop && tokenAnim.directionTimer >= 0.2f)
			{
				tokenAnim.currentDriftGoal = UnityEngine.Random.insideUnitSphere * num3;
				tokenAnim.directionTimer = 0f;
			}
			if (tokenAnim.endLoop)
			{
				tokenAnim.currentDriftGoal = Vector3.zero;
			}
			tokenAnim.currentDrift = Vector3.MoveTowards(tokenAnim.currentDrift, tokenAnim.currentDriftGoal, Time.deltaTime * num4);
			if (!tokenAnim.endLoop)
			{
				loopMotion();
			}
			else
			{
				moveToEnd();
			}
			if (tokenAnim.timer > 4f)
			{
				tokenAnim.token.gameObject.SetActive(value: false);
				tokenAnimations.Remove(tokenAnim);
			}
			tokenAnim.token.transform.Rotate(Vector3.one, (float)num2 * Time.deltaTime);
			tokenAnim.token.transform.position = playerCamera.transform.position + playerCamera.transform.rotation * tokenAnim.positionGoal + tokenAnim.currentDrift;
			num--;
			void loopMotion()
			{
				float num5 = 4.363323f;
				float f = tokenAnim.timer * num5;
				Vector3 vector6 = new Vector3(Mathf.Cos(f) * radius, Mathf.Sin(f) * radius, 0f);
				tokenAnim.positionGoalLoop = loopCenter + vector6;
				tokenAnim.positionGoal = Vector3.MoveTowards(tokenAnim.positionGoal, tokenAnim.positionGoalLoop, Time.deltaTime * 3f);
				if (tokenAnim.timer >= 1f)
				{
					tokenAnim.endLoop = true;
					tokenCountCurrent.text = syncedFoundTokens.Count.ToString();
				}
				tokenAnim.token.transform.localScale = Vector3.MoveTowards(tokenAnim.token.transform.localScale, Vector3.one * 0.2f, Time.deltaTime);
			}
			void moveToEnd()
			{
				tokenAnim.positionGoal = Vector3.MoveTowards(tokenAnim.positionGoal, endPoint, speed * Time.deltaTime * 1.5f);
				tokenAnim.token.transform.localScale = Vector3.MoveTowards(tokenAnim.token.transform.localScale, Vector3.zero, Time.deltaTime);
			}
		}
		tokenCountPanel.gameObject.SetActive(tokens.Length != 0 && (tokenAnimations.Count > 0 || mainMenu.gameObject.activeSelf));
		if (controlMode.current != ControlMode.VR)
		{
			playerCamera.fieldOfView = contestedFov.value();
			playerCamera.transform.position = contestedCameraPosition.value() + screenShakeOffset;
			playerCamera.transform.rotation = contestedCameraRotation.value();
		}
		characterLightRig.transform.localPosition = playerCamera.transform.localPosition;
		characterLightRig.transform.localRotation = Quaternion.Euler(0f, playerCamera.transform.localRotation.eulerAngles.y, 0f);
		characterLight.lightDimmer = characterLightStrength;
		pointerCleanup();
		levelLogic.onLateUpdate();
		layoutRebuilder.lateUpdate();
	}

	private void OnDestroy()
	{
		UnityEngine.Debug.Log("Game OnDestroy start");
		Shader.SetGlobalFloat("pineSpotlightCount", 0f);
		onDestroyNet();
		destroyLua();
		destroySaveSystem();
		destroyFinishScreen();
		stopAllEditorSounds();
		gameplayTweenSP.destroyAllTweens(performEvents: false, performFinalUpdate: false);
		gameplayTweenMP.destroyAllTweens(performEvents: false, performFinalUpdate: false);
		menuTween.destroyAllTweens(performEvents: false, performFinalUpdate: false);
		gameplayTweenSP = null;
		gameplayTweenMP = null;
		menuTween = null;
		if (isCustomLevelFromMenu())
		{
			UnityEngine.Debug.Log(string.Format("[{0}::{1}] Releasing {2} custom room sounds...", "Game", "OnDestroy", RoomEditor.soundsCache.Count));
			foreach (FMOD.Sound item in RoomEditor.soundsCache)
			{
				item.release();
			}
			RoomEditor.soundsCache.Clear();
		}
		gcDontKill.Clear();
		Draggable[] array = allDraggables;
		for (int i = 0; i < array.Length; i++)
		{
			PineFmod.stop(array[i].soundEmitter);
		}
		UnityEngine.Debug.Log("Game OnDestroy end");
	}

	private void OnApplicationQuit()
	{
		UnityEngine.Debug.Log("Game OnApplicationQuit 1");
		PineFmod.destroy();
		UnityEngine.Debug.Log("Game OnApplicationQuit 2");
		vr.destroy();
		UnityEngine.Debug.Log("Game OnApplicationQuit 3");
		if (!isSplitscreen)
		{
			session.send(new KickPlayerPacket
			{
				playerBeingKicked = session.localPlayerId
			});
			UnityEngine.Debug.Log("Game OnApplicationQuit 4");
			session.destroy();
			UnityEngine.Debug.Log("Game OnApplicationQuit 5");
		}
		Controller.destroy();
		UnityEngine.Debug.Log("Game OnApplicationQuit 6");
		destroySaveSystem();
		SharedWriter.dispose();
		UnityEngine.Debug.Log("Game OnApplicationQuit 7");
	}

	private Rect viewportRectForRectTransform(RectTransform rt)
	{
		Vector3[] array = new Vector3[4];
		rt.GetWorldCorners(array);
		Vector3 vector = playerCamera.WorldToViewportPoint(array[0]);
		Vector3 lhs = vector;
		Vector3 lhs2 = vector;
		for (int i = 1; i < 4; i++)
		{
			vector = playerCamera.WorldToViewportPoint(array[i]);
			lhs = Vector3.Min(lhs, vector);
			lhs2 = Vector3.Max(lhs2, vector);
		}
		return new Rect(lhs.x, lhs.y, lhs2.x - lhs.x, lhs2.y - lhs.y);
	}

	private void setPlayerLocation(Vector3 newLocation)
	{
		playerLocation = newLocation;
	}

	public void teleportPlayer(Vector3 location)
	{
		UnityEngine.Debug.Log($"Teleporting player to location: {location}");
		Vector3 vector = ((!isSplitscreen || session.localPlayerId == Net.SPLITSCREEN_HOST_ID) ? Vector3.zero : (Vector3.back * 300f));
		location += vector;
		if (isVR() && isCustomLevel() && NavMesh.SamplePosition(location, out var hit, 1000f, -1))
		{
			float num = Vector3.Distance(location, hit.position);
			if (num > 0.01f)
			{
				VR.debugLog($"Adjusting teleport position from {location} to {hit.position} (distance change: {num}).");
			}
			location = hit.position;
		}
		setPlayerLocation(location);
		if (heightSlider.value == 0)
		{
			heightSlider.moveTo(2);
		}
		if (zoomContexts.Count == 0)
		{
			contestedCameraPosition.set(ContestedPose.Game, headPov.position);
		}
		handleMovementChange(Vector3.zero, teleport: true);
		performVRMoveTo(location);
		if (isVR() && NavMesh.SamplePosition(playerLocation, out var hit2, (!isCustomLevel()) ? 1 : 1000, -1))
		{
			VR.debugLog($"Adjusted last valid VR nav-mesh position from {vrLastValidNavMeshPosition} to {hit2.position}.");
			vrLastValidNavMeshPosition = hit2.position;
		}
		updateVRMenuCanvasSoThatItFacesPlayer();
		if (Is.LowDevice)
		{
			iterateAllOccludeesNextFrame = true;
		}
	}

	public void teleportPlayer(Vector3 location, Vector3 eulerAngles)
	{
		vr.setRigDirection(Quaternion.AngleAxis(eulerAngles.y, Vector3.up) * Vector3.forward);
		teleportPlayer(location);
		targetRotation = new Vector2(eulerAngles.y, eulerAngles.x);
		currentRotation = targetRotation;
		headPov.localRotation = Quaternion.Euler(currentRotation);
	}

	private void initCanvasHandlers()
	{
		Canvas[] componentsInChildren = levelContainer.GetComponentsInChildren<Canvas>();
		foreach (Canvas canvas in componentsInChildren)
