	public void saveAchievement(string achievement)
	{
		if (achievementsEnabled)
		{
			bool pbAchieved = false;
			SteamUserStats.GetAchievement(achievement, out pbAchieved);
			if (!pbAchieved)
			{
				SteamUserStats.SetAchievement(achievement);
				SteamUserStats.StoreStats();
			}
			if (Is.Oculus)
			{
				saveOculusAchievement(achievement);
			}
			else if (!pbAchieved)
			{
				UnityEngine.Debug.Log(achievement + " unlocked");
			}
		}
	}

	private void saveOculusAchievement(string achievement)
	{
		if (!Core.IsInitialized())
		{
			UnityEngine.Debug.LogError("[saveOculusAchievement] Oculus Platform SDK is not initialized");
			return;
		}
		Achievements.GetProgressByName(new string[1] { achievement }).OnComplete(delegate(Message<AchievementProgressList> message)
		{
			if (message.IsError)
			{
				UnityEngine.Debug.LogError("[saveOculusAchievement] Failed to get achievement '" + achievement + "' progress: " + message.GetError().Message);
			}
			else
			{
				foreach (AchievementProgress datum in message.Data)
				{
					if (!(datum.Name != achievement) && datum.IsUnlocked)
					{
						return;
					}
				}
				Achievements.Unlock(achievement).OnComplete(delegate(Message<AchievementUpdate> msg)
				{
					if (msg.IsError)
					{
						UnityEngine.Debug.LogError("[saveOculusAchievement] Failed to unlock achievement '" + achievement + "': " + msg.GetError().Message);
					}
					else
					{
						UnityEngine.Debug.Log("[saveOculusAchievement] Oculus achievement '" + achievement + "' has been unlocked!");
					}
				});
			}
		});
	}

	public void initAchievements()
	{
		DroppedTimers = new List<float>();
		dropInTimeCount = new List<int>();
		pingTimers = new List<float>();
		pingInTimeCount = new List<int>();
	}

	public void updateAchievements()
	{
		float num = 5f;
		for (int i = 0; i < DroppedTimers.Count; i++)
		{
			DroppedTimers[i] += Time.deltaTime;
			if (DroppedTimers[i] >= num)
			{
				DroppedTimers.RemoveAt(i);
				dropInTimeCount.RemoveAt(i);
			}
		}
		float num2 = 1f;
		for (int j = 0; j < pingTimers.Count; j++)
		{
			pingTimers[j] += Time.deltaTime;
			if (pingTimers[j] >= num2)
			{
				pingTimers.RemoveAt(j);
				pingInTimeCount.RemoveAt(j);
			}
		}
		int num3 = 0;
		for (int k = 0; k < trashInventory.Count; k++)
		{
			num3 += trashInventory[k].gameObjects.Count;
		}
		if (num3 >= 3)
		{
			saveAchievement("ACHIEVEMENT_CLEANER");
		}
	}

	public void achievementCheckPing()
	{
		for (int i = 0; i < pingInTimeCount.Count; i++)
		{
			pingInTimeCount[i]++;
			int num = 3;
			if (pingInTimeCount[i] >= num)
			{
				saveAchievement("ACHIEVEMENT_LOOK_LOOK_LOOK");
			}
		}
		pingTimers.Add(0f);
		pingInTimeCount.Add(1);
	}

	private void updateChat()
	{
		if (isChatOpen)
		{
			return;
		}
		for (int num = shownChatMessages.Count - 1; num >= 0; num--)
		{
			ChatMessage chatMessage = shownChatMessages[num];
			chatMessage.timeLeft -= Time.deltaTime;
			if (!(chatMessage.timeLeft > 0f))
			{
				chatMessage.alpha = Mathf.Clamp01(chatMessage.alpha - Time.deltaTime * 2f);
				chatMessage.canvasGroup.alpha = Mathf.SmoothStep(0f, 1f, chatMessage.alpha);
				if (!(chatMessage.alpha > 0f))
				{
					chatMessage.gameObject.SetActive(value: false);
					shownChatMessages.RemoveAt(num);
				}
			}
		}
	}

	private void openChat()
	{
		CanvasGroup component = chatCanvas.GetComponent<CanvasGroup>();
		component.interactable = true;
		component.blocksRaycasts = true;
		foreach (ChatMessage chatMessage in chatMessages)
		{
			chatMessage.canvasGroup.alpha = 1f;
			chatMessage.gameObject.SetActive(value: true);
		}
		chatInputField.text = previousInputedChatMessage;
		chatInputField.gameObject.SetActive(value: true);
		chatInputField.ActivateInputField();
		isChatOpen = true;
	}

	public void closeChat()
	{
		previousInputedChatMessage = chatInputField.text;
		chatInputField.text = "";
		chatInputField.gameObject.SetActive(value: false);
		CanvasGroup component = chatCanvas.GetComponent<CanvasGroup>();
		component.interactable = false;
		component.blocksRaycasts = false;
		foreach (ChatMessage chatMessage in chatMessages)
		{
			chatMessage.gameObject.SetActive(chatMessage.alpha > 0f);
		}
		wasChatClosedThisFrame = true;
		isChatOpen = false;
	}

	public void onTypeChatMessage(string text)
	{
		if (text != "" && isChatOpen)
		{
			addChatMessageSynced(text, ChatMessage.Type.LocalPlayer);
			chatInputField.text = "";
		}
		closeChat();
	}

