	public void addChatMessageLocal(string messageText, string sender = "", ChatMessage.Type type = ChatMessage.Type.LocalPlayer, string puzzleName = "")
	{
		if ((type == ChatMessage.Type.PuzzleUnlocked || type == ChatMessage.Type.ManyPuzzlesUnlocked) && session.gameDifficulty == GameDifficulty.Hard)
		{
			return;
		}
		if (isCustomLevel() && (type == ChatMessage.Type.LocalPlayer || type == ChatMessage.Type.OtherPlayer || type == ChatMessage.Type.PlayerNote) && messageText.StartsWith("/"))
		{
			levelLogic.onChatCommand(messageText);
			return;
		}
		GameObject gameObject = UnityEngine.Object.Instantiate(chatTextPrefab, chatContent);
		gameObject.SetActive(value: true);
		ChatMessage chatMessage = new ChatMessage
		{
			gameObject = gameObject,
			canvasGroup = gameObject.GetComponent<CanvasGroup>(),
			text = gameObject.GetComponent<Text>(),
			timeLeft = 10f,
			alpha = 1f
		};
		chatMessages.Add(chatMessage);
		shownChatMessages.Add(chatMessage);
		switch (type)
		{
		case ChatMessage.Type.Ping:
			chatMessage.text.color = new Color(0.8862745f, 0.8862745f, 0.8862745f);
			chatMessage.text.text = (sender.Colored(CHAT_COLOR_NAME) + " " + Localization.lookupInDictionary("Pinged")).Colored(CHAT_COLOR_ACTION);
			break;
		case ChatMessage.Type.PingOnObject:
			chatMessage.text.color = new Color(0.8862745f, 0.8862745f, 0.8862745f);
			chatMessage.text.text = (sender.Colored(CHAT_COLOR_NAME) + " " + Localization.lookupInDictionary("PingedOnItem").Replace("[Item]", messageText.Colored(CHAT_COLOR_NAME))).Colored(CHAT_COLOR_ACTION);
			break;
		case ChatMessage.Type.LocalPlayer:
			chatMessage.text.color = new Color(71f / 85f, 71f / 85f, 71f / 85f);
			chatMessage.text.text = (sender + ":").Colored(CHAT_COLOR_NAME) + " " + messageText;
			break;
		case ChatMessage.Type.OtherPlayer:
			chatMessage.text.text = (sender + ":").Colored(CHAT_COLOR_NAME) + " " + messageText;
			break;
		case ChatMessage.Type.PlayerNote:
			chatMessage.text.text = messageText;
			break;
		case ChatMessage.Type.PuzzleFinished:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("puzzleCompleted").Replace("[Puzzle]", puzzleName.Colored(CHAT_COLOR_NAME)).Colored(CHAT_COLOR_ACTION);
			break;
		case ChatMessage.Type.PuzzleFinishedOtherPlayer:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("puzzleCompletedOtherPlayer").Replace("[Name]", sender.Colored(CHAT_COLOR_NAME)).Replace("[Puzzle]", puzzleName.Colored(CHAT_COLOR_NAME))
				.Colored(CHAT_COLOR_ACTION);
			break;
		case ChatMessage.Type.PuzzleFinishedTeamwork:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("puzzleCompletedTeamwork").Replace("[Puzzle]", puzzleName.Colored(CHAT_COLOR_NAME)).Colored(CHAT_COLOR_ACTION);
			break;
		case ChatMessage.Type.PuzzleUnlocked:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("versusModePuzzleUnlockedMessage").Replace("[Puzzle]", puzzleName);
			break;
		case ChatMessage.Type.ManyPuzzlesUnlocked:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("versusModeManyPuzzlesUnlockedMessage").Replace("[Count]", puzzleName);
			break;
		case ChatMessage.Type.OtherPlayerFinishedLevel:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("versusModePlayerFinishedLevelMessage").Replace("[Name]", sender).Replace("[Place]", puzzleName);
			break;
		case ChatMessage.Type.LevelNote:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = messageText;
			break;
		case ChatMessage.Type.CodeDebug:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = sender + " " + messageText;
			break;
		case ChatMessage.Type.CodeDebugError:
			chatMessage.text.color = Color.red;
			chatMessage.text.text = sender + " " + messageText;
			break;
		case ChatMessage.Type.RespawnedItem:
			chatMessage.text.color = new Color(0.8862745f, 0.8862745f, 0.8862745f);
			chatMessage.text.text = Localization.lookupInDictionary("respawnedItemToInventory").Replace("[ITEM]", Localization.translate(messageText).Colored(CHAT_COLOR_NAME));
			break;
		case ChatMessage.Type.PlayerJoined:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("ChatMessage_PlayerJoined").Replace("[Player]", messageText.Colored(CHAT_COLOR_NAME)).Colored(CHAT_COLOR_PLAYER_JOINED);
			break;
		case ChatMessage.Type.PlayerLeft:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("ChatMessage_PlayerLeft").Replace("[Player]", messageText.Colored(CHAT_COLOR_NAME)).Colored(CHAT_COLOR_PLAYER_LEFT);
			break;
		case ChatMessage.Type.PlayerFoundToken:
			chatMessage.text.color = Color.white;
			chatMessage.text.text = Localization.lookupInDictionary("ChatMessage_PlayerFoundToken").Replace("[Player]", messageText.Colored(CHAT_COLOR_NAME)).Colored(CHAT_COLOR_ACTION);
			break;
		}
	}

	private void updateDistanceBasedOcclusion()
	{
		if (occludees.Count == 0)
		{
			return;
		}
		float num = cullingDistance * cullingDistance;
		Stopwatch stopwatch = (Is.Editor ? Stopwatch.StartNew() : null);
		Vector3 position = playerCamera.transform.position;
		Plane[] planes = GeometryUtility.CalculateFrustumPlanes(playerCamera);
		float num2 = Screen.width;
		float num3 = Screen.height;
		float screenAreaInverse = 1f / (num2 * num3);
		int num4 = (Is.Oculus ? 72 : (Is.Switch ? 30 : 60));
		int num5 = occludees.Count / num4 * 4;
		bool flag = false;
		if (iterateAllOccludeesNextFrame)
		{
			UnityEngine.Debug.Log($"Forced all {occludees.Count} occludees to be iterated.");
			nextOccludeeIndex = 0;
			num5 = occludees.Count;
			iterateAllOccludeesNextFrame = false;
		}
		for (int i = 0; i < num5; i++)
		{
			Occludee occludee = occludees[nextOccludeeIndex];
			nextOccludeeIndex = (nextOccludeeIndex + 1) % occludees.Count;
			if (nextOccludeeIndex == 0)
			{
				flag = true;
				_ = cullingCloseCount;
				_ = cullingFarCount;
				_ = cullingCulledCount;
				cullingCloseCount = 0;
				cullingFarCount = 0;
				cullingCulledCount = 0;
			}
			if (!occludee.cachedGameObject.activeInHierarchy)
			{
				continue;
			}
			Bounds bounds = occludee.cachedRenderer.bounds;
			if (!GeometryUtility.TestPlanesAABB(planes, bounds))
			{
				continue;
			}
			bool flag2;
			if ((occludee.cachedTransform.position - position).sqrMagnitude < num)
			{
				flag2 = true;
				cullingCloseCount++;
			}
			else
			{
				flag2 = calculateRendererPercentageOfScreen(bounds, playerCamera, screenAreaInverse) > 0.001f;
				cullingFarCount++;
			}
			if (!flag2)
			{
				cullingCulledCount++;
			}
			if (flag2 != occludee.wasEnabledLastFrame)
			{
				if (flag2)
				{
					removeDisabledRenderer(occludee.cachedRenderer, DisabledRenderer.DisabledFlag.Culling);
				}
				else
				{
					addDisabledRenderer(occludee.cachedRenderer, DisabledRenderer.DisabledFlag.Culling);
				}
				if (occludee.cachedLight != null)
				{
					occludee.cachedLight.enabled = flag2;
				}
				occludee.wasEnabledLastFrame = flag2;
			}
		}
		if (Is.Editor)
		{
			cullingDuration += stopwatch.Elapsed.TotalMilliseconds;
			cullingIterations++;
			if (flag)
			{
				cullingDuration = 0.0;
				cullingIterations = 0;
			}
			for (int j = 0; j < 256; j++)
			{
				float f = MathF.PI * 2f * (float)j / 256f;
				float x = Mathf.Cos(f);
				float z = Mathf.Sin(f);
				UnityEngine.Debug.DrawLine(position, position + new Vector3(x, 0f, z) * cullingDistance, Color.green);
			}
		}
		static float calculateRendererPercentageOfScreen(Bounds bounds2, Camera camera, float num12)
		{
			Vector3 min = bounds2.min;
			Vector3 max = bounds2.max;
			Span<Vector3> span = stackalloc Vector3[8];
			span[0] = new Vector3(min.x, min.y, min.z);
			span[1] = new Vector3(min.x, min.y, max.z);
			span[2] = new Vector3(min.x, max.y, min.z);
			span[3] = new Vector3(min.x, max.y, max.z);
			span[4] = new Vector3(max.x, min.y, min.z);
			span[5] = new Vector3(max.x, min.y, max.z);
			span[6] = new Vector3(max.x, max.y, min.z);
			span[7] = new Vector3(max.x, max.y, max.z);
			Span<Vector3> span2 = stackalloc Vector3[8];
			for (int k = 0; k < 8; k++)
			{
				span2[k] = camera.WorldToScreenPoint(span[k]);
			}
			float num6 = float.PositiveInfinity;
			float num7 = float.NegativeInfinity;
			float num8 = float.PositiveInfinity;
			float num9 = float.NegativeInfinity;
			Span<Vector3> span3 = span2;
			for (int l = 0; l < span3.Length; l++)
			{
				Vector3 vector = span3[l];
				num6 = Mathf.Min(num6, vector.x);
				num7 = Mathf.Max(num7, vector.x);
				num8 = Mathf.Min(num8, vector.y);
				num9 = Mathf.Max(num9, vector.y);
			}
			float num10 = num7 - num6;
			float num11 = num9 - num8;
			return num10 * num11 * num12;
		}
	}

	private void addOccludeeIfNeeded(GameObject levelObject)
	{
		if (!levelObject.TryGetComponent<Renderer>(out var component))
		{
			return;
		}
		PropTags component2 = levelObject.GetComponent<PropTags>();
		Material sharedMaterial = component.sharedMaterial;
		if ((!levelObject.TryGetComponent<Collider>(out var _) || !(sharedMaterial != null) || !sharedMaterial.name.Contains("ColliderMaterial")) && (!(sharedMaterial != null) || !sharedMaterial.name.Contains("LogicMaterial")) && levelObject.layer != LayerMask.NameToLayer("RoomEditorSpecialObject") && levelObject.layer != LayerMask.NameToLayer("Area") && (!(component2 != null) || !component2.tags.Contains(PropTag.Logic)))
		{
			Vector3 size = component.bounds.size;
			if (size.x < 2f && size.y < 2f && size.z < 2f && !levelObject.TryGetComponent<DontOcclude>(out var _))
			{
				Occludee occludee = levelObject.AddComponent<Occludee>();
				occludee.cachedGameObject = levelObject;
				occludee.cachedTransform = levelObject.transform;
				occludee.cachedRenderer = component;
				occludee.cachedLight = levelObject.GetComponent<Light>();
				occludees.Add(occludee);
			}
		}
	}

	public void screenDebug(object reference, string message, float time = 1f)
	{
		if (!Is.dev())
		{
			return;
		}
		debugScreenCanvas.SetActive(value: true);
		int num = 0;
		while (num < debugScreenLines.Count)
		{
			DebugScreenLine debugScreenLine = debugScreenLines[num];
			debugScreenLine.time -= Time.deltaTime;
			if (debugScreenLine.time <= 0f)
			{
				UnityEngine.Object.Destroy(debugScreenLine.ui);
				debugScreenLines.RemoveAt(num);
			}
			else
			{
				num++;
			}
		}
		DebugScreenLine debugScreenLine2 = null;
		foreach (DebugScreenLine debugScreenLine3 in debugScreenLines)
		{
			if (debugScreenLine3.reference == reference)
			{
				debugScreenLine2 = debugScreenLine3;
				break;
			}
		}
		if (debugScreenLine2 == null)
		{
			debugScreenLine2 = new DebugScreenLine
			{
				ui = UnityEngine.Object.Instantiate(debugScreenLineTemplate),
				reference = reference
			};
			debugScreenLine2.ui.SetActive(value: true);
			debugScreenLine2.ui.transform.SetParent(debugScreenCanvas.transform);
		}
		debugScreenLine2.ui.GetComponentInChildren<Text>().text = message;
		debugScreenLine2.time = time;
	}

