		if (!Is.dev())
		{
			return;
		}
		debugScrollView.SetActive(value: true);
		introSubtitlesScrollView.SetActive(value: false);
		introShotsScrollView.SetActive(value: false);
		GameObject gameObject = debugMenuAddNewTitle("Level Logic", debugContent.transform);
		List<DebugButton> allDefinedDebugButtons = getAllDefinedDebugButtons();
		if (allDefinedDebugButtons.Count > 0)
		{
			allDefinedDebugButtons.ForEach(createDebugButton);
		}
		else
		{
			gameObject.SetActive(value: false);
		}
		debugMenuAddNewTitle("Debug", debugContent.transform);
		debugMenuAddNewButton("Get key items", delegate
		{
			int num2 = 0;
			HashSet<GameObject> hashSet = new HashSet<GameObject>();
			foreach (Puzzle puzzle in puzzles)
			{
				foreach (Hint hint in puzzle.hints)
				{
					hashSet.Add(hint.gameObject);
				}
			}
			foreach (Item keyItem in keyItems)
			{
				if (!isInInventory(keyItem.gameObject) && !hashSet.Contains(keyItem.gameObject))
				{
					setParent(keyItem.transform, levelContainerTransform);
					keyItem.gameObject.SetActive(value: true);
					Collider[] componentsInChildren = keyItem.transform.GetComponentsInChildren<Collider>();
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						componentsInChildren[i].enabled = true;
					}
					try
					{
						keyItem.targetable = true;
						addItemToInventory(keyItem.gameObject);
						num2++;
					}
					catch (Exception exception)
					{
						UnityEngine.Debug.LogException(exception, keyItem.gameObject);
					}
				}
			}
			UnityEngine.Debug.Log($"Added {num2} key items to inventory.");
		}, debugContent.transform);
		debugMenuAddNewButton("Finish Level", delegate
		{
			levelCompleted();
		}, debugContent.transform);
