		{
			List<Rigidbody> list = new List<Rigidbody>();
			list.AddRange(levelContainer.GetComponentsInChildren<Rigidbody>(includeInactive: true));
			List<Rigidbody> list2 = new List<Rigidbody>();
			foreach (Rigidbody item in list)
			{
				Breakable component = item.GetComponent<Breakable>();
				if (!(component == null))
				{
					foreach (GameObject piece in component.pieces)
					{
						if (piece.TryGetComponent<Rigidbody>(out var component2))
