							list2.Add(component2);
						}
					}
				}
			}
			foreach (Rigidbody item2 in list)
			{
				if (!isInInventory(item2.gameObject) && !(item2.mass > 4f) && !list2.Contains(item2) && !item2.TryGetComponent<Zoomable>(out var _))
				{
					setParent(item2.transform, levelContainerTransform);
					item2.gameObject.SetActive(value: true);
					Collider[] componentsInChildren = item2.transform.GetComponentsInChildren<Collider>();
					for (int i = 0; i < componentsInChildren.Length; i++)
					{
						componentsInChildren[i].enabled = true;
					}
					try
