	private void debugShowPlayerNames(bool value)
	{
		updateCanvasVisibility(localPlayerData.playerObject, value);
		foreach (GamePlayerData netPlayer in netPlayers)
		{
			updateCanvasVisibility(netPlayer.playerObject, value);
		}
		static void updateCanvasVisibility(GameObject player, bool active)
		{
			Canvas[] componentsInChildren = player.GetComponentsInChildren<Canvas>(includeInactive: true);
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].gameObject.SetActive(active);
			}
		}
	}

	private void toggleCanvases(bool turnOff = false)
	{
		if (toggledCanvases.Count == 0 || turnOff)
		{
			debugCanvasesTurnedOff = true;
			disableInventory.addSource(value: true, DisableInventorySource.DebugDisabled);
			Canvas[] componentsInChildren = GetComponentsInChildren<Canvas>(includeInactive: true);
			foreach (Canvas canvas in componentsInChildren)
			{
				if (canvas.gameObject.activeInHierarchy)
				{
					if (!toggledCanvases.Contains(canvas))
					{
						toggledCanvases.Add(canvas);
					}
					canvas.gameObject.SetActive(value: false);
				}
			}
			closeMainMenu();
			return;
		}
		disableInventory.removeSource(DisableInventorySource.DebugDisabled);
		debugCanvasesTurnedOff = false;
		foreach (Canvas toggledCanvase in toggledCanvases)
		{
			toggledCanvase.gameObject.SetActive(value: true);
		}
		toggledCanvases.Clear();
	}

	private void updateDebug()
	{
		if (Input.GetKeyDown(KeyCode.Space))
		{
			UnityUtils.printUIUnderMouse();
		}
		if (Input.GetKeyDown(KeyCode.F5))
		{
			levelCompleted();
		}
		if (Input.GetKeyDown(KeyCode.F9))
		{
			performLevelResync();
		}
		if (Input.GetKeyDown(KeyCode.P))
		{
			UnityEngine.Debug.Break();
		}
		if (Input.GetKey(KeyCode.C))
		{
			Time.timeScale = 10f;
		}
		else if (Input.GetKey(KeyCode.V))
		{
			Time.timeScale = 0.1f;
		}
		else
		{
			Time.timeScale = 1f;
		}
		if (Input.GetKeyDown(KeyCode.L))
		{
			debugColliderRaycasts = !debugColliderRaycasts;
			if (debugColliderRaycasts)
			{
				debugSpheres = new Transform[12600];
				for (int i = 0; i < debugSpheres.Length; i++)
				{
					GameObject gameObject = GameObject.CreatePrimitive(PrimitiveType.Sphere);
					UnityEngine.Object.Destroy(gameObject.GetComponent<Collider>());
					debugSpheres[i] = gameObject.transform;
					debugSpheres[i].localScale = Vector3.one * 0.01f;
				}
			}
			else
			{
				Transform[] array = debugSpheres;
				for (int j = 0; j < array.Length; j++)
				{
					UnityEngine.Object.Destroy(array[j].gameObject);
				}
				debugSpheres = new Transform[0];
			}
		}
		if (debugColliderRaycasts)
		{
			for (int k = 0; k < 90; k++)
			{
				for (int l = 0; l < 140; l++)
				{
					Transform transform = debugSpheres[k * 140 + l];
					if (Physics.Raycast(playerCamera.ViewportPointToRay(new Vector2((float)l * (1f / 140f), (float)k * (1f / 90f))), out var hitInfo, float.PositiveInfinity, -5, QueryTriggerInteraction.Ignore))
					{
						transform.position = hitInfo.point;
					}
					else
					{
						transform.position = Vector3.one * 10000f;
					}
				}
			}
		}
		if (Input.GetKeyDown(KeyCode.F1))
		{
			saveLevel(shouldWriteToDisk: true);
		}
		else if (Input.GetKeyDown(KeyCode.F2))
		{
			loadLevelUsingLatestSave();
		}
		if (Input.GetKeyDown(KeyCode.F8))
		{
			freeCamOn = !freeCamOn;
			toggleCanvases(freeCamOn);
		}
		if (Input.GetKeyDown(KeyCode.F3))
		{
			StartCoroutine(takeScreenshot(2));
		}
		if (Input.GetKeyDown(KeyCode.F3))
		{
			StartCoroutine(takeScreenshot(1));
		}
		if (Input.GetKeyDown(KeyCode.F4))
		{
			StartCoroutine(takeScreenshot(1, "", "", showUI: true));
		}
		if (Input.GetKeyDown(KeyCode.F6))
		{
			StartCoroutine(take());
		}
		if (freeCamOn)
		{
			Vector3 position = localPlayerData.lastTransformPose.position;
			position.y = 0f;
			bool flag = Vector3.Distance(position, localPlayerData.playerObject.transform.position) > 0.0001f;
			if (flag)
			{
				localPlayerData.lastTransformPose.position = localPlayerData.playerObject.transform.position;
				localPlayerData.lastTransformPose.rotation = Quaternion.Euler(debugCharacterPresetRotation.y, debugCharacterPresetRotation.x, 0f);
			}
			if (localPlayerData.animator != null)
			{
				localPlayerData.animator.SetBool("Move", flag);
				localPlayerData.animator.SetBool("Crouch", heightSlider.value == 0);
			}
			AnimatorStateInfo currentAnimatorStateInfo = localPlayerData.animator.GetCurrentAnimatorStateInfo(0);
			if (localPlayerData.lastPlayerPickUpItem)
			{
				if (!currentAnimatorStateInfo.IsName("PickUp"))
				{
					localPlayerData.animator.SetTrigger("PickUp");
				}
				localPlayerData.lastPlayerPickUpItem = false;
			}
		}
		bool flag2 = Input.GetKey(KeyCode.LeftShift) || Input.GetKey(KeyCode.RightShift);
		bool flag3 = Input.GetKey(KeyCode.LeftAlt) || Input.GetKey(KeyCode.RightAlt);
		if (flag2 || flag3)
		{
			for (int m = 0; m < 12; m++)
			{
				KeyCode key = (KeyCode)(48 + m);
				if (m == 10)
				{
					key = KeyCode.Minus;
				}
				if (m == 11)
				{
					key = KeyCode.Equals;
				}
				if (Enum.IsDefined(typeof(DebugAnimation), m) && Input.GetKeyDown(key))
				{
					if (flag2)
					{
						localPlayerData.animator.Play(Enum.GetName(typeof(DebugAnimation), m));
					}
					else
					{
						netPlayers[0].animator.Play(Enum.GetName(typeof(DebugAnimation), m));
					}
				}
			}
		}
		if (freeCamOn)
		{
			Quaternion quaternion = Quaternion.Euler(freeCamRotation.y, freeCamRotation.x, 0f);
			Vector3 zero = Vector3.zero;
			zero.x = (menuOptions.getActionKey(KeyBindingAction.Left) ? (-1) : 0) + (menuOptions.getActionKey(KeyBindingAction.Right) ? 1 : 0);
			zero.y = (menuOptions.getActionKey(KeyBindingAction.Down) ? (-1) : 0) + (menuOptions.getActionKey(KeyBindingAction.Up) ? 1 : 0);
			freeCamPosition += quaternion * Vector3.right * Time.deltaTime * zero.x * PlayerSave.getDebug().freeCamMovementSpeed;
			freeCamPosition += quaternion * Vector3.forward * Time.deltaTime * zero.y * PlayerSave.getDebug().freeCamMovementSpeed;
			freeCamPosition += quaternion * Vector3.up * Time.deltaTime * (Input.GetKey(KeyCode.E) ? 1 : 0) * PlayerSave.getDebug().freeCamMovementSpeed;
			freeCamPosition += quaternion * -Vector3.up * Time.deltaTime * (Input.GetKey(KeyCode.Q) ? 1 : 0) * PlayerSave.getDebug().freeCamMovementSpeed;
			Vector2 vector = new Vector2(0f - Input.GetAxisRaw("Mouse X"), 0f - Input.GetAxisRaw("Mouse Y"));
			freeCamRotation.x -= Time.deltaTime * vector.x * PlayerSave.getDebug().freeCamLookSpeed * 2f;
			freeCamRotation.y += Time.deltaTime * vector.y * PlayerSave.getDebug().freeCamLookSpeed * 2f;
		}
		_ = debugShowCastLine;
		IEnumerator take()
		{
			base.enabled = false;
			Quaternion tilt = Quaternion.Euler(40f, 0f, 0f);
			yield return 0;
			yield return 0;
			yield return 0;
			float fovRestore = playerCamera.fieldOfView;
			playerCamera.fieldOfView = 80f;
			playerCamera.transform.rotation = Quaternion.Euler(0f, 0f, 0f) * tilt;
			playerCamera.transform.position = new Vector3(0f, 2.5f, 0f);
			yield return takeScreenshot(1, "360", "1");
			playerCamera.transform.rotation = Quaternion.Euler(0f, 90f, 0f) * tilt;
			playerCamera.transform.position = new Vector3(0f, 2.5f, 0f);
			yield return takeScreenshot(1, "360", "2");
			playerCamera.transform.rotation = Quaternion.Euler(0f, 180f, 0f) * tilt;
			playerCamera.transform.position = new Vector3(0f, 2.5f, 0f);
			yield return takeScreenshot(1, "360", "3");
			playerCamera.transform.rotation = Quaternion.Euler(0f, 270f, 0f) * tilt;
			playerCamera.transform.position = new Vector3(0f, 2.5f, 0f);
			yield return takeScreenshot(1, "360", "4");
			playerCamera.fieldOfView = 80f;
			playerCamera.transform.rotation = Quaternion.Euler(90f, 0f, 0f);
			playerCamera.transform.position = new Vector3(0f, 3f, 0f);
			yield return takeScreenshot(1, "360", "5");
			playerCamera.fieldOfView = fovRestore;
			base.enabled = true;
		}
		IEnumerator takeScreenshot(int supersampling, string prefix = "", string manualNumber = "", bool showUI = false)
		{
			_ = Time.timeScale;
			disableQualityManagement();
			string folderPath = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
			if (!showUI)
			{
				Canvas[] componentsInChildren = GetComponentsInChildren<Canvas>(includeInactive: true);
				foreach (Canvas canvas in componentsInChildren)
				{
					if (canvas.gameObject.activeInHierarchy)
					{
						toggledCanvases.Add(canvas);
						canvas.gameObject.SetActive(value: false);
					}
				}
			}
			string suffix = ".png";
			if (supersampling > 1)
			{
				suffix = "@" + supersampling + "x.png";
			}
			if (showUI)
			{
				suffix = "-ui" + suffix;
			}
			string base1 = Path.Combine(folderPath, prefix + SceneManager.GetActiveScene().name + "-");
			yield return 0;
			yield return 0;
			yield return 0;
			if (manualNumber != "")
			{
				string text = base1 + manualNumber + suffix;
				UnityEngine.Debug.Log("Taking 360 Screenshot: " + text);
				ScreenCapture.CaptureScreenshot(text, supersampling);
			}
			else
			{
				for (int num = 0; num < 1000; num++)
				{
					string text2 = base1 + num + suffix;
					if (!File.Exists(text2))
					{
						UnityEngine.Debug.Log("Taking Screenshot: " + text2);
						ScreenCapture.CaptureScreenshot(text2, supersampling);
						break;
					}
				}
			}
			yield return 0;
			yield return 0;
			yield return 0;
			if (!showUI)
			{
				foreach (Canvas toggledCanvase in toggledCanvases)
				{
					toggledCanvase.gameObject.SetActive(value: true);
				}
				toggledCanvases.Clear();
			}
		}
	}

	private void saveLevelThenCloseMainMenu()
	{
		saveLevel(shouldWriteToDisk: true);
		closeMainMenu();
	}

	private void loadLevelUsingLatestSave()
	{
		string latestSaveForLevel = getLatestSaveForLevel(levelIdentifier);
		if (latestSaveForLevel == null)
		{
			UnityEngine.Debug.LogError("Could not find latest save for level '" + levelIdentifier + "'.");
		}
		else if (!isSaveFileCompatibleWithLevel(latestSaveForLevel, levelIdentifier))
		{
			UnityEngine.Debug.LogError("Save file '" + latestSaveForLevel + "' is not compatible with level '" + levelIdentifier + "'.");
		}
		else
		{
			loadLevel(latestSaveForLevel);
		}
	}

