	private GameObject debugMenuAddNewToggle(string label, bool initial, Action<bool> onChange, Transform parent, Func<bool> validation = null)
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(debugToggleTemplate, parent);
		gameObject.SetActive(value: true);
		gameObject.GetComponentInChildren<Text>().text = Localization.translate(label);
		Toggle toggle = gameObject.GetComponentInChildren<Toggle>();
		toggle.isOn = initial;
		toggle.onValueChanged.AddListener(delegate
		{
			onChange(toggle.isOn);
			PineFmod.playOneShotSound("event:/SFX/GENERAL/uiToggle");
		});
		if (validation != null)
		{
			objectsToValidate.Add(new ValidateInfo
			{
				objectToControl = gameObject,
				shouldObjectBeVisible = validation
			});
		}
		return gameObject;
	}

	private GameObject debugMenuAddNewSlider(string label, float initial, float min, float max, Action<float> onChange, Transform parent, Func<bool> validation = null)
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(debugSliderTemplate, parent);
		gameObject.SetActive(value: true);
		gameObject.GetComponentInChildren<Text>().text = Localization.translate(label);
		Slider slider = gameObject.GetComponentInChildren<Slider>();
		slider.minValue = min;
		slider.maxValue = max;
		slider.value = initial;
		InputField inputField = gameObject.GetComponentInChildren<InputField>();
		inputField.text = slider.value.ToString("0.00");
		inputField.onValueChanged.AddListener(delegate
		{
			if (float.TryParse(inputField.text, out var result))
			{
				slider.value = result;
			}
		});
		slider.onValueChanged.AddListener(delegate
		{
			onChange(slider.value);
			inputField.text = slider.value.ToString("0.00");
		});
		if (validation != null)
		{
			objectsToValidate.Add(new ValidateInfo
			{
				objectToControl = gameObject,
				shouldObjectBeVisible = validation
			});
		}
		return gameObject;
	}

	private GameObject debugMenuAddNewDropdown(string label, string[] choices, int initial, Action<int> onChange, Transform parent, Func<bool> validation = null)
