	private void startBenchmark()
	{
		benchmarkActive = true;
		benchmarkTimer = 0f;
		fpsList = new List<float>();
		fpsListSide = new List<float>();
		benchmarkLevelId = 0;
		prevSceneName = base.gameObject.scene.name;
		loadNextBenchmarkScene();
	}

	private void loadNextBenchmarkScene()
	{
		int num = 0;
		List<string> allPacks = RoomDatabase.getAllPacks();
		for (int i = 0; i < allPacks.Count; i++)
		{
			List<RoomDatabase.Room> allRooms = RoomDatabase.getAllRooms(allPacks[i], includeUnbuiltRooms: true);
			for (int j = 0; j < allRooms.Count; j++)
			{
				if (num == benchmarkLevelId + 1)
				{
					SceneManager.LoadSceneAsync(allRooms[i].name);
					return;
				}
			}
		}
		benchmarkActive = false;
		SceneManager.LoadSceneAsync(prevSceneName);
	}

	private List<DebugButton> getAllDefinedDebugButtons()
	{
		List<DebugButton> list = new List<DebugButton>();
		BindingFlags bindingAttr = BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;
		MethodInfo[] methods = levelLogic.GetType().GetMethods(bindingAttr);
		foreach (MethodInfo method in methods)
		{
			foreach (DebugButtonAttribute customAttribute in method.GetCustomAttributes<DebugButtonAttribute>())
			{
				int num = method.GetParameters().Length;
				int num2 = customAttribute.args.Length;
				if (num > num2)
				{
					UnityEngine.Debug.LogError($"Method '{method.Name}' expects {num} parameter(s), but {num2} were provided.");
					continue;
				}
				if (num > 0 && num2 % num != 0)
				{
					UnityEngine.Debug.LogError($"Method '{method.Name}' expects multiple of {num} parameters, but {num2} were provided.");
					continue;
				}
				int num3 = ((num <= 0) ? 1 : (customAttribute.args.Length / num));
				Color? color = customAttribute.tint switch
				{
					Tint.Default => null, 
					Tint.Red => Color.red, 
					Tint.Green => Color.green, 
					Tint.Blue => Color.blue, 
					Tint.Yellow => Color.yellow, 
					Tint.DarkGreen => new Color(0f, 0.4f, 0f), 
					_ => null, 
				};
				for (int j = 0; j < num3; j++)
				{
					object[] args = new object[num];
					for (int k = 0; k < num; k++)
					{
						args[k] = customAttribute.args[j * num + k];
					}
					string text = string.Empty;
					if (args.Length != 0)
					{
						text = " (" + string.Join(", ", args) + ")";
					}
					list.Add(new DebugButton
					{
						label = (string.IsNullOrEmpty(customAttribute.label) ? method.Name : customAttribute.label) + text,
						onClick = delegate
						{
							method.Invoke(method.IsStatic ? null : levelLogic, args);
						},
						color = color,
						postClickAction = customAttribute.postClickAction,
						priority = customAttribute.priority
					});
				}
			}
		}
		return list.OrderByDescending((DebugButton button) => button.priority).ToList();
	}

	private void createDebugButton(DebugButton debugButton)
	{
		GameObject buttonObject = UnityEngine.Object.Instantiate(debugButtonTemplate, debugContent.transform);
		buttonObject.SetActive(value: true);
		string text = Regex.Replace(Localization.translate(debugButton.label), "(?<!^)(?<!\\s)([A-Z])", " $1");
		text = char.ToUpper(text[0]) + text.Substring(1);
		buttonObject.GetComponentInChildren<Text>().text = text;
		if (debugButton.color.HasValue)
		{
			buttonObject.GetComponentInChildren<Image>().color = debugButton.color.Value;
		}
		buttonObject.GetComponent<Button>().onClick.AddListener(delegate
		{
			if (isVR())
			{
				vr.vibrateController(1, 0.3f, 0.1f);
				vr.vibrateController(2, 0.3f, 0.1f);
			}
			debugButton.onClick();
			PineFmod.playOneShotSound("event:/SFX/GENERAL/uiToggle");
			if (debugButton.postClickAction.HasFlag(PostClickAction.ReturnToGame))
			{
				closeMainMenu();
			}
			if (debugButton.postClickAction.HasFlag(PostClickAction.HideButton))
			{
				buttonObject.SetActive(value: false);
			}
		});
	}

	public bool hasDeferred(Interactive interactable)
	{
		if (interactable != null)
		{
			return deferredInteractives.Contains(interactable);
		}
		return false;
	}

	private byte[] saveInteractable(Interactive interactable)
	{
		FastBinaryWriter writer;
		using (SharedWriter.borrow(out writer))
		{
			interactable.save(writer);
			if (interactable is Switch3D switch3D)
			{
				if (switch3D.tweenState != null && switch3D.tweenState.hasRecord("Down"))
				{
					writer.Write<float>(switch3D.tweenState.getWeight("Down"), default(FastBinaryWriter.ForPrimitives));
				}
				if (switch3D.sequence != null)
				{
					writer.Write(in switch3D.sequence.sequenceTime, default(FastBinaryWriter.ForPrimitives));
				}
			}
			else if (interactable is Turnable turnable)
			{
				writer.Write<Vector3>(turnable.rootTransform().localPosition, default(FastBinaryWriter.ForPrimitives));
				writer.Write<Quaternion>(turnable.rootTransform().localRotation, default(FastBinaryWriter.ForPrimitives));
				writer.Write<Vector3>(turnable.rootTransform().localScale, default(FastBinaryWriter.ForPrimitives));
			}
			else if (interactable is Dial dial)
			{
				writer.Write<Vector3>(dial.rootTransform().localPosition, default(FastBinaryWriter.ForPrimitives));
				writer.Write<Quaternion>(dial.rootTransform().localRotation, default(FastBinaryWriter.ForPrimitives));
				writer.Write<Vector3>(dial.rootTransform().localScale, default(FastBinaryWriter.ForPrimitives));
			}
			else
			{
				writer.Write<Vector3>(interactable.transform.localPosition, default(FastBinaryWriter.ForPrimitives));
				writer.Write<Quaternion>(interactable.transform.localRotation, default(FastBinaryWriter.ForPrimitives));
				writer.Write<Vector3>(interactable.transform.localScale, default(FastBinaryWriter.ForPrimitives));
			}
			return writer.ToArray();
		}
	}

	private void loadInteractable(Interactive interactable, byte[] data)
	{
		using FastBinaryReader reader = new FastBinaryReader(data);
		interactable.load(reader);
		if (interactable is Switch3D switch3D)
		{
			if (switch3D.tweenState != null && switch3D.tweenState.hasRecord("Down"))
			{
				switch3D.tweenState.setWeight("Down", reader.ReadSingle());
			}
			if (switch3D.sequence != null)
			{
				switch3D.sequence.setTime(reader.ReadSingle());
			}
		}
		else if (interactable is Turnable turnable)
		{
			turnable.rootTransform().localPosition = reader.ReadVector3();
			turnable.rootTransform().localRotation = reader.ReadQuaternion();
			turnable.rootTransform().localScale = reader.ReadVector3();
		}
		else if (interactable is Dial dial)
		{
			dial.rootTransform().localPosition = reader.ReadVector3();
			dial.rootTransform().localRotation = reader.ReadQuaternion();
			dial.rootTransform().localScale = reader.ReadVector3();
		}
		else
		{
			interactable.transform.localPosition = reader.ReadVector3();
			interactable.transform.localRotation = reader.ReadQuaternion();
			interactable.transform.localScale = reader.ReadVector3();
		}
	}

	private void trackLogicChanges(Action performAction)
	{
		if (!isProcessingPacket && !isHost() && !isInBackgroundUpdateProcessing)
		{
			return;
		}
		if (!isHost())
		{
			foreach (Interactive key in localViewState.Keys)
			{
				stateBeforeEvent[key] = saveInteractable(key);
			}
		}
		bool num = PineFmod.enabled;
		PineFmod.enabled = true;
		performAction();
		PineFmod.enabled = num;
		if (isHost())
		{
			return;
		}
		foreach (Interactive key2 in localViewState.Keys)
		{
			byte[] data = saveInteractable(key2);
			List<Action<Interactive>> collection = resolveStateChanges(key2, stateBeforeEvent[key2]);
			changeAppliers[key2].AddRange(collection);
			loadInteractable(key2, data);
		}
	}

