	private void initRoomEditorVolume()
	{
		if (isCustomLevel())
		{
			editorVolumeRefs = levelContainer.GetComponentInChildren<EditorVolumeRefs>();
		}
	}

	private void updateRoomEditorVolume()
	{
		if (!isCustomLevel())
		{
			return;
		}
		if (localPlayerData.postProcessingData != null)
		{
			float t = calculatePercent(localPlayerData.postProcessingData.transitionTime, localPlayerData.postProcessingData.currentTransitionTime);
			localPlayerData.postProcessingData.currentTransitionTime += Time.deltaTime;
			editorVolumeRefs.exposure.fixedExposure.Interp(localPlayerData.postProcessingData.exposureStart, localPlayerData.postProcessingData.exposureGoal, t);
			editorVolumeRefs.ssao.intensity.Interp(localPlayerData.postProcessingData.ssaoIntensityStart, localPlayerData.postProcessingData.ssaoIntensityGoal, t);
			editorVolumeRefs.ssao.radius.Interp(localPlayerData.postProcessingData.ssaoRadiusStart, localPlayerData.postProcessingData.ssaoRadiusGoal, t);
			editorVolumeRefs.bloom.threshold.Interp(localPlayerData.postProcessingData.bloomThresholdStart, localPlayerData.postProcessingData.bloomThresholdGoal, t);
			editorVolumeRefs.bloom.intensity.Interp(localPlayerData.postProcessingData.bloomIntensityStart, localPlayerData.postProcessingData.bloomIntensityGoal, t);
			editorVolumeRefs.colorAdjustments.contrast.Interp(localPlayerData.postProcessingData.colorAdjustmentContrastStart, localPlayerData.postProcessingData.colorAdjustmentContrastGoal, t);
			editorVolumeRefs.colorAdjustments.colorFilter.Interp(localPlayerData.postProcessingData.colorAdjustmentColorFilterStart, localPlayerData.postProcessingData.colorAdjustmentColorFilterGoal, t);
			editorVolumeRefs.colorAdjustments.hueShift.Interp(localPlayerData.postProcessingData.colorAdjustmentHueStart, localPlayerData.postProcessingData.colorAdjustmentHueGoal, t);
			editorVolumeRefs.colorAdjustments.saturation.Interp(localPlayerData.postProcessingData.colorAdjustmentSaturationStart, localPlayerData.postProcessingData.colorAdjustmentSaturationGoal, t);
			editorVolumeRefs.chromaticAberration.intensity.Interp(localPlayerData.postProcessingData.chromaticAberrationIntensityStart, localPlayerData.postProcessingData.chromaticAberrationIntensityGoal, t);
			editorVolumeRefs.vignette.intensity.Interp(localPlayerData.postProcessingData.vignetteIntensityStart, localPlayerData.postProcessingData.vignetteIntensityGoal, t);
			editorVolumeRefs.filmGrain.intensity.Interp(localPlayerData.postProcessingData.grainIntensityStart, localPlayerData.postProcessingData.grainIntensityGoal, t);
			editorVolumeRefs.motionBlur.intensity.Interp(localPlayerData.postProcessingData.motionBlurIntensityStart, localPlayerData.postProcessingData.motionBlurIntensityGoal, t);
		}
		if (localPlayerData.skyData != null)
		{
			float t2 = calculatePercent(localPlayerData.skyData.transitionTime, localPlayerData.skyData.currentTransitionTime);
			localPlayerData.skyData.currentTransitionTime += Time.deltaTime;
			SkyboxType skyboxType = localPlayerData.skyData.skyboxType;
			SkyType skyType = default(SkyType);
			switch (skyboxType)
			{
			case SkyboxType.Procedural:
				skyType = SkyType.Gradient;
				break;
			case SkyboxType.PhysicallyBased:
				skyType = SkyType.PhysicallyBased;
				break;
			case SkyboxType.SixSided:
				skyType = SkyType.HDRI;
				break;
			default:
				global::_003CPrivateImplementationDetails_003E.ThrowSwitchExpressionException(skyboxType);
				break;
			}
			SkyType value = skyType;
			editorVolumeRefs.visualEnvironment.skyType.value = (int)value;
			if (localPlayerData.skyData.skyboxType == SkyboxType.Procedural)
			{
				editorVolumeRefs.gradientSky.top.Interp(localPlayerData.skyData.topColorStart, localPlayerData.skyData.topColorGoal, t2);
				editorVolumeRefs.gradientSky.middle.Interp(localPlayerData.skyData.midColorStart, localPlayerData.skyData.midColorGoal, t2);
				editorVolumeRefs.gradientSky.bottom.Interp(localPlayerData.skyData.botColorStart, localPlayerData.skyData.botColorGoal, t2);
				editorVolumeRefs.gradientSky.gradientDiffusion.Interp(localPlayerData.skyData.horizonSizeStart, localPlayerData.skyData.horizonSizeGoal, t2);
				editorVolumeRefs.gradientSky.exposure.Interp(localPlayerData.skyData.exposureStart, localPlayerData.skyData.exposureGoal, t2);
			}
			else if (localPlayerData.skyData.skyboxType == SkyboxType.SixSided)
			{
				editorVolumeRefs.hdriSky.exposure.Interp(localPlayerData.skyData.exposure2Start, localPlayerData.skyData.exposure2Goal, t2);
				editorVolumeRefs.hdriSky.rotation.Interp(localPlayerData.skyData.rotationStart, localPlayerData.skyData.rotationGoal, t2);
				editorVolumeRefs.hdriSky.hdriSky.Interp(localPlayerData.skyData.cubemapStart, localPlayerData.skyData.cubemapGoal, t2);
			}
			else if (localPlayerData.skyData.skyboxType == SkyboxType.PhysicallyBased)
			{
				editorVolumeRefs.physicallyBasedSky.aerosolDensity.Interp(localPlayerData.skyData.aersolDensityStart, localPlayerData.skyData.aersolDensityGoal, t2);
				editorVolumeRefs.physicallyBasedSky.alphaMultiplier.Interp(localPlayerData.skyData.alphaMultiplierStart, localPlayerData.skyData.alphaMultiplierGoal, t2);
			}
		}
		if (localPlayerData.fogData != null)
		{
			float t3 = calculatePercent(localPlayerData.fogData.transitionTime, localPlayerData.fogData.currentTransitionTime);
			localPlayerData.fogData.currentTransitionTime += Time.deltaTime;
			editorVolumeRefs.fog.meanFreePath.Interp(localPlayerData.fogData.attenuationStart, localPlayerData.fogData.attenuationGoal, t3);
			editorVolumeRefs.fog.maxFogDistance.Interp(localPlayerData.fogData.distanceStart, localPlayerData.fogData.distanceGoal, t3);
			editorVolumeRefs.fog.tint.Interp(localPlayerData.fogData.colorStart, localPlayerData.fogData.colorGoal, t3);
			editorVolumeRefs.fog.enableVolumetricFog.value = localPlayerData.fogData.isVolumetric;
			editorVolumeRefs.fog.albedo.Interp(localPlayerData.fogData.volumetricColorStart, localPlayerData.fogData.volumetricColorGoal, t3);
		}
		if (localPlayerData.cloudData != null)
		{
			float t4 = calculatePercent(localPlayerData.cloudData.transitionTime, localPlayerData.cloudData.currentTransitionTime);
			localPlayerData.cloudData.currentTransitionTime += Time.deltaTime;
			editorVolumeRefs.clouds.opacity.Interp(localPlayerData.cloudData.opacityStart, localPlayerData.cloudData.opacityGoal, t4);
			editorVolumeRefs.clouds.upperHemisphereOnly.value = localPlayerData.cloudData.upperHemisphereOnly;
			editorVolumeRefs.clouds.layerA.opacityR.Interp(localPlayerData.cloudData.opacityColorsStart.r, localPlayerData.cloudData.opacityColorsGoal.r, t4);
			editorVolumeRefs.clouds.layerA.opacityG.Interp(localPlayerData.cloudData.opacityColorsStart.g, localPlayerData.cloudData.opacityColorsGoal.g, t4);
			editorVolumeRefs.clouds.layerA.opacityB.Interp(localPlayerData.cloudData.opacityColorsStart.b, localPlayerData.cloudData.opacityColorsGoal.b, t4);
			editorVolumeRefs.clouds.layerA.opacityA.Interp(localPlayerData.cloudData.opacityColorsStart.a, localPlayerData.cloudData.opacityColorsGoal.a, t4);
			editorVolumeRefs.clouds.layerA.rotation.Interp(localPlayerData.cloudData.rotationStart, localPlayerData.cloudData.rotationGoal, t4);
			editorVolumeRefs.clouds.layerA.tint.Interp(localPlayerData.cloudData.tintStart, localPlayerData.cloudData.tintGoal, t4);
			editorVolumeRefs.clouds.layerA.exposure.Interp(localPlayerData.cloudData.exposureStart, localPlayerData.cloudData.exposureGoal, t4);
			editorVolumeRefs.clouds.layerA.distortionMode.value = (localPlayerData.cloudData.useWind ? CloudDistortionMode.Procedural : CloudDistortionMode.None);
			float value2 = Mathf.Lerp(localPlayerData.cloudData.windDirectionStart, localPlayerData.cloudData.windDirectionGoal, t4);
			editorVolumeRefs.clouds.layerA.scrollOrientation = new WindOrientationParameter(value2, WindParameter.WindOverrideMode.Custom);
			float value3 = Mathf.Lerp(localPlayerData.cloudData.windSpeedStart, localPlayerData.cloudData.windSpeedGoal, t4) * 1000f;
			editorVolumeRefs.clouds.layerA.scrollSpeed = new WindSpeedParameter(value3, WindParameter.WindOverrideMode.Custom);
			editorVolumeRefs.clouds.layerA.castShadows.value = localPlayerData.cloudData.useWind;
			editorVolumeRefs.clouds.shadowTint.Interp(localPlayerData.cloudData.shadowColorStart, localPlayerData.cloudData.shadowColorGoal, t4);
		}
		editorVolumeRefs.ocean.gameObject.SetActive(localPlayerData.oceanData != null);
		if (localPlayerData.oceanData != null)
		{
			float t5 = calculatePercent(localPlayerData.oceanData.transitionTime, localPlayerData.oceanData.currentTransitionTime);
			localPlayerData.oceanData.currentTransitionTime += Time.deltaTime;
			editorVolumeRefs.ocean.largeWindSpeed = Mathf.Lerp(localPlayerData.oceanData.distantWindSizeStart, localPlayerData.oceanData.distantWindSizeGoal, t5);
			editorVolumeRefs.ocean.largeChaos = Mathf.Lerp(localPlayerData.oceanData.chaosStart, localPlayerData.oceanData.chaosGoal, t5);
			editorVolumeRefs.ocean.largeCurrentSpeedValue = Mathf.Lerp(localPlayerData.oceanData.currentSpeedStart, localPlayerData.oceanData.currentSpeedGoal, t5);
			editorVolumeRefs.ocean.largeOrientationValue = Mathf.Lerp(localPlayerData.oceanData.currentSpeedDirectionStart, localPlayerData.oceanData.currentSpeedDirectionGoal, t5);
			editorVolumeRefs.ocean.largeBand0Multiplier = Mathf.Lerp(localPlayerData.oceanData.amplitudeModifierStart, localPlayerData.oceanData.amplitudeModifierGoal, t5);
			editorVolumeRefs.ocean.largeBand1Multiplier = Mathf.Lerp(localPlayerData.oceanData.amplitudeModifierStart, localPlayerData.oceanData.amplitudeModifierGoal, t5);
			editorVolumeRefs.ocean.ripplesWindSpeed = Mathf.Lerp(localPlayerData.oceanData.rippleSpeedStart, localPlayerData.oceanData.rippleSpeedGoal, t5);
			editorVolumeRefs.ocean.refractionColor = Color.Lerp(localPlayerData.oceanData.refractionColorStart, localPlayerData.oceanData.refractionColorGoal, t5);
			editorVolumeRefs.ocean.scatteringColor = Color.Lerp(localPlayerData.oceanData.waterColorStart, localPlayerData.oceanData.waterColorGoal, t5);
			editorVolumeRefs.ocean.ambientScattering = Mathf.Lerp(localPlayerData.oceanData.ambientIntensityStart, localPlayerData.oceanData.ambientIntensityGoal, t5);
			editorVolumeRefs.ocean.transform.position = new Vector3(0f, Mathf.Lerp(localPlayerData.oceanData.heightStart, localPlayerData.oceanData.heightGoal, t5), 0f);
		}
		static float calculatePercent(float totalTransitionTime, float currentTransitionTime)
		{
			float num = UnityUtils.map(0f, totalTransitionTime, 0f, 1f, currentTransitionTime);
			if (!float.IsNaN(num))
			{
				return Mathf.Clamp01(num);
			}
			return 0f;
		}
	}

	public static void applyVolumeData(EditorVolumeRefs refs, EditorPostProcessingData postProcessingData)
	{
		refs.exposure.fixedExposure.value = UnityUtils.map(-3f, 1f, 15f, -5f, postProcessingData.exposure);
		refs.ssao.intensity.value = postProcessingData.ssaoIntensity;
		refs.ssao.radius.value = postProcessingData.ssaoRadius;
		refs.bloom.threshold.value = postProcessingData.bloomThreshold;
		refs.bloom.intensity.value = postProcessingData.bloomIntensity;
		refs.colorAdjustments.contrast.value = postProcessingData.colorAdjustmentContrast;
		refs.colorAdjustments.colorFilter.value = postProcessingData.colorAdjustmentColorFilter;
		refs.colorAdjustments.hueShift.value = postProcessingData.colorAdjustmentHue;
		refs.colorAdjustments.saturation.value = postProcessingData.colorAdjustmentSaturation;
		refs.chromaticAberration.intensity.value = postProcessingData.chromaticAberrationIntensity;
		refs.vignette.intensity.value = postProcessingData.vignetteIntensity;
		refs.filmGrain.intensity.value = postProcessingData.grainIntensity;
		refs.motionBlur.intensity.value = postProcessingData.motionBlurIntensity;
	}

	public static void applySkyData(EditorVolumeRefs refs, SkyboxData skyData)
	{
		SkyboxType type = skyData.type;
		SkyType skyType = default(SkyType);
		switch (type)
		{
		case SkyboxType.Procedural:
			skyType = SkyType.Gradient;
			break;
		case SkyboxType.PhysicallyBased:
			skyType = SkyType.PhysicallyBased;
			break;
		case SkyboxType.SixSided:
			skyType = SkyType.HDRI;
			break;
		default:
			global::_003CPrivateImplementationDetails_003E.ThrowSwitchExpressionException(type);
			break;
		}
		SkyType value = skyType;
		refs.visualEnvironment.skyType.value = (int)value;
		if (skyData.type == SkyboxType.Procedural)
		{
			refs.gradientSky.top.value = skyData.topColor;
			refs.gradientSky.middle.value = skyData.midColor;
			refs.gradientSky.bottom.value = skyData.botColor;
			refs.gradientSky.gradientDiffusion.value = skyData.horizonSize;
			refs.gradientSky.exposure.value = skyData.exposure;
		}
		else if (skyData.type == SkyboxType.SixSided)
		{
			refs.hdriSky.exposure.value = skyData.exposure2;
			refs.hdriSky.rotation.value = skyData.rotation;
			refs.hdriSky.hdriSky.value = skyData.tempTexture;
		}
		else if (skyData.type == SkyboxType.PhysicallyBased)
		{
			refs.physicallyBasedSky.aerosolDensity.value = skyData.aersolDensity;
			refs.physicallyBasedSky.alphaMultiplier.value = skyData.alphaMultiplier;
		}
	}

	public static void applyFogData(EditorVolumeRefs refs, FogData fogData)
	{
		refs.fog.meanFreePath.value = fogData.attenuation;
		refs.fog.maxFogDistance.value = fogData.distance;
		refs.fog.maximumHeight.value = fogData.maxHeight;
		refs.fog.tint.value = fogData.color;
		refs.fog.enableVolumetricFog.value = fogData.isVolumetric;
		refs.fog.albedo.value = fogData.volumetricColor;
	}

	public static void applyClouds(EditorVolumeRefs refs, CloudsData cloudsData)
	{
		refs.clouds.opacity.value = cloudsData.opacity;
		refs.clouds.upperHemisphereOnly.value = cloudsData.upperHemisphereOnly;
		refs.clouds.layerA.opacityR.value = cloudsData.opacityColorsR;
		refs.clouds.layerA.opacityG.value = cloudsData.opacityColorsG;
		refs.clouds.layerA.opacityB.value = cloudsData.opacityColorsB;
		refs.clouds.layerA.opacityA.value = cloudsData.opacityColorsA;
		refs.clouds.layerA.rotation.value = cloudsData.rotation;
		refs.clouds.layerA.tint.value = cloudsData.tint;
		refs.clouds.layerA.exposure.value = cloudsData.exposure;
		refs.clouds.layerA.distortionMode.value = (cloudsData.useWind ? CloudDistortionMode.Procedural : CloudDistortionMode.None);
		refs.clouds.layerA.scrollOrientation.value = new WindParameter.WindParamaterValue
		{
			mode = WindParameter.WindOverrideMode.Custom,
			customValue = cloudsData.windDirection
		};
		refs.clouds.layerA.scrollSpeed.value = new WindParameter.WindParamaterValue
		{
			mode = WindParameter.WindOverrideMode.Custom,
			customValue = cloudsData.windSpeed * 1000f
		};
		refs.clouds.layerA.castShadows.value = cloudsData.useWindShadows;
		refs.clouds.shadowTint.value = cloudsData.windShadowsColor;
	}

	public static void applyOcean(EditorVolumeRefs refs, OceanData oceanData)
	{
		refs.ocean.gameObject.SetActive(oceanData != null);
		if (oceanData != null)
		{
			refs.ocean.largeWindSpeed = oceanData.distantWindSize;
			refs.ocean.largeChaos = oceanData.chaos;
			refs.ocean.largeCurrentSpeedValue = oceanData.currentSpeed;
			refs.ocean.largeOrientationValue = oceanData.currentDirection;
			refs.ocean.largeBand0Multiplier = oceanData.amplitudeModifier;
			refs.ocean.largeBand1Multiplier = oceanData.amplitudeModifier;
			refs.ocean.ripplesWindSpeed = oceanData.rippleSpeed;
			refs.ocean.refractionColor = oceanData.refractionColor;
			refs.ocean.scatteringColor = oceanData.waterColor;
			refs.ocean.ambientScattering = oceanData.ambientIntensity;
			refs.ocean.transform.position = new Vector3(0f, oceanData.height, 0f);
		}
	}

