	public void initFinishLevel()
	{
		finishLevelUI.root.gameObject.SetActive(value: false);
		finishLevelUI.SafeAreas_FinalScreen.gameObject.SetActive(value: false);
	}

	public void destroyFinishScreen()
	{
		UnityEngine.Object.Destroy(screenshotTexture);
		screenshotTexture = null;
	}

	public void enterFinishLevel(FinishLevelShot finishLevelShot)
	{
		session.lockLobby();
		currentFinishLevelShot = finishLevelShot;
		if (finishLevelImageState.current == FinishLevelImageState.None)
		{
			setupTakePhotoScreen();
		}
		else
		{
			setupPhotoFinish();
		}
		for (int num = pinnedItems.Count - 1; num >= 0; num--)
		{
			handleUnpinItem(pinnedItems[num].originalItem, setItemInWorld: false);
		}
		for (int i = 0; i < zoomContexts.Count; i++)
		{
			handleZoomLeave();
		}
		if (localPlayerData.customMode != null)
		{
			handleCustomModeLeave(localPlayerData.customMode);
		}
		finishLevelUI.root.gameObject.SetActive(value: true);
		menuHostOptions.gameObject.SetActive(value: false);
		finishLevelUI.SafeAreas_TopModal_AwardsModal_Token_Number.text = $"{syncedFoundTokens.Count}/8";
		finishLevelUI.SafeAreas_FinalScreen_TopModal_TitleText.text = Localization.lookupInDictionary("congratulationLevel");
		finishLevelUI.SafeAreas_TopModal_TitleText.text = getLocalizedNameOfScene();
		if (PlayerSave.getSettings().showTimer)
		{
			finishLevelUI.SafeAreas_TopModal_AwardsModal_Time.gameObject.SetActive(value: true);
			int num2 = Mathf.FloorToInt(timerCurrentTime / 60f);
			int num3 = Mathf.FloorToInt(timerCurrentTime % 60f);
			finishLevelUI.SafeAreas_TopModal_AwardsModal_Time_Number.text = $"{num2:00}:{num3:00}";
		}
		setupPlayersForPhoto();
		void setupPlayersForPhoto()
		{
			List<NetPlayerId> finishLevelNetIds = new List<NetPlayerId>();
			finishLevelNetIds.Add(localPlayerData.id);
			foreach (GamePlayerData netPlayer in netPlayers)
			{
				finishLevelNetIds.Add(netPlayer.id);
			}
			finishLevelNetIds.Sort();
			UnityEngine.Debug.Log("sorted playerIds count " + finishLevelNetIds.Count);
			int playersCountIndex = getPlayerCountIndex();
			if (finishLevelShot != null && playersCountIndex >= 0 && playersCountIndex < finishLevelShot.poseParents.Count)
			{
				finishLevelShot.poseParents[playersCountIndex].gameObject.SetActive(value: true);
			}
			System.Random random = new System.Random(getSyncedRandomSeed());
			int[] playerIdRandomizer = new int[finishLevelNetIds.Count];
			for (int j = 0; j < playerIdRandomizer.Length; j++)
			{
				playerIdRandomizer[j] = j;
			}
			for (int num4 = playerIdRandomizer.Length - 1; num4 > 0; num4--)
			{
				int num5 = random.Next(0, num4 + 1);
				ref int reference = ref playerIdRandomizer[num4];
				ref int reference2 = ref playerIdRandomizer[num5];
				int num6 = playerIdRandomizer[num5];
				int num7 = playerIdRandomizer[num4];
				reference = num6;
				reference2 = num7;
			}
			string text = "";
			for (int k = 0; k < playerIdRandomizer.Length; k++)
			{
				text = text + playerIdRandomizer[k] + " ";
			}
			UnityEngine.Debug.Log("randomizer " + text + " " + finishLevelNetIds.Count);
			createClone(localPlayerData.id, localPlayerData.selectedCharacter.gameObject);
			localPlayerData.playerObject.gameObject.SetActive(value: false);
			foreach (GamePlayerData netPlayer2 in netPlayers)
			{
				netPlayer2.playerObject.gameObject.SetActive(value: false);
				createClone(netPlayer2.id, netPlayer2.selectedCharacter.gameObject);
			}
			finishLevelUI.Flash.gameObject.SetActive(value: false);
			void createClone(NetPlayerId id, GameObject character)
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(getAllPlayers().Find((GamePlayerData x) => x.id == id).selectedCharacter).gameObject;
				gameObject.GetComponentInChildren<Canvas>(includeInactive: true).gameObject.SetActive(value: false);
