	private void changeCheezeState(ShotClone character, bool state)
	{
		character.cheezeDown = state;
		bool flag = false;
		foreach (ShotClone finishLevelShotCharacter in finishLevelShotCharacters)
		{
			if (finishLevelShotCharacter.cheezeDown)
			{
				flag = true;
				break;
			}
		}
		if (flag && finishLevelImageState.current == FinishLevelImageState.None)
		{
			finishLevelImageState.changeState(FinishLevelImageState.TakeScreenshot);
			takePhotoVisualControl.setCurrentDownTimestamp(Time.time);
		}
		else if (!flag && finishLevelImageState.current == FinishLevelImageState.TakeScreenshot)
		{
			finishLevelImageState.changeState(FinishLevelImageState.None);
			takePhotoVisualControl.setCurrentDownTimestamp(0f);
		}
	}

	public void cheezeDown()
	{
		UnityEngine.Debug.Log("Cheeze down");
		session.send(new FinishLevelCheezeStatePacket
		{
			down = true
		});
		changeCheezeState(finishLevelLocalCharacter, state: true);
	}

	public void cheezeUp()
	{
		UnityEngine.Debug.Log("Cheeze up");
		session.send(new FinishLevelCheezeStatePacket
		{
			down = false
		});
		changeCheezeState(finishLevelLocalCharacter, state: false);
	}

	public void exitFinishLevelLocal()
	{
		if (session.isHost(session.localPlayerId))
		{
			if (isInViewPhotoScreen)
			{
				exitFinishLevel();
				session.send(new FinishLevelStaySyncedPacket(), allowSendInMessageResponse: true);
			}
		}
		else
		{
			session.send(new FinishLevelStayRequestPacket());
		}
	}

	public void retakePhotoLocal()
	{
		if (session.isHost(session.localPlayerId))
		{
			if (isInFinishLevelScreen && isInViewPhotoScreen)
			{
				setupTakePhotoScreen();
				session.send(new FinishLevelRetakeSyncedPacket(), allowSendInMessageResponse: true);
			}
		}
		else
		{
			session.send(new FinishLevelRetakeRequestPacket());
		}
	}

	public void exitFinishLevel()
	{
		if (!isInFinishLevelScreen)
		{
			return;
		}
		removeGameFrameSource(GameFrameSourceType.FinishLevel);
		session.unlockLobby();
		finishLevelBlur = 0f;
		finishLevelUI.root.gameObject.SetActive(value: false);
		foreach (ShotClone finishLevelShotCharacter in finishLevelShotCharacters)
		{
			UnityEngine.Object.Destroy(finishLevelShotCharacter.clone);
		}
		finishLevelShotCharacters.Clear();
		localPlayerData.playerObject.gameObject.SetActive(value: true);
		foreach (GamePlayerData netPlayer in netPlayers)
		{
			netPlayer.playerObject.gameObject.SetActive(value: true);
		}
		if (!(currentFinishLevelShot != null))
		{
			return;
		}
		foreach (Transform poseParent in currentFinishLevelShot.poseParents)
		{
			poseParent.gameObject.SetActive(value: false);
		}
	}

	private int getPlayerCountIndex()
	{
		if (currentFinishLevelShot != null)
		{
			return Mathf.Min(netPlayers.Count, currentFinishLevelShot.poseParents.Count - 1);
		}
		return 0;
	}

	private NetPlayerId[] swapFinishLevelCharactersHost(ShotClone localCharacter, ShotClone shotClone)
	{
		ShotClone shotClone2 = shotClone;
		int shotPlaceId = shotClone.shotPlaceId;
		int shotPlaceId2 = localCharacter.shotPlaceId;
		localCharacter.shotPlaceId = shotPlaceId;
		shotClone2.shotPlaceId = shotPlaceId2;
		List<ShotClone> list = new List<ShotClone>(finishLevelShotCharacters);
		for (int i = 0; i < list.Count - 1; i++)
		{
			for (int j = i + 1; j < list.Count; j++)
			{
				if (list[i].shotPlaceId > list[j].shotPlaceId)
				{
					shotPlaceId2 = i;
					List<ShotClone> list2 = list;
					shotPlaceId = j;
					shotClone2 = list[j];
					ShotClone shotClone3 = list[i];
					ShotClone shotClone4 = (list[shotPlaceId2] = shotClone2);
					shotClone4 = (list2[shotPlaceId] = shotClone3);
				}
			}
		}
		NetPlayerId[] array = new NetPlayerId[list.Count];
		for (int k = 0; k < list.Count; k++)
		{
			array[k] = list[k].netId;
		}
		return array;
	}

	private void swapFinishLevelCharactersLocal(ShotClone localCharacter, ShotClone shotClone)
	{
		if (session.isHost(session.localPlayerId))
		{
			NetPlayerId[] array = swapFinishLevelCharactersHost(localCharacter, shotClone);
			finishLevelSwapCharacters(array);
			session.send(new FinishLevelSwapPlaceSyncedPacket
			{
				playerLocations = array
			}, allowSendInMessageResponse: true);
		}
		else
		{
			session.send(new FinishLevelSwapPlaceRequestPacket
			{
				index1 = localCharacter.shotPlaceId,
				index2 = shotClone.shotPlaceId
			});
		}
	}

	public void updateFinishLevel()
	{
		if (!isInFinishLevelScreen)
		{
			return;
		}
		Vector3 newValue = Vector3.up;
		Quaternion newValue2 = Quaternion.identity;
		if (currentFinishLevelShot != null)
		{
			newValue = currentFinishLevelShot.eyePosition;
			newValue2 = currentFinishLevelShot.eyeRotation;
		}
		contestedCameraPosition.set(ContestedPose.FinishLevel, newValue, oneFrame: true);
		contestedCameraRotation.set(ContestedPose.FinishLevel, newValue2, oneFrame: true);
		contestedFov.set(ContestedFov.FreeCam, 50f, oneFrame: true);
		Ray ray = playerCamera.ScreenPointToRay(Input.mousePosition);
		if (getMouseButtonDown(0) && !finishLevelLocalCharacter.cheezeDown)
		{
			foreach (ShotClone finishLevelShotCharacter in finishLevelShotCharacters)
			{
				if (finishLevelShotCharacter.collider.Raycast(ray, out var _, 100f) && finishLevelShotCharacter != finishLevelLocalCharacter)
				{
					swapFinishLevelCharactersLocal(finishLevelLocalCharacter, finishLevelShotCharacter);
					break;
				}
			}
		}
		if (finishLevelFaceAnimPicker.isDragging || finishLevelFaceAnimPicker.forceUpdate)
		{
			Vector2 anchoredPosition = finishLevelFaceAnimPicker.rectTransform.anchoredPosition;
			anchoredPosition /= finishLevelFaceAnimPicker.maxOffset;
			session.send(new FinishLevelChangeFacePacket
			{
				faceAnim = anchoredPosition
			});
			changeFace(finishLevelLocalCharacter, anchoredPosition);
			finishLevelFaceAnimPicker.forceUpdate = false;
		}
		finishLevelImageState.update();
		float time = finishLevelImageState.time;
		switch (finishLevelImageState.current)
		{
		case FinishLevelImageState.TakeScreenshot:
			if (time > 1f)
			{
				startFinishLevelScreenshotSynced();
			}
			break;
		case FinishLevelImageState.Flash:
			finishLevelUI.Flash.color = new Color(1f, 1f, 1f, flashCurve.Evaluate(Mathf.Clamp01(time)));
			if (time > 1f)
			{
				finishLevelUI.Flash.gameObject.SetActive(value: false);
				setupPhotoFinish();
				finishLevelImageState.changeState(FinishLevelImageState.ImageAnim);
			}
			break;
		case FinishLevelImageState.ImageAnim:
		{
			float num = time * 1.5f;
			finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageMask.transform.localScale = Vector3.Lerp(Vector3.zero, Vector3.one, num);
			finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageMask.color = Color.Lerp(Color.clear, Color.white, num);
			finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageBackground.transform.localScale = Vector3.Lerp(Vector3.zero, Vector3.one, num);
			finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageBackground.color = Color.Lerp(Color.clear, Color.white, num);
			if (num >= 1f)
			{
				finishLevelImageState.changeState(FinishLevelImageState.End);
			}
			break;
		}
		}
		FinishLevelImageState current2 = finishLevelImageState.current;
		int num2 = ((current2 == FinishLevelImageState.ImageAnim || current2 == FinishLevelImageState.End) ? 1 : 0);
		finishLevelBlur = Mathf.MoveTowards(finishLevelBlur, num2, Time.deltaTime * 5f);
		if (loadOldScreenshotTask != null && loadOldScreenshotTask.IsCompletedSuccessfully)
		{
			screenshotTexture = new Texture2D(2, 2, TextureFormat.RGBA32, mipChain: false);
			if (screenshotTexture.LoadImage(loadOldScreenshotTask.Result))
			{
				setImageToScreen();
			}
			else
			{
				UnityEngine.Debug.LogError("Couldn't load last screenshot.");
			}
			loadOldScreenshotTask = null;
		}
	}

	private void startFinishLevelScreenshotSynced()
	{
		if (session.isHost(session.localPlayerId))
		{
			startFinishLevelScreenshotLocal();
			session.send(new FinishLevelStartScreenshotPacket());
		}
	}

	private void startFinishLevelScreenshotLocal()
	{
		StartCoroutine(takeScreenshot());
		PineFmod.playOneShotSound("event:/Sound Effects/00 General/Shutter");
		finishLevelImageState.changeState(FinishLevelImageState.Flash);
	}

	private void changeFace(ShotClone character, Vector2 pos)
	{
		float num = Mathf.Clamp01((pos.x + 1f) * 0.5f);
		float num2 = Mathf.Clamp01((pos.y + 1f) * 0.5f);
		float num3 = 1f - Mathf.Abs(num - 0.5f) * 2f;
		float num4 = 1f - Mathf.Abs(num2 - 0.5f) * 2f;
		float num5 = Mathf.Clamp01(num3 * num4);
		float num6 = (1f - num) * num2;
		float num7 = num * num2;
		float num8 = (1f - num) * (1f - num2);
		float num9 = num * (1f - num2);
		float num10 = 1f - num5;
		num6 *= num10;
		num7 *= num10;
		num8 *= num10;
		num9 *= num10;
		Vector4 vector = new Vector4(num6, num7, num8, num9);
		character.faceMesh.SetBlendShapeWeight(character.blendShapeIndexes[0], vector.y * 60f);
		character.faceMesh.SetBlendShapeWeight(character.blendShapeIndexes[1], vector.x * 80f);
		character.faceMesh.SetBlendShapeWeight(character.blendShapeIndexes[2], vector.z * 100f);
		character.faceMesh.SetBlendShapeWeight(character.blendShapeIndexes[3], vector.w * 100f);
		character.mouthMesh.SetBlendShapeWeight(character.blendShapeIndexes[4], vector.y * 60f);
		character.mouthMesh.SetBlendShapeWeight(character.blendShapeIndexes[5], vector.x * 80f);
	}

	private void finishLevelSwapCharacters(NetPlayerId[] playerPositions)
	{
		int playerCountIndex = getPlayerCountIndex();
		for (int i = 0; i < playerPositions.Length; i++)
		{
			foreach (ShotClone finishLevelShotCharacter in finishLevelShotCharacters)
			{
				if (!(finishLevelShotCharacter.netId != playerPositions[i]))
				{
					Transform transform = currentFinishLevelShot.getPoses(playerCountIndex)[i];
					finishLevelShotCharacter.clone.transform.position = transform.position;
					finishLevelShotCharacter.clone.transform.rotation = transform.rotation;
					finishLevelShotCharacter.clone.transform.localScale = transform.localScale;
					finishLevelShotCharacter.animator.Play(transform.name);
				}
			}
		}
	}

	private void onFinishLevelButtonDown(string id)
	{
		if (id == "finishTakePhoto")
		{
			cheezeDown();
		}
	}

	private void onFinishLevelButtonClick(string id)
	{
		if (isInViewPhotoScreen)
		{
			switch (id)
			{
			case "finishStay":
				exitFinishLevelLocal();
				break;
			case "finishExitToLobby":
				requestOrLoadLobby();
				break;
			case "finishNextEpisode":
				loadNextScene();
				break;
			case "finishRetakePhoto":
				retakePhotoLocal();
				break;
			}
		}
		if (id == "finishReStay")
		{
			finishLevelImageState.changeState(FinishLevelImageState.None);
			exitFinishLevel();
		}
	}

	private void onFinishLevelButtonUp(string id)
	{
		if (id == "finishTakePhoto")
		{
			cheezeUp();
		}
	}

	private void setupTakePhotoScreen()
	{
		if (!finishLevelUI.SafeAreas_PoseSelection.gameObject.activeInHierarchy)
		{
			finishLevelUI.SafeAreas_PoseSelection.gameObject.SetActive(value: true);
			finishLevelUI.SafeAreas_FinalScreen.gameObject.SetActive(value: false);
			finishLevelUI.SafeAreas_TopModal.gameObject.SetActive(value: false);
			List<VisualControl> list = new List<VisualControl>();
			if (isTestingPlaymodeInEditor)
			{
				VisualControl visualControl = new VisualControl("finishReStay", ControllerButtonActionType.UIBack, "%stay%", VisualControl.ControlType.Button, VisualControl.Position.BotCenter);
				visualControl.addEscape();
				list.Add(visualControl);
			}
			else
			{
				takePhotoVisualControl = new VisualControl("finishTakePhoto", ControllerButtonActionType.UIConfirmPrimary, "%takePhoto%", VisualControl.ControlType.Button, VisualControl.Position.BotCenter);
				takePhotoVisualControl.addKeybindAction(KeyBindingAction.ExamineInventory, menuOptions);
				takePhotoVisualControl.setTimeToClick(1f, isExternallyControlled: true);
				list.Add(takePhotoVisualControl);
			}
			addGameFrameSource(GameFrameSourceType.FinishLevel, list);
			finishLevelUI.SafeAreas_TopModal.gameObject.SetActive(value: false);
			finishLevelImageState.changeState(FinishLevelImageState.None);
		}
	}

