	{
		UnityEngine.Debug.Log("setupPhotoFinish");
		finishLevelUI.SafeAreas_PoseSelection.gameObject.SetActive(value: false);
		finishLevelUI.SafeAreas_FinalScreen.gameObject.SetActive(value: true);
		finishLevelUI.SafeAreas_TopModal.gameObject.SetActive(value: true);
