		{
			VisualControl item = new VisualControl("finishNextEpisode", ControllerButtonActionType.UIExtra2, "%nextepisode%", VisualControl.ControlType.Button, VisualControl.Position.BotRight);
			list.Add(item);
		}
		addGameFrameSource(GameFrameSourceType.FinishLevel, list);
	}

	private IEnumerator takeScreenshot()
	{
		UnityEngine.Debug.Log("Take screenshot");
		foreach (ShotClone finishLevelShotCharacter in finishLevelShotCharacters)
		{
			EyeController componentInChildren = finishLevelShotCharacter.clone.GetComponentInChildren<EyeController>();
			if (componentInChildren != null)
			{
				componentInChildren.forceOpenEyes();
				componentInChildren.enabled = false;
			}
			else
			{
				UnityEngine.Debug.LogError("No eye controller found on " + finishLevelShotCharacter.clone.name);
			}
		}
		yield return new WaitForEndOfFrame();
		(int width, int height) resizedTextureDimensions = getResizedTextureDimensions(Screen.width, Screen.height);
		int item = resizedTextureDimensions.width;
		int item2 = resizedTextureDimensions.height;
		RenderTexture tempRT = new RenderTexture(item, item2, 0, RenderTextureFormat.ARGB32);
		if (!tempRT.Create())
		{
			UnityEngine.Debug.LogError("Failed creating finish level render texture.");
		}
		else
		{
			playerCamera.targetTexture = tempRT;
			playerCamera.Render();
			AsyncGPUReadback.Request(tempRT, 0, TextureFormat.RGBA32, delegate(AsyncGPUReadbackRequest request)
			{
				tempRT.Release();
				UnityEngine.Object.Destroy(tempRT);
				if (request.hasError)
				{
					UnityEngine.Debug.LogError("Screenshot capture failed.");
				}
				else
				{
					var (width, height) = getResizedTextureDimensions(Screen.width, Screen.height);
					screenshotTexture = new Texture2D(width, height, TextureFormat.RGBA32, mipChain: false);
					screenshotTexture.LoadRawTextureData(request.GetData<byte>());
					screenshotTexture.Apply();
					setImageToScreen();
					string path = "FinishLevelImages";
					string text = Path.Combine(UnityEngine.Application.persistentDataPath, path);
					if (!Directory.Exists(text))
					{
						Directory.CreateDirectory(text);
					}
					string path2 = Path.Combine(text, levelIdentifier + ".png");
					if (File.Exists(path2))
					{
						string path3 = $"{levelIdentifier}_{5}.png";
						if (File.Exists(path3))
						{
							File.Delete(path3);
						}
						for (int num = 4; num >= 1; num--)
						{
							string text2 = ((num == 1) ? levelIdentifier : $"{levelIdentifier}_{num}");
							string text3 = $"{levelIdentifier}_{num + 1}";
							string text4 = Path.Combine(text, text2 + ".png");
							string text5 = Path.Combine(text, text3 + ".png");
							if (File.Exists(text4))
							{
								if (File.Exists(text5))
								{
									File.Delete(text5);
								}
								File.Move(text4, text5);
							}
						}
					}
					File.WriteAllBytesAsync(path2, screenshotTexture.EncodeToPNG());
				}
			});
			playerCamera.targetTexture = null;
		}
		finishLevelUI.Flash.gameObject.SetActive(value: true);
	}

	private (int width, int height) getResizedTextureDimensions(int initialWidth, int initialHeight)
	{
		int num = initialHeight;
		int num2 = initialWidth;
		float num3 = (float)num2 / (float)num;
		if (num > 1024 || num2 > 1024)
		{
			if (num2 > num)
			{
				num2 = 1024;
				num = Mathf.RoundToInt(1024f / num3);
			}
			else
			{
				num = 1024;
				num2 = Mathf.RoundToInt(1024f * num3);
			}
		}
		return (width: num2, height: num);
	}

	private void setImageToScreen()
	{
		finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageMask_FinishLevelImage.texture = screenshotTexture;
		RectTransform component = finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageMask_FinishLevelImage.GetComponent<RectTransform>();
		float num = (float)screenshotTexture.width / (float)screenshotTexture.height;
		float num2 = 1.7777778f;
		component.sizeDelta = new Vector2(component.sizeDelta.y * num, component.sizeDelta.y);
		finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageMask.GetComponent<RectTransform>().sizeDelta = new Vector2(component.sizeDelta.y * num2, component.sizeDelta.y);
		finishLevelUI.SafeAreas_FinalScreen_FinishLevelImageBackground.GetComponent<RectTransform>().sizeDelta = new Vector2(component.sizeDelta.y * num2 + 25f, component.sizeDelta.y + 25f);
	}

	private void handleInteractiveCancel(Interactive interactive)
	{
		if (interactive is Turnable turnable)
		{
			handleTurnableCancel(turnable);
		}
		else if (interactive is Trackable trackable)
		{
			handleTrackableFinalize(trackable);
		}
		else if (interactive is Dial dial)
		{
			handleDialCancel(dial);
		}
		else if (interactive is Slidable slidable)
		{
			handleSlidableCancel(slidable);
		}
		else if (interactive is SlidableGraphPiece piece)
		{
			handleSlidableGraphCancel(piece);
		}
		else if (interactive is HorizontalSlider horizontalSlider)
		{
			handleHorizontalSliderCancel(horizontalSlider);
		}
		else if (interactive is Draggable draggable)
		{
			handleDraggableCancel(draggable);
		}
		else if (!(interactive is Slot) && !(interactive is CharacterPose))
		{
			if (interactive is Switch3D switch3D)
			{
				handleSwitch3DCancel(switch3D);
			}
			else if (interactive is JigsawPiece piece2)
			{
				handleJigsawCancel(piece2);
			}
			else
			{
				UnityEngine.Debug.LogError($"NO CANCEL IMPLEMENTED FOR {interactive.name} ({interactive.GetType()})", interactive);
			}
		}
		cancelSoundsOnInteractive(interactive);
	}

	private void cancelSoundsOnInteractive(Interactive interactive)
	{
		PineFmod.stop(interactive.soundEmitter);
		if (interactive is SlidableGraphPiece slidableGraphPiece)
		{
			PineFmod.stop(slidableGraphPiece.graph.soundEmitter);
		}
	}

	private void handleInteractiveBackground(Interactive interactive, float dt)
	{
		if (interactive.backgroundUpdate)
		{
			if (interactive is Turnable turnable)
			{
				handleTurnableBackground(turnable, dt);
			}
			else if (interactive is Dial dial)
			{
				handleDialBackground(dial, dt);
			}
			else if (interactive is Slidable slidable)
			{
				handleSlidableBackground(slidable, dt);
			}
			else if (interactive is SlidableGraphPiece piece)
			{
				handleSlidableGraphBackground(piece, dt);
			}
			else if (interactive is HorizontalSlider horizontalSlider)
			{
				handleHorizontalSliderBackground(horizontalSlider, dt);
			}
			else if (interactive is Draggable draggable)
			{
				handleDraggableBackground(draggable, dt);
			}
			else if (interactive is Chessable chessable)
			{
				handleChessableBackground(chessable, dt);
			}
			else if (interactive is Joystick joystick)
			{
				handleJoystickBackground(joystick, dt);
			}
			else if (interactive is Slot slot)
			{
				handleSlotBackground(slot, dt);
			}
			else if (interactive is SurfaceSlot surfaceSlot)
			{
				handleSurfaceSlotBackground(surfaceSlot, dt);
			}
			else if (interactive is Item item)
			{
				handleItemBackground(item, dt);
			}
			else if (interactive is Switch3D switch3D)
			{
				handleSwitch3DBackground(switch3D, dt);
			}
			else if (interactive is Jigsaw jigsaw)
			{
				handleJigsawBackground(jigsaw, dt);
			}
			else if (interactive is JigsawPiece piece2)
			{
				handleJigsawPieceBackground(piece2, dt);
			}
			else if (interactive is CharacterPose pose)
			{
				handlePoseBackground(pose, dt);
			}
			else
			{
				UnityEngine.Debug.LogError($"NO BACKGROUND IMPLEMENTED FOR {interactive.name} ({interactive.GetType()})", interactive);
			}
			interactive.backgroundTime = (interactive.backgroundUpdate ? (interactive.backgroundTime + dt) : 0f);
			if (myInteractingObjects.Contains(interactive.gameObject) && !interactive.backgroundUpdate && !isInInventory(interactive.gameObject))
			{
				stopInteraction(interactive.gameObject);
			}
		}
	}

	private void handleSlidable(Pointer pointer)
	{
		Slidable component = pointer.context.target.GetComponent<Slidable>();
		if (component.sessionId != pointer.context.interactionSessionId)
		{
			component.sessionId = pointer.context.interactionSessionId;
			component.cameraStartPosition = playerCamera.transform.position;
			component.cameraStartRotation = playerCamera.transform.rotation;
			component.lastSyncedPosition = component.transform.position;
			component.idleFrames = 0;
			component.pointerScreenPosition = Vector3.Lerp(playerCamera.WorldToScreenPoint(component.startPoint), playerCamera.WorldToScreenPoint(component.endPoint), component.value);
			startInteraction(component.gameObject);
			controllerStartInteraction(pointer);
			handleSlidableStart(component);
			session.send(new SlidableStartPacket
			{
				slidable = component
			});
		}
		component.pointerScreenPosition += pointer.gestureMovementScreen;
		Vector3 position = playerCamera.transform.position;
		Quaternion rotation = playerCamera.transform.rotation;
		if (isVR())
		{
			playerCamera.transform.position = component.cameraStartPosition;
			playerCamera.transform.rotation = component.cameraStartRotation;
		}
		Vector3 vector = playerCamera.WorldToScreenPoint(component.startPoint);
		Vector3 vector2 = playerCamera.WorldToScreenPoint(component.endPoint);
		if (isVR())
		{
			playerCamera.transform.position = position;
			playerCamera.transform.rotation = rotation;
		}
		Vector3 projected = component.pointerScreenPosition - vector;
		Vector3 onVector = vector2 - vector;
		float num = Vector3.Dot(onVector.normalized, pointer.gestureMovementScreen.normalized);
		float value = ((Controller.isActive() && component.controllerSpeed > 0f) ? (component.value + num * component.controllerSpeed * (pointer.gestureMovementScreen / 5f).magnitude) : ((component.mouseDragType != MouseDragType.ScreenPosition) ? (component.value + num * (pointer.gestureMovementScreen.magnitude / onVector.magnitude) * component.mouseDragSpeed) : Maths.vectorProjectionPercent(projected, onVector)));
		value = Mathf.Clamp01(value);
		handleSlidableInteraction(component, value);
		session.send(new SlidableInteractionPacket
		{
			slidable = component,
			percent = value
		});
		if (value < 0f)
		{
			component.pointerScreenPosition = vector;
		}
		if (value > 1f)
		{
			component.pointerScreenPosition = vector2;
		}
		if (pointer.gestureUp)
		{
			handleSlidableFinalize(component, component.value);
			session.send(new SlidableFinalizePacket
			{
				slidable = component,
				percent = component.value
			});
			stopInteraction(component.gameObject);
			cursorVisible.changeState(CursorVisibleState.VirtualVisible);
			controllerEndInteraction();
		}
	}

	private void handleSlidableStart(Slidable slidable)
	{
		PineFmod.playOneShotSoundAttached(slidable.startSound, slidable.gameObject);
	}

	private void handleSlidableInteraction(Slidable slidable, float percent)
	{
		slidable.backgroundUpdate = false;
		Vector3 position = slidable.transform.position;
		float value = slidable.value;
		Vector3 positionForPercent = slidable.getPositionForPercent(percent);
		slidable.setAtPercent(percent);
		bool flag = (double)Vector3.Distance(position, positionForPercent) > 1E-06;
		callOrDeferOnSlidableMoved(slidable, MoveEvent.Moved);
		slidable.idleFrames += ((!flag) ? 1 : (-slidable.idleFrames));
		if (slidable.idleFramesToStopMoveSound >= 0 && slidable.idleFrames > slidable.idleFramesToStopMoveSound)
		{
			PineFmod.stop(slidable.soundEmitter);
		}
		else if (!PineFmod.isPlaying(slidable.soundEmitter))
		{
			PineFmod.play(slidable.soundEmitter);
		}
		if (slidable.playSnapPointSoundWhileDragging)
		{
			bool num = value == 0f || value == 1f;
			float value2 = slidable.value;
			bool flag2 = value2 == 0f || value2 == 1f;
			bool num2 = !num && flag2;
			float num3 = 1f / (float)(slidable.additionalSnapPointCount + 1);
			int num4 = Mathf.FloorToInt(value / num3);
			if (value == 1f)
			{
				num4--;
			}
			int num5 = Mathf.FloorToInt(slidable.value / num3);
			if (slidable.value == 1f)
			{
				num5--;
			}
			if (num2 || num4 != num5)
			{
				PineFmod.playOneShotSoundAttached(slidable.snapPointSound, slidable.gameObject);
			}
		}
	}

	private void handleSlidableCancel(Slidable slidable)
	{
		float value = slidable.value;
		handleSlidableFinalize(slidable, value);
	}

	private void handleSlidableFinalize(Slidable slidable, float percent)
	{
		slidable.setAtPercent(percent);
		callOrDeferOnSlidableMoved(slidable, MoveEvent.Released);
		if (slidable.snapMode == Slidable.SnapMode.DontSnap)
		{
			PineFmod.playOneShotSoundAttached(slidable.endSound, slidable.gameObject);
			PineFmod.stop(slidable.soundEmitter);
		}
		else
		{
			PineFmod.playOrContinue(slidable.soundEmitter);
			slidable.currentSnapStartPercent = percent;
			slidable.backgroundUpdate = true;
		}
	}

	private void handleSlidableBackground(Slidable slidable, float dt)
	{
		Vector3 positionForPercent = slidable.getPositionForPercent(slidable.currentSnapStartPercent);
		slidable.transform.position = positionForPercent;
		float num = (float)((slidable.snapMode == Slidable.SnapMode.ToClosestSnapPoint) ? slidable.closestSnapPointIndex : slidable.snapPointIndex) / (float)(slidable.additionalSnapPointCount + 1);
		Vector3 positionForPercent2 = slidable.getPositionForPercent(num);
		float num2 = Vector3.Distance(slidable.transform.position, positionForPercent2) / slidable.segment.magnitude;
		float num3 = slidable.snapAnimationDuration * num2;
		bool flag = num3 == 0f;
		if (num3 > 0f)
		{
			float num4 = Mathf.Clamp01(slidable.backgroundTime / num3);
			float atPercent = Mathf.Lerp(slidable.currentSnapStartPercent, num, num4);
			slidable.setAtPercent(atPercent);
			flag = num4 >= 1f;
		}
		if (flag)
		{
			PineFmod.stop(slidable.soundEmitter);
			PineFmod.playOneShotSoundAttached(slidable.snapPointSound, slidable.gameObject);
			PineFmod.playOneShotSoundAttached(slidable.endSound, slidable.gameObject);
			slidable.backgroundUpdate = false;
		}
		callOrDeferOnSlidableMoved(slidable, flag ? MoveEvent.Snapped : MoveEvent.Moved);
	}

	private void handleSlidableGraph(Pointer pointer)
	{
		GameObject target = pointer.context.target;
		if (target == null || !target.TryGetComponent<SlidableGraphPiece>(out var piece))
		{
			return;
		}
		SlidableGraph graph = piece.graph;
		if (graph == null)
		{
			return;
		}
		Transform transform = playerCamera.transform;
		if (controlMode.current == ControlMode.VR)
		{
			transform = vr.getControllerForId(pointer.gestureFingerId).transform;
			if (pointers.Find((Pointer ptr) => ptr.context.interactionSessionId == piece.sessionId && ptr != pointer) != null)
			{
				return;
			}
		}
		if (pointer.context.interactionSessionId != piece.sessionId)
		{
			piece.sessionId = pointer.context.interactionSessionId;
			graph.lastSyncedPosition = piece.transform.position;
			piece.anchor = transform;
			piece.initialLocalHitPosition = piece.transform.InverseTransformPoint(pointer.context.targetHitPoint);
			piece.initialPosition = piece.transform.position;
			piece.initialAnchorWorldPoint = pointer.context.targetHitPoint;
			piece.anchorSpaceDragPoint = transform.InverseTransformPoint(pointer.context.targetHitPoint);
			if (graph.tryGetNode(piece, out var node))
			{
				calculateSlidableGraphNodeDragData(graph, piece, node);
			}
			startInteraction(piece.gameObject);
			controllerStartInteraction(pointer);
			handleSlidableGraphStart(piece);
			session.send(new SlidableGraphStartPacket
			{
				slidableGraphPiece = piece
			});
		}
		SlidableGraph.Event? obj = null;
		SlidableGraph.Edge edge;
		if (graph.tryGetNode(piece, out var node2))
		{
			obj = handleInNodeDrag(graph, piece, node2, pointer);
		}
		else if (graph.tryGetEdge(piece, out edge))
		{
			obj = handleOnEdgeDrag(graph, piece, edge, pointer);
		}
		else
		{
			UnityEngine.Debug.LogError(string.Format("{0} invalid state detected: Piece '{1}' is not in node or on edge.", "SlidableGraph", piece), piece);
		}
		if (obj.HasValue)
		{
			SlidableGraph.Edge edge2 = graph.getEdge(piece);
			int num = graph.nodes.IndexOf(edge2.startNode);
			int num2 = graph.nodes.IndexOf(edge2.endNode);
			float pieceEdgePercentage = UnityUtils.inverseLerp(edge2.startPoint, edge2.endPoint, piece.currentLinearPosition);
			handleSlidableGraphInteraction(piece, num, num2, pieceEdgePercentage, obj.Value);
			session.send(new SlidableGraphInteractionPacket
			{
				slidableGraphPiece = piece,
				pieceEdgePercentage = pieceEdgePercentage,
				startNodeIndex = (short)num,
				endNodeIndex = (short)num2,
				graphEvent = obj.Value
			});
			graph.lastSyncedPosition = piece.transform.position;
		}
		if (pointer.gestureUp)
		{
			SlidableGraph.Edge edge3 = graph.getEdge(piece.currentEdgeStartNode, piece.currentEdgeEndNode);
			int num3 = graph.nodes.IndexOf(edge3.startNode);
			int num4 = graph.nodes.IndexOf(edge3.endNode);
			float pieceEdgePercentage2 = UnityUtils.inverseLerp(edge3.startPoint, edge3.endPoint, piece.currentLinearPosition);
			handleSlidableGraphFinalize(piece, num3, num4, pieceEdgePercentage2);
			session.send(new SlidableGraphFinalizePacket
			{
				slidableGraphPiece = piece,
				startNodeIndex = (short)num3,
				endNodeIndex = (short)num4,
				pieceEdgePercentage = pieceEdgePercentage2
			});
			stopInteraction(piece.gameObject);
			cursorVisible.changeState(CursorVisibleState.VirtualVisible);
			controllerEndInteraction();
		}
	}

	private void handleSlidableGraphStart(SlidableGraphPiece piece)
	{
		callOrDeferOnSlidableGraphBegin(piece, new SlidableGraph.OnPieceInteraction(piece.graph, piece));
		PineFmod.playOneShotSoundAttached(piece.graph.startSound, piece.gameObject);
	}

	private void handleSlidableGraphInteraction(SlidableGraphPiece piece, int startNodeIndex, int endNodeIndex, float pieceEdgePercentage, SlidableGraph.Event graphEvent)
	{
		SlidableGraph graph = piece.graph;
		GameObject gameObject = graph.nodes[startNodeIndex];
		GameObject gameObject2 = graph.nodes[endNodeIndex];
		SlidableGraph.Edge edge = graph.getEdge(gameObject, gameObject2);
		moveSlidableGraphPiece(graph, piece, edge, pieceEdgePercentage);
		switch (graphEvent)
		{
		case SlidableGraph.Event.MovedOnEdge:
			callOrDeferOnSlidableGraphMovedOnEdge(piece, new SlidableGraph.OnEdge(graph, piece, edge, pieceEdgePercentage));
			break;
		case SlidableGraph.Event.ArrivedToNode:
		{
			GameObject toNode = ((pieceEdgePercentage < 0.5f) ? gameObject : gameObject2);
			callOrDeferOnSlidableGraphArrivedToNode(piece, new SlidableGraph.ToNode(graph, piece, edge, toNode));
			break;
		}
		case SlidableGraph.Event.ArrivedToEdge:
			callOrDeferOnSlidableGraphArrivedToEdge(piece, new SlidableGraph.ToEdge(graph, piece, gameObject, edge));
			break;
		default:
			UnityEngine.Debug.LogError(string.Format("Invalid '{0}' value: {1}", "graphEvent", graphEvent));
			break;
		}
	}

	private void handleSlidableGraphCancel(SlidableGraphPiece piece)
	{
		SlidableGraph graph = piece.graph;
		SlidableGraph.Edge edge = graph.getEdge(piece);
		int startNodeIndex = graph.nodes.IndexOf(edge.startNode);
		int endNodeIndex = graph.nodes.IndexOf(edge.endNode);
		float pieceEdgePercentage = UnityUtils.inverseLerp(edge.startPoint, edge.endPoint, piece.currentLinearPosition);
		handleSlidableGraphFinalize(piece, startNodeIndex, endNodeIndex, pieceEdgePercentage);
	}

	private void handleSlidableGraphFinalize(SlidableGraphPiece piece, int startNodeIndex, int endNodeIndex, float pieceEdgePercentage)
	{
		SlidableGraph graph = piece.graph;
		GameObject startNode = graph.nodes[startNodeIndex];
		GameObject endNode = graph.nodes[endNodeIndex];
		SlidableGraph.Edge edge = graph.getEdge(startNode, endNode);
		piece.currentEdgeStartNode = edge.startNode;
		piece.currentEdgeEndNode = edge.endNode;
		piece.currentEdgePercent = pieceEdgePercentage;
		piece.transform.position = edge.getPoint(pieceEdgePercentage);
		if (graph.useSnapping)
		{
			PineFmod.playOrContinue(graph.soundEmitter);
			piece.currentSnapStartPercent = pieceEdgePercentage;
			piece.currentSnapStartNodeIndex = (short)startNodeIndex;
			piece.currentSnapEndNodeIndex = (short)endNodeIndex;
			graph.piecesList.ForEach(delegate(SlidableGraphPiece p)
			{
				p.backgroundTime = 0f;
				p.backgroundUpdate = true;
				p.isBackgroundUpdatePiece = false;
			});
			piece.wasReleasedInNode = graph.tryGetNode(piece, out var _);
			piece.isBackgroundUpdatePiece = true;
		}
		else
		{
			PineFmod.playOneShotSoundAttached(graph.endSound, piece.gameObject);
			PineFmod.stop(graph.soundEmitter);
			callOrDeferOnSlidableGraphReleased(piece, new SlidableGraph.OnPieceInteraction(graph, piece));
		}
	}

	private void handleSlidableGraphBackground(SlidableGraphPiece piece, float dt)
	{
		if (!piece.isBackgroundUpdatePiece)
		{
			return;
		}
		SlidableGraph graph = piece.graph;
		GameObject startNode = graph.nodes[piece.currentSnapStartNodeIndex];
		GameObject endNode = graph.nodes[piece.currentSnapEndNodeIndex];
		SlidableGraph.Edge edge = graph.getEdge(startNode, endNode);
		Vector3 a = edge.startPoint + Mathf.Clamp01(piece.currentSnapStartPercent) * edge.direction;
		piece.currentEdgeStartNode = edge.startNode;
		piece.currentEdgeEndNode = edge.endNode;
		piece.currentEdgePercent = piece.currentSnapStartPercent;
		float num = Vector3.Distance(piece.currentLinearPosition, edge.startPoint);
		float num2 = Vector3.Distance(piece.currentLinearPosition, edge.endPoint);
		SlidableGraphPiece piece2;
		SlidableGraphPiece piece3;
		GameObject gameObject = ((!(num < num2)) ? ((!graph.tryGetPiece(edge.endNode, out piece2) || piece2 == piece) ? edge.endNode : edge.startNode) : ((!graph.tryGetPiece(edge.startNode, out piece3) || piece3 == piece) ? edge.startNode : edge.endNode));
		float snapAnimationDuration = graph.snapAnimationDuration;
		bool flag = snapAnimationDuration == 0f;
		if (snapAnimationDuration > 0f)
		{
			float num3 = Mathf.Clamp01(piece.backgroundTime / snapAnimationDuration);
			GameObject gameObject2 = ((gameObject == edge.startNode) ? edge.endNode : edge.startNode);
			Vector3 value = Vector3.Lerp(a, gameObject.transform.position, num3);
			piece.currentEdgeStartNode = edge.startNode;
			piece.currentEdgeEndNode = edge.endNode;
			piece.currentEdgePercent = UnityUtils.inverseLerp(edge.startPoint, edge.endPoint, value);
			float t = UnityUtils.inverseLerp(gameObject.transform.position, gameObject2.transform.position, piece.currentLinearPosition);
			piece.transform.position = edge.getPoint(t, gameObject == edge.endNode);
			flag = num3 >= 1f;
		}
		if (flag)
		{
			PineFmod.stop(graph.soundEmitter);
			PineFmod.playOneShotSoundAttached(graph.endSound, graph.gameObject);
			graph.piecesList.ForEach(delegate(SlidableGraphPiece p)
			{
				p.backgroundUpdate = false;
			});
			if (!piece.wasReleasedInNode)
			{
				callOrDeferOnSlidableGraphArrivedToNode(piece, new SlidableGraph.ToNode(graph, piece, edge, gameObject));
			}
			callOrDeferOnSlidableGraphReleased(piece, new SlidableGraph.OnPieceInteraction(graph, piece));
		}
		else
		{
			float percent = UnityUtils.inverseLerp(edge.startPoint, edge.endPoint, piece.currentLinearPosition);
			callOrDeferOnSlidableGraphMovedOnEdge(piece, new SlidableGraph.OnEdge(graph, piece, edge, percent));
		}
	}

	private SlidableGraph.Event? handleInNodeDrag(SlidableGraph graph, SlidableGraphPiece piece, GameObject node, Pointer pointer)
	{
		if (!graph.tryGetNeighbours(node, out var neighbours))
		{
			return null;
		}
		if (!graph.isFreeCamera)
		{
			float num = (isVR() ? graph.vrSpeedMultiplier : (Controller.isActive() ? graph.controllerSpeedMultiplier : 1f));
			graph.nodeScreenMovement += pointer.gestureMovementScreen * num;
			if (graph.nodeScreenMovement.normalized == Vector3.zero)
			{
				return null;
			}
		}
		float num2 = float.NegativeInfinity;
		GameObject gameObject = null;
		SlidableGraph.Edge edge = null;
		float num3 = 0f;
		foreach (GameObject item in neighbours)
		{
			if ((graph.occupiedNodeBlocksEdges && graph.tryGetPiece(item, out var _)) || !graph.tryGetEdge(node, item, out var edge2) || (graph.isEdgeBlockedPredicate != null && graph.isEdgeBlockedPredicate(node, item, piece)))
			{
				continue;
			}
			float lowerT = 0f;
			float higherT = 1f;
			if (graph.useCollision && piece.useCollision && !tryGetMovableInterval(graph, piece, edge2, out lowerT, out higherT))
			{
				continue;
			}
			Vector3 start = edge2.startPoint + lowerT * edge2.direction;
			Vector3 end = edge2.startPoint + higherT * edge2.direction;
			UnityEngine.Debug.DrawLine(start, end, Color.magenta);
			if (graph.isFreeCamera)
			{
				Vector3 vector = piece.anchor.TransformPoint(piece.anchorSpaceDragPoint);
				Vector3 vector2 = Maths.closestPointOnLine(vector, piece.initialAnchorWorldPoint, edge2.direction);
				float num4 = Vector3.Dot(edge2.direction.normalized, (vector - piece.initialAnchorWorldPoint).normalized);
				if (num4 > num2)
				{
					num2 = num4;
					gameObject = item;
					edge = edge2;
					Vector3 vector3 = vector2 - piece.initialAnchorWorldPoint;
					num3 = Maths.vectorProjectionPercent(piece.initialPosition + vector3 - edge2.startPoint, edge2.direction);
					num3 = Mathf.Clamp(num3, lowerT, higherT);
				}
			}
			else
			{
				Vector3 vector4 = playerCamera.WorldToScreenPoint(node.transform.position);
				Vector3 onVector = playerCamera.WorldToScreenPoint(item.transform.position) - vector4;
				float num5 = Vector3.Dot(onVector.normalized, graph.nodeScreenMovement.normalized);
				if (num5 > num2)
				{
					num2 = num5;
					gameObject = item;
					edge = edge2;
					num3 = Mathf.Clamp(Maths.vectorProjectionPercent(graph.nodeScreenMovement, onVector), lowerT, higherT);
				}
			}
		}
		if (gameObject != null && num3 > 0.001f)
		{
			if (graph.isFreeCamera)
			{
				SlidableGraph.Edge edge3 = graph.getEdge(piece.currentEdgeStartNode, piece.currentEdgeEndNode);
				bool flag = edge3.startNode == edge.startNode && edge3.endNode == edge.endNode;
				bool flag2 = edge3.startNode == edge.endNode && edge3.endNode == edge.startNode;
				if (!(flag || flag2))
				{
					if (edge3.startNode == node)
					{
						float num6 = UnityUtils.inverseLerp(edge3.startPoint, edge3.endPoint, piece.currentLinearPosition);
						num6 -= 0.05f;
						if (num6 > 0f)
						{
							edge = edge3;
							num3 = Mathf.Clamp01(num6);
						}
						else
						{
							flag = true;
						}
					}
					else
					{
						float num7 = UnityUtils.inverseLerp(edge3.startPoint, edge3.endPoint, piece.currentLinearPosition);
						num7 += 0.05f;
						if (num7 < 1f)
						{
							edge = edge3;
							num3 = Mathf.Clamp01(num7);
						}
						else
						{
							flag2 = true;
						}
					}
				}
				if (flag)
				{
					float currentEdgePercent = piece.currentEdgePercent;
					float num8 = Mathf.Clamp(num3 - currentEdgePercent, -0.05f, 0.05f);
					num3 = currentEdgePercent + num8;
				}
				else if (flag2)
				{
					float num9 = 1f - piece.currentEdgePercent;
					float num10 = Mathf.Clamp(num3 - num9, -0.05f, 0.05f);
					num3 = num9 + num10;
				}
			}
			moveSlidableGraphPiece(graph, piece, edge, num3);
			bool flag3 = Vector3.Distance(piece.currentLinearPosition, node.transform.position) < graph.nodeRadius;
			if (Vector3.Distance(piece.currentLinearPosition, gameObject.transform.position) < graph.nodeRadius)
			{
				calculateSlidableGraphNodeDragData(graph, piece, gameObject);
				return SlidableGraph.Event.ArrivedToNode;
			}
			return (!flag3) ? SlidableGraph.Event.ArrivedToEdge : SlidableGraph.Event.MovedOnEdge;
		}
		return null;
	}

	private SlidableGraph.Event? handleOnEdgeDrag(SlidableGraph graph, SlidableGraphPiece piece, SlidableGraph.Edge edge, Pointer pointer)
	{
		float lowerT = 0f;
		float higherT = 1f;
		if (graph.useCollision && piece.useCollision && !tryGetMovableInterval(graph, piece, edge, out lowerT, out higherT))
		{
			return null;
		}
		Vector3 start = edge.startPoint + lowerT * edge.direction;
		Vector3 end = edge.startPoint + higherT * edge.direction;
		UnityEngine.Debug.DrawLine(start, end, Color.magenta);
		Vector3 position = edge.startNode.transform.position;
		Vector3 position2 = edge.endNode.transform.position;
		float num;
		if (graph.isFreeCamera)
		{
			Vector3 vector = Maths.closestPointOnLine(piece.anchor.TransformPoint(piece.anchorSpaceDragPoint), piece.initialAnchorWorldPoint, edge.direction) - piece.initialAnchorWorldPoint;
			num = Maths.vectorProjectionPercent(piece.initialPosition + vector - edge.startPoint, edge.direction);
			float num2 = Mathf.Clamp(num - piece.currentEdgePercent, -0.05f, 0.05f);
			num = piece.currentEdgePercent + num2;
		}
		else
		{
			Vector3 vector2 = playerCamera.WorldToScreenPoint(position);
			Vector3 vector3 = playerCamera.WorldToScreenPoint(position2);
			Vector3 onVector = vector3 - vector2;
			float t = Maths.vectorProjectionPercent(piece.currentLinearPosition - edge.startPoint, edge.direction);
			float num3 = (isVR() ? graph.vrSpeedMultiplier : (Controller.isActive() ? graph.controllerSpeedMultiplier : 1f));
			num = Maths.vectorProjectionPercent(Vector3.Lerp(vector2, vector3, t) + pointer.gestureMovementScreen * num3 - vector2, onVector);
		}
		moveSlidableGraphPiece(graph, piece, edge, Mathf.Clamp(num, lowerT, higherT));
		bool flag = Vector3.Distance(piece.currentLinearPosition, position) < graph.nodeRadius;
		bool flag2 = Vector3.Distance(piece.currentLinearPosition, position2) < graph.nodeRadius;
		if (!flag && !flag2)
		{
			return SlidableGraph.Event.MovedOnEdge;
		}
		calculateSlidableGraphNodeDragData(graph, piece, flag ? edge.startNode : edge.endNode, edge);
		return SlidableGraph.Event.ArrivedToNode;
	}

	private void moveSlidableGraphPiece(SlidableGraph graph, SlidableGraphPiece piece, SlidableGraph.Edge edge, float percent)
	{
		GameObject currentEdgeStartNode = piece.currentEdgeStartNode;
		GameObject currentEdgeEndNode = piece.currentEdgeEndNode;
		float currentEdgePercent = piece.currentEdgePercent;
		Vector3 position = piece.transform.position;
		piece.currentEdgeStartNode = edge.startNode;
		piece.currentEdgeEndNode = edge.endNode;
		piece.currentEdgePercent = percent;
		piece.transform.position = edge.getPoint(UnityUtils.inverseLerp(edge.startPoint, edge.endPoint, piece.currentLinearPosition));
		foreach (SlidableGraphPiece pieces in graph.piecesList)
		{
			if (graph.useCollision && piece.useCollision && pieces.useCollision && !object.Equals(pieces, piece) && Vector3.Distance(pieces.currentLinearPosition, piece.currentLinearPosition) <= pieces.colliderRadius + piece.colliderRadius)
			{
				UnityEngine.Debug.Log($"Collision detected between pieces '{piece}' and '{pieces}'. Reverting position...", pieces);
				piece.currentEdgeStartNode = currentEdgeStartNode;
				piece.currentEdgeEndNode = currentEdgeEndNode;
				piece.currentEdgePercent = currentEdgePercent;
				piece.transform.position = position;
				break;
			}
		}
		bool flag = (double)Vector3.Distance(position, piece.transform.position) > 1E-06;
		graph.idleFrames += ((!flag) ? 1 : (-graph.idleFrames));
		if (graph.idleFramesToStopMoveSound >= 0 && graph.idleFrames > graph.idleFramesToStopMoveSound)
		{
			PineFmod.stop(graph.soundEmitter);
		}
		else
		{
			PineFmod.playOrContinue(graph.soundEmitter);
		}
	}

	private void calculateSlidableGraphNodeDragData(SlidableGraph graph, SlidableGraphPiece piece, GameObject node, SlidableGraph.Edge edge = null)
	{
		if (graph.isFreeCamera)
		{
			Vector3 position = piece.transform.position;
			piece.transform.position = node.transform.position;
			piece.initialPosition = piece.transform.position;
			piece.initialAnchorWorldPoint = piece.transform.TransformPoint(piece.initialLocalHitPosition);
			piece.transform.position = position;
		}
		else
		{
			Vector3 vector = playerCamera.WorldToScreenPoint(piece.currentLinearPosition);
			Vector3 vector2 = playerCamera.WorldToScreenPoint(node.transform.position);
			graph.nodeScreenMovement = vector - vector2;
		}
	}

	private bool tryGetMovableInterval(SlidableGraph graph, SlidableGraphPiece piece, SlidableGraph.Edge edge, out float lowerT, out float higherT)
	{
		lowerT = 0f;
		higherT = 1f;
		if (!piece.useCollision)
		{
			return true;
		}
		float num = Maths.vectorProjectionPercent(piece.currentLinearPosition - edge.startPoint, edge.direction);
		bool flag = false;
		foreach (SlidableGraphPiece pieces in graph.piecesList)
		{
			if (!object.Equals(pieces, piece) && pieces.useCollision && tryGetCollisionInterval(piece, pieces, edge, out var t, out var t2))
			{
				flag = true;
				float num2 = Mathf.Min(t, t2);
				float num3 = Mathf.Max(t, t2);
				if (num2 < num && num < num3)
				{
					lowerT = (higherT = num);
					return false;
				}
				if (num <= num2 && num2 < higherT)
				{
					higherT = num2;
				}
				else if (num3 <= num && num3 > lowerT)
				{
					lowerT = num3;
				}
			}
		}
		if (flag)
		{
			lowerT += 0.001f;
			higherT -= 0.001f;
		}
		return true;
	}

	private bool tryGetCollisionInterval(SlidableGraphPiece piece, SlidableGraphPiece otherPiece, SlidableGraph.Edge edge, out float t1, out float t2)
	{
		float colliderRadius = piece.colliderRadius;
		float colliderRadius2 = otherPiece.colliderRadius;
		float num = (colliderRadius + colliderRadius2) * (colliderRadius + colliderRadius2);
		Vector3 direction = edge.direction;
		Vector3 vector = edge.startPoint - otherPiece.currentLinearPosition;
		float num2 = Vector3.Dot(direction, direction);
		float num3 = 2f * Vector3.Dot(direction, vector);
		float num4 = Vector3.Dot(vector, vector) - num;
		float num5 = num3 * num3 - 4f * num2 * num4;
		if (num2 == 0f || num5 <= 0f)
		{
			t1 = (t2 = 0f);
			return false;
		}
		float num6 = Mathf.Sqrt(num5);
		t1 = (0f - num3 + num6) / (2f * num2);
		t2 = (0f - num3 - num6) / (2f * num2);
		if ((t1 < 0f && t2 < 0f) || (t1 > 1f && t2 > 1f))
		{
			t1 = (t2 = 0f);
			return false;
		}
		float num7 = t1;
		if (num7 >= 0f && num7 <= 1f)
		{
			UnityEngine.Debug.DrawLine(otherPiece.currentLinearPosition, edge.startPoint + t1 * direction, Color.green);
		}
		num7 = t2;
		if (num7 >= 0f && num7 <= 1f)
		{
			UnityEngine.Debug.DrawLine(otherPiece.currentLinearPosition, edge.startPoint + t2 * direction, Color.green);
		}
		return true;
	}

	private void handleHorizontalSlider(Pointer pointer)
	{
		HorizontalSlider component = pointer.context.target.GetComponent<HorizontalSlider>();
		if (component.sessionId != pointer.context.interactionSessionId)
		{
			component.sessionId = pointer.context.interactionSessionId;
			component.controllerOffset = Vector3.zero;
			if (Controller.isActive() && component.plane.Raycast(pointer.gestureFirstRay, out var enter))
			{
				Vector3 point = pointer.gestureFirstRay.GetPoint(enter);
				component.controllerOffset = point - component.transform.position;
			}
			startInteraction(component.gameObject);
			controllerStartInteraction(pointer, virtualHiddenButMovable: true);
			handleHorizontalSliderStart(component);
			session.send(new HorizontalSliderStartPacket
			{
				horizontalSlider = component
			});
		}
		component.initPlane();
		Vector3 vector = Vector3.zero;
		float change = 0f;
		Vector3 vector2 = ((component.areaLimitsPlaneOrigin != null) ? component.areaLimitsPlaneOrigin.position : component.originalPosition);
		if (component.plane.Raycast(pointer.gestureRayPrevious, out var enter2) && component.plane.Raycast(pointer.gestureRay, out var enter3))
		{
			Vector3 point2 = pointer.gestureRayPrevious.GetPoint(enter2);
			Vector3 point3 = pointer.gestureRay.GetPoint(enter3);
			change = Vector3.Distance(point3, point2);
			Vector3 lhs = point3 - vector2 - component.controllerOffset;
			Vector3 vector3 = ((component.areaLimitsPlaneOrigin != null) ? component.areaLimitsPlaneOrigin.right : component.worldRight);
			Vector3 vector4 = ((component.areaLimitsPlaneOrigin != null) ? component.areaLimitsPlaneOrigin.up : component.worldUp);
			float num = Vector3.Dot(lhs, vector3);
			float num2 = Vector3.Dot(lhs, vector4);
			if (component.type == HorizontalSlider.Type.Circular)
			{
				float num3 = component.transform.lossyScale.magnitude / component.baseScale.magnitude;
				float maxLength = component.circularMaxRadius * num3;
				vector = Vector3.ClampMagnitude(vector3 * num + vector4 * num2, maxLength);
			}
			else if (component.type == HorizontalSlider.Type.Rectangular)
			{
				Vector3 vector5 = Vector3.Scale(b: new Vector3(component.transform.lossyScale.x / component.baseScale.x, component.transform.lossyScale.y / component.baseScale.y, component.transform.lossyScale.z / component.baseScale.z), a: component.rectangularMaxSize);
				num = Mathf.Clamp(num, 0f - vector5.x, vector5.x);
				num2 = Mathf.Clamp(num2, 0f - vector5.y, vector5.y);
				vector = vector3 * num + vector4 * num2;
			}
		}
		Vector3 vector6 = component.transform.parent.InverseTransformVector(vector);
		handleHorizontalSliderInteraction(component, vector6, change);
		session.send(new HorizontalSliderInteractionPacket
		{
			horizontalSlider = component,
			offset = vector6,
			change = change
		});
		if (pointer.gestureUp)
		{
			handleHorizontalSliderFinalize(component, vector6);
			session.send(new HorizontalSliderFinalizePacket
			{
				horizontalSlider = component,
				offset = vector6
			});
			stopInteraction(component.gameObject);
			controllerEndInteraction();
		}
	}

	private void handleHorizontalSliderStart(HorizontalSlider horizontalSlider)
	{
		horizontalSlider.initPlane();
		PineFmod.playOneShotSoundAttached(horizontalSlider.startSound, horizontalSlider.gameObject);
	}

	private void handleHorizontalSliderInteraction(HorizontalSlider horizontalSlider, Vector3 localOffset, float change)
	{
		horizontalSlider.offset = localOffset;
		horizontalSlider.transform.localPosition = horizontalSlider.originalLocalPosition + localOffset;
		bool num = (double)change > 1E-06;
		if (num)
		{
			callOrDeferOnHorizontalSliderMoved(horizontalSlider, horizontalSlider.getNearestInterestPoint(), MoveEvent.Moved);
		}
		if (num)
		{
			PineFmod.playOrContinue(horizontalSlider.soundEmitter);
			horizontalSlider.soundStopTimer = 0f;
		}
		else if (horizontalSlider.soundStopTimer >= 0.1f)
		{
			PineFmod.stop(horizontalSlider.soundEmitter);
		}
		else
		{
			horizontalSlider.soundStopTimer += Time.deltaTime;
		}
	}

	private void handleHorizontalSliderCancel(HorizontalSlider horizontalSlider)
	{
		Vector3 offset = horizontalSlider.offset;
		handleHorizontalSliderFinalize(horizontalSlider, offset);
	}

	private void handleHorizontalSliderFinalize(HorizontalSlider horizontalSlider, Vector3 offset)
	{
		horizontalSlider.transform.localPosition = horizontalSlider.originalLocalPosition + offset;
		callOrDeferOnHorizontalSliderMoved(horizontalSlider, horizontalSlider.getNearestInterestPoint(), MoveEvent.Released);
		if (horizontalSlider.snapBack)
		{
			PineFmod.playOrContinue(horizontalSlider.soundEmitter);
			horizontalSlider.currentSnapStartOffset = horizontalSlider.offset;
			horizontalSlider.backgroundUpdate = true;
		}
		else
		{
			PineFmod.stop(horizontalSlider.soundEmitter);
			PineFmod.playOneShotSoundAttached(horizontalSlider.endSound, horizontalSlider.gameObject);
		}
	}

	private void handleHorizontalSliderBackground(HorizontalSlider horizontalSlider, float dt)
	{
		float num = Mathf.Clamp01(horizontalSlider.backgroundTime / 0.25f);
		horizontalSlider.offset = Vector3.Lerp(horizontalSlider.currentSnapStartOffset, Vector3.zero, num);
		horizontalSlider.transform.localPosition = horizontalSlider.originalLocalPosition + horizontalSlider.offset;
		bool num2 = num >= 1f;
		if (num2)
		{
			PineFmod.stop(horizontalSlider.soundEmitter);
			PineFmod.playOneShotSoundAttached(horizontalSlider.endSound, horizontalSlider.gameObject);
			horizontalSlider.backgroundUpdate = false;
		}
		MoveEvent moveEvent = (num2 ? MoveEvent.Snapped : MoveEvent.Moved);
		callOrDeferOnHorizontalSliderMoved(horizontalSlider, horizontalSlider.getNearestInterestPoint(), moveEvent);
	}

	private void handleTurnable(Pointer pointer)
	{
		Turnable component = pointer.context.target.GetComponent<Turnable>();
		if (component.sessionId != pointer.context.interactionSessionId)
		{
			component.sessionId = pointer.context.interactionSessionId;
			component.interactionDuration = 0f;
			startInteraction(component.gameObject);
			controllerStartInteraction(pointer);
			handleTurnableStart(component);
			session.send(new TurnableStartPacket
			{
				turnable = component
			});
		}
		float num = 1000f * component.speed;
		float num2 = pointer.gestureMovementViewport.x * component.screenAxis.x + pointer.gestureMovementViewport.y * component.screenAxis.y;
		num2 *= num;
		handleTurnableInteraction(component, num2);
		session.send(new TurnableInteractionPacket
		{
			turnable = component,
			rotationChange = num2
		});
		component.interactionDuration += Time.deltaTime;
		if (pointer.gestureUp)
		{
			if (component.interactionDuration < shortPressTime)
			{
				TurnableAnnotation annotation = pointer.context.targetAnnotation as TurnableAnnotation;
				handleTurnableAdvance(component, annotation);
				session.send(new TurnableAdvancePacket
				{
					turnable = component,
					annotation = annotation
				});
			}
			else
			{
				float turnableSnapAngle = getTurnableSnapAngle(component);
				handleTurnableFinalize(component, turnableSnapAngle);
				session.send(new TurnableFinalizePacket
				{
					turnable = component,
					rotation = turnableSnapAngle
				});
			}
			stopInteraction(component.gameObject);
			controllerEndInteraction();
		}
	}

	private void handleTurnableStart(Turnable turnable)
	{
		PineFmod.playOneShotSoundAttached(turnable.startSound, turnable.gameObject);
	}

	private void handleTurnableInteraction(Turnable turnable, float change)
	{
		turnable.backgroundUpdate = false;
		turnable.lastValue = turnable.value;
		turnable.currentRotation += change;
		if (turnable.useAngleLimits)
		{
			turnable.currentRotation = Mathf.Clamp(turnable.currentRotation, turnable.minAngle, turnable.maxAngle);
		}
		syncTurnableView(turnable);
		if (turnable.hasValueChanged)
		{
			PineFmod.playOneShotSoundAttached(turnable.soundTurnHotspot, turnable.gameObject);
		}
		if (change != 0f)
		{
			PineFmod.playOrContinue(turnable.soundEmitter);
		}
		else
		{
			PineFmod.stop(turnable.soundEmitter);
		}
		callOrDeferOnTurnableMoved(turnable, MoveEvent.Moved);
	}

	private void handleTurnableAdvance(Turnable turnable, TurnableAnnotation annotation)
	{
		int num = turnable.clickDirection;
		if (annotation != null)
		{
			num = annotation.clickDirectionOverride;
		}
		turnable.rotationGoal = getTurnableSnapAngle(turnable) + (float)num * turnable.stepAngle;
		if (turnable.useAngleLimits)
		{
			turnable.rotationGoal = Mathf.Clamp(turnable.rotationGoal, turnable.minAngle, turnable.maxAngle);
		}
		turnable.backgroundUpdate = true;
		PineFmod.playOrContinue(turnable.soundEmitter);
		callOrDeferOnTurnableMoved(turnable, MoveEvent.Released);
	}

	private void handleTurnableCancel(Turnable turnable)
	{
		float turnableSnapAngle = getTurnableSnapAngle(turnable);
		handleTurnableFinalize(turnable, turnableSnapAngle);
	}

	private void handleTurnableFinalize(Turnable turnable, float rotationGoal)
	{
		if (turnable.useHotspots)
		{
			PineFmod.playOrContinue(turnable.soundEmitter);
			turnable.rotationGoal = rotationGoal;
			turnable.backgroundUpdate = true;
		}
		else
		{
			PineFmod.playOneShotSoundAttached(turnable.endSound, turnable.gameObject);
			PineFmod.stop(turnable.soundEmitter);
			turnable.currentRotation = rotationGoal;
			syncTurnableView(turnable);
		}
		callOrDeferOnTurnableMoved(turnable, MoveEvent.Released);
	}

	private void handleTurnableBackground(Turnable turnable, float dt)
	{
		turnable.lastValue = turnable.value;
		turnable.currentRotation = Mathf.MoveTowards(turnable.currentRotation, turnable.rotationGoal, dt * 200f);
		syncTurnableView(turnable);
		bool flag = turnable.currentRotation == turnable.rotationGoal;
		if (flag)
		{
			PineFmod.stop(turnable.soundEmitter);
			PineFmod.playOneShotSoundAttached(turnable.soundTurnHotspot, turnable.gameObject);
			PineFmod.playOneShotSoundAttached(turnable.endSound, turnable.gameObject);
			turnable.backgroundUpdate = false;
		}
		callOrDeferOnTurnableMoved(turnable, flag ? MoveEvent.Snapped : MoveEvent.Moved);
	}

	private void syncTurnableView(Turnable turnable)
	{
		if (turnable.type == TurnableType.Rotation)
		{
			if (turnable.rootTransform().TryGetComponent<Rigidbody>(out var component))
			{
				component.MoveRotation(turnable.rootTransform().parent.rotation * (turnable.originalRotation * Quaternion.Euler(turnable.worldAxis * turnable.currentRotation)));
			}
			else
			{
				turnable.rootTransform().localRotation = turnable.originalRotation * Quaternion.Euler(turnable.worldAxis * turnable.currentRotation);
			}
		}
		else if (turnable.type == TurnableType.UV && turnable.targetRenderer != null)
		{
			turnable.targetRenderer.material.SetTextureOffset("_BaseColorMap", new Vector2(0f, turnable.currentRotation / 360f));
			turnable.targetRenderer.material.SetTextureOffset("_DetailMap", new Vector2(0f, turnable.currentRotation / 360f));
		}
	}

	private float getTurnableSnapAngle(Turnable turnable)
	{
		if (!turnable.useHotspots)
		{
			return turnable.currentRotation;
		}
		int num = Mathf.RoundToInt((turnable.currentRotation - turnable.minAngle) / turnable.stepAngle);
		if (turnable.useAngleLimits)
		{
			num = Mathf.Clamp(num, 0, turnable.steps - 1);
		}
		return turnable.minAngle + (float)num * turnable.stepAngle;
	}

	private void handleDial(Pointer pointer)
	{
		Dial component = pointer.context.target.GetComponent<Dial>();
		bool flag = component.sessionId != pointer.context.interactionSessionId;
		if (flag)
		{
			component.sessionId = pointer.context.interactionSessionId;
			component.interactionDuration = 0f;
			component.currentControllerRotationSpeed = 0f;
			component.dialAudioTurnOffDelay = 0;
			component.dialControllerTimeAtZero = 0f;
			if (vr.isActive())
			{
				VRRig.Controller controllerForId = vr.getControllerForId(pointer.gestureFingerId);
				component.cursorViewPosLast = controllerForId.raycastDestinationIndicator.transform.position;
			}
			else
			{
				component.cursorViewPosLast = pointer.gesturePositionScreen;
			}
			foreach (LockArgument @lock in component.locks)
			{
				if (@lock.targetIndex == -1 && @lock.targetLock.nextValueIndex > 0)
				{
					@lock.targetLock.nextValueIndex--;
				}
			}
			startInteraction(component.gameObject);
			controllerStartInteraction(pointer);
			handleDialStart(component);
			session.send(new DialStartPacket
			{
				dial = component
			});
		}
		bool recalculateControllerDialDirection = flag && Controller.isActive() && component.controllerDialType == Dial.ControllerDialType.Horizontal;
		float num = calculateDialAngleChangeDelta(pointer, component, recalculateControllerDialDirection);
		DialAnnotation annotation = pointer.context.targetAnnotation as DialAnnotation;
		handleDialInteraction(component, num, annotation);
		session.send(new DialInteractionPacket
		{
			dial = component,
			angleChangeDelta = num,
			annotation = annotation
		});
		component.interactionDuration += Time.deltaTime;
		if (pointer.gestureUp)
		{
			if (component.interactionDuration < shortPressTime)
			{
				handleDialAdvance(component, annotation);
				session.send(new DialAdvancePacket
				{
					dial = component,
					annotation = annotation
				});
			}
			else
			{
				float dialSnapAngle = getDialSnapAngle(component);
				handleDialFinalize(component, dialSnapAngle);
				session.send(new DialFinalizePacket
				{
					dial = component,
					targetAngle = dialSnapAngle
				});
			}
			stopInteraction(component.gameObject);
			controllerEndInteraction();
		}
	}

	private void handleDialStart(Dial dial)
	{
		PineFmod.playOneShotSoundAttached(dial.startSound, dial.gameObject);
	}

	private void handleDialInteraction(Dial dial, float angleChangDelta, DialAnnotation annotation)
	{
		int num = 1;
		if (annotation != null)
		{
			num = annotation.dragDirectionOverride;
		}
		dial.backgroundUpdate = false;
		dial.lastValue = dial.value;
		dial.angleChange = angleChangDelta * (float)num;
		dial.currentAngle += angleChangDelta * (float)num;
		if (dial.useAngleLimits)
		{
			dial.currentAngle = Mathf.Clamp(dial.currentAngle, dial.minAngle, dial.maxAngle);
		}
		syncDialView(dial);
		if (dial.soundOnPoints && dial.hasValueChanged && (dial.soundOnEveryValue || dial.value % 5 == 0))
		{
			PineFmod.playOneShotSoundAttached(dial.soundTurnHotspot, dial.gameObject);
		}
		if (dial.angleChange != 0f)
		{
			PineFmod.playOrContinue(dial.soundEmitter);
			dial.dialAudioTurnOffDelay = 0;
		}
		else if (dial.dialAudioTurnOffDelay >= dial.soundTurnStopDelay)
		{
			PineFmod.stop(dial.soundEmitter);
		}
		else
		{
			dial.dialAudioTurnOffDelay++;
		}
		callOrDeferOnDialMoved(dial, MoveEvent.Moved);
	}

	private void handleDialAdvance(Dial dial, DialAnnotation annotation)
	{
		int num = dial.clickDirection;
		if (annotation != null)
		{
			num = annotation.clickDirectionOverride;
		}
		dial.targetAngle = getDialSnapAngle(dial) + (float)num * dial.stepAngle;
		if (dial.useAngleLimits)
		{
			dial.targetAngle = Mathf.Clamp(dial.targetAngle, dial.minAngle, dial.maxAngle);
		}
		dial.backgroundUpdate = true;
		PineFmod.playOrContinue(dial.soundEmitter);
		callOrDeferOnDialMoved(dial, MoveEvent.Released);
	}

	private void handleDialCancel(Dial dial)
	{
		float dialSnapAngle = getDialSnapAngle(dial);
		handleDialFinalize(dial, dialSnapAngle);
	}

	private void handleDialFinalize(Dial dial, float targetAngle)
	{
		if (dial.snapToPosition)
		{
			PineFmod.playOrContinue(dial.soundEmitter);
			dial.targetAngle = targetAngle;
			dial.backgroundUpdate = true;
		}
		else
		{
			PineFmod.playOneShotSoundAttached(dial.endSound, dial.gameObject);
			PineFmod.stop(dial.soundEmitter);
			dial.angleChange = 0f;
			dial.currentAngle = targetAngle;
			syncDialView(dial);
		}
		callOrDeferOnDialMoved(dial, MoveEvent.Released);
	}

	private void handleDialBackground(Dial dial, float dt)
	{
		dial.lastValue = dial.value;
		float currentAngle = dial.currentAngle;
		dial.currentAngle = Mathf.MoveTowards(dial.currentAngle, dial.targetAngle, dt * 200f);
		dial.angleChange = dial.currentAngle - currentAngle;
		syncDialView(dial);
		bool flag = dial.currentAngle == dial.targetAngle;
		if (flag)
		{
			if (dial.soundOnPoints && !dial.soundTurnHotspot.IsNull)
			{
				PineFmod.playOneShotSoundAttached(dial.soundTurnHotspot, dial.gameObject);
			}
			PineFmod.playOneShotSoundAttached(dial.endSound, dial.gameObject);
			PineFmod.stop(dial.soundEmitter);
			dial.backgroundUpdate = false;
		}
		callOrDeferOnDialMoved(dial, flag ? MoveEvent.Snapped : MoveEvent.Moved);
	}

	private void syncDialView(Dial dial)
	{
		dial.rootTransform().localRotation = dial.originalRotation * Quaternion.Euler(dial.rotationAxis * dial.currentAngle);
	}

	private float getDialSnapAngle(Dial dial)
	{
		if (!dial.snapToPosition)
		{
			return dial.currentAngle;
		}
		int num = Mathf.RoundToInt((dial.currentAngle - dial.minAngle) / dial.stepAngle);
		if (dial.useAngleLimits)
		{
			num = Mathf.Clamp(num, 0, dial.valueCount - 1);
		}
		return dial.minAngle + (float)num * dial.stepAngle;
	}

	private float calculateDialAngleChangeDelta(Pointer pointer, Dial dial, bool recalculateControllerDialDirection)
	{
		float result;
		if (vr.isActive())
		{
			Vector3 position = vr.getControllerForId(pointer.gestureFingerId).raycastDestinationIndicator.transform.position;
			result = 0f - Vector3.SignedAngle(dial.cursorViewPosLast - dial.transform.position, position - dial.transform.position, -playerCamera.transform.forward);
			dial.cursorViewPosLast = position;
		}
		else if (Controller.isActive())
		{
			Vector3 vector = getControllerMove(canInvert: false);
			if (vector == Vector3.zero)
			{
				vector = -getControllerLookRaw();
			}
			if (dial.controllerDialType == Dial.ControllerDialType.Horizontal)
			{
				if (vector == Vector3.zero)
				{
					dial.dialControllerTimeAtZero += Time.deltaTime;
					if (dial.dialControllerTimeAtZero > 0.5f)
					{
						recalculateControllerDialDirection = true;
					}
				}
				else
				{
					dial.dialControllerTimeAtZero = 0f;
				}
				if (recalculateControllerDialDirection)
				{
					Vector3 position2 = dial.transform.position;
					float num = Vector3.Dot((dial.transform.TransformPoint(dial.originToHandleDirection) - position2).normalized, playerCamera.transform.forward);
					dial.currentControllerRotationSpeed = dial.controllerRotationSpeed * (float)((num < 0f) ? 1 : (-1));
				}
				result = vector.x * dial.currentControllerRotationSpeed * Time.deltaTime * 100f;
			}
			else
			{
				int num2 = 0;
				if (vector.x > 0.8f)
				{
					num2 = -1;
				}
				if (vector.x < -0.8f)
				{
					num2 = 1;
				}
				result = dial.controllerRotationSpeed * Time.deltaTime * 100f * (float)num2;
			}
		}
		else
		{
			Vector3 vector2 = ((gameState.current == GameState.Zoom) ? playerCamera.WorldToScreenPoint(dial.transform.position) : playerCamera.ViewportToScreenPoint(playerCamera.WorldToViewportPoint(dial.transform.position)));
			vector2.z = 0f;
			Vector3 vector3 = dial.cursorViewPosLast + pointer.gestureMovementRaw;
			result = Vector2.SignedAngle(dial.cursorViewPosLast - vector2, vector3 - vector2);
			dial.cursorViewPosLast = vector3;
		}
		return result;
	}

	[LuaAPI]
	public void startSwitch(Switch3D switch3D)
	{
		handleSwitch3DStart(switch3D);
	}

	private void handleSwitch3D(Pointer pointer)
	{
		Switch3D component = pointer.context.target.GetComponent<Switch3D>();
		if (component.sessionId != pointer.context.interactionSessionId)
		{
			component.sessionId = pointer.context.interactionSessionId;
			startInteraction(component.gameObject);
			handleSwitch3DStart(component);
			session.send(new Switch3DStartPacket
			{
				switch3D = component
			});
			if (component.switchType != Switch3DType.Hold)
			{
				stopInteraction(component.gameObject);
			}
		}
		if (pointer.gestureUp)
		{
			handleSwitch3DFinalize(component);
			session.send(new Switch3DFinalizePacket
			{
				switch3D = component
			});
			if (component.switchType == Switch3DType.Hold)
			{
				stopInteraction(component.gameObject);
			}
		}
	}

	public void handleSwitch3DStart(Switch3D switch3D)
	{
		callOrDeferOnSwitch3D(switch3D, Switch3DEvent.Start);
		if (switch3D.switchType == Switch3DType.Click)
		{
			handleSwitch3DStartClick(switch3D);
		}
		else if (switch3D.switchType == Switch3DType.Flip)
		{
			handleSwitch3DStartFlip(switch3D);
		}
		else if (switch3D.switchType == Switch3DType.Hold)
		{
			handleSwitch3DStartHold(switch3D);
		}
		else if (switch3D.switchType == Switch3DType.Loop)
		{
			handleSwitch3DStartLoop(switch3D);
		}
		else if (switch3D.switchType == Switch3DType.ClickLoop)
		{
			handleSwitch3DStartClickLoop(switch3D);
		}
		else if (switch3D.switchType == Switch3DType.OnlyOnce)
		{
			handleSwitch3DStartOnlyOnce(switch3D);
		}
		else
		{
			UnityEngine.Debug.LogError(string.Format("Unsupported '{0} = {1}'!", "switchType", switch3D.switchType));
		}
	}

	private void handleSwitch3DStartClick(Switch3D switch3D)
	{
		bool num = switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null;
		bool flag = switch3D.sequence != null;
		if (num)
		{
			switch3D.currentValue = switch3D.tweenState.getWeight("Down");
			switch3D.targetValue = 1f;
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
		}
		else if (flag)
		{
			switch3D.currentValue = switch3D.sequence.sequenceTime;
			switch3D.targetValue = switch3D.sequence.sequenceDuration;
			switch3D.sequence.setTime(switch3D.currentValue);
		}
		else
		{
			switch3D.currentValue = ((switch3D.currentValue == 0f) ? 1 : 0);
			switch3D.targetValue = switch3D.currentValue;
		}
		switch3D.backgroundUpdate = true;
		if (num || flag)
		{
			handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: true);
		}
		handleSwitch3DSoundOneShot(switch3D, isOnSound: true);
		handleSwitch3DSoundOneShotTweenState(switch3D, isStartSound: true);
	}

	private void handleSwitch3DStartFlip(Switch3D switch3D)
	{
		bool num = switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null;
		bool flag = switch3D.sequence != null;
		if (num)
		{
			switch3D.currentValue = switch3D.tweenState.getWeight("Down");
			switch3D.targetValue = ((switch3D.currentValue < 0.5f) ? 1 : 0);
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
		}
		else if (flag)
		{
			switch3D.currentValue = switch3D.sequence.sequenceTime;
			switch3D.targetValue = ((switch3D.currentValue < switch3D.sequence.sequenceDuration / 2f) ? switch3D.sequence.sequenceDuration : 0f);
			switch3D.sequence.setTime(switch3D.currentValue);
		}
		else
		{
			switch3D.currentValue = ((switch3D.currentValue == 0f) ? 1 : 0);
			switch3D.targetValue = switch3D.currentValue;
			callOrDeferOnSwitch3D(switch3D, (switch3D.currentValue != 0f) ? Switch3DEvent.On : Switch3DEvent.Off);
		}
		if (num || flag)
		{
			switch3D.backgroundUpdate = true;
			handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: true);
		}
		handleSwitch3DSoundOneShot(switch3D, switch3D.targetValue != 0f);
		handleSwitch3DSoundOneShotTweenState(switch3D, isStartSound: true);
	}

	private void handleSwitch3DStartHold(Switch3D switch3D)
	{
		bool num = switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null;
		bool flag = switch3D.sequence != null;
		if (num)
		{
			switch3D.currentValue = switch3D.tweenState.getWeight("Down");
			switch3D.targetValue = 1f;
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
		}
		else if (flag)
		{
			switch3D.currentValue = switch3D.sequence.sequenceTime;
			switch3D.targetValue = switch3D.sequence.sequenceDuration;
			switch3D.sequence.setTime(switch3D.currentValue);
		}
		else
		{
			switch3D.currentValue = 1f;
			switch3D.targetValue = 1f;
			callOrDeferOnSwitch3D(switch3D, Switch3DEvent.On);
		}
		if (num || flag)
		{
			switch3D.backgroundUpdate = true;
			handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: true);
		}
	}

	private void handleSwitch3DStartLoop(Switch3D switch3D)
	{
		handleSwitch3DStartClick(switch3D);
	}

	private void handleSwitch3DStartClickLoop(Switch3D switch3D)
	{
		handleSwitch3DStartClick(switch3D);
	}

	private void handleSwitch3DStartOnlyOnce(Switch3D switch3D)
	{
		if (switch3D.targetValue == 0f)
		{
			handleSwitch3DStartClick(switch3D);
		}
	}

	private void handleSwitch3DCancel(Switch3D switch3D)
	{
		handleSwitch3DFinalize(switch3D);
	}

	private void handleSwitch3DFinalize(Switch3D switch3D)
	{
		if (switch3D.switchType != Switch3DType.Click && switch3D.switchType != Switch3DType.Flip)
		{
			if (switch3D.switchType == Switch3DType.Hold)
			{
				handleSwitch3DFinalizeHold(switch3D);
			}
			else if (switch3D.switchType != Switch3DType.Loop && switch3D.switchType != Switch3DType.ClickLoop && switch3D.switchType != Switch3DType.OnlyOnce)
			{
				UnityEngine.Debug.LogError(string.Format("Unsupported '{0} = {1}'!", "switchType", switch3D.switchType));
			}
		}
	}

	private void handleSwitch3DFinalizeHold(Switch3D switch3D)
	{
		callOrDeferOnSwitch3D(switch3D, Switch3DEvent.Release);
		switch3D.targetValue = 0f;
		handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: true);
		if (switch3D.tweenState == null && switch3D.sequence == null)
		{
			switch3D.currentValue = 0f;
			callOrDeferOnSwitch3D(switch3D, Switch3DEvent.Off);
		}
	}

	private void handleSwitch3DBackground(Switch3D switch3D, float dt)
	{
		if (switch3D.switchType == Switch3DType.Click)
		{
			handleSwitch3DBackgroundClick(switch3D, dt);
		}
		else if (switch3D.switchType == Switch3DType.Flip)
		{
			handleSwitch3DBackgroundFlip(switch3D, dt);
		}
		else if (switch3D.switchType == Switch3DType.Hold)
		{
			handleSwitch3DBackgroundHold(switch3D, dt);
		}
		else if (switch3D.switchType == Switch3DType.Loop)
		{
			handleSwitch3DBackgroundLoop(switch3D, dt);
		}
		else if (switch3D.switchType == Switch3DType.ClickLoop)
		{
			handleSwitch3DBackgroundClickLoop(switch3D, dt);
		}
		else if (switch3D.switchType == Switch3DType.OnlyOnce)
		{
			handleSwitch3DBackgroundOnlyOnce(switch3D, dt);
		}
		else
		{
			UnityEngine.Debug.LogError(string.Format("Unsupported '{0} = {1}'!", "switchType", switch3D.switchType));
		}
	}

	private void handleSwitch3DBackgroundClick(Switch3D switch3D, float dt)
	{
		switch3D.currentValue = Mathf.MoveTowards(switch3D.currentValue, switch3D.targetValue, switch3D.transitionSpeed * dt);
		bool flag = false;
		if (switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null)
		{
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
			flag = true;
		}
		else if (switch3D.sequence != null)
		{
			switch3D.sequence.setTime(switch3D.currentValue);
			flag = true;
		}
		if (!flag)
		{
			switch3D.currentValue = switch3D.targetValue;
		}
		if (switch3D.currentValue == switch3D.targetValue)
		{
			if (switch3D.targetValue == 0f)
			{
				switch3D.backgroundUpdate = false;
				handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: false);
				callOrDeferOnSwitch3D(switch3D, Switch3DEvent.Off);
			}
			else
			{
				switch3D.targetValue = 0f;
				handleSwitch3DSoundOneShot(switch3D, isOnSound: false);
				callOrDeferOnSwitch3D(switch3D, Switch3DEvent.On);
			}
			handleSwitch3DSoundOneShotTweenState(switch3D, isStartSound: false);
		}
	}

	private void handleSwitch3DBackgroundFlip(Switch3D switch3D, float dt, bool forceFinish = false)
	{
		switch3D.currentValue = Mathf.MoveTowards(switch3D.currentValue, switch3D.targetValue, switch3D.transitionSpeed * dt);
		if (forceFinish)
		{
			switch3D.currentValue = switch3D.targetValue;
		}
		if (switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null)
		{
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
		}
		else if (switch3D.sequence != null)
		{
			switch3D.sequence.setTime(switch3D.currentValue);
		}
		if (switch3D.currentValue == switch3D.targetValue)
		{
			switch3D.backgroundUpdate = false;
			handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: false);
			handleSwitch3DSoundOneShotTweenState(switch3D, isStartSound: false);
			callOrDeferOnSwitch3D(switch3D, (switch3D.targetValue != 0f) ? Switch3DEvent.On : Switch3DEvent.Off);
		}
	}

	private void handleSwitch3DBackgroundHold(Switch3D switch3D, float dt)
	{
		float currentValue = switch3D.currentValue;
		switch3D.currentValue = Mathf.MoveTowards(switch3D.currentValue, switch3D.targetValue, switch3D.transitionSpeed * dt);
		if (switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null)
		{
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
		}
		else if (switch3D.sequence != null)
		{
			switch3D.sequence.setTime(switch3D.currentValue);
		}
		if (switch3D.currentValue == switch3D.targetValue)
		{
			handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: false);
			if (switch3D.targetValue == 0f)
			{
				switch3D.backgroundUpdate = false;
				callOrDeferOnSwitch3D(switch3D, Switch3DEvent.Off);
			}
			else if (currentValue != switch3D.currentValue)
			{
				callOrDeferOnSwitch3D(switch3D, Switch3DEvent.On);
			}
		}
	}

	private void handleSwitch3DBackgroundLoop(Switch3D switch3D, float dt)
	{
		if (switch3D.currentPauseTime > 0f)
		{
			switch3D.currentPauseTime -= dt;
			return;
		}
		switch3D.currentValue = Mathf.MoveTowards(switch3D.currentValue, switch3D.targetValue, switch3D.transitionSpeed * dt);
		if (switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null)
		{
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
		}
		else if (switch3D.sequence != null)
		{
			switch3D.sequence.setTime(switch3D.currentValue);
		}
		if (switch3D.currentValue == switch3D.targetValue)
		{
			switch3D.currentPauseTime = switch3D.pauseOnLoop;
			switch3D.currentValue = 0f;
			handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: false);
			handleSwitch3DSoundOneShotTweenState(switch3D, isStartSound: false);
			callOrDeferOnSwitch3D(switch3D, (switch3D.targetValue != 0f) ? Switch3DEvent.On : Switch3DEvent.Off);
		}
	}

	private void handleSwitch3DBackgroundClickLoop(Switch3D switch3D, float dt)
	{
		if (switch3D.currentPauseTime > 0f)
		{
			switch3D.currentPauseTime -= dt;
			return;
		}
		switch3D.currentValue = Mathf.MoveTowards(switch3D.currentValue, switch3D.targetValue, switch3D.transitionSpeed * dt);
		if (switch3D.tweenState != null && switch3D.tweenState.findStateByName("Down") != null)
		{
			switch3D.tweenState.setWeight("Down", switch3D.currentValue);
		}
		else if (switch3D.sequence != null)
		{
			switch3D.sequence.setTime(switch3D.currentValue);
		}
		if (switch3D.currentValue == switch3D.targetValue)
		{
			switch3D.currentPauseTime = switch3D.pauseOnLoop;
			switch3D.targetValue = ((switch3D.targetValue == 0f) ? 1 : 0);
			handleSwitch3DSoundLoop(switch3D, shouldPlayOrContinue: false);
			handleSwitch3DSoundOneShotTweenState(switch3D, isStartSound: false);
			callOrDeferOnSwitch3D(switch3D, (switch3D.targetValue != 0f) ? Switch3DEvent.On : Switch3DEvent.Off);
		}
	}

	private void handleSwitch3DBackgroundOnlyOnce(Switch3D switch3D, float dt)
	{
		handleSwitch3DBackgroundFlip(switch3D, dt);
	}

	private void handleSwitch3DSoundOneShot(Switch3D switch3D, bool isOnSound)
	{
		if (!switch3D.soundStinger.IsNull && !switch3D.playedStinger && switch3D.playStingerWhenOn == isOnSound)
		{
			PineFmod.playOneShotSoundAttached(switch3D.soundStinger, switch3D.gameObject);
			switch3D.playedStinger = true;
		}
		else
		{
			PineFmod.playOneShotSoundAttached(isOnSound ? switch3D.soundTurnOn : switch3D.soundTurnOff, switch3D.gameObject);
		}
	}

	private void handleSwitch3DSoundOneShotTweenState(Switch3D switch3D, bool isStartSound)
	{
		TweenState tweenState = switch3D.tweenState;
		if (!(tweenState == null))
		{
			PineFmod.playOneShotSoundAttached(isStartSound ? tweenState.soundStart : tweenState.soundEnd, switch3D.gameObject);
		}
	}

	private void handleSwitch3DSoundLoop(Switch3D switch3D, bool shouldPlayOrContinue)
	{
		if (switch3D.tweenState != null && switch3D.tweenState.soundLoopEmitter != null)
		{
			if (shouldPlayOrContinue)
			{
				PineFmod.playOrContinue(switch3D.tweenState.soundLoopEmitter);
			}
			else
			{
				PineFmod.stop(switch3D.tweenState.soundLoopEmitter);
			}
		}
		else if (switch3D.sequence != null && switch3D.sequence.soundLoopEmitter != null)
		{
			if (shouldPlayOrContinue)
			{
				PineFmod.playOrContinue(switch3D.sequence.soundLoopEmitter);
			}
			else
			{
				PineFmod.stop(switch3D.sequence.soundLoopEmitter);
			}
		}
	}

	private void handleTrackable(Pointer pointer)
	{
		Trackable component = pointer.context.target.GetComponent<Trackable>();
		Vector3 vector = ((gameState.current == GameState.Zoom) ? pointer.gesturePositionViewport : pointer.context.currentTargetHitPoint);
		if (component.sessionId != pointer.context.interactionSessionId)
		{
			component.sessionId = pointer.context.interactionSessionId;
			startInteraction(component.gameObject);
			controllerStartInteraction(pointer);
			handleTrackableStart(component, vector);
			session.send(new TrackableStartPacket
			{
				trackable = component,
				value = vector
			});
		}
		handleTrackableInteraction(component, vector);
		session.send(new TrackableInteractionPacket
		{
			trackable = component,
			value = vector
		});
		if (pointer.gestureUp)
		{
			handleTrackableFinalize(component);
			session.send(new TrackableFinalizePacket
			{
				trackable = component
			});
			stopInteraction(component.gameObject);
			controllerEndInteraction();
		}
	}

	private void handleTrackableStart(Trackable trackable, Vector3 startingValue)
	{
		trackable.currentValue = startingValue;
		callOrDeferOnTrackable(trackable, new TrackableEvent
		{
			diff = Vector3.zero,
			type = TrackableEventType.Start
		});
		PineFmod.playOneShotSoundAttached(trackable.startSound, trackable.gameObject);
	}

	private void handleTrackableInteraction(Trackable trackable, Vector3 currentValue)
	{
		Vector3 vector = currentValue - trackable.currentValue;
		trackable.currentValue = currentValue;
		callOrDeferOnTrackable(trackable, new TrackableEvent
		{
			diff = vector,
			type = TrackableEventType.Moved
		});
		if (vector != Vector3.zero)
		{
			PineFmod.playOrContinue(trackable.soundEmitter);
		}
		else
		{
			PineFmod.stop(trackable.soundEmitter);
		}
	}

	private void handleTrackableFinalize(Trackable trackable)
	{
		callOrDeferOnTrackable(trackable, new TrackableEvent
		{
			diff = Vector3.zero,
			type = TrackableEventType.Release
		});
		PineFmod.playOneShotSoundAttached(trackable.endSound, trackable.gameObject);
		PineFmod.stop(trackable.soundEmitter);
	}

	private void handleJoystick(Pointer pointer)
	{
		Joystick component = pointer.context.target.GetComponent<Joystick>();
		if (component.sessionId != pointer.context.interactionSessionId)
		{
			component.sessionId = pointer.context.interactionSessionId;
			destroyGameplayAnimations(component.gameObject, performEvents: false);
			startInteraction(component.gameObject);
			controllerStartInteraction(pointer, virtualHiddenButMovable: true);
			handleJoystickStart(component);
			session.send(new JoystickStartPacket
			{
				joystick = component
			});
		}
		Vector2 newRotation = component.currentRotation;
		if (Controller.isActive() && new Vector2(pointer.gestureMovementViewport.x, pointer.gestureMovementViewport.y).magnitude < 6.6666666E-06f)
		{
			newRotation = Vector2.MoveTowards(component.currentRotation, Vector2.zero, Time.deltaTime * 150f);
		}
		float num = 1000f * component.speed;
		newRotation.x += pointer.gestureMovementViewport.x * num;
		newRotation.x = Mathf.Clamp(newRotation.x, 0f - component.axisAngleLimits.x, component.axisAngleLimits.x);
		newRotation.y += pointer.gestureMovementViewport.y * num;
		newRotation.y = Mathf.Clamp(newRotation.y, 0f - component.axisAngleLimits.y, component.axisAngleLimits.y);
		handleJoystickInteraction(component, newRotation);
		session.send(new JoystickInteractionPacket
		{
			joystick = component,
			newRotation = newRotation
		});
		if (pointer.gestureUp)
		{
			handleJoystickFinalize(component);
			session.send(new JoystickFinalizePacket
			{
				joystick = component
			});
			stopInteraction(component.gameObject);
			controllerEndInteraction();
		}
	}

	private void handleJoystickStart(Joystick joystick)
	{
		PineFmod.playOneShotSoundAttached(joystick.soundBegin, joystick.gameObject);
	}

	private void handleJoystickInteraction(Joystick joystick, Vector2 targetRotation)
	{
		Quaternion joystickQuaternionFromRotation = getJoystickQuaternionFromRotation(joystick, targetRotation);
		bool num = (double)Vector3.Distance(joystick.currentRotation, targetRotation) > 1E-06;
		if (num)
		{
			PineFmod.playOrContinue(joystick.soundEmitter);
		}
		else
		{
			PineFmod.stop(joystick.soundEmitter);
		}
		if (num)
		{
			callOrDeferOnJoystickMoved(joystick, MoveEvent.Moved);
		}
		joystick.currentRotation = targetRotation;
		joystick.transform.localRotation = joystick.initialRotation * joystickQuaternionFromRotation;
	}

	private void handleJoystickFinalize(Joystick joystick)
	{
		PineFmod.playOrContinue(joystick.soundEmitter);
		PineFmod.playOneShotSoundAttached(joystick.soundEnd, joystick.gameObject);
		joystick.backgroundUpdate = true;
		joystick.rotationOnBackgroundStart = joystick.currentRotation;
		callOrDeferOnJoystickMoved(joystick, MoveEvent.Released);
	}

	private void handleJoystickBackground(Joystick joystick, float dt)
	{
		float num = Mathf.Clamp01(UnityUtils.smootherStep(0f, 1f, joystick.backgroundTime * 2f * joystick.returnSpeed));
		joystick.currentRotation = Vector2.Lerp(joystick.rotationOnBackgroundStart, Vector2.zero, num);
		joystick.transform.localRotation = joystick.initialRotation * getJoystickQuaternionFromRotation(joystick, joystick.currentRotation);
		if (num >= 1f)
		{
			PineFmod.stop(joystick.soundEmitter);
			joystick.backgroundUpdate = false;
			callOrDeferOnJoystickMoved(joystick, MoveEvent.Snapped);
		}
	}

	private Quaternion getJoystickQuaternionFromRotation(Joystick joystick, Vector2 rotation)
	{
		Quaternion result = Quaternion.identity;
		if (joystick.horizontalAxis == Joystick.JoystickAxis.X)
		{
			result = Quaternion.Euler(rotation.x, 0f, 0f);
		}
		else if (joystick.horizontalAxis == Joystick.JoystickAxis.Y)
		{
			result = Quaternion.Euler(0f, rotation.x, 0f);
		}
		else if (joystick.horizontalAxis == Joystick.JoystickAxis.Z)
		{
			result = Quaternion.Euler(0f, 0f, rotation.x);
		}
		else if (joystick.horizontalAxis == Joystick.JoystickAxis.MinusX)
		{
			result = Quaternion.Euler(0f - rotation.x, 0f, 0f);
		}
		else if (joystick.horizontalAxis == Joystick.JoystickAxis.MinusY)
		{
			result = Quaternion.Euler(0f, 0f - rotation.x, 0f);
		}
		else if (joystick.horizontalAxis == Joystick.JoystickAxis.MinusZ)
		{
			result = Quaternion.Euler(0f, 0f, 0f - rotation.x);
		}
		if (joystick.verticalAxis == Joystick.JoystickAxis.X)
		{
			result *= Quaternion.Euler(rotation.y, 0f, 0f);
		}
		else if (joystick.verticalAxis == Joystick.JoystickAxis.Y)
		{
			result *= Quaternion.Euler(0f, rotation.y, 0f);
		}
		else if (joystick.verticalAxis == Joystick.JoystickAxis.Z)
		{
			result *= Quaternion.Euler(0f, 0f, rotation.y);
		}
		else if (joystick.verticalAxis == Joystick.JoystickAxis.MinusX)
		{
			result *= Quaternion.Euler(0f - rotation.y, 0f, 0f);
		}
		else if (joystick.verticalAxis == Joystick.JoystickAxis.MinusY)
		{
			result *= Quaternion.Euler(0f, 0f - rotation.y, 0f);
		}
		else if (joystick.verticalAxis == Joystick.JoystickAxis.MinusZ)
		{
			result *= Quaternion.Euler(0f, 0f, 0f - rotation.y);
		}
		return result;
	}

	private void handleRotatable(Pointer pointer)
	{
		Rotatable component = pointer.context.target.GetComponent<Rotatable>();
		if (component.sessionId != pointer.context.interactionSessionId)
		{
			component.sessionId = pointer.context.interactionSessionId;
			startInteraction(component.gameObject);
			controllerStartInteraction(pointer);
			handleRotatableStart(component);
			session.send(new RotatableStartPacket
			{
				rotatable = component
			});
		}
		Vector3 vector = component.transform.position - playerCamera.transform.position;
		Vector3 vector2 = Vector3.Cross(playerCamera.transform.up, vector);
		Vector3 axis = Vector3.Cross(vector, vector2);
		float num = 1000f * component.speed;
		Quaternion quaternion = Quaternion.AngleAxis(pointer.gestureMovementViewport.y * num, vector2) * Quaternion.AngleAxis((0f - pointer.gestureMovementViewport.x) * num, axis) * component.transform.rotation;
		handleRotatableInteraction(component, quaternion);
		session.send(new RotatableInteractionPacket
		{
			rotatable = component,
			rotation = quaternion
		});
		if (pointer.gestureUp)
		{
			handleRotatableFinalize(component);
			session.send(new RotatableFinalizePacket
			{
				rotatable = component
			});
			stopInteraction(component.gameObject);
			controllerEndInteraction();
		}
	}

	private void handleRotatableStart(Rotatable rotatable)
	{
		rotatable.idleFrames = 0;
		PineFmod.playOneShotSoundAttached(rotatable.startSound, rotatable.gameObject);
	}

	private void handleRotatableInteraction(Rotatable rotatable, Quaternion newRotation)
	{
		Transform obj = rotatable.transform;
		Quaternion rotation = obj.rotation;
		obj.rotation = newRotation;
		bool flag = Quaternion.Angle(rotation, newRotation) > 0f;
		rotatable.idleFrames += ((!flag) ? 1 : (-rotatable.idleFrames));
		if (flag)
		{
			callOrDeferOnRotatableMoved(rotatable, MoveEvent.Moved);
		}
		if (rotatable.idleFramesToStopTurnSound >= 0 && rotatable.idleFrames > rotatable.idleFramesToStopTurnSound)
		{
			PineFmod.stop(rotatable.soundEmitter);
		}
		else if (!PineFmod.isPlaying(rotatable.soundEmitter))
		{
			PineFmod.play(rotatable.soundEmitter);
		}
	}

	private void handleRotatableFinalize(Rotatable rotatable)
	{
		PineFmod.playOneShotSoundAttached(rotatable.endSound, rotatable.gameObject);
		PineFmod.stop(rotatable.soundEmitter);
		callOrDeferOnRotatableMoved(rotatable, MoveEvent.Released);
	}

	private void handleItemBackground(Item item, float dt)
	{
		if (item.toolZoomType == ToolZoomType.None)
		{
			ToolContext toolContext = new ToolContext();
			toolContext.deltaTime = dt;
			toolContext.state = ToolState.Update;
			item.toolUseTimer += dt;
			if (!item.lockItemInteractions && item.toolUseTimer >= item.toolUseDuration)
			{
				item.toolUseTimer = 0f;
				item.backgroundUpdate = false;
				toolContext.state = ToolState.End;
			}
			if (item.lockItemInteractions && item.unlockItemInteractions)
			{
				item.backgroundUpdate = false;
				item.unlockItemInteractions = false;
				toolContext.state = ToolState.End;
			}
			callOrDeferOnTool(item, toolContext);
		}
		else
		{
			ToolContext toolContext2 = new ToolContext();
			toolContext2.deltaTime = dt;
			toolContext2.state = ToolState.Update;
			handleToolInteraction(item, toolContext2);
		}
	}

	private void handleTool(Pointer pointer, bool forceEnd = false)
	{
		Item component = inventory[pcSelectedItem].topGameObject().GetComponent<Item>();
		if (component.sessionId != pointer.context.interactionSessionId && component.toolZoomType != ToolZoomType.None && zoomState != ZoomState.None)
		{
			return;
		}
		bool flag = pointer.gestureUp || forceEnd;
		ToolContext toolContext = new ToolContext();
		toolContext.deltaTime = Time.deltaTime;
		toolContext.state = ToolState.Update;
		if (component.sessionId != pointer.context.interactionSessionId && !flag)
		{
			component.sessionId = pointer.context.interactionSessionId;
			toolContext.state = ToolState.Start;
			if (component.toolZoomType != ToolZoomType.None && zoomState == ZoomState.None)
			{
				pointer.context.doNotKill = true;
				handleToolZoomEnter(component, component.toolZoomType == ToolZoomType.Hold);
			}
			if (component.toolUseDuration >= 0f)
			{
				component.toolUseTimer = 0f;
			}
			if ((component.toolZoomType == ToolZoomType.None && component.toolUseDuration >= 0f) || component.lockItemInteractions)
			{
				component.toolUseTimer = 0f;
				component.backgroundUpdate = true;
			}
		}
		if (flag)
		{
			toolContext.state = ToolState.End;
		}
		toolContext.target = pointer.context.target?.GetComponent<Interactive>();
		toolContext.currentTarget = pointer.context.currentTarget?.GetComponent<Interactive>();
		toolContext.ray = pointer.gestureFirstRay;
		toolContext.currentRay = pointer.gestureRay;
		toolContext.targetHitPoint = pointer.context.targetHitPoint;
		toolContext.targetHitNormal = pointer.context.targetHitNormal;
		toolContext.currentTargetHitPoint = pointer.context.currentTargetHitPoint;
		toolContext.currentTargetHitNormal = pointer.context.currentTargetHitNormal;
		toolContext.deltaTime = Time.deltaTime;
		if (component.toolZoomType == ToolZoomType.None || toolContext.state == ToolState.Start)
		{
			handleToolInteraction(component, toolContext);
			if (toolContext.state == ToolState.Start)
			{
				captureHostViewState(component);
			}
			session.send(new ToolInteractionPacket
			{
				tool = component,
				context = toolContext
			});
		}
	}

	private void handleToolEndSync(Item item)
	{
		ToolContext toolContext = new ToolContext();
		toolContext.state = ToolState.End;
		handleToolInteraction(item, toolContext);
		session.send(new ToolInteractionPacket
		{
			tool = item,
			context = toolContext
		});
	}

	private void handleToolInteraction(Item tool, ToolContext context)
	{
		if (tool.toolZoomType != ToolZoomType.None)
		{
			if (context.state == ToolState.End)
			{
				tool.backgroundUpdate = false;
			}
			else if (context.state == ToolState.Start)
			{
				tool.backgroundUpdate = true;
			}
		}
		callOrDeferOnTool(tool, context);
	}

	public void handleLockValue(List<LockArgument> lockArguments, int value)
	{
		handleLockValue(lockArguments.ToArray(), value);
	}

	public void handleLockValue(LockArgument[] lockArguments, int value)
	{
		LockArgument[] array = lockArguments;
		foreach (LockArgument lockArgument in array)
		{
			enterLockInput(lockArgument.targetLock, value, lockArgument.targetIndex);
		}
		array = lockArguments;
		foreach (LockArgument lockArgument2 in array)
		{
			checkLockPassword(lockArgument2.targetLock);
		}
	}

	public void enterLockInput(Lock targetLock, int value, int index)
	{
		switch (index)
		{
		case -400:
			if (value != 0)
			{
				for (int k = 0; k < targetLock.password.Length; k++)
				{
					targetLock.currentValues[k] = 0;
				}
				targetLock.nextValueIndex = 0;
			}
			break;
		case -500:
			if (value != 0)
			{
				for (int j = 0; j < targetLock.password.Length; j++)
				{
					targetLock.currentValues[j] = targetLock.password[j];
				}
				targetLock.nextValueIndex = targetLock.password.Length;
			}
			break;
		default:
			if (targetLock.lockType == LockType.Inplace)
			{
				targetLock.currentValues[index] = value;
			}
			else if (targetLock.lockType == LockType.Continuous)
			{
				targetLock.currentValues[targetLock.nextValueIndex % targetLock.password.Length] = value;
				targetLock.nextValueIndex++;
			}
			else
			{
				if (targetLock.lockType != LockType.Fixed)
				{
					break;
				}
				if (targetLock.nextValueIndex == targetLock.password.Length)
				{
					for (int i = 0; i < targetLock.password.Length; i++)
					{
						targetLock.currentValues[i] = 0;
					}
					targetLock.nextValueIndex = 0;
				}
				targetLock.currentValues[targetLock.nextValueIndex] = value;
				targetLock.nextValueIndex++;
			}
			break;
		}
		targetLock.revisionNumber++;
	}

	public void unlockLock(Lock targetLock)
	{
		for (int i = 0; i < targetLock.currentValues.Length; i++)
		{
			handleLockValue(new LockArgument[1]
			{
				new LockArgument
				{
					targetLock = targetLock,
					targetIndex = i
				}
			}, targetLock.password[i]);
		}
	}

	public void checkLockPassword(Lock targetLock)
	{
		if (updateLockIsUnlocked())
		{
			onLockChangedStatus();
		}
		static bool logicCompare(bool left, bool right, LockLogicType type, out bool breakLoop)
		{
			breakLoop = false;
			switch (type)
			{
			case LockLogicType.And:
				return left && right;
			case LockLogicType.Or:
				return left || right;
			case LockLogicType.Xor:
				if (left || right)
				{
					return !(left && right);
				}
				return false;
			case LockLogicType.Xxor:
				breakLoop = left && right;
				if (left || right)
				{
					return !(left && right);
				}
				return false;
			default:
				return left && right;
			}
		}
		void onLockChangedStatus()
		{
			if (targetLock.isActive || !targetLock.deactivateLockOnUnlock)
			{
				bool flag = false;
				ZoomContext context = null;
				if (gameState.current != GameState.Room && targetLock.exitZoomOnUnlock && topZoomContextSafe(out context) && (targetLock.transform.IsChildOf(context.selected.transform) || context.selected.transform.IsChildOf(targetLock.transform)))
				{
					flag = true;
				}
				if (flag)
				{
					UnityEngine.Debug.Log("[JURA] TODO");
					handleZoomLeave();
				}
				if (targetLock.isUnlocked)
				{
					levelLogic.onUnlock(targetLock);
					if (targetLock.onUnlock.locks != null && targetLock.onUnlock.locks.Count > 0)
					{
						handleLockValue(targetLock.onUnlock.locks, targetLock.onUnlock.output);
					}
					if (targetLock.deactivateLockOnUnlock)
					{
						targetLock.isActive = false;
					}
				}
				else if (targetLock.onLock.locks.Count > 0)
				{
					handleLockValue(targetLock.onLock.locks, targetLock.onLock.output);
				}
			}
		}
		bool updateLockIsUnlocked()
		{
			bool flag = targetLock.lockLogicType == LockLogicType.And;
			if (targetLock.lockType == LockType.Inplace)
			{
				for (int i = 0; i < targetLock.password.Length; i++)
				{
					flag = logicCompare(flag, targetLock.password[i] == targetLock.currentValues[i], targetLock.lockLogicType, out var breakLoop);
					if (breakLoop)
					{
						break;
					}
				}
			}
			else if (targetLock.lockType == LockType.Continuous)
			{
				if (targetLock.nextValueIndex >= targetLock.password.Length)
				{
					for (int j = 0; j < targetLock.password.Length; j++)
					{
						flag = logicCompare(flag, targetLock.password[j] == targetLock.currentValues[(targetLock.nextValueIndex - targetLock.password.Length + j) % targetLock.password.Length], targetLock.lockLogicType, out var breakLoop2);
						if (breakLoop2)
						{
							break;
						}
					}
				}
				else
				{
					flag = false;
				}
			}
			else if (targetLock.lockType == LockType.Fixed)
			{
				if (targetLock.nextValueIndex == targetLock.password.Length)
				{
					for (int k = 0; k < targetLock.password.Length; k++)
					{
						flag = logicCompare(flag, targetLock.password[k] == targetLock.currentValues[k], targetLock.lockLogicType, out var breakLoop3);
						if (breakLoop3)
						{
							break;
						}
					}
				}
				else
				{
					flag = false;
				}
			}
			if (targetLock.lockNegateValue)
			{
				flag = !flag;
			}
			bool isUnlocked = targetLock.isUnlocked;
			targetLock.isUnlocked = flag;
			return isUnlocked != flag;
		}
	}

	private void handleSwapper(Pointer pointer)
	{
		if (pointer.context.targetType == ScreenTargetType.ItemInventory)
		{
			Item component = pointer.context.target.GetComponent<Item>();
			pointer.context.target.SetActive(value: false);
			placeSwapperItem(component);
			return;
		}
		SwapperPiece component2 = pointer.context.target.GetComponent<SwapperPiece>();
		Swapper swapper = component2.swapper;
		if (!(component2 == null) && pointer.gestureDown)
		{
			startInteraction(swapper.gameObject);
			handleSwapper(swapper, component2);
			session.send(new SwapperInteractionPacket
			{
				swapper = swapper,
				currentPiece = component2
			});
			stopInteraction(swapper.gameObject);
		}
		void placeSwapperItem(Item item)
		{
			Swapper component3 = pointer.context.currentTarget.GetComponent<Swapper>();
			SwapperPiece[] componentsInChildren = component3.GetComponentsInChildren<SwapperPiece>(includeInactive: true);
			foreach (SwapperPiece swapperPiece in componentsInChildren)
			{
				if (swapperPiece.linkedItem == item)
				{
					swapperPiece.gameObject.SetActive(value: true);
					Vector3 normalized = component3.transform.TransformDirection(component3.localNormal).normalized;
					if (new Plane(normalized, swapperPiece.transform.position).Raycast(pointer.gestureRay, out var enter))
					{
						swapperPiece.transform.position = pointer.gestureRay.GetPoint(enter) - swapperPiece.transform.rotation * swapperPiece.pivot;
					}
					break;
				}
			}
		}
	}

	private void handleSwapper(Swapper swapper, SwapperPiece currentPiece)
	{
		if (swapper.firstPiece == null)
		{
			Vector3 normalized = swapper.transform.TransformDirection(swapper.localNormal).normalized;
			swapper.swapperPieceOriginalPosition = currentPiece.transform.localPosition;
			if (swapper.pieceLift != 0f)
			{
				currentPiece.transform.position += normalized * swapper.pieceLift;
			}
			swapper.firstPiece = currentPiece;
			callOrDeferOnSwapper(swapper, new Swapper.SwapperEvent(swapper.firstPiece, null, isSolved: false, isReset: false));
			PineFmod.playOneShotSoundAttached(swapper.soundStart, currentPiece.gameObject);
			return;
		}
		swapper.firstPiece.transform.localPosition = swapper.swapperPieceOriginalPosition;
		if (swapper.firstPiece != currentPiece)
		{
			Transform obj = currentPiece.transform;
			Transform transform = swapper.firstPiece.transform;
			Vector3 position = swapper.firstPiece.transform.position;
			Vector3 position2 = currentPiece.transform.position;
			Vector3 vector = (obj.position = position);
			vector = (transform.position = position2);
			SwapperPiece swapperPiece = ((currentPiece.swappedPiece != null) ? currentPiece.swappedPiece : currentPiece);
			SwapperPiece swapperPiece2 = ((swapper.firstPiece.swappedPiece != null) ? swapper.firstPiece.swappedPiece : swapper.firstPiece);
			swapper.firstPiece.swappedPiece = ((swapper.firstPiece != swapperPiece) ? swapperPiece : null);
			currentPiece.swappedPiece = ((currentPiece != swapperPiece2) ? swapperPiece2 : null);
			bool isSolved = true;
			SwapperPiece[] componentsInChildren = swapper.GetComponentsInChildren<SwapperPiece>(includeInactive: true);
			foreach (SwapperPiece swapperPiece3 in componentsInChildren)
			{
				bool num = swapperPiece3.swappedPiece == null;
				bool flag = swapperPiece3.pieceGenericType != -1;
				bool flag2 = !num && flag && swapperPiece3.swappedPiece.pieceGenericType == swapperPiece3.pieceGenericType;
				if (!num && !flag2)
				{
					isSolved = false;
					break;
				}
			}
			callOrDeferOnSwapper(swapper, new Swapper.SwapperEvent(swapper.firstPiece, currentPiece, isSolved, isReset: false));
			PineFmod.playOneShotSoundAttached(swapper.soundSwap, currentPiece.gameObject);
		}
		else
		{
			callOrDeferOnSwapper(swapper, new Swapper.SwapperEvent(swapper.firstPiece, currentPiece, isSolved: false, isReset: true));
			PineFmod.playOneShotSoundAttached(swapper.soundCancel, currentPiece.gameObject);
		}
		swapper.firstPiece = null;
	}

	public void cancelSwapperSelection(Swapper swapper)
	{
		if (!(swapper.firstPiece == null))
		{
			levelLogic.onSwapper(swapper, new Swapper.SwapperEvent(swapper.firstPiece, swapper.firstPiece, isSolved: false, isReset: true));
			swapper.firstPiece = null;
		}
	}

	private void handlePaintable(Pointer pointer)
	{
		Paintable component = pointer.context.target.GetComponent<Paintable>();
		float brushSizeViewport = component.brushSize;
		if (component.brushSizeMode == PaintableSizeSpace.World)
		{
			float num = playerCamera.fieldOfView * (MathF.PI / 180f);
			float num2 = 2f * pointer.context.currentTargetHitDistance * Mathf.Tan(num / 2f);
			brushSizeViewport = component.brushSize / num2;
		}
		PaintableEdit edit = new PaintableEdit
		{
			brushColor = component.brushColor,
			brushCenterViewport = pointer.gesturePositionViewport,
			brushSizeViewport = brushSizeViewport,
			hitPointInLocalSpace = component.transform.InverseTransformPoint(pointer.context.currentTargetHitPoint),
			cameraPosition = playerCamera.transform.position,
			packedCameraRotation = QuaternionCompressor.compress(playerCamera.transform.rotation),
			screenWidth = (ushort)Screen.width,
			screenHeight = (ushort)Screen.height,
			pass = (byte)component.paintMode
		};
		float change = Vector3.Distance(pointer.gestureRay.direction, pointer.gestureRayPrevious.direction);
		handlePaintable(component, in edit, change, pointer.gestureDown, pointer.gestureUp);
		session.send(new PaintPaintablePacket
		{
			paintable = component,
			edit = edit,
			change = change,
			gestureDown = pointer.gestureDown,
			gestureUp = pointer.gestureUp
		});
	}

	private void handlePaintable(Paintable paintable, in PaintableEdit edit, float change, bool gestureDown, bool gestureUp)
	{
		brushPaintable(paintable, in edit);
		if (paintable.edits.Count < 1000)
		{
			bool flag = false;
			Vector3 vector = paintable.transform.TransformPoint(edit.hitPointInLocalSpace);
			foreach (PaintableEdit edit2 in paintable.edits)
			{
				Vector3 vector2 = paintable.transform.TransformPoint(edit2.hitPointInLocalSpace);
				if ((vector - vector2).sqrMagnitude < 0.0016f)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				paintable.edits.Add(edit);
			}
		}
		if (change > 0.0005f)
		{
			PineFmod.playOrContinue(paintable.soundEmitter);
		}
		else
		{
			PineFmod.stop(paintable.soundEmitter);
		}
		if (gestureDown)
		{
			PineFmod.playOneShotSoundAttached(paintable.startSound, paintable.gameObject);
			PineFmod.playOrContinue(paintable.soundEmitter);
		}
		else if (gestureUp)
		{
			PineFmod.playOneShotSoundAttached(paintable.endSound, paintable.gameObject);
			PineFmod.stop(paintable.soundEmitter);
		}
	}

	private void brushPaintable(Paintable paintable, in PaintableEdit edit)
	{
		Vector3 position = playerCamera.transform.position;
		Quaternion rotation = playerCamera.transform.rotation;
		playerCamera.transform.position = edit.cameraPosition;
		playerCamera.transform.rotation = QuaternionCompressor.decompress(edit.packedCameraRotation);
		RenderTexture albedoRT = paintable.albedoRT;
		Renderer component = paintable.GetComponent<Renderer>();
		Texture2D brush = paintable.brush;
		Color32 brushColor = edit.brushColor;
		Vector2 brushCenterViewport = edit.brushCenterViewport;
		float brushSizeViewport = edit.brushSizeViewport;
		byte pass = edit.pass;
		CommandBuffer commandBuffer = new CommandBuffer();
		commandBuffer.name = "Pine Draw - Point";
		commandBuffer.SetGlobalTexture("_BaseLayerTexture", albedoRT);
		commandBuffer.SetGlobalTexture("_BrushTexture", brush);
		commandBuffer.SetGlobalColor("_BrushColor", brushColor);
		commandBuffer.SetGlobalVector("_BrushData", new Vector4(brushCenterViewport.x, brushCenterViewport.y, 1f / brushSizeViewport, 1f / brushSizeViewport));
		commandBuffer.SetViewProjectionMatrices(playerCamera.worldToCameraMatrix, playerCamera.projectionMatrix);
		RenderTextureDescriptor desc = new RenderTextureDescriptor(edit.screenWidth, edit.screenHeight, RenderTextureFormat.Depth, 24);
		desc.msaaSamples = 1;
		desc.autoGenerateMips = false;
		desc.useMipMap = false;
		desc.sRGB = false;
		commandBuffer.GetTemporaryRT(Shader.PropertyToID("VisibilityMask"), desc, FilterMode.Point);
		commandBuffer.SetRenderTarget(Shader.PropertyToID("VisibilityMask"));
		commandBuffer.ClearRenderTarget(clearDepth: true, clearColor: true, Color.clear);
		for (int i = 0; i < component.sharedMaterials.Length; i++)
		{
			commandBuffer.DrawRenderer(component, paintablePaintMaterial, i, 3);
		}
		commandBuffer.SetGlobalTexture("_VisibilityMask", Shader.PropertyToID("VisibilityMask"));
		commandBuffer.GetTemporaryRT(Shader.PropertyToID("DrawTemp"), albedoRT.width, albedoRT.height, 0, FilterMode.Point);
		commandBuffer.Blit(albedoRT, Shader.PropertyToID("DrawTemp"), paintableBlitCopyMaterial, 0);
		commandBuffer.SetRenderTarget(Shader.PropertyToID("DrawTemp"));
		commandBuffer.SetViewProjectionMatrices(playerCamera.worldToCameraMatrix, playerCamera.projectionMatrix);
		for (int j = 0; j < component.sharedMaterials.Length; j++)
		{
			commandBuffer.DrawRenderer(component, paintablePaintMaterial, j, pass);
		}
		commandBuffer.Blit(Shader.PropertyToID("DrawTemp"), albedoRT, paintableBlitCopyMaterial, 0);
		commandBuffer.ReleaseTemporaryRT(Shader.PropertyToID("DrawTemp"));
		commandBuffer.ReleaseTemporaryRT(Shader.PropertyToID("VisibilityMask"));
		Graphics.ExecuteCommandBuffer(commandBuffer);
		playerCamera.transform.position = position;
		playerCamera.transform.rotation = rotation;
	}

	private void handleSlotTriggers()
	{
		bool flag = dragData != null;
		Slot[] array = allSlots;
		foreach (Slot slot in array)
		{
			if (slot == null)
			{
				continue;
			}
			foreach (GameObject item in slot.triggerEnterLastFrame)
			{
				if (flag || slot.insertedItem != null || !hasAuthority(item) || (vr.isActive() && tryGetGrabVRData(item, out var grabData) && !(grabData.sceneTransitionTimer >= 1f)))
				{
					continue;
				}
				Item component = item.GetComponent<Item>();
				if (!(component == null) && canBePlacedInSlot(slot, component))
				{
					ItemState itemState = getItemState(component);
					if (itemState != ItemState.Slot && itemState != ItemState.SlotAnimation)
					{
						handleSlotFromThrow(slot, component);
						break;
					}
				}
			}
			slot.triggerEnterLastFrame.Clear();
		}
	}

	private void handleSlotTriggersHost()
	{
		if (!isHost())
		{
			return;
		}
		Slot[] array = allSlots;
		foreach (Slot slot in array)
		{
			if (slot == null)
			{
				continue;
			}
			foreach (GameObject item in slot.triggerEnterLastFrame)
			{
				if (slot.targetable && !(slot.insertedItem != null) && slot.currentSlotState == SlotState.Idle && (!vr.isActive() || !tryGetGrabVRData(item, out var grabData) || grabData.sceneTransitionTimer >= 1f))
				{
					Item component = item.GetComponent<Item>();
					if (!(component == null) && !(component.slot != null) && getItemState(component) == ItemState.World && (UnityUtils.contains(slot.acceptItems, component) || UnityUtils.contains(slot.rejectItems, component)))
					{
						handleSlotFromThrow(slot, component);
						break;
					}
				}
			}
			slot.triggerEnterLastFrame.Clear();
		}
	}

	private void handleSlotFromItemClick(Slot slot, Item item)
	{
		item.transform.position = pcSelectedItemImpostors[0].transform.position;
		item.transform.rotation = pcSelectedItemImpostors[0].transform.rotation;
		activateSlotWithItemLocal(slot, item, SlotPlacement.FromItemClick);
	}

	private void handleSlotFromThrow(Slot slot, Item item)
	{
		activateSlotWithItemLocal(slot, item, SlotPlacement.FromThrow);
	}

	private void handleSlotFromItemDrag(Pointer pointer)
	{
		Slot component = pointer.context.currentTarget.GetComponent<Slot>();
		Item itemDrag = dragData.itemDrag;
		handlePlaceItemScreenSpace(pointer);
		handlePlaceItemSlotForImpostors(dragData.itemDrag.gameObject, dragData.dragImpostors, component);
		if (pointer.gestureUp)
		{
			itemDrag.transform.position = dragData.dragImpostors.itemDragImpostorSlot.transform.position;
			itemDrag.transform.rotation = dragData.dragImpostors.itemDragImpostorSlot.transform.rotation;
			activateSlotWithItemLocal(component, itemDrag, SlotPlacement.FromItemDrag);
		}
	}

	private void handleSlotFromSwapDrag(Pointer pointer)
	{
		Slot slot = pointer.context.currentTarget.GetComponent<Item>().slot;
		Item itemDrag = dragData.itemDrag;
		activateSlotWithItemLocal(slot, itemDrag, SlotPlacement.FromSwapDrag);
	}

	private void activateSlotWithItemLocal(Slot slot, Item item, SlotPlacement placement)
	{
		startInteraction(slot.gameObject);
		bool flag = false;
		if (slot.canSwap && slot.insertedItem != null)
		{
			UnityEngine.Debug.Log($"Swap on slot '{slot.gameObject}': Old item: {slot.insertedItem.gameObject} -> New item: {item.gameObject}");
			GameObject gameObject = slot.insertedItem.gameObject;
			if (gameObject.TryGetComponent<Item>(out var component) && component.carriable)
			{
				removeItemFromSlotLocal(component);
				takeCarriableItem(component);
				flag = true;
			}
			else
			{
				addItemToInventory(gameObject);
				pcChangeItemSelection(gameObject, 0f);
			}
		}
		else
		{
			InventoryItem inventoryItem = ((pcSelectedItem != -1) ? inventory[pcSelectedItem] : null);
			if (inventoryItem != null && inventoryItem.gameObjects.Contains(item.gameObject))
			{
				pcChangeItemSelectionIndex(-1);
			}
		}
		if (isVR())
		{
			forceEndGrabVRForObject(item.gameObject);
		}
		updatePuzzleInteraction(slot.gameObject);
		if (carryingItem != null && !flag)
		{
			dropCarriableItem(carryingItem);
		}
		activateSlotWithItem(slot, item, placement);
		captureHostViewState(slot);
		session.send(new PlaceItemInSlotPacket
		{
			slot = slot,
			item = item,
			placement = placement
		});
	}

	private void handlePlaceItemSlotForImpostors(GameObject itemDrag, DragImpostors dragImpostors, Slot slot)
	{
		dragImpostors.itemDragImpostorScreen.SetActive(value: false);
		dragImpostors.itemDragImpostorWorld.SetActive(value: false);
		dragImpostors.itemDragImpostorSlot.SetActive(value: true);
		bool num = slotTouchFrame == Time.frameCount - 1;
		slotTouchTime += Time.deltaTime;
		if (!num)
		{
			slotTouchTime = 0f;
		}
		slotTouchFrame = Time.frameCount;
		if (slot.transform.IsChildOf(zoomAttachment))
		{
			Vector3 localScale = zoomAttachment.localScale;
			zoomAttachment.localScale = Vector3.one;
			setParent(dragImpostors.itemDragImpostorSlot.transform, zoomAttachment);
			dragImpostors.itemDragImpostorSlot.transform.localScale = itemDrag.transform.localScale;
			zoomAttachment.localScale = localScale;
			setParent(dragImpostors.itemDragImpostorSlot.transform, null);
		}
		else
		{
			dragImpostors.itemDragImpostorSlot.transform.SetGlobalScale(itemDrag.transform.lossyScale);
		}
		float t = slotTouchTime * 2f;
		if (gameState.current == GameState.Zoom)
		{
			t = 1f;
		}
		dragImpostors.itemDragImpostorSlot.transform.position = Vector3.Lerp(dragImpostors.itemDragImpostorSlot.transform.position, slot.pivot.position, t);
		dragImpostors.itemDragImpostorSlot.transform.rotation = Quaternion.Slerp(dragImpostors.itemDragImpostorSlot.transform.rotation, slot.pivot.rotation, t);
	}

	private void handlePlaceItemJigsawForImpostors(Pointer pointer, JigsawPiece piece, Jigsaw jigsaw)
	{
		DragImpostors dragImpostors = dragData.dragImpostors;
		dragImpostors.itemDragImpostorScreen.SetActive(value: false);
		dragImpostors.itemDragImpostorWorld.SetActive(value: true);
		dragImpostors.itemDragImpostorSlot.SetActive(value: false);
		if (jigsawLastUsedImpostorId != dragImpostors.id)
		{
			jigsawLastUsedImpostorId = dragImpostors.id;
		}
		dragImpostors.itemDragImpostorWorld.transform.position = getJigsawPiecePosition(jigsaw, piece, pointer);
		dragImpostors.itemDragImpostorWorld.transform.rotation = piece.transform.rotation;
	}

	public bool isSlotCloseEnough(Slot slot)
	{
		float neoRange = ((slot.interactionMaxDistance == -1f) ? pointerReach : slot.interactionMaxDistance);
		return inReach(playerCamera.transform.position, slot.transform.position, neoRange);
	}

	public void activateSlotWithItemNonSynced(Slot slot, Item item)
	{
		activateSlotWithItem(slot, item, SlotPlacement.FromNonSyncedCode);
	}

	private void activateSlotWithItem(Slot slot, Item item, SlotPlacement placement)
	{
		UnityEngine.Debug.Log($"activating {slot.name} with {item.name} mode: {placement} frame: {Time.frameCount}");
		bool flag = slot.transform.IsChildOf(zoomAttachment);
		Vector3 localScale = zoomAttachment.localScale;
		zoomAttachment.localScale = Vector3.one;
		setParent(item.transform, zoomAttachment);
		zoomAttachment.localScale = (flag ? localScale : Vector3.one);
		slot.originalItemInZoomScale = item.transform.localScale;
		setParent(item.transform, levelContainerTransform);
		zoomAttachment.localScale = localScale;
		slot.originalZoomScale = localScale;
		item.gameObject.SetActive(value: true);
		item.targetable = false;
		item.targetPriority = slot.targetPriority + 1;
		item.inSlotAnimation = true;
		slot.backgroundUpdate = true;
		slot.targetable = false;
		slot.itemForCurrentInteraction = item;
		slot.itemTravellingStartPosition = item.transform.position;
		slot.itemTravellingStartRotation = item.transform.rotation;
		slot.isSilentPlacement = placement == SlotPlacement.FromNonSyncedCode && (isLevelLogicInit || placement == SlotPlacement.FromCoreInit);
		slot.currentSlotState = SlotState.ItemTravellingToSlot;
		slot.backgroundTime = ((placement == SlotPlacement.FromItemClick || placement == SlotPlacement.FromThrow) ? 0f : 0.25f);
		if (slot.backgroundTime >= 0.25f)
		{
			handleSlotBackgroundItemTravellingToSlot(slot, 0f);
			handleSlotBackgroundItemArrivedToSlot(slot, 0f);
			if (!isLevelLogicInit && placement != SlotPlacement.FromCoreInit)
			{
				updateItemStates();
			}
		}
	}

	private void handleSlotBackground(Slot slot, float dt)
	{
		if (slot.currentSlotState == SlotState.ItemTravellingToSlot)
		{
			handleSlotBackgroundItemTravellingToSlot(slot, dt);
		}
		else if (slot.currentSlotState == SlotState.ItemArrivedToSlot)
		{
			handleSlotBackgroundItemArrivedToSlot(slot, dt);
		}
		else if (slot.currentSlotState == SlotState.ItemAnimatingInSlot)
		{
			handleSlotBackgroundItemAnimatingInSlot(slot, dt);
		}
		else if (slot.currentSlotState == SlotState.ItemAnimationDone)
		{
			handleSlotBackgroundItemAnimationDone(slot, dt);
		}
		else if (slot.currentSlotState == SlotState.ItemBeingEjectedFromSlot)
		{
			handleSlotBackgroundItemBeingEjectedFromSlot(slot, dt);
		}
		slot.backgroundUpdate = slot.currentSlotState != SlotState.Idle;
	}

	private void handleSlotBackgroundItemTravellingToSlot(Slot slot, float dt)
	{
		Item itemForCurrentInteraction = slot.itemForCurrentInteraction;
		float num = Mathf.Clamp01(UnityUtils.smootherStep(0f, 1f, slot.backgroundTime / 0.25f));
		itemForCurrentInteraction.transform.position = Vector3.Lerp(slot.itemTravellingStartPosition, slot.pivot.position, num);
		itemForCurrentInteraction.transform.rotation = Quaternion.Slerp(slot.itemTravellingStartRotation, slot.pivot.rotation, num);
		if (num >= 1f)
		{
			slot.currentSlotState = SlotState.ItemArrivedToSlot;
			itemForCurrentInteraction.inSlotAnimation = false;
			itemForCurrentInteraction.slot = slot;
			slot.insertedItem = itemForCurrentInteraction;
		}
	}

	private void handleSlotBackgroundItemArrivedToSlot(Slot slot, float dt)
	{
		Item itemForCurrentInteraction = slot.itemForCurrentInteraction;
		bool num = Array.IndexOf(slot.acceptItems, itemForCurrentInteraction) != -1;
		if ((num ? slot.onAcceptItemPlaced : slot.onRejectItemPlaced) != SlotPlaceBehaviour.ItemEjectsToInventory && isInInventory(itemForCurrentInteraction.gameObject))
		{
			removeItemFromInventory(itemForCurrentInteraction.gameObject);
		}
		if (num)
		{
			if (!slot.isSilentPlacement)
			{
				PineFmod.playOneShotSoundAttached(slot.soundOnAcceptItemPlaced, slot.gameObject);
			}
		}
		else if (!slot.isSilentPlacement)
		{
			PineFmod.playOneShotSoundAttached(slot.soundOnRejectItemPlaced, slot.gameObject);
		}
		if (!slot.isSilentPlacement)
		{
			PineFmod.playOneShotSoundAttached("event:/SFX/GENERAL/uiToggle", slot.gameObject);
		}
		setParent(itemForCurrentInteraction.transform, slot.transform);
		slot.currentSlotState = ((slot.animationType == SlotAnimationType.None) ? SlotState.ItemAnimationDone : SlotState.ItemAnimatingInSlot);
		slot.backgroundTime = 0f;
	}

	private void handleSlotBackgroundItemAnimatingInSlot(Slot slot, float dt)
	{
		Item insertedItem = slot.insertedItem;
		bool flag = Array.IndexOf(slot.acceptItems, insertedItem) != -1;
		float num = (flag ? (slot.rotateKeyTurnDuration * Mathf.Abs(slot.rotateKeyTurnCount)) : slot.rotateKeyTurnDuration);
		float num2 = ((num > 0f) ? (slot.backgroundTime / num) : 1f);
		if (slot.animationType == SlotAnimationType.RotateKey)
		{
			float num3 = (flag ? (num2 * slot.rotateKeyTurnCount) : (Mathf.PingPong(num2, 0.5f) * Mathf.Sign(slot.rotateKeyTurnCount)));
			insertedItem.transform.rotation = slot.pivot.transform.rotation * Quaternion.Euler(slot.rotateKeyTurnAxis * (360f * num3));
			insertedItem.transform.position = slot.pivot.transform.position;
		}
		else if (slot.animationType == SlotAnimationType.KeyAnimation)
		{
			if (insertedItem.TryGetComponent<Animation>(out var component))
			{
				component.clip.SampleAnimation(component.gameObject, num2 * component.clip.length);
			}
			else
			{
				UnityEngine.Debug.LogError(string.Format("Item '{0}' is missing '{1}' component, but slot uses '{2} = {3}'!", insertedItem.name, "Animation", "animationType", SlotAnimationType.KeyAnimation), insertedItem);
			}
		}
		else
		{
			UnityEngine.Debug.LogError(string.Format("Unsupported '{0} = {1}'!", "animationType", slot.animationType));
		}
		if (num2 >= 1f)
		{
			slot.currentSlotState = SlotState.ItemAnimationDone;
		}
	}

	private void handleSlotBackgroundItemAnimationDone(Slot slot, float dt)
	{
		Item insertedItem = slot.insertedItem;
		bool flag = Array.IndexOf(slot.acceptItems, insertedItem) != -1;
		if (flag)
		{
			slot.isUnlocked = true;
		}
		switch (flag ? slot.onAcceptItemPlaced : slot.onRejectItemPlaced)
		{
		case SlotPlaceBehaviour.ItemEjectsToInventory:
		case SlotPlaceBehaviour.ItemEjectsToWorld:
			slot.backgroundTime = 0f;
			slot.currentSlotState = SlotState.ItemBeingEjectedFromSlot;
			break;
		case SlotPlaceBehaviour.ItemMergesWithSlot:
			handleSlotBackgroundTransitionToIdle(slot, dt, isSlotTargetable: false, insertedItem, isItemTargetable: false);
			break;
		case SlotPlaceBehaviour.ItemStaysInSlot:
			handleSlotBackgroundTransitionToIdle(slot, dt, !flag || !slot.disableSlotOnUnlock, insertedItem, isItemTargetable: true);
			break;
		}
		callOrDeferOnSlot(slot);
	}

	private void handleSlotBackgroundItemBeingEjectedFromSlot(Slot slot, float dt)
	{
		Item itemForCurrentInteraction = slot.itemForCurrentInteraction;
		if (itemForCurrentInteraction == null)
		{
			UnityEngine.Debug.LogError($"[{base.name}] Item is null for slot '{slot}'!", slot);
			return;
		}
		itemForCurrentInteraction.transform.position += slot.pivot.transform.TransformDirection(slot.ejectDirection) * dt;
		if (((slot.ejectDuration > 0f) ? Mathf.Clamp01(slot.backgroundTime / slot.ejectDuration) : 1f) < 1f)
		{
			return;
		}
		bool flag = Array.IndexOf(slot.acceptItems, itemForCurrentInteraction) != -1;
		SlotPlaceBehaviour slotPlaceBehaviour = (flag ? slot.onAcceptItemPlaced : slot.onRejectItemPlaced);
		setParent(itemForCurrentInteraction.transform, levelContainerTransform);
		switch (slotPlaceBehaviour)
		{
		case SlotPlaceBehaviour.ItemEjectsToInventory:
		{
			if (hasAuthority(itemForCurrentInteraction.gameObject))
			{
				pcChangeItemSelection(itemForCurrentInteraction.gameObject, 0f);
				if (!isInInventory(itemForCurrentInteraction.gameObject))
				{
					addItemToInventory(itemForCurrentInteraction.gameObject, returnBorrowed: false, 0, 1f, shouldRemoveFromSlotIfNeeded: false);
				}
			}
			Vector3 position = playerCamera.transform.InverseTransformPoint(itemForCurrentInteraction.transform.position);
			Quaternion rotation = Quaternion.Inverse(playerCamera.transform.rotation) * itemForCurrentInteraction.transform.rotation;
			itemImpostorPoseInitial = new Pose(position, rotation);
			itemForCurrentInteraction.gameObject.SetActive(value: false);
			break;
		}
		case SlotPlaceBehaviour.ItemEjectsToWorld:
			itemForCurrentInteraction.rbOverrides = new RigidbodyOverrides
			{
				velocity = slot.pivot.transform.TransformDirection(slot.ejectDirection)
			};
			break;
		default:
			UnityEngine.Debug.LogError(string.Format("Unsupported '{0} = {1}'!", "SlotPlaceBehaviour", slotPlaceBehaviour));
			break;
		}
		handleSlotBackgroundTransitionToIdle(slot, dt, !flag || !slot.disableSlotOnUnlock, itemForCurrentInteraction, isItemTargetable: true);
		restoreItemScaleForSlot(slot, itemForCurrentInteraction, itemForCurrentInteraction.transform.parent);
		removeItemFromSlot(itemForCurrentInteraction);
	}

	private void handleSlotBackgroundTransitionToIdle(Slot slot, float dt, bool isSlotTargetable, Item item, bool isItemTargetable)
	{
		item.targetable = isItemTargetable;
		slot.targetable = isSlotTargetable;
		slot.currentSlotState = SlotState.Idle;
		if (isLocalPlayerInteracting(slot.gameObject))
		{
			stopInteraction(slot.gameObject);
		}
	}

	private void handleSlotCancel(Slot slot)
	{
		if (slot.itemForCurrentInteraction != null)
		{
			slot.itemForCurrentInteraction.targetable = true;
			slot.itemForCurrentInteraction.slot = null;
			slot.itemForCurrentInteraction.inSlotAnimation = false;
			bool flag = isProcessingPacket;
			isProcessingPacket = false;
			if (slot.itemForCurrentInteraction.carriable)
			{
				takeCarriableItem(slot.itemForCurrentInteraction);
			}
			else
			{
				addItemToInventory(slot.itemForCurrentInteraction.gameObject);
			}
			isProcessingPacket = flag;
		}
		slot.targetable = true;
		slot.backgroundUpdate = false;
		slot.currentSlotState = SlotState.Idle;
	}

	public void removeItemFromSlotLocal(Item item)
	{
		Slot slot = item.slot;
		if (!(slot == null))
		{
			bool num = myInteractingObjects.Contains(slot.gameObject);
			if (!num)
			{
				startInteraction(slot.gameObject);
			}
			session.send(new RemoveItemFromSlotPacket
			{
				item = item,
				slot = slot
			});
			removeItemFromSlot(item);
			if (!num)
			{
				stopInteraction(slot.gameObject);
			}
		}
	}

	[LuaAPI]
	public void removeItemFromSlot(Item item)
	{
		Slot slot = item.slot;
		if (slot == null)
		{
			return;
		}
		if (slot.currentSlotState != SlotState.Idle)
		{
			slot.backgroundUpdate = false;
			slot.currentSlotState = SlotState.Idle;
			if (isLocalPlayerInteracting(slot.gameObject))
			{
				stopInteraction(slot.gameObject);
			}
		}
		slot.targetable = true;
		slot.insertedItem = null;
		slot.isUnlocked = false;
		slot.itemForCurrentInteraction = null;
		restoreItemScaleForSlot(slot, item, levelContainerTransform);
		item.slot = null;
		item.inSlotAnimation = false;
		item.targetable = true;
		PineFmod.playOneShotSoundAttached(slot.soundOnRemove, slot.gameObject);
		callOrDeferOnRemoveFromSlot(slot, item);
	}

	private bool canBePlacedInSlot(Slot slot, Item item)
	{
		if (item == null)
		{
			return false;
		}
		if (deferredInteractives.Contains(item))
		{
			return false;
		}
		if (item.slot != null)
		{
			return false;
		}
		if (getItemState(item) == ItemState.SlotAnimation)
		{
			return false;
		}
		if (!slot.targetable)
		{
			return false;
		}
		if (slot.currentSlotState != SlotState.Idle)
		{
			return false;
		}
		if (!slot.canSwap && slot.insertedItem != null)
		{
			return false;
		}
		if (slot.canSwap && slot.insertedItem != null && pcSelectedItem == -1 && Controller.isActive())
		{
			return false;
		}
		if (!UnityUtils.contains(slot.acceptItems, item))
		{
			return UnityUtils.contains(slot.rejectItems, item);
		}
		return true;
	}

	private void restoreItemScaleForSlot(Slot slot, Item item, Transform oldParent)
	{
		bool flag = slot.transform.IsChildOf(zoomAttachment);
		Vector3 localScale = zoomAttachment.localScale;
		zoomAttachment.localScale = (flag ? slot.originalZoomScale : Vector3.one);
		setParent(item.transform, zoomAttachment);
		item.transform.localScale = slot.originalItemInZoomScale;
		zoomAttachment.localScale = Vector3.one;
		setParent(item.transform, oldParent);
		zoomAttachment.localScale = localScale;
	}

	private void takeCarriableItem(Item item)
	{
		if (item == null)
		{
			UnityEngine.Debug.LogError("Cannot take carriable item as it is null.");
			return;
		}
		if (pcSelectedItemGhost != null)
		{
			UnityEngine.Object.Destroy(pcSelectedItemGhost);
			pcSelectedItemGhost = null;
			GameObject[] array = pcSelectedItemImpostors;
			for (int i = 0; i < array.Length; i++)
			{
				UnityEngine.Object.Destroy(array[i]);
			}
			pcSelectedItemImpostors = null;
		}
		startInteraction(item.gameObject);
		session.send(new CarriableStartPacket
		{
			item = item
		});
		if (item.slot != null)
		{
			removeItemFromSlotLocal(item);
		}
		item.hasRigidbody = true;
		carryingItem = item;
		if (localPlayerData != null)
		{
			localPlayerData.carriableItem = item;
		}
		if (getRelevantPuzzlesFor(item.gameObject).Contains(getCurrentPuzzleIndex()))
		{
			inventoryHistoryCurrentPuzzle.Add(item.gameObject);
		}
		if (!item.soundPickup.IsNull)
		{
			PineFmod.playOneShotSoundAttached(item.soundPickup, item.gameObject);
		}
		pcSelectedItemImpostors = new GameObject[2];
		pcSelectedItemImpostors[0] = ImpostorClone.create(impostorContext, item.gameObject, LayerMask.NameToLayer("Zoom"), strip: true, setupTransparentZoomAction);
		setupTransparentZoom(pcSelectedItemImpostors[0].transform);
		pcSelectedItemImpostors[1] = ImpostorClone.create(impostorContext, item.gameObject, LayerMask.NameToLayer("Default"), strip: true, setupSecondAction, "", ImpostorClone.StrippingFlags.AllowAll);
		setupSecond(pcSelectedItemImpostors[1].transform);
		for (int j = 0; j < pcSelectedItemImpostors.Length; j++)
		{
			setParent(pcSelectedItemImpostors[j].transform, levelContainerTransform);
			pcSelectedItemImpostors[j].name = "Item Clone";
			pcSelectedItemImpostors[j].transform.position = item.transform.position;
			pcSelectedItemImpostors[j].transform.rotation = item.transform.rotation;
			pcSelectedItemImpostors[j].transform.localScale = item.transform.localScale;
			itemImpostorScaleInitial = pcSelectedItemImpostors[j].transform.localScale;
			setParent(pcSelectedItemImpostors[j].transform, playerCamera.transform);
		}
		shouldItemImpostortBeVisible = true;
		carryingItemBounds = computeLocalBounds(item.gameObject);
		pcSelectedItemGhost = ImpostorClone.create(impostorContext, item.gameObject, LayerMask.NameToLayer("PlacingGhost"), strip: true, null, "DisableGhost", ImpostorClone.StrippingFlags.None, automaticSync: false, "EnableGhost");
		pcSelectedItemGhost.SetActive(value: false);
		Canvas[] componentsInChildren = pcSelectedItemGhost.GetComponentsInChildren<Canvas>(includeInactive: true);
		for (int num = componentsInChildren.Length - 1; num >= 0; num--)
		{
			componentsInChildren[num].enabled = false;
		}
		pcSelectedItemGhost.name = "Item Ghost Clone: " + item.name;
		ImpostorClone.replaceMaterials(pcSelectedItemGhost, pcSelectedItemGhostMaterial);
		shouldItemGhostBeVisible = false;
		itemImpostorPoseInitial = new Pose(pcSelectedItemImpostors[0].transform.localPosition, pcSelectedItemImpostors[0].transform.localRotation);
		itemImpostorWorldSlotWeight = 0f;
		itemImpostorInitialWeight = 0f;
		item.gameObject.SetActive(value: false);
		callOrDeferOnPickUpCarriableItem(item);
		void setupSecond(Transform clone)
		{
			ImpostorClone.replaceMaterialsKinds(clone.gameObject, clearDepthAndMotion, clearDepthAndMotionAlphaTest, ignoreDepthAndMotion);
		}
		void setupSecondAction(ImpostorClone clone)
		{
			if (clone != null)
			{
				setupSecond(clone.transform);
			}
		}
		static void setupTransparentZoom(Transform clone)
		{
			if (!(clone == null))
			{
				ImpostorClone.replaceLightLayers(clone.gameObject, 32u);
				Transform[] componentsInChildren2 = clone.GetComponentsInChildren<Transform>(includeInactive: true);
				foreach (Transform transform in componentsInChildren2)
				{
					if (transform.gameObject.CompareTag("ExamineTransparentEffect"))
					{
						transform.gameObject.layer = LayerMask.NameToLayer("ZoomTransparent");
					}
				}
			}
		}
		static void setupTransparentZoomAction(ImpostorClone clone)
		{
			if (clone != null)
			{
				setupTransparentZoom(clone.transform);
			}
		}
	}

