	private void handleSurfaceSlotPlacementFromClick(SurfaceSlot surfaceSlot, Item placedObject, Pose initialPose)
	{
		startInteraction(surfaceSlot.gameObject);
		handleSurfaceSlotPlacement(surfaceSlot, placedObject, initialPose);
		session.send(new SurfaceSlotInteractionPacket
		{
			surfaceSlot = surfaceSlot,
			item = placedObject,
			initialPose = initialPose
		});
	}

	private void handleSurfaceSlotPlacement(SurfaceSlot surfaceSlot, Item item, Pose initialPose)
	{
		UnityEngine.Debug.Log(base.name + "handleSurfaceSlotPlacement");
		item.transform.position = initialPose.position;
		item.transform.rotation = initialPose.rotation;
		int interestPointIndex = -1;
		for (int i = 0; i < surfaceSlot.interestPoints.Count; i++)
		{
			SurfaceSlot.InterestPoint interestPoint = surfaceSlot.interestPoints[i];
			Vector3 vector = surfaceSlot.transform.TransformPoint(interestPoint.localPosition);
			if ((item.transform.position - vector).magnitude <= interestPoint.radius)
			{
				interestPointIndex = i;
				break;
			}
		}
		surfaceSlot.currentPlacement = new SurfaceSlot.Placement(surfaceSlot, item, interestPointIndex);
		surfaceSlot.state = SurfaceSlot.SurfaceSlotState.PlacedWaiting;
		surfaceSlot.backgroundUpdate = true;
		item.surfaceSlot = surfaceSlot;
	}

	private void handleSurfaceSlotBackground(SurfaceSlot surfaceSlot, float dt)
	{
		Item item;
		if (surfaceSlot.state == SurfaceSlot.SurfaceSlotState.PlacedWaiting)
		{
			if (surfaceSlot.backgroundTime > 0.7f)
			{
				surfaceSlot.backgroundTime = 0f;
				surfaceSlot.state = (surfaceSlot.ejectToInventory ? SurfaceSlot.SurfaceSlotState.AnimatingToInventory : SurfaceSlot.SurfaceSlotState.Animating);
				callOrDeferOnSurfaceSlot(surfaceSlot.currentPlacement);
			}
		}
		else if (surfaceSlot.state == SurfaceSlot.SurfaceSlotState.AnimatingToInventory)
		{
			item = surfaceSlot.currentPlacement.placedObject;
			if (surfaceSlot.isAnimated && item.TryGetComponent<Animation>(out var component))
			{
				component.clip.SampleAnimation(item.gameObject, component.clip.length * surfaceSlot.backgroundTime);
				if (surfaceSlot.backgroundTime >= component.clip.length)
				{
					ejectToInventory();
					setToIdle();
				}
			}
			else
			{
				ejectToInventory();
				setToIdle();
			}
		}
		else
		{
			if (surfaceSlot.state != SurfaceSlot.SurfaceSlotState.Animating)
			{
				return;
			}
			Item placedObject = surfaceSlot.currentPlacement.placedObject;
			if (surfaceSlot.isAnimated && placedObject.TryGetComponent<Animation>(out var component2))
			{
				component2.clip.SampleAnimation(placedObject.gameObject, component2.clip.length * surfaceSlot.backgroundTime);
				if (surfaceSlot.backgroundTime >= component2.clip.length)
				{
					setToIdle();
				}
			}
			else
			{
				setToIdle();
			}
		}
		void ejectToInventory()
		{
			if (hasAuthority(item))
			{
				bool flag = inventory.FindIndex(0, inventory.Count, (InventoryItem x) => x.gameObjects.Contains(item.gameObject)) != -1;
				transitionItemToInventory(item.gameObject, flag);
				pcChangeItemSelection(item.gameObject, (!flag) ? 1 : 0);
			}
			item.surfaceSlot = null;
		}
		void setToIdle()
		{
			surfaceSlot.state = SurfaceSlot.SurfaceSlotState.Idle;
			surfaceSlot.backgroundUpdate = false;
			surfaceSlot.currentPlacement = null;
			if (isLocalPlayerInteracting(surfaceSlot.gameObject))
			{
				stopInteraction(surfaceSlot.gameObject);
			}
		}
	}

	private void handleSurfaceSlotCancel(SurfaceSlot surfaceSlot)
	{
		if (surfaceSlot.currentPlacement != null)
		{
			Item placedObject = surfaceSlot.currentPlacement.placedObject;
			placedObject.slot = null;
			bool flag = isProcessingPacket;
			isProcessingPacket = false;
			addItemToInventory(placedObject.gameObject);
			isProcessingPacket = flag;
			surfaceSlot.currentPlacement = null;
		}
		surfaceSlot.backgroundUpdate = false;
		surfaceSlot.state = SurfaceSlot.SurfaceSlotState.Idle;
	}

	private void handleNpcEnter(Npc npc)
	{
		levelLogic.onNpcStart(npc);
		syncNpcVisuals(npc);
	}

	private void handleNpcButtonHover()
	{
		if (topZoomContextSafe(out var context) && context.selectedType == ScreenTargetType.NPC)
		{
			Npc component = context.selected.GetComponent<Npc>();
			PineFmod.playOneShotSoundAttached(component.soundButtonHover, component.gameObject);
		}
	}

	private void handleNpcButtonPressed(int choiceIndex)
	{
		if (topZoomContextSafe(out var context) && context.selectedType == ScreenTargetType.NPC)
		{
			Npc component = context.selected.GetComponent<Npc>();
			if (isHost())
			{
				handleNpcButtonPressed(component, component.currentLine, choiceIndex);
				return;
			}
			component.clientWaitingForResponse = true;
			session.send(new NpcDialoguePacket
			{
				npc = component,
				orderIndex = component.currentLine,
				choiceIndex = choiceIndex
			});
			syncNpcVisuals(component);
		}
	}

	private void handleNpcButtonPressed(Npc npc, int lineIndex, int choiceIndex)
	{
		if (isHost())
		{
			if (npc.currentLine != lineIndex)
			{
				UnityEngine.Debug.Log($"Npc error: Client sent an answer for a different question. current local question:{npc.currentLine} got question: {lineIndex}");
				return;
			}
			session.send(new NpcDialoguePacket
			{
				npc = npc,
				orderIndex = lineIndex,
				choiceIndex = choiceIndex
			}, allowSendInMessageResponse: true);
		}
		else
		{
			npc.clientWaitingForResponse = false;
		}
		PineFmod.playOneShotSoundAttached(npc.soundButtonPressed, npc.gameObject);
		UnityEngine.Debug.Log($"on Choice {npc} orderIndex:{lineIndex} choiceIndex:{choiceIndex} {base.name}");
		npc.changedOrderIndexInLevelLogic = false;
		levelLogic.onNpcChoiceSelected(npc, lineIndex, choiceIndex);
		if (npc.currentLine < npc.dialogue.dialogueLines.Count - 1)
		{
			if (!npc.changedOrderIndexInLevelLogic)
			{
				npc.currentLine = npc.dialogue.dialogueLines[npc.currentLine].choicesNeo[choiceIndex].goToIndex;
			}
		}
		else if (npc.exitZoomOnDialogueEnd)
		{
			increaseZoomCounter(npc);
		}
		syncNpcVisuals(npc);
	}

	private void syncNpcVisuals(Npc npc)
	{
		if (npc.dialogue.dialogueLines.Count <= npc.currentLine)
		{
			return;
		}
		DialogueLine currentLine = npc.getCurrentLine();
		dialogueName.text = "<b>" + Localization.translate(currentLine.name) + "</b> : ";
		dialogueLine.text = Localization.translate(currentLine.displayText);
		for (int i = 0; i < dialogueChoices.Length; i++)
		{
			dialogueChoices[i].gameObject.SetActive(i < currentLine.choicesNeo.Count);
			if (i < currentLine.choicesNeo.Count)
			{
				dialogueChoicesText[i].text = Localization.translate(currentLine.choicesNeo[i].text);
			}
		}
		dialogueWaitingUI.gameObject.SetActive(npc.clientWaitingForResponse);
		dialogueMainUI.gameObject.SetActive(!npc.clientWaitingForResponse);
		if (!currentLine.lineSound.IsNull)
		{
			PineFmod.playSoundOnEmitter(npc.soundEmitter, currentLine.lineSound);
		}
	}

