	}

	private void handlePoseEnterLocal(Pointer pointer)
	{
		handlePoseEnterLocal(pointer.context.target.GetComponent<CharacterPose>(), transitionIn: true);
	}

	public void handlePoseEnterLocal(CharacterPose characterPose, bool transitionIn)
	{
		UnityEngine.Debug.Log(string.Format("{0}: {1}, transition: {2}", "handlePoseEnterLocal", characterPose, transitionIn), characterPose);
		if (characterPose == null)
		{
			UnityEngine.Debug.LogError("Pose cannot be null");
			return;
		}
		if (localPlayerData.characterPoseContext.poseState != CharacterPoseState.None)
		{
			if (localPlayerData.characterPoseContext.pose == characterPose)
			{
				UnityEngine.Debug.LogError("Cannot enter pose the player is already in.");
			}
			else
			{
				UnityEngine.Debug.LogError("Cannot enter pose because you are already in pose.");
			}
			return;
		}
		if (netPlayers.Any((GamePlayerData x) => x.characterPoseContext?.pose == characterPose))
		{
			UnityEngine.Debug.Log("Cannot enter pose while another player is in the same pose");
			return;
		}
		handlePoseEnter(localPlayerData, characterPose, transitionIn);
		startInteraction(characterPose.gameObject);
		session.send(new CharacterPoseEnterPacket
		{
			pose = characterPose,
			transitionIn = transitionIn
		}, isLoadingSaveFile);
		updateCharacterPoseUI("%leave%");
	}

	public void updateCharacterPoseUI(string translatableText)
	{
		CharacterPose pose = localPlayerData.characterPoseContext.pose;
		removeGameFrameSource(GameFrameSourceType.Pose);
		if (pose == null)
		{
			UnityEngine.Debug.Log("No character pose set for the player, cannot update character pose UI");
		}
		else if (!pose.lockedInPose)
		{
			List<VisualControl> list = new List<VisualControl>();
			VisualControl visualControl = new VisualControl("back", ControllerButtonActionType.GameBack, translatableText, VisualControl.ControlType.Button, VisualControl.Position.BotRight);
			visualControl.addEscape();
			list.Add(visualControl);
			addGameFrameSource(GameFrameSourceType.Pose, list);
		}
	}

	public void handlePoseEnter(GamePlayerData player, CharacterPose characterPose, bool transitionIn)
	{
		if (isProcessingPacket && !isLoadingSaveFile && session.isLocalPlayer(player.id))
		{
			callOrDeferOnPose(player.id, characterPose, CharacterPoseState.TransitionIn);
		}
		else if (!Is.perfTest())
		{
			UnityEngine.Debug.Log(string.Format("{0}: {1}, player: {2}, transition: {3}", "handlePoseEnter", characterPose, session.getUsername(player.id), transitionIn), characterPose);
			player.characterPoseContext = new CharacterPoseContext
			{
				pose = characterPose,
				poseState = CharacterPoseState.TransitionIn,
				transitionInPosition = ((player == localPlayerData) ? playerCamera.transform.position : player.lastTransformPose.position),
				transitionInRotation = ((player == localPlayerData) ? playerCamera.transform.rotation : player.lastTransformPose.rotation),
				pivotRotation = characterPose.eyeRotation,
				currentRotationOffset = Vector2.zero,
				transitionIn = transitionIn,
				lastPlayerPosition = ((player == localPlayerData) ? playerLocation : player.lastTransformPose.position),
				lastPlayerRotation = targetRotation
			};
			characterPose.backgroundUpdate = true;
			callOrDeferOnPose(player.id, characterPose, CharacterPoseState.TransitionIn);
			PineFmod.playOneShotSoundAttached(characterPose.enterSound, characterPose.gameObject);
		}
	}

	public void handlePoseLeaveLocal(CharacterPose characterPose)
	{
		UnityEngine.Debug.Log(string.Format("{0}: {1}", "handlePoseLeaveLocal", characterPose), characterPose);
		if (hasDeferred(characterPose))
		{
			UnityEngine.Debug.LogError("Tried to leave pose from pose that is not validated by host.", characterPose);
			return;
		}
		CharacterPoseContext characterPoseContext = localPlayerData.characterPoseContext;
		if (characterPoseContext.poseState != CharacterPoseState.None && !(characterPoseContext.pose != characterPose))
		{
			if (characterPoseContext.pose != null && characterPoseContext.pose.exitPointTransform != null && NavMesh.SamplePosition(characterPoseContext.pose.exitPointTransform.position, out var hit, 1000f, -1))
			{
				Quaternion quaternion = Quaternion.LookRotation(characterPoseContext.pose.exitPointTransform.forward);
				targetRotation = new Vector2(quaternion.eulerAngles.y, Mathf.DeltaAngle(0f, quaternion.eulerAngles.x));
				setPlayerLocation(hit.position);
			}
			else
			{
				setPlayerLocation(characterPoseContext.lastPlayerPosition);
				targetRotation = characterPoseContext.lastPlayerRotation;
			}
			localPlayerData.characterPoseContext.transitionOutStartPosition = contestedCameraPosition.value();
			localPlayerData.characterPoseContext.transitionOutStartRotation = contestedCameraRotation.value();
			handlePoseLeave(localPlayerData, characterPose);
			captureHostViewState(characterPose);
			session.send(new CharacterPoseLeavePacket
			{
				pose = characterPose
			});
			removeGameFrameSource(GameFrameSourceType.Pose);
			stopInteraction(characterPose.gameObject);
		}
	}

	public void handlePoseLeave(GamePlayerData player, CharacterPose characterPose)
	{
		UnityEngine.Debug.Log(string.Format("{0}: {1}, player: {2}", "handlePoseLeave", characterPose, session.getUsername(player.id)), characterPose);
		if (isProcessingPacket && player == localPlayerData)
		{
			callOrDeferOnPose(player.id, characterPose, CharacterPoseState.TransitionOut);
			return;
		}
		player.characterPoseContext.poseState = CharacterPoseState.TransitionOut;
		PineFmod.playOneShotSoundAttached(characterPose.exitSound, characterPose.gameObject);
		callOrDeferOnPose(player.id, characterPose, CharacterPoseState.TransitionOut);
		characterPose.backgroundUpdate = true;
		characterPose.backgroundTime = 0f;
	}

	private void handlePoseBackground(CharacterPose pose, float dt)
	{
		GamePlayerData gamePlayerData = getAllPlayers().Find((GamePlayerData x) => x.characterPoseContext?.pose == pose);
		if (gamePlayerData == null)
		{
			pose.backgroundUpdate = false;
			return;
		}
		CharacterPoseContext characterPoseContext = gamePlayerData.characterPoseContext;
		float num = UnityUtils.smootherStep(0f, 1f, pose.backgroundTime / 0.75f);
		CharacterPoseState poseState = gamePlayerData.characterPoseContext.poseState;
		if (poseState == CharacterPoseState.TransitionIn || poseState == CharacterPoseState.InPose)
		{
			if (!characterPoseContext.transitionIn)
			{
				num = 1f;
			}
			if (gamePlayerData == localPlayerData)
			{
				contestedCameraPosition.set(ContestedPose.Game, Vector3.Lerp(characterPoseContext.transitionInPosition, pose.eyePosition, num), oneFrame: true);
				contestedCameraPosition.set(ContestedPose.Pose, Vector3.Lerp(characterPoseContext.transitionInPosition, pose.eyePosition, num), oneFrame: true);
				if (num < 1f)
				{
					contestedCameraRotation.set(ContestedPose.Game, Quaternion.Lerp(characterPoseContext.transitionInRotation, pose.eyeRotation, num), oneFrame: true);
					contestedCameraRotation.set(ContestedPose.Pose, Quaternion.Lerp(characterPoseContext.transitionInRotation, pose.eyeRotation, num), oneFrame: true);
				}
				else
				{
					Quaternion newValue = pose.eyeRotation * Quaternion.Euler(characterPoseContext.currentRotationOffset);
					contestedCameraRotation.set(ContestedPose.Game, newValue, oneFrame: true);
					contestedCameraRotation.set(ContestedPose.Pose, newValue, oneFrame: true);
					currentRotation = (targetRotation = new Vector2(newValue.eulerAngles.y, newValue.eulerAngles.x));
					gamePlayerData.characterPoseContext.poseState = CharacterPoseState.InPose;
				}
				setPlayerLocation(pose.transform.position);
			}
			else if (num >= 1f)
			{
				gamePlayerData.characterPoseContext.poseState = CharacterPoseState.InPose;
			}
			if (gamePlayerData.selectedCharacter != null)
			{
				HumanPose humanPose = default(HumanPose);
				pose.humanPoseHandler.GetHumanPose(ref humanPose);
				gamePlayerData.selectedCharacter.transform.parent.position = pose.transform.position;
				gamePlayerData.selectedCharacter.transform.parent.rotation = pose.transform.rotation;
				gamePlayerData.selectedCharacter.getHumanPoseHandler()?.SetHumanPose(ref humanPose);
			}
		}
		else if (gamePlayerData.characterPoseContext.poseState == CharacterPoseState.TransitionOut)
		{
			if (gamePlayerData == localPlayerData && !isProcessingPacket)
			{
				contestedCameraPosition.set(ContestedPose.Game, headPov.transform.position);
				Vector3 newValue2 = Vector3.Lerp(characterPoseContext.transitionOutStartPosition, headPov.transform.position, num);
				contestedCameraPosition.set(ContestedPose.Pose, newValue2, oneFrame: true);
				Quaternion newValue3 = Quaternion.Lerp(characterPoseContext.transitionOutStartRotation, Quaternion.Euler(targetRotation.y, targetRotation.x, 0f), num);
				contestedCameraRotation.set(ContestedPose.Pose, newValue3, oneFrame: true);
			}
			if (pose.backgroundTime >= 1f)
			{
				gamePlayerData.characterPoseContext = CharacterPoseContext.None;
			}
		}
	}

	private void handlePoseCancel(CharacterPose pose)
	{
		CharacterPoseContext characterPoseContext = localPlayerData.characterPoseContext;
		if (characterPoseContext != null && !(characterPoseContext.pose != pose))
		{
			pose.backgroundTime = 0f;
			pose.backgroundUpdate = false;
			setPlayerLocation(characterPoseContext.lastPlayerPosition);
			contestedCameraPosition.set(ContestedPose.Game, headPov.transform.position);
			contestedCameraPosition.set(ContestedPose.Pose, headPov.transform.position, oneFrame: true);
			contestedCameraRotation.set(ContestedPose.Pose, Quaternion.Euler(targetRotation.y, targetRotation.x, 0f), oneFrame: true);
			localPlayerData.characterPoseContext = CharacterPoseContext.None;
		}
	}

	public void handleChessablePiece(Pointer pointer)
	{
		ChessablePiece component = pointer.context.target.GetComponent<ChessablePiece>();
		Chessable chessable = component.chessable;
		if (chessable.targetable && !chessable.backgroundUpdate)
		{
			PineFmod.playOneShotSoundAttached("event:/Sound Effects/04 Items/Wood/Chess/Chess_Piece_Pickup", chessable.gameObject);
			if (chessable.currentSelectedPiece == null)
			{
				startInteraction(chessable.gameObject);
				handleChessablePiece(component);
				session.send(new ChessablePieceStartPacket
				{
					piece = component
				});
			}
			else
			{
				handleChessablePiece(component);
				session.send(new ChessablePieceEndPacket
				{
					tile = chessable.getTileForPiece(component)
				});
				stopInteraction(chessable.gameObject);
			}
		}
	}

	public void handleChessableTile(Pointer pointer)
	{
		ChessableTile component = pointer.context.target.GetComponent<ChessableTile>();
		Chessable chessable = component.chessable;
		if (!chessable.backgroundUpdate && chessable.currentSelectedPiece != null)
		{
			handleChessableTile(component);
			session.send(new ChessablePieceEndPacket
			{
				tile = component
			});
			stopInteraction(chessable.gameObject);
		}
	}

	public void handleChessablePiece(ChessablePiece piece)
	{
		Chessable chessable = piece.chessable;
		if (chessable.currentSelectedPiece == null)
		{
			chessable.currentSelectedPiece = piece;
			chessable.pieceState = Chessable.PieceState.SelectingPiece;
			chessable.backgroundUpdate = true;
		}
		else
		{
			handleChessableTile(chessable.getTileForPiece(piece));
		}
	}

	public void handleChessableTile(ChessableTile tile)
	{
		Chessable chessable = tile.chessable;
		ChessablePiece pieceForTile = chessable.getPieceForTile(tile);
		ChessableTile tileForPiece = chessable.getTileForPiece(chessable.currentSelectedPiece);
		bool num = pieceForTile == null || chessable.currentSelectedPiece.isWhite() != pieceForTile.isWhite();
		bool flag = tileForPiece != tile;
		if (num && flag)
		{
			chessable.moveTile = tile;
			chessable.backgroundUpdate = true;
			chessable.pieceState = Chessable.PieceState.MovingPiece;
		}
		else
		{
			chessable.backgroundUpdate = true;
			chessable.pieceState = Chessable.PieceState.DeselectingPiece;
		}
	}

	public void handleChessableBackground(Chessable chessable, float dt)
	{
		if (chessable.pieceState == Chessable.PieceState.SelectingPiece)
		{
			ChessableTile tileForPiece = chessable.getTileForPiece(chessable.currentSelectedPiece);
			Vector3 b = tileForPiece.transform.position + tileForPiece.transform.up * 0.05f;
			float num = Mathf.Clamp01(UnityUtils.smootherStep(0f, 1f, chessable.backgroundTime * 2f));
			chessable.currentSelectedPiece.transform.position = Vector3.Lerp(chessable.currentSelectedPiece.transform.position, b, num);
			if (num >= 1f)
			{
				chessable.backgroundUpdate = false;
			}
		}
		else if (chessable.pieceState == Chessable.PieceState.DeselectingPiece)
		{
			Vector3 position = chessable.getTileForPiece(chessable.currentSelectedPiece).transform.position;
			float num2 = Mathf.Clamp01(UnityUtils.smootherStep(0f, 1f, chessable.backgroundTime * 2f));
			chessable.currentSelectedPiece.transform.position = Vector3.Lerp(chessable.currentSelectedPiece.transform.position, position, num2);
			if (num2 >= 1f)
			{
				chessable.backgroundUpdate = false;
				chessable.currentSelectedPiece = null;
			}
		}
		else
		{
			if (chessable.pieceState != Chessable.PieceState.MovingPiece)
			{
				return;
			}
			float num3 = Mathf.Clamp01(UnityUtils.smootherStep(0f, 1f, chessable.backgroundTime * 2f));
			Vector3 position2 = chessable.moveTile.transform.position;
			chessable.currentSelectedPiece.transform.position = Vector3.Lerp(chessable.currentSelectedPiece.transform.position, position2, num3);
			if (num3 > 0.2f)
			{
				Chessable.PiecePosition piecePosition = chessable.piecesOnTiles.Find((Chessable.PiecePosition x) => x.tile == chessable.moveTile);
				if (piecePosition != null)
				{
					piecePosition.piece.gameObject.SetActive(value: false);
					chessable.piecesOnTiles.Remove(piecePosition);
				}
			}
			if (num3 >= 1f)
			{
				Chessable.PiecePosition item = chessable.piecesOnTiles.Find((Chessable.PiecePosition x) => x.piece == chessable.currentSelectedPiece);
				chessable.currentSelectedPiece.transform.position = chessable.moveTile.transform.position;
				chessable.piecesOnTiles.Remove(item);
				chessable.piecesOnTiles.Add(new Chessable.PiecePosition(chessable.currentSelectedPiece, chessable.moveTile));
				PineFmod.playOneShotSoundAttached("event:/Sound Effects/04 Items/Wood/Chess/Chess_Piece_Place", chessable.currentSelectedPiece.gameObject);
				chessable.backgroundUpdate = false;
				chessable.currentSelectedPiece = null;
			}
		}
	}

	private void handleDraggable(Pointer pointer)
	{
		GameObject target = pointer.context.target;
		DraggableAnnotation draggableAnnotation = pointer.context.targetAnnotation as DraggableAnnotation;
		Draggable draggable = target.GetComponent<Draggable>();
		Transform anchorObject = playerCamera.transform;
		if (controlMode.current == ControlMode.VR)
		{
			anchorObject = vr.getControllerForId(pointer.gestureFingerId).transform;
			if (pointers.Find((Pointer ptr) => ptr.context.interactionSessionId == draggable.sessionId && ptr != pointer) != null)
			{
				return;
			}
		}
		if (draggable.sessionId != pointer.context.interactionSessionId)
		{
			draggable.sessionId = pointer.context.interactionSessionId;
			startInteraction(target);
			controllerStartInteraction(pointer);
			draggable.idleTime = 0f;
			dragRigidbodyLocation = draggable.draggableRigidbody.transform.InverseTransformPoint(pointer.context.targetHitPoint);
			dragSolverIterations = draggable.draggableRigidbody.solverIterations;
			dragCollisionDetectionMode = draggable.draggableRigidbody.collisionDetectionMode;
			dragConstraints = draggable.draggableRigidbody.constraints;
			draggable.draggableRigidbody.interpolation = RigidbodyInterpolation.Interpolate;
			draggable.draggableRigidbody.solverIterations = 24;
			draggable.draggableRigidbody.collisionDetectionMode = CollisionDetectionMode.Continuous;
			oldAngularDrag = draggable.draggableRigidbody.angularDamping;
			draggable.draggableRigidbody.angularDamping = draggable.angularDragOverride;
			if (draggable.dragConstraintFlags != RigidbodyConstraints.None)
			{
				draggable.draggableRigidbody.constraints = draggable.dragConstraintFlags;
			}
			manipulation = ((draggableAnnotation != null) ? draggableAnnotation.manipulationTypeOverride : draggable.manipulationType);
			if (Vector3.Dot(Vector3.up, draggable.transform.TransformDirection(draggable.originalUp)) < 0.75f)
			{
				manipulation = Draggable.ManipulationType.Free;
			}
			dragLineRenderer.gameObject.SetActive(value: true);
			cameraSpaceDragPoint = anchorObject.InverseTransformPoint(pointer.context.targetHitPoint);
			Collider[] componentsInChildren = draggable.draggableRigidbody.GetComponentsInChildren<Collider>();
			foreach (Collider collider in componentsInChildren)
			{
				if (!collider.gameObject.CompareTag("KeepFrictionDuringDrag"))
				{
					originalFrictions[collider] = collider.material;
					PhysicsMaterial physicsMaterial = new PhysicsMaterial();
					if (manipulation == Draggable.ManipulationType.Free)
					{
						physicsMaterial.staticFriction = 0.25f;
						physicsMaterial.dynamicFriction = 0.25f;
						physicsMaterial.bounciness = 0f;
					}
					else
					{
						physicsMaterial.staticFriction = 0f;
						physicsMaterial.dynamicFriction = 0f;
						physicsMaterial.bounciness = 0f;
					}
					physicsMaterial.bounceCombine = PhysicsMaterialCombine.Minimum;
					physicsMaterial.frictionCombine = PhysicsMaterialCombine.Minimum;
					collider.material = physicsMaterial;
				}
			}
			lastPositionDragObject = target.gameObject.transform.position;
			handleDraggableStart(draggable);
			session.send(new DraggableStartPacket
			{
				draggable = draggable
			});
		}
		else if (draggable.draggableRigidbody == null)
		{
			return;
		}
		draggableMovementTotal += pointer.gestureMovementViewport.x;
		if (dragLineRenderer.gameObject.activeSelf)
		{
			calculateOriginAndDiff(out var origin, out var diff);
			dragLineRenderer.positionCount = 4;
			dragLineRenderer.SetPosition(0, origin + diff * 0f);
			dragLineRenderer.SetPosition(1, origin + diff * 0.05f);
			dragLineRenderer.SetPosition(2, origin + diff * 0.95f);
			dragLineRenderer.SetPosition(3, origin + diff * 1f);
		}
		performOnFixedUpdate(delegate
		{
			if ((draggableMovementTotal != 0f || manipulation != Draggable.ManipulationType.OnlyRotation) && !(draggable.draggableRigidbody == null))
			{
				calculateOriginAndDiff(out var origin2, out var diff2);
				if (manipulation == Draggable.ManipulationType.OnlyRotation)
				{
					Vector3 torque = new Vector3(0f, (0f - draggableMovementTotal) * 2000f, 0f);
					draggable.draggableRigidbody.AddTorque(torque, ForceMode.Acceleration);
					dragLineRenderer.gameObject.SetActive(value: false);
				}
				else
				{
					Vector3 vector = Vector3.ClampMagnitude(4f * diff2, 25f) - draggable.draggableRigidbody.linearVelocity;
					Vector3 force = Vector3.ClampMagnitude(50f * vector, 60f);
					if (draggable.forcePoint == Draggable.ForcePoint.HitPoint)
					{
						draggable.draggableRigidbody.AddForceAtPosition(force, origin2, ForceMode.Acceleration);
					}
					else if (draggable.forcePoint == Draggable.ForcePoint.CenterOfMass)
					{
						draggable.draggableRigidbody.AddForce(force, ForceMode.Acceleration);
					}
					else if (draggable.forcePoint == Draggable.ForcePoint.CustomLocal)
					{
						draggable.draggableRigidbody.AddForceAtPosition(force, draggable.draggableRigidbody.transform.TransformPoint(draggable.customLocal), ForceMode.Acceleration);
					}
					if (manipulation == Draggable.ManipulationType.Horizontal)
					{
						draggable.draggableRigidbody.angularVelocity = new Vector3(0f, draggable.draggableRigidbody.angularVelocity.y * 0.85f, 0f);
					}
					else if (manipulation == Draggable.ManipulationType.HorizontalNoRotation)
					{
						draggable.draggableRigidbody.angularVelocity = Vector3.zero;
					}
				}
				draggableMovementTotal = 0f;
			}
		});
		float num2 = Vector3.Distance(lastPositionDragObject, target.gameObject.transform.position);
		lastPositionDragObject = target.gameObject.transform.position;
		bool flag = num2 > 0.001f;
		if (!(num2 > 0.0001f))
		{
			_ = draggable.idleTime;
			_ = 0.1f;
			draggable.idleTime += Time.deltaTime;
		}
		if (flag && isVR())
		{
			float intensity = 0.01f + (1f - Mathf.Exp(-5f * num2)) * 0.49f;
			vr.vibrateController(pointer.gestureFingerId, intensity, 0.1f);
		}
		handleDraggableInteraction(draggable, flag);
		session.send(new DraggableInteractionPacket
		{
			draggable = draggable,
			hasMoved = flag
		});
		if (pointer.gestureUp)
		{
			handleDraggableFinalize(draggable);
			session.send(new DraggableFinalizePacket
			{
				draggable = draggable
			});
			stopInteraction(draggable.gameObject);
			controllerEndInteraction();
		}
		void calculateOriginAndDiff(out Vector3 reference, out Vector3 reference2)
		{
			reference = draggable.draggableRigidbody.transform.TransformPoint(dragRigidbodyLocation);
			Vector3 vector = anchorObject.TransformPoint(cameraSpaceDragPoint);
			if (controlMode.current == ControlMode.VirtualGamepad)
			{
				float magnitude = cameraSpaceDragPoint.magnitude;
				vector = playerCamera.ViewportToWorldPoint(new Vector3(pointer.gesturePositionViewport.x, pointer.gesturePositionViewport.y, magnitude));
			}
			reference2 = vector - reference;
			if (manipulation != Draggable.ManipulationType.Free)
			{
				reference2.y *= 0f;
			}
		}
	}

	private void handleDraggableStart(Draggable draggable)
	{
		PineFmod.playOneShotSoundAttached(draggable.soundDragStart, draggable.gameObject);
	}

	private void handleDraggableInteraction(Draggable draggable, bool hasMovedSound)
	{
		if (hasMovedSound)
		{
			PineFmod.playOrContinue(draggable.soundEmitter);
		}
		else
		{
			PineFmod.pause(draggable.soundEmitter);
		}
	}

	private void handleDraggableCancel(Draggable draggable)
	{
		handleDraggableFinalize(draggable);
	}

	private void handleDraggableFinalize(Draggable draggable)
	{
		PineFmod.playOneShotSoundAttached(draggable.soundDragEnd, draggable.gameObject);
		PineFmod.stop(draggable.soundEmitter);
		if (isProcessingPacket)
		{
			return;
		}
		clearDragLineRenderer();
		draggable.draggableRigidbody.solverIterations = dragSolverIterations;
		draggable.draggableRigidbody.collisionDetectionMode = dragCollisionDetectionMode;
		draggable.draggableRigidbody.constraints = dragConstraints;
		draggable.draggableRigidbody.angularDamping = oldAngularDrag;
		foreach (KeyValuePair<Collider, PhysicsMaterial> originalFriction in originalFrictions)
		{
			originalFriction.Deconstruct(out var key, out var value);
			Collider collider = key;
			PhysicsMaterial material = value;
			collider.material = material;
		}
		originalFrictions.Clear();
		if (!(Physics.gravity.sqrMagnitude > 0.1f))
		{
			return;
		}
		draggable.draggableRigidbody.isKinematic = true;
		draggable.draggableRigidbody.linearVelocity = Vector3.zero;
		draggable.draggableRigidbody.angularVelocity = Vector3.zero;
		performOnEarlyUpdate(delegate
		{
			if (draggable.draggableRigidbody == null)
			{
				UnityEngine.Debug.LogError($"Rigidbody of Draggable '{draggable}' should not be null.", draggable);
			}
			else
			{
				draggable.draggableRigidbody.isKinematic = false;
				draggable.draggableRigidbody.linearVelocity = Vector3.zero;
				draggable.draggableRigidbody.angularVelocity = Vector3.zero;
			}
		});
	}

	private void handleDraggableBackground(Draggable draggable, float dt)
	{
	}

	private void handleJigsawHoverZoom(Pointer pointer)
	{
		Jigsaw component = pointer.context.currentTarget.GetComponent<Jigsaw>();
		Item item = ((dragData != null) ? dragData.itemDrag : pointer.context.target.GetComponent<Item>());
		if (tryGetJigsawPieceItem(component, item, out var output))
		{
			handlePlaceItemScreenSpace(pointer);
			handlePlaceItemJigsawForImpostors(pointer, output, component);
			if (pointer.gestureUp)
			{
				startInteraction(component.gameObject);
				Vector3 jigsawPiecePosition = getJigsawPiecePosition(component, output, pointer);
				handleJigsawItemAdd(output, jigsawPiecePosition);
				session.send(new JigsawAddPiecePacket
				{
					piece = output,
					position = jigsawPiecePosition
				});
				component.deferedPiece = output;
				stopInteraction(component.gameObject);
			}
		}
	}

	private void handleJigsawHoverSelectedItem(Pointer pointer, Item item)
	{
		Jigsaw component = pointer.context.currentTarget.GetComponent<Jigsaw>();
		if (tryGetJigsawPieceItem(component, item, out var output) && pointer.gestureUp)
		{
			startInteraction(component.gameObject);
			Vector3 jigsawPiecePosition = getJigsawPiecePosition(component, output, pointer);
			session.send(new JigsawAddPiecePacket
			{
				piece = output,
				position = jigsawPiecePosition
			});
			component.deferedPiece = output;
			handleJigsawItemAdd(output, jigsawPiecePosition);
			stopInteraction(component.gameObject);
		}
	}

	private void handleJigsawItemAdd(JigsawPiece piece, Vector3 position)
	{
		Jigsaw jigsaw = piece.jigsaw;
		jigsaw.selectedPiece = piece;
		if (!isProcessingPacket)
		{
			selectJigsawPiece(jigsaw, piece);
		}
		piece.transform.position = position;
		piece.gameObject.SetActive(value: true);
		callOrDeferOnJigsaw(jigsaw, piece, JigsawEvent.PiecePlaced);
		piece.linkedItem.gameObject.SetActive(value: false);
	}

	private bool didHandleJigsawAnnotation(Pointer pointer)
	{
		if (pointer.context.targetAnnotation != null)
		{
			if (!pointer.gestureUp)
			{
				return true;
			}
			JigsawAnnotation jigsawAnnotation = pointer.context.targetAnnotation as JigsawAnnotation;
			rotateJigsawPiece(jigsawAnnotation.piece.jigsaw, jigsawAnnotation.piece, (jigsawAnnotation.direction == JigsawAnnotation.AnnotationDirection.Left) ? 1 : (-1));
			return true;
		}
		return false;
	}

	private void handleJigsaw(Pointer pointer)
	{
		didHandleJigsawAnnotation(pointer);
	}

	private void handleJigsawPiece(Pointer pointer)
	{
		if (didHandleJigsawAnnotation(pointer))
		{
			return;
		}
		JigsawPiece component = pointer.context.target.GetComponent<JigsawPiece>();
		Jigsaw jigsaw = component.jigsaw;
		if (component == null && pointer.context.targetHelper == null)
		{
			return;
		}
		jigsaw.plane = ((jigsaw.areaLimitsPlaneOrigin != null) ? new Plane(-jigsaw.areaLimitsPlaneOrigin.forward, jigsaw.areaLimitsPlaneOrigin.position) : new Plane(jigsaw.worldNormal, jigsaw.jigsawPieceOriginalPosition));
		if (jigsaw.sessionId != pointer.context.interactionSessionId)
		{
			jigsaw.sessionId = pointer.context.interactionSessionId;
			startInteraction(jigsaw.gameObject);
			controllerStartInteraction(pointer, virtualHiddenButMovable: true);
			bool num = pointer.context.targetHelper == null;
			if (num)
			{
				jigsaw.selectedPiece = component;
			}
			handleJigsawStart(jigsaw.selectedPiece);
			session.send(new JigsawStartPacket
			{
				piece = jigsaw.selectedPiece
			});
			if (num)
			{
				selectJigsawPiece(jigsaw, jigsaw.selectedPiece);
			}
		}
		Transform obj = jigsaw.selectedPiece.transform;
		Vector3 position = obj.position;
		handleJigsawInteractionMove(jigsaw, pointer);
		Vector3 position2 = obj.position;
		obj.position = position;
		JigsawPiece selectedPiece = jigsaw.selectedPiece;
		handleJigsawInteraction(selectedPiece, position2);
		session.send(new JigsawInteractionPacket
		{
			piece = selectedPiece,
			piecePosition = position
		});
		if (pointer.gestureUp)
		{
			handleJigsawFinalize(selectedPiece);
			session.send(new JigsawFinalizePacket
			{
				piece = selectedPiece
			});
			if (jigsaw.selectedPiece == null)
			{
				clearJigsawSelection(jigsaw);
			}
			stopInteraction(jigsaw.gameObject);
			controllerEndInteraction(resetPosition: false);
		}
	}

	private void handleJigsawStart(JigsawPiece piece)
	{
		Jigsaw jigsaw = piece.jigsaw;
		jigsaw.selectedPiece = piece;
		connectJigsawPieces(jigsaw, jigsaw.selectedPiece);
		PineFmod.playOneShotSoundAttached(jigsaw.soundStart, jigsaw.gameObject);
		jigsaw.jigsawPieceOriginalPosition = jigsaw.selectedPiece.transform.position;
		jigsaw.jigsawPieceRotationOffset = Vector3.zero;
		if (isProcessingPacket)
		{
			clearJigsawSelection(jigsaw);
		}
	}

	private void handleJigsawInteractionMove(Jigsaw jigsaw, Pointer pointer)
	{
		if (jigsaw.plane.Raycast(pointer.gestureFirstRay, out var enter) && jigsaw.plane.Raycast(pointer.gestureRay, out var enter2))
		{
			Vector3 point = pointer.gestureFirstRay.GetPoint(enter);
			Vector3 vector = pointer.gestureRay.GetPoint(enter2) - point;
			jigsaw.selectedPiece.transform.position = jigsaw.jigsawPieceOriginalPosition + vector + jigsaw.jigsawPieceRotationOffset;
			if (jigsaw.areaLimitsPlaneOrigin != null)
			{
				Vector3 vector2 = jigsaw.selectedPiece.transform.TransformPoint(jigsaw.selectedPiece.sharedPivot);
				Vector3 vector3 = jigsaw.selectedPiece.transform.position - vector2;
				Vector3 position = jigsaw.areaLimitsPlaneOrigin.InverseTransformPoint(vector2);
				position.x = Mathf.Clamp(position.x, 0f - jigsaw.areaLimits.x, jigsaw.areaLimits.x);
				position.y = Mathf.Clamp(position.y, 0f - jigsaw.areaLimits.y, jigsaw.areaLimits.y);
				position.z = 0f;
				jigsaw.selectedPiece.transform.position = jigsaw.areaLimitsPlaneOrigin.TransformPoint(position) + vector3;
			}
			if (jigsaw.snapPosition != Vector3.zero)
			{
				Vector3 position2 = jigsaw.selectedPiece.transform.position;
				Vector3 originalPosition = jigsaw.selectedPiece.originalPosition;
				Vector3 lhs = position2 - originalPosition;
				Vector3 normalized = Vector3.Cross(Vector3.up, jigsaw.worldNormal).normalized;
				Vector3 normalized2 = Vector3.Cross(jigsaw.worldNormal, normalized).normalized;
				float num = Vector3.Dot(lhs, normalized);
				float num2 = Vector3.Dot(lhs, jigsaw.worldNormal);
				float num3 = Vector3.Dot(lhs, normalized2);
				num = ((jigsaw.snapPosition.x != 0f) ? (Mathf.Round(num / jigsaw.snapPosition.x) * jigsaw.snapPosition.x) : num);
				num2 = ((jigsaw.snapPosition.y != 0f) ? (Mathf.Round(num2 / jigsaw.snapPosition.y) * jigsaw.snapPosition.y) : num2);
				num3 = ((jigsaw.snapPosition.z != 0f) ? (Mathf.Round(num3 / jigsaw.snapPosition.z) * jigsaw.snapPosition.z) : num3);
				Vector3 position3 = originalPosition + num * normalized + num2 * jigsaw.worldNormal + num3 * normalized2;
				jigsaw.selectedPiece.transform.position = position3;
			}
		}
	}

	private void handleJigsawInteraction(JigsawPiece piece, Vector3 piecePosition)
	{
		if (piece == null)
		{
			UnityEngine.Debug.LogError("[" + base.name + "] Jigsaw piece is null.");
			return;
		}
		Jigsaw jigsaw = piece.jigsaw;
		Vector3 position = jigsaw.selectedPiece.transform.position;
		jigsaw.selectedPiece.transform.position = piecePosition;
		jigsaw.selectedPiece.transform.position += jigsaw.worldNormal * jigsaw.pieceLift;
		if (position != jigsaw.selectedPiece.transform.position)
		{
			PineFmod.playOrContinue(jigsaw.soundEmitter);
		}
		else
		{
			PineFmod.stop(jigsaw.soundEmitter);
		}
		foreach (JigsawPiece connectedPiece in jigsaw.selectedPiece.connectedPieces)
		{
			if (!(connectedPiece == jigsaw.selectedPiece))
			{
				connectedPiece.connectTo(jigsaw.selectedPiece);
			}
		}
	}

	private bool tryGetJigsawPieceItem(Jigsaw jigsaw, Item item, out JigsawPiece output)
	{
		output = null;
		JigsawPiece[] componentsInChildren = jigsaw.GetComponentsInChildren<JigsawPiece>(includeInactive: true);
		foreach (JigsawPiece jigsawPiece in componentsInChildren)
		{
			if (!(jigsawPiece.linkedItem != item))
			{
				output = jigsawPiece;
				return true;
			}
		}
		return false;
	}

	private Vector3 getJigsawPiecePosition(Jigsaw jigsaw, JigsawPiece piece, Pointer pointer)
	{
		if (new Plane(jigsaw.worldNormal, piece.transform.position).Raycast(pointer.gestureRay, out var enter))
		{
			Vector3 vector = piece.transform.rotation * piece.pivot;
			return pointer.gestureRay.GetPoint(enter) - vector;
		}
		return Vector3.zero;
	}

	private bool connectJigsawPieces(Jigsaw jigsaw, JigsawPiece piece)
	{
		if (!jigsaw.allowConnectingPieces)
		{
			return false;
		}
		bool result = false;
		List<JigsawPiece> list = new List<JigsawPiece>();
		foreach (JigsawPiece connectedPiece in piece.connectedPieces)
		{
			Jigsaw.JigsawConnectable[] connectablePieces = jigsaw.connectablePieces;
			foreach (Jigsaw.JigsawConnectable jigsawConnectable in connectablePieces)
			{
				if (!(jigsawConnectable.piece1 != connectedPiece) || !(jigsawConnectable.piece2 != connectedPiece))
				{
					JigsawPiece jigsawPiece = ((jigsawConnectable.piece1 == connectedPiece) ? jigsawConnectable.piece2 : jigsawConnectable.piece1);
					if (jigsawPiece.targetable && !piece.connectedPieces.Contains(jigsawPiece) && jigsaw.arePiecesConnected(jigsawPiece, piece))
					{
						list.AddRange(jigsawPiece.connectedPieces);
						result = true;
					}
				}
			}
		}
		piece.connectedPieces.AddRange(list);
		foreach (JigsawPiece connectedPiece2 in piece.connectedPieces)
		{
			connectedPiece2.connectedPieces = piece.connectedPieces;
		}
		foreach (JigsawPiece connectedPiece3 in piece.connectedPieces)
		{
			connectedPiece3.recalculateSharedPivot();
		}
		return result;
	}

	public void deselectJigsaw(Jigsaw jigsaw)
	{
		if (jigsaw.selectedPiece != null)
		{
			handleJigsawCancel(jigsaw.selectedPiece);
		}
	}

	private void handleJigsawCancel(JigsawPiece piece)
	{
		handleJigsawFinalize(piece);
		clearJigsawSelection(piece.jigsaw);
		piece.jigsaw.selectedPiece = null;
	}

	private void handleJigsawFinalize(JigsawPiece piece)
	{
		Jigsaw jigsaw = piece.jigsaw;
		if (jigsaw.selectedPiece == null)
		{
			UnityEngine.Debug.LogError("[handleJigsawFinalize] Jigsaw piece cannot be null in finalize.");
			return;
		}
		callOrDeferOnJigsaw(jigsaw, jigsaw.selectedPiece, JigsawEvent.PieceReleased);
		jigsaw.selectedPiece.transform.position = jigsaw.plane.ClosestPointOnPlane(jigsaw.selectedPiece.transform.position);
		handleJigsawSnap(jigsaw);
		foreach (JigsawPiece connectedPiece in jigsaw.selectedPiece.connectedPieces)
		{
			if (!(connectedPiece == jigsaw.selectedPiece))
			{
				connectedPiece.connectTo(jigsaw.selectedPiece);
			}
		}
		if (connectJigsawPieces(jigsaw, jigsaw.selectedPiece))
		{
			List<JigsawPiece> connectedPieces = jigsaw.selectedPiece.connectedPieces;
			JigsawPiece jigsawPiece = connectedPieces[connectedPieces.Count - 1];
			foreach (JigsawPiece connectedPiece2 in jigsaw.selectedPiece.connectedPieces)
			{
				if (connectedPiece2 != jigsawPiece)
				{
					connectedPiece2.connectTo(jigsawPiece);
				}
			}
			jigsaw.selectedPiece.connectTo(jigsaw.selectedPiece.connectedPieces[1]);
			selectInteractiveHighlightList(jigsaw.selectedPiece.connectedPieces);
		}
		PineFmod.stop(jigsaw.soundEmitter);
		PineFmod.playOneShotSoundAttached(jigsaw.soundEnd, jigsaw.gameObject);
		clearJigsawSelection(jigsaw);
		jigsaw.selectedPiece = null;
	}

	private bool handleJigsawSnap(Jigsaw jigsaw)
	{
		if (!jigsaw.allowSnap)
		{
			return false;
		}
		if (!(Vector3.Distance(jigsaw.selectedPiece.transform.position, jigsaw.selectedPiece.originalPosition) < jigsaw.clearancePosition))
		{
			return false;
		}
		if (!(Quaternion.Angle(jigsaw.selectedPiece.transform.rotation, jigsaw.selectedPiece.originalRotation) < jigsaw.clearanceRotation))
		{
			return false;
		}
		foreach (JigsawPiece connectedPiece in jigsaw.selectedPiece.connectedPieces)
		{
			connectedPiece.transform.position = connectedPiece.originalPosition;
			connectedPiece.transform.rotation = connectedPiece.originalRotation;
			connectedPiece.targetable = false;
			connectedPiece.blocksRaycasts = false;
			callOrDeferOnJigsaw(jigsaw, connectedPiece, JigsawEvent.PieceSnapped);
		}
		if (jigsaw.areAllPiecesSnapped())
		{
			callOrDeferOnJigsaw(jigsaw, jigsaw.selectedPiece, JigsawEvent.AllPiecesSnapped);
		}
		return true;
	}

	private void handleJigsawBackground(Jigsaw jigsaw, float dt)
	{
		jigsawLeftInput.update();
		jigsawRightInput.update();
		handleInput(jigsawLeftInput, -1, ref jigsawLastSmallStepLeft);
		handleInput(jigsawRightInput, 1, ref jigsawLastSmallStepRight);
		void handleInput(StateMachine<InputState> timestamp, int direction, ref float lastSmallStep)
		{
			if (timestamp.current == InputState.Down)
			{
				timestamp.changeState(InputState.Hold);
				rotateJigsawPiece(jigsaw, jigsaw.selectedPiece, direction);
			}
			if (timestamp.current == InputState.Hold && timestamp.time > 0.5f && lastSmallStep + 0.15f < Time.time)
			{
				lastSmallStep = Time.time;
				rotateJigsawPiece(jigsaw, jigsaw.selectedPiece, direction);
			}
			if (timestamp.current == InputState.Up)
			{
				timestamp.changeState(InputState.None);
			}
		}
	}

	private void rotateJigsawPiece(Jigsaw jigsaw, JigsawPiece piece, int direction)
	{
		if (!piece.backgroundUpdate)
		{
			bool num = myInteractingObjects.Contains(jigsaw.gameObject);
			if (!num)
			{
				startInteraction(jigsaw.gameObject);
			}
			float rotationSnaps = jigsaw.rotationSnaps;
			float num2 = 360f / rotationSnaps;
			float num3 = (float)(Mathf.RoundToInt(Vector3.SignedAngle(jigsaw.worldUp, piece.transform.TransformDirection(jigsaw.localUpPiece), jigsaw.worldNormal) / num2) + direction) * num2;
			rotateJigsawPieceLocal(jigsaw, piece, num3);
			session.send(new JigsawPieceRotationPacket
			{
				piece = piece,
				angle = num3
			});
			if (!num)
			{
				stopInteraction(jigsaw.gameObject);
			}
		}
	}

	private void rotateJigsawPieceLocal(Jigsaw jigsaw, JigsawPiece piece, float targetAngle)
	{
		foreach (JigsawPiece connectedPiece in piece.connectedPieces)
		{
			if (connectedPiece.backgroundUpdate)
			{
				connectedPiece.transform.RotateAround(connectedPiece.transform.TransformPoint(connectedPiece.sharedPivot), connectedPiece.jigsaw.worldNormal, connectedPiece.remainingRotation);
			}
		}
		float num = Vector3.SignedAngle(jigsaw.worldUp, piece.transform.TransformDirection(jigsaw.localUpPiece), jigsaw.worldNormal);
		float remainingRotation = targetAngle - num;
		Vector3 position = piece.transform.position;
		foreach (JigsawPiece connectedPiece2 in piece.connectedPieces)
		{
			connectedPiece2.remainingRotation = remainingRotation;
			PineFmod.playOrContinue(connectedPiece2.jigsaw.soundEmitter);
			connectedPiece2.backgroundUpdate = true;
		}
		Vector3 vector = piece.transform.position - position;
		jigsaw.jigsawPieceRotationOffset += vector;
	}

	private void handleJigsawPieceBackground(JigsawPiece piece, float dt)
	{
		float num = Mathf.MoveTowards(piece.remainingRotation, 0f, dt * 180f * piece.jigsaw.pieceRotationSpeed);
		float angle = piece.remainingRotation - num;
		piece.remainingRotation = num;
		Vector3 position = piece.transform.position;
		piece.transform.RotateAround(piece.transform.TransformPoint(piece.sharedPivot), piece.jigsaw.worldNormal, angle);
		if (Mathf.Approximately(piece.remainingRotation, 0f))
		{
			PineFmod.stop(piece.jigsaw.soundEmitter);
			piece.transform.RotateAround(piece.transform.TransformPoint(piece.sharedPivot), piece.jigsaw.worldNormal, piece.remainingRotation);
			piece.remainingRotation = 0f;
			piece.backgroundUpdate = false;
		}
		if (piece.jigsaw.selectedPiece == piece)
		{
			Vector3 vector = piece.transform.position - position;
			piece.jigsaw.jigsawPieceRotationOffset += vector;
		}
	}

	private void clearJigsawSelection(Jigsaw jigsaw)
	{
		currentlySelectedJigsaw = null;
		jigsaw.backgroundUpdate = false;
		removeGameFrameSource(GameFrameSourceType.Jigsaw);
		removeInteractiveHighlight();
	}

	private void selectJigsawPiece(Jigsaw jigsaw, JigsawPiece piece)
	{
		currentlySelectedJigsaw = jigsaw;
		if (gameState.current == GameState.Zoom)
		{
			if (piece.connectedPieces.Count > 1)
			{
				selectInteractiveHighlightList(piece.connectedPieces);
			}
			else
			{
				selectInteractiveHighlight(piece);
			}
		}
		jigsaw.backgroundUpdate = true;
		jigsawLeftInput.changeState(InputState.None);
		jigsawRightInput.changeState(InputState.None);
		if (gameState.current == GameState.Zoom)
		{
			List<GameFrameSourceData> list = gameFrameSourceData;
			if (list[list.Count - 1].type != GameFrameSourceType.Jigsaw)
			{
				_ = jigsaw.allowRotation;
			}
		}
	}

	private void calculateCornersOfBounds(GameObject go, out Vector2 upPoint, out Vector2 rightPoint, out Vector2 leftPoint, out Vector2 downPoint, out Vector2 centerScreenPos)
	{
		Bounds localBounds = go.GetComponent<Renderer>().localBounds;
		Vector3[] array = new Vector3[8];
		Vector3 min = localBounds.min;
		Vector3 max = localBounds.max;
		array[0] = go.transform.TransformPoint(new Vector3(min.x, min.y, min.z));
		array[1] = go.transform.TransformPoint(new Vector3(min.x, min.y, max.z));
		array[2] = go.transform.TransformPoint(new Vector3(min.x, max.y, min.z));
		array[3] = go.transform.TransformPoint(new Vector3(min.x, max.y, max.z));
		array[4] = go.transform.TransformPoint(new Vector3(max.x, min.y, min.z));
		array[5] = go.transform.TransformPoint(new Vector3(max.x, min.y, max.z));
		array[6] = go.transform.TransformPoint(new Vector3(max.x, max.y, min.z));
		array[7] = go.transform.TransformPoint(new Vector3(max.x, max.y, max.z));
		drawBoundingBox(array);
		Vector3 position = go.transform.TransformPoint(localBounds.center);
		centerScreenPos = playerCamera.WorldToScreenPoint(position);
		upPoint = new Vector2(0f, float.MinValue);
		rightPoint = new Vector2(float.MinValue, 0f);
		leftPoint = new Vector2(float.MaxValue, 0f);
		downPoint = new Vector2(0f, float.MaxValue);
		Vector3[] array2 = array;
		foreach (Vector3 position2 in array2)
		{
			Vector3 vector = playerCamera.WorldToScreenPoint(position2);
			if (!(vector.z < 0f))
			{
				if (vector.y > upPoint.y)
				{
					upPoint = vector;
				}
				if (vector.y < downPoint.y)
				{
					downPoint = vector;
				}
				if (vector.x < leftPoint.x)
				{
					leftPoint = vector;
				}
				if (vector.x > rightPoint.x)
				{
					rightPoint = vector;
				}
			}
		}
	}

	private Vector3 calculateBestCornerPoint(Vector2 upPoint, Vector2 rightPoint, Vector2 leftPoint, Vector2 downPoint, Vector2 centerScreen, bool forceTopRight = false)
	{
		(Vector2, Vector2)[] array = new(Vector2, Vector2)[4]
		{
			(rightPoint, upPoint),
			(rightPoint, downPoint),
			(leftPoint, downPoint),
			(leftPoint, upPoint)
		};
		(Vector2, Vector2) tuple = (rightPoint, upPoint);
		bool flag = false;
		float num = (float)Screen.height / 20f;
		float num2 = (float)Screen.height / 20f;
		if (!forceTopRight)
		{
			(Vector2, Vector2)[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				(Vector2, Vector2) tuple2 = array2[i];
				if (tuple2.Item1.x > num && tuple2.Item1.x < (float)Screen.width - num && tuple2.Item2.y > num2 && tuple2.Item2.y < (float)Screen.height - num2)
				{
					tuple = tuple2;
					flag = true;
					break;
				}
			}
		}
		else
		{
			flag = true;
		}
		Vector2 vector = new Vector2(tuple.Item1.x, tuple.Item2.y);
		if (!flag)
		{
			float x = Mathf.Clamp(centerScreen.x, num, (float)Screen.width - num);
			float y = Mathf.Clamp(centerScreen.y, num2, (float)Screen.height - num2);
			vector = new Vector2(x, y);
		}
		else
		{
			Vector2 vector2 = tuple.Item1 - tuple.Item2;
			Vector2 vector3 = new Vector2(tuple.Item1.x, tuple.Item2.y) - centerScreen;
			float num3 = vector2.x * vector3.y - vector2.y * vector3.x;
			if (num3 != 0f && vector2 != Vector2.zero && vector3 != Vector2.zero)
			{
				float num4 = ((centerScreen.x - tuple.Item2.x) * vector3.y - (centerScreen.y - tuple.Item2.y) * vector3.x) / num3;
				_ = ((centerScreen.x - tuple.Item2.x) * vector2.y - (centerScreen.y - tuple.Item2.y) * vector2.x) / num3;
				vector = tuple.Item2 + num4 * vector2;
			}
		}
		if ((Mathf.Abs(vector.x - centerScreen.x) < Mathf.Abs(centerScreen.x) * 0.1f || Mathf.Abs(centerScreen.x) < 0.1f) && (Mathf.Abs(vector.y - centerScreen.y) < Mathf.Abs(centerScreen.y) * 0.1f || Mathf.Abs(centerScreen.y) < 0.1f))
		{
			vector = new Vector2(tuple.Item1.x, tuple.Item2.y);
		}
		return vector;
	}

	private void drawBoundingBox(Vector3[] corners)
	{
		Color cyan = Color.cyan;
		UnityEngine.Debug.DrawLine(corners[0], corners[1], cyan);
		UnityEngine.Debug.DrawLine(corners[1], corners[5], cyan);
		UnityEngine.Debug.DrawLine(corners[5], corners[4], cyan);
		UnityEngine.Debug.DrawLine(corners[4], corners[0], cyan);
		UnityEngine.Debug.DrawLine(corners[2], corners[3], cyan);
		UnityEngine.Debug.DrawLine(corners[3], corners[7], cyan);
		UnityEngine.Debug.DrawLine(corners[7], corners[6], cyan);
		UnityEngine.Debug.DrawLine(corners[6], corners[2], cyan);
		UnityEngine.Debug.DrawLine(corners[0], corners[2], cyan);
		UnityEngine.Debug.DrawLine(corners[1], corners[3], cyan);
		UnityEngine.Debug.DrawLine(corners[5], corners[7], cyan);
		UnityEngine.Debug.DrawLine(corners[4], corners[6], cyan);
	}

	private void handleToken(Pointer pointer)
	{
		Token component = pointer.context.target.GetComponent<Token>();
		handleToken(component, session.localPlayerId);
		session.send(new TokenFoundPacket
		{
			token = component
		});
	}

	private void handleToken(Token token, NetPlayerId playerThatFoundToken)
	{
		if (token == null)
		{
			UnityEngine.Debug.LogError("Cannot handle null token!");
			return;
		}
		PineFmod.playOneShotSoundAttached("event:/Sound Effects/00 General/Pickup/Token_Pickup", token.gameObject);
		int num = Array.IndexOf(tokens, token);
		if (!isTestingPlaymodeInEditor)
		{
			PlayerSave.setTokenCollected(levelIdentifier, num);
			PlayerSave.flush();
		}
		if (!syncedFoundTokens.Contains(num))
		{
			syncedFoundTokens.Add(num);
		}
		UnityEngine.Debug.Log(PlayerSave.ensureAndGetLevelState(levelIdentifier).foundTokens.Count + " tokens collected in " + levelIdentifier);
		if (PlayerSave.ensureAndGetLevelState(levelIdentifier).foundTokens.Count == 8 && levelIdentifier == "Dracula1" && Is.Demo)
		{
			saveAchievement("ACHIEVEMENT_TOKEN_COLLECTOR");
		}
		if (!Is.Demo && !isCustomLevel())
		{
			saveAchievement("ACHIEVEMENT_FIND_TOKEN");
			bool flag = true;
			foreach (RoomDatabase.Room item in RoomDatabase.getPackOfARoom(levelIdentifier))
			{
				if (PlayerSave.ensureAndGetLevelState(item.name).foundTokens.Count < 8)
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				saveAchievement("ACHIEVEMENT_FIND_ALL_TOKENS_PACK");
			}
			bool flag2 = true;
			foreach (RoomDatabase.Room allRegularRoom in RoomDatabase.getAllRegularRooms())
			{
				if (PlayerSave.ensureAndGetLevelState(allRegularRoom.name).foundTokens.Count < 8)
				{
					flag2 = false;
					break;
				}
			}
			if (flag2)
			{
				saveAchievement("ACHIEVEMENT_FIND_ALL_TOKENS_GAME");
			}
		}
		refreshVRWatchesTokenDisplay();
		if (!isProcessingPacket)
		{
			tokenCountPanel.gameObject.SetActive(value: true);
			Vector3 vector = playerCamera.WorldToViewportPoint(token.transform.position);
			tokenAnimations.Add(new TokenAnimation
			{
				token = token.gameObject,
				timer = 0f,
				startPoint = new Vector3(vector.x, vector.y, 0f),
				positionGoal = playerCamera.transform.InverseTransformPoint(token.transform.position)
			});
			if (token.TryGetComponent<Renderer>(out var component))
			{
				component.enabled = true;
				component.material = tokenUIMaterial;
			}
			Collider[] componentsInChildren = token.GetComponentsInChildren<Collider>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].enabled = false;
			}
		}
		else
		{
			Renderer[] componentsInChildren2 = token.GetComponentsInChildren<Renderer>();
			foreach (Renderer renderer in componentsInChildren2)
			{
				Texture mainTexture = renderer.material.mainTexture;
				renderer.material = tokenGhostMaterial;
				if (token.overridePickedUpTexture)
				{
					renderer.material.mainTexture = mainTexture;
				}
			}
			tokenCountCurrent.text = syncedFoundTokens.Count.ToString();
		}
		addChatMessageLocal(session.getUsername(playerThatFoundToken), "", ChatMessage.Type.PlayerFoundToken);
	}

	public void handleRoulette(Roulette roulette)
	{
		if (roulette == null || roulette.targets.Count == 0 || !isHost())
		{
			return;
		}
		List<int> list = new List<int>();
		for (int i = 0; i < roulette.targets.Count; i++)
		{
			if (!roulette.targetCanBeActivatedOnlyOnce || !roulette.indexHistory.Contains(i))
			{
				list.Add(i);
			}
		}
		if (list.Count == 0)
		{
			return;
		}
		int num = list[UnityEngine.Random.Range(0, list.Count)];
		if (isTestingPlaymodeInEditor && roulette.testingTarget >= 0)
		{
			num = roulette.testingTarget;
			if (roulette.targetCanBeActivatedOnlyOnce)
			{
				roulette.testingTarget = -1;
			}
		}
		roulette.indexHistory.Add(num);
		triggerRoulette(roulette, num);
		session.send(new RouletteTriggeredPacket
		{
			roulette = roulette,
			randomTargetIndex = num
		}, allowSendInMessageResponse: true);
	}

	private void triggerRoulette(Roulette roulette, int targetIndex)
	{
		levelLogic.onRoulette(roulette, targetIndex);
	}

	public void handleDelay(EditorDelay delay)
	{
		if (delay == null)
		{
			UnityEngine.Debug.LogError("Cannot handle null delay!");
		}
		else
		{
			startTimer(new LuaLevelLogic.EditorTimer(delay), delay.delay);
		}
	}

	public void handleActivatorComponent(GameObject go)
	{
		if (!go.TryGetComponent<ActivatorComponent>(out var component))
		{
			return;
		}
		switch (component.type)
		{
		case ActivatorComponent.ActivatorType.Disable:
		{
			foreach (GameObject key in component.keys)
			{
				handleActivatorDisable(component, key);
			}
			break;
		}
		case ActivatorComponent.ActivatorType.Enable:
		{
			foreach (GameObject key2 in component.keys)
			{
				handleActivatorEnable(component, key2);
			}
			break;
		}
		case ActivatorComponent.ActivatorType.Toggle:
		{
			foreach (GameObject key3 in component.keys)
			{
				handleActivatorToggle(component, key3);
			}
			break;
		}
		}
	}

	private void handleActivatorDisable(ActivatorComponent activator, GameObject target)
	{
		if (activator.targetObject)
		{
			handleActivatorToggleObject(target, enable: false);
		}
		if (activator.targetRenderer)
		{
			handleActivatorToggleRenderer(target, ActivatorComponent.ActivatorType.Disable);
		}
		if (activator.targetCollider)
		{
			handleActivatorToggleCollider(target, enable: false);
		}
		if (activator.targetObstacle)
		{
			handleActivatorToggleObstacle(target, enable: false);
		}
		if (activator.targetTargetable)
		{
			handleActivatorToggleTargetable(target, enable: false);
		}
	}

	private void handleActivatorEnable(ActivatorComponent activator, GameObject target)
	{
		if (!isInAnyPlayerInventory(target))
		{
			if (activator.targetObject)
			{
				handleActivatorToggleObject(target, enable: true);
			}
			if (activator.targetRenderer)
			{
				handleActivatorToggleRenderer(target, ActivatorComponent.ActivatorType.Enable);
			}
			if (activator.targetCollider)
			{
				handleActivatorToggleCollider(target, enable: true);
			}
			if (activator.targetObstacle)
			{
				handleActivatorToggleObstacle(target, enable: true);
			}
			if (activator.targetTargetable)
			{
				handleActivatorToggleTargetable(target, enable: true);
			}
		}
	}

	private void handleActivatorToggle(ActivatorComponent activator, GameObject target)
	{
		if (activator.targetObject)
		{
			handleActivatorToggleObject(target, !target.activeSelf);
		}
		if (activator.targetRenderer)
		{
			handleActivatorToggleRenderer(target, ActivatorComponent.ActivatorType.Toggle);
		}
		if (activator.targetCollider)
		{
			handleActivatorToggleCollider(target, target.GetComponent<ActivatorComponent.DisabledColliderMarker>() != null);
		}
		if (activator.targetObstacle)
		{
			handleActivatorToggleObstacle(target, target.GetComponent<ActivatorComponent.DisabledObstacleMarker>() != null);
		}
		if (activator.targetTargetable)
		{
			handleActivatorToggleTargetable(target, target.GetComponent<ActivatorComponent.DisabledTargetableMarker>() != null);
		}
	}

	private void handleActivatorToggleObject(GameObject target, bool enable)
	{
		if (isInTopZoom(target))
		{
			handleZoomLeave();
		}
		if (isInInventory(target))
		{
			performItemDrop(target);
		}
		Item component = target.GetComponent<Item>();
		if ((bool)isInSlot(component))
		{
			removeItemFromSlot(component);
		}
		target.SetActive(enable);
		if (!enable)
		{
			removeFromBehindObjectCommandBuffer(target);
		}
	}

	private void handleActivatorToggleRenderer(GameObject target, ActivatorComponent.ActivatorType state)
	{
		activatorComponentRemoveFromInventory(target);
		recursiveToggleRendererInChild(target.transform);
		void recursiveToggleRendererInChild(Transform parent)
		{
			if (parent.TryGetComponent<Renderer>(out var component) && component.sharedMaterial != null && (string.IsNullOrEmpty(component.sharedMaterial.name) || !component.sharedMaterial.name.Contains("ColliderMaterial")))
			{
				bool flag = true;
				if (state == ActivatorComponent.ActivatorType.Disable)
				{
					flag = false;
				}
				else if (state == ActivatorComponent.ActivatorType.Toggle)
				{
					flag = parent.TryGetComponent<DisabledRenderer>(out var component2) && component2.hasFlag(DisabledRenderer.DisabledFlag.Activator);
				}
				if (flag)
				{
					removeDisabledRenderer(component, DisabledRenderer.DisabledFlag.Activator);
				}
				else
				{
					addDisabledRenderer(component, DisabledRenderer.DisabledFlag.Activator);
				}
			}
			for (int i = 0; i < parent.childCount; i++)
			{
				Transform child = parent.GetChild(i);
				if (!(child.GetComponent<PropInstance>() != null))
				{
					recursiveToggleRendererInChild(child);
				}
			}
		}
	}

	private void handleActivatorToggleCollider(GameObject target, bool enable)
	{
		activatorComponentRemoveFromInventory(target);
		recursiveToggleColliderInChild(target.transform);
		ActivatorComponent.DisabledColliderMarker component = target.GetComponent<ActivatorComponent.DisabledColliderMarker>();
		if (enable && component != null)
		{
			UnityEngine.Object.Destroy(component);
		}
		else if (!enable && component == null)
		{
			target.AddComponent<ActivatorComponent.DisabledColliderMarker>();
		}
		void recursiveToggleColliderInChild(Transform root)
		{
			Collider[] components = root.GetComponents<Collider>();
			for (int i = 0; i < components.Length; i++)
			{
				components[i].enabled = enable;
			}
			for (int j = 0; j < root.childCount; j++)
			{
				Transform child = root.GetChild(j);
				if (!(child.GetComponent<PropInstance>() != null))
				{
					recursiveToggleColliderInChild(child);
				}
			}
		}
	}

	private void handleActivatorToggleObstacle(GameObject target, bool enable)
	{
		if (enable && target.TryGetComponent<PropInstance>(out var component))
		{
			RoomEditor.addNavMeshObstacles(component);
		}
		recursiveToggleObstacleInChild(target.transform);
		ActivatorComponent.DisabledObstacleMarker component2 = target.GetComponent<ActivatorComponent.DisabledObstacleMarker>();
		if (enable && component2 != null)
		{
			UnityEngine.Object.Destroy(component2);
		}
		else if (!enable && component2 == null)
		{
			target.AddComponent<ActivatorComponent.DisabledObstacleMarker>();
		}
		void recursiveToggleObstacleInChild(Transform root)
		{
			NavMeshObstacle[] components = root.GetComponents<NavMeshObstacle>();
			for (int i = 0; i < components.Length; i++)
			{
				components[i].enabled = enable;
			}
			for (int j = 0; j < root.childCount; j++)
			{
				Transform child = root.GetChild(j);
				if (!(child.GetComponent<PropInstance>() != null))
				{
					recursiveToggleObstacleInChild(child);
				}
			}
		}
	}

	private void handleActivatorToggleTargetable(GameObject target, bool enable)
	{
		ActivatorComponent.DisabledTargetableMarker component = target.GetComponent<ActivatorComponent.DisabledTargetableMarker>();
		if (enable && component != null)
		{
			UnityEngine.Object.Destroy(component);
		}
		else if (!enable && component == null)
		{
			target.AddComponent<ActivatorComponent.DisabledTargetableMarker>();
		}
		Interactive component2 = target.GetComponent<Interactive>();
		if (component2 != null)
		{
			component2.targetable = enable;
		}
	}

	private void activatorComponentRemoveFromInventory(GameObject go)
	{
		if (isInTopZoom(go))
		{
			handleZoomLeave();
		}
		if (isInInventory(go))
		{
			performItemDrop(go);
		}
		Item component = go.GetComponent<Item>();
		if ((bool)isInSlot(component))
		{
			removeItemFromSlotLocal(component);
		}
	}

	private void addDisabledRenderer(Renderer rend, DisabledRenderer.DisabledFlag flag)
	{
		if (!rend.gameObject.TryGetComponent<DisabledRenderer>(out var component))
		{
			component = rend.gameObject.AddComponent<DisabledRenderer>();
			component.initialRendererEnable = rend.enabled;
		}
		component.flags |= flag;
		rend.enabled = false;
	}

	private void removeDisabledRenderer(Renderer rend, DisabledRenderer.DisabledFlag flag)
	{
		if (rend.gameObject.TryGetComponent<DisabledRenderer>(out var component) && component.hasFlag(flag))
		{
			component.flags &= ~flag;
			if (component.flags == DisabledRenderer.DisabledFlag.None)
			{
				rend.enabled = component.initialRendererEnable;
			}
		}
	}

	public void handleEditorPuzzle(GameObject target)
	{
		EditorPuzzle component = target.gameObject.GetComponent<EditorPuzzle>();
		if (!component.done)
		{
			List<EditorPuzzle> solvedPuzzles = localSolvePuzzleAndAllConditions(component);
			walkthrough.showOnlyHeaders(getActivePuzzleHints());
			finishPuzzleCore(component.puzzleName, -1, puzzleRequiresTeamwork: false, component.muteSound);
			session.send(new EditorPuzzleCompletedPacket
			{
				solvedPuzzles = solvedPuzzles
			});
		}
	}

	public HashSet<int> getActivePuzzleHints()
	{
		HashSet<int> hashSet = new HashSet<int>();
		foreach (EditorPuzzle allEditorPuzzle in allEditorPuzzles)
		{
			if (!allEditorPuzzle.done && solvedConditions(allEditorPuzzle))
			{
				hashSet.UnionWith(allEditorPuzzle.hints);
			}
		}
		return hashSet;
		static bool solvedConditions(EditorPuzzle puzzle)
		{
			bool result = true;
			foreach (GameObject condition in puzzle.conditions)
			{
				if (!condition.gameObject.GetComponent<EditorPuzzle>().done)
				{
					result = false;
					break;
				}
			}
			return result;
		}
	}

	private List<EditorPuzzle> localSolvePuzzleAndAllConditions(EditorPuzzle puzzle)
	{
		List<EditorPuzzle> solvedPuzzles = new List<EditorPuzzle>();
		HashSet<EditorPuzzle> visited = new HashSet<EditorPuzzle>();
		traverse(puzzle);
		return solvedPuzzles;
		void traverse(EditorPuzzle parent)
		{
			visited.Add(parent);
			foreach (GameObject condition in parent.conditions)
			{
				EditorPuzzle component = condition.gameObject.GetComponent<EditorPuzzle>();
				if (!visited.Contains(component))
				{
					traverse(component);
				}
			}
			if (solvePuzzle(parent))
			{
				solvedPuzzles.Add(parent);
			}
		}
	}

	private void otherPlayerSolvedPuzzles(EditorPuzzleCompletedPacket packet)
	{
		List<string> list = new List<string>();
		foreach (EditorPuzzle solvedPuzzle in packet.solvedPuzzles)
		{
			solvePuzzle(solvedPuzzle);
			if (!solvedPuzzle.done && !string.IsNullOrEmpty(solvedPuzzle.puzzleName))
			{
				list.Add(solvedPuzzle.puzzleName);
			}
		}
		if (list.Count > 0 && list.Count <= 3)
		{
			addChatMessageLocal("", "", ChatMessage.Type.PuzzleUnlocked, string.Join("<color=white>,</color> ", list));
		}
		else if (list.Count > 3)
		{
			addChatMessageLocal("", "", ChatMessage.Type.ManyPuzzlesUnlocked, list.Count.ToString());
		}
	}

	private bool solvePuzzle(EditorPuzzle puzzle)
	{
		if (puzzle == null)
		{
			return false;
		}
		if (puzzle.done)
		{
			return false;
		}
		puzzle.done = true;
		UnityEngine.Debug.Log("Solved puzzle: " + puzzle.puzzleName);
		return puzzle.done;
	}

	private void initHintSystem()
	{
		if (isCustomLevel())
		{
			puzzles = new List<Puzzle>();
			return;
		}
		string text = levelIdentifier;
		bool flag = text == "Lobby1" || text == "Tutorial1";
		gameHintUI.Explanation.gameObject.SetActive(!flag);
		gameHintUI.ExplanationTutorial.gameObject.SetActive(flag);
		gameObjectsToRelevantPuzzles.Clear();
		interactedPuzzleOrder.Clear();
		lookedItemsCurrentPuzzle.Clear();
		inventoryHistoryCurrentPuzzle.Clear();
	}

	private void updateHintSystem()
	{
		updateHintButtonClickability();
		updateHintRequestState();
		updateHintCooldown();
	}

	private void updateHintButtonClickability()
	{
		gameHintUI.ButtonHint_RequestHintController.gameObject.SetActive(Controller.isActive());
		bool interactable = gameHintUI.ButtonHint.interactable;
		bool flag = getNextHint(interactedPuzzleOrder).hintIndex >= 0 && hintCooldown == 0f;
		if (Controller.isActive() && flag)
		{
			holdingHintButton = Controller.getButton(ControllerButtonActionType.UIExtra1);
		}
		if (interactable != flag)
		{
			gameHintUI.ButtonHint.interactable = flag;
			if (gameHintUI.ButtonHint.TryGetComponent<TweenStateButton>(out var component))
			{
				component.enabled = flag;
			}
		}
	}

	private void updateHintRequestState()
	{
		if (hintRequestState == HintRequestState.NotRequested)
		{
			if (holdingHintButton && hintCooldown == 0f)
			{
				holdingHintButtonTimer = Mathf.MoveTowards(holdingHintButtonTimer, 1.5f, Time.deltaTime * 2f);
				if (holdingHintButtonTimer >= 1.5f)
				{
					hintFlash.raycastTarget = true;
					hintFlashPercent = 0f;
					hintRequestState = HintRequestState.AnimatingToFlash;
				}
			}
			else
			{
				holdingHintButtonTimer = Mathf.MoveTowards(holdingHintButtonTimer, 0f, Time.deltaTime * 2f);
			}
		}
		else if (hintRequestState == HintRequestState.AnimatingToFlash)
		{
			hintFlashPercent = Mathf.MoveTowards(hintFlashPercent, 1f, Time.deltaTime * 2f);
			if (hintFlashPercent >= 1f)
			{
				closeMainMenu(animate: false);
				requestHint();
				hintCooldown = 5f;
			}
		}
		else if (hintRequestState == HintRequestState.WaitingForResponse)
		{
			hintFlashPercent = 1f;
		}
		else if (hintRequestState == HintRequestState.AnimatingFromFlash)
		{
			hintFlashPercent = Mathf.MoveTowards(hintFlashPercent, 0f, Time.deltaTime * 2f);
			hintFlash.raycastTarget = false;
			if (hintFlashPercent == 0f)
			{
				hintRequestState = HintRequestState.NotRequested;
			}
		}
		gameHintUI.ButtonHint_Fill.fillAmount = Mathf.SmoothStep(0f, 1f, holdingHintButtonTimer / 1.5f);
		hintFlash.color = new Color(0f, 0f, 0f, hintFlashPercent);
	}

	private void updateHintCooldown()
	{
		hintCooldown = Mathf.MoveTowards(hintCooldown, 0f, Time.deltaTime * 1f);
		hintCooldown = Mathf.Clamp(hintCooldown, 0f, 10000f);
		gameHintUI.ButtonHint_HintCooldownText.text = ((hintCooldown > 0f) ? (" (" + Mathf.CeilToInt(hintCooldown) + ")") : "");
		gameHintUI.ButtonHint_HintCooldownText.gameObject.SetActive(hintCooldown > 0f);
	}

	private void hintButtonMenuDown()
	{
		holdingHintButton = true;
	}

	private void hintButtonMenuUp()
	{
		holdingHintButton = false;
	}

	private (int puzzleIndex, int hintIndex) getNextHint(List<int> interactedPuzzleOrder)
	{
		int currentPuzzleIndex = getCurrentPuzzleIndex(interactedPuzzleOrder);
		int item = ((currentPuzzleIndex >= 0) ? puzzles[currentPuzzleIndex].getCurrentHintIndex() : (-1));
		return (puzzleIndex: currentPuzzleIndex, hintIndex: item);
	}

	private void requestHint()
	{
		if (hintRequestState != HintRequestState.WaitingForResponse)
		{
			hintRequestState = HintRequestState.WaitingForResponse;
			if (isHost() || getPlayerCount() == 1)
			{
				handleHintRequest(interactedPuzzleOrder, localPlayerData.id);
				UnityEngine.Debug.Log(string.Format("{0} Host (ID: {1}) requested hint", "[Hint-Sync]", localPlayerData.id));
			}
			else
			{
				session.sendToSpecificPlayerFromClient(new HintRequestPacket
				{
					interactedPuzzleOrder = interactedPuzzleOrder
				}, session.hostPlayerId);
				UnityEngine.Debug.Log(string.Format("{0} Client (ID: {1}) requested hint", "[Hint-Sync]", localPlayerData.id));
			}
			saveAchievement("ACHIEVEMENT_TAKE_A_HINT");
		}
	}

	private void handleHintRequest(List<int> interactedPuzzleOrder, NetPlayerId playerThatRequestedHint)
	{
		if (!isHost() && getPlayerCount() != 1)
		{
			UnityEngine.Debug.LogError("Only host can handle hint requests!");
			return;
		}
		var (puzzleIndex, hintIndex) = getNextHint(interactedPuzzleOrder);
		handleHintFetched(puzzleIndex, hintIndex, playerThatRequestedHint);
		session.send(new HintFetchedPacket
		{
			puzzleIndex = puzzleIndex,
			hintIndex = hintIndex,
			playerThatRequestedHint = playerThatRequestedHint
		}, allowSendInMessageResponse: true);
		UnityEngine.Debug.Log(string.Format("{0} Host handled fetch request for player (ID: {1})", "[Hint-Sync]", playerThatRequestedHint));
	}

	private void handleHintFetched(int puzzleIndex, int hintIndex, NetPlayerId playerThatRequestedHint)
	{
		if (playerThatRequestedHint == localPlayerData.id)
		{
			hintRequestState = HintRequestState.AnimatingFromFlash;
		}
		if (puzzleIndex >= 0 && hintIndex >= 0)
		{
			Puzzle puzzle = puzzles[puzzleIndex];
			Hint hint = puzzle.hints[hintIndex];
			hint.isFinished = true;
			for (int i = 0; i < hintIndex; i++)
			{
				puzzles[puzzleIndex].hints[i].isFinished = true;
			}
			if (!canShowPuzzleHint(puzzle))
			{
				interactedPuzzleOrder.Remove(puzzleIndex);
			}
			hint.gameObject.GetComponent<Renderer>().material.SetColor("_Color", hintTintColor);
			if (playerThatRequestedHint == localPlayerData.id)
			{
				hint.gameObject.SetActive(value: true);
				addItemToInventory(hint.gameObject);
				handleZoomEnter(hint.gameObject, ScreenTargetType.ItemInventory);
			}
			string arg = $"Is local: {session.isLocalPlayer(playerThatRequestedHint)} | Puzzle index: {puzzleIndex} | Hint index: {hintIndex}";
			UnityEngine.Debug.Log(string.Format("{0} Player (ID: {1}) fetched hint | {2}", "[Hint-Sync]", playerThatRequestedHint, arg));
		}
	}

	public void finishPuzzle<T>(T puzzle) where T : Enum
	{
		lookedItemsCurrentPuzzle.Clear();
		inventoryHistoryCurrentPuzzle.Clear();
		if (isHost())
		{
			int puzzleIndex = (int)(object)puzzle;
			PuzzleInfoAttribute customAttribute = typeof(T).GetField(puzzle.ToString()).GetCustomAttribute<PuzzleInfoAttribute>();
			string puzzleName;
			bool puzzleRequiresTeamwork;
			if (customAttribute != null)
			{
				puzzleName = Localization.translate(customAttribute.nameDisplayedInChat);
				puzzleRequiresTeamwork = customAttribute.requiresTeamwork;
			}
			else
			{
				puzzleName = Localization.translate(puzzle.ToString().SplitPascalCase());
				puzzleRequiresTeamwork = false;
				UnityEngine.Debug.LogError(string.Format("Puzzle '{0}' has no '{1}' defined.", puzzle, "PuzzleInfoAttribute"));
			}
			finishPuzzleCore(puzzleName, puzzleIndex, puzzleRequiresTeamwork);
			session.send(new PuzzleCompletedPacket
			{
				puzzleName = puzzleName,
				puzzleIndex = puzzleIndex,
				puzzleRequiresTeamwork = puzzleRequiresTeamwork,
				puzzleMuteSound = false
			}, allowSendInMessageResponse: true);
		}
	}

	private void finishPuzzleCore(string puzzleName, int puzzleIndex, bool puzzleRequiresTeamwork, bool muteSound = false)
	{
		if (puzzleIndex != -1)
		{
			if (puzzles[puzzleIndex].isSolved)
			{
				return;
			}
			markPuzzleAndConditionsDone(puzzleIndex);
			autosavePuzzleSolved = true;
		}
		UnityEngine.Debug.Log(string.Format("[{0}] Name: {1}, Index: {2}, Teamwork: {3}", "finishPuzzleCore", puzzleName, puzzleIndex, puzzleRequiresTeamwork));
		if (!muteSound)
		{
			PineFmod.playOneShotSoundAttached(soundPuzzleComplete, localPlayerData.playerObject);
		}
		addChatMessageLocal("", "", ChatMessage.Type.PuzzleFinished, puzzleName);
	}

	private void markPuzzleAndConditionsDone(int puzzleIndex)
	{
		Puzzle puzzle = puzzles[puzzleIndex];
		puzzle.isSolved = true;
		interactedPuzzleOrder.Remove(puzzleIndex);
		foreach (Hint hint in puzzle.hints)
		{
			hint.isFinished = true;
			if (hint.gameObject == null)
			{
				UnityEngine.Debug.LogError($"puzzles[{puzzleIndex}]: hint with index {puzzle.hints.IndexOf(hint)} gameObject is null");
			}
			else
			{
				removeItemFromGame(hint.gameObject);
			}
		}
		foreach (int conditionPuzzleIndex in puzzle.conditionPuzzleIndexes)
		{
			bool flag = false;
			for (int i = 0; i < puzzles.Count; i++)
			{
				if (i != puzzleIndex && puzzles[i].conditionPuzzleIndexes.Contains(conditionPuzzleIndex) && !puzzles[i].isSolved)
				{
					flag = true;
				}
			}
			if (!flag)
			{
				markPuzzleAndConditionsDone(conditionPuzzleIndex);
			}
		}
	}

	public void removeItemFromGame(GameObject item)
	{
		bool flag = false;
		if (isInTopZoom(item))
		{
			flag = true;
			handleZoomLeave();
		}
		if (pinnedItems.Exists((PinnedItemInfo x) => x.originalItem == item))
		{
			flag = true;
			handleUnpinItem(item, setItemInWorld: true);
		}
		if (isInInventory(item))
		{
			flag = true;
			removeItemFromInventory(item);
		}
		if (isInTrashcan(item))
		{
			flag = true;
			removeItemFromTrash(item.GetComponent<Item>());
		}
		item.layer = LayerMask.NameToLayer("Ignore Raycast");
		if (!flag)
		{
			Rigidbody component = item.GetComponent<Rigidbody>();
			if (component != null)
			{
				component.mass = 5f;
			}
			Renderer[] componentsInChildren = item.GetComponentsInChildren<Renderer>();
			foreach (Renderer rend in componentsInChildren)
			{
				Renderer currentRenderer = rend;
				getGameplayTween().tween(currentRenderer.gameObject, UnityEngine.Random.Range(0.5f, 2f), 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, delegate
				{
					Color[] originalColors = new Color[currentRenderer.materials.Length];
					for (int i = 0; i < currentRenderer.materials.Length; i++)
					{
						Material material = currentRenderer.materials[i];
						toFadeMode(material, zWrite: false);
						if (material.HasColor("_Color"))
						{
							originalColors[i] = material.GetColor("_Color");
						}
					}
					RawImage currentImage = rend.GetComponentInChildren<RawImage>();
					Color transparent = Color.white;
					transparent.a = 0f;
					getGameplayTween().tween(currentRenderer.gameObject, 1f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, delegate(float t)
					{
						for (int j = 0; j < currentRenderer.materials.Length; j++)
						{
							Color value = originalColors[j];
							value.a = Mathf.Lerp(originalColors[j].a, 0f, t);
							currentRenderer.materials[j].SetColor("_Color", value);
						}
						if (currentImage != null)
						{
							currentImage.color = Color.Lerp(Color.white, transparent, t);
						}
					}, delegate
					{
						currentRenderer.gameObject.SetActive(value: false);
					});
				});
			}
		}
		else
		{
			item.SetActive(value: false);
		}
	}

	private void updatePuzzleInteraction(GameObject item)
	{
		if (item == null)
		{
			return;
		}
		List<int> relevantPuzzlesFor = getRelevantPuzzlesFor(item);
		if (relevantPuzzlesFor.Count <= 0)
		{
			return;
		}
		int num = -1;
		if (interactedPuzzleOrder.Count > 0)
		{
			List<int> list = interactedPuzzleOrder;
			int num2 = list[list.Count - 1];
			if (relevantPuzzlesFor.Contains(num2) && canShowPuzzleHint(puzzles[num2]))
			{
				num = num2;
			}
		}
		if (num < 0)
		{
			foreach (int item2 in relevantPuzzlesFor)
			{
				int lowestPuzzleIndex = getLowestPuzzleIndex(item2);
				if (lowestPuzzleIndex >= 0)
				{
					num = lowestPuzzleIndex;
					break;
				}
			}
		}
		if (num >= 0 && num < puzzles.Count)
		{
			interactedPuzzleOrder.Remove(num);
			interactedPuzzleOrder.Add(num);
		}
	}

	public void forcePuzzleInteraction<TPuzzle>(TPuzzle puzzle) where TPuzzle : Enum
	{
		int num = (int)(object)puzzle;
		if (num >= 0 && num < puzzles.Count)
		{
			interactedPuzzleOrder.Remove(num);
			interactedPuzzleOrder.Add(num);
		}
		else
		{
			UnityEngine.Debug.Log("Puzzle you are trying to interact with doesnt exist");
		}
	}

	public void setHintCondition<TPuzzle, THint>(TPuzzle puzzle, THint hint, Func<bool> isSolvedCondition) where TPuzzle : Enum where THint : Enum
	{
		int index = (int)(object)puzzle;
		int index2 = (int)(object)hint;
		Hint hint2 = puzzles[index].hints[index2];
		if (hint2.isSolvedCondition == Hint.DefaultIsSolvedCondition)
		{
			hint2.isSolvedCondition = isSolvedCondition;
		}
		else
		{
			UnityEngine.Debug.LogError(string.Format("Detected duplicate '{0}' for puzzle '{1}', hint '{2}'.", "isSolvedCondition", puzzle, hint));
		}
	}

	public void setPuzzleConditions<T>(T puzzle, params T[] requiredPuzzles) where T : Enum
	{
		if (requiredPuzzles == null || requiredPuzzles.Length == 0)
		{
			UnityEngine.Debug.LogError("'requiredPuzzles' must be a non-empty entry.");
			return;
		}
		int puzzleIndex = (int)(object)puzzle;
		List<int> list = new List<int>(Array.ConvertAll(requiredPuzzles, (T p) => (int)(object)p));
		if (hasLoop(list))
		{
			UnityEngine.Debug.LogError($"Puzzle condition loop detected for puzzle '{puzzle}'. Conditions were not added.");
			return;
		}
		puzzles[puzzleIndex].conditionPuzzleIndexes.Clear();
		puzzles[puzzleIndex].conditionPuzzleIndexes.AddRange(list);
		UnityEngine.Debug.Log(string.Format("Puzzle '{0}' conditions: {1}", puzzle, string.Join(", ", requiredPuzzles)));
		bool hasLoop(List<int> conditions)
		{
			foreach (int condition in conditions)
			{
				if (condition == puzzleIndex)
				{
					return true;
				}
				if (hasLoop(puzzles[condition].conditionPuzzleIndexes))
				{
					return true;
				}
			}
			return false;
		}
	}

	public void setRelevantObjectsForPuzzle<T>(T puzzle, params GameObject[] relevantObjects) where T : Enum
	{
		int item = (int)(object)puzzle;
		foreach (GameObject key in relevantObjects)
		{
			if (!gameObjectsToRelevantPuzzles.ContainsKey(key))
			{
				gameObjectsToRelevantPuzzles[key] = new List<int>();
			}
			gameObjectsToRelevantPuzzles[key].Add(item);
		}
	}

	private List<int> getRelevantPuzzlesFor(GameObject item)
	{
		if (!gameObjectsToRelevantPuzzles.TryGetValue(item, out var value))
		{
			return new List<int>();
		}
		return value;
	}

	private int getLowestPuzzleIndex(int puzzleIndex, List<int> checkedIndexes = null)
	{
		if (checkedIndexes == null)
		{
			checkedIndexes = new List<int>();
		}
		if (checkedIndexes.Contains(puzzleIndex))
		{
			return -1;
		}
		checkedIndexes.Add(puzzleIndex);
		int result = -1;
		if (canShowPuzzleHint(puzzles[puzzleIndex]))
		{
			result = puzzleIndex;
		}
		else
		{
			foreach (int conditionPuzzleIndex in puzzles[puzzleIndex].conditionPuzzleIndexes)
			{
				int lowestPuzzleIndex = getLowestPuzzleIndex(conditionPuzzleIndex, checkedIndexes);
				if (lowestPuzzleIndex >= 0)
				{
					result = lowestPuzzleIndex;
					break;
				}
			}
		}
		return result;
	}

	public int getCurrentPuzzleIndex(List<int> interactedPuzzleOrder = null)
	{
		if (interactedPuzzleOrder == null)
		{
			interactedPuzzleOrder = this.interactedPuzzleOrder;
		}
		if (interactedPuzzleOrder.Count > 0)
		{
			List<int> list = interactedPuzzleOrder;
			return list[list.Count - 1];
		}
		int result = -1;
		for (int i = 0; i < puzzles.Count; i++)
		{
			if (canShowPuzzleHint(puzzles[i]))
			{
				result = i;
				break;
			}
		}
		return result;
	}

	private bool canShowPuzzleHint(Puzzle puzzle)
	{
		if (puzzle.isSolved || puzzle.getCurrentHintIndex() < 0)
		{
			return false;
		}
		bool result = true;
		foreach (int conditionPuzzleIndex in puzzle.conditionPuzzleIndexes)
		{
			if (!puzzles[conditionPuzzleIndex].isSolved)
			{
				result = false;
				break;
			}
		}
		return result;
	}

