	private void recalculateGameState()
	{
		GameState currentGameState = getCurrentGameState();
		gameState.changeState(currentGameState);
		gameState.update();
	}

	private GameState getCurrentGameState()
	{
		GameState result = GameState.Room;
		ZoomContext context;
		if (menuOptions.gameObject.activeInHierarchy || mainMenu.gameObject.activeInHierarchy || reconnectingCanvas.activeSelf || optionDialog.gameObject.activeInHierarchy || menuHostOptions.gameObject.activeInHierarchy || walkthrough.gameObject.activeInHierarchy || isChatOpen || isAnyLobbyUIOpen() || LoadingCanvas.get().isActive())
		{
			result = GameState.Menu;
		}
		else if (isInFinishLevelScreen)
		{
			result = GameState.FinishLevel;
		}
		else if (topZoomContextSafe(out context))
		{
			result = GameState.Zoom;
		}
		else
		{
			CharacterPoseState poseState = localPlayerData.characterPoseContext.poseState;
			if (poseState == CharacterPoseState.TransitionIn || poseState == CharacterPoseState.InPose)
			{
				result = GameState.Pose;
			}
			else if (localPlayerData.customMode != null)
			{
				result = GameState.CustomMode;
			}
			else if (foundCutScene != null || isInExitTweenFromCutscene())
			{
				result = GameState.Cutscene;
			}
		}
		return result;
	}

	[LuaAPI]
	public ItemState getItemState(Item item)
	{
		if (item.inSlotAnimation)
		{
			return ItemState.SlotAnimation;
		}
		if (item.slot != null || item.surfaceSlot != null)
		{
			return ItemState.Slot;
		}
		if (dragData?.itemDrag == item)
		{
			return ItemState.Drag;
		}
		item = getRootItem(item);
		foreach (ZoomContext zoomContext in zoomContexts)
		{
			if (zoomContext.selected == item.gameObject)
			{
				return ItemState.Zoom;
			}
		}
		if (item.inZoomAnimation)
		{
			return ItemState.ZoomAnimation;
		}
		int num = inventory.FindIndex((InventoryItem x) => x.gameObjects.Contains(item.gameObject));
		if (carryingItem == item || (num != -1 && inventory[num].topGameObject() == item.gameObject))
		{
			return ItemState.Hand;
		}
		if (isInAnyPlayerInventory(item.gameObject) || isInTrashcan(item.gameObject))
		{
			return ItemState.Inventory;
		}
		if (toolZoomObject != null && toolZoomObject == item.gameObject)
		{
			return ItemState.ToolZoom;
		}
		return ItemState.World;
		static Item getRootItem(Item item2)
		{
			Item result = item2;
			Transform parent = item2.transform;
			while (true)
			{
				parent = parent.parent;
				if (parent == null)
				{
					break;
				}
				Item component = parent.GetComponent<Item>();
				if (component != null)
				{
					result = component;
				}
			}
			return result;
		}
	}

	[LuaAPI]
	public void screenShakeDefault(float duration, float intensity, float roughness)
	{
		screenShake(duration, intensity, roughness);
	}

	public void screenShake(float duration, float intensity, float roughness, AnimationCurve intensityScaleCurve = null)
	{
		if (shakeScreenCoroutine == null)
		{
			shakeScreenCoroutine = StartCoroutine(shakeCoroutine());
		}
		IEnumerator shakeCoroutine()
		{
			float elapsedTime = 0f;
			Vector2 perlinNoiseSamplePositionX = Vector2.zero;
			Vector2 perlinNoiseSamplePositionY = Vector2.zero;
			Vector2 perlinNoiseSamplePositionZ = Vector2.zero;
			while (elapsedTime < duration)
			{
				perlinNoiseSamplePositionX += new Vector2(UnityEngine.Random.Range(0f - roughness, roughness), UnityEngine.Random.Range(0f - roughness, roughness));
				perlinNoiseSamplePositionY += new Vector2(UnityEngine.Random.Range(0f - roughness, roughness), UnityEngine.Random.Range(0f - roughness, roughness));
				perlinNoiseSamplePositionZ += new Vector2(UnityEngine.Random.Range(0f - roughness, roughness), UnityEngine.Random.Range(0f - roughness, roughness));
				float x = (2f * Mathf.PerlinNoise(perlinNoiseSamplePositionX.x, perlinNoiseSamplePositionX.y) - 1f) * intensity;
				float y = (2f * Mathf.PerlinNoise(perlinNoiseSamplePositionY.x, perlinNoiseSamplePositionY.y) - 1f) * intensity;
				float z = (2f * Mathf.PerlinNoise(perlinNoiseSamplePositionZ.x, perlinNoiseSamplePositionZ.y) - 1f) * intensity;
				screenShakeOffset = new Vector3(x, y, z) * (intensityScaleCurve?.Evaluate(elapsedTime / duration) ?? 1f);
				elapsedTime += Time.deltaTime;
				yield return null;
			}
			screenShakeOffset = Vector3.zero;
			shakeScreenCoroutine = null;
		}
	}

	[LuaAPI]
	public void setPointerReach(float newReach)
	{
		pointerReach = newReach;
	}

	[LuaAPI]
	public void resetPointerReach()
	{
		pointerReach = 2f;
	}

	public static bool inReach(Vector3 originPoint, Vector3 point)
	{
		return inReach(originPoint, point, pointerReach);
	}

	public static bool inReach(Vector3 originPoint, Vector3 point, float neoRange)
	{
		float num = neoRange * neoRange;
		return new Vector3(point.x - originPoint.x, 0f, point.z - originPoint.z).sqrMagnitude < num;
	}

