	private void initLookables()
	{
		Lookable[] array = allLookables;
		foreach (Lookable obj in array)
		{
			Collider[] componentsInChildren = obj.GetComponentsInChildren<Collider>(includeInactive: true);
			MeshRenderer[] componentsInChildren2 = obj.GetComponentsInChildren<MeshRenderer>(includeInactive: true);
			Bounds bounds = combineBounds(componentsInChildren);
			obj.init(bounds, componentsInChildren2, componentsInChildren, playerCamera, playerCamera.transform);
		}
		static Bounds combineBounds(Collider[] renderers)
		{
			if (renderers == null || renderers.Length == 0)
			{
				return default(Bounds);
			}
			Bounds bounds2 = renderers[0].bounds;
			for (int j = 1; j < renderers.Length; j++)
			{
				bounds2.Encapsulate(renderers[j].bounds);
			}
			return bounds2;
		}
	}

	private void updateLookables()
	{
		Lookable[] array = allLookables;
		foreach (Lookable lookable in array)
		{
			if (lookable.activateOnlyOnce && lookable.wasTriggeredOnce)
			{
				continue;
			}
			lookable.estimateVisibility();
			lookable.estimateScreenCoverage();
			bool isActivated = lookable.isActivated;
			if (isActivated != lookable.localPlayerActivating)
			{
				if (isHost())
				{
					setLookableState(lookable, localPlayerData.id, isActivated);
				}
				else
				{
					session.send(new LookableChangedPacket
					{
						lookable = lookable,
						newState = isActivated
					});
				}
				lookable.localPlayerActivating = isActivated;
			}
		}
	}

	private void setLookableState(Lookable lookable, NetPlayerId playerId, bool isActivated)
	{
		if (isHost())
		{
			if (lookable.activateOnlyOnce && lookable.wasTriggeredOnce)
			{
				return;
			}
			if (!playersActivatingLookable.TryGetValue(lookable, out var value))
			{
				value = new List<NetPlayerId>();
				playersActivatingLookable[lookable] = value;
			}
			bool num = value.Count > 0;
			if (isActivated)
			{
				if (!value.Contains(playerId))
				{
					value.Add(playerId);
				}
			}
			else
			{
				value.Remove(playerId);
			}
			bool flag = value.Count > 0;
			if (num != flag)
			{
				activateLookable(lookable, isActivated);
				session.send(new LookableChangedPacket
				{
					lookable = lookable,
					newState = isActivated
				}, allowSendInMessageResponse: true);
			}
		}
		else
		{
			activateLookable(lookable, isActivated);
		}
	}

	private void activateLookable(Lookable lookable, bool isActivated)
	{
		if (isActivated)
		{
			lookable.wasTriggeredOnce = true;
		}
		levelLogic.onLookable(lookable, isActivated);
	}

	private void startInteractionsOnLevelReady(bool shouldStartInteractions)
	{
		UnityEngine.Debug.Log($"{base.name} Starting interactions on level ready. Autoplay interactions: {shouldStartInteractions}");
		Item[] array = allItems;
		foreach (Item item in array)
		{
			if (item.TryGetComponent<EditorNonItemPoses>(out var component))
			{
				item.examinePivotOffset = component.examinePivotOffset;
				item.examineBaseRotation = component.examineBaseRotation;
				item.examineScaleModifier = component.examineScaleModifier;
				item.handRotationOffset = component.handRotationOffset;
				item.handScale = component.handScale;
				item.handPivotOffset = component.handPivotOffset;
				item.toolZoomRotationOffset = component.toolZoomRotationOffset;
				item.toolZoomScale = component.toolZoomScale;
				item.toolZoomPivotOffset = component.toolZoomPivotOffset;
				item.inventoryPositionOffset = component.inventoryPositionOffset;
				item.inventoryRotationOffset = component.inventoryRotationOffset;
				item.inventoryScale = component.inventoryScale;
				item.groundRotation = component.groundRotation;
			}
		}
		if (isCustomLevel())
		{
			Draggable[] array2 = allDraggables;
			foreach (Draggable draggable in array2)
			{
				if (draggable.draggableRigidbody == null)
				{
					draggable.draggableRigidbody = draggable.gameObject.AddComponent<Rigidbody>();
				}
			}
		}
		if (!shouldStartInteractions)
		{
			return;
		}
		Interactive[] array3 = allInteractives;
		foreach (Interactive interactive in array3)
		{
			if (interactive.roomEditorTargetPriotity == RoomEditorTargetPriotity.HigherThanParent)
			{
				Interactive componentInParent = interactive.transform.parent.GetComponentInParent<Interactive>();
				if (componentInParent != null)
				{
					interactive.targetPriority = componentInParent.targetPriority + 1;
				}
			}
