	private void zoomInInteractionFixCamera()
	{
		Vector3 normalized = (interactionZoom.transform.position - headPov.position).normalized;
		Vector3 eulerAngles = (Quaternion.FromToRotation(interactionZoomStoredDir, normalized) * headPov.transform.rotation).eulerAngles;
		float y = normalizeAngle(eulerAngles.x);
		float x = normalizeAngle(eulerAngles.y);
		targetRotation.y = y;
		targetRotation.x = x;
		currentRotation.y = y;
		currentRotation.x = x;
		static float normalizeAngle(float angle)
		{
			if (!(angle > 180f))
			{
				return angle;
			}
			return angle - 360f;
		}
	}

	private void updateInteractions()
	{
		if (isHost())
		{
			topZoomContextSafe(out var context);
			foreach (GamePlayerData netPlayer in netPlayers)
			{
				GameObject zoomItem = netPlayer.zoomItem;
				if (zoomItem != null && !allZoomsInUse.Contains(zoomItem))
				{
					anyPlayerZoomEnter(zoomItem);
				}
			}
			if (context != null && !allZoomsInUse.Contains(context.selected))
			{
				anyPlayerZoomEnter(context.selected);
			}
			List<GameObject> list = new List<GameObject>();
			foreach (GameObject zoom in allZoomsInUse)
			{
				bool num = netPlayers.Any((GamePlayerData x) => x.zoomItem == zoom);
				bool flag = context != null && context.selected == zoom;
				if (!num && !flag)
				{
					list.Add(zoom);
				}
			}
			foreach (GameObject item in list)
			{
				allZoomsInUse.Remove(item);
				Interactive component = item.GetComponent<Interactive>();
				handleAllPlayersLeaveZoom(component);
				session.send(new AllPlayersLeaveZoomPacket
				{
					zoom = component
				});
			}
		}
		accumulatedTime += Time.deltaTime;
		float deltaTime = Time.deltaTime;
		while (accumulatedTime >= deltaTime)
		{
			isInBackgroundUpdateProcessing = true;
			Interactive[] array = allInteractives;
			foreach (Interactive interactive in array)
			{
				handleInteractiveBackground(interactive, deltaTime);
			}
			isInBackgroundUpdateProcessing = false;
			accumulatedTime -= deltaTime;
		}
		Sound[] array2 = allSounds;
		for (int num2 = 0; num2 < array2.Length; num2++)
		{
			array2[num2].update3D();
		}
		handleTrashcanTriggers();
		foreach (Breakable.Pair item2 in breakablesEnterLastFrame)
		{
			if (!item2.breakable.isUsed && levelReadyProcessCompleted && (hasAuthority(item2.breakable.gameObject) || !isAnyOtherPlayerInteracting(item2.breakable.gameObject)))
			{
				float magnitude = item2.relativeVelocity.magnitude;
				if (item2.rigidbody != null)
				{
					breakObject(item2.breakable, magnitude, item2.rigidbody.mass);
				}
				else
				{
					breakObject(item2.breakable, magnitude);
				}
			}
		}
		breakablesEnterLastFrame.Clear();
		if (interactionZoom != null)
		{
			if (pointers.Count == 0 || pointers[0]?.context?.target != interactionZoom.gameObject)
			{
				zoomInInteractionDir = false;
			}
			float num3 = 0f;
			if (!zoomInInteractionDelay || zoomInInteractionDir)
			{
				interactionZoom.zoomInTimer += Time.deltaTime;
				if (!zoomInInteractionDir && (double)interactionZoom.zoomInTimer > 0.9)
				{
					zoomInInteractionDelay = true;
					zoomInInteractionFixCamera();
				}
			}
			else
			{
				interactionZoom.zoomInTimer -= Time.deltaTime * 1.5f;
				contestedCameraPosition.set(ContestedPose.Game, headPov.position);
				contestedCameraRotation.set(ContestedPose.Game, headPov.rotation);
			}
			interactionZoom.zoomInTimer = Mathf.Clamp(interactionZoom.zoomInTimer, 0f, 1f);
			num3 = UnityUtils.smootherStep(0f, 1f, interactionZoom.zoomInTimer);
			contestedCameraPosition.set(ContestedPose.InteractionZoom, Vector3.Lerp(headPov.position, interactionZoom.eyePosition, num3), oneFrame: true);
			contestedCameraRotation.set(ContestedPose.InteractionZoom, Quaternion.Lerp(headPov.rotation, Quaternion.Euler(interactionZoom.eyeRotation), num3), oneFrame: true);
			if (interactionZoom.zoomInTimer <= 0f)
			{
				interactionZoom = null;
			}
		}
		if (gameState.current == GameState.Zoom)
		{
			handleZoomUpdate();
		}
		if (!exiting)
		{
			levelLogic.onUpdate();
		}
		if (topZoomContextSafe(out var _) && lookTimer >= 0f)
		{
			lookTimer += Time.deltaTime;
		}
		triggersToProcess.Clear();
		foreach (CollisionEventData collisionEvent in onCollisionsEnter)
		{
			Trigger trigger = allTriggers.Find((Trigger t) => t.collisionData == collisionEvent.source);
			if (!(trigger == null))
			{
				if (collisionEvent.frame > lastLoadLevelInvocationFrame + 1)
				{
					triggersToProcess.Add(trigger);
				}
				else
				{
					UnityEngine.Debug.Log("Detected trigger enter that happened before loading level " + $"(Trigger frame: {collisionEvent.frame}, Load frame: {lastLoadLevelInvocationFrame}, Collider: {collisionEvent.collider}).", trigger);
				}
			}
		}
		onCollisionsEnter.Clear();
		foreach (CollisionEventData collisionEvent2 in onCollisionsExit)
		{
			Trigger trigger2 = allTriggers.Find((Trigger t) => t.collisionData == collisionEvent2.source);
			if (!(trigger2 == null))
			{
				if (collisionEvent2.frame > lastLoadLevelInvocationFrame + 1)
				{
					triggersToProcess.Add(trigger2);
				}
				else
				{
					UnityEngine.Debug.Log("Detected trigger exit that happened before loading level " + $"(Trigger frame: {collisionEvent2.frame}, Load frame: {lastLoadLevelInvocationFrame}, Collider: {collisionEvent2.collider}).", trigger2);
				}
			}
		}
		onCollisionsExit.Clear();
		processTriggers();
		processDisplays(allDisplays);
		TweenState[] tweenStates = tweenStateContextLevel.tweenStates;
		foreach (TweenState tweenState in tweenStates)
		{
			tweenStateCompletedStates.Clear();
			tweenState.update(Time.deltaTime, tweenStateCompletedStates);
			foreach (string tweenStateCompletedState in tweenStateCompletedStates)
			{
				levelLogic.onTweenTransitionDone(tweenState, tweenStateCompletedState);
			}
		}
		MaterialState[] array3 = allMaterialStates;
		foreach (MaterialState materialState in array3)
		{
			materialStateCompletedStates.Clear();
			materialState.update(Time.deltaTime, materialStateCompletedStates);
			foreach (string materialStateCompletedState in materialStateCompletedStates)
			{
				levelLogic.onMaterialTransitionDone(materialState, materialStateCompletedState);
			}
		}
		Sequence[] array4 = allSequences;
		foreach (Sequence sequence in array4)
		{
			sequence.update(Time.deltaTime, out var complete);
			if (complete)
			{
				levelLogic.onSequenceDone(sequence);
			}
		}
		updateLookables();
