	private void processTriggers()
	{
		foreach (Trigger item2 in triggersToProcess)
		{
			var (players, interactives) = isTriggered(item2);
			if (triggerEnterNeo(item2, players, interactives) && !item2.isLocalOnly)
			{
				session.send(new ProcessTriggerPacket
				{
					trigger = item2,
					triggerEventType = TriggerEventType.Enter,
					players = players,
					interactives = interactives
				});
			}
			if (triggerExitNeo(item2, players, interactives) && !item2.isLocalOnly)
			{
				session.send(new ProcessTriggerPacket
				{
					trigger = item2,
					triggerEventType = TriggerEventType.Exit,
					players = players,
					interactives = interactives
				});
			}
		}
		(HashSet<NetPlayerId> players, HashSet<Interactive> interactives) isTriggered(Trigger trigger)
		{
			HashSet<NetPlayerId> hashSet = new HashSet<NetPlayerId>();
			HashSet<Interactive> hashSet2 = new HashSet<Interactive>();
			foreach (Collider item in trigger.collisionData.allTouchingNonAllocUnsafe)
			{
				if (!(item == null))
				{
					if (trigger.canPlayerTrigger && !trigger.triggerWhenAllPlayersEnter)
					{
						if (item.gameObject == playerCollider.gameObject)
						{
							hashSet.Add(session.localPlayerId);
						}
						if (!trigger.isLocalOnly)
						{
							GamePlayerData gamePlayerData = netPlayers.Find((GamePlayerData x) => x.playerCollider?.gameObject == item.gameObject);
							if (gamePlayerData != null)
							{
								hashSet.Add(gamePlayerData.id);
							}
						}
					}
					if (trigger.anyObjectCanTrigger)
					{
						Interactive componentInParent = item.GetComponentInParent<Interactive>();
						if (componentInParent != null)
						{
							hashSet2.Add(componentInParent);
						}
					}
					else
					{
						foreach (GameObject key in trigger.keys)
						{
							if (isAncestor(item.gameObject, key, checkTheirRelationship: true))
							{
								Interactive componentInParent2 = item.GetComponentInParent<Interactive>();
								if (componentInParent2 != null)
								{
									hashSet2.Add(componentInParent2);
								}
							}
						}
					}
				}
			}
			if (trigger.triggerWhenAllPlayersEnter)
			{
				bool flag = true;
				foreach (GamePlayerData netPlayer in netPlayers)
				{
					if (!trigger.collisionData.isTouching(netPlayer.playerCollider))
					{
						flag = false;
					}
				}
				if (!trigger.collisionData.isTouching(playerCollider))
				{
					flag = false;
				}
				if (flag)
				{
					hashSet.Add(session.localPlayerId);
				}
			}
			return (players: hashSet, interactives: hashSet2);
		}
	}

	private bool triggerEnterNeo(Trigger trigger, HashSet<NetPlayerId> players, HashSet<Interactive> interactives)
	{
		HashSet<NetPlayerId> hashSet = new HashSet<NetPlayerId>(players);
		hashSet.ExceptWith(trigger.playersInTriggerLastEvent);
		HashSet<Interactive> hashSet2 = new HashSet<Interactive>(interactives);
		hashSet2.ExceptWith(trigger.interactivesInTriggerLastEvent);
		if (hashSet.Count == 0 && hashSet2.Count == 0)
		{
			return false;
		}
		TriggerEvent triggerEvent = new TriggerEvent(TriggerEventType.Enter, players, interactives);
		triggerEvent.addEntered(hashSet, hashSet2);
		trigger.playersInTriggerLastEvent = players;
		trigger.interactivesInTriggerLastEvent = interactives;
		levelLogic.onTrigger(trigger, triggerEvent);
		if (trigger.enterData.locks != null)
		{
			handleLockValue(trigger.enterData.locks, trigger.enterData.output);
		}
		if (triggerEvent.wasEmpty)
		{
			triggerEvent.type = TriggerEventType.Started;
			levelLogic.onTrigger(trigger, triggerEvent);
			if (trigger.startData.locks != null)
			{
				handleLockValue(trigger.startData.locks, trigger.startData.output);
			}
			SoundTrigger soundTrigger = trigger.soundTrigger;
			if (soundTrigger != null)
			{
				if (!soundTrigger.onEnter.IsNull)
				{
					if (soundTrigger.onEnterEmitter == null)
					{
						soundTrigger.onEnterEmitter = PineFmod.addSoundEmitter(soundTrigger.gameObject);
					}
					soundTrigger.onEnterEmitter.EventReference = soundTrigger.onEnter;
					soundTrigger.onEnterEmitter.Lookup();
					soundTrigger.onEnterEmitter.Play();
					EventReference onEnter = trigger.soundTrigger.onEnter;
					UnityEngine.Debug.Log("Play sound: " + onEnter.ToString());
				}
				if (!string.IsNullOrEmpty(soundTrigger.ambienceParam.Name))
				{
					if (!soundTriggersForAmbience.TryGetValue(soundTrigger.ambienceParam.Name, out var value))
					{
						value = new List<SoundTrigger>();
						soundTriggersForAmbience[soundTrigger.ambienceParam.Name] = value;
					}
					value.Add(soundTrigger);
					updateAmbienceParams();
				}
				if (!string.IsNullOrEmpty(soundTrigger.musicParam.Name))
				{
					if (!soundTriggersForMusic.TryGetValue(soundTrigger.musicParam.Name, out var value2))
					{
						value2 = new List<SoundTrigger>();
						soundTriggersForMusic[soundTrigger.musicParam.Name] = value2;
					}
					value2.Add(soundTrigger);
					updateMusicParams();
				}
				if (!soundTrigger.footsteps.IsNull)
				{
					soundStepOverrides.Add(soundTrigger);
				}
			}
		}
		return true;
	}

	private bool triggerExitNeo(Trigger trigger, HashSet<NetPlayerId> players, HashSet<Interactive> interactives)
	{
		HashSet<NetPlayerId> hashSet = new HashSet<NetPlayerId>(trigger.playersInTriggerLastEvent);
		hashSet.ExceptWith(players);
		HashSet<Interactive> hashSet2 = new HashSet<Interactive>(trigger.interactivesInTriggerLastEvent);
		hashSet2.ExceptWith(interactives);
		if (hashSet.Count == 0 && hashSet2.Count == 0)
		{
			return false;
		}
		TriggerEvent triggerEvent = new TriggerEvent(TriggerEventType.Exit, players, interactives);
		triggerEvent.addLeft(hashSet, hashSet2);
		trigger.playersInTriggerLastEvent = players;
		trigger.interactivesInTriggerLastEvent = interactives;
		levelLogic.onTrigger(trigger, triggerEvent);
		if (trigger.exitData.locks != null)
		{
			handleLockValue(trigger.exitData.locks, trigger.exitData.output);
		}
		if (triggerEvent.isEmpty)
		{
			triggerEvent.type = TriggerEventType.Ended;
			levelLogic.onTrigger(trigger, triggerEvent);
			if (trigger.endData.locks != null)
			{
				handleLockValue(trigger.endData.locks, trigger.endData.output);
			}
			SoundTrigger soundTrigger = trigger.soundTrigger;
			if (soundTrigger != null)
			{
				if (soundTrigger.onEnterEmitter != null)
				{
					soundTrigger.onEnterEmitter.Stop();
				}
				if (!soundTrigger.onExit.IsNull)
				{
					PineFmod.playOneShotSound(soundTrigger.onExit);
					EventReference onExit = trigger.soundTrigger.onExit;
					UnityEngine.Debug.Log("Play sound: " + onExit.ToString());
				}
				if (!string.IsNullOrEmpty(trigger.soundTrigger.ambienceParam.Name))
				{
					soundTriggersForAmbience[trigger.soundTrigger.ambienceParam.Name].Remove(trigger.soundTrigger);
					updateAmbienceParams();
				}
				if (!string.IsNullOrEmpty(trigger.soundTrigger.musicParam.Name))
				{
					soundTriggersForMusic[trigger.soundTrigger.musicParam.Name].Remove(trigger.soundTrigger);
					updateMusicParams();
				}
				if (soundStepOverrides.Contains(soundTrigger))
				{
					soundStepOverrides.Remove(soundTrigger);
				}
			}
		}
		return true;
	}

	private void updateAmbienceParams()
	{
		foreach (KeyValuePair<string, List<SoundTrigger>> item in soundTriggersForAmbience)
		{
			item.Deconstruct(out var key, out var value);
			string text = key;
			List<SoundTrigger> list = value;
			float value2 = 0f;
			if (list.Count > 0)
			{
				value2 = list[list.Count - 1].ambienceParam.Value;
			}
			emitterAmbience.SetParameter(text, value2);
		}
	}

	private void updateMusicParams()
	{
		foreach (KeyValuePair<string, List<SoundTrigger>> item in soundTriggersForMusic)
		{
			item.Deconstruct(out var key, out var value);
			string text = key;
			List<SoundTrigger> list = value;
			float value2 = 0f;
			if (list.Count > 0)
			{
				value2 = list[list.Count - 1].ambienceParam.Value;
			}
			emitterMusic.SetParameter(text, value2);
		}
	}

	private void tryToSetActiveLadder(Vector3 movement)
	{
		ladderEmptyToMatchRotation = null;
		if (localPlayerData.ladderData != null || allLadders == null)
		{
			return;
		}
		foreach (Ladder allLadder in allLadders)
		{
			if (allLadder.enabled)
			{
				if (activatedLadder(allLadder.downExit, allLadder.downEmpty, allLadder.upEmpty))
				{
					localPlayerData.ladderData = new LadderMovementRuntimeData
					{
						ladder = allLadder,
						startEmpty = allLadder.downEmpty,
						startExit = getLadderExit(allLadder.downExit),
						endEmpty = allLadder.upEmpty,
						endExit = getLadderExit(allLadder.upExit)
					};
					break;
				}
				if (activatedLadder(allLadder.upExit, allLadder.upEmpty, allLadder.downEmpty))
				{
					localPlayerData.ladderData = new LadderMovementRuntimeData
					{
						ladder = allLadder,
						startEmpty = allLadder.upEmpty,
						startExit = getLadderExit(allLadder.upExit),
						endEmpty = allLadder.downEmpty,
						endExit = getLadderExit(allLadder.downExit)
					};
					break;
				}
			}
		}
		bool activatedLadder(Transform targetPlayerPosition, Transform ladderStart, Transform ladderEnd)
		{
			bool num = Vector3.Distance(playerLocation, targetPlayerPosition.position) < 0.25f || isActivatedBySpherecast(targetPlayerPosition);
			bool flag = Vector3.Dot(playerCamera.transform.forward, (ladderEnd.position - ladderStart.position).normalized) > -0.1f;
			bool flag2 = Vector3.Dot(playerCamera.transform.forward, (ladderStart.position - playerLocation).normalized) > 0f;
			bool flag3 = Vector3.Dot(movement.normalized, Vector3.ProjectOnPlane(playerCamera.transform.forward, Vector3.up).normalized) > 0.95f;
			if (num && flag2 && !flag)
			{
				ladderEmptyToMatchRotation = ladderEnd;
			}
			return num && flag && flag2 && flag3;
		}
		static Vector3 getLadderExit(Transform ladderEmpty)
		{
			Vector3 position = ladderEmpty.position;
			for (int i = 0; i < 10; i++)
			{
				if (NavMesh.SamplePosition(position, out var hit, 0.25f + (float)i * 0.25f, -1))
				{
					position = hit.position;
					break;
				}
			}
			return position;
		}
		bool isActivatedBySpherecast(Transform empty)
		{
			int num = Physics.OverlapSphereNonAlloc(empty.position, 0.25f, ladderHits);
			for (int i = 0; i < num; i++)
			{
				if (ladderHits[i].transform == playerCollider.transform)
				{
					return true;
				}
			}
			return false;
		}
	}

	private void stopLadder()
	{
		if (localPlayerData.ladderData != null)
		{
			PineFmod.stop(localPlayerData.ladderData.ladder.ladderSoundEventInstance, FMOD.Studio.STOP_MODE.IMMEDIATE);
			ladderDirection = 0;
			localPlayerData.ladderData = null;
			session.send(new UpdateLadderPacket
			{
				ladderData = null
			});
		}
	}

	private bool isClimbingLadder()
	{
		if (localPlayerData.ladderData != null)
		{
			return localPlayerData.ladderData.stage != LadderMovementStage.BeforeStart;
		}
		return false;
	}

	public static void processDisplays(List<EditorDisplay> displays, bool runningInEditor = false)
	{
		foreach (EditorDisplay display in displays)
		{
			if (display.quadCache == null)
			{
				display.quadCache = new List<GameObject>();
			}
			if (display.targetLock != null && (display.targetLock.revisionNumber > display.lockRevisionNumber || runningInEditor))
			{
				if (!runningInEditor)
				{
					display.lockRevisionNumber = display.targetLock.revisionNumber;
				}
				updateMemory(display);
			}
			else if (runningInEditor && display.memory.Length != 0)
			{
				display.memory = new int[0];
			}
			int num = display.memory.Length;
			if (display.quadCache.Count < num)
			{
				int num2 = num - display.quadCache.Count;
				for (int i = 0; i < num2; i++)
				{
					GameObject gameObject = GameObject.CreatePrimitive(PrimitiveType.Quad);
					gameObject.transform.SetParent(display.transform);
					display.quadCache.Add(gameObject);
					UnityEngine.Object.Destroy(gameObject.GetComponent<Collider>());
					gameObject.GetComponent<MeshRenderer>().material = display.quadMaterial;
				}
			}
			bool flag = display.columns > 0 && display.rows > 0;
			Vector3 localScale = default(Vector3);
			if (flag)
			{
				localScale = new Vector3((1f - (float)(display.columns - 1) * display.padding.x) / (float)display.columns, (1f - (float)(display.rows - 1) * display.padding.y) / (float)display.rows, 1f);
			}
			Vector3 vector = new Vector3(localScale.x / 2f, (0f - localScale.y) / 2f, -0.0001f);
			for (int j = 0; j < display.quadCache.Count; j++)
			{
				if (j < num && flag)
				{
					int num3 = j % display.columns;
					int num4 = j / display.columns;
					Vector3 localPosition = new Vector3((float)num3 * localScale.x + (float)num3 * display.padding.x, 0f - ((float)num4 * localScale.y + (float)num4 * display.padding.y), 0f) + vector;
					GameObject gameObject2 = display.quadCache[j];
					gameObject2.transform.localRotation = Quaternion.identity;
					gameObject2.transform.localPosition = localPosition;
					gameObject2.transform.localScale = localScale;
					if (display.spriteSheetTexture != null)
					{
						Material material = gameObject2.GetComponent<MeshRenderer>().material;
						material.SetTexture("_BaseColorMap", display.spriteSheetTexture);
						float x = 0f;
						float y = 0f;
						Vector2 value = new Vector2(1f, 1f);
						if (display.spriteSheetColumns > 0 && display.spriteSheetRows > 0)
						{
							value = new Vector2(1f / (float)display.spriteSheetColumns, 1f / (float)display.spriteSheetRows);
							x = (float)(display.memory[j] % display.spriteSheetColumns) * value.x;
							y = 1f - value.y * (float)(display.memory[j] / display.spriteSheetColumns + 1);
						}
						material.SetTextureScale("_BaseColorMap", value);
						material.SetTextureOffset("_BaseColorMap", new Vector2(x, y));
					}
					display.quadCache[j].SetActive(value: true);
				}
				else
				{
					display.quadCache[j].SetActive(value: false);
				}
			}
		}
		void updateMemory(EditorDisplay display)
		{
			if (display.targetLock != null)
			{
				int[] obj = ((!runningInEditor) ? display.targetLock.currentValues : display.targetLock.password);
				int num5 = obj.Length;
				if (num5 != display.memory.Length)
				{
					display.memory = new int[num5];
				}
				Array.Copy(obj, display.memory, num5);
			}
		}
	}

