	private void handleSubsystemZoom(Pointer pointer)
	{
		if (!topZoomContextSafe(out var context))
		{
			return;
		}
		bool flag = controlMode.current == ControlMode.MouseAndKeyboard;
		if (context.state == ZoomContextState.None)
		{
			if (pointer.context.targetType == ScreenTargetType.InteractiveHinge)
			{
				handleInteractiveHinge(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Dial)
			{
				handleDial(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Switch3D && pointer.gestureUp)
			{
				handleSwitch3D(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Trackable && pointer.gestureUp)
			{
				handleTrackable(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.ChessablePiece && pointer.gestureUp)
			{
				handleChessablePiece(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.ChessableTile && pointer.gestureUp)
			{
				handleChessableTile(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.JigsawPiece)
			{
				handleJigsawPiece(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Tool)
			{
				handleTool(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.SwapperPiece)
			{
				handleSwapper(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Paintable)
			{
				handlePaintable(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Slidable)
			{
				handleSlidable(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.HorizontalSlider)
			{
				handleHorizontalSlider(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.SlidableGraphPiece)
			{
				handleSlidableGraph(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Rotatable)
			{
				handleRotatable(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Turnable)
			{
				handleTurnable(pointer);
			}
			else if (pointer.context.targetType == ScreenTargetType.Joystick)
			{
				handleJoystick(pointer);
			}
			else if ((pointer.gestureLongPress || pointer.gestureMoved) && pointer.context.targetType == ScreenTargetType.Item)
			{
				handleItemDragStart(pointer);
			}
			else if (!flag && pointer.gestureLongPress && pointer.context.targetType == ScreenTargetType.ZoomedItem)
			{
				bool flag2 = context.selected == pointer.context.target || pointer.context.target.GetComponent<Rigidbody>() == null;
				if (flag2)
				{
					handleZoomLeave();
				}
				handleItemDragStart(pointer, flag2);
			}
			else if (!flag && pointer.gestureLongPress && context.selectedType != ScreenTargetType.Zoomable)
			{
				handleZoomLeave();
				handleItemDragStart(pointer, context.selected, leaveZoom: true);
			}
			else if (context.selectedType != ScreenTargetType.Zoomable && context.selectedType != ScreenTargetType.SharedZoom && (pointer.gestureMoved || (Controller.isActive() && getControllerLook() != Vector2.zero)) && context.selectedType != ScreenTargetType.Tool && !isItemPinned(context.selected))
			{
				context.state = ZoomContextState.Orbit;
			}
			else
			{
				if (!pointer.gestureUp)
				{
					return;
				}
				if (pointer.context.targetType == ScreenTargetType.Item)
				{
					addItemToInventory(pointer.context.target);
				}
				if (pointer.context.targetType == ScreenTargetType.InventorySlot)
				{
					if (context.selectedType != ScreenTargetType.Zoomable)
					{
						handleZoomLeave();
						if (!isInInventory(context.selected))
						{
							transitionItemToInventory(context.selected);
						}
					}
				}
				else if (pointer.context.targetType == ScreenTargetType.Token)
				{
					handleToken(pointer);
				}
				else if (pointer.context.targetType == ScreenTargetType.ItemInventory)
				{
					if (MenuOptions.dragZoomItemsOnClick || (Controller.isActive() && Controller.touchStateController == InputState.None))
					{
						int potentialIndex = cursorOverInventorySlot(pointer.gesturePositionViewport, InventorySource.Inventory) - 1;
						startZoomItemModalDrag(potentialIndex);
					}
					else
					{
						handleItemInventoryAction(context, pointer);
					}
				}
				else if (pointer.context.targetType == ScreenTargetType.ZoomInventorySlot)
				{
					if (!checkTopZoomType(ScreenTargetType.Zoomable) && !checkTopZoomType(ScreenTargetType.Item))
					{
						handleZoomLeave();
						pcChangeItemSelection(null);
					}
				}
				else
				{
					if (pointer.context.targetType == ScreenTargetType.Trashcan)
					{
						return;
					}
					if (pointer.context.targetType == ScreenTargetType.None)
					{
						if (controlMode.current != ControlMode.MouseAndKeyboard && (controlMode.current != ControlMode.VirtualGamepad || !isInZoomMode))
						{
							handleZoomLeave();
						}
					}
					else if (!pointer.gestureLongPress && (pointer.context.targetType == ScreenTargetType.Item || pointer.context.targetType == ScreenTargetType.ZoomedItem) && context.selected != pointer.context.target && draggingInventoryIndex == -1 && !isInInventory(pointer.context.target) && pointer.context.target.layer == LayerMask.NameToLayer("Zoom"))
					{
						transitionItemToInventory(pointer.context.target);
					}
				}
			}
		}
		else if (context.state == ZoomContextState.None && context.toolZoomType != ToolZoomType.None)
		{
			if (pointer.context.targetType == ScreenTargetType.Tool)
			{
				handleTool(pointer);
			}
		}
		else if (context.state == ZoomContextState.Orbit && !isItemPinned(context.selected))
		{
			handleZoomOrbit(pointer, context);
		}
	}

	private void startZoomItemModalDrag(int potentialIndex)
	{
		if (!topZoomContextSafe(out var context))
		{
			return;
		}
		InventoryItem inventoryItem = inventory[potentialIndex];
		if (context.selected != inventoryItem.topGameObject() && potentialIndex != draggingInventoryIndex)
		{
			if (draggingInventoryIndex != -1)
			{
				draggingInventoryIndex = -1;
				destroyDragImpostors(draggingInventoryImpostors);
			}
			draggingInventoryIndex = potentialIndex;
			UnityEngine.Debug.Log(draggingInventoryIndex);
			draggingInventoryImpostors = createDragImpostors(inventoryItem.topGameObject());
			Vector3 localScale = draggingInventoryImpostors.itemDragImpostorScreen.transform.localScale;
			localScale *= 0.2f;
			draggingInventoryImpostors.itemDragImpostorScreen.transform.localScale = localScale;
			draggingInventoryImpostors.itemDragImpostorScreen.transform.rotation = inventoryItem.impostorClone.transform.rotation;
			draggingInventoryImpostors.itemDragImpostorWorld.SetActive(value: false);
			draggingInventoryImpostors.itemDragImpostorSlot.SetActive(value: false);
			initDragSlots(inventoryItem.gameObjects[0]);
		}
	}

	private void handleItemInventoryAction(ZoomContext zoomContext, Pointer pointer)
	{
		if (isAnySlotInProgress(zoomContext.selected) || pointer.context.interactionSessionId == dragInteractionId)
		{
			return;
		}
		ScreenTargetType selectedType = zoomContext.selectedType;
		if (selectedType != ScreenTargetType.Zoomable && selectedType != ScreenTargetType.Item)
		{
			if (isInTopZoom(pointer.context.target))
			{
				zoomRecenter();
				return;
			}
			handleZoomLeave();
		}
		handleZoomEnter(pointer);
	}

	private void dispatcher(Pointer pointer)
	{
		if (dragData != null)
		{
			if (gameState.current == GameState.Zoom)
			{
				if (pointer.gestureUp)
				{
					dispatcherItemDragZoomGestureUp();
				}
				else
				{
					dispatcherItemDragZoom();
				}
			}
			return;
		}
		GameState current = gameState.current;
		if (current == GameState.Room || current == GameState.Pose)
		{
			if (pointer.gestureUp)
			{
				dispatcherNoneRoomPoseGestureUp();
				return;
			}
			if (pointer.gestureDown)
			{
				dispatcherNoneRoomPoseGestureDown();
			}
			if (pointer.gestureDownToLongPress || pointer.gestureMoved || pointer.gestureLongPress)
			{
				dispatcherNoneRoomPoseGestureDownHold();
			}
		}
		else if (gameState.current == GameState.Zoom)
		{
			if (pointer.gestureDown)
			{
				dispatcherNoneZoomGestureDown();
			}
			if (pointer.gestureUp)
			{
				dispatcherNoneZoomGestureUp();
			}
			else if (pointer.gestureMoved)
			{
				dispatcherNoneZoomGestureMoved();
			}
			dispatcherNoneZoom();
		}
		static bool canStartRotatingHoveringItemInZoom(Pointer pointer2)
		{
			if (pointer2.context.target == null)
			{
				return true;
			}
			Item component = pointer2.context.target.GetComponent<Item>();
			if (component == null)
			{
				return true;
			}
			if (component.slot == null || !component.slot.canSwap)
			{
				return true;
			}
			return false;
		}
		void dispatcherItemDragZoom()
		{
			handleItemDragUpdate(pointer);
			if (pointer.context.currentTargetType == ScreenTargetType.Slot && !pointer.context.overUI)
			{
				handleSlotFromItemDrag(pointer);
			}
			else if (pointer.context.currentTargetType == ScreenTargetType.JigsawPiece && !pointer.context.overUI)
			{
				handleJigsawHoverZoom(pointer);
			}
			else
			{
				handlePlaceItemScreenSpace(pointer);
			}
		}
		void dispatcherItemDragZoomGestureUp()
		{
			handleItemDragEnd();
			switch (pointer.context.currentTargetType)
			{
			case ScreenTargetType.MagnifyingGlass:
				handleZoomEnterIcon(pointer);
				break;
			case ScreenTargetType.ItemInventory:
			case ScreenTargetType.InventorySlot:
				addItemToInventory(dragData.itemDrag.gameObject, returnBorrowed: false, dragData.itemDragInventoryPosition);
				break;
			case ScreenTargetType.Slot:
				if (isTargetPlacedInCompatibleSlot())
				{
					handleSlotFromItemDrag(pointer);
				}
				break;
			case ScreenTargetType.Jigsaw:
				handleJigsawHoverZoom(pointer);
				break;
			case ScreenTargetType.Tool:
				handleTool(pointer);
				break;
			case ScreenTargetType.SwapperPiece:
				handleSwapper(pointer);
				break;
			case ScreenTargetType.Item:
				if (isTargetPlacedInCompatibleSlot())
				{
					handleSlotFromSwapDrag(pointer);
				}
				break;
			default:
				handleReturnToInventory();
				break;
			}
			dragData = null;
			removeGameFrameSource(GameFrameSourceType.ZoomDrag);
		}
		void dispatcherNoneRoomPoseGestureDown()
		{
			if (pointer.context.targetType != ScreenTargetType.None && !(pointer.context.target == null))
			{
				Interactive component = pointer.context.target.GetComponent<Interactive>();
				if (component.zoomInInteraction)
				{
					if (interactionZoom == null)
					{
						interactionZoom = component;
						component.zoomInTimer = 0f;
					}
					interactionZoomStoredDir = component.transform.position - headPov.transform.position;
					zoomInInteractionDir = true;
					zoomInInteractionDelay = false;
				}
			}
		}
