		void dispatcherNoneRoomPoseGestureUp()
		{
			zoomInInteractionDir = false;
			switch (pointer.context.targetType)
			{
			case ScreenTargetType.ItemInventory:
				handleZoomEnter(pointer);
				break;
			case ScreenTargetType.InventorySlot:
				if (controlMode.current == ControlMode.MouseAndKeyboard)
				{
					pcChangeItemSelectionIndex(-1);
