				break;
			case ScreenTargetType.Token:
				handleToken(pointer);
				break;
			case ScreenTargetType.Trashcan:
				if (!pointer.gestureShortPressFailed && controlMode.current != ControlMode.MouseAndKeyboard)
				{
					handleTrashcan(pointer);
				}
				break;
			case ScreenTargetType.Item:
				addNewInteractedItem(pointer, pointer.context.target);
				break;
			case ScreenTargetType.NPC:
				handleNpcZoomEnter(pointer.context.target.GetComponent<Npc>());
				break;
			case ScreenTargetType.Zoomable:
				handleZoomEnter(pointer);
				break;
			case ScreenTargetType.CharacterPose:
				if (!isInPoseMode())
				{
					handlePoseEnterLocal(pointer);
				}
				break;
