		void dispatcherNoneZoom()
		{
			if (topZoomContextSafe(out var context))
			{
				if (context.state == ZoomContextState.None)
				{
					switch (pointer.context.targetType)
					{
					case ScreenTargetType.InteractiveHinge:
						handleInteractiveHinge(pointer);
						break;
					case ScreenTargetType.Dial:
						handleDial(pointer);
						break;
					case ScreenTargetType.JigsawPiece:
						handleJigsawPiece(pointer);
						break;
					case ScreenTargetType.Tool:
						handleTool(pointer);
						break;
					case ScreenTargetType.SwapperPiece:
						handleSwapper(pointer);
						break;
					case ScreenTargetType.Paintable:
						handlePaintable(pointer);
						break;
					case ScreenTargetType.Slidable:
						handleSlidable(pointer);
						break;
					case ScreenTargetType.HorizontalSlider:
						handleHorizontalSlider(pointer);
						break;
					case ScreenTargetType.SlidableGraphPiece:
						handleSlidableGraph(pointer);
						break;
					case ScreenTargetType.Rotatable:
						handleRotatable(pointer);
						break;
					case ScreenTargetType.Turnable:
						handleTurnable(pointer);
						break;
					case ScreenTargetType.Joystick:
						handleJoystick(pointer);
						break;
					default:
					{
						bool num = pointer.context.targetType != ScreenTargetType.ItemInventory && canStartRotatingHoveringItemInZoom(pointer) && context.selectedType != ScreenTargetType.Zoomable && context.selectedType != ScreenTargetType.SharedZoom && (pointer.gestureMoved || (Controller.isActive() && getControllerLook() != Vector2.zero)) && context.selectedType != ScreenTargetType.Tool && !isItemPinned(context.selected);
						bool flag = pointer.context.targetType == ScreenTargetType.Item;
						Switch3D component;
						bool flag2 = pointer.context.targetType == ScreenTargetType.Switch3D && pointer.context.target.TryGetComponent<Switch3D>(out component) && component.disableDragInZoom;
						if (num && !flag && !flag2)
						{
							context.state = ZoomContextState.Orbit;
						}
						break;
					}
					}
				}
				else if (context.state == ZoomContextState.None && context.toolZoomType != ToolZoomType.None)
				{
					if (pointer.context.targetType == ScreenTargetType.Tool)
					{
						handleTool(pointer);
					}
				}
				else if (context.state == ZoomContextState.Orbit && !isItemPinned(context.selected))
				{
					handleZoomOrbit(pointer, context);
				}
			}
		}
		void dispatcherNoneZoomGestureDown()
		{
			_ = pointer.context.targetType;
		}
		void dispatcherNoneZoomGestureMoved()
		{
			switch (pointer.context.targetType)
			{
			case ScreenTargetType.Trackable:
				handleTrackable(pointer);
				break;
			case ScreenTargetType.ItemInventory:
				if (!inTrashInventoryFocus && !isInTopZoom(pointer.context.target))
				{
					handleItemDragStart(pointer);
				}
				break;
			case ScreenTargetType.Item:
				if (!canStartRotatingHoveringItemInZoom(pointer))
				{
					handleItemDragStart(pointer);
				}
				break;
			}
		}
		void dispatcherNoneZoomGestureUp()
		{
			if (pointer.context.targetType != ScreenTargetType.PinnedItem && pointer.context.targetType != ScreenTargetType.GameUIBlocker && pinnedItemThisFrame == null)
			{
				unselectPinItem();
			}
			pinnedItemThisFrame = null;
			if (topZoomContextSafe(out var context) && context.state == ZoomContextState.None)
			{
				switch (pointer.context.targetType)
				{
				case ScreenTargetType.Switch3D:
					handleSwitch3D(pointer);
					break;
				case ScreenTargetType.Trackable:
					handleTrackable(pointer);
					break;
				case ScreenTargetType.ChessablePiece:
					handleChessablePiece(pointer);
					break;
				case ScreenTargetType.ChessableTile:
					handleChessableTile(pointer);
					break;
				case ScreenTargetType.Item:
					addItemToInventory(pointer.context.target);
					break;
				case ScreenTargetType.InventorySlot:
					if (context.selectedType != ScreenTargetType.Zoomable)
					{
						handleZoomLeave();
						if (!isInInventory(context.selected))
						{
							transitionItemToInventory(context.selected);
						}
					}
					break;
				case ScreenTargetType.Token:
					handleToken(pointer);
					break;
				case ScreenTargetType.ItemInventory:
					handleItemInventoryAction(context, pointer);
					break;
				case ScreenTargetType.ZoomInventorySlot:
					if (!checkTopZoomType(ScreenTargetType.Zoomable) && !checkTopZoomType(ScreenTargetType.Item))
					{
						handleZoomLeave();
						pcChangeItemSelection(null);
					}
					break;
				default:
					if (!pointer.gestureLongPress)
					{
						ScreenTargetType targetType = pointer.context.targetType;
						if ((targetType == ScreenTargetType.Item || targetType == ScreenTargetType.ZoomedItem) && context.selected != pointer.context.target && draggingInventoryIndex == -1 && !isInInventory(pointer.context.target) && pointer.context.target.layer == LayerMask.NameToLayer("Zoom"))
						{
							transitionItemToInventory(pointer.context.target);
						}
					}
					break;
				}
			}
		}
		bool isTargetPlacedInCompatibleSlot()
		{
			if (pointer.context.currentTarget == null)
			{
				return false;
			}
			Item component = dragData.itemDrag.GetComponent<Item>();
			Slot slot = pointer.context.currentTargetType switch
			{
				ScreenTargetType.Slot => pointer.context.currentTarget.GetComponent<Slot>(), 
				ScreenTargetType.Item => pointer.context.currentTarget.GetComponent<Item>().slot, 
				_ => null, 
			};
			if (slot != null)
			{
				if (Array.IndexOf(slot.acceptItems, component) == -1)
				{
					return Array.IndexOf(slot.rejectItems, component) != -1;
				}
				return true;
			}
			return false;
		}
	}

