	private void activateControllerSlotCanvas(bool activate)
	{
		inventoryGridContainer.useHover = activate;
		RectTransform component = inventoryCanvas.GetComponent<RectTransform>();
		if (activate)
		{
			prevSlotInventoryCanvasPosition = component.anchoredPosition;
			component.anchoredPosition = Vector2.zero;
		}
		else
		{
			component.anchoredPosition = prevSlotInventoryCanvasPosition;
		}
		inSlotInventoryFocus = activate;
		isTrashFocusOpen = activate;
		activateCenterScreenCanvas(activate, inventory, inventorySlots, inventoryEmpty, inventoryCanvas, isTrash: false);
	}

	private void activateCenterScreenCanvas(bool activate, List<InventoryItem> inventory, List<InventorySlot> inventorySlots, GameObject inventoryEmpty, RectTransform inventoryCanvas, bool isTrash = true)
	{
		trashInventoryGridContainer.isTrash = isTrash;
		if (isTrash)
		{
			inventoryCanvas.gameObject.SetActive(activate);
			if (inventoryCanvas.TryGetComponent<CanvasGroup>(out var component))
			{
				component.alpha = (activate ? 1f : 0f);
			}
		}
		bool active = true;
		slotFocusZoomedItemIndex = -1;
		if (inventory.Count > 0)
		{
			for (int i = 0; i < inventory.Count; i++)
			{
				foreach (GameObject gameObject in inventory[i].gameObjects)
				{
					if (isInTopZoom(gameObject))
					{
						slotFocusZoomedItemIndex = i;
					}
				}
				if (isTrash || activate)
				{
					inventory[i].impostorClone.gameObject.SetActive(activate);
					inventorySlots[i + 1].ui.gameObject.SetActive(activate);
				}
				active = false;
				if (!isTrash && slotFocusZoomedItemIndex == i)
				{
					inventory[i].impostorClone.gameObject.SetActive(!activate);
					inventorySlots[i + 1].ui.gameObject.SetActive(!activate);
				}
			}
			trashInventoryGridContainer.selected = -1;
			inventoryGridContainer.selected = -1;
		}
		inventoryEmpty.SetActive(active);
		if (!isTrash && !activate)
		{
			inventoryEmpty.SetActive(value: false);
		}
		trashInventoryGridContainer.cellScale = (activate ? 2f : 0.7f);
		if (activate && Controller.isActive() && inventory.Count > 0)
		{
			inventoryGridContainer.hover = 0;
		}
		syncControllerInventorySlotPositions();
	}

	private int getSlotFocusItemIndex(int index)
	{
		if (slotFocusZoomedItemIndex >= 0 && index >= slotFocusZoomedItemIndex)
		{
			index++;
		}
		index = Mathf.Min(index, inventory.Count - 1);
		return index;
	}

	public void breakObject(Breakable breakable, float magnitude, float newMass = -1f)
	{
		if (breakable.isUsed)
		{
			return;
		}
		float num = 1f;
		if (newMass != -1f)
		{
			num = newMass;
		}
		float num2 = magnitude * num;
		breakable.damage += num2;
		bool flag = hasAuthority(breakable.gameObject) || !isAnyOtherPlayerInteracting(breakable.gameObject) || isProcessingPacket;
		if (!(((num2 > breakable.breakingImpulse && breakable.breakingImpulse > 0f) || (breakable.health > 0f && breakable.damage > breakable.health)) && flag) || !levelReadyProcessCompleted)
		{
			return;
		}
		if (!isProcessingPacket)
		{
			setAuthority(breakable.gameObject, session.localPlayerId);
			session.send(new BreakBreakablePacket
			{
				breakableObject = breakable.gameObject
			});
		}
		breakable.isUsed = true;
		PineFmod.playOneShotSoundAttached(breakable.soundBreak, breakable.gameObject);
		Joint joint = breakable.GetComponent<Joint>();
		if (breakable.lockBreak != null)
		{
			unlockLock(breakable.lockBreak);
		}
		if (breakable.pieces.Count > 0)
		{
			breakable.wholePiece.SetActive(value: false);
			foreach (GameObject additionalOriginalRenderer in breakable.additionalOriginalRenderers)
			{
				additionalOriginalRenderer.SetActive(value: false);
			}
			{
				foreach (GameObject piece in breakable.pieces)
				{
					if (MenuOptions.isBreakableFadeOn)
					{
						Renderer[] componentsInChildren = piece.GetComponentsInChildren<Renderer>();
						foreach (Renderer renderer in componentsInChildren)
						{
							Renderer currentItem = renderer;
							getGameplayTween().tween(currentItem.gameObject, UnityEngine.Random.Range(2f, 3f), 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, delegate
							{
								Color[] originalColors = new Color[currentItem.materials.Length];
								for (int j = 0; j < currentItem.materials.Length; j++)
								{
									Material material = currentItem.materials[j];
									toFadeMode(material, zWrite: false);
									originalColors[j] = material.GetColor("_Color");
								}
								getGameplayTween().tween(currentItem.gameObject, 1f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, delegate(float t)
								{
									for (int k = 0; k < currentItem.materials.Length; k++)
									{
										Color value = originalColors[k];
										value.a = Mathf.Lerp(originalColors[k].a, 0f, t);
										currentItem.materials[k].SetColor("_Color", value);
									}
								}, delegate
								{
									currentItem.gameObject.SetActive(value: false);
								});
							});
						}
					}
					setParent(piece.transform, piece.transform.root);
					piece.SetActive(value: true);
				}
				return;
			}
		}
		if ((bool)joint)
		{
			if (joint.gameObject == controllerInteractionData?.interactingObject)
			{
				controllerEndInteraction();
			}
			JointRigidbody jointRigidbody = allJoints.Find((JointRigidbody x) => x.joint.gameObject == joint.gameObject);
			if (jointRigidbody != null)
			{
				allJoints.Remove(jointRigidbody);
			}
			UnityEngine.Object.Destroy(joint);
		}
		else
		{
			breakable.gameObject.SetActive(value: false);
		}
	}

	public static void toFadeMode(Material material, bool zWrite, int renderOffset = 0)
	{
		if (!(material.GetTag("RenderType", searchFallbacks: true) == "Transparent"))
		{
			material.SetFloat("_Mode", 2f);
			material.SetOverrideTag("RenderType", "Transparent");
			material.SetInt("_SrcBlend", 5);
			material.SetInt("_DstBlend", 10);
			material.SetInt("_ZWrite", zWrite ? 1 : 0);
			material.DisableKeyword("_ALPHATEST_ON");
			material.EnableKeyword("_ALPHABLEND_ON");
			material.DisableKeyword("_ALPHAPREMULTIPLY_ON");
			material.renderQueue = 3000 + renderOffset;
		}
	}

	public static void toOpaqueMode(Material material)
	{
		if (!(material.GetTag("RenderType", searchFallbacks: true) == ""))
		{
			material.SetFloat("_Mode", 0f);
			material.SetOverrideTag("RenderType", "");
			material.SetInt("_SrcBlend", 1);
			material.SetInt("_DstBlend", 0);
			material.SetInt("_ZWrite", 1);
			material.DisableKeyword("_ALPHATEST_ON");
			material.DisableKeyword("_ALPHABLEND_ON");
			material.DisableKeyword("_ALPHAPREMULTIPLY_ON");
			material.renderQueue = -1;
		}
	}

	private void handleMovementPan(Vector2 pan)
	{
		Vector3 zero = Vector3.zero;
		Vector3 normalized = new Vector3(playerCamera.transform.forward.x, 0f, playerCamera.transform.forward.z).normalized;
		float magnitude = pan.magnitude;
		zero = Quaternion.Euler(0f, Mathf.Atan2(pan.x, pan.y) * 57.29578f, 0f) * normalized * (magnitude * 0.0025f);
		handleMovementChange(zero);
	}

	private void handleMovementChange(Vector3 movement, bool teleport = false)
	{
		bool num = localPlayerData.ladderData != null;
		tryToSetActiveLadder(movement);
		bool flag = localPlayerData.ladderData != null;
		if (num != flag)
		{
			session.send(new UpdateLadderPacket
			{
				ladderData = localPlayerData.ladderData
			});
		}
		if (localPlayerData.ladderData != null && !teleport)
		{
			float num2 = ((!Controller.isActive()) ? ((float)((menuOptions.getActionKey(KeyBindingAction.Down) ? (-1) : 0) + (menuOptions.getActionKey(KeyBindingAction.Up) ? 1 : 0))) : getControllerMove().z);
			LadderMovementStage stage = localPlayerData.ladderData.stage;
			if (stage == LadderMovementStage.JumpoffAnimationToEnd || stage == LadderMovementStage.JumpoffAnimationToStart || stage == LadderMovementStage.InitialJumpToStart || stage == LadderMovementStage.ExitToStart)
			{
				num2 = 1f;
			}
			float maxDistanceDelta = Mathf.Abs(num2) * 2f * Time.deltaTime;
			bool flag2 = num2 > 0.01f;
			bool flag3 = num2 < -0.01f;
			int num3 = ladderDirection;
			ladderDirection = 0;
			LadderMovementStage stage2 = localPlayerData.ladderData.stage;
			bool jumpoffGoingToEndExit = localPlayerData.ladderData.jumpoffGoingToEndExit;
			if (flag2)
			{
				ladderDirection = 1;
				switch (localPlayerData.ladderData.stage)
				{
				case LadderMovementStage.BeforeStart:
					setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.startExit, maxDistanceDelta));
					if (Vector3.Distance(playerLocation, localPlayerData.ladderData.startExit) < 0.1f)
					{
						localPlayerData.ladderData.stage = LadderMovementStage.InitialJumpToStart;
					}
					break;
				case LadderMovementStage.InitialJumpToStart:
					setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.startEmpty.position, maxDistanceDelta));
					if (Vector3.Distance(playerLocation, localPlayerData.ladderData.startEmpty.position) < 0.1f)
					{
						localPlayerData.ladderData.stage = LadderMovementStage.BetweenEmpties;
					}
					break;
				case LadderMovementStage.BetweenEmpties:
					setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.endEmpty.position, maxDistanceDelta));
					if (UnityUtils.inverseLerp(localPlayerData.ladderData.startEmpty.position, localPlayerData.ladderData.endEmpty.position, playerLocation) > 0.6f)
					{
						localPlayerData.ladderData.stage = LadderMovementStage.JumpoffAnimationToEnd;
						localPlayerData.ladderData.jumpoffGoingToEndExit = true;
					}
					break;
				case LadderMovementStage.JumpoffAnimationToEnd:
					if (localPlayerData.ladderData.jumpoffGoingToEndExit)
					{
						setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.endEmpty.position, maxDistanceDelta));
						if (Vector3.Distance(playerLocation, localPlayerData.ladderData.endEmpty.position) < 0.1f)
						{
							localPlayerData.ladderData.jumpoffGoingToEndExit = false;
						}
					}
					else
					{
						setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.endExit, maxDistanceDelta));
						if (Vector3.Distance(playerLocation, localPlayerData.ladderData.endExit) < 0.1f)
						{
							stopLadder();
						}
					}
					break;
				case LadderMovementStage.ExitToStart:
					setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.startExit, maxDistanceDelta));
					if (Vector3.Distance(playerLocation, localPlayerData.ladderData.startExit) < 0.1f)
					{
						stopLadder();
					}
					break;
				}
			}
			else if (flag3)
			{
				ladderDirection = -1;
				switch (localPlayerData.ladderData.stage)
				{
				case LadderMovementStage.BeforeStart:
					setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.startExit, maxDistanceDelta));
					break;
				case LadderMovementStage.BetweenEmpties:
					setPlayerLocation(Vector3.MoveTowards(playerLocation, localPlayerData.ladderData.startEmpty.position, maxDistanceDelta));
					if (Vector3.Distance(playerLocation, localPlayerData.ladderData.startEmpty.position) < 0.1f)
					{
						localPlayerData.ladderData.stage = LadderMovementStage.ExitToStart;
					}
					break;
				}
			}
			if (num3 == 0 && ladderDirection != 0 && (flag2 || flag3))
			{
				PineFmod.start(localPlayerData.ladderData.ladder.ladderSoundEventInstance);
			}
			else if (num3 != 0 && ladderDirection == 0 && !flag2 && !flag3)
			{
				PineFmod.stop(localPlayerData.ladderData.ladder.ladderSoundEventInstance, FMOD.Studio.STOP_MODE.IMMEDIATE);
			}
			if (localPlayerData.ladderData != null && (stage2 != localPlayerData.ladderData.stage || jumpoffGoingToEndExit != localPlayerData.ladderData.jumpoffGoingToEndExit))
			{
				session.send(new UpdateLadderPacket
				{
					ladderData = localPlayerData.ladderData
				});
			}
		}
		else
		{
			if (ladderEmptyToMatchRotation != null)
			{
				Vector3 vector = ladderEmptyToMatchRotation.position - playerCamera.transform.position;
				float target = (0f - Mathf.Atan2(vector.y, new Vector2(vector.x, vector.z).magnitude)) * 57.29578f;
				float f = Mathf.DeltaAngle(targetRotation.y, target);
				targetRotation.y += Mathf.Sign(f) * 40f * Time.deltaTime;
			}
			Vector3 sourcePosition = playerLocation + movement;
			Vector3 vector2 = playerLocation;
			float num4 = (isCustomLevel() ? 0.25f : 0.5f);
			bool num5 = heightSlider.visualValue != 0f;
			NavMeshQueryFilter filter = (num5 ? walkableFilter : crouchFilter);
			bool flag4 = false;
			bool flag5 = false;
			bool flag6 = false;
			Vector3 vector3 = Vector3.zero;
			NavMeshHit hit = default(NavMeshHit);
			if (!num5)
			{
				if (NavMesh.SamplePosition(playerLocation, out hit, num4, crouchFilter))
				{
					flag6 = hit.distance > 0.001f;
					if (flag6)
					{
						vector3 = hit.position;
					}
				}
				flag5 = NavMesh.SamplePosition(sourcePosition, out hit, num4, crouchFilter);
			}
			if (num5 || !flag5)
			{
				if (NavMesh.SamplePosition(playerLocation, out hit, num4, walkableFilter))
				{
					flag6 = flag6 || hit.distance > 0.001f;
					if (flag6)
					{
						vector3 = hit.position;
					}
				}
				flag4 = NavMesh.SamplePosition(sourcePosition, out hit, num4, walkableFilter);
				filter = walkableFilter;
			}
			if (flag4 || flag5)
			{
				NavMeshPath navMeshPath = new NavMeshPath();
				if (teleport)
				{
					setPlayerLocation(hit.position);
					playerRig.localPosition = playerLocation;
					contestedCameraPosition.set(ContestedPose.Game, headPov.position);
				}
				else if (NavMesh.CalculatePath(vector2, hit.position, filter, navMeshPath) && navMeshPath.status == NavMeshPathStatus.PathComplete)
				{
					setPlayerLocation(hit.position);
				}
				else if (flag6)
				{
					setPlayerLocation(vector3);
				}
			}
			isOnStairs = false;
			int num6 = Physics.RaycastNonAlloc(playerLocation, Vector3.down, stairsHits, num4 * 2f);
			isOnStairs = false;
			for (int i = 0; i < num6; i++)
			{
				Collider collider = stairsHits[i].collider;
				if (collider != null && (collider.TryGetComponent<Stairs>(out var component) || collider.transform.parent.TryGetComponent<Stairs>(out component)))
				{
					isOnStairs = true;
					break;
				}
			}
			float movementDelta = Mathf.Min((vector2 - playerLocation).magnitude, movement.magnitude);
			trackTotalPlayerMovement(movementDelta);
		}
		if (controlMode.current == ControlMode.VR)
		{
			playerCollider.transform.position = playerCamera.transform.position;
			sendTeleportPose = teleport;
		}
		else if (teleport)
		{
			playerCollider.transform.position = playerLocation;
			sendTeleportPose = true;
		}
		else
		{
			playerCollider.transform.position = headPov.position;
		}
	}

	private void trackTotalPlayerMovement(float movementDelta)
	{
		float num = (isOnStairs ? 0.5f : 1f);
		int num2 = (int)(playerTotalMovement / num);
		playerTotalMovement += movementDelta;
		int num3 = (int)(playerTotalMovement / num);
		if (num2 == num3)
		{
			return;
		}
		lastStepTimestamp = Time.time;
		if (roomEditorSoundStepOverride != null)
		{
			if (roomEditorSoundStepOverride._event.Length > 0)
			{
				FMOD.Studio.EventInstance instance;
				RESULT rESULT = PineFmod.createInstance(new EventDescription(new IntPtr(roomEditorSoundStepOverride.eventHandle)), out instance);
				if (rESULT == RESULT.OK)
				{
					PineFmod.setVolume(instance, roomEditorSoundStepOverride.volume);
					PineFmod.start(instance);
				}
				else
				{
					UnityEngine.Debug.Log($"Error '{rESULT}' playing footsteps '{roomEditorSoundStepOverride._event}'");
				}
			}
			else if (roomEditorSoundStepOverride.path.Length > 0)
			{
				Bus bus = PineFmod.getBus("bus:/Sound Effects");
				FMOD.System coreSystem = RuntimeManager.CoreSystem;
				FMOD.Sound fmodSound = getFmodSound(roomEditorSoundStepOverride.gameObject);
				PineFmod.getChannelGroup(bus, out var channelGroup);
				Channel channel;
				RESULT rESULT2 = PineFmod.playSound(coreSystem, fmodSound, channelGroup, paused: false, out channel);
				if (rESULT2 == RESULT.OK)
				{
					PineFmod.setVolume(channel, roomEditorSoundStepOverride.volume);
				}
				else
				{
					UnityEngine.Debug.Log($"Error '{rESULT2}' playing footsteps '{roomEditorSoundStepOverride.path}'");
				}
			}
		}
		else
		{
			EventReference eventReference = ((soundStepOverrides.Count > 0) ? soundStepOverrides[0].footsteps : soundStepDefault);
			stepEmitter.EventReference = eventReference;
			stepEmitter.Lookup();
			stepEmitter.Play();
		}
	}

	public void handleCustomModeEnter(CustomMode mode, bool shouldAllPlayersEnter = true)
	{
		UnityEngine.Debug.Log("handleCustomModeEnter");
		if (!shouldAllPlayersEnter && isProcessingPacket)
		{
			return;
		}
		localPlayerData.customMode = mode;
		localPlayerData.turning = 0f;
		if (gameState.current == GameState.Zoom)
		{
			handleZoomLeave();
		}
		disableInventory.addSource(value: true, DisableInventorySource.InCustomMode);
		foreach (GameObject item in mode.toEnableWhenInMode)
		{
			item.SetActive(value: true);
		}
		foreach (GameObject item2 in mode.toDisableWhenInMode)
		{
			item2.SetActive(value: false);
		}
		if (localPlayerData.customMode.allowExit)
		{
			List<VisualControl> list = new List<VisualControl>();
			VisualControl visualControl = new VisualControl("back", ControllerButtonActionType.UIBack, "%back%", VisualControl.ControlType.Button, VisualControl.Position.BotRight);
			visualControl.addEscape();
			list.Add(visualControl);
			addGameFrameSource(GameFrameSourceType.CustomMode, list);
		}
	}

	public void handleCustomModeLeave(CustomMode mode)
	{
		UnityEngine.Debug.Log("handleCustomModeLeave");
		disableInventory.removeSource(DisableInventorySource.InCustomMode);
		levelLogic.onCustomModeLeave(mode);
		if (mode.overrideCamera)
		{
			if (mode.instantCameraMove)
			{
				playerCamera.transform.position = headPov.position;
				playerCamera.transform.rotation = headPov.rotation;
				contestedCameraPosition.set(ContestedPose.CustomMode, headPov.position, oneFrame: true);
				contestedCameraRotation.set(ContestedPose.CustomMode, headPov.rotation, oneFrame: true);
			}
			else
			{
				Vector3 eyePos = localPlayerData.customMode.eyePosition;
				Quaternion eyeRot = localPlayerData.customMode.eyeRotation;
				getGameplayTween().tween(playerCamera.gameObject, 0.75f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, delegate(float t)
				{
					float t2 = UnityUtils.smootherStep(0f, 1f, t / 0.75f);
					contestedCameraPosition.set(ContestedPose.Game, headPov.position);
					contestedCameraPosition.set(ContestedPose.CustomMode, Vector3.Lerp(eyePos, headPov.position, t2), oneFrame: true);
					contestedCameraRotation.set(ContestedPose.CustomMode, Quaternion.Lerp(eyeRot, Quaternion.Euler(targetRotation.y, targetRotation.x, 0f), t2), oneFrame: true);
				});
			}
		}
		foreach (GameObject item in mode.toEnableWhenInMode)
		{
			item.SetActive(value: false);
		}
		foreach (GameObject item2 in mode.toDisableWhenInMode)
		{
			item2.SetActive(value: true);
		}
		removeGameFrameSource(GameFrameSourceType.CustomMode);
		localPlayerData.customMode = null;
	}

