	public bool isAnySlotInProgress(GameObject gameObject)
	{
		Slot[] componentsInChildren = gameObject.GetComponentsInChildren<Slot>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (componentsInChildren[i].currentSlotState != SlotState.Idle)
			{
				return true;
			}
		}
		return false;
	}

	public void changeExamineRotation(GameObject zoom, Vector2 newRotation, float duration)
	{
		examineRotationChanges.RemoveAll((ChangeExamineRotationData x) => x.zoom == zoom);
		ChangeExamineRotationData item = new ChangeExamineRotationData
		{
			zoom = zoom,
			endRotation = new Vector2(closestAngle(examineRotationCurrent.x, newRotation.x), closestAngle(examineRotationCurrent.y, newRotation.y)),
			remainingTime = duration,
			totalTime = duration
		};
		examineRotationChanges.Add(item);
		static float closestAngle(float current, float target)
		{
			float num = Mathf.DeltaAngle(current % 360f, target % 360f);
			return current + num;
		}
	}

	public Vector2 getExamineRotationTarget()
	{
		return examineRotationTarget;
	}

	private void handleInteractiveHinge(Pointer pointer)
	{
		Rigidbody rigidbody = pointer.context.target.GetComponent<Rigidbody>();
		Joint component = rigidbody.GetComponent<Joint>();
		StudioEventEmitter component2 = pointer.context.target.GetComponent<StudioEventEmitter>();
		bool flag = false;
		flag = ((controlMode.current != ControlMode.VirtualGamepad) ? (hingeSessionId != pointer.context.interactionSessionId && pointer.gestureDown) : (hingeSessionId != pointer.context.interactionSessionId && pointer.gestureLongPress));
		bool flag2 = true;
		if (!isAnyOtherPlayerInteracting(pointer.context.target))
		{
			if (!myInteractingObjects.Contains(pointer.context.target) && flag)
			{
				startInteraction(pointer.context.target);
			}
			flag2 = hasAuthority(pointer.context.target);
		}
		if (pointer.gestureUp && !flag2)
		{
			endHingeInteraction(destroyedJoint: false);
		}
		if (!(component != null && flag2))
