			rigidbody.collisionDetectionMode = CollisionDetectionMode.ContinuousSpeculative;
			rigidbody.constraints = (RigidbodyConstraints)80;
			hingeStartingEulers = rigidbody.transform.localEulerAngles;
			if (Mathf.Abs(hingeStartingEulers.y) > 100f)
			{
				hingeStartingEulers.y += 360f * (0f - Mathf.Sign(hingeStartingEulers.y));
			}
			hingeStartRotation = rigidbody.transform.localRotation;
			flag3 = true;
			tempAnchor = new GameObject("Hinge Temporary Anchor");
