		Vector3 vector4 = Vector3.ProjectOnPlane(pointer.context.targetHitPoint, vector2);
		Vector3 vector5 = Quaternion.FromToRotation(Vector3.forward, vector2) * Vector3.right;
		float num = Vector3.SignedAngle(vector4 - vector3, vector5, vector2);
		if (flag3)
		{
			lastAngle = num;
		}
		float num2 = Mathf.Abs(Vector3.Dot(ray.direction, plane.normal));
		if (num2 < 0.05f)
		{
			num2 = 0f;
		}
		else if (num2 > 0.95f)
		{
			num2 = 1f;
		}
		float b;
		if (plane.Raycast(ray, out var enter))
		{
			b = Vector3.SignedAngle(Vector3.ProjectOnPlane(ray.GetPoint(enter), vector2) - vector3, vector5, vector2);
		}
		else
		{
			b = 0f;
			num2 = 0f;
		}
		Ray ray2 = new Ray(Vector3.ProjectOnPlane(ray.origin, vector2), Vector3.ProjectOnPlane(ray.direction, vector2));
		float num3 = Vector3.Distance(vector4, vector3);
		DebugDraw.cross(vector4, 0.25f, Color.blue);
		DebugDraw.ray(ray2, Color.yellow);
		DebugDraw.cross(vector3, 0.5f, Color.red);
		DebugDraw.circle(vector3, vector2, num3, Color.magenta);
		Vector3 vector6 = ray2.origin - vector3;
		float num4 = Vector3.Dot(ray2.direction, ray2.direction);
		float num5 = 2f * Vector3.Dot(ray2.direction, vector6);
		float num6 = Vector3.Dot(vector6, vector6) - num3 * num3;
		float distance = 0f;
		float num7 = num5 * num5 - 4f * num4 * num6;
		bool flag4;
		if (num7 < 0f)
		{
			flag4 = false;
		}
		else
		{
			float num8 = (0f - num5 + Mathf.Sqrt(num7)) / (2f * num4);
			float num9 = (0f - num5 - Mathf.Sqrt(num7)) / (2f * num4);
			if (num8 > 0f && num9 > 0f)
			{
				flag4 = true;
				float target = Mathf.LerpAngle(lastAngle, b, num2);
				float current = Vector3.SignedAngle(ray2.GetPoint(num8) - vector3, vector5, vector2);
				float current2 = Vector3.SignedAngle(ray2.GetPoint(num9) - vector3, vector5, vector2);
				float num10 = Mathf.Abs(Mathf.DeltaAngle(current, target));
				float num11 = Mathf.Abs(Mathf.DeltaAngle(current2, target));
				distance = ((Mathf.Abs(num10 - num11) < 0.1f) ? Mathf.Min(num8, num9) : ((!(num10 < num11)) ? num9 : num8));
			}
			else if (num8 > 0f)
			{
				flag4 = true;
				distance = num8;
			}
			else if (num9 > 0f)
			{
				flag4 = true;
				distance = num9;
			}
			else
			{
				flag4 = false;
			}
		}
		float num12;
		if (flag4)
		{
			Vector3 point = ray2.GetPoint(distance);
			num12 = Vector3.SignedAngle(point - vector3, vector5, vector2);
			DebugDraw.cross(point, 0.3f, Color.green);
			DebugDraw.ray(new Ray(vector3, Quaternion.AngleAxis(0f - num12, vector2) * vector5), Color.green);
		}
		else
		{
			float num13 = Vector3.Distance(vector3, ray2.origin);
			float num14 = 90f - Mathf.Asin(num3 / num13) * 57.29578f;
			float num15 = Vector3.SignedAngle(ray2.origin - vector3, vector5, vector2);
			float num16 = num15 + num14;
			float num17 = num15 - num14;
			distance = Vector3.Dot(vector3 - ray2.origin, ray2.direction);
			if (distance < num3)
			{
				distance = num3;
			}
			float num18 = Vector3.SignedAngle(ray2.GetPoint(distance) - vector3, vector5, vector2);
			num12 = ((!(Mathf.DeltaAngle(num18, num15) < 0f)) ? num17 : num16);
			DebugDraw.ray(new Ray(vector3, Quaternion.AngleAxis(0f - num12, vector2) * vector5), Color.green);
			DebugDraw.ray(new Ray(vector3, Quaternion.AngleAxis(0f - num18, vector2) * vector5), Color.gray);
		}
		float num19 = (lastAngle = Mathf.LerpAngle(num12, b, num2));
		hingeStartRotation.ToAngleAxis(out var angle, out var axis);
		angle = Mathf.Cos(Vector3.Angle(axis, vector2) * (MathF.PI / 180f)) * angle;
		float num20 = angle + num - num19;
		if (num20 < 0f)
		{
			num20 += 360f;
		}
		if (component.gameObject.TryGetComponent<HingeJoint>(out var component3))
		{
			if (num20 > 180f)
			{
				num20 -= 360f;
			}
			num20 = Mathf.Clamp(num20, component3.limits.min, component3.limits.max);
		}
		if (component.gameObject.TryGetComponent<CharacterJoint>(out var component4))
		{
			if (num20 > 180f)
			{
				num20 -= 360f;
			}
			num20 = Mathf.Clamp(num20, component4.lowTwistLimit.limit, component4.highTwistLimit.limit);
		}
		Quaternion localRotation = tempAnchor.transform.localRotation;
		tempAnchor.transform.localRotation = Quaternion.AngleAxis(num20, component.axis);
		float num21 = Mathf.Abs(Quaternion.Angle(localRotation, tempAnchor.transform.localRotation));
		if (component2 != null)
		{
			if (num21 < 0.01f)
			{
				PineFmod.stop(component2);
			}
			else if (!PineFmod.isPlaying(component2))
			{
				PineFmod.play(component2);
			}
		}
		bool flag5 = false;
		dragIcon.position = playerCamera.ViewportToWorldPoint(new Vector3(pointer.gesturePositionViewport.x, pointer.gesturePositionViewport.y, 0.5f));
		if (pointer.gestureUp || flag5)
		{
			endHingeInteraction(flag5);
		}
