	public void handleOpenLink(GameObject linkGO)
	{
		if (!isProcessingPacket)
		{
			string text = linkGO.GetComponent<OpenLink>().link.Trim();
			if (verifyOpenLink(text))
			{
				UnityEngine.Debug.Log("Opening link: \"" + text + "\"");
				SteamFriends.ActivateGameOverlayToWebPage(text, EActivateGameOverlayToWebPageMode.k_EActivateGameOverlayToWebPageMode_Modal);
			}
			else
			{
				UnityEngine.Debug.Log("Link does not lead to a steam workshop room: \"" + text + "\"");
			}
		}
	}

	public static bool verifyOpenLink(string link)
	{
		bool flag = false;
		bool flag2 = false;
		if (Uri.IsWellFormedUriString(link, UriKind.Absolute))
		{
			string[] array = new string[4] { "store.steampowered.com", "steamcommunity.com", "en.wikipedia.org", "pinestudio.com" };
			string[] array2 = new string[1] { "linkfilter" };
			foreach (string value in array2)
			{
				if (link.Contains(value))
				{
					flag2 = true;
				}
			}
			Uri uri = new Uri(link);
			array2 = array;
			foreach (string text in array2)
			{
				if (uri.Host == text)
				{
					flag = true;
					break;
				}
			}
		}
		if (flag)
		{
			return !flag2;
		}
		return false;
	}

	private void handleTeleport(GameObject teleport, bool forceTeleport, bool teleportRotation)
	{
		if (!isProcessingPacket || forceTeleport)
