			}
			else
			{
				teleportPlayer(teleport.transform.position, teleport.transform.rotation.eulerAngles);
			}
		}
	}

	private void startupEditorLevelInPlayMode(LevelContainerEditor levelContainer)
	{
		UnityEngine.Debug.LogError("This possibly should not even exist anymore. Merge logic with startInteractionsOnLevelReady");
		Component[] componentsInChildren = levelContainer.GetComponentsInChildren<Component>();
		if (SceneManager.GetActiveScene() == base.gameObject.scene)
		{
			levelContainer.navMeshSurface.BuildNavMesh();
			levelContainer.navMeshSurfaceCrouch.BuildNavMesh();
		}
		Stairs[] componentsInChildren2 = levelContainer.GetComponentsInChildren<Stairs>(includeInactive: true);
		foreach (Stairs stairs in componentsInChildren2)
		{
			if (stairs.slope != null)
			{
				stairs.slope.enabled = false;
			}
		}
		List<Transform> list = new List<Transform>();
		bool flag = false;
		int num = LayerMask.NameToLayer("RoomEditorSpecialObject");
		Component[] array = componentsInChildren;
		foreach (Component component in array)
		{
			if (component is Renderer renderer && component.gameObject.layer == num)
			{
				renderer.enabled = false;
			}
			if (component is Slot slot && slot.insertedItem != null)
			{
				Item insertedItem = slot.insertedItem;
				slot.insertedItem.transform.position = slot.pivot.transform.position;
				slot.insertedItem.transform.rotation = slot.pivot.transform.rotation;
				Item component2 = insertedItem.GetComponent<Item>();
				if (component2 != null)
				{
					component2.targetPriority = slot.targetPriority + 1;
				}
				insertedItem.slot = slot;
			}
			if (component is CustomModel { disableGeneratedCollider: not false })
			{
				component.GetComponent<Collider>().enabled = false;
			}
			if (component is Slidable { snapPointIndex: not 0 } slidable)
			{
				slidable.initRuntimeSlidablePosition(slidable.snapPointIndex);
			}
			if (component is EditorPuzzle editorPuzzle)
			{
				if (!flag)
				{
					walkthrough.hideAllHeaders();
					flag = true;
				}
				if (editorPuzzle.conditions.Count == 0)
				{
					walkthrough.hideAndShowHeaders(null, new List<int>(editorPuzzle.hints));
				}
			}
		}
		impostorCloneExplicitSyncEntries = list.ToArray();
	}

	private static FMOD.Sound getFmodSound(GameObject soundGO)
	{
		Sound component = soundGO.GetComponent<Sound>();
		if (component.type == Sound.SoundType.Music)
		{
			FMOD.Sound sound = new FMOD.Sound(new IntPtr(component.handle));
			PineFmod.setMode(sound, MODE.LOOP_NORMAL | MODE._2D);
			PineFmod.setLoopCount(sound, -1);
			return sound;
		}
		if (component.type == Sound.SoundType.SoundEffect)
		{
			FMOD.Sound result = new FMOD.Sound(new IntPtr(component.handle));
			MODE mODE = (component.is2D ? MODE._2D : MODE._3D);
			if (component.isLoopable)
			{
				mODE |= MODE.LOOP_NORMAL;
			}
			if (component.falloffMode == Sound.FalloffMode.NaturalFade)
			{
				mODE |= MODE._3D_INVERSEROLLOFF;
			}
			else if (component.falloffMode == Sound.FalloffMode.LinearFade)
			{
				mODE |= MODE._3D_LINEARROLLOFF;
			}
			else if (component.falloffMode == Sound.FalloffMode.SmoothFade)
			{
				mODE |= MODE._3D_INVERSETAPEREDROLLOFF;
			}
			result.setMode(mODE);
			result.setLoopCount(component.isLoopable ? (-1) : 0);
			return result;
		}
		FMOD.Sound sound2 = new FMOD.Sound(new IntPtr(component.handle));
		PineFmod.setMode(sound2, MODE._2D);
		PineFmod.setLoopCount(sound2, 0);
		return sound2;
	}

	public static void stopAllEditorSounds()
	{
		UnityEngine.Debug.Log("stopAllEditorSounds");
		foreach (EditorSoundWrapper currentEditorSound in currentEditorSounds)
		{
