		}
		currentEditorSounds.Clear();
	}

	public static FMOD.Studio.EventInstance playSoundAsEventInstance(GameObject soundGO)
	{
		FMOD.Sound fmodSound = getFmodSound(soundGO);
		FMOD.Studio.EventInstance eventInstance = RuntimeManager.CreateInstance("event:/Sound Effects/06 Test/Programer");
		eventInstance.setCallback(delegate(EVENT_CALLBACK_TYPE type, IntPtr instance, IntPtr paramPtr)
		{
			UnityEngine.Debug.Log(type);
			switch (type)
			{
			case EVENT_CALLBACK_TYPE.CREATE_PROGRAMMER_SOUND:
				UnityEngine.Debug.Log("CREATE_PROGRAMMER_SOUND");
				Marshal.StructureToPtr(new PROGRAMMER_SOUND_PROPERTIES
				{
					sound = fmodSound.handle,
					subsoundIndex = -1
				}, paramPtr, fDeleteOld: false);
				break;
			case EVENT_CALLBACK_TYPE.DESTROY_PROGRAMMER_SOUND:
				UnityEngine.Debug.Log("DESTROY_PROGRAMMER_SOUND");
				fmodSound.release();
				fmodSound.clearHandle();
				break;
			}
			return RESULT.OK;
		});
		eventInstance.start();
		currentEditorSounds.Add(new EditorSoundWrapper(fmodSound, eventInstance));
		return eventInstance;
	}

	public void playSound(GameObject soundGO)
	{
		Sound component = soundGO.GetComponent<Sound>();
		if ((!canExecuteLocalOnlyEvents() && component.localOnly) || (component.handle == 0L && component.eventHandle == 0L))
		{
			return;
		}
		UnityEngine.Debug.Log($"playSound path: {component.path}, {component.handle}, {component.eventHandle}");
		FMOD.System coreSystem = RuntimeManager.CoreSystem;
		FMOD.Sound fmodSound = getFmodSound(soundGO);
		if (component.type == Sound.SoundType.Music)
		{
			Bus bus = PineFmod.getBus("bus:/Music");
			PineFmod.stopAllEvents(bus, FMOD.Studio.STOP_MODE.ALLOWFADEOUT);
			PineFmod.getChannelGroup(bus, out var channelGroup);
			PineFmod.killSoundsInChannelGroup(channelGroup);
			if (component.handle != 0L)
			{
				UnityEngine.Debug.Log($"Try playing music with handle: {component.handle}");
				Channel channel;
				RESULT rESULT = PineFmod.playSound(coreSystem, fmodSound, channelGroup, paused: false, out channel);
				if (rESULT == RESULT.OK)
				{
					PineFmod.setVolume(channel, component.volume);
				}
				else
				{
					UnityEngine.Debug.Log($"Error '{rESULT}' playing music '{component.path}'");
				}
				return;
			}
			EventDescription eventDescription = new EventDescription(new IntPtr(component.eventHandle));
			UnityEngine.Debug.Log($"Try playing music from event: {component.eventHandle}");
			FMOD.Studio.EventInstance instance;
			RESULT rESULT2 = PineFmod.createInstance(eventDescription, out instance);
			if (rESULT2 == RESULT.OK)
			{
				PineFmod.setVolume(instance, component.volume);
				PineFmod.start(instance);
			}
			else
			{
				UnityEngine.Debug.Log($"Error '{rESULT2}' playing music '{component._event}'");
			}
		}
		else if (component.type == Sound.SoundType.SoundEffect)
		{
			if (component.handle != 0L)
			{
				Bus bus2 = PineFmod.getBus("bus:/Sound Effects");
				bool flag = false;
				if (component.channel.handle != IntPtr.Zero && PineFmod.isPlaying(component.channel, out var playing) == RESULT.OK && playing && PineFmod.getLoopCount(component.channel, out var loopcount) == RESULT.OK && loopcount == -1)
				{
					UnityEngine.Debug.Log("Stop playing loop sound");
					PineFmod.stop(component.channel);
					flag = true;
				}
				if (flag || PineFmod.getChannelGroup(bus2, out var channelGroup2) != RESULT.OK)
				{
					return;
				}
				UnityEngine.Debug.Log($"Try playing sound with handle: {component.handle}, 2D: {component.is2D}, loopable: {component.isLoopable}");
				Channel channel2;
				RESULT rESULT3 = PineFmod.playSound(coreSystem, fmodSound, channelGroup2, paused: false, out channel2);
				if (rESULT3 == RESULT.OK)
				{
					PineFmod.setVolume(channel2, component.volume);
					component.channel = channel2;
					if (!component.is2D)
					{
						channel2.set3DMinMaxDistance(component.minDistance3D, component.maxDistance3D);
						PineFmod.get3DAttributes(channel2, out var _, out var vel);
						Vector3 position = soundGO.transform.position;
						VECTOR pos2 = new VECTOR
						{
							x = position.x,
							y = position.y,
							z = position.z
						};
						PineFmod.set3DAttributes(channel2, ref pos2, ref vel);
					}
				}
				else
				{
					UnityEngine.Debug.Log($"Error '{rESULT3}' playing sound '{component.path}'");
				}
				return;
			}
			EventDescription eventDescription2 = new EventDescription(new IntPtr(component.eventHandle));
			UnityEngine.Debug.Log($"Try playing sound from event: {component.eventHandle}");
			FMOD.Studio.EventInstance instance2;
			RESULT rESULT4 = PineFmod.createInstance(eventDescription2, out instance2);
			if (rESULT4 == RESULT.OK)
			{
				PineFmod.setVolume(instance2, component.volume);
				if (eventDescription2.is3D(out var is3D) == RESULT.OK && is3D)
				{
					PineFmod.attachInstanceToGameObject(instance2, component.transform, null);
				}
				PineFmod.start(instance2);
			}
			else
			{
				UnityEngine.Debug.Log($"Error '{rESULT4}' playing music '{component._event}'");
			}
		}
		else
		{
			roomEditorSoundStepOverride = component;
		}
	}

