	public void addForce(GameObject go, Vector3 direction, bool addRandomDirection)
	{
		Rigidbody[] componentsInChildren = go.GetComponentsInChildren<Rigidbody>();
		foreach (Rigidbody obj in componentsInChildren)
		{
			Vector3 force = direction * (addRandomDirection ? UnityEngine.Random.Range(0.1f, 3f) : 1f);
			obj.AddForce(force);
		}
	}

	public void createKeyForSlot(Item go)
	{
		Slot[] slots = go.GetComponent<SlotKeyCreationHelper>().slots;
		for (int i = 0; i < slots.Length; i++)
		{
			Item[] array = new Item[slots[i].acceptItems.Length + 1];
			Array.Copy(slots[i].acceptItems, 0, array, 0, slots[i].acceptItems.Length);
			array[^1] = go;
			slots[i].acceptItems = array;
		}
	}

	public void animatorPlay(GameObject go, string clipName)
	{
		bool activeInHierarchy = go.activeInHierarchy;
		if (!go.activeInHierarchy)
		{
			go.SetActive(value: true);
		}
		go.GetComponent<Animator>().Play(clipName);
		if (go.activeInHierarchy != activeInHierarchy)
		{
			go.SetActive(activeInHierarchy);
		}
	}

