	public static bool findTransformOnSurfaceTop(Camera camera, GameObject gameObject, Item item, Bounds localBounds, Vector3 hitPoint, Vector3 hitNormal, float offset, bool ignoreNormal, out Vector3 position, out Quaternion rotation)
	{
		bool result = false;
		float num = Vector3.Dot(hitNormal, Vector3.up);
		position = Vector3.zero;
		rotation = Quaternion.identity;
		if (num > 0f)
		{
			Quaternion rotation2 = gameObject.transform.rotation;
			Vector3 vector = camera.transform.position - hitPoint;
			if (Mathf.Abs(vector.x) < 0.001f && Mathf.Abs(vector.z) < 0.001f)
			{
				Vector3 vector2 = -camera.transform.up;
				vector.x = vector2.x;
				vector.z = vector2.z;
			}
			Quaternion rotation3 = Quaternion.LookRotation(new Vector3(vector.x, 0f, vector.z), Vector3.up);
			if (item != null)
			{
				rotation3 *= Quaternion.Euler(0f, 180f, 0f);
				rotation3 *= Quaternion.Euler(item.examineBaseRotation) * Quaternion.Euler(item.groundRotation);
			}
			gameObject.transform.rotation = rotation3;
			Vector3 vector3 = Vector3.Scale(gameObject.transform.localScale, gameObject.transform.localRotation * localBounds.extents);
			vector3.x = Mathf.Abs(vector3.x);
			vector3.y = Mathf.Abs(vector3.y);
			vector3.z = Mathf.Abs(vector3.z);
			Vector3 vector4 = Vector3.Scale(gameObject.transform.lossyScale, gameObject.transform.rotation * localBounds.center);
			Vector3 vector5 = hitPoint + Vector3.up * (vector3.y + offset);
			Vector3 halfExtents = Vector3.Scale(gameObject.transform.localScale, localBounds.extents);
			int num2 = -5 & ~LayerMask.GetMask("ItemOverUI", "Zoom");
			RaycastHit hitInfo = default(RaycastHit);
			if (Physics.BoxCast(vector5, halfExtents, Vector3.down, out hitInfo, gameObject.transform.rotation, vector3.y + 0.2f, num2, QueryTriggerInteraction.Ignore))
			{
				bool flag = Physics.CheckBox(vector5, halfExtents, gameObject.transform.rotation, num2, QueryTriggerInteraction.Ignore);
				float distance = hitInfo.distance;
				isViewBlocked(camera, num2, ref distance);
				Vector3 vector6 = vector5 + Vector3.down * distance;
				bool flag2 = inReach(camera.transform.position, vector6);
				DrawBoxCastBox(vector5, halfExtents, Vector3.down, gameObject.transform.rotation, hitInfo.distance, flag ? Color.red : Color.blue);
				bool flag3 = ignoreNormal || Vector3.Dot(hitInfo.normal, Vector3.up) > 0.9f;
				if (flag2 && flag3 && !flag)
				{
					position = vector6 - vector4;
					rotation = gameObject.transform.rotation;
					result = true;
				}
			}
			gameObject.transform.rotation = rotation2;
		}
		return result;
	}

	public static void DrawBoxCastOnHit(Vector3 origin, Vector3 halfExtents, Vector3 direction, Quaternion orientation, float hitInfoDistance, Color color)
	{
		origin = CastCenterOnCollision(origin, direction, hitInfoDistance);
		DrawBox(origin, halfExtents, orientation, color);
	}

	public static void DrawBoxCastBox(Vector3 origin, Vector3 halfExtents, Vector3 direction, Quaternion orientation, float distance, Color color)
	{
		direction.Normalize();
		Box box = new Box(origin, halfExtents, orientation);
		Box box2 = new Box(origin + direction * distance, halfExtents, orientation);
		UnityEngine.Debug.DrawLine(box.backBottomLeft, box2.backBottomLeft, color);
		UnityEngine.Debug.DrawLine(box.backBottomRight, box2.backBottomRight, color);
		UnityEngine.Debug.DrawLine(box.backTopLeft, box2.backTopLeft, color);
		UnityEngine.Debug.DrawLine(box.backTopRight, box2.backTopRight, color);
		UnityEngine.Debug.DrawLine(box.frontTopLeft, box2.frontTopLeft, color);
		UnityEngine.Debug.DrawLine(box.frontTopRight, box2.frontTopRight, color);
		UnityEngine.Debug.DrawLine(box.frontBottomLeft, box2.frontBottomLeft, color);
		UnityEngine.Debug.DrawLine(box.frontBottomRight, box2.frontBottomRight, color);
		DrawBox(box, color);
		DrawBox(box2, color);
	}

	public static void DrawBox(Vector3 origin, Vector3 halfExtents, Quaternion orientation, Color color)
	{
		DrawBox(new Box(origin, halfExtents, orientation), color);
	}

	public static void DrawBox(Box box, Color color)
	{
		UnityEngine.Debug.DrawLine(box.frontTopLeft, box.frontTopRight, color);
		UnityEngine.Debug.DrawLine(box.frontTopRight, box.frontBottomRight, color);
		UnityEngine.Debug.DrawLine(box.frontBottomRight, box.frontBottomLeft, color);
		UnityEngine.Debug.DrawLine(box.frontBottomLeft, box.frontTopLeft, color);
		UnityEngine.Debug.DrawLine(box.backTopLeft, box.backTopRight, color);
		UnityEngine.Debug.DrawLine(box.backTopRight, box.backBottomRight, color);
		UnityEngine.Debug.DrawLine(box.backBottomRight, box.backBottomLeft, color);
		UnityEngine.Debug.DrawLine(box.backBottomLeft, box.backTopLeft, color);
		UnityEngine.Debug.DrawLine(box.frontTopLeft, box.backTopLeft, color);
		UnityEngine.Debug.DrawLine(box.frontTopRight, box.backTopRight, color);
		UnityEngine.Debug.DrawLine(box.frontBottomRight, box.backBottomRight, color);
		UnityEngine.Debug.DrawLine(box.frontBottomLeft, box.backBottomLeft, color);
	}

	private static Vector3 CastCenterOnCollision(Vector3 origin, Vector3 direction, float hitInfoDistance)
	{
		return origin + direction.normalized * hitInfoDistance;
	}

	private static Vector3 RotatePointAroundPivot(Vector3 point, Vector3 pivot, Quaternion rotation)
	{
		Vector3 vector = point - pivot;
		return pivot + rotation * vector;
	}

	private void handleMoveItemScreenSpace(Pointer pointer)
	{
		Transform transform = dragData.dragImpostors.itemDragImpostorScreen.transform;
		dragData.dragImpostors.itemDragImpostorScreen.transform.localScale = dragData.itemDrag.transform.localScale * dragItemScale;
		Quaternion quaternion = Quaternion.identity;
		Item itemDrag = dragData.itemDrag;
		if (itemDrag != null)
		{
			quaternion = Quaternion.Euler(itemDrag.examineBaseRotation) * Quaternion.Euler(itemDrag.inventoryRotationOffset);
		}
		transform.rotation = playerCamera.transform.rotation * quaternion;
		Vector3 vector = Vector3.Scale(transform.rotation * dragData.itemDragLocalBounds.center, transform.lossyScale);
		float num = pointer.gesturePositionViewport.y;
		if (controlMode.current == ControlMode.VirtualGamepad)
		{
			num += 0.05f;
		}
		if (gameState.current == GameState.Room)
		{
			transform.position = playerCamera.ViewportToWorldPoint(new Vector3(pointer.gesturePositionViewport.x, num, 0.1f)) - vector;
		}
		else
		{
			transform.position = playerCamera.ViewportToWorldPoint(new Vector3(pointer.gesturePositionViewport.x, num, 0.1f)) - vector;
		}
		Transform transform2 = inventorySlots[0].ui.Circle.transform;
		float num2 = 1f;
		if (pointer.context.currentTargetType == ScreenTargetType.InventorySlot)
		{
			num2 = 2f;
		}
		Vector3 vector2 = Vector3.one * num2;
		Vector3 value = vector2 * 1.1f;
		if (circleTweenState == 0)
		{
			PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
			GameObject obj = transform2.gameObject;
			Vector3? scaleTo = vector2;
			gameplayTween.tween(obj, 0.2f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo, null, null, null, null, null, delegate
			{
				circleTweenState = 1;
			});
			circleTweenState = -1;
		}
		else if (circleTweenState == 1)
		{
			PineTweenSystemEnableNoHandles gameplayTween2 = getGameplayTween();
			GameObject obj2 = transform2.gameObject;
			float duration = 0.5f / num2;
			Vector3? scaleTo = value;
			gameplayTween2.tween(obj2, duration, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo, null, null, null, null, null, delegate
			{
				circleTweenState = 2;
			});
			circleTweenState = -1;
		}
		else if (circleTweenState == 2)
		{
			PineTweenSystemEnableNoHandles gameplayTween3 = getGameplayTween();
			GameObject obj3 = transform2.gameObject;
			float duration2 = 0.5f / num2;
			Vector3? scaleTo = vector2;
			gameplayTween3.tween(obj3, duration2, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo, null, null, null, null, null, delegate
			{
				circleTweenState = 1;
			});
			circleTweenState = -1;
		}
		transform2.Rotate(Vector3.forward, 60f * Time.deltaTime);
	}

	private void handlePlaceItemScreenSpace(Pointer pointer)
