		handleCameraRotationInput(pointer);
	}

	private void handleItemDragUpdate(Pointer pointer)
	{
		GameObject gameObject = null;
		performOnLateUpdate(delegate
		{
			playerCamera.ResetWorldToCameraMatrix();
			foreach (Slot dragSlot in dragSlots)
			{
				Vector3 vector = playerCamera.WorldToViewportPoint(dragSlot.pivot.transform.position);
				dragSlot.hotspotIndicator.gameObject.SetActive(vector.z >= 0f);
				dragSlot.hotspotIndicator.position = playerCamera.ViewportToWorldPoint(new Vector3(vector.x, vector.y, 0.5f));
			}
		});
		foreach (Slot dragSlot2 in dragSlots)
		{
			GameObject gameObject2 = dragSlot2.hotspotIndicator.gameObject;
			if (dragSlot2.gameObject == pointer.context.currentTarget)
			{
				gameObject = gameObject2;
				if (focusedHotspot == null)
				{
					destroyGameplayTweens(gameObject2, performEvents: false, performFinalUpdate: false);
					PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
					Vector3? scaleTo = Vector3.one * 2f;
					focusedHotspot = gameplayTween.tween(gameObject2, 0.25f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo);
				}
			}
		}
		if (focusedHotspot != null)
		{
			focusedHotspot.gameObject.transform.localRotation = Quaternion.Euler(0f, 0f, Time.time * 10f);
			if (focusedHotspot.gameObject != gameObject)
			{
				destroyGameplayTweens(focusedHotspot.gameObject, performEvents: false, performFinalUpdate: false);
				PineTweenSystemEnableNoHandles gameplayTween2 = getGameplayTween();
				GameObject obj = focusedHotspot.gameObject;
				Vector3? scaleTo = Vector3.one;
				gameplayTween2.tween(obj, 0.25f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo);
				focusedHotspot = null;
			}
		}
		dragData.dragImpostors.itemDragImpostorScreen.SetActive(value: true);
		dragData.dragImpostors.itemDragImpostorWorld.SetActive(value: false);
		dragData.dragImpostors.itemDragImpostorSlot.SetActive(value: false);
	}

	private void handleItemDragStart(Pointer pointer, bool leaveZoom = false)
	{
		if (!Controller.isActive())
		{
			handleItemDragStart(pointer, pointer.context.target, leaveZoom);
		}
	}

	private DragImpostors createDragImpostors(GameObject gameObject)
	{
		DragImpostors dragImpostors = new DragImpostors();
		dragImpostors.itemDragImpostorScreen = ImpostorClone.create(impostorContext, gameObject, LayerMask.NameToLayer("ItemDrag"));
		dragImpostors.itemDragImpostorWorld = ImpostorClone.create(impostorContext, gameObject, LayerMask.NameToLayer("Default"));
		dragImpostors.itemDragImpostorSlot = ImpostorClone.create(impostorContext, gameObject, LayerMask.NameToLayer(isInBlurredZoom() ? "Zoom" : "Default"));
		dragImpostors.itemDragImpostorScreen.name = "Impostor - Screen: " + gameObject.name;
		dragImpostors.itemDragImpostorWorld.name = "Impostor - World: " + gameObject.name;
		dragImpostors.itemDragImpostorSlot.name = "Impostor - Slot: " + gameObject.name;
		dragImpostors.id = currentImpostorId++;
		return dragImpostors;
	}

	private void destroyDragImpostors(DragImpostors dragImpostors)
	{
		UnityEngine.Object.Destroy(dragImpostors.itemDragImpostorScreen);
		UnityEngine.Object.Destroy(dragImpostors.itemDragImpostorWorld);
		UnityEngine.Object.Destroy(dragImpostors.itemDragImpostorSlot);
	}

	private void handleItemDragStart(Pointer pointer, GameObject gameObject, bool leaveZoom = false)
	{
		if (dragInteractionId != pointer.context.interactionSessionId)
		{
			dragInteractionId = pointer.context.interactionSessionId;
			if (!leaveZoom && pointer.context.targetType != ScreenTargetType.ItemInventory)
			{
				startInteraction(gameObject);
				controllerStartInteraction(pointer);
			}
			DragImpostors dragImpostors = createDragImpostors(gameObject);
			dragImpostors.itemDragImpostorWorld.SetActive(value: false);
			dragImpostors.itemDragImpostorSlot.SetActive(value: false);
			Item component = gameObject.GetComponent<Item>();
			dragData = new DragData
			{
				dragImpostors = dragImpostors,
				itemDrag = component
			};
			updateDragZoomUiControls();
			Slot slot = component.slot;
			removeItemFromSlotLocal(component);
			InventoryItem inventoryItem = inventory.Find((InventoryItem x) => x.gameObjects.Contains(gameObject));
			if (inventoryItem != null)
			{
				dragImpostors.itemDragImpostorScreen.transform.position = inventoryItem.impostorClone.transform.position;
				dragImpostors.itemDragImpostorScreen.transform.rotation = inventoryItem.impostorClone.transform.rotation;
				dragData.itemDragInventoryPosition = removeItemFromInventory(component.gameObject, isForDrag: true);
			}
			dragData.itemDragLocalBounds = computeLocalBounds(gameObject);
			addNewInteractedItem(pointer, gameObject);
			focusedHotspot = null;
			dragSlots.Clear();
			Bounds bounds = computeBoundsForGameObject(gameObject);
			float num = Mathf.Max(Mathf.Max(bounds.size.x, bounds.size.y), bounds.size.z);
			ZoomContext context;
			float num2 = ((pointer.context.targetType != ScreenTargetType.ItemInventory && topZoomContextSafe(out context)) ? zoomAttachment.localScale.x : 1f);
			dragItemScale = 1f / num * 0.015f * num2;
			dragImpostors.itemDragImpostorScreen.transform.localScale = gameObject.transform.localScale * dragItemScale;
			if (component != null && !component.soundPickup.IsNull)
			{
				PineFmod.playOneShotSoundAttached(component.soundPickup, gameObject);
			}
			else
			{
				PineFmod.playOneShotSoundAttached("event:/SFX/GENERAL/zoom", gameObject);
			}
			initDragSlots(gameObject);
			gameObject.SetActive(value: false);
			if (slot != null)
			{
				handlePlaceItemSlotForImpostors(gameObject, dragImpostors, slot);
			}
		}
		static Bounds computeBoundsForGameObject(GameObject gameObject2)
		{
			Bounds result = default(Bounds);
			Renderer[] componentsInChildren = gameObject2.GetComponentsInChildren<Renderer>(includeInactive: true);
			if (componentsInChildren.Length == 0)
			{
				return result;
			}
			bool flag = true;
			Item component2 = gameObject2.GetComponent<Item>();
			bool isSlotChild = component2 != null && component2.slot != null;
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				MeshFilter meshFilter = meshFilterAcceptableForBoundsCalculations(componentsInChildren[i], isSlotChild);
				if (!(meshFilter == null))
				{
					Bounds bounds2 = meshFilter.sharedMesh.bounds;
					Transform transform = gameObject2.transform;
					if (flag)
					{
						result = new Bounds(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.min.x, bounds2.min.y, bounds2.min.z))), Vector3.zero);
						flag = false;
					}
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.min.x, bounds2.min.y, bounds2.min.z))));
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.min.x, bounds2.max.y, bounds2.min.z))));
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.min.x, bounds2.min.y, bounds2.max.z))));
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.min.x, bounds2.max.y, bounds2.max.z))));
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.max.x, bounds2.min.y, bounds2.min.z))));
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.max.x, bounds2.max.y, bounds2.min.z))));
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.max.x, bounds2.min.y, bounds2.max.z))));
					result.Encapsulate(transform.InverseTransformPoint(meshFilter.transform.TransformPoint(new Vector3(bounds2.max.x, bounds2.max.y, bounds2.max.z))));
				}
			}
			result.center = Vector3.Scale(gameObject2.transform.lossyScale, gameObject2.transform.rotation * result.center);
			result.size = Vector3.Scale(gameObject2.transform.lossyScale, result.size);
			return result;
		}
		static MeshFilter meshFilterAcceptableForBoundsCalculations(Renderer rendererCandidate, bool isSlotChild)
		{
			int num3 = LayerMask.NameToLayer("RoomEditorSpecialObject");
			bool flag = rendererCandidate.gameObject.layer == num3;
			ParticleSystem component2 = rendererCandidate.GetComponent<ParticleSystem>();
			LineRenderer component3 = rendererCandidate.GetComponent<LineRenderer>();
			SkinnedMeshRenderer component4 = rendererCandidate.GetComponent<SkinnedMeshRenderer>();
			MeshRenderer component5 = rendererCandidate.GetComponent<MeshRenderer>();
			Dial component6 = rendererCandidate.GetComponent<Dial>();
			Turnable component7 = rendererCandidate.GetComponent<Turnable>();
			MeshFilter meshFilter = ((component5 != null) ? component5.GetComponent<MeshFilter>() : null);
			Item component8 = rendererCandidate.GetComponent<Item>();
			bool flag2 = component8 != null && component8.slot != null;
			if (component6 != null || component7 != null || (flag2 && !isSlotChild))
			{
				return null;
			}
			if (flag || component4 != null || component3 != null || component2 != null)
			{
				return null;
			}
			if (component5 != null && component5.gameObject.activeInHierarchy && !component5.gameObject.CompareTag("IgnoreBounds") && meshFilter != null && (component5.enabled || component5.CompareTag("InvisibleBounds")))
			{
				return meshFilter;
			}
			return null;
		}
	}

	private void initDragSlots(GameObject item)
	{
		int num = LayerMask.NameToLayer("Zoom");
		Slot[] componentsInChildren = levelContainer.GetComponentsInChildren<Slot>();
		foreach (Slot slot in componentsInChildren)
		{
			if (canBePlacedInSlot(slot, item.GetComponent<Item>()) && (slot.gameObject.layer == num || gameState.current != GameState.Zoom) && isSlotCloseEnough(slot))
			{
				dragSlots.Add(slot);
				if (slot.hotspotIndicator == null)
				{
					GameObject gameObject = UnityEngine.Object.Instantiate(hotspotIcon.gameObject);
					setParent(gameObject.transform, hotspotIcon.transform.parent);
					gameObject.transform.localRotation = Quaternion.identity;
					slot.hotspotIndicator = gameObject.GetComponent<RectTransform>();
				}
				slot.hotspotIndicator.gameObject.SetActive(value: true);
				PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
				GameObject obj = slot.hotspotIndicator.gameObject;
				Vector3? scaleFrom = Vector3.zero;
				Vector3? scaleTo = Vector3.one;
				gameplayTween.tween(obj, 0.25f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, scaleFrom, scaleTo);
			}
		}
	}

	private void handleItemDragEnd()
	{
		UnityEngine.Debug.Log("handleItemDragEnd");
		if (dragData.dragImpostors.itemDragImpostorScreen.activeSelf)
		{
			dragData.itemDrag.transform.position = dragData.dragImpostors.itemDragImpostorScreen.transform.position;
			dragData.itemDrag.transform.rotation = dragData.dragImpostors.itemDragImpostorScreen.transform.rotation;
		}
		else if (dragData.dragImpostors.itemDragImpostorScreen.activeSelf)
		{
			dragData.itemDrag.transform.position = dragData.dragImpostors.itemDragImpostorSlot.transform.position;
			dragData.itemDrag.transform.rotation = dragData.dragImpostors.itemDragImpostorSlot.transform.rotation;
		}
		else
		{
			dragData.itemDrag.transform.position = dragData.dragImpostors.itemDragImpostorWorld.transform.position;
			dragData.itemDrag.transform.rotation = dragData.dragImpostors.itemDragImpostorWorld.transform.rotation;
		}
		dragData.itemDrag.gameObject.SetActive(value: true);
		if (gameState.current != GameState.Zoom)
		{
			stopInteraction(dragData.itemDrag.gameObject);
			controllerEndInteraction();
		}
		session.send(new ToggleVisibilityPacket
		{
			targetObject = dragData.itemDrag.gameObject,
			isVisible = true,
			positionWhenVisible = dragData.itemDrag.transform.position,
			rotationWhenVisible = dragData.itemDrag.transform.rotation
		});
		Image circle = inventorySlots[0].ui.Circle;
		destroyGameplayTweens(circle.gameObject, performEvents: true, performFinalUpdate: false);
		PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
		GameObject obj = circle.gameObject;
		Vector3? scaleTo = Vector3.zero;
		gameplayTween.tween(obj, 0.2f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo);
		circleTweenState = 0;
		foreach (Slot dragSlot in dragSlots)
		{
			UnityEngine.Debug.Log(dragSlot.gameObject.name);
			PineTweenSystemEnableNoHandles gameplayTween2 = getGameplayTween();
			GameObject obj2 = dragSlot.hotspotIndicator.gameObject;
			scaleTo = Vector3.zero;
			gameplayTween2.tween(obj2, 0.25f, 0f, deactivate: true, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo);
		}
		if (dragItemEmitter != null)
		{
			dragItemEmitter.Stop();
			UnityEngine.Object.Destroy(dragItemEmitter);
			dragItemEmitter = null;
		}
		cursorVisible.changeState(cursorVisible.last);
		destroyDragImpostors(dragData.dragImpostors);
	}

	private void controllerStartInteraction(Pointer pointer, bool virtualHiddenButMovable = false)
	{
		if (Controller.isActive())
		{
			controllerInteractionData = new ControllerInteractionData();
			controllerInteractionData.startPosition = pcVirtualCursorRT.anchoredPosition;
			UnityEngine.Debug.Log(string.Format("{0} {1}", "controllerStartInteraction", virtualHiddenButMovable));
			if (pointer.gestureDownControllerStick)
			{
				controllerInteractionData.interactingObject = pointer.context.target;
				controllerModalDrag.changeState(ButtonState.Hold);
			}
			if (virtualHiddenButMovable)
			{
				cursorVisible.changeState(CursorVisibleState.VirtualHiddenButMovable);
			}
			else
			{
				cursorVisible.changeState(CursorVisibleState.Hidden);
			}
		}
	}

