	private void handleCameraRotationInput(Pointer pointer)
	{
		if (pointer.context.overUI || gameState.current == GameState.Zoom || (!pointer.gestureCalm && controlMode.current != ControlMode.MouseAndKeyboard))
		{
			return;
		}
		float num = 0.2f;
		float num2 = 0.2f;
		if (Screen.width < Screen.height)
		{
			num2 *= (float)Screen.width / (float)Screen.height;
		}
		else
		{
			num *= (float)Screen.height / (float)Screen.width;
		}
		Vector2 zero = Vector2.zero;
		zero.x += Mathf.Min(0f, pointer.gesturePositionViewport.x - num) / num;
		zero.x += Mathf.Max(0f, pointer.gesturePositionViewport.x - 1f + num) / num;
		zero.y += (0f - Mathf.Min(0f, pointer.gesturePositionViewport.y - num2)) / num2;
		zero.y += (0f - Mathf.Max(0f, pointer.gesturePositionViewport.y - 1f + num2)) / num2;
		if (zero != Vector2.zero)
		{
			if (controlMode.current == ControlMode.MouseAndKeyboard)
			{
				zero *= Time.deltaTime * 50f;
			}
			else
			{
				zero *= Time.deltaTime * 50f * Mathf.Min(1f, pointer.gestureCalmTimer / 0.2f);
			}
			targetRotation += zero;
			targetRotation.y = Mathf.Clamp(targetRotation.y, -90f, 90f);
			currentRotation = targetRotation;
		}
	}

	private void updateCameraRotation(Vector3 offset)
	{
		if (Is.Mac && offset.magnitude != 0f)
		{
			lockedFramesAfterMouseLock++;
			if (lockedFramesAfterMouseLock < 4)
			{
				return;
			}
		}
		Vector2 vector = Vector2.one * -0.1f;
		if (controlMode.current != ControlMode.VirtualGamepad)
		{
			vector *= -1f;
		}
		if (PlayerSave.getSettings().invertLookX)
		{
			vector.x *= -1f;
		}
		if (PlayerSave.getSettings().invertLookY)
		{
			vector.y *= -1f;
		}
		float num = (isTurning = (0f - offset.x) * vector.x);
		localPlayerData.turning = isTurning;
		targetRotation.x += num;
		targetRotation.y += offset.y * vector.y;
		targetRotation.y = Mathf.Clamp(targetRotation.y, -90f, 90f);
	}

	public void removeFromBehindObjectCommandBuffer(GameObject go)
	{
		Transform[] componentsInChildren = go.GetComponentsInChildren<Transform>(includeInactive: false);
		foreach (Transform transform in componentsInChildren)
		{
			if (behindObjectsCommandBuffer.ContainsKey(transform.gameObject))
			{
				playerCamera.RemoveCommandBuffer(CameraEvent.AfterForwardOpaque, behindObjectsCommandBuffer[transform.gameObject]);
				behindObjectsCommandBuffer.Remove(transform.gameObject);
				interactedKeyObjects.Remove(transform.gameObject);
			}
		}
	}

