	public bool isAncestor(GameObject go, GameObject potentialAncestor, bool checkTheirRelationship = false)
	{
		if (checkTheirRelationship && go == potentialAncestor)
		{
			return true;
		}
		Transform parent = go.transform.parent;
		while (parent != null)
		{
			if (parent.gameObject == potentialAncestor)
			{
				return true;
			}
			parent = parent.parent;
		}
		return false;
	}

