	private void levelCompletedHandler(Finish finish)
	{
		if (isLevelCompleted && isInFinishLevelScreen)
		{
			return;
		}
		isLevelCompleted = true;
		EventReference eventReference = soundLevelComplete;
		UnityEngine.Debug.Log("Level completed! " + eventReference.ToString());
		PineFmod.playOneShotSoundAttached(soundLevelComplete, playerCamera.gameObject);
		if (isDarkestPuzzle)
		{
			PlayerSave.setLevelFinishState(levelIdentifier, PlayerSave.FinishState.Trophy);
			if (levelIdentifier == "DraculaDarkest1" && Is.Demo)
			{
				saveAchievement("ACHIEVEMENT_PUZZLE_MASTER");
			}
			if (!Is.Demo)
			{
				saveAchievement("ACHIEVEMENT_FINISH_DARKEST");
				bool flag = true;
				foreach (RoomDatabase.Room allDarkestPuzzlesRoom in RoomDatabase.getAllDarkestPuzzlesRooms())
				{
					if (!PlayerSave.isLevelFinished(allDarkestPuzzlesRoom.name))
					{
						flag = false;
					}
				}
				if (flag)
				{
					saveAchievement("ACHIEVEMENT_FINISH_ALL_DARKEST_ROOMS");
				}
			}
			string text = levelIdentifier;
			string text2 = text.Substring(0, text.Length - 1);
			bool flag2 = true;
			for (int i = 0; i < 4; i++)
			{
				if (PlayerSave.ensureAndGetLevelState($"{text2}{i + 1}").finishState != PlayerSave.FinishState.Trophy)
				{
					flag2 = false;
				}
			}
			if (flag2)
			{
				if (Enum.TryParse<Menu.AwardType>(text2, out var result))
				{
					if (!PlayerSave.getProgress().awards.Contains(result))
					{
						UnityEngine.Debug.Log("Awarded: " + result);
						PlayerSave.getProgress().awardToShowInLobby = result;
						PlayerSave.getProgress().awards.Add(result);
						PlayerSave.flush();
					}
					else
					{
						UnityEngine.Debug.Log("Already has award: " + result);
					}
				}
				else
				{
					UnityEngine.Debug.Log("Failed to parse award type from level prefix: " + text2);
				}
			}
			UnityEngine.Debug.Log(text2);
			showDarkestSolvedDialogue();
			return;
		}
		PlayerSave.FinishState finishState = ((timerCurrentTime > 0f) ? PlayerSave.FinishState.Trophy : PlayerSave.FinishState.Finished);
		PlayerSave.setLevelFinishState(levelIdentifier, finishState);
		if (levelIdentifier == "Dracula1" && Is.Demo)
		{
			saveAchievement("ACHIEVEMENT_FIRST_ESCAPE");
		}
		if (!Is.Demo && !isTestingPlaymodeInEditor)
		{
			string text = levelIdentifier;
			if (!(text == "Lobby1") && !(text == "Tutorial1"))
			{
				if (session.players.Count == 1)
				{
					saveAchievement("ACHIEVEMENT_FINISH_ROOM");
				}
				else
				{
					saveAchievement("ACHIEVEMENT_FINISH_ROOM_MP");
				}
				if (isCustomLevel())
				{
					saveAchievement("ACHIEVEMENT_FINISH_COMMUNITY_ROOM");
				}
				if (finishState == PlayerSave.FinishState.Trophy)
				{
					saveAchievement("ACHIEVEMENT_GET_TROPHY");
				}
				if (!isCustomLevel())
				{
					bool flag3 = true;
					foreach (RoomDatabase.Room item in RoomDatabase.getPackOfARoom(levelIdentifier))
					{
						PlayerSave.LevelState levelState = PlayerSave.ensureAndGetLevelState(item.name);
						if (levelState.finishState != PlayerSave.FinishState.Trophy)
						{
							flag3 = false;
						}
						if (levelState.finishState != PlayerSave.FinishState.None)
						{
							_ = 1;
						}
					}
					if (flag3)
					{
						saveAchievement("ACHIEVEMENT_GET_ALL_TROPHIES_PACK");
					}
				}
				bool flag4 = true;
				foreach (RoomDatabase.Room allRegularRoom in RoomDatabase.getAllRegularRooms())
				{
					if (PlayerSave.ensureAndGetLevelState(allRegularRoom.name).finishState != PlayerSave.FinishState.Trophy)
					{
						flag4 = false;
					}
				}
				if (flag4)
				{
					saveAchievement("ACHIEVEMENT_GET_ALL_TROPHIES_GAME");
				}
			}
		}
		if (vr.isActive())
		{
			closeVRMenu();
			return;
		}
		closeMainMenu();
		closeOptions();
		if (finish != null && finish.levelShot != null)
		{
			finish.levelShot.eyeLocalPosition = finish.levelShot.eyeLocalPosition;
			finish.levelShot.eyeLocalRotation = finish.levelShot.eyeLocalRotation;
			enterFinishLevel(finish.levelShot);
		}
		else
		{
			FinishLevelShot componentInChildren = levelContainer.GetComponentInChildren<FinishLevelShot>(includeInactive: true);
			enterFinishLevel(componentInChildren);
		}
	}

