	private void createInventorySlot(InventorySource source)
	{
		SlotTemplateUI container_SlotTemplate = default(SlotTemplateUI);
		switch (source)
		{
		case InventorySource.Inventory:
			container_SlotTemplate = slotPrefab;
			break;
		case InventorySource.Trash:
			container_SlotTemplate = slotTrashPrefab;
			break;
		case InventorySource.OtherPlayerInventory:
			container_SlotTemplate = otherPlayerInventoryUI.Container_SlotTemplate;
			break;
		case InventorySource.OtherPlayerPreview:
			container_SlotTemplate = otherPlayerPreviewUI.Container_SlotTemplate;
			break;
		default:
			global::_003CPrivateImplementationDetails_003E.ThrowSwitchExpressionException(source);
			break;
		}
		SlotTemplateUI slotTemplateUI = container_SlotTemplate;
		InventorySlot inventorySlot = new InventorySlot();
		inventorySlot.ui = UnityEngine.Object.Instantiate(slotTemplateUI, slotTemplateUI.transform.parent);
		inventorySlot.ui.gameObject.SetActive(value: true);
		inventorySlot.innerSlot = inventorySlot.ui.transform.GetChild(0).GetComponent<RectTransform>();
		if (inventorySlots.Count > 0)
		{
			List<InventorySlot> list = inventorySlots;
			RectTransform rectTransform = list[list.Count - 1].ui.rectT();
			inventorySlot.ui.rectT().anchoredPosition = rectTransform.anchoredPosition + Vector2.right * rectTransform.rect.width;
		}
		switch (source)
		{
		case InventorySource.Inventory:
			inventorySlots.Add(inventorySlot);
			break;
		case InventorySource.Trash:
			trashInventorySlots.Add(inventorySlot);
			inventorySlot.ui.gameObject.SetActive(value: false);
			inventorySlot.ui.Shortcut.gameObject.SetActive(value: false);
			inventorySlot.ui.Pocket.gameObject.SetActive(value: false);
			break;
		case InventorySource.OtherPlayerInventory:
			currentOtherPlayerInventorySlots.Add(inventorySlot);
			inventorySlot.ui.gameObject.SetActive(value: false);
			inventorySlot.ui.Shortcut.gameObject.SetActive(value: false);
			inventorySlot.ui.Pocket.gameObject.SetActive(value: false);
			break;
		case InventorySource.OtherPlayerPreview:
			previewPlayerSlots.Add(inventorySlot);
			inventorySlot.ui.gameObject.SetActive(value: false);
			inventorySlot.ui.Shortcut.gameObject.SetActive(value: false);
			inventorySlot.ui.Pocket.gameObject.SetActive(value: false);
			break;
		}
	}

