	private void updateInventory()
	{
		inventoryCanvas.gameObject.SetActive(!isInventoryHidden());
		zoomSlotUI.gameObject.SetActive(showZoomSlot && !isInventoryHidden());
		inventoryCanvas.anchoredPosition = Vector2.MoveTowards(inventoryCanvas.anchoredPosition, getInventoryCanvasEndPosition(), Time.deltaTime * 750f);
		bool flag = controlMode.current == ControlMode.MouseAndKeyboard;
		for (int i = 0; i < inventorySlots.Count; i++)
		{
			inventorySlots[i].ui.PinIcon.gameObject.SetActive(value: false);
			inventorySlots[i].ui.Selected.gameObject.SetActive(value: false);
			inventorySlots[i].ui.Circle.gameObject.SetActive(i == 0 && !flag);
		}
		updateInventory(flag, trashInventory, trashInventorySlots, trashInventoryGridContainer.cellScale, trashInventoryGridContainer);
		GridContainer gridContainer = (inSlotInventoryFocus ? trashInventoryGridContainer : inventoryGridContainer);
		updateInventory(flag, inventory, inventorySlots, gridContainer.cellScale, gridContainer);
		updateInventory(flag, currentOtherPlayerInventory, currentOtherPlayerInventorySlots, otherPlayerInventoryUI.Container.cellScale, otherPlayerInventoryUI.Container);
		updateInventory(flag, previewPlayerInventory, previewPlayerSlots, 1f, null);
		updateInventoryItemsNames();
		updateTrashItemsNames();
		updateOtherPlayerItemsNames();
		void updateInventoryItemsNames()
		{
			bool flag2 = inventorySlots.Any((InventorySlot x) => x.ui.Hover.gameObject.activeInHierarchy);
			for (int num = 0; num < inventory.Count; num++)
			{
				InventoryItem inventoryItem = inventory[num];
				GameObject gameObject = inventoryItem.topGameObject();
				ItemUI itemUI = inventorySlots[num + 1].ui.InventoryItemUI;
				if (itemUI.selectedObject != gameObject)
				{
					setupItemUI(itemUI, gameObject, canBeStreamlined: true);
					RectTransform component = itemUI.nameLbl.GetComponent<RectTransform>();
					RectTransform component2 = itemUI.GetComponent<RectTransform>();
					LayoutRebuilder.ForceRebuildLayoutImmediate(component2);
					float num2 = Mathf.Min((float)(45 + num * 80) - component.sizeDelta.x / 2f, 0f);
					component2.anchoredPosition = new Vector2(0f - num2, 0f);
					itemUI.panel.alpha = 0f;
					itemUI.selectedObject = inventoryItem.topGameObject();
				}
				inventoryItem.impostorClone.gameObject.SetActive(!isInventoryHidden());
				float target = ((pcSelectedItem == num && !flag2 && gameState.current != GameState.Zoom) ? 1f : 0f);
				itemUI.panel.alpha = Mathf.MoveTowards(itemUI.panel.alpha, target, Time.deltaTime * 10f);
			}
		}
		void updateOtherPlayerItemsNames()
		{
			for (int j = 0; j < currentOtherPlayerInventory.Count; j++)
			{
				InventoryItem inventoryItem = currentOtherPlayerInventory[j];
				GameObject gameObject = inventoryItem.topGameObject();
				ItemUI itemUI = currentOtherPlayerInventorySlots[j + 1].ui.InventoryItemUI;
				if (itemUI.selectedObject != gameObject)
				{
					setupItemUI(itemUI, gameObject, canBeStreamlined: true);
					itemUI.panel.alpha = 0f;
					itemUI.selectedObject = inventoryItem.topGameObject();
				}
				float target = ((otherPlayerInventoryUI.Container.hover == j) ? 1f : 0f);
				itemUI.panel.alpha = Mathf.MoveTowards(itemUI.panel.alpha, target, Time.deltaTime * 10f);
			}
		}
		void updateTrashItemsNames()
		{
			for (int j = 0; j < trashInventory.Count; j++)
			{
				InventoryItem inventoryItem = trashInventory[j];
				GameObject gameObject = inventoryItem.topGameObject();
				ItemUI itemUI = trashInventorySlots[j + 1].ui.InventoryItemUI;
				if (itemUI.selectedObject != gameObject)
				{
					setupItemUI(itemUI, gameObject, canBeStreamlined: true);
					itemUI.panel.alpha = 0f;
					itemUI.selectedObject = inventoryItem.topGameObject();
				}
				float target = ((trashInventoryGridContainer.hover == j) ? 1f : 0f);
				itemUI.panel.alpha = Mathf.MoveTowards(itemUI.panel.alpha, target, Time.deltaTime * 10f);
			}
		}
	}

	private bool isInventoryHidden()
	{
		if (!disableInventory.getValue(MultipleSourcesGetStrategy.HasAny))
		{
			return gameState.current == GameState.FinishLevel;
		}
		return true;
	}

	private void updateInventory(bool isPC, List<InventoryItem> inventory, List<InventorySlot> inventorySlots, float cellScale, GridContainer inventoryGridContainer)
	{
		if (controlMode.current == ControlMode.VR)
		{
			return;
		}
		int num = -1;
		int i;
		for (i = 0; i < inventory.Count; i++)
		{
			InventoryItem inventoryItem = inventory[i];
			Transform transform = inventoryItem.impostorClone.transform;
			Item component = inventoryItem.topGameObject().GetComponent<Item>();
			InventorySlot inventorySlot = inventorySlots[i + 1];
			if (inventorySlot.centerLocalSet)
			{
				float t = Mathf.Clamp01(inventoryItem.transitionTime * 5f);
				transform.localRotation = Quaternion.Lerp(inventoryItem.transitionRotation, Quaternion.Euler(component.examineBaseRotation) * Quaternion.Euler(component.inventoryRotationOffset), t);
				Vector3 b = component.gameObject.transform.lossyScale.normalized * (1.75f * component.examineScaleModifier * 0.1f * inventoryItemScale * cellScale * component.inventoryScale);
				transform.localScale = Vector3.Lerp(inventoryItem.transitionScale, b, t);
				Vector3 vector = Vector3.Scale(transform.localScale, transform.localRotation * component.examinePivotOffset);
				Vector3 b2 = inventorySlot.centerLocal + vector + component.inventoryPositionOffset * 0.01f;
				Vector3 localPosition = Vector3.Lerp(inventoryItem.transitionPosition, b2, t);
				if (isInventoryHidden() || !inventorySlot.ui.gameObject.activeInHierarchy)
				{
					localPosition = Vector3.one * 10000f;
				}
				transform.localPosition = localPosition;
			}
			inventorySlot.ui.Circle.transform.localScale = Vector3.zero;
			PinnedItemInfo pinnedItemInfo = pinnedItems.Find((PinnedItemInfo x) => x.originalItem == inventory[i].topGameObject());
			bool active = pinnedItemInfo != null && !pinnedItemInfo.isWearable;
			bool active2 = pinnedItemInfo?.isWearable ?? false;
			inventorySlot.ui.PinIcon.gameObject.SetActive(active);
			inventorySlot.ui.ShirtIcon.gameObject.SetActive(active2);
			if (num == -1 && topZoomContextSafe(out var context) && inventory[i].gameObjects.Contains(context.selected))
			{
				num = i;
				pcChangeItemSelectionIndex(i);
			}
			if (num == -1 && toolZoomObject != null && inventory[i].gameObjects.Contains(toolZoomObject))
			{
				num = i;
				pcChangeItemSelectionIndex(i);
			}
			float num2 = Time.time - inventoryItem.pingTimestamp;
			bool flag = num2 < 1f;
			if (flag)
			{
				float value = Mathf.Sin(num2 * MathF.PI * 4f) * 0.05f;
				Image pingBg = inventorySlot.ui.PingBg;
				Color color = inventorySlot.ui.PingBg.color;
				float? a = value;
				pingBg.color = color.With(null, null, null, a);
				float num3 = UnityUtils.map(0f, 1f, 1.5f, 1f, Interpolation.OutQuart.evaluate(num2));
				float value2 = Interpolation.OutQuart.evaluate(num2);
				inventorySlot.ui.PingBg_PingCircle.transform.localScale = Vector3.one * num3;
				Image pingBg_PingCircle = inventorySlot.ui.PingBg_PingCircle;
				Color color2 = inventorySlot.ui.PingBg_PingCircle.color;
				a = value2;
				pingBg_PingCircle.color = color2.With(null, null, null, a);
			}
			inventorySlot.ui.PingBg.gameObject.SetActive(flag);
			inventoryItem.transitionTime += Time.deltaTime;
		}
		for (int num4 = 1; num4 < inventorySlots.Count; num4++)
		{
			List<GameObject> gameObjects = inventory[num4 - 1].gameObjects;
			InventorySlot inventorySlot2 = inventorySlots[num4];
			inventorySlot2.ui.CollectionBackground.gameObject.SetActive(!isPC && gameObjects.Count > 1);
			inventorySlot2.ui.CollectionBackground_CollectionCount.text = gameObjects.Count.ToString();
			inventorySlot2.ui.CollectionBackgroundPC.gameObject.SetActive(isPC && gameObjects.Count > 1);
			inventorySlot2.ui.CollectionBackgroundPC_CollectionCount.text = $"{gameObjects.Count}x";
		}
		if (inventoryGridContainer != null)
		{
			if (controlMode.current == ControlMode.VirtualGamepad)
			{
				inventoryGridContainer.selected = num;
			}
			else
			{
				inventoryGridContainer.selected = ((num != -1) ? num : pcSelectedItem);
			}
		}
	}

	private void updateInventorySlots(List<InventorySlot> inventorySlots, bool updateShortcut = true, bool hideShortcuts = false)
	{
		if (Controller.isActive() || isVR())
		{
			hideShortcuts = true;
		}
		inventoryCanvas.transform.parent.GetComponent<Canvas>().worldCamera = utilityCamera;
		utilityCamera.aspect = playerCamera.aspect;
		uiCamera.aspect = playerCamera.aspect;
		for (int i = 0; i < inventorySlots.Count; i++)
		{
			Rect rect = calculateRectTransformViewportRect(inventorySlots[i].innerSlot, utilityCamera);
			Vector3 vector = new Vector3(rect.center.x, rect.center.y, 0f);
			Vector3 position = uiCamera.ViewportToWorldPoint(vector + Vector3.forward);
			Vector3 centerLocal = uiCamera.transform.InverseTransformPoint(position);
			inventorySlots[i].centerLocal = centerLocal;
			inventorySlots[i].centerLocalSet = true;
			if (hideShortcuts)
			{
				inventorySlots[i].ui.Shortcut.gameObject.SetActive(value: false);
			}
			else if (updateShortcut)
			{
				inventorySlots[i].ui.Shortcut.text = ((i <= 9) ? digitsAsStrings[i] : "");
				inventorySlots[i].ui.Shortcut.gameObject.SetActive(i > 0);
			}
		}
		inventoryCanvas.transform.parent.GetComponent<Canvas>().worldCamera = playerCamera;
		bool active = inventory.Count > 0 && Controller.isActive() && !inSlotInventoryFocus && !isInventoryHidden();
		foreach (RectTransform controllerInventoryHint in controllerInventoryHints)
		{
			controllerInventoryHint.gameObject.SetActive(active);
		}
		static Rect calculateRectTransformViewportRect(RectTransform rectTransform, Camera camera)
		{
			rectTransform.GetWorldCorners(sharedWorldCorners);
			Bounds bounds = new Bounds(camera.WorldToViewportPoint(sharedWorldCorners[0]), Vector3.zero);
			for (int j = 1; j < 4; j++)
			{
				bounds.Encapsulate(camera.WorldToViewportPoint(sharedWorldCorners[j]));
			}
			return new Rect(bounds.min.x, bounds.min.y, bounds.size.x, bounds.size.y);
		}
	}

	private int cursorOverInventorySlot(Vector3 viewportPos, InventorySource source)
	{
		if (Controller.isActive())
		{
			return -1;
		}
		List<InventorySlot> list = null;
		switch (source)
		{
		case InventorySource.Inventory:
			list = inventorySlots;
			break;
		case InventorySource.Trash:
			list = trashInventorySlots;
			break;
		case InventorySource.OtherPlayerInventory:
			list = currentOtherPlayerInventorySlots;
			break;
		}
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].ui.gameObject.activeSelf && inventorySlotContains(list[i], viewportPos))
			{
				return i;
			}
		}
		return -1;
	}

	private bool inventorySlotContains(InventorySlot slot, Vector2 location)
	{
		bool num = rectTransformContains(slot.ui.root.rectT(), location);
		bool flag = inventorySlotHoverContains(slot, location);
		return num || flag;
	}

	private bool inventorySlotHoverContains(InventorySlot slot, Vector2 location)
	{
		return rectTransformContains(slot.ui.Hover.rectT(), location);
	}

	private void dropFromInventory()
	{
		if (!topZoomContextSafe(out var context) || !handleZoomLeave())
		{
			return;
		}
		GameObject item = context.selected;
		int num = -1;
		if (context.selected == item)
		{
			num = inventory.FindIndex((InventoryItem x) => x.gameObjects.Contains(item));
			if (inventory[num].gameObjects.Count <= 1)
			{
				num--;
			}
			if (num < 0 && inventory.Count >= 2)
			{
				num = 0;
			}
		}
		performItemDrop(item);
		if (num != -1)
		{
			handleZoomEnter(inventory[num].topGameObject(), ScreenTargetType.ItemInventory);
		}
	}

	private void addZoomedItemToInventory()
	{
		if (topZoomContextSafe(out var context) && handleZoomLeave())
		{
			addItemToInventory(context.selected);
		}
	}

	public void transitionItemToInventory(GameObject item, bool returnBorrowed = false, int preferredInventoryIndex = 0, float transitionOriginScaleModifier = 1f, bool shouldRemoveFromSlotIfNeeded = true)
	{
		addItemToInventoryInternal(item, transition: true, returnBorrowed, preferredInventoryIndex, transitionOriginScaleModifier, shouldRemoveFromSlotIfNeeded);
	}

	[LuaAPI]
	public void addItemToInventory(GameObject item, bool returnBorrowed = false, int preferredInventoryIndex = 0, float transitionOriginScaleModifier = 1f, bool shouldRemoveFromSlotIfNeeded = true)
	{
		addItemToInventoryInternal(item, transition: false, returnBorrowed, preferredInventoryIndex, transitionOriginScaleModifier, shouldRemoveFromSlotIfNeeded);
	}

	private void addItemToInventoryInternal(GameObject item, bool transition, bool returnBorrowed = false, int preferredInventoryIndex = 0, float transitionOriginScaleModifier = 1f, bool shouldRemoveFromSlotIfNeeded = true)
	{
		if (item == null)
		{
			UnityEngine.Debug.LogError("Cannot add null item to inventory.");
			return;
		}
		if (isInInventory(item) && !returnBorrowed)
		{
			UnityEngine.Debug.LogError("Cannot add item '" + item.name + "' to inventory as it is already in the player's inventory.", item);
			return;
		}
		if (isInAnyOtherPlayerInventory(item) && !isLoadingSaveFile)
		{
			UnityEngine.Debug.LogError("Cannot add item '" + item.name + "' to inventory as it is already in other player's inventory.", item);
			return;
		}
		if (item.TryGetComponent<Breakable>(out var component) && component.isBrokenIntoPieces)
		{
			UnityEngine.Debug.LogError("Cannot add Breakable '" + item.name + "' to inventory as it is broken into pieces.", item);
			return;
		}
		if (isLoadingSaveFile && !item.activeInHierarchy)
		{
			setParent(item.transform, levelContainerTransform);
			item.SetActive(value: true);
		}
		int manualAddBubbleIndex = preferredInventoryIndex;
		Item component2 = item.GetComponent<Item>();
		if (component2 != null)
		{
			if (getItemState(component2) == ItemState.SlotAnimation)
			{
				UnityEngine.Debug.LogError("Cannot add item '" + item.name + "' to inventory as it is being animated towards slot.", component2);
				return;
			}
			if (component2.resetTargetPriorityOnInventoryAdd)
			{
				component2.targetPriority = -1;
			}
		}
		if (isVR())
		{
			forceEndGrabVRForObject(item);
			int num = 0;
			if (vrInventory.Count > 0)
			{
				for (int i = 0; i < preferredInventoryIndex; i++)
				{
					if (!(vrInventory[i].original != null))
					{
						num++;
					}
				}
			}
			preferredInventoryIndex -= num;
		}
		if (!isLoadingSaveFile)
		{
			if (isProcessingPacket)
			{
				UnityEngine.Debug.LogWarning($"{base.name} Trying to add item {item} to inventory while processing packet.", item);
			}
			bool flag = isProcessingPacket;
			isProcessingPacket = false;
			startInteraction(item);
			session.send(new InventoryActionPacket
			{
				item = component2,
				isAddedToInventory = true
			}, allowSendInMessageResponse: true);
			isProcessingPacket = flag;
		}
		if (localPlayerData != null)
		{
			localPlayerData.lastPlayerPickUpItem = true;
		}
		if (!isLoadingSaveFile)
		{
			updatePuzzleInteraction(item);
			if (getRelevantPuzzlesFor(item).Contains(getCurrentPuzzleIndex()))
			{
				inventoryHistoryCurrentPuzzle.Add(item);
			}
		}
		InventoryItem inventoryItem = null;
		Item component3 = item.GetComponent<Item>();
		foreach (InventoryItem item2 in inventory)
		{
			Item component4 = item2.gameObjects[0].GetComponent<Item>();
			if (component4 != null && component3 != null && component4.collectionId != 0 && component4.collectionId == component3.collectionId)
			{
				inventoryItem = item2;
			}
		}
		bool flag2 = false;
		if (shouldRemoveFromSlotIfNeeded)
		{
			flag2 = isInSlot(component2) != null;
			removeItemFromSlotLocal(component3);
		}
		if (component2 != null)
		{
			component2.hasRigidbody = true;
		}
		removeFromBehindObjectCommandBuffer(item);
		destroyGameplayTweens(item, performEvents: false, performFinalUpdate: false);
		Vector3 position = item.transform.position;
		Quaternion rotation = item.transform.rotation;
		Vector3 lossyScale = item.transform.lossyScale;
		Vector3 vector = item.transform.position;
		Quaternion rotation2 = item.transform.rotation;
		Vector3 vector2 = item.transform.localScale * transitionOriginScaleModifier;
		Vector3 localScale = zoomAttachment.localScale;
		zoomAttachment.localScale = Vector3.one;
		setParent(item.transform, levelContainerTransform);
		zoomAttachment.localScale = localScale;
		Bounds bounds = computeLocalBounds(item);
		if (gameState.current != GameState.Zoom)
		{
			vector = utilityCamera.ViewportToWorldPoint(utilityCamera.WorldToViewportPoint(item.transform.position));
		}
		else
		{
			foreach (Pointer pointer in pointers)
			{
				if (pointer.context.targetType == ScreenTargetType.ItemInventory && dragData.itemDrag.gameObject == item)
				{
					GameObject itemDragImpostorScreen = dragData.dragImpostors.itemDragImpostorScreen;
					vector = itemDragImpostorScreen.transform.position;
					rotation2 = itemDragImpostorScreen.transform.rotation;
					vector2 = itemDragImpostorScreen.transform.localScale;
				}
			}
		}
		bool flag3 = false;
		if (returnBorrowed)
		{
			int num2 = inventory.FindIndex(0, inventory.Count, (InventoryItem x) => x.gameObjects.Contains(item));
			if (num2 != -1)
			{
				InventoryItem inventoryItem2 = inventory[num2];
				inventoryItem2.scenePosition = position;
				inventoryItem2.sceneRotation = rotation;
				inventoryItem2.sceneLocalScale = lossyScale;
			}
		}
		else if (inventoryItem != null)
		{
			inventoryItem.gameObjects.Add(item);
			inventoryItem.localBoundsCollection.Add(bounds);
			if (inventoryItem.impostorClone != null)
			{
				UnityEngine.Object.Destroy(inventoryItem.impostorClone.gameObject);
			}
			inventoryItem.impostorClone = createInventoryImpostor(item);
			inventoryItem.localBounds = bounds;
			inventoryItem.scenePosition = position;
			inventoryItem.sceneRotation = rotation;
			inventoryItem.sceneLocalScale = lossyScale;
		}
		else
		{
			createInventorySlot(InventorySource.Inventory);
			Vector3 vector3 = vector;
			Quaternion quaternion = rotation2;
			Vector3 vector4 = vector2;
			InventoryItem inventoryItem3 = new InventoryItem
			{
				transitionTime = (transition ? 0f : 1000f),
				transitionPosition = vector3,
				transitionRotation = quaternion,
				transitionScale = vector4,
				scenePosition = position,
				sceneRotation = rotation,
				sceneLocalScale = lossyScale,
				localBounds = bounds
			};
			inventoryItem3.gameObjects.Add(item);
			inventoryItem3.localBoundsCollection.Add(bounds);
			if (inventoryItem3.impostorClone != null)
			{
				UnityEngine.Object.Destroy(inventoryItem3.impostorClone.gameObject);
			}
			inventoryItem3.impostorClone = createInventoryImpostor(item);
			if (transition)
			{
				inventoryItem3.impostorClone.transform.position = vector3;
				inventoryItem3.impostorClone.transform.rotation = quaternion;
				inventoryItem3.impostorClone.transform.localScale = vector4;
			}
			inventoryItem3.transitionPosition = inventoryItem3.impostorClone.transform.localPosition;
			inventoryItem3.transitionRotation = inventoryItem3.impostorClone.transform.localRotation;
			inventoryItem3.transitionScale = inventoryItem3.impostorClone.transform.localScale;
			if (preferredInventoryIndex == -1)
			{
				inventory.Add(inventoryItem3);
			}
			else if (preferredInventoryIndex >= 0 && preferredInventoryIndex <= inventory.Count)
			{
				inventory.Insert(preferredInventoryIndex, inventoryItem3);
				flag3 = preferredInventoryIndex == pcSelectedItem;
			}
			else
			{
				UnityEngine.Debug.LogError($"[BUG] Out-of-bounds preferred inventory index: {preferredInventoryIndex} (inventory count: {inventory.Count}");
				preferredInventoryIndex = -1;
				inventory.Add(inventoryItem3);
			}
			if (inventory.Count < inventorySlots.Count)
			{
				InventorySlot inventorySlot = inventorySlots[inventory.Count];
				inventorySlot.ui.gameObject.SetActive(value: true);
				inventorySlot.ui.Pocket.gameObject.SetActive(value: false);
				inventorySlot.ui.Circle.transform.localScale = Vector3.zero;
			}
		}
		item.SetActive(value: false);
		if (!flag2)
		{
			if (!component3.playedPickupStinger)
			{
				ItemType itemType = component3.itemType;
				if (itemType == ItemType.Key || itemType == ItemType.Clue)
				{
					component3.playedPickupStinger = true;
					string sound = ((component3.itemType == ItemType.Key) ? "event:/Sound Effects/00 General/Pickup/Pickup_Key_Item" : "event:/Sound Effects/00 General/Pickup/Pickup_Clue_Item");
					if (shouldShowItemHints())
					{
						PineFmod.playOneShotSoundAttached(sound, item);
					}
				}
			}
			if (!component3.soundPickup.IsNull)
			{
				PineFmod.playOneShotSoundAttached(component3.soundPickup, item);
			}
			else
			{
				PineFmod.playOneShotSoundAttached("event:/Sound Effects/00 General/Pickup/Pickup_Item", item);
			}
		}
		if (flag3 && controlMode.current != ControlMode.VirtualGamepad)
		{
			pcChangeItemSelectionIndex(preferredInventoryIndex + 1, 1f, 0f, playSound: false);
		}
		if (isVR())
		{
			Vector3 position2 = position + item.transform.TransformDirection(bounds.center);
			UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(animationPoof, position2, Quaternion.identity, levelContainer.transform), 3f);
			if (vrInventory.Count > 0)
			{
				int index = inventory.FindIndex((InventoryItem inventoryItem4) => inventoryItem4.gameObjects.Contains(item));
				addSingleItemToVrInventory(inventory[index], manualAddBubbleIndex);
			}
		}
		if (!isLoadingSaveFile)
		{
			callOrDeferOnAddItemToInventory(component2);
		}
		syncControllerInventorySlotPositions();
	}

	public int removeItemFromInventory(GameObject item, bool isForDrag = false, bool syncMultiplayer = true, InventoryRemovalBehaviour removal = InventoryRemovalBehaviour.RemainingCollectionOrNothing)
	{
		UnityEngine.Debug.Log("removeItemFromInventory");
		Item component = item.GetComponent<Item>();
		if (component != null && getItemState(component) == ItemState.SlotAnimation)
		{
			UnityEngine.Debug.Log("Trying to remove an item that is borrowed. This is not allowed");
			return -1;
		}
		InventoryItem inventoryItem = inventory.Find((InventoryItem x) => x.gameObjects.Contains(item));
		if (inventoryItem == null)
		{
			UnityEngine.Debug.Log("inventoryItem is null! base item is: " + item);
			return -1;
		}
		bool flag = inventoryItem.gameObjects.Count > 1;
		int num = inventory.IndexOf(inventoryItem);
		if (syncMultiplayer)
		{
			session.send(new InventoryActionPacket
			{
				item = component,
				isAddedToInventory = false,
				disableItemWhenRemoving = !isForDrag
			}, allowSendInMessageResponse: true);
			stopInteraction(item);
		}
		if (pinnedItems.Find((PinnedItemInfo x) => x.originalItem == item) != null)
		{
			handleUnpinItem(item, setItemInWorld: true);
		}
		bool flag2 = controlMode.current == ControlMode.MouseAndKeyboard;
		if (inventoryItem.gameObjects.Count > 1)
		{
			int index = inventoryItem.gameObjects.IndexOf(item);
			inventoryItem.gameObjects.RemoveAt(index);
			inventoryItem.localBoundsCollection.RemoveAt(index);
			inventoryItem.localBounds = inventoryItem.topLocalBounds();
			if (inventoryItem.impostorClone != null)
			{
				UnityEngine.Object.Destroy(inventoryItem.impostorClone.gameObject);
			}
			inventoryItem.impostorClone = createInventoryImpostor(inventoryItem.topGameObject());
		}
		else
		{
			InventorySlot inventorySlot = inventorySlots[inventory.Count - 1];
			GameObject gameObject = inventorySlot.ui.Pocket.gameObject;
			if (inventory.Count > 1)
			{
				gameObject.transform.localScale = Vector3.zero;
			}
			gameObject.SetActive(controlMode.current != ControlMode.MouseAndKeyboard);
			GameObject gameObject2 = inventorySlot.ui.Circle.gameObject;
			PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
			Vector3? scaleTo = Vector3.zero;
			gameplayTween.tween(gameObject2, 0.2f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo);
			InventorySlot inventorySlot2 = inventorySlots[inventory.Count];
			if (flag2)
			{
				getGameplayTween().destroyTweens(inventorySlot2.ui.gameObject);
				getGameplayTween().destroyTweens(inventorySlot2.ui.Circle.gameObject);
				getGameplayTween().destroyTweens(inventorySlot2.ui.Pocket.gameObject);
				UnityEngine.Object.Destroy(inventorySlot2.ui.gameObject);
			}
			else
			{
				UnityEngine.Object.Destroy(inventorySlot2.ui.gameObject);
			}
			if (inventoryItem.impostorClone != null)
			{
				UnityEngine.Object.Destroy(inventoryItem.impostorClone.gameObject);
			}
			inventory.Remove(inventoryItem);
			inventorySlots.RemoveAt(inventorySlots.Count - 1);
		}
		levelLogic.onRemoveFromInventory(item.GetComponent<Item>());
		Vector3 localScale = zoomAttachment.transform.localScale;
		zoomAttachment.transform.localScale = Vector3.one;
		setParent(item.transform, levelContainerTransform);
		zoomAttachment.transform.localScale = localScale;
		item.SetActive(value: true);
		if (controlMode.current == ControlMode.MouseAndKeyboard && pcSelectedItem != -1)
		{
			if (pcSelectedItem == num)
			{
				switch (removal)
				{
				case InventoryRemovalBehaviour.RemainingCollectionOrNothing:
					if (flag)
					{
						pcChangeItemSelectionIndex(pcSelectedItem, 1f, 0f, playSound: true, forceChangeSelection: true);
					}
					else
					{
						pcChangeItemSelectionIndex(-1);
					}
					break;
				case InventoryRemovalBehaviour.RemainingCollectionOrClosest:
					if (flag)
					{
						pcChangeItemSelectionIndex(pcSelectedItem, 1f, 0f, playSound: true, forceChangeSelection: true);
					}
					else if (pcSelectedItem >= num)
					{
						pcChangeItemSelectionIndex(Mathf.Min(pcSelectedItem, inventory.Count - 1), 1f, 0f, playSound: true, forceChangeSelection: true);
					}
					break;
				}
			}
			else if (pcSelectedItem > num)
			{
				pcSelectedItem--;
			}
		}
		return num;
	}

	private void inventoryItemImpostorPass(ImpostorClone clone)
	{
		SkinnedMeshRenderer[] componentsInChildren = clone.gameObject.GetComponentsInChildren<SkinnedMeshRenderer>(includeInactive: true);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].updateWhenOffscreen = true;
		}
		ImpostorClone.replaceMaterialsWithUnlit(clone.gameObject, fakeItemMaterial, fakeItemTransparentMaterial);
		Renderer[] componentsInChildren2 = clone.gameObject.GetComponentsInChildren<Renderer>(includeInactive: true);
		foreach (Renderer renderer in componentsInChildren2)
		{
			if (renderer.gameObject.CompareTag("DisableInPin"))
			{
				UnityEngine.Object.DestroyImmediate(renderer);
			}
		}
		Renderer[] componentsInChildren3 = clone.gameObject.GetComponentsInChildren<Renderer>();
		fillRendererLists(componentsInChildren3, clone.renderersOpaque, clone.renderersTransparent);
	}

	private ImpostorClone createInventoryImpostor(GameObject item)
	{
		GameObject gameObject;
		if (controlMode.current == ControlMode.VR)
		{
			gameObject = ImpostorClone.create(impostorContext, item, LayerMask.NameToLayer("ItemOverUI"), strip: true, inventoryItemImpostorPass);
			gameObject.gameObject.SetActive(value: false);
		}
		else
		{
			gameObject = ImpostorClone.create(impostorContext, item, LayerMask.NameToLayer("ItemOverUI"), strip: true, inventoryItemImpostorPass);
			setParent(gameObject.transform, playerCamera.transform, worldPositionStays: false);
			gameObject.transform.localScale = Vector3.zero;
		}
		gameObject.name = $"Inventory Clone: {item}";
		ImpostorClone component = gameObject.GetComponent<ImpostorClone>();
		inventoryItemImpostorPass(component);
		return component;
	}

	private void initItemRespawnSystem()
	{
		itemRespawnTriggers.Clear();
		HashSet<Collider> hashSet = new HashSet<Collider>();
		ItemRespawnVolume[] componentsInChildren = levelContainer.transform.GetComponentsInChildren<ItemRespawnVolume>(includeInactive: true);
		ItemRespawnVolume[] array = componentsInChildren;
		for (int i = 0; i < array.Length; i++)
		{
			Collider[] componentsInChildren2 = array[i].GetComponentsInChildren<Collider>(includeInactive: true);
			foreach (Collider collider in componentsInChildren2)
			{
				if (hashSet.Add(collider))
				{
					if (!collider.isTrigger)
					{
						UnityEngine.Debug.LogError("Collider '" + collider.name + "' is a child of 'ItemRespawnVolume', but is not set as trigger.", collider);
					}
					else
					{
						itemRespawnTriggers.Add(collider.GetOrAddComponent<CollisionData>());
					}
				}
			}
		}
		if (componentsInChildren.Length != 0)
		{
			UnityEngine.Debug.Log(string.Format("[{0}] Initialized with {1} respawn triggers.", "initItemRespawnSystem", itemRespawnTriggers.Count), componentsInChildren[0]);
		}
		else
		{
			UnityEngine.Debug.LogError("[initItemRespawnSystem] No 'ItemRespawnVolume' defined in the scene.");
		}
	}

	private void updateItemRespawnSystem()
	{
		updateItemRespawnSystemRespawnEntries();
		if (itemRespawnCheckTimer > 0f)
		{
			itemRespawnCheckTimer -= Time.deltaTime;
			return;
		}
		updateItemRespawnSystemUnderground();
		updateItemRespawnSystemRespawnAreas();
		itemRespawnCheckTimer = 1f;
	}

	private void updateItemRespawnSystemRespawnEntries()
	{
		for (int num = itemRespawnEntries.Count - 1; num >= 0; num--)
		{
			ItemRespawnEntry itemRespawnEntry = itemRespawnEntries[num];
			itemRespawnEntry.respawnTimer -= Time.deltaTime;
			if (!(itemRespawnEntry.respawnTimer > 0f))
			{
				respawnItem(itemRespawnEntry.itemRigidbody, itemRespawnEntry.item, itemRespawnEntry.respawnVolume);
				itemRespawnEntries.RemoveAt(num);
			}
		}
	}

	private void updateItemRespawnSystemUnderground()
	{
		foreach (Item keyItem in keyItems)
		{
			if (!(keyItem.transform.position.y >= -100f) && !(keyItem.rigidbody == null) && hasAuthority(keyItem.gameObject))
			{
				Rigidbody parentRigidbody = getParentRigidbody(keyItem.rigidbody);
				parentRigidbody.position = Vector3.zero;
				parentRigidbody.transform.position = Vector3.zero;
				respawnItem(parentRigidbody, parentRigidbody.GetComponent<Item>(), null);
			}
		}
		foreach (Item nonKeyItem in nonKeyItems)
		{
			if (!(nonKeyItem.transform.position.y >= -100f) && !(nonKeyItem.rigidbody == null))
			{
				Vector3 position = nonKeyItem.transform.position;
				position.y = -100f;
				nonKeyItem.transform.position = position;
				nonKeyItem.gameObject.SetActive(value: false);
			}
		}
	}

	private void updateItemRespawnSystemRespawnAreas()
	{
		foreach (CollisionData itemRespawnTrigger in itemRespawnTriggers)
		{
			if (itemRespawnTrigger == null)
			{
				UnityEngine.Debug.LogError("Collision Data for respawning items is null");
			}
			else
			{
				if (itemRespawnTrigger.allTouchingNonAllocUnsafe.Count <= 0)
				{
					continue;
				}
				Collider[] array = itemRespawnTrigger.allTouchingSnapshot();
				for (int num = array.Length - 1; num >= 0; num--)
				{
					Rigidbody rb = getParentRigidbody(array[num].GetComponentInParent<Rigidbody>());
					itemRespawnTrigger.removeCollider(array[num]);
					if (!(rb == null))
					{
						Item componentInParent = rb.gameObject.GetComponentInParent<Item>();
						if (!(componentInParent == null) && componentInParent.itemRespawn != ItemRespawn.NeverRespawn && itemRespawnEntries.Find((ItemRespawnEntry entry) => entry.itemRigidbody == rb) == null && (componentInParent.itemRespawn == ItemRespawn.AlwaysRespawn || componentInParent.itemType != ItemType.Undefined))
						{
							itemRespawnEntries.Add(new ItemRespawnEntry
							{
								itemRigidbody = rb,
								item = componentInParent,
								respawnTimer = 0.3f,
								respawnVolume = itemRespawnTrigger.GetComponentInParent<ItemRespawnVolume>()
							});
						}
					}
				}
			}
		}
	}

	private void respawnItem(Rigidbody rb, Item item, ItemRespawnVolume respawnVolume)
	{
		UnityEngine.Debug.Log($"Respawning item: {item} from {respawnVolume?.name}", item);
		if (respawnVolume == null || respawnVolume.respawnMode == ItemRespawnVolume.RespawnMode.ToPlayerInventory)
		{
			if (!(rb == null) && hasAuthority(rb.gameObject))
			{
				if (item.carriable)
				{
					Vector3 position = localPlayerData.lastTransformPose.position + Vector3.up * 0.8f;
					rb.MovePosition(position);
					rb.transform.position = position;
					Physics.SyncTransforms();
				}
				else
				{
					addItemToInventory(rb.gameObject, returnBorrowed: false, inventory.Count);
					addChatMessageLocal(item.displayName, "", ChatMessage.Type.RespawnedItem);
				}
			}
			return;
		}
		ItemRespawnVolume.RespawnMode respawnMode = respawnVolume.respawnMode;
		int num;
		Vector3 vector;
		if (respawnMode == ItemRespawnVolume.RespawnMode.ToOriginalPositionAndRotation || respawnMode == ItemRespawnVolume.RespawnMode.ToAnObject)
		{
			if (respawnVolume.respawnMode == ItemRespawnVolume.RespawnMode.ToAnObject)
			{
				num = ((respawnVolume.objectToRespawnTo != null) ? 1 : 0);
				if (num != 0)
				{
					vector = respawnVolume.objectToRespawnTo.position;
					goto IL_0106;
				}
			}
			else
			{
				num = 0;
			}
			vector = item.initialPosition;
			goto IL_0106;
		}
		UnityEngine.Debug.LogError($"Unknown respawn type '{respawnVolume.respawnMode}' for item '{item}'.", item);
		return;
		IL_0106:
		Vector3 position2 = vector;
		Quaternion rotation = ((num != 0) ? respawnVolume.objectToRespawnTo.rotation : item.initialRotation);
		item.gameObject.transform.position = position2;
		item.gameObject.transform.rotation = rotation;
		item.hasRigidbody = respawnVolume.respawnWithPhysics;
		if (rb != null)
		{
			rb.position = position2;
			rb.rotation = rotation;
			rb.linearVelocity = Vector3.zero;
			rb.angularVelocity = Vector3.zero;
		}
	}

	private Rigidbody getParentRigidbody(Rigidbody child)
	{
		if (child == null)
		{
			return child;
		}
		Rigidbody componentInParent = child.transform.parent.GetComponentInParent<Rigidbody>();
		if (componentInParent != null)
		{
			return getParentRigidbody(componentInParent);
		}
		return child;
	}

	public void registerPredicate<T>(T type, params Func<bool>[] predicates) where T : Enum
	{
		registerPredicate(type, 0f, canBeUndone: false, predicates);
	}

	public void registerPredicate<T>(T type, float timeToTrigger, bool canBeUndone, params Func<bool>[] predicates) where T : Enum
	{
		int typeValue = (int)(object)type;
		if (!levelPredicates.TryFind((LevelPredicate predicate) => predicate.type == typeValue, out var _))
		{
			levelPredicates.Add(new LevelPredicate(new List<Func<bool>>(predicates), typeValue, timeToTrigger, canBeUndone));
			return;
		}
		T val = type;
		UnityEngine.Debug.LogError("Predicate type already registered: " + val);
	}

	private void updateLevelPredicates()
	{
		if (!isHost())
		{
			return;
		}
		foreach (LevelPredicate levelPredicate in levelPredicates)
		{
			if (levelPredicate.done && !levelPredicate.canBeUndone)
			{
				continue;
			}
			bool flag = levelPredicate.predicates.TrueForAll((Func<bool> predicate) => predicate());
			if (flag)
			{
				levelPredicate.timeAccumulator += Time.deltaTime;
			}
			else
			{
				levelPredicate.timeAccumulator = 0f;
			}
			bool flag2 = levelPredicate.timeAccumulator >= levelPredicate.timeToTrigger && flag;
			if (!levelPredicate.done)
			{
				if (flag2)
				{
					session.send(new LevelPredicateCallPacket
					{
						predicateType = levelPredicate.type,
						isDone = true
					});
					callLevelPredicate(levelPredicate.type, isDone: true);
				}
			}
			else if (!flag2)
			{
				session.send(new LevelPredicateCallPacket
				{
					predicateType = levelPredicate.type,
					isDone = false
				});
				callLevelPredicate(levelPredicate.type, isDone: false);
			}
		}
	}

	private void callLevelPredicate(int type, bool isDone)
	{
		LevelPredicate levelPredicate = levelPredicates.Find((LevelPredicate lp) => lp.type == type);
		if (levelPredicate == null)
		{
			return;
		}
		levelPredicate.done = isDone;
		if (isDone)
		{
			levelPredicate.doneCounter++;
		}
		trackLogicChanges(delegate
		{
			if (isDone)
			{
				levelLogic.onLevelPredicateDone(type, levelPredicate.doneCounter);
			}
			else
			{
				levelLogic.onLevelPredicateUndone(type);
			}
		});
	}

	public bool checkSlotSolution(Slot slot, Item isItem)
	{
		if (slot.currentSlotState == SlotState.Idle)
		{
			return slot.insertedItem == isItem;
		}
		return false;
	}

	private void levelReadyInit()
	{
		if (levelReadyProcessCompleted)
		{
			return;
		}
		levelReadyRequiredPlayers.Clear();
		levelReadyReadyPlayers.Clear();
		foreach (NetPlayerData player in session.players)
		{
			levelReadyRequiredPlayers.Add(player.id);
		}
		levelReadyLog("Init");
		if (session.netMode != NetMode.Client)
		{
			levelReadyHandlePlayerReady(session.localPlayerId);
		}
	}

	private void levelReadyHandlePlayerJoin(NetPlayerId playerId)
	{
		if (!levelReadyProcessCompleted)
		{
			levelReadyRequiredPlayers.Add(playerId);
			levelReadyLog($"Player {playerId} joined during process");
		}
	}

	private void levelReadyHandlePlayerReady(NetPlayerId playerId)
	{
		if (levelReadyProcessCompleted)
		{
			levelReadySync(playerId);
			return;
		}
		levelReadyReadyPlayers.Add(playerId);
		levelReadyLog($"Player {playerId} marked as ready");
		levelReadyCheckIfCompleted();
	}

	private void levelReadyHandlePlayerLeave(NetPlayerId playerId)
	{
		if (!levelReadyProcessCompleted)
		{
			levelReadyRequiredPlayers.Remove(playerId);
			levelReadyLog($"Player {playerId} left during process");
			levelReadyCheckIfCompleted();
		}
	}

	private void levelReadyCheckIfCompleted()
	{
		if (!levelReadyProcessCompleted && !levelReadyRequiredPlayers.Any((NetPlayerId player) => !levelReadyReadyPlayers.Contains(player)))
		{
			levelReadyProcessCompleted = true;
			levelReadyLog("Process completed, level is ready");
			levelReadySync(null);
			startInteractionsOnLevelReady(!isCurrentLevelLoadedFromSave);
		}
	}

	private void levelReadySync(NetPlayerId dropInPlayerId)
	{
		if (session.netMode == NetMode.Host)
		{
			if ((object)dropInPlayerId == null)
			{
				session.send(new LevelSyncReadyPacket
				{
					shouldStartInteractions = !isCurrentLevelLoadedFromSave
				}, allowSendInMessageResponse: true);
			}
			else
			{
				session.sendToSpecificPlayerFromHost(new LevelSyncReadyPacket
				{
					shouldStartInteractions = false
				}, dropInPlayerId, allowSendInMessageResponse: true);
			}
			levelReadyLog("Sync level ready (" + (((object)dropInPlayerId == null) ? "sent to all players" : $"sent to drop-in player {dropInPlayerId}") + ")");
		}
	}

	private void levelReadyLog(string message)
	{
		string text = string.Join(", ", levelReadyRequiredPlayers);
		string text2 = string.Join(", ", levelReadyReadyPlayers);
		UnityEngine.Debug.Log("[Level-Ready] " + message + " | Required: [" + text + "], Ready: [" + text2 + "]");
	}

	private void performLevelResync()
	{
		if (session.netMode == NetMode.Client)
		{
			UnityEngine.Debug.Log("[Level-Sync] Performing level re-sync.");
			PineSceneManager.loadScene(SceneManager.GetActiveScene().name, "Re-syncing Level...", "", null);
		}
		else
		{
			UnityEngine.Debug.LogError("[Level-Sync] Host cannot perform level re-sync.");
		}
	}

	private void initLevelSync()
	{
		if (session.netMode == NetMode.Client)
		{
			session.sendToSpecificPlayerFromClient(new LevelSyncRequestPacket(), session.hostPlayerId);
			UnityEngine.Debug.Log("[Level-Sync] Sent LevelSyncRequestPacket.");
		}
		else
		{
			session.setSynced(session.localPlayerId);
		}
	}

	private void processLevelSyncPacket(Packet packet)
	{
		if (!(packet is LevelSyncRequestPacket packet2))
		{
			if (!(packet is LevelSyncResponsePacket packet3))
			{
				if (!(packet is LevelSyncSceneLoadedPacket packet4))
				{
					if (!(packet is LevelSyncSceneStatePacket packet5))
					{
						if (packet is LevelSyncReadyPacket packet6)
						{
							processLevelSyncReady(packet6);
						}
					}
					else
					{
						processLevelSyncSceneState(packet5);
					}
				}
				else
				{
					processLevelSyncSceneLoaded(packet4);
				}
			}
			else
			{
				processLevelSyncResponse(packet3);
			}
		}
		else
		{
			processLevelSyncRequest(packet2);
		}
	}

	private void processLevelSyncRequest(LevelSyncRequestPacket packet)
	{
		NetPlayerId senderId = packet.senderId;
		if (!session.isPlayerInLobby(senderId))
		{
			UnityEngine.Debug.LogError(string.Format("{0} Received {1} from player (ID: {2}) which is not in lobby.", "[Level-Sync]", "LevelSyncRequestPacket", senderId));
		}
		else if (!isHost())
		{
			UnityEngine.Debug.LogError(string.Format("{0} Client received {1} from {2} (ID: {3})", "[Level-Sync]", "LevelSyncRequestPacket", session.getUsername(senderId), senderId));
		}
		else
		{
			UnityEngine.Debug.Log(string.Format("{0} Received {1} from {2} (ID: {3})", "[Level-Sync]", "LevelSyncRequestPacket", session.getUsername(senderId), senderId));
			session.sendToSpecificPlayerFromHost(new LevelSyncResponsePacket
			{
				levelId = levelIdentifier
			}, senderId, allowSendInMessageResponse: true);
			session.setUnsynced(senderId);
		}
	}

	private void processLevelSyncResponse(LevelSyncResponsePacket packet)
	{
		string text = levelIdentifier;
		string levelId = packet.levelId;
		UnityEngine.Debug.Log("[Level-Sync] Received LevelSyncResponsePacket. Local scene: " + text + " | Host scene: " + levelId);
		if (text == levelId)
		{
			session.sessionId = packet.sessionId;
			session.sendToSpecificPlayerFromClient(new LevelSyncSceneLoadedPacket
			{
				levelId = text
			}, packet.senderId, allowSendInMessageResponse: true);
			session.send(new CharacterCustomizationPacket
			{
				customization = PlayerSave.getCC()
			}, allowSendInMessageResponse: true);
		}
		else if (levelId == "Lobby1")
		{
			quitToMenu(continueSession: true);
		}
		else if (levelIdentifier == "Lobby1")
		{
			loadScene(levelId, shouldLoadLatestSave: false);
		}
		else
		{
			loadScene(levelId, shouldLoadLatestSave: false);
		}
	}

	private void processLevelSyncSceneLoaded(LevelSyncSceneLoadedPacket packet)
	{
		NetPlayerId senderId = packet.senderId;
		if (!session.isPlayerInLobby(senderId))
		{
			UnityEngine.Debug.LogError(string.Format("{0} Received {1} from player (ID: {2}) which is not in lobby.", "[Level-Sync]", "LevelSyncSceneLoadedPacket", senderId));
			return;
		}
		if (!isHost())
		{
			UnityEngine.Debug.LogError(string.Format("{0} Received {1} from {2} (ID: {3})", "[Level-Sync]", "LevelSyncSceneLoadedPacket", session.getUsername(senderId), packet.senderId));
			return;
		}
		UnityEngine.Debug.Log(string.Format("{0} Received {1} from {2} (ID: {3}).", "[Level-Sync]", "LevelSyncSceneLoadedPacket", session.getUsername(packet.senderId), packet.senderId));
		if (levelReadyProcessCompleted)
		{
			spawnPlayerByHost(packet.senderId);
		}
		byte[] levelState = (isSplitscreen ? null : saveLevel(!isLobby()));
		List<int> collectedTokens = PlayerSave.getCollectedTokens(levelIdentifier);
		session.sendToSpecificPlayerFromHost(new LevelSyncSceneStatePacket
		{
			levelState = levelState,
			foundTokens = collectedTokens
		}, packet.senderId, allowSendInMessageResponse: true);
		foreach (NetPlayerData player in session.players)
		{
			if (player.id == packet.senderId)
			{
				continue;
			}
			if (session.isLocalPlayer(player.id))
			{
				session.sendToSpecificPlayerFromHost(new CharacterCustomizationPacket
				{
					customization = PlayerSave.getCC()
				}, senderId, allowSendInMessageResponse: true);
				continue;
			}
			GamePlayerData gamePlayerData = netPlayers.Find((GamePlayerData p) => p.id == player.id);
			if (gamePlayerData == null)
			{
				UnityEngine.Debug.LogError(string.Format("{0} Could not find other client player with ID {1}", "[Level-Sync]", player.id));
			}
			else if (gamePlayerData.characterCustomizationPacket == null)
			{
				UnityEngine.Debug.LogError("[Level-Sync] Found other player " + session.getUsername(player.id) + ", but no character customization packet.");
				CharacterCustomizationPacket packet2 = new CharacterCustomizationPacket
				{
					customization = PlayerSave.getCC(),
					senderId = gamePlayerData.id
				};
				session.sendToSpecificPlayerFromHost(packet2, senderId, allowSendInMessageResponse: true);
			}
			else
			{
				session.sendToSpecificPlayerFromHost(gamePlayerData.characterCustomizationPacket, senderId, allowSendInMessageResponse: true);
			}
		}
		session.setSynced(senderId);
		levelReadyHandlePlayerReady(senderId);
	}

	private void processLevelSyncSceneState(LevelSyncSceneStatePacket packet)
	{
		byte[] levelState = packet.levelState;
		UnityEngine.Debug.Log(string.Format("{0} Received {1} with {2} bytes.", "[Level-Sync]", "LevelSyncSceneStatePacket", (levelState != null) ? levelState.Length : 0));
		syncedFoundTokens = packet.foundTokens;
		loadLevel(packet.levelState);
		session.setSynced(session.localPlayerId);
		if (lobbyMenu != null)
		{
			lobbyMenu.onClientLoadedLevel();
		}
	}

	private void processLevelSyncReady(LevelSyncReadyPacket packet)
	{
		if (!levelReadyProcessCompleted)
		{
			UnityEngine.Debug.Log("[Level-Sync] Received LevelSyncReadyPacket.");
			levelReadyProcessCompleted = true;
			startInteractionsOnLevelReady(packet.shouldStartInteractions);
		}
	}

	public void initLuaLevelLogicScript(string script, HashSet<string> invokableFunctions)
	{
		try
		{
			levelLogicLuaScript.DoString(script);
			levelLogicLuaInvokableFunctions.UnionWith(invokableFunctions);
			foreach (TablePair pair in (levelLogicLuaScript.Globals["_G"] as Table).Pairs)
			{
				if (pair.Key.Type == DataType.String)
				{
					luaDontSaveKeys.Add(pair.Key.String);
				}
			}
			UnityEngine.Debug.Log("Lua don't save keys:\n" + string.Join("\n", luaDontSaveKeys));
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
		}
	}

	private void initLua(List<CustomRoomDataFile> overrideFiles)
	{
		UnityEngine.Debug.Log(string.Format("[{0}] Custom level ID: {1} | {2}: {3}", "initLua", customRoomData?.roomId ?? 0, "overrideFiles", overrideFiles?.Count ?? 0));
		foreach (Type luaType in luaTypes)
		{
			UserData.RegisterType(luaType);
		}
		luaApi = new LuaAPI();
		luaApi.init(this);
		allLuaExecutors = new List<LuaExecutor>(levelContainer.GetComponentsInChildren<LuaExecutor>(includeInactive: true));
		for (int num = allLuaExecutors.Count - 1; num >= 0; num--)
		{
			LuaExecutor luaExecutor = allLuaExecutors[num];
			luaExecutor.game = this;
			if (string.IsNullOrWhiteSpace(luaExecutor.luaCodeLocation))
			{
				LuaAPI.executingScriptName = string.Empty;
				string text = luaExecutor.transform.position.ToString().Colored(Color.gray9);
				string text2 = "Lua".Colored(Color.gray9);
				luaApi.log("Script at position " + text + " has no associated " + text2 + " file.", isError: true);
				allLuaExecutors.RemoveAt(num);
			}
			else
			{
				LuaAPI.executingScriptName = luaExecutor.luaCodeLocation + ".lua";
				UnityEngine.Debug.Log("Loading lua executor: " + luaExecutor.luaCodeLocation);
				string path;
				bool num2 = isLuaPathValid(luaExecutor, out path);
				bool flag = false;
				if (num2)
				{
					Script lua = luaExecutor.lua;
					fillLuaReferences(luaExecutor.luaLinks, lua);
					try
					{
						string text3 = ((overrideFiles != null) ? Encoding.UTF8.GetString(overrideFiles.Find((CustomRoomDataFile x) => x.path == path).data) : File.ReadAllText(path));
						UnityEngine.Debug.Log("[initLua] Lua script:\n" + text3);
						MethodInfo[] methods = typeof(LevelLogic).GetMethods(BindingFlags.Instance | BindingFlags.Public);
						foreach (MethodInfo methodInfo in methods)
						{
							if (methodInfo.IsVirtual && text3.Contains("function " + methodInfo.Name))
							{
								luaExecutor.callFilter.Add(methodInfo.Name);
							}
						}
						lua.DoString(text3);
						foreach (TablePair pair in (lua.Globals["_G"] as Table).Pairs)
						{
							if (pair.Key.Type == DataType.String && !luaDontSaveKeys.Contains(pair.Key.String))
							{
								DataType type = pair.Value.Type;
								if (type == DataType.Boolean || type == DataType.Number || type == DataType.String || type == DataType.Table)
								{
									luaExecutor.initialGlobalVariables.Add(new LuaVariable
									{
										name = pair.Key.String,
										type = pair.Value.Type
									});
								}
							}
						}
					}
					catch (Exception ex)
					{
						UnityEngine.Debug.LogException(ex);
						if (ex is SyntaxErrorException ex2)
						{
							luaApi.log(ex2.DecoratedMessage, isError: true);
						}
						else
						{
							luaApi.log("Script has errors. Cannot be loaded.", isError: true);
						}
						flag = true;
					}
				}
				else
				{
					luaApi.log("Script does not exist. Cannot be loaded.", isError: true);
					flag = true;
				}
				if (flag)
				{
					allLuaExecutors.RemoveAt(num);
				}
			}
		}
		LuaAPI.executingScriptName = "main.lua";
		fillLuaReferences(levelLogicLuaLinks, levelLogicLuaScript);
		bool isLuaPathValid(LuaExecutor luaExecutor2, out string reference)
		{
			reference = "";
			if (overrideFiles != null)
			{
				string potentialpath = luaExecutor2.luaCodeLocation + ".lua";
				if (overrideFiles.Find((CustomRoomDataFile x) => x.path == potentialpath && x.customType == CustomRoomDataFile.CustomType.Lua) != null)
				{
					reference = potentialpath;
					return true;
				}
				return false;
			}
			reference = Path.Combine(isCustomLevel() ? customRoomData.path : UnityEngine.Application.streamingAssetsPath, luaExecutor2.luaCodeLocation);
			reference += ".lua";
			return File.Exists(reference);
		}
	}

