		PropInstance[] array = allPropInstances;
		foreach (PropInstance propInstance in array)
		{
			if (!string.IsNullOrEmpty(propInstance.scriptName))
			{
				bool flag = addNewComponent<ActivatorComponent>(arrays5, luaLinks.linkedActivators);
				if (!flag)
