			}
			bool addNewComponent<T>(Dictionary<string, List<T>> dictionary, List<T> linkedObjects) where T : UnityEngine.Object
			{
				if (!propInstance.TryGetComponent<T>(out var component))
				{
					return false;
				}
				string scriptName = propInstance.scriptName;
				if (!scriptName.Contains("{"))
				{
					lua.Globals[scriptName] = component;
					linkedObjects.Add(component);
					return true;
				}
				int num = scriptName.IndexOf("{", StringComparison.Ordinal) + 1;
				int num2 = scriptName.IndexOf("}", StringComparison.Ordinal);
				if (int.TryParse(scriptName.Substring(num, num2 - num), out var result))
				{
					result--;
					if (result < 0)
					{
						luaApi.log("Object " + scriptName + " has array index 0 or less.", isError: true);
						return true;
					}
					string key = scriptName.Substring(0, num - 1);
					if (!dictionary.ContainsKey(key))
					{
						dictionary[key] = new List<T>();
					}
					List<T> list = dictionary[key];
					if (result >= list.Count)
					{
						int count = list.Count;
						for (int j = 0; j <= result - count; j++)
						{
							list.Add(null);
						}
					}
					list[result] = component;
				}
				linkedObjects.Add(component);
				return true;
			}
		}
		linkAllArrays<ActivatorComponent>(arrays5);
		linkAllArrays<Switch3D>(arrays2);
		linkAllArrays<Trigger>(arrays4);
		linkAllArrays<Slot>(arrays);
		linkAllArrays<Lock>(arrays3);
		linkAllArrays<Slidable>(arrays7);
		linkAllArrays<Roulette>(arrays8);
