		linkAllArrays<Interactive>(arrays19);
		linkAllArrays<Teleport>(arrays21);
		linkAllArrays<EditorPuzzle>(arrays22);
		linkAllArrays<Finish>(arrays23);
		void linkAllArrays<T>(Dictionary<string, List<T>> dictionary)
		{
			foreach (var (key, value) in dictionary)
			{
				lua.Globals[key] = value;
			}
		}
	}

	public void callLevelLogicLuaFunction(string functionName, Func<LuaLinks, bool> hasLinkedComponent, params object[] args)
	{
		LuaAPI.executingScriptName = "main.lua";
		if (levelLogicLuaInvokableFunctions.Contains(functionName))
		{
			callLuaFunction(levelLogicLuaScript, functionName, args);
		}
		foreach (LuaExecutor allLuaExecutor in allLuaExecutors)
		{
			if (hasLinkedComponent(allLuaExecutor.luaLinks) && allLuaExecutor.callFilter.Contains(functionName))
			{
				LuaAPI.executingScriptName = allLuaExecutor.luaCodeLocation + ".lua";
				callLuaFunction(allLuaExecutor.lua, functionName, args);
			}
		}
	}

	public DynValue callLuaFunction(Script lua, string functionName, params object[] args)
	{
		try
		{
			object obj = lua.Globals[functionName];
			if (obj == null)
			{
				UnityEngine.Debug.Log("[" + LuaAPI.executingScriptName + "] No function '" + functionName + "' in Lua script!");
				return DynValue.Nil;
			}
			return lua.Call(obj, args);
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("[" + LuaAPI.executingScriptName + "] Exception in function: " + functionName + "(" + string.Join(", ", args) + ")");
			UnityEngine.Debug.LogException(ex);
			if (ex is InterpreterException ex2)
			{
				luaApi.log(functionName + ": " + ex2.DecoratedMessage, isError: true);
			}
			else
			{
				luaApi.log(functionName + ": " + ex.Message, isError: true);
			}
			return DynValue.Nil;
		}
	}

