	private void initMenu()
	{
		initGameFrame();
		tweenStateContextMenu = TweenState.createContext(mainMenu.gameObject);
		Text buttonMenu_Label = mainMenuButtonsUI.ButtonMenu_Label;
		if (isLobby() || SceneManager.GetActiveScene().name == "SplashScreen")
		{
			buttonMenu_Label.text = "%exitLobby%";
		}
		else if (isSaveSystemEnabledFor(SceneManager.GetActiveScene().name) && isHost())
		{
			buttonMenu_Label.text = "%uiSaveAndExit%";
		}
		else if (!isHost())
		{
			buttonMenu_Label.text = "%exitSession%";
		}
		Localization.translateObject(buttonMenu_Label.transform, forceNewText: true);
		zoomCanvasUI.NormalActions_PinLeft.onClick.AddListener(delegate
		{
			pinItem(0);
		});
		zoomCanvasUI.NormalActions_PinRight.onClick.AddListener(delegate
		{
			pinItem(1);
		});
		foreach (object value in Enum.GetValues(typeof(DarkestPuzzles)))
		{
			isDarkestPuzzle = RoomDatabase.getAllRooms((DarkestPuzzles)value, includeUnbuiltRooms: true).Exists((RoomDatabase.Room room) => SceneManager.GetActiveScene().name == room.name);
			if (isDarkestPuzzle)
			{
				gameHintUI.gameObject.SetActive(value: false);
				break;
			}
		}
		if (isCustomLevel())
		{
			gameHintUI.gameObject.SetActive(value: false);
		}
		bool num = session.netMode != NetMode.Host;
		bool flag = isLobby();
		bool flag2 = Is.Switch && isCustomLevel();
		if (num || flag2 || flag)
		{
			mainMenuButtonsUI.ButtonRestart.gameObject.SetActive(value: false);
		}
		showTranslatedSceneName();
		if (isCustomLevel() && session.gameDifficulty != GameDifficulty.Hard && customRoomData != null && customRoomData.walkthrough != null && customRoomData.walkthrough.Count > 0)
		{
			walkthrough.init(customRoomData.walkthrough);
			mainMenuButtonsUI.ButtonWalkthrough.gameObject.SetActive(value: true);
		}
		else
		{
			mainMenuButtonsUI.ButtonWalkthrough.gameObject.SetActive(value: false);
		}
		initES2HostOptions();
		SteamUGC.StopPlaytimeTrackingForAllItems();
	}

