	private void onButtonClick(Button button)
	{
		if (button == mainMenuButtonsUI.ButtonHelp)
		{
			UnityEngine.Application.OpenURL("https://youtu.be/mDTFxOOYQoI");
		}
		if (button == mainMenuButtonsUI.ButtonResume)
		{
			closeMainMenu();
		}
		PlayerInviteItemUI component;
		if (button == mainMenuButtonsUI.ButtonInvite)
		{
			openNativeInvitation();
		}
		else if (button == mainMenuButtonsUI.ButtonResync)
		{
			performLevelResync();
		}
		else if (button == mainMenuButtonsUI.ButtonOptions)
		{
			openOptions();
		}
		else if (button == mainMenuButtonsUI.ButtonRestart)
		{
			openRestartSceneDialog();
		}
		else if (button == mainMenuButtonsUI.ButtonMenu)
		{
			if (isHost() && !isLobby())
			{
				saveLevel(shouldWriteToDisk: true);
			}
			if (isLobby())
			{
				quitToMenu(continueSession: false);
			}
			else
			{
				quitToMenu(session.netMode != NetMode.Client);
			}
		}
		else if (button.TryGetComponent<PlayerInviteItemUI>(out component))
		{
			inviteFriend(component);
		}
	}

