	private void onChangeLanguage()
	{
		UnityEngine.Debug.Log("Translating scene to: " + PlayerSave.getSettings().language);
		Localization.init(PlayerSave.getSettings().language);
		translateScene();
		Localization.translateCurrentScene();
		if (isVR())
		{
			Localization.translateObject(vr.rig.transform, forceNewText: true);
		}
		showTranslatedSceneName();
		Stopwatch stopwatch = Stopwatch.StartNew();
		int num = 0;
		GameObject[] rootGameObjects = SceneManager.GetActiveScene().GetRootGameObjects();
		for (int i = 0; i < rootGameObjects.Length; i++)
		{
			LayoutGroup[] componentsInChildren = rootGameObjects[i].GetComponentsInChildren<LayoutGroup>();
			for (int j = 0; j < componentsInChildren.Length; j++)
			{
				LayoutRebuilder.ForceRebuildLayoutImmediate(componentsInChildren[j].rectT());
				num++;
			}
		}
		UnityEngine.Debug.Log($"Layout update of {num} layouts took {stopwatch.ElapsedMilliseconds} ms.");
	}

