	private void onButtonInteraction(Button button, EventTriggerType type, PointerEventData data)
	{
		switch (type)
		{
		case EventTriggerType.PointerEnter:
			onButtonPointerEnter(button, handCursor, isRoomEditor: false);
			break;
		case EventTriggerType.PointerExit:
			onButtonPointerExit(button, defaultCursor);
			break;
		case EventTriggerType.PointerDown:
			if (button == gameHintUI.ButtonHint)
			{
				hintButtonMenuDown();
			}
			break;
		case EventTriggerType.PointerUp:
			if (button == gameHintUI.ButtonHint)
			{
				hintButtonMenuUp();
			}
			break;
		}
	}

	public static void onButtonPointerEnter(Button button, Texture2D cursorIcon, bool isRoomEditor)
	{
		Cursor.SetCursor(cursorIcon, handCursorOffset, CursorMode.Auto);
		setHoverStyle(button);
