	public static void onButtonPointerExit(Button button, Texture2D cursorIcon)
	{
		Cursor.SetCursor(cursorIcon, defaultCursorOffset, CursorMode.Auto);
		resetHoverStyle(button);
	}

	public static void resetHoverStyle(Selectable selectable)
	{
		if (selectable != null && selectable.TryGetComponent<EventButton>(out var eventButton))
		{
			if (eventButton.buttonType == EventButtonType.CoverScreen)
			{
				resetFont();
			}
			else if (eventButton.buttonType == EventButtonType.PackSelect && !selectable.GetComponent<Toggle>().isOn)
			{
				resetFont();
			}
		}
		void resetFont()
		{
			Text componentInChildren = selectable.GetComponentInChildren<Text>();
			if (componentInChildren != null)
			{
				Themes.setColorWithoutAlpha(componentInChildren, Menu.getTheme().buttonHoverableColors.unselectedColorText);
				if (eventButton.normalTextFont != null)
				{
					componentInChildren.font = eventButton.normalTextFont;
				}
			}
		}
	}

	public static void setHoverStyle(Selectable selectable)
	{
		if (selectable != null && selectable.TryGetComponent<EventButton>(out var eventButton))
		{
			if (eventButton.buttonType == EventButtonType.CoverScreen)
			{
				setHoverFont();
			}
			else if (eventButton.buttonType == EventButtonType.PackSelect)
			{
				setHoverFont();
			}
		}
		void setHoverFont()
		{
			Text componentInChildren = selectable.GetComponentInChildren<Text>();
			if (!(componentInChildren == null))
			{
				Themes.setColorWithoutAlpha(componentInChildren, Menu.getTheme().buttonHoverableColors.hoverColorText);
				if (eventButton.hoverTextFont != null)
				{
					componentInChildren.font = eventButton.hoverTextFont;
				}
			}
		}
	}

	private void updateMenu()
	{
		TweenState[] tweenStates = tweenStateContextMenu.tweenStates;
		for (int i = 0; i < tweenStates.Length; i++)
		{
			tweenStates[i].update(Time.deltaTime, tweenEventsMenu);
			tweenEventsMenu.Clear();
		}
		menuTween.processTweens(Time.deltaTime);
		updateGameFrame();
		updateChat();
		updateFriends();
		walkthrough.update();
		runValidation();
	}

	private void runValidation()
	{
		foreach (ValidateInfo item in objectsToValidate)
		{
			item.objectToControl.SetActive(item.shouldObjectBeVisible());
		}
	}

