	private void updateFriends()
	{
		if (Friends.didListChange)
		{
			List<PlayerInviteItemUI> list = (List<PlayerInviteItemUI>)menuHostOptions.data;
			if (list != null)
			{
				foreach (PlayerInviteItemUI item in list)
				{
					UnityEngine.Object.Destroy(item.gameObject);
				}
			}
			List<PlayerInviteItemUI> list2 = new List<PlayerInviteItemUI>();
			foreach (Friends.FriendInfo sortedFriend in Friends.get().getSortedFriends())
			{
				PlayerInviteItemUI panel_ScrollView_Viewport_Content_PlayerInviteItem = menuHostOptions.Panel_ScrollView_Viewport_Content_PlayerInviteItem;
				PlayerInviteItemUI playerInviteItemUI = UnityEngine.Object.Instantiate(panel_ScrollView_Viewport_Content_PlayerInviteItem, panel_ScrollView_Viewport_Content_PlayerInviteItem.transform.parent);
				playerInviteItemUI.gameObject.SetActive(value: true);
				string text = sortedFriend.name;
				if (text.Length > 13)
				{
					text = text.Substring(0, 10) + "...";
				}
				playerInviteItemUI.Name.text = text;
				bool flag = false;
				flag = sortedFriend.status != EPersonaState.k_EPersonaStateOffline;
				playerInviteItemUI.offline.gameObject.SetActive(!flag);
				playerInviteItemUI.inGame.gameObject.SetActive(flag && sortedFriend.gamePlayed == Friends.GamePlayed.InGame);
				playerInviteItemUI.InES2.gameObject.SetActive(flag && sortedFriend.gamePlayed == Friends.GamePlayed.EscapeSimulator2);
				playerInviteItemUI.online.gameObject.SetActive(flag && sortedFriend.gamePlayed == Friends.GamePlayed.NotInGame);
				playerInviteItemUI.Avatar.texture = sortedFriend.avatar;
				playerInviteItemUI.root.GetComponent<CanvasGroup>().alpha = (flag ? 1f : 0.2f);
				playerInviteItemUI.data = sortedFriend;
				list2.Add(playerInviteItemUI);
			}
			menuHostOptions.data = list2;
		}
		if (menuHostOptions.gameObject.activeInHierarchy)
		{
			List<PlayerInviteItemUI> list3 = (List<PlayerInviteItemUI>)menuHostOptions.data;
			if (list3 == null || list3.Count <= 0)
			{
				return;
			}
			if (Controller.isActive())
			{
				if (Friends.didListChange)
				{
					Controller.setSelectingGroup(null);
				}
				Controller.setSelectingGroup(menuHostOptions.Panel_ScrollView_Viewport_Content_PlayerInviteItem.transform.parent, list3[0].root);
				GameObject selected = EventSystem.current.currentSelectedGameObject;
				int num = list3.FindIndex((PlayerInviteItemUI x) => x.root.gameObject == selected);
				int num2 = Mathf.CeilToInt((float)list3.Count / 3f);
				int num3 = num / 3;
				float target = 1f - (float)num3 / ((float)num2 - 1f);
				menuHostOptions.Panel_ScrollView.verticalNormalizedPosition = Mathf.MoveTowards(menuHostOptions.Panel_ScrollView.normalizedPosition.y, target, Time.deltaTime);
			}
			{
				foreach (PlayerInviteItemUI item2 in list3)
				{
					item2.ControllerSelected.gameObject.SetActive(Controller.isActive() && EventSystem.current.currentSelectedGameObject == item2.root.gameObject);
				}
				return;
			}
		}
		if (lobbyMenu == null)
		{
			Controller.setSelectingGroup(null);
		}
	}

