	private string getTitleCase(string input)
	{
		StringBuilder stringBuilder = new StringBuilder(24);
		stringBuilder.Append(input[0]);
		stringBuilder.Append(input.Substring(1).ToLower());
		return stringBuilder.ToString();
	}

	public void onFrameClick(string id)
	{
		switch (id)
		{
		case "back":
			if (currentlySelectedJigsaw != null)
			{
				clearJigsawSelection(currentlySelectedJigsaw);
			}
			else if (walkthrough.isActive())
			{
				closeWalkthrough();
			}
			else if (menuOptions.gameObject.activeInHierarchy)
			{
				if (lobbyMenu == null || !lobbyMenu.inCoverScreen)
				{
					if (isRebindingEnterKeyOpen)
					{
						closeRebindingEnterKey();
						return;
					}
					closeOptions();
					openMainMenu();
				}
				else
				{
					lobbyMenu.onBack();
				}
			}
			else if (menuHostOptions.gameObject.activeInHierarchy)
			{
				closeHostOptions();
			}
			else if (gameState.current == GameState.CustomMode)
			{
				handleCustomModeLeave(localPlayerData.customMode);
			}
			else
			{
				if (gameState.current != GameState.Zoom)
				{
					return;
				}
				if (topZoomContextSafe(out var context))
				{
					if (dragData != null)
					{
						stopZoomDrag();
					}
					else if (lobbyZoomablesWithFrame.Find((Zoomable x) => x.gameObject == context.selected) == null)
					{
						UnityEngine.Debug.Log("leave zoom");
						handleZoomLeave();
					}
				}
			}
			return;
		case "drop":
			dropFromInventory();
			return;
		case "pinLeft":
			pinItem(0);
			return;
		case "pinRight":
			pinItem(1);
			return;
		case "take":
			addZoomedItemToInventory();
			return;
		}
		if (id.Contains("finish"))
		{
			onFinishLevelButtonClick(id);
			return;
		}
		switch (id)
		{
		case "inviteFriend":
		{
			if (EventSystem.current.currentSelectedGameObject.TryGetComponent<Button>(out var component) && component.TryGetComponent<PlayerInviteItemUI>(out var component2))
			{
				inviteFriend(component2);
			}
			break;
		}
		case "copyCode":
			copyCode();
			break;
		case "openSteamInvite":
			openNativeInvitation();
			break;
		case "recenter":
			zoomRecenter();
			break;
		}
	}

