	private bool isFinalLevel()
	{
		if (isDemoLobby())
		{
			return true;
		}
		if (isAnyPlayerOnOculus())
		{
			return true;
		}
		string text = levelIdentifier;
		int num;
		switch (text)
		{
		default:
			num = ((!(text == "Test1")) ? 1 : 0);
			break;
		case "Tutorial1":
		case "Dracula4":
		case "Space4":
		case "Pirate4":
		case "Zombie4":
			num = 0;
			break;
		}
		return num == 0;
	}

	public void popup(RectTransform position, string message, float duration, Vector2 offset, float addHeight = 0f, bool inverted = false, Action onKill = null)
	{
		if (activePopups.ContainsKey(position.gameObject))
		{
			killPopup(activePopups[position.gameObject]);
			return;
		}
		GameObject activePopup = UnityEngine.Object.Instantiate(popupPrefab, position.transform);
		RectTransform component = activePopup.GetComponent<RectTransform>();
		component.anchoredPosition = offset;
		component.sizeDelta = new Vector2(component.sizeDelta.x, component.sizeDelta.y + addHeight);
		Text componentInChildren = activePopup.GetComponentInChildren<Text>();
		componentInChildren.text = Localization.translate(message);
		if (inverted)
		{
			componentInChildren.gameObject.transform.Rotate(0f, 180f, 180f);
			activePopup.gameObject.transform.Rotate(0f, 180f, 180f);
		}
		PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
		GameObject obj = activePopup;
		Vector3? scaleFrom = Vector3.zero;
		Vector3? scaleTo = Vector3.one;
		float? alphaFrom = 0f;
		float? alphaTo = 1f;
		gameplayTween.tween(obj, 0.25f, 0f, deactivate: false, activate: true, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, scaleFrom, scaleTo, alphaTo, alphaFrom, null, null, null, null, Interpolation.SmootherStep);
		activePopup.GetComponent<Button>().onClick.AddListener(delegate
		{
			killPopup(activePopup);
		});
		getGameplayTween().animate(position.gameObject, delegate(float t)
		{
			bool num = t > duration;
			if (num)
			{
				killPopup(activePopup);
				if (onKill != null)
				{
					onKill();
				}
			}
			return num;
		});
		activePopups[position.gameObject] = activePopup;
		PineFmod.playOneShotSound("event:/SFX/GENERAL/popupHint");
	}

	public void killPopup(GameObject popup)
	{
		if (popup == null)
		{
			return;
		}
		destroyGameplayTweens(popup, performEvents: false, performFinalUpdate: false);
		PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
		Vector3? scaleTo = Vector3.zero;
		float? alphaTo = 0f;
		gameplayTween.tween(popup, 0.25f, 0f, deactivate: false, activate: false, destroy: true, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo, alphaTo);
		foreach (KeyValuePair<GameObject, GameObject> activePopup in activePopups)
		{
			if (activePopup.Value == popup)
			{
				activePopups.Remove(activePopup.Key);
				break;
			}
		}
	}

	private bool shouldShowItemHints()
	{
		if (!PlayerSave.getSettings().isHidingItemHints)
		{
			return session.gameDifficulty == GameDifficulty.Normal;
		}
		return false;
	}

	private void setupItemUI(ItemUI uiItem, GameObject go, bool canBeStreamlined)
	{
		if (isCustomLevel() && customRoomData.hideItemNameplates)
		{
			return;
		}
		Interactive interactive = go?.GetComponent<Interactive>();
		bool flag = !string.IsNullOrEmpty(interactive?.displayName);
		if (Is.Editor)
		{
			flag = (debugShowNameLabel ? flag : debugShowNameLabel);
		}
		ItemUI ui = uiItem;
		ui.panel.alpha = (flag ? 1 : 0);
		if (flag)
		{
			Item item = go?.GetComponent<Item>();
			if (item != null && shouldShowItemHints())
			{
				bool flag2 = item.toolType != ItemTool.None;
				ui.buttonTool.gameObject.SetActive(flag2);
				ui.buttonKey.gameObject.SetActive(item.itemType == ItemType.Key && !flag2);
				ui.buttonHint.gameObject.SetActive(item.itemType == ItemType.Clue && !flag2);
				ui.buttonContainer.gameObject.SetActive(item.itemType == ItemType.Container && !flag2);
				ui.buttonTrashcan.gameObject.SetActive(value: false);
			}
			else
			{
				ui.buttonTool.gameObject.SetActive(value: false);
				ui.buttonKey.gameObject.SetActive(value: false);
				ui.buttonHint.gameObject.SetActive(value: false);
				ui.buttonContainer.gameObject.SetActive(value: false);
				ui.buttonTrashcan.gameObject.SetActive(value: false);
			}
			ui.nameLbl.text = Localization.translate(interactive.displayName);
			if (!canBeStreamlined)
			{
				ui.buttonTool.onClick.RemoveAllListeners();
				ui.buttonTool.onClick.AddListener(delegate
				{
					popup(ui.buttonTool.GetComponent<RectTransform>(), "%iconToolDescription%", 10f, ui.offsetPosition, ui.addHeight, ui.shouldInvertPopup);
				});
				ui.buttonKey.onClick.RemoveAllListeners();
				ui.buttonKey.onClick.AddListener(delegate
				{
					popup(ui.buttonKey.GetComponent<RectTransform>(), "%iconKeyDescription%", 10f, ui.offsetPosition, ui.addHeight, ui.shouldInvertPopup);
				});
				ui.buttonHint.onClick.RemoveAllListeners();
				ui.buttonHint.onClick.AddListener(delegate
				{
					popup(ui.buttonHint.GetComponent<RectTransform>(), "%iconHintDescription%", 10f, ui.offsetPosition, ui.addHeight, ui.shouldInvertPopup);
				});
				ui.buttonContainer.onClick.RemoveAllListeners();
				ui.buttonContainer.onClick.AddListener(delegate
				{
					popup(ui.buttonContainer.GetComponent<RectTransform>(), "%iconContainerDescription%", 10f, ui.offsetPosition, ui.addHeight, ui.shouldInvertPopup);
				});
				ui.buttonTrashcan.onClick.RemoveAllListeners();
				ui.buttonTrashcan.onClick.AddListener(delegate
				{
					popup(ui.buttonTrashcan.GetComponent<RectTransform>(), "%iconTrashcanDescription%", 10f, ui.offsetPosition, ui.addHeight, ui.shouldInvertPopup);
				});
			}
		}
		killAllPopupsForItemUI(ui);
	}

	public void fillRendererLists(Renderer[] renderers, List<RendererCommandParams> renderersOpaque, List<RendererCommandParams> renderersTransparent)
	{
		renderersOpaque.Clear();
		renderersTransparent.Clear();
		foreach (Renderer renderer in renderers)
		{
			if (!(renderer != null) || !renderer.enabled)
			{
				continue;
			}
			for (int j = 0; j < renderer.sharedMaterials.Length; j++)
			{
				Material material = renderer.sharedMaterials[j];
				if (material != null)
				{
					bool flag = material.shader.name == "Pine Studio/Item In UI Transparent";
					bool flag2 = material.shader.name == "Pine Studio/Item In UI";
					if (flag || flag2)
					{
						(flag ? renderersTransparent : renderersOpaque).Add(new RendererCommandParams
						{
							renderer = renderer,
							material = material,
							index = j
						});
					}
				}
			}
		}
	}

	private void killAllPopupsForItemUI(ItemUI ui)
