	private void initGameFrame()
	{
		frame.setup(gameInputDispatcher, onFrameButtonDown, onFrameButtonUp, onFrameClick);
	}

	private void updateGameFrame()
	{
		frame.interactable = dragData == null;
		frame.gameObject.SetActive(this.gameFrameSourceData.Count > 0 && !debugCanvasesTurnedOff);
		if (this.gameFrameSourceData.Count == 0)
		{
			lastFrameUsedFrameSourceType = GameFrameSourceType.None;
			return;
		}
		List<GameFrameSourceData> list = this.gameFrameSourceData;
		GameFrameSourceData gameFrameSourceData = list[list.Count - 1];
		if (gameFrameSourceData.type != lastFrameUsedFrameSourceType)
		{
			frame.visualController.removeAll();
			frame.addOrUpdateControl(gameFrameSourceData.controls);
			lastFrameUsedFrameSourceType = gameFrameSourceData.type;
		}
	}

	private void addGameFrameSource(GameFrameSourceType type, List<VisualControl> controls)
	{
		GameFrameSourceData gameFrameSourceData = this.gameFrameSourceData.Find((GameFrameSourceData x) => x.type == type);
		if (gameFrameSourceData != null)
		{
			this.gameFrameSourceData.Remove(gameFrameSourceData);
			if (lastFrameUsedFrameSourceType == type)
			{
				lastFrameUsedFrameSourceType = GameFrameSourceType.None;
			}
		}
		GameFrameSourceData item = new GameFrameSourceData(type, controls);
		this.gameFrameSourceData.Add(item);
	}

	private void removeGameFrameSource(GameFrameSourceType type)
	{
		GameFrameSourceData gameFrameSourceData = this.gameFrameSourceData.Find((GameFrameSourceData x) => x.type == type);
		if (gameFrameSourceData != null)
		{
			this.gameFrameSourceData.Remove(gameFrameSourceData);
		}
	}

	private void removeVisualControlFromFrame(string id)
	{
		frame.visualController.removeControl(id);
	}

	private void initNet()
	{
		chatBlacklist = new List<string>(chatBlacklistFile.text.Split(new string[1] { "\r\n" }, StringSplitOptions.None));
		UnityEngine.Debug.Log("Player count " + session.players.Count);
		if (isTestingPlaymodeInEditor)
		{
			netLoadingCondition = LoadingCanvas.get().enqueueEndCondition("", "");
		}
		else
		{
			netLoadingCondition = LoadingCanvas.get().enqueueEndCondition(Localization.lookupInDictionary("waitingOtherPlayers"), LoadingCanvas.get().getTopEndCondition().title);
		}
		if (session.players.Count == 1)
		{
			netLoadingCondition.done = true;
		}
		Interactive[] array = allInteractives;
		foreach (Interactive interactive in array)
		{
			setAuthority(interactive.gameObject, session.hostPlayerId);
		}
		session.game = this;
		session.unlockLobby();
	}

	public void lateUpdateNet()
	{
		if (!levelReadyProcessCompleted)
		{
			return;
		}
		foreach (GamePlayerData netPlayer in netPlayers)
		{
			if (netPlayer == null || netPlayer.selectedCharacter == null)
			{
				continue;
			}
			Vector3 eulerAngles = netPlayer.lastTransformPose.rotation.eulerAngles;
			if (eulerAngles.x > 180f)
			{
				eulerAngles.x -= 360f;
			}
			eulerAngles.x = UnityUtils.map(-90f, 90f, -30f, 50f, eulerAngles.x) + 10f;
			eulerAngles.y = 0f;
			eulerAngles.z = 0f;
			netPlayer.selectedCharacter.neck.transform.localRotation = Quaternion.Euler(eulerAngles);
			if (netPlayer.isPlayingInVR)
			{
				if (netPlayer.playerCanvas != null && netPlayer.selectedMesh.vrHead != null)
				{
					netPlayer.playerCanvas.transform.position = netPlayer.selectedMesh.vrHead.transform.position + Vector3.up * 0.35f;
				}
				if (netPlayer.leftHandObject != null && netPlayer.selectedMesh.vrHandLeft != null)
				{
					netPlayer.leftHandObject.transform.position = netPlayer.selectedMesh.vrHandLeft.transform.position + netPlayer.leftHandObjectPos;
					netPlayer.leftHandObject.transform.rotation = netPlayer.selectedMesh.vrHandLeft.transform.rotation * netPlayer.leftHandObjectRot;
				}
				if (netPlayer.rightHandObject != null && netPlayer.selectedMesh.vrHandRight != null)
				{
					netPlayer.rightHandObject.transform.position = netPlayer.selectedMesh.vrHandRight.transform.position + netPlayer.rightHandObjectPos;
					netPlayer.rightHandObject.transform.rotation = netPlayer.selectedMesh.vrHandRight.transform.rotation * netPlayer.rightHandObjectRot;
				}
			}
			if (isVR())
			{
				netPlayer.playerCanvas.transform.rotation = Quaternion.LookRotation(netPlayer.playerCanvas.transform.position - vr.rig.headCamera.transform.position, Vector3.up);
			}
			else
			{
				netPlayer.playerCanvas.transform.rotation = Quaternion.LookRotation(netPlayer.playerCanvas.transform.position - playerCamera.transform.position, playerCamera.transform.rotation * Vector3.up);
			}
		}
	}

	private void updateNet()
	{
		if (isSplitscreen)
		{
			ScreenSafeAreaScaler[] componentsInChildren = base.gameObject.GetComponentsInChildren<ScreenSafeAreaScaler>(includeInactive: true);
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				RectTransform component = componentsInChildren[i].GetComponent<RectTransform>();
				component.pivot = Vector2.one * 0.5f;
				component.anchorMin = Vector2.zero;
				component.anchorMax = Vector2.one;
				component.offsetMin = Vector2.zero;
				component.offsetMax = Vector2.zero;
			}
		}
		updateReconnecting();
		for (int num = netPlayers.Count - 1; num >= 0; num--)
		{
			GamePlayerData gamePlayerData = netPlayers[num];
			if (gamePlayerData == null)
			{
				UnityEngine.Debug.LogError($"Could not find player data for (disconnected) player with ID '{gamePlayerData.id}'. Skipping...");
				netPlayers.Remove(gamePlayerData);
			}
		}
		bool button = Controller.getButton(ControllerButtonActionType.GamePushToTalk, ControllerButtonActionType.UIPushToTalk);
		bool flag = isVR() && vrPushToTalkHoldTime >= 0.3f;
		bool canRecordVoice = menuOptions.getActionKey(KeyBindingAction.PushToTalk) || button || flag || PlayerSave.getSettings().voiceChatAlwaysOn;
		session.update(canRecordVoice);
		if (!levelReadyProcessCompleted)
		{
			return;
		}
		if (!netLoadingCondition.done)
		{
			bool flag2 = true;
			foreach (GamePlayerData netPlayer in netPlayers)
			{
				if (!netPlayer.setFirstPosition)
				{
					flag2 = false;
					break;
				}
			}
			if (flag2)
			{
				netLoadingCondition.done = true;
			}
		}
		keepAliveSendCooldown -= Time.deltaTime;
		if (keepAliveSendCooldown <= 0f)
		{
			session.send(new KeepAlivePacket());
			keepAliveSendCooldown = 1f;
		}
		if (session.netMode == NetMode.Host)
		{
			timeLastSentSyncTimers -= Time.deltaTime;
			if (timeLastSentSyncTimers <= 0f)
			{
				session.send(new SyncTimerTimePacket
				{
					timerTime = timerCurrentTime
				});
				timeLastSentSyncTimers = 0.5f;
			}
		}
		foreach (GamePlayerData netPlayer2 in netPlayers)
		{
			if (netPlayer2.isInZoom && netPlayer2.sharedZoomBubble.activeInHierarchy)
			{
				Vector3 zero = Vector3.zero;
				CharacterBuild selectedCharacter = netPlayer2.selectedCharacter;
				GameObject[] fingers = selectedCharacter.fingers;
				foreach (GameObject gameObject in fingers)
				{
					zero += gameObject.transform.position;
				}
				zero /= (float)selectedCharacter.fingers.Length;
				netPlayer2.sharedZoomBubble.transform.position = zero;
				netPlayer2.sharedZoomBubble.transform.Rotate(0f, Time.deltaTime * 50f, 0f);
			}
			if (netPlayer2.inHandItemBubble != null)
			{
				AnimatorClipInfo[] currentAnimatorClipInfo = netPlayer2.animator.GetCurrentAnimatorClipInfo(1);
				if (netPlayer2.animator.IsInTransition(1) || currentAnimatorClipInfo.Length == 0 || currentAnimatorClipInfo[0].clip.name.ToLower() != "hold")
				{
					netPlayer2.inHandItemBubble.transform.localScale = Vector3.zero;
				}
				else
				{
					netPlayer2.inHandItemBubble.transform.localScale = Vector3.MoveTowards(netPlayer2.inHandItemBubble.transform.localScale, netPlayer2.initialHandItemBubbleScale, Time.deltaTime * 5f);
					Vector3 fingerAveragePosition = getFingerAveragePosition(netPlayer2);
					netPlayer2.inHandItemBubble.transform.position = fingerAveragePosition;
					updateBubbleItemPosition(netPlayer2.inHandItemBubble, netPlayer2.inHandItemBubble.transform.GetChild(0).gameObject, netPlayer2.inHandItem.gameObject);
				}
			}
			if (netPlayer2.playerCanvas != null)
			{
				netPlayer2.playerCanvas.enabled = !inZoomMode();
			}
			netPlayer2.zoomCursor.gameObject.SetActive(isInTopZoom(netPlayer2.zoomItem) || isInFinishLevelScreen);
			animatePlayer(netPlayer2);
			float alpha = netPlayer2.offScreenPingIndicator.alpha;
			if (netPlayer2.offScreenPingIndicator != null)
			{
				bool flag3 = true;
				if (netPlayer2.animateOffScreenIndicator)
				{
					netPlayer2.offScreenIndicatorTimer += Time.deltaTime;
					if (netPlayer2.offScreenIndicatorTimer >= 1f)
					{
						netPlayer2.animateOffScreenIndicator = false;
					}
					Vector3 vector = playerCamera.WorldToViewportPoint(netPlayer2.lastPingLocation);
					if (vector.x > 0f && vector.x < 1f && vector.y > 0f && vector.y < 1f && vector.z > 0f)
					{
						flag3 = false;
					}
					else
					{
						float num2 = Vector3.Dot(playerCamera.transform.right, netPlayer2.lastPingLocation - playerCamera.transform.position);
						float num3 = Vector3.Dot(playerCamera.transform.up, netPlayer2.lastPingLocation - playerCamera.transform.position);
						if (Mathf.Abs(num3) > Mathf.Abs(num2))
						{
							float y = 0.1f;
							if (num3 > 0f)
							{
								y = 0.85f;
							}
							vector = ((!(vector.z > 0f)) ? new Vector3(1f - Mathf.Clamp(vector.x, 0.03f, 0.97f), y, vector.z) : new Vector3(Mathf.Clamp(vector.x, 0.03f, 0.97f), y, vector.z));
						}
						else
						{
							float x = 0.03f;
							if (num2 > 0f)
							{
								x = 0.97f;
							}
							vector = ((!(vector.z > 0f)) ? new Vector3(x, 1f - Mathf.Clamp(vector.y, 0.1f, 0.85f), vector.z) : new Vector3(x, Mathf.Clamp(vector.y, 0.1f, 0.85f), vector.z));
						}
						RectTransform rectTransform = roomCanvasUI.rectT();
						Vector2 anchoredPosition = new Vector2(vector.x * rectTransform.sizeDelta.x - rectTransform.sizeDelta.x * 0.5f, vector.y * rectTransform.sizeDelta.y - rectTransform.sizeDelta.y * 0.5f);
						netPlayer2.offScreenPingIndicator.GetComponent<RectTransform>().anchoredPosition = anchoredPosition;
					}
				}
				else
				{
					flag3 = false;
				}
				netPlayer2.offScreenPingIndicator.alpha = Mathf.Lerp(alpha, flag3 ? 1 : 0, Time.deltaTime * 4f);
			}
			if (isProximityChatUsed())
			{
				float num4 = Vector3.Distance(playerLocation, netPlayer2.lastTransformPose.position);
				VECTOR pos = (netPlayer2.lastTransformPose.position * 2f * num4).ToFMODVector();
				VECTOR vel = default(VECTOR);
				netPlayer2.voice.set3DAttributes(ref pos, ref vel);
				Vector3 vector2 = netPlayer2.lastTransformPose.rotation * Vector3.forward;
				VECTOR orientation = new VECTOR
				{
					x = vector2.x,
					y = vector2.y,
					z = vector2.z
				};
				netPlayer2.voice.set3DConeOrientation(ref orientation);
			}
		}
		updateVoiceChatIndicators();
		bool num5 = Vector3.Distance(lastSentPose.position, playerLocation) > 0.1f;
		Quaternion quaternion = Quaternion.Euler(currentRotation.y, currentRotation.x, 0f);
		bool flag4 = Quaternion.Angle(lastSentPose.rotation, quaternion) > 2f;
		bool flag5 = heightSlider.value == 0 || (isVR() && crouchingInVR);
		bool flag6 = lastSentPlayerCrouch != flag5 || lastSentPlayerClimb != isClimbingLadder() || lastSentPlayerClimbDir != ladderDirection;
		bool flag7 = Time.time - lastSentPlayerPoseTimestamp > 2f;
		bool flag8 = !UnityUtils.closeEnough(lastSentTurning, isTurning, 5f) || (lastSentTurning != 0f && isTurning == 0f);
		if (num5 || flag4 || flag6 || flag7 || flag8)
		{
			lastSentPose.position = playerLocation;
			lastSentPose.rotation = quaternion;
			lastSentPlayerCrouch = flag5;
			lastSentPlayerClimb = isClimbingLadder();
			lastSentPlayerClimbDir = ladderDirection;
			lastSentPlayerPoseTimestamp = Time.time;
			lastSentTurning = isTurning;
			NetPlayerData player = session.getPlayer();
			if (player != null && player.isSynced)
			{
				session.send(new PlayerPosePacket
				{
					position = lastSentPose.position,
					rotation = lastSentPose.rotation,
					currentRotation = currentRotation,
					isCrouching = flag5,
					isTeleporting = sendTeleportPose,
					isClimbing = isClimbingLadder(),
					isRunning = localPlayerData.isRunning,
					turning = isTurning,
					climbDirection = (sbyte)ladderDirection
				});
				if (syncPlayerRays)
				{
					session.send(new PlayerRayPacket
					{
						rayPosition = localPlayerData.playerCameraRay.origin,
						rayDirection = localPlayerData.playerCameraRay.direction
					});
				}
			}
			sendTeleportPose = false;
		}
		if (isSplitscreen)
		{
			if (Input.GetKeyDown(KeyCode.R))
			{
				hasControl = !hasControl;
			}
			splitScreenCanvas.gameObject.SetActive(hasControl);
		}
		int width = Screen.width;
		int height = Screen.height;
		Vector2 vector3 = getMousePosition() - new Vector3((float)width / 2f, (float)height / 2f, 0f);
		if ((gameState.current == GameState.Zoom || isInFinishLevelScreen) && !UnityUtils.closeEnough(lastSentNetCursorPosition, vector3, 0.001f))
		{
			session.send(new ZoomCursorPacket
			{
				screenPositionFromCenter = vector3,
				screenHeight = height
			});
			lastSentNetCursorPosition = vector3;
		}
		for (int num6 = localNetworkedImposters.Count - 1; num6 >= 0; num6--)
		{
			LocalNetworkedImposter localNetworkedImposter = localNetworkedImposters[num6];
			if (!localNetworkedImposter.sentInit)
			{
				session.send(new ReplicateWithImpostorPacket
				{
					originalObject = localNetworkedImposter.original,
					replicateType = ReplicateWithImpostorType.Init,
					impostorPosition = localNetworkedImposter.impostor.transform.position,
					impostorRotation = localNetworkedImposter.impostor.transform.rotation
				});
				localNetworkedImposter.sentInit = true;
			}
			else if (localNetworkedImposter.impostor != null)
			{
				Vector3 position = localNetworkedImposter.impostor.transform.position;
				Quaternion rotation = localNetworkedImposter.impostor.transform.rotation;
				bool num7 = Vector3.Distance(localNetworkedImposter.lastSentPosition, position) > 0.01f;
				bool flag9 = Quaternion.Angle(localNetworkedImposter.lastSentRotation, rotation) > 1f;
				if (num7 || flag9)
				{
					session.send(new ReplicateWithImpostorPacket
					{
						originalObject = localNetworkedImposter.original,
						replicateType = ReplicateWithImpostorType.Update,
						impostorPosition = position,
						impostorRotation = rotation
					});
					localNetworkedImposter.lastSentPosition = position;
					localNetworkedImposter.lastSentRotation = rotation;
				}
			}
			else
			{
				session.send(new ReplicateWithImpostorPacket
				{
					originalObject = localNetworkedImposter.original,
					replicateType = ReplicateWithImpostorType.Destroy
				});
				localNetworkedImposters.Remove(localNetworkedImposter);
			}
		}
	}

	private Vector3 getFingerAveragePosition(GamePlayerData player)
	{
		CharacterBuild selectedCharacter = player.selectedCharacter;
		Vector3 vector = Vector3.up / 2f;
		GameObject[] pickupHandFingers = selectedCharacter.pickupHandFingers;
		foreach (GameObject gameObject in pickupHandFingers)
		{
			vector += gameObject.transform.position;
		}
		return vector / selectedCharacter.pickupHandFingers.Length;
	}

	private bool isProximityChatUsed()
	{
		if (!isSplitscreen)
		{
			if (!isCustomLevel() || !customRoomData.useProximityChat)
			{
				if (!isCustomLevel())
				{
					return useProximityVoiceChat;
				}
				return false;
			}
			return true;
		}
		return false;
	}

	private void updateVoiceChatIndicators()
	{
		roomCanvasUI.VoiceChatCanvas.gameObject.SetActive(showVoiceChatIndicators && !isSplitscreen && PlayerSave.getSettings().voiceChatEnabled && PlayerSave.getSettings().showVoiceChatIndicators && !storyMenu.activeSelf);
		if (isSplitscreen)
		{
			return;
		}
		foreach (NetPlayerData player in session.players)
		{
			NetPlayerId playerId = player.id;
			if (!idToVoiceChatPlayerUI.TryGetValue(playerId, out var value))
			{
				continue;
			}
			if (session.isLocalPlayer(playerId))
			{
				bool flag = Time.time - session.lastLocalPlayerSpeakTime < 0.1f;
				value.canvasGroup.alpha = (flag ? 1f : 0.5f);
				value.isSpeakingIndicator.enabled = flag;
				continue;
			}
			int num = session.players.FindIndex((NetPlayerData v) => v.id == playerId);
			bool flag2 = ((session.lobbyType != LobbyType.SteamPine) ? (num != -1 && session.players[num].photonSpeaker != null && session.players[num].photonSpeaker.IsPlaying) : (num != -1 && session.players[num].steamSpeaker != null && session.players[num].steamSpeaker.IsPlaying));
			value.canvasGroup.alpha = (flag2 ? 1f : 0.5f);
			value.isSpeakingIndicator.enabled = flag2;
		}
	}

	private void animatePlayer(GamePlayerData player)
	{
		if (!player.hasCharacterInited)
		{
			return;
		}
		Transform parent = player.selectedCharacter.transform.parent;
		Vector3 localPosition = parent.localPosition;
		Vector3 position = player.lastTransformPose.position;
		if (session.connectionMode == ConnectionMode.Splitscreen && session.localPlayerId == Net.SPLITSCREEN_CLIENT_ID)
		{
			position.z += getSplitscreenPositionOffset();
		}
		player.selectedCharacter.lookOffset = Mathf.MoveTowards(player.selectedCharacter.lookOffset, UnityUtils.map(-90f, 90f, 0.5f, -0.5f, player.currentRotation.y) + 0.1f, Time.deltaTime * 5f);
		if (player.characterPoseContext.poseState == CharacterPoseState.None)
		{
			Quaternion to = Quaternion.Euler(0f, player.lastTransformPose.rotation.eulerAngles.y, 0f);
			if (player.ladderData != null && player.isClimbing)
			{
				to = player.ladderData.ladder.upEmpty.rotation;
				if (player.ladderData.ladder.invertRotationForCoopAnimation)
				{
					to *= Quaternion.Euler(0f, 180f, 0f);
				}
			}
			parent.rotation = Quaternion.RotateTowards(player.selectedCharacter.transform.rotation, to, Time.deltaTime * 360f);
		}
		Vector3 vector = Vector3.zero;
		if (parent.localPosition != position)
		{
			UnityEngine.Debug.DrawLine(position, position + Vector3.up, Color.red);
			Vector3 direction = position - localPosition;
			direction.y = 0f;
			vector = parent.InverseTransformDirection(direction).normalized;
		}
		if (player.playerModelVisibility == GamePlayerData.PlayerModelVisibility.InitialPlayerPosePacketReceived)
		{
			player.playerObject.SetActive(value: true);
			player.playerModelVisibility = GamePlayerData.PlayerModelVisibility.PlayerModelVisible;
		}
		if (LoadingCanvas.get().isActive())
		{
			parent.localPosition = position;
			player.setFirstPosition = true;
		}
		else if (player.teleportTime > 0f)
		{
			player.teleportTime -= Time.deltaTime;
			parent.localPosition = position;
		}
		else
		{
			float num = (player.isRunning ? 4f : 2f);
			float sqrMagnitude = (parent.localPosition - position).sqrMagnitude;
			if (sqrMagnitude > 4f)
			{
				Mathf.Sqrt(sqrMagnitude);
				num *= 2f;
			}
			parent.localPosition = Vector3.MoveTowards(parent.localPosition, position, num * Time.deltaTime);
		}
		if (player.ghostData != null && debugFadeCharactersWhenClose && Is.dev())
		{
			if (player.objectsToFade.Count > 0)
			{
				foreach (GameObject item2 in player.objectsToFade)
				{
					Renderer[] componentsInChildren = item2.GetComponentsInChildren<Renderer>();
					foreach (Renderer item in componentsInChildren)
					{
						player.ghostData.Add(createGhostMaterial(item));
					}
				}
				player.objectsToFade.Clear();
			}
			Vector3 a = playerLocation;
			a.y = parent.localPosition.y;
			float num2 = Vector3.Distance(a, parent.localPosition);
			foreach (NetPlayerMaterialData ghostDatum in player.ghostData)
			{
				for (int j = 0; j < ghostDatum.renderer.materials.Length; j++)
				{
					Material material = ghostDatum.renderer.materials[j];
					if (num2 <= 0.3f)
					{
						if (!ghostDatum.isFade[j])
						{
							toFadeMode(material, zWrite: true, 10);
						}
						float num3 = Mathf.Clamp01(UnityUtils.map(0.35f, 0.15f, 0f, 1f, num2));
						float t = num3 * num3 * num3;
						Color value = ghostDatum.originalColors[j];
						value.a = Mathf.Lerp(ghostDatum.originalColors[j].a, 0f, t);
						material.SetColor("_Color", value);
					}
					else
					{
						if (!ghostDatum.isFade[j])
						{
							toOpaqueMode(material);
						}
						material.SetColor("_Color", ghostDatum.originalColors[j]);
					}
				}
			}
		}
		if (!player.isPlayingInVR)
		{
			Animator animator = player.animator;
			CharacterPoseState poseState = player.characterPoseContext.poseState;
			animator.enabled = poseState == CharacterPoseState.None || poseState == CharacterPoseState.TransitionOut;
			player.animator.SetFloat("Side", Mathf.MoveTowards(player.animator.GetFloat("Side"), vector.x, Time.deltaTime * 10f));
			player.animator.SetFloat("Forward", Mathf.MoveTowards(player.animator.GetFloat("Forward"), vector.z, Time.deltaTime * 6f));
			player.animator.SetFloat("RunningSpeed", Mathf.MoveTowards(player.animator.GetFloat("RunningSpeed"), player.isRunning ? 1 : 0, Time.deltaTime * 8f));
			player.animator.SetBool("Interaction", player.isInteracting);
			player.animator.SetBool("Turnable", player.isUsingTurnable);
			player.animator.SetFloat("EmoteX", player.emoteValue.x);
			player.animator.SetFloat("EmoteY", player.emoteValue.y);
			activateAnimatorTrigger(player, "Emote", ref player.isEmoting);
			player.animator.SetFloat("Turning", processTurning());
			player.animator.SetBool("IsClimbing", player.isClimbing);
			player.animator.SetFloat("ClimbDirection", player.climbingDirection);
			player.animator.SetBool("Examine", player.isInZoom || player.leftHandObject != null || player.rightHandObject != null);
			player.animator.SetBool("Hold", player.inHandItem != null);
			activateAnimatorTrigger(player, "Pickup", ref player.lastPlayerPickUpItem);
			player.animator.SetFloat("PickupHeight", player.pickUpAnimationIndex);
			player.animator.SetBool("Crouch", player.lastPlayerCrouch);
		}
		if (player != localPlayerData && player.isPlayingInVR)
		{
			player.leftHandAnimator.SetFloat("Trigger", player.leftTriggerValue);
			player.leftHandAnimator.SetFloat("Grip", player.leftGripValue);
			player.rightHandAnimator.SetFloat("Trigger", player.rightTriggerValue);
			player.rightHandAnimator.SetFloat("Grip", player.rightGripValue);
		}
		float processTurning()
		{
			float current2 = player.animator.GetFloat("Turning");
			float num4 = player.turning * 10f;
			if (Mathf.Abs(num4) < 0.001f)
			{
				return Mathf.MoveTowards(current2, 0f, Time.deltaTime * 2f);
			}
			num4 = ((!(num4 < 0f)) ? 1 : (-1));
			return Mathf.MoveTowards(current2, num4, Time.deltaTime * 10f);
		}
	}

	private void activateAnimatorTrigger(GamePlayerData player, string animation, ref bool state)
	{
		AnimatorStateInfo currentAnimatorStateInfo = player.animator.GetCurrentAnimatorStateInfo(0);
		player.animator.ResetTrigger(animation);
		if (state && !currentAnimatorStateInfo.IsName(animation))
		{
			player.animator.SetTrigger(animation);
		}
		state = false;
	}

	private void emote(GamePlayerData player, Vector3 emoteValue, bool displayText)
	{
		player.isEmoting = true;
		player.emoteValue = emoteValue;
		if (displayText)
		{
			EmoteValues.EmoteValue forValue = EmoteValues.getForValue(emoteValue);
			string text = Localization.lookupInDictionary("emoteMessage" + forValue.name);
			text = text.Replace("<Name>", session.getUsername(player.id).Colored(Color.aquamarine));
			addChatMessageLocal(text, "", ChatMessage.Type.LevelNote);
			if (forValue == EmoteValues.cheer)
			{
				saveAchievement("ACHIEVEMENT_JUST_DANCE");
			}
		}
	}

	private void forceLocalPlayerToCrouch()
	{
		heightSlider.value = 0;
		heightSlider.visualValue = 0f;
		float num = (heightSlider.visualValue - 2f) * 0.45f;
		headPov.localPosition = playerHeightVector + Vector3.up * num;
		contestedCameraPosition.set(ContestedPose.Game, headPov.position);
		localPlayerData.lastPlayerCrouch = true;
	}

	public void setupGhostData(GamePlayerData data)
	{
		if (data.ghostData == null)
		{
			data.ghostData = new List<NetPlayerMaterialData>();
		}
		data.ghostData.Clear();
		Renderer[] componentsInChildren = data.selectedCharacter.GetComponentsInChildren<Renderer>();
		foreach (Renderer item in componentsInChildren)
		{
			data.ghostData.Add(createGhostMaterial(item));
		}
	}

	public NetPlayerMaterialData createGhostMaterial(Renderer item)
	{
		NetPlayerMaterialData netPlayerMaterialData = new NetPlayerMaterialData
		{
			originalColors = new Color[item.materials.Length],
			isFade = new bool[item.materials.Length]
		};
		for (int i = 0; i < item.materials.Length; i++)
		{
			netPlayerMaterialData.renderer = item;
			Color color = item.materials[i].GetColor("_BaseColor");
			if (color == Color.clear)
			{
				color = item.materials[i].GetColor("_BaseColor");
			}
			netPlayerMaterialData.isFade[i] = item.materials[i].GetTag("RenderType", searchFallbacks: true) == "Transparent";
			if (!netPlayerMaterialData.isFade[i])
			{
				color.a = 1f;
				item.materials[i].SetColor("_BaseColor", color);
			}
			netPlayerMaterialData.originalColors[i] = color;
		}
		return netPlayerMaterialData;
	}

