		}
		GameStarter.splitScreenGame = null;
	}

	private void processGamePacket(Packet gamePacket, GamePlayerData senderPlayer)
	{
		Func<Packet, Interactive> value;
		Interactive interactive = (INTERACTION_PACKET_EXTRACTORS.TryGetValue(gamePacket.GetType(), out value) ? value(gamePacket) : null);
		if (isHost() && interactive != null)
		{
			if (!senderPlayer.interactingObjects.Contains(interactive.gameObject))
			{
				return;
			}
			if (gamePacket is InventoryActionPacket || gamePacket is PlaceItemInSlotPacket)
			{
				session.relay(gamePacket);
			}
			else
			{
				session.send(gamePacket, allowSendInMessageResponse: true);
			}
		}
		bool flag = session.isLocalPlayer(senderPlayer.id);
		bool flag2 = !isHost() && interactive != null;
		Interactive key;
		byte[] value2;
		if (flag2)
		{
			localViewState.Clear();
			foreach (KeyValuePair<Interactive, byte[]> item2 in hostViewState)
			{
				item2.Deconstruct(out key, out value2);
				Interactive interactive2 = key;
				byte[] data = value2;
				localViewState[interactive2] = saveInteractable(interactive2);
				loadInteractable(interactive2, data);
				if (changeAppliers.TryGetValue(interactive2, out var value3))
				{
					value3.Clear();
				}
				else
				{
					changeAppliers[interactive2] = new List<Action<Interactive>>(16);
				}
			}
			if (flag)
			{
				PineFmod.enabled = false;
			}
		}
		try
		{
			processPacket();
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogError($"Exception while processing '{gamePacket.GetType()}' game-packet:\n\n{gamePacket}");
			UnityEngine.Debug.LogException(exception);
		}
		if (!flag2)
		{
			return;
		}
		foreach (KeyValuePair<Interactive, byte[]> item3 in localViewState)
		{
			item3.Deconstruct(out key, out value2);
			Interactive interactive3 = key;
			byte[] data2 = value2;
			if (hostViewState.ContainsKey(interactive3))
			{
				hostViewState[interactive3] = saveInteractable(interactive3);
			}
			loadInteractable(interactive3, data2);
			foreach (Action<Interactive> item4 in changeAppliers[interactive3])
			{
				item4(interactive3);
			}
		}
		if (flag)
		{
			PineFmod.enabled = true;
		}
