		void processExamineItem(ExamineItemPacket packet)
		{
			senderPlayer.isInZoom = packet.isEnteringExamineMode;
			senderPlayer.zoomItem = (packet.isEnteringExamineMode ? packet.examinedItem : null);
			senderPlayer.isZoomItemSharedZoom = false;
			if (packet.isEnteringExamineMode)
			{
				senderPlayer.zoomCameraPosition = adjustPositionForSplitScreen(packet.cameraPosition);
				senderPlayer.zoomCameraRotation = packet.cameraRotation;
				if (gameState.current == GameState.Zoom && checkTopZoomType(ScreenTargetType.SharedZoom) && !isInTopZoom(packet.examinedItem))
				{
					handleZoomLeave();
					recalculateGameState();
				}
			}
			else if (gameState.current == GameState.Zoom && checkTopZoomType(ScreenTargetType.SharedZoom) && isInTopZoom(packet.examinedItem))
			{
				isProcessingPacket = false;
				killAllPointers();
				isProcessingPacket = true;
				handleZoomLeave();
				recalculateGameState();
			}
			if (!packet.examinedItem.TryGetComponent<Zoomable>(out var _))
			{
				if (packet.isEnteringExamineMode)
				{
					if (senderPlayer.sharedZoomImpostor != null)
					{
						destroyZoomBubbleImpostor();
					}
					packet.examinedItem.SetActive(value: false);
					senderPlayer.sharedZoomBubble.transform.rotation = Quaternion.identity;
					senderPlayer.sharedZoomBubble.transform.localScale = Vector3.one * 0.25f;
					senderPlayer.sharedZoomBubble.SetActive(value: true);
					if (packet.examinedItem.TryGetComponent<ZoomLod>(out var component2))
					{
						component2.syncLODs(isZoom: true);
					}
					senderPlayer.sharedZoomImpostor = ImpostorClone.create(impostorContext, packet.examinedItem, LayerMask.NameToLayer("Characters"), strip: true, delegate
					{
						onChangedBubbleImpostor(senderPlayer.sharedZoomBubble, senderPlayer.sharedZoomImpostor, packet.examinedItem);
					});
					setParent(senderPlayer.sharedZoomImpostor.transform, senderPlayer.sharedZoomBubble.transform);
					onChangedBubbleImpostor(senderPlayer.sharedZoomBubble, senderPlayer.sharedZoomImpostor, packet.examinedItem);
				}
				else
				{
					destroyZoomBubbleImpostor();
				}
			}
			if (senderPlayer.inHandItemBubble != null)
			{
				senderPlayer.inHandItemBubble.SetActive(!packet.isEnteringExamineMode);
			}
			void destroyZoomBubbleImpostor()
			{
				UnityEngine.Object.Destroy(senderPlayer.sharedZoomImpostor);
				packet.examinedItem.SetActive(packet.isItemVisibleOnExit);
				senderPlayer.sharedZoomBubble.SetActive(value: false);
				if (packet.examinedItem.TryGetComponent<ZoomLod>(out var component3))
				{
					component3.syncLODs(isZoom: false);
				}
			}
		}
