		void processInGameMessage(InGameMessagePacket packet)
		{
			string text = packet.messageText;
			if (PlayerSave.getSettings().chatProfanityFilterEnabled)
			{
				string[] array = Regex.Split(text, "\\s+");
				StringBuilder stringBuilder = new StringBuilder(128);
				string[] array2 = array;
				foreach (string text2 in array2)
				{
					if (chatBlacklist.Contains(text2))
					{
						stringBuilder.Append('*', text2.Length);
					}
					else
					{
						stringBuilder.Append(text2);
					}
					stringBuilder.Append(' ');
				}
				text = stringBuilder.ToString();
			}
			ChatMessage.Type type = packet.messageType;
			if (type == ChatMessage.Type.LocalPlayer)
			{
				type = ChatMessage.Type.OtherPlayer;
			}
			NetPlayerData netPlayerData = session.players.Find((NetPlayerData x) => x.id == senderPlayer.id);
			addChatMessageLocal(text, netPlayerData.username, type);
		}
		void processInteractionOverlap(Interactive interactable, byte[] initialState)
		{
			UnityEngine.Debug.LogError($"[{base.name}] INTERACTION OVERLAP - Interaction with {interactable.GetType().Name} '{interactable}' was not confirmed.", interactable);
			clearAllPointers();
			if (interactable is Slot slot)
			{
				handleSlotCancel(slot);
			}
			if (interactable is SurfaceSlot surfaceSlot)
			{
				handleSurfaceSlotCancel(surfaceSlot);
			}
			if (interactable is Item { carriable: not false } item)
			{
				carriableCancel(item);
			}
			if (interactable is Jigsaw jigsaw && jigsaw.deferedPiece != null)
			{
				isProcessingPacket = false;
				addItemToInventory(jigsaw.deferedPiece.linkedItem.gameObject);
				jigsaw.deferedPiece.gameObject.SetActive(value: false);
				isProcessingPacket = true;
			}
			loadInteractable(interactable, initialState);
			cancelSoundsOnInteractive(interactable);
			confirmEndInteraction(interactable);
			deferredInteractives.Remove(interactable);
			if (isInInventory(interactable.gameObject))
			{
				removeItemFromInventory(interactable.gameObject, isForDrag: false, syncMultiplayer: false);
			}
			if (interactable is CharacterPose pose)
			{
				handlePoseCancel(pose);
			}
			if (isSelectedInPCMode(interactable.gameObject))
			{
				pcChangeItemSelectionIndex(-1);
			}
			if (interactable is Draggable)
			{
				clearDragLineRenderer();
			}
		}
		void processInventoryAction(InventoryActionPacket packet)
		{
			bool isAddedToInventory = packet.isAddedToInventory;
			Item item = packet.item;
			bool disableItemWhenRemoving = packet.disableItemWhenRemoving;
			if (item != null)
			{
				ItemState itemState = getItemState(item);
				if (itemState != ItemState.SlotAnimation && itemState != ItemState.Slot && isAddedToInventory)
				{
					item.hasRigidbody = true;
				}
			}
			if (isAddedToInventory)
			{
				processInventoryAdd();
			}
			else
			{
				removeItemFromBelt(senderPlayer, item.gameObject, disableItemWhenRemoving);
			}
		}
		void processInventoryAdd()
		{
			if (senderPlayer.isPlayingInVR)
			{
				Bounds bounds = computeLocalBounds(P_0.item.gameObject);
				Vector3 position = P_0.item.transform.position + P_0.item.transform.TransformDirection(bounds.center);
				UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(animationPoof, position, Quaternion.identity, levelContainer.transform), 3f);
			}
			if (!senderPlayer.inventory.Contains(P_0.item.gameObject))
			{
				senderPlayer.inventory.Add(P_0.item.gameObject);
				callOrDeferOnAddItemToInventory(P_0.item);
			}
			senderPlayer.lastPlayerPickUpItem = true;
			float num = P_0.item.transform.position.y;
			if (senderPlayer.lastPlayerCrouch)
			{
				num += 0.5f;
			}
			senderPlayer.pickUpAnimationIndex = ((!(num < 0.8f)) ? ((num < 1.3f) ? 1 : 2) : 0);
			Vector3 localScale = zoomAttachment.localScale;
			zoomAttachment.localScale = Vector3.one;
			setParent(P_0.item.transform, levelContainerTransform);
			zoomAttachment.localScale = localScale;
			P_0.item.gameObject.SetActive(value: false);
			destroyGameplayTweens(P_0.item.gameObject);
		}
		void processKickPlayer(KickPlayerPacket packet)
		{
			removePlayerFromGame(packet.playerBeingKicked);
		}
		void processLevelLogicPacket(LevelLogicPacket packet)
		{
			Packet packet2 = packet.toConcretePacket(levelLogic);
			if (packet2 != null)
			{
				levelLogic.onPacket(packet2);
			}
		}
		void processLocationPing(LocationPingPacket packet)
		{
			Vector3 vector = adjustPositionForSplitScreen(packet.pingPosition);
			showLocationPing(vector, packet.pingRotation);
			senderPlayer.lastPingLocation = vector;
			senderPlayer.offScreenIndicatorTimer = 0f;
			senderPlayer.animateOffScreenIndicator = true;
			emote(senderPlayer, EmoteValues.point.value, displayText: false);
			if (packet.pingedInteractable != null)
			{
				addChatMessageLocal(Localization.translate(packet.pingedInteractable.displayName), session.getUsername(senderPlayer.id), ChatMessage.Type.PingOnObject);
			}
			else
			{
				addChatMessageLocal(Localization.lookupInDictionary("Pinged"), session.getUsername(senderPlayer.id), ChatMessage.Type.Ping);
			}
		}
		void processNpcZoomEnter(NpcZoomEnterPacket packet)
		{
			senderPlayer.isInZoom = true;
			senderPlayer.zoomItem = packet.npc.gameObject;
		}
