		void processPaintPaintable(PaintPaintablePacket packet)
		{
			if (isSplitscreen)
			{
				packet.edit.cameraPosition.z += getSplitscreenPositionOffset();
			}
			handlePaintable(packet.paintable, in packet.edit, packet.change, packet.gestureDown, packet.gestureUp);
		}
		void processPinItem(PinItemPacket packet)
		{
			Vector3 pinPosition = packet.pinPosition;
			if (isSplitscreen)
			{
				pinPosition.z += getSplitscreenPositionOffset();
			}
			vrPinnedItems.Add(new VRPinnedItem
			{
				gameObject = packet.pinnedItem,
				pinPosition = pinPosition,
				pinRotation = packet.pinRotation,
				pinTime = packet.pinTime
			});
		}
		void processPingItem(PingItemPacket packet)
		{
			UnityEngine.Debug.Log("processPingItem " + packet.item);
			inventory.Find((InventoryItem x) => x.gameObjects.Contains(packet.item.gameObject)).pingTimestamp = Time.time;
		}
		void processPlaceItemInWorld(PlaceItemInWorldPacket packet)
		{
			if (!(packet.item == null))
			{
				packet.item.transform.position = adjustPositionForSplitScreen(packet.position);
				packet.item.transform.rotation = packet.rotation;
			}
		}
		void processPlayerPose(PlayerPosePacket packet)
		{
			if (senderPlayer.hasCharacterInited)
			{
				if (senderPlayer.playerModelVisibility == GamePlayerData.PlayerModelVisibility.WaitingForInitialPlayerPosePacket)
				{
					senderPlayer.playerModelVisibility = GamePlayerData.PlayerModelVisibility.InitialPlayerPosePacketReceived;
				}
				if (!UnityUtils.closeEnough(packet.position, Vector3.forward * 100000f))
				{
					bool isCrouching = packet.isCrouching;
					bool isTeleporting = packet.isTeleporting;
					bool isClimbing = packet.isClimbing;
					int climbDirection = packet.climbDirection;
					if (isTeleporting)
					{
						senderPlayer.teleportTime = 0.5f;
					}
					senderPlayer.lastTransformPose = new Pose(packet.position, packet.rotation);
					senderPlayer.currentRotation = packet.currentRotation;
					bool lastPlayerCrouch = senderPlayer.lastPlayerCrouch;
					senderPlayer.lastPlayerCrouch = isCrouching;
					senderPlayer.isClimbing = isClimbing;
					senderPlayer.climbingDirection = climbDirection;
					senderPlayer.isRunning = packet.isRunning;
					senderPlayer.turning = packet.turning;
					if (lastPlayerCrouch != senderPlayer.lastPlayerCrouch)
					{
						float num = 2f;
						float num2 = 1f;
						if (!senderPlayer.isMale)
						{
							num2 = 0.88f;
						}
						senderPlayer.playerCollider.height = ((!senderPlayer.lastPlayerCrouch) ? num : (num - num / 4f));
						Vector3 center = senderPlayer.playerCollider.center;
						center.y = ((!senderPlayer.lastPlayerCrouch) ? num2 : (num2 - num / 8f));
						senderPlayer.playerCollider.center = center;
					}
				}
			}
		}
