		void processReplicateWithImpostor(ReplicateWithImpostorPacket packet)
		{
			switch (packet.replicateType)
			{
			case ReplicateWithImpostorType.Init:
			{
				GameObject gameObject = ImpostorClone.create(impostorContext, packet.originalObject);
				Vector3 impostorPosition2 = packet.impostorPosition;
				if (isSplitscreen)
				{
					impostorPosition2.z += getSplitscreenPositionOffset();
				}
				gameObject.transform.position = impostorPosition2;
				gameObject.transform.rotation = packet.impostorRotation;
				this.remoteNetworkedImposters.Add(new RemoteNetworkedImposters
				{
					original = packet.originalObject,
					impostor = gameObject
				});
				break;
			}
			case ReplicateWithImpostorType.Update:
			{
				RemoteNetworkedImposters obj = this.remoteNetworkedImposters.Find((RemoteNetworkedImposters x) => x.original == packet.originalObject);
				Vector3 impostorPosition = packet.impostorPosition;
				if (isSplitscreen)
				{
					impostorPosition.z += getSplitscreenPositionOffset();
				}
				obj.impostor.transform.position = impostorPosition;
				obj.impostor.transform.rotation = packet.impostorRotation;
				break;
			}
			case ReplicateWithImpostorType.Destroy:
			{
				RemoteNetworkedImposters remoteNetworkedImposters = this.remoteNetworkedImposters.Find((RemoteNetworkedImposters x) => x.original == packet.originalObject);
				UnityEngine.Object.Destroy(remoteNetworkedImposters.impostor);
				this.remoteNetworkedImposters.Remove(remoteNetworkedImposters);
				break;
			}
			}
		}
