		void processSceneCheckRequest(SceneCheckRequestPacket packet)
		{
			if (ESUGC.current.isCustomLevel(packet.levelName))
			{
				ESUGC.current.getVersion(packet.levelName, delegate(uint num)
				{
					string localVersion = num.ToString();
					session.sendToSpecificPlayer(new SceneCheckResponsePacket
					{
						sceneName = packet.levelName,
						result = canSceneLoadLocally(packet.levelName, localVersion, packet.versionToCheck)
					}, session.hostPlayerId, allowSendInMessageResponse: true);
				}, delegate(string error)
				{
					session.sendToSpecificPlayer(new SceneCheckResponsePacket
					{
						sceneName = packet.levelName,
						result = CanLoadSceneResult.CannotLoadUGCFail
					}, session.hostPlayerId, allowSendInMessageResponse: true);
					UnityEngine.Debug.LogError("Failed to get version for custom level " + packet.levelName + ": " + error);
				});
			}
			else
			{
				string version = RoomDatabase.getVersion(packet.levelName);
				session.sendToSpecificPlayer(new SceneCheckResponsePacket
				{
					sceneName = packet.levelName,
					result = canSceneLoadLocally(packet.levelName, version, packet.versionToCheck)
				}, session.hostPlayerId, allowSendInMessageResponse: true);
			}
		}
		void processSceneCheckResponse(SceneCheckResponsePacket packet)
		{
			if (currentSceneCheck == null)
			{
				UnityEngine.Debug.Log("Received SceneCheckResponsePacket " + packet.sceneName + " but currentSceneLoadCheck is null");
			}
			else if (currentSceneCheck.sceneName != packet.sceneName)
			{
				UnityEngine.Debug.Log("Received SceneCheckResponsePacket for a different scene than the one we are checking packet:" + packet.sceneName + " check:" + currentSceneCheck.sceneName);
			}
			else if (currentSceneCheck.validPlayers.Contains(senderPlayer.id))
			{
				UnityEngine.Debug.Log(string.Format("Received {0} for a player that already responded valid {1}", "SceneCheckResponsePacket", senderPlayer.id));
			}
			else if (currentSceneCheck.invalidPlayers.FindIndex(((NetPlayerId playerId, CanLoadSceneResult result) player) => player.playerId == senderPlayer.id) >= 0)
			{
				UnityEngine.Debug.Log(string.Format("Received {0} for a player that already responded invalid {1}", "SceneCheckResponsePacket", senderPlayer.id));
			}
			else
			{
				UnityEngine.Debug.Log(string.Format("Received {0} {1} from {2}", "SceneCheckResponsePacket", packet.result, senderPlayer.id));
				addPlayerToSceneCheck(senderPlayer.id, packet.result);
			}
		}
		void processSceneLoadRequest(SceneLoadRequestPacket packet)
		{
			if (isHost())
			{
				if (currentSceneCheck != null && currentSceneCheck.invalidPlayers.Count + currentSceneCheck.validPlayers.Count < session.players.Count)
				{
					UnityEngine.Debug.Log("Received SceneLoadRequestPacket " + packet.sceneName + " but currentSceneLoadCheck is not finished yet");
				}
				SceneCheckPostEvent postEvent = ((!packet.shouldLoadLatestSave) ? SceneCheckPostEvent.LoadScene : SceneCheckPostEvent.LoadSceneAndSave);
				startSceneCheck(packet.sceneName, postEvent, packet.senderId);
			}
		}
		void processSelectItemInHand(SelectItemInHandPacket packet)
		{
			createSelectedItemInHand(senderPlayer, packet.selectedItem);
		}
		void processSharedZoomRotation(SharedZoomRotationPacket packet)
		{
			if (topZoomContextSafe(out var context) && netPlayers.Find((GamePlayerData x) => x.zoomItem == context.selected && x.id == packet.senderId) != null)
			{
				zoomAttachment.rotation = playerCamera.transform.rotation * packet.rotation;
			}
		}
		void processStartInteraction(StartInteractionPacket packet)
		{
			Interactive component = packet.interactable.GetComponent<Interactive>();
			if (isHost())
			{
				if (packet.requestedInteractionId == component.hostSyncedInteractionId)
				{
					session.relay(packet);
					session.sendToSpecificPlayerFromHost(new ConfirmStartInteractionPacket
					{
						interactable = component,
						confirmedInteractionId = component.hostSyncedInteractionId
					}, packet.senderId, allowSendInMessageResponse: true);
					component.hostSyncedInteractionId++;
					senderPlayer.interactingObjects.Add(packet.interactable.gameObject);
					setAuthority(component.gameObject, packet.senderId);
				}
				else
				{
					UnityEngine.Debug.Log($"Host: Player '{session.getUsername(packet.senderId)}' can't start interaction with '{component.name}', Requested ID: {packet.requestedInteractionId} | Host ID: {component.hostSyncedInteractionId}", component);
				}
			}
			else
			{
				if (hasDeferred(component))
				{
					processInteractionOverlap(component, packet.initialState);
				}
				component.hostSyncedInteractionId = packet.requestedInteractionId + 1;
				senderPlayer.interactingObjects.Add(packet.interactable.gameObject);
				setAuthority(component.gameObject, packet.senderId);
				UnityEngine.Debug.Log("Client: Other player is starting interaction with: " + component.name, component);
			}
		}
		void processStealing(StealingPacket packet)
		{
			foreach (GamePlayerData netPlayer in netPlayers)
			{
				if (netPlayer.inventory.Contains(packet.item))
				{
					removeItemFromBelt(netPlayer, packet.item, disableItemWhenRemoving: false);
				}
			}
			if (isInInventory(packet.item))
			{
				removeItemFromInventory(packet.item, isForDrag: false, syncMultiplayer: false);
			}
			packet.item.gameObject.SetActive(value: false);
		}
		void processStoppedEndScreenAnimation(StoppedEndScreenAnimationPacket packet)
		{
			senderPlayer.isEndScreenAnimationRunning = false;
		}
		void processSyncTimerTime(SyncTimerTimePacket packet)
		{
			timerCurrentTime = packet.timerTime;
		}
		void processSyncTransform(SyncTransformPacket packet)
		{
			TransformSnapshot snapshot = packet.snapshot;
			if (snapshot != null && !(snapshot.targetObject == null))
			{
				if (session.connectionMode == ConnectionMode.Splitscreen)
				{
					snapshot.position.z += getSplitscreenPositionOffset();
				}
				if (snapshot.targetObject.TryGetComponent<TransformSync>(out var component))
				{
					component.handleSnapshot(snapshot);
				}
			}
		}
		void processTakeCameraPicture(TakeCameraPicturePacket packet)
		{
			if (vrPictureCamera != null)
			{
				Vector3 position = vrPictureCamera.transform.position;
				Quaternion rotation = vrPictureCamera.transform.rotation;
				if (!isSplitscreen)
				{
					vrPictureCamera.transform.position = packet.cameraPosition;
					vrPictureCamera.transform.rotation = packet.cameraRotation;
				}
				vrPictureCamera.takePicture(saveScreenshotToDisk: false);
				vrPictureCamera.transform.position = position;
				vrPictureCamera.transform.rotation = rotation;
			}
			else
			{
				UnityEngine.Debug.LogError("Cannot take picture as 'vrPictureCamera' is null.");
			}
		}
		static void processToggleVisibility(ToggleVisibilityPacket packet)
		{
			packet.targetObject.SetActive(packet.isVisible);
			packet.targetObject.transform.position = packet.positionWhenVisible;
			packet.targetObject.transform.rotation = packet.rotationWhenVisible;
		}
		void processToolUse(ToolInteractionPacket toolUsePacket)
		{
			handleToolInteraction(toolUsePacket.tool, toolUsePacket.context);
		}
		void processVRPlayerTransformPacket(VRPlayerTransformPacket packet)
		{
			VRPlayerTransformPacket vrLastPlayerTransform = senderPlayer.vrLastPlayerTransform;
			if (vrLastPlayerTransform != null)
			{
				if ((packet.usedFieldsBitMask & 1) == 0)
				{
					packet.headPosition = vrLastPlayerTransform.headPosition;
				}
				if ((packet.usedFieldsBitMask & 2) == 0)
				{
					packet.headRotation = vrLastPlayerTransform.headRotation;
				}
				if ((packet.usedFieldsBitMask & 4) == 0)
				{
					packet.torsoRotation = vrLastPlayerTransform.torsoRotation;
				}
				if ((packet.usedFieldsBitMask & 8) == 0)
				{
					packet.forceTorsoRotation = vrLastPlayerTransform.forceTorsoRotation;
				}
				if ((packet.usedFieldsBitMask & 0x10) == 0)
				{
					packet.leftHandPosition = vrLastPlayerTransform.leftHandPosition;
				}
				if ((packet.usedFieldsBitMask & 0x20) == 0)
				{
					packet.leftHandRotation = vrLastPlayerTransform.leftHandRotation;
				}
				if ((packet.usedFieldsBitMask & 0x40) == 0)
				{
					packet.leftHandPackedGripValue = vrLastPlayerTransform.leftHandPackedGripValue;
				}
				if ((packet.usedFieldsBitMask & 0x80) == 0)
				{
					packet.leftHandPackedTriggerValue = vrLastPlayerTransform.leftHandPackedTriggerValue;
				}
				if ((packet.usedFieldsBitMask & 0x100) == 0)
				{
					packet.rightHandPosition = vrLastPlayerTransform.rightHandPosition;
				}
				if ((packet.usedFieldsBitMask & 0x200) == 0)
				{
					packet.rightHandRotation = vrLastPlayerTransform.rightHandRotation;
				}
				if ((packet.usedFieldsBitMask & 0x400) == 0)
				{
					packet.rightHandPackedGripValue = vrLastPlayerTransform.rightHandPackedGripValue;
				}
				if ((packet.usedFieldsBitMask & 0x800) == 0)
				{
					packet.rightHandPackedTriggerValue = vrLastPlayerTransform.rightHandPackedTriggerValue;
				}
			}
			senderPlayer.vrLastPlayerTransform = packet;
		}
		void processVrGrabbedObjectPos(VRHeldItemPosePacket packet)
		{
			if (packet.handId == 1)
			{
				if (senderPlayer.leftHandObject != null)
				{
					senderPlayer.leftHandObjectPos = packet.heldObjectPos;
					senderPlayer.leftHandObjectRot = packet.heldObjectRot;
				}
			}
			else if (senderPlayer.rightHandObject != null)
			{
				senderPlayer.rightHandObjectPos = packet.heldObjectPos;
				senderPlayer.rightHandObjectRot = packet.heldObjectRot;
			}
		}
		void processZoomCursor(ZoomCursorPacket packet)
		{
			float num = (float)Screen.height / packet.screenHeight;
			Vector2 vector = packet.screenPositionFromCenter * (num * (1f / cursorCanvas.transform.localScale.x));
			Vector2 vector2 = new Vector2(senderPlayer.zoomCursor.sizeDelta.x / 4f, (0f - senderPlayer.zoomCursor.sizeDelta.y) / 2f);
			senderPlayer.zoomCursor.anchoredPosition = vector + vector2;
		}
	}

	private void createSelectedItemInHand(GamePlayerData senderPlayer, Item item)
	{
		senderPlayer.inHandItem = item;
		if (senderPlayer.inHandItemBubble != null)
		{
			UnityEngine.Object.Destroy(senderPlayer.inHandItemBubble);
		}
		if (item != null)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(bubbleTemplate, senderPlayer.playerObject.transform);
			gameObject.layer = LayerMask.NameToLayer("Characters");
			gameObject.transform.localScale = Vector3.one * 0.2f;
			GameObject gameObject2 = ImpostorClone.create(impostorContext, item.gameObject, LayerMask.NameToLayer("Characters"), strip: true, processHandBubbleClone);
			processHandBubbleClone(gameObject2.GetComponent<ImpostorClone>());
			setParent(gameObject2.transform, gameObject.transform);
			updateBubbleItemPosition(gameObject, gameObject2, item.gameObject);
			senderPlayer.inHandItemBubble = gameObject;
			senderPlayer.initialHandItemBubbleScale = gameObject.transform.localScale;
			senderPlayer.sharedZoomStartBounds = computeLocalBounds(gameObject2);
		}
		else
		{
			senderPlayer.inHandItemBubble = null;
		}
		static void processHandBubbleClone(ImpostorClone clone)
		{
			Renderer[] componentsInChildren = clone.GetComponentsInChildren<Renderer>(includeInactive: true);
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].shadowCastingMode = ShadowCastingMode.Off;
			}
		}
	}

	private Vector3 adjustPositionForSplitScreen(Vector3 position)
	{
		if (!isSplitscreen)
		{
			return position;
		}
		Vector3 result = position;
		position.z += getSplitscreenPositionOffset();
		return result;
	}

	private float getSplitscreenPositionOffset()
	{
		if (session.localPlayerId == Net.SPLITSCREEN_CLIENT_ID)
		{
			return 300f;
		}
		return -300f;
	}

	private void onChangedBubbleImpostor(GameObject bubble, GameObject impostor, GameObject original)
	{
		SharedZoomObject sharedZoomObject = impostor.AddComponent<SharedZoomObject>();
		if (!renderPlayers)
		{
			sharedZoomObject.targetable = false;
		}
		updateBubbleItemPosition(bubble, impostor, original);
		MeshRenderer[] componentsInChildren = impostor.GetComponentsInChildren<MeshRenderer>(includeInactive: true);
		foreach (MeshRenderer meshRenderer in componentsInChildren)
		{
			MeshFilter component = meshRenderer.GetComponent<MeshFilter>();
			if (component == null)
			{
				UnityEngine.Debug.LogError("Object " + meshRenderer.name + " has 'MeshRenderer', but no 'MeshFilter'.", meshRenderer);
			}
			else if (component.mesh.vertexCount > 0)
			{
				meshRenderer.gameObject.AddComponent<BoxCollider>();
			}
		}
	}

	private void removeItemFromBelt(GamePlayerData player, GameObject item, bool disableItemWhenRemoving)
	{
		player.inventory.Remove(item);
		if (item.TryGetComponent<Item>(out var component) && getItemState(component) == ItemState.World)
		{
			item.transform.position = getFingerAveragePosition(player);
		}
		item.SetActive(disableItemWhenRemoving);
	}

	public void updateBeltItemsPositions(List<NetInventoryBeltItem> inventoryBelt, float radius = 0.003f, bool lerp = false)
	{
		for (int i = 0; i < inventoryBelt.Count; i++)
		{
			NetInventoryBeltItem netInventoryBeltItem = inventoryBelt[i];
			updateBubbleItemPosition(netInventoryBeltItem.bubble, netInventoryBeltItem.impostor, netInventoryBeltItem.original);
			float f = (float)i * MathF.PI * 2f / (float)inventoryBelt.Count;
			Vector3 vector = new Vector3(Mathf.Cos(f) * radius, 0f, Mathf.Sin(f) * radius) * 0.6f;
			if (lerp)
			{
				destroyGameplayTweens(netInventoryBeltItem.bubble);
				PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
				GameObject bubble = netInventoryBeltItem.bubble;
				Vector3? localPositionTo = vector;
				gameplayTween.tween(-1, bubble, 1f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, localPositionTo, null, null, null, null, null, null, null, null, null, null, Interpolation.SmootherStep);
			}
			else
			{
				netInventoryBeltItem.bubble.transform.localPosition = vector;
			}
		}
	}

	private void updateBubbleItemPosition(GameObject bubble, GameObject impostor, GameObject original)
	{
		Quaternion rotation = bubble.transform.rotation;
		bubble.transform.rotation = Quaternion.identity;
		Bounds bounds = computeLocalBounds(impostor);
		Vector3 vector = original.transform.lossyScale.normalized * 1.75f * (1f / bounds.extents.magnitude) * 0.5f;
		if (isInfinity(vector))
		{
			vector = Vector3.one;
		}
		impostor.transform.localScale = vector;
		Item component = original.GetComponent<Item>();
		Quaternion quaternion = Quaternion.identity;
		if (component != null)
		{
			quaternion = Quaternion.Euler(component.examineBaseRotation);
		}
		Vector3 vector2 = Vector3.Scale(impostor.transform.localScale, quaternion * bounds.center);
		impostor.transform.localPosition = -vector2;
		Quaternion rotation2 = Quaternion.identity;
		if (component != null)
		{
			rotation2 = Quaternion.Euler(component.examineBaseRotation);
		}
		impostor.transform.rotation = rotation2;
		bubble.transform.rotation = rotation;
	}

	private bool isInfinity(Vector3 value)
	{
		if (value == Vector3.positiveInfinity || value == Vector3.negativeInfinity)
		{
			UnityEngine.Debug.Log("isInfinity 1");
			return true;
		}
		if (float.IsInfinity(value.x) || float.IsInfinity(value.y) || float.IsInfinity(value.z))
		{
			UnityEngine.Debug.Log("isInfinity 2");
			return true;
		}
		if (float.IsNaN(value.x) || float.IsNaN(value.y) || float.IsNaN(value.z))
		{
			UnityEngine.Debug.Log("isInfinity 3");
			return true;
		}
		return false;
	}

	public CollisionData addCollisionData(GameObject go)
	{
		if (go.GetComponent<Rigidbody>() == null)
		{
			return null;
		}
		CollisionData component = go.GetComponent<CollisionData>();
		if (component != null)
		{
			return component;
		}
		return go.AddComponent<CollisionData>();
	}

	private void setAuthority(GameObject go, NetPlayerId playerId)
	{
		if (go == null)
		{
			UnityEngine.Debug.LogError("Cannot set authority on null game-object.");
			return;
		}
		Interactive[] componentsInChildren = go.GetComponentsInChildren<Interactive>(includeInactive: true);
		foreach (Interactive interactive in componentsInChildren)
		{
			if (!(interactive.authorityPlayerId == playerId))
			{
				UnityEngine.Debug.Log(string.Format("[{0}] {1}: {2} -> {3}", "setAuthority", interactive, session.getUsername(interactive.authorityPlayerId), session.getUsername(playerId)), interactive);
				interactive.authorityPlayerId = playerId;
			}
		}
	}

	private void startInteraction(GameObject interactingObject)
	{
		Interactive component = interactingObject.GetComponent<Interactive>();
		startInteractionWith(component);
		foreach (Interactive linkedInteractive in component.linkedInteractives)
		{
			startInteractionWith(linkedInteractive);
		}
		void startInteractionWith(Interactive interactable)
		{
			if (!myInteractingObjects.Add(interactable.gameObject))
			{
				UnityEngine.Debug.LogError($"[{Time.frameCount}] Cannot interact with {interactable} because you are already interacting with it.", interactable);
			}
			else
			{
				byte[] array = saveInteractable(interactable);
				if (!isHost())
				{
					hostViewState[interactable] = array;
					deferredInteractives.Add(interactable);
				}
				session.send(new StartInteractionPacket
				{
					interactable = interactable,
					requestedInteractionId = interactable.hostSyncedInteractionId,
					initialState = array
				}, allowSendInMessageResponse: true);
				if (isHost())
				{
					interactable.hostSyncedInteractionId++;
					setAuthority(interactable.gameObject, session.localPlayerId);
				}
				updatePuzzleInteraction(interactable.gameObject);
			}
		}
	}

	private void captureHostViewState(Interactive rootInteractable)
	{
		if (isHost())
		{
			return;
		}
		hostViewState[rootInteractable] = saveInteractable(rootInteractable);
		foreach (Interactive linkedInteractive in rootInteractable.linkedInteractives)
		{
			hostViewState[linkedInteractive] = saveInteractable(linkedInteractive);
		}
	}

	private void stopInteraction(GameObject interactingObject)
	{
		Interactive component = interactingObject.GetComponent<Interactive>();
		stopInteractionWith(component);
		foreach (Interactive linkedInteractive in component.linkedInteractives)
		{
			stopInteractionWith(linkedInteractive);
		}
		void stopInteractionWith(Interactive interactable)
		{
			if (!(interactable == null) && !interactable.backgroundUpdate)
			{
				if (!isLocalPlayerInteracting(interactable.gameObject))
				{
					UnityEngine.Debug.LogError("Attempting to stop interaction with " + interactable.name + " but not interacting with it.", interactable);
				}
				else
				{
					session.send(new EndInteractionPacket
					{
						interactable = interactable
					}, allowSendInMessageResponse: true);
					if (isHost())
					{
						confirmEndInteraction(interactable);
					}
					else
					{
						endInteractionUnconfirmedInteractives.Add(interactable);
					}
				}
			}
		}
	}

	private void confirmEndInteraction(Interactive interactable)
	{
		hostViewState.Remove(interactable);
		myInteractingObjects.Remove(interactable.gameObject);
		endInteractionUnconfirmedInteractives.Remove(interactable);
	}

