	private void sendLocationPing()
	{
		int layerMask = -5 & ~LayerMask.GetMask("IgnoreTrigger", "RoomEditorSpecialObject", "Teleportation", "VRHands", "ItemExamine");
		if (Physics.Raycast(vr.isActive() ? new Ray(vr.rig.rightController.raycastSource.position, vr.rig.rightController.raycastSource.forward) : playerCamera.ViewportPointToRay(getMousePositionViewport()), out var hitInfo, 1000f, layerMask, QueryTriggerInteraction.Ignore))
		{
			Vector3 point = hitInfo.point;
			Quaternion quaternion = Quaternion.LookRotation(-hitInfo.normal);
			getObjectUnderViewportPosition(getMousePositionViewport(), out var pointer);
			if (pointer != null && pointer.context != null && pointer.context.target != null && pointer.context.target.TryGetComponent<Interactive>(out var component) && !string.IsNullOrEmpty(component.displayName))
			{
				session.send(new LocationPingPacket
				{
					pingPosition = point,
					pingRotation = quaternion,
					pingedInteractable = component
				});
				addChatMessageLocal(Localization.translate(component.displayName), session.getUsername(), ChatMessage.Type.PingOnObject);
			}
			else
			{
				session.send(new LocationPingPacket
				{
					pingPosition = point,
					pingRotation = quaternion,
					pingedInteractable = null
				});
				addChatMessageLocal(Localization.lookupInDictionary("Pinged"), session.getUsername(), ChatMessage.Type.Ping);
			}
			showLocationPing(point, quaternion);
			emote(localPlayerData, EmoteValues.point.value, displayText: false);
		}
		else
		{
			addChatMessageSynced(Localization.lookupInDictionary("Pinged"), ChatMessage.Type.Ping);
		}
		achievementCheckPing();
	}

