	public void callRPC<T>(T type) where T : Enum
	{
		if (isHost())
		{
			levelLogic.onRPCCalled((int)(object)type);
			session.send(new LevelRPCPacket
			{
				rpcType = (int)(object)type
			}, allowSendInMessageResponse: true);
		}
	}

	public bool shouldSyncTransform(GameObject targetObject, bool checkHierarchy = true)
	{
		if (checkHierarchy && !targetObject.activeInHierarchy)
		{
			return false;
		}
		Rigidbody component = targetObject.GetComponent<Rigidbody>();
		if (component != null)
		{
			if (component.isKinematic)
			{
				return shouldSyncDynamicRigidbody(component);
			}
			return true;
		}
		Item component2 = targetObject.GetComponent<Item>();
		if (component2 != null)
		{
			return shouldSyncItem(component2);
		}
		return false;
		bool shouldSyncDynamicRigidbody(Rigidbody rb)
		{
			if (targetObject.transform.parent.GetComponentInParent<Rigidbody>() != null && rb.isKinematic)
			{
				return false;
			}
			return shouldSyncDynamicShared(targetObject);
		}
	}

	private bool shouldSyncItem(Item item)
	{
		if (isInTopZoom(item.gameObject) || isAnyPlayerZoomIn(item.gameObject))
		{
			return true;
		}
		if (!hasAuthority(item.gameObject))
		{
			return false;
		}
		if (item.GetComponentInParent<Rigidbody>() != null)
		{
			return false;
		}
		return shouldSyncDynamicShared(item.gameObject);
	}

	private bool shouldSyncDynamicShared(GameObject targetObject)
	{
		if (isInTopZoom(targetObject) || isAnyPlayerZoomIn(targetObject) || isInAnyVRPlayerHand(targetObject))
		{
			return true;
		}
		Zoomable componentInParent = targetObject.GetComponentInParent<Zoomable>(includeInactive: true);
		if ((bool)componentInParent && componentInParent.targetable)
		{
			return true;
		}
		return false;
	}

