	public void onGamePacket(Packet packet)
	{
		GamePlayerData gamePlayerData = netPlayers.Find((GamePlayerData player) => player.id == packet.senderId);
		if (localPlayerData.id == packet.senderId)
		{
			gamePlayerData = localPlayerData;
		}
		if (gamePlayerData == null)
		{
			UnityEngine.Debug.LogError($"Game: Cannot process {packet.GetType()} as player with ID {packet.senderId} is not found.");
			return;
		}
		gamePlayerData.lastKeepAliveTimestamp = Time.time;
		isProcessingPacket = true;
		processingPacketPlayerId = gamePlayerData.id;
		try
		{
			processLevelSyncPacket(packet);
			processGamePacket(packet, gamePlayerData);
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogError($"Exception occurred while processing the following '{packet.GetType()}' game-packet:\n\n{packet}");
			UnityEngine.Debug.LogException(exception);
		}
		isProcessingPacket = false;
		processingPacketPlayerId = null;
	}

