	private void syncNetPlayers()
	{
		foreach (NetPlayerData player in session.players)
		{
			NetPlayerId playerId = player.id;
			if (!session.isLocalPlayer(playerId) && netPlayers.Find((GamePlayerData p) => p.id == playerId) == null)
			{
				UnityEngine.Debug.Log($"Adding player to game: {playerId}");
				addPlayerToGame(playerId);
			}
		}
	}

	public void addPlayerToGame(NetPlayerId playerId)
	{
		UnityEngine.Debug.Log($"addPlayerToSession with id: {playerId}");
		NetPlayerData netPlayerData = session.players.Find((NetPlayerData ps) => ps.id == playerId);
		if (netPlayerData == null)
		{
			UnityEngine.Debug.LogError($"Could not find player socials for player ID {playerId}");
			return;
		}
		bool flag = session.isLocalPlayer(playerId);
		GamePlayerData gamePlayerData = (flag ? localPlayerData : instantiateAndSetupNetPlayer());
		gamePlayerData.playerObject.name = $"Player - {playerId} (isLocal: {flag})";
		gamePlayerData.id = playerId;
		if (!flag)
		{
			gamePlayerData.zoomCursor.GetComponentInChildren<Text>().text = netPlayerData.username;
			gamePlayerData.finishLevelCursor.GetComponentInChildren<Text>().text = netPlayerData.username;
			UnityEngine.Debug.Log("new player id: " + gamePlayerData.id?.ToString() + ", local id: " + session.localPlayerId);
			netPlayers.Add(gamePlayerData);
			if (mpPointerOffscreenIndicator != null)
			{
				Image component = UnityEngine.Object.Instantiate(mpPointerOffscreenIndicator, roomCanvasUI.transform).GetComponent<Image>();
				Text componentInChildren = component.GetComponentInChildren<Text>();
				if (componentInChildren != null)
				{
					componentInChildren.text = netPlayerData.username;
				}
				gamePlayerData.offScreenPingIndicator = component.GetComponent<CanvasGroup>();
				gamePlayerData.offScreenPingIndicator.alpha = 0f;
			}
			gamePlayerData.playerModelVisibility = GamePlayerData.PlayerModelVisibility.WaitingForInitialPlayerPosePacket;
			gamePlayerData.playerObject.SetActive(value: false);
			PineFmod.playOneShotSound("event:/Sound Effects/00 General/Player_Drop_IN");
		}
		else
		{
			gamePlayerData.playerModelVisibility = GamePlayerData.PlayerModelVisibility.PlayerModelVisible;
		}
		gamePlayerData.isPlayingInVR = netPlayerData.isVR;
		VoiceChatPlayerUI voiceChatPlayerUI = UnityEngine.Object.Instantiate(voiceChatPlayerUIPrefab, roomCanvasUI.VoiceChatCanvas);
		voiceChatPlayerUI.canvasGroup.alpha = 0.5f;
		voiceChatPlayerUI.isSpeakingIndicator.enabled = false;
		voiceChatPlayerUI.avatar.texture = netPlayerData.avatar;
		voiceChatPlayerUI.username.text = netPlayerData.username;
		idToVoiceChatPlayerUI[playerId] = voiceChatPlayerUI;
		UnityEngine.Debug.Log($"'{netPlayerData.username}' playing in VR: {netPlayerData.isVR}, on Quest: {netPlayerData.isOculus}");
		if (!isSplitscreen)
		{
			if (session.lobbyType == LobbyType.PhotonPine)
			{
				if (netPlayerData.photonSpeaker != null)
				{
					PineFmodAudioOut<float> pineFmodAudioOut = (PineFmodAudioOut<float>)netPlayerData.photonSpeaker.audioOutput;
					gamePlayerData.voice = pineFmodAudioOut.Channel;
				}
			}
			else if (netPlayerData.steamSpeaker != null)
			{
				gamePlayerData.voice = netPlayerData.steamSpeaker.Channel;
			}
			if (isProximityChatUsed())
			{
				UnityEngine.Debug.Log("Using proximity chat");
				PineFmod.setMode(gamePlayerData.voice, PineFmodAudioOut<float>.DEFAULT_MODE | MODE._3D | MODE._3D_WORLDRELATIVE);
				PineFmod.set3DSpread(gamePlayerData.voice, 20f);
				PineFmod.set3DMinMaxDistance(gamePlayerData.voice, 0.02f, 1000f);
				PineFmod.setVolume(gamePlayerData.voice, 100f);
			}
			else
			{
				UnityEngine.Debug.Log("NOT Using proximity chat");
			}
		}
		if (gamePlayerData.isPlayingInVR)
		{
			CharacterBuild selectedMesh = gamePlayerData.selectedMesh;
			Transform parent = selectedMesh.transform.parent;
			setParent(selectedMesh.vrHead.transform, parent);
			setParent(selectedMesh.vrTorso.transform, parent);
			setParent(selectedMesh.vrTorsoTarget.transform, parent);
		}
		if (session.netMode == NetMode.Host)
		{
			levelReadyHandlePlayerJoin(playerId);
		}
		int num = session.players.FindIndex((NetPlayerData p) => p.id == session.localPlayerId);
		int num2 = session.players.FindIndex((NetPlayerData p) => p.id == playerId);
		bool flag2 = num2 > num;
		UnityEngine.Debug.Log($"Local player index: {num}, new player index: {num2}, has player joined after local player: {flag2}");
		if (num == -1)
		{
			flag2 = false;
		}
		if (levelReadyProcessCompleted && flag2)
		{
			addChatMessageLocal(session.getUsername(playerId), "", ChatMessage.Type.PlayerJoined);
		}
		loadPersistentPlayerData(gamePlayerData);
		if (isHost() && getPlayerCount() == hostDecidingLevelConversionRequiredPlayerCount)
		{
			hostDecidingLevelConversionRequiredPlayerCount = -1;
			optionDialog.hide();
		}
	}

	public void removePlayerFromGame(NetPlayerId playerId)
	{
		if (idToVoiceChatPlayerUI.TryGetValue(playerId, out var value))
		{
			UnityEngine.Object.Destroy(value.gameObject);
			idToVoiceChatPlayerUI.Remove(playerId);
		}
		GamePlayerData gamePlayerData = netPlayers.Find((GamePlayerData player) => player.id == playerId);
		if (gamePlayerData == null)
		{
			UnityEngine.Debug.Log(string.Format("[{0}] Can't remove player (ID: {1}) because player is not in the party.", "removePlayerFromGame", playerId));
			return;
		}
		savePersistentPlayerData(gamePlayerData);
		if (gamePlayerData.isInZoom && gamePlayerData.interactingObjects.Contains(gamePlayerData.zoomItem) && !gamePlayerData.zoomItem.TryGetComponent<Zoomable>(out var _))
		{
			gamePlayerData.inventory.Add(gamePlayerData.zoomItem);
		}
		if (session.netMode == NetMode.Host)
		{
			session.send(new KickPlayerPacket
			{
				playerBeingKicked = playerId
			}, allowSendInMessageResponse: true);
			for (int num = 0; num < gamePlayerData.inventory.Count; num++)
			{
				GameObject gameObject = gamePlayerData.inventory[num];
				if (!(gameObject == null))
				{
					setAuthority(gameObject.gameObject, session.localPlayerId);
					gameObject.transform.position = gamePlayerData.lastTransformPose.position + Vector3.up * num * 0.2f;
				}
			}
			removeSpawnPointFromPlayer(playerId);
			levelReadyHandlePlayerLeave(playerId);
		}
		string username = session.getUsername(playerId);
		if (levelReadyProcessCompleted)
		{
			addChatMessageLocal(username, "", ChatMessage.Type.PlayerLeft);
		}
		if (session.localPlayerId != playerId)
		{
			PineFmod.playOneShotSound("event:/Sound Effects/00 General/Player_Drop_OUT");
		}
		if (session.localPlayerId == playerId)
		{
			if (isProcessingPacket)
			{
				quitToMenu(continueSession: false);
				session.destroy();
			}
			return;
		}
		if (playerId == session.hostPlayerId)
		{
			quitToMenu(continueSession: false);
			return;
		}
		if (isHost())
		{
			for (int num2 = gamePlayerData.inventory.Count - 1; num2 >= 0; num2--)
			{
				GameObject gameObject2 = gamePlayerData.inventory[num2];
				if (!(gameObject2 == null))
				{
					gamePlayerData.inventory.Remove(gameObject2);
					gameObject2.SetActive(value: true);
					bool flag = isProcessingPacket;
					isProcessingPacket = false;
					addItemToInventory(gameObject2.gameObject);
					isProcessingPacket = flag;
				}
			}
		}
		else
		{
			gamePlayerData.inventory.Clear();
		}
		if (gamePlayerData.selectedCharacter != null)
		{
			gamePlayerData.playerObject.gameObject.SetActive(value: false);
		}
		if (gamePlayerData.inHandItemBubble != null)
		{
			UnityEngine.Object.Destroy(gamePlayerData.inHandItemBubble);
		}
		if (gamePlayerData.sharedZoomBubble != null)
		{
			UnityEngine.Object.Destroy(gamePlayerData.sharedZoomBubble);
		}
		int playerCount = getPlayerCount();
		netPlayers.Remove(gamePlayerData);
		UnityEngine.Debug.Log(string.Format("Removed player (ID: {0}) from '{1}', new count is {2}.", playerId, "netPlayers", netPlayers.Count));
		handleLevelConversion(playerCount, username);
	}

	private GamePlayerData instantiateAndSetupNetPlayer()
	{
		GamePlayerData gamePlayerData = new GamePlayerData();
		gamePlayerData.playerObject = UnityEngine.Object.Instantiate(netPlayerMesh);
		gamePlayerData.models = gamePlayerData.playerObject.GetComponentInChildren<CharacterModels>();
		gamePlayerData.maleCharacter = gamePlayerData.models.builds[0];
		gamePlayerData.femaleCharacter = gamePlayerData.models.builds[1];
		gamePlayerData.maleCharacter.outfit = CharacterBuild.Outfit.Dracula;
		gamePlayerData.femaleCharacter.outfit = CharacterBuild.Outfit.Dracula;
		gamePlayerData.maleCharacter.hair = CharacterBuild.Hair.Hair1;
		gamePlayerData.femaleCharacter.hair = CharacterBuild.Hair.Hair1;
		gamePlayerData.maleCharacter.hairColor = 0;
		gamePlayerData.femaleCharacter.hairColor = 0;
		gamePlayerData.maleCharacter.syncCharacter();
		gamePlayerData.femaleCharacter.syncCharacter();
		gamePlayerData.lastKeepAliveTimestamp = Time.time;
		gamePlayerData.sharedZoomBubble = UnityEngine.Object.Instantiate(bubbleTemplate, gamePlayerData.playerObject.transform);
		gamePlayerData.sharedZoomBubble.layer = LayerMask.NameToLayer("Characters");
		gamePlayerData.sharedZoomBubble.SetActive(value: false);
		gamePlayerData.zoomCursor = UnityEngine.Object.Instantiate(netPlayerCursor, Vector3.zero, Quaternion.identity, cursorCanvas.transform);
		gamePlayerData.zoomCursor.transform.localScale = Vector3.one;
		gamePlayerData.zoomCursor.gameObject.SetActive(value: false);
		gamePlayerData.finishLevelCursor = UnityEngine.Object.Instantiate(netPlayerCursor, Vector3.zero, Quaternion.identity, finishLevelUI.SafeAreas_PoseSelection.transform);
		gamePlayerData.finishLevelCursor.transform.localScale = Vector3.one;
		gamePlayerData.finishLevelCursor.gameObject.SetActive(value: false);
		gamePlayerData.ghostData = new List<NetPlayerMaterialData>();
		gamePlayerData.objectsToFade = new List<GameObject>();
		return gamePlayerData;
	}

	private void savePersistentPlayerData(GamePlayerData player)
	{
		PersistentPlayerData persistentPlayerData = persistentPlayers.Find((PersistentPlayerData p) => p.id == player.id);
		if (persistentPlayerData == null)
		{
			persistentPlayerData = new PersistentPlayerData();
			persistentPlayers.Add(persistentPlayerData);
		}
		persistentPlayerData.id = player.id;
		persistentPlayerData.position = player.lastTransformPose.position;
		persistentPlayerData.rotation = player.currentRotation;
		persistentPlayerData.isCrouching = player.lastPlayerCrouch;
		persistentPlayerData.characterPoseContext = player.characterPoseContext;
		persistentPlayerData.ladderData = player.ladderData;
		UnityEngine.Debug.Log($"Saved persistent data for player {session.getUsername(player.id)}:\n{persistentPlayerData}");
	}

	private void loadPersistentPlayerData(GamePlayerData player)
	{
		PersistentPlayerData persistentPlayerData = persistentPlayers.Find((PersistentPlayerData p) => p.id == player.id);
		if (persistentPlayerData == null)
		{
			return;
		}
		player.lastTransformPose.position = persistentPlayerData.position;
		player.currentRotation = persistentPlayerData.rotation;
		player.lastPlayerCrouch = persistentPlayerData.isCrouching;
		player.characterPoseContext = persistentPlayerData.characterPoseContext;
		player.ladderData = persistentPlayerData.ladderData;
		if (player.characterPoseContext.poseState != CharacterPoseState.None)
		{
			if (netPlayers.Any((GamePlayerData otherPlayer) => otherPlayer.id != player.id && otherPlayer.characterPoseContext?.pose == player.characterPoseContext.pose))
			{
				player.characterPoseContext = CharacterPoseContext.None;
			}
			else if (player.characterPoseContext.pose != null)
			{
				UnityEngine.Debug.Log("loadPersistentPlayerData Resetting pose background time.");
				player.characterPoseContext.pose.backgroundTime = 0f;
				player.characterPoseContext.pose.backgroundUpdate = true;
			}
		}
		UnityEngine.Debug.Log($"Loaded persistent data for player {session.getUsername(player.id)}:\n{persistentPlayerData}");
	}

	private void handleLevelConversion(int requiredPlayerCountToContinue, string leavingPlayerUsername)
	{
		if (!isLevelConvertedToSinglePlayer && hostDecidingLevelConversionRequiredPlayerCount == -1 && isHost() && !isCustomLevel() && !isLobby() && UnityUtils.isMethodOverriden(levelLogic.GetType(), "onConvertToSinglePlayer") && !puzzles.All((Puzzle puzzle) => puzzle.type == Puzzle.Type.NotCoop || puzzle.isSolved))
		{
			if (puzzles.Any((Puzzle puzzle) => puzzle.type == Puzzle.Type.CoopAsk && !puzzle.isSolved))
			{
				hostDecidingLevelConversionRequiredPlayerCount = requiredPlayerCountToContinue;
				showSinglePlayerLevelConvertDialog(leavingPlayerUsername);
			}
			else
			{
				convertLevelToSinglePlayer(shouldSync: true);
			}
		}
	}

	private void showSinglePlayerLevelConvertDialog(string leavingPlayerUsername)
	{
		VisualControl visualControl = new VisualControl("convert", ControllerButtonActionType.UIConfirmPrimary, "%Convert%", VisualControl.ControlType.Button, VisualControl.Position.BotCenter);
		VisualControl visualControl2 = new VisualControl("quitToLobby", ControllerButtonActionType.UIBack, "%QuitToLobby%", VisualControl.ControlType.Button, VisualControl.Position.BotCenter);
		optionDialog.showNoTranslate("", Localization.lookupInDictionary("ConvertLevelToSinglePlayerMessage").Replace("[Name]", leavingPlayerUsername.Colored(Color.darkOrange)), delegate(string id)
		{
			hostDecidingLevelConversionRequiredPlayerCount = -1;
			if (id == "convert")
			{
				convertLevelToSinglePlayer(shouldSync: true);
			}
			else if (id == "quitToLobby")
			{
				quitToMenu(continueSession: true);
			}
		}, visualControl, visualControl2);
	}

	private void convertLevelToSinglePlayer(bool shouldSync)
	{
		if (!isLevelConvertedToSinglePlayer)
		{
			if (shouldSync)
			{
				session.send(new ConvertLevelToSinglePlayerPacket(), allowSendInMessageResponse: true);
			}
			isLevelConvertedToSinglePlayer = true;
			levelLogic.onConvertToSinglePlayer();
		}
	}

	public void showOtherPlayerInventory(NetPlayerId playerId)
	{
		List<GameObject> list = getAllPlayers().Find((GamePlayerData x) => x.id == playerId).inventory;
		if (localPlayerData.id == playerId)
		{
			list = extractItemsFromInventory(inventory);
		}
		currentOtherPlayerInventoryId = playerId;
		otherPlayerInventoryUI.PlayerNameBg_PlayerName.text = session.getUsername(playerId);
		otherPlayerInventoryUI.gameObject.SetActive(value: true);
		foreach (InventoryItem item in currentOtherPlayerInventory)
		{
			UnityEngine.Object.Destroy(item.impostorClone.gameObject);
		}
		currentOtherPlayerInventory.Clear();
		foreach (InventorySlot currentOtherPlayerInventorySlot in currentOtherPlayerInventorySlots)
		{
			UnityEngine.Object.Destroy(currentOtherPlayerInventorySlot.ui.gameObject);
		}
		currentOtherPlayerInventorySlots.Clear();
		createInventorySlot(InventorySource.OtherPlayerInventory);
		foreach (GameObject item2 in list)
		{
			createInventorySlot(InventorySource.OtherPlayerInventory);
			InventoryItem inventoryItem = new InventoryItem
			{
				transitionTime = 1000f,
				transitionPosition = item2.transform.position,
				transitionRotation = item2.transform.rotation,
				transitionScale = item2.transform.lossyScale * (playerCamera.fieldOfView / defaultFOV)
			};
			inventoryItem.scenePosition = item2.transform.position;
			inventoryItem.sceneRotation = item2.transform.rotation;
			inventoryItem.sceneLocalScale = item2.transform.localScale;
			inventoryItem.localBounds = computeLocalBounds(item2.gameObject);
			inventoryItem.gameObjects.Add(item2.gameObject);
			inventoryItem.localBoundsCollection.Add(inventoryItem.localBounds);
			inventoryItem.impostorClone = createInventoryImpostor(item2.gameObject);
			inventoryItem.impostorClone.gameObject.SetActive(value: false);
			inventoryItem.transitionPosition = inventoryItem.impostorClone.transform.localPosition;
			inventoryItem.transitionRotation = inventoryItem.impostorClone.transform.localRotation;
			inventoryItem.transitionScale = inventoryItem.impostorClone.transform.localScale;
			currentOtherPlayerInventory.Add(inventoryItem);
		}
		activateCenterScreenCanvas(activate: true, currentOtherPlayerInventory, currentOtherPlayerInventorySlots, otherPlayerInventoryUI.Container_Empty.gameObject, otherPlayerInventoryUI.root.GetComponent<RectTransform>());
	}

	public void hideOtherPlayerInventory()
	{
		otherPlayerInventoryUI.gameObject.SetActive(value: false);
	}

	public void updatePreviewPlayer()
	{
		otherPlayerPreviewUI.root.alpha = Mathf.MoveTowards(otherPlayerPreviewUI.root.alpha, (previewPlayerId != null) ? 1f : 0f, Time.deltaTime * 10f);
		if (!(previewPlayerId != currentPreviewPlayerId))
		{
			return;
		}
		foreach (InventoryItem item in previewPlayerInventory)
		{
			UnityEngine.Object.Destroy(item.impostorClone.gameObject);
		}
		previewPlayerInventory.Clear();
		foreach (InventorySlot previewPlayerSlot in previewPlayerSlots)
		{
			UnityEngine.Object.Destroy(previewPlayerSlot.ui.gameObject);
		}
		previewPlayerSlots.Clear();
		createInventorySlot(InventorySource.OtherPlayerPreview);
		if (previewPlayerId != null)
		{
			GamePlayerData gamePlayerData = getAllPlayers().Find((GamePlayerData x) => x.id == previewPlayerId);
			otherPlayerPreviewUI.Container_Top_PlayerName.text = session.getUsername(gamePlayerData.id);
			List<GameObject> list = gamePlayerData.inventory;
			if (gamePlayerData == localPlayerData)
			{
				list = extractItemsFromInventory(inventory);
			}
			int num = 0;
			int num2 = 0;
			foreach (GameObject item2 in list)
			{
				Item component = item2.GetComponent<Item>();
				if (component.itemType == ItemType.Key)
				{
					num++;
				}
				if (component.itemType == ItemType.Clue)
				{
					num2++;
				}
			}
			otherPlayerPreviewUI.Container_Top_Info_KeyAmount.text = num.ToString();
			otherPlayerPreviewUI.Container_Top_Info_HintAmount.text = num2.ToString();
			otherPlayerPreviewUI.Container_Empty.gameObject.SetActive(list.Count == 0);
			otherPlayerPreviewUI.Container_EmptyTxt.gameObject.SetActive(list.Count == 0);
			for (int num3 = 0; num3 < list.Count; num3++)
			{
				GameObject gameObject = list[num3];
				createInventorySlot(InventorySource.OtherPlayerPreview);
				InventoryItem inventoryItem = new InventoryItem
				{
					transitionTime = 1000f,
					transitionPosition = gameObject.transform.position,
					transitionRotation = gameObject.transform.rotation,
					transitionScale = gameObject.transform.lossyScale * (playerCamera.fieldOfView / defaultFOV)
				};
				previewPlayerSlots[num3 + 1].ui.gameObject.SetActive(value: true);
				inventoryItem.scenePosition = gameObject.transform.position;
				inventoryItem.sceneRotation = gameObject.transform.rotation;
				inventoryItem.sceneLocalScale = gameObject.transform.localScale;
				inventoryItem.localBounds = computeLocalBounds(gameObject.gameObject);
				inventoryItem.gameObjects.Add(gameObject.gameObject);
