			isInZoomMode = isZoomedWithController;
		}
		else
		{
			isInZoomMode = pc.mouseMiddle;
		}
	}

	private void updateCursorVisibility()
	{
		bool flag = false;
		if (Controller.isActive())
		{
			topZoomContextSafe(out var context);
			bool flag2 = false;
			bool flag3 = gameInputDispatcher.get(ControllerButtonActionType.GameHoldInteract, ControllerButtonActionType.UIConfirmSecondary);
			if (context != null)
			{
				flag2 = pointers.Count > 0 && !isZoomedWithController && flag3;
			}
			flag = cursorVisible.current == CursorVisibleState.VirtualVisible && controllerInteractionData == null && !flag2 && pcVirtualCursor.sprite != null;
			if (lastFrameCursorVisible != flag || Controller.controllerModeChanged || forceSyncCursorVisible)
			{
				pcVirtualCursor.gameObject.SetActive(flag);
			}
			Cursor.visible = false;
		}
		else
		{
			flag = cursorVisible.current == CursorVisibleState.Visible || cursorVisible.current == CursorVisibleState.VirtualVisible;
			if (lastFrameCursorVisible != flag || Controller.controllerModeChanged || forceSyncCursorVisible)
			{
				Cursor.visible = flag;
			}
			pcVirtualCursor.gameObject.SetActive(value: false);
		}
		if (cursorVisible.current == CursorVisibleState.Hidden || Controller.isActive())
		{
			Cursor.lockState = CursorLockMode.Locked;
		}
		else
		{
			Cursor.lockState = CursorLockMode.None;
		}
		if (hoverActionsObject != null)
		{
			hoverActionsObject.fade.alpha = Mathf.MoveTowards(hoverActionsObject.fade.alpha, 1f, Time.deltaTime * 10f);
		}
		for (int num = fadeOutActions.Count - 1; num >= 0; num--)
		{
			HoverActions hoverActions = fadeOutActions[num];
			hoverActions.fade.alpha = Mathf.MoveTowards(hoverActions.fade.alpha, 0f, Time.deltaTime * 10f);
			if (hoverActions.fade.alpha == 0f)
			{
				fadeOutActions.Remove(hoverActions);
				UnityEngine.Object.Destroy(hoverActions.gameObject);
			}
		}
		lastFrameCursorVisible = flag;
	}

	private bool selectItemKeyboard()
	{
		if (pcSelectedItem != -1 && inventory[pcSelectedItem].topGameObject().TryGetComponent<Item>(out var component) && component.backgroundUpdate)
		{
			return false;
		}
		if (carryingItem != null)
		{
			return false;
		}
		if (isDraggingAnyTypeOnAnyPointer())
		{
			return false;
		}
		if (topZoomContextSafe(out var context))
		{
			if (isAnySlotInProgress(context.selected))
			{
				return false;
			}
			if (context.selectedType == ScreenTargetType.NPC)
			{
				return false;
			}
		}
		if (Controller.isActive())
		{
			if (gameInputDispatcher.getDown(ControllerButtonActionType.GameInventoryRight))
			{
				int selection = -1;
				if (pcSelectedItem < inventory.Count - 1)
				{
					selection = pcSelectedItem + 1;
				}
				pcChangeItemSelectionIndex(selection);
				return true;
			}
			if (gameInputDispatcher.getDown(ControllerButtonActionType.GameInventoryLeft))
			{
				int selection2 = inventory.Count - 1;
				if (pcSelectedItem >= 0)
				{
					selection2 = pcSelectedItem - 1;
				}
				pcChangeItemSelectionIndex(selection2);
				return true;
			}
		}
		else
		{
			for (int i = 0; i < Mathf.Min(inventory.Count, 9); i++)
			{
				if (Input.GetKeyDown((KeyCode)(49 + i)))
				{
					pcChangeItemSelectionIndex((pcSelectedItem == i) ? (-1) : i);
					return true;
				}
			}
		}
		return false;
	}

	public Vector3 getMovement()
	{
		Vector3 zero = Vector3.zero;
		if (Controller.isActive())
		{
			zero = getControllerMove(canInvert: false);
		}
		else
		{
			Vector3 zero2 = Vector3.zero;
			zero2.x = (menuOptions.getActionKey(KeyBindingAction.Left) ? (-1) : 0) + (menuOptions.getActionKey(KeyBindingAction.Right) ? 1 : 0);
			zero2.y = (menuOptions.getActionKey(KeyBindingAction.Down) ? (-1) : 0) + (menuOptions.getActionKey(KeyBindingAction.Up) ? 1 : 0);
			zero = zero2;
		}
		float magnitude = zero.magnitude;
		if (magnitude > 1f)
		{
			zero *= 1f / magnitude;
		}
		return zero;
	}

	private void handlePCEmote(PCControlContext pc)
	{
		pcCrosshair.gameObject.SetActive(!isEmoteWheelOpen);
		if (!initedEmoteWheel)
		{
			for (int i = 0; i < EmoteValues.all.Length; i++)
			{
				EmoteValues.EmoteValue emote = EmoteValues.all[i];
				EmotePickUI center_EmotePick = emotesPicker.Center_EmotePick;
				EmotePickUI emotePickUI = UnityEngine.Object.Instantiate(center_EmotePick, center_EmotePick.transform.parent);
				emotePickUI.Arc.sprite = emoteUIPiece[EmoteValues.all.Length - 2];
				emotePickUI.name = emote.name;
				emotePickUI.name = "%emote" + emote.name + "%";
				emotePickUI.data = emote;
				emotePickUI.Icon.sprite = emoteIcons.Find((EmoteIcon x) => x.name == emote.name).icon;
				emotePickUI.gameObject.SetActive(value: true);
				float num = (float)i * (360f / (float)EmoteValues.all.Length);
				emotePickUI.transform.localRotation = Quaternion.Euler(0f, 0f, num);
				emotePickUI.Icon.transform.localRotation = Quaternion.Euler(0f, 0f, 0f - num);
				emotePickerItems.Add(emotePickUI);
			}
			initedEmoteWheel = true;
		}
		if (pc.modifierAltDown)
		{
			emoteDownTimestamp = Time.time;
			isEmoteWheelOpen = false;
			lastFrameClosestEmote = null;
		}
		if (pc.modifierAlt && Time.time - emoteDownTimestamp > 0.5f)
		{
			emotesPicker.gameObject.SetActive(value: true);
			isEmoteWheelOpen = true;
			if (Controller.isActive())
			{
				Vector2 axis = Controller.getAxis(ControllerAxisActionType.GameLook);
				float num2 = Mathf.Atan2(axis.y, axis.x) * 57.29578f;
				emotesPicker.Center_Arrow.transform.localRotation = Quaternion.Euler(0f, 0f, num2 - 90f);
			}
			else
			{
				Vector2 vector = new Vector2(Input.GetAxis("Mouse X"), Input.GetAxis("Mouse Y"));
				if (vector.magnitude > 0.01f)
				{
					float num3 = Mathf.Atan2(vector.y, vector.x) * 57.29578f;
					emotesPicker.Center_Arrow.transform.localRotation = Quaternion.Lerp(emotesPicker.Center_Arrow.transform.localRotation, Quaternion.Euler(0f, 0f, num3 - 90f), Time.deltaTime * 10f);
				}
			}
			EmotePickUI emotePickUI2 = getClosestEmote();
			if (lastFrameClosestEmote != emotePickUI2)
			{
				EmoteValues.EmoteValue emoteValue = (EmoteValues.EmoteValue)emotePickUI2.data;
				emotesPicker.Center_ItemName.text = Localization.lookupInDictionary("emote" + emoteValue.name);
				lastFrameClosestEmote = emotePickUI2;
			}
			foreach (EmotePickUI emotePickerItem in emotePickerItems)
			{
				bool flag = emotePickerItem == emotePickUI2;
				Vector3 target = Vector3.one * (flag ? 1.1f : 1f);
				emotePickerItem.transform.localScale = Vector3.MoveTowards(emotePickerItem.transform.localScale, target, Time.deltaTime * 5f);
				Color color = emotePickerItem.Arc.color;
				float? a = (flag ? 0.5f : 0.1f);
				Color b = color.With(null, null, null, a);
				emotePickerItem.Arc.color = Color.Lerp(emotePickerItem.Arc.color, b, Time.deltaTime * 10f);
			}
		}
		if (pc.modifierAltUp)
		{
			if (isEmoteWheelOpen)
			{
				EmoteValues.EmoteValue emoteValue2 = (EmoteValues.EmoteValue)getClosestEmote().data;
				this.emote(localPlayerData, emoteValue2.value, displayText: true);
				session.send(new EmotePacket
				{
					emoteValue = emoteValue2.value
				});
			}
			else
			{
				sendLocationPing();
			}
			emotesPicker.gameObject.SetActive(value: false);
			isEmoteWheelOpen = false;
		}
		EmotePickUI getClosestEmote()
		{
			EmotePickUI result = emotePickerItems[0];
			float num4 = float.MaxValue;
			foreach (EmotePickUI emotePickerItem2 in emotePickerItems)
			{
				float num5 = Quaternion.Angle(emotePickerItem2.transform.localRotation, emotesPicker.Center_Arrow.transform.localRotation);
				if (num5 < num4)
				{
					num4 = num5;
					result = emotePickerItem2;
				}
			}
			return result;
		}
	}

	public void invalidateItemImpostors(Item item)
	{
		PinnedItemInfo pinnedItemInfo = pinnedItems.Find((PinnedItemInfo x) => x.originalItem == item);
		if (pinnedItemInfo != null)
		{
			ImpostorClone componentInChildren = pinnedItemInfo.impostor.GetComponentInChildren<ImpostorClone>();
			if (componentInChildren != null)
			{
				componentInChildren.invalidated = true;
			}
		}
		InventoryItem inventoryItem = inventory.Find((InventoryItem x) => x.gameObjects.Contains(item.gameObject));
		if (inventoryItem != null && inventoryItem.impostorClone != null)
		{
			inventoryItem.impostorClone.invalidated = true;
		}
		if (pcSelectedItemImpostors != null && pcSelectedItemImpostors.Length >= 2 && pcSelectedItemImpostors[0].TryGetComponent<ImpostorClone>(out var component) && pcSelectedItemImpostors[1].TryGetComponent<ImpostorClone>(out var component2))
		{
			component.invalidated = true;
			component2.invalidated = true;
		}
		syncPinnedDepths();
	}

