			pcSelectedItemImpostors[1] = ImpostorClone.create(impostorContext, gameObject, LayerMask.NameToLayer("Default"), strip: true, onMotionPunchChange, "", ImpostorClone.StrippingFlags.None);
			ImpostorClone.replaceMaterialsKinds(pcSelectedItemImpostors[1], clearDepthAndMotion, clearDepthAndMotionAlphaTest, ignoreDepthAndMotion);
			onMotionPunchChange(pcSelectedItemImpostors[1].GetComponent<ImpostorClone>());
			for (int j = 0; j < pcSelectedItemImpostors.Length; j++)
			{
				setParent(pcSelectedItemImpostors[j].transform, levelContainerTransform);
				pcSelectedItemImpostors[j].name = "Item Clone";
				pcSelectedItemImpostors[j].transform.position = inventoryItem.scenePosition;
				pcSelectedItemImpostors[j].transform.rotation = inventoryItem.sceneRotation;
				pcSelectedItemImpostors[j].transform.localScale = inventoryItem.sceneLocalScale;
				setParent(pcSelectedItemImpostors[j].transform, playerCamera.transform);
			}
			shouldItemImpostortBeVisible = true;
