			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive((gameState.current != GameState.Zoom && !(toolZoomObject != null)) ? true : false);
			}
			shouldItemScreenSpaceBeVisible = false;
			shouldItemImpostortBeVisible = false;
			getObjectUnderViewportPosition(new Vector2(0.5f, 0.5f), out var pointer);
			pcSelectedItemGhost = ImpostorClone.create(impostorContext, gameObject, LayerMask.NameToLayer("PlacingGhost"), strip: true, null, "DisableGhost", ImpostorClone.StrippingFlags.None, automaticSync: false, "EnableGhost");
			pcSelectedItemGhost.SetActive(value: false);
			Canvas[] componentsInChildren = pcSelectedItemGhost.GetComponentsInChildren<Canvas>(includeInactive: true);
			for (int num = componentsInChildren.Length - 1; num >= 0; num--)
