		static void onMotionPunchChange(ImpostorClone clone)
		{
			Renderer[] componentsInChildren2 = clone.GetComponentsInChildren<Renderer>(includeInactive: true);
			for (int k = 0; k < componentsInChildren2.Length; k++)
			{
				componentsInChildren2[k].shadowCastingMode = ShadowCastingMode.Off;
			}
		}
		static void setupTransparentZoom(Transform clone)
		{
			if (!(clone == null))
			{
				Transform[] componentsInChildren2 = clone.GetComponentsInChildren<Transform>(includeInactive: true);
				foreach (Transform transform in componentsInChildren2)
				{
					if (transform.gameObject.CompareTag("ExamineTransparentEffect"))
					{
						transform.gameObject.layer = LayerMask.NameToLayer("ZoomTransparent");
					}
					if (transform.gameObject.TryGetComponent<Renderer>(out var component3))
					{
						component3.shadowCastingMode = ShadowCastingMode.Off;
					}
				}
			}
		}
		static void setupTransparentZoomAction(ImpostorClone clone)
		{
			if (clone != null)
			{
				setupTransparentZoom(clone.transform);
			}
		}
	}

	private void handlePCZoomMode(PCControlContext pc)
	{
		if (!topZoomContextSafe(out var zoomContext))
		{
			return;
		}
		if (Controller.isActive())
		{
			if (pc.mouseMiddleUp)
			{
				isZoomedWithController = !isZoomedWithController;
			}
			if (isZoomedWithController)
			{
				zoomContext.additionalZoom = Mathf.MoveTowards(zoomContext.additionalZoom, 0.7f, Time.deltaTime * 3f);
				zoomContext.positionOffset += Controller.getAxis(ControllerAxisActionType.UIMoveAndRotate) * Time.deltaTime;
				zoomContext.positionOffset = new Vector2(Mathf.Clamp(zoomContext.positionOffset.x, -0.5f, 0.5f), Mathf.Clamp(zoomContext.positionOffset.y, -0.5f, 0.5f));
			}
			else
			{
				zoomContext.additionalZoom = Mathf.MoveTowards(zoomContext.additionalZoom, 0f, Time.deltaTime * 5f);
			}
		}
		else if (pc.mouseMiddle)
		{
			zoomContext.additionalZoom = Mathf.MoveTowards(zoomContext.additionalZoom, 0.7f, Time.deltaTime * 3f);
			zoomContext.positionOffset = -(Vector2.one * 0.5f - getMousePositionViewport());
		}
		else
		{
			zoomContext.additionalZoom = Mathf.MoveTowards(zoomContext.additionalZoom, 0f, Time.deltaTime * 5f);
		}
		zoomContext.additionalZoom = Mathf.Clamp(zoomContext.additionalZoom, -0.5f, 1f);
		int num = inventory.FindIndex((InventoryItem x) => x.gameObjects.Contains(zoomContext.selected));
		int num2 = -2;
		for (int num3 = 0; num3 < Mathf.Min(inventory.Count, 9); num3++)
		{
			if (Input.GetKeyDown((KeyCode)(49 + num3)))
			{
				num2 = num3;
			}
		}
		if (zoomContext.selectedType == ScreenTargetType.SharedZoom)
		{
			pc.cursor = cursorSharedZoom;
		}
		if (toolZoomObject != null && zoomState == ZoomState.Zoom && zoomContext.transitionTime == 1f && zoomContext.toolZoomType == ToolZoomType.Modal)
		{
			Vector3 zero = Vector3.zero;
			Vector2 mousePositionViewport = getMousePositionViewport();
			if (mousePositionViewport.x > 0.99f)
			{
				zero -= Vector3.right;
			}
			if (mousePositionViewport.x < 0.09f)
			{
				zero += Vector3.right;
			}
			if (mousePositionViewport.y > 0.99f)
			{
				zero -= Vector3.up;
			}
			if (mousePositionViewport.y < 0.09f)
			{
				zero += Vector3.up;
			}
			if (zero != Vector3.zero)
			{
				updateCameraRotation(zero * Time.deltaTime * 300f);
			}
		}
		GameObject gameObject = ((pc.pointer.context.target != null) ? pc.pointer.context.target : pc.pointer.context.currentTarget);
		ScreenTargetType screenTargetType = ((pc.pointer.context.target != null) ? pc.pointer.context.targetType : pc.pointer.context.currentTargetType);
		pc.virtualCursorImage = pcCrosshairs[0];
		Interactive component;
		if (gameObject != zoomContext.selected && screenTargetType == ScreenTargetType.Slot)
		{
			pc.cursor = cursorHand;
			pc.virtualCursorImage = pcCrosshairs[4];
		}
		else if (gameObject != null && gameObject.TryGetComponent<Interactive>(out component))
		{
			PCCrosshair pCCrosshair = component.getCursor();
			InteractiveAnnotation currentTargetAnnotation = pc.pointer.context.currentTargetAnnotation;
			if (currentTargetAnnotation != null && currentTargetAnnotation.getOverrideCursor() != PCCrosshair.Default)
			{
				pCCrosshair = currentTargetAnnotation.getOverrideCursor();
			}
			if (pCCrosshair == PCCrosshair.EvaluateInCallback)
			{
				pCCrosshair = evaluateCustomCursor(pc.pointer);
			}
			pc.cursor = default(HardwareCursor);
			pc.cursor.texture = pcCrosshairs[(int)pCCrosshair].texture;
			pc.cursor.hotspot = new Vector2(9f, 3f);
			pc.virtualCursorImage = pcCrosshairs[(int)pCCrosshair];
		}
		getObjectUnderViewportPosition(getMousePositionViewport(), out var pointer);
		if (pointer.context.currentTargetType == ScreenTargetType.ItemInventory)
		{
			int hover = inventory.FindIndex((InventoryItem x) => x.gameObjects.Contains(pointer.context.currentTarget));
			if (!inTrashInventoryFocus && !inSlotInventoryFocus)
			{
				if (!inZoomMode())
				{
					inventoryGridContainer.hover = hover;
				}
			}
			else
			{
				trashInventoryGridContainer.hover = hover;
			}
			pc.cursor = cursorHand;
			pc.virtualCursorImage = pcCrosshairs[10];
			if (pc.pointer.gestureDown)
			{
				if (!inTrashInventoryFocus && !inSlotInventoryFocus)
				{
					inventoryGridContainer.hoverFlash = 0f;
				}
				else
				{
					trashInventoryGridContainer.hoverFlash = 0f;
				}
			}
		}
		else if (pointer.context.currentTargetType == ScreenTargetType.ZoomInventorySlot)
		{
			pc.cursor = cursorHand;
			pc.virtualCursorImage = pcCrosshairs[10];
		}
		inventorySlots.ForEach(delegate(InventorySlot x)
		{
			x.ui.Hover.gameObject.SetActive(value: false);
		});
		inventorySlots.ForEach(delegate(InventorySlot x)
		{
			x.ui.Recenter.gameObject.SetActive(value: false);
		});
		ScreenTargetType currentTargetType = pointer.context.currentTargetType;
		if (currentTargetType == ScreenTargetType.ItemInventory || currentTargetType == ScreenTargetType.ItemInventoryUse)
		{
			int num4 = inventory.FindIndex((InventoryItem x) => x.gameObjects.Contains(pointer.context.currentTarget));
			for (int num5 = 0; num5 < inventorySlots.Count; num5++)
			{
				InventorySlot inventorySlot = inventorySlots[num5];
				bool flag = num5 == num4 + 1;
				bool flag2 = flag && num != num5 - 1 && dragData == null;
				if (flag2 && !inventorySlot.ui.Hover.gameObject.activeInHierarchy)
				{
					setupItemUI(inventorySlot.ui.Hover_StreamlinedUI_StreamlinedtemNameBG, pointer.context.currentTarget, canBeStreamlined: true);
				}
				if (flag2)
				{
					RectTransform component2 = inventorySlot.ui.Hover_StreamlinedUI.GetComponent<RectTransform>();
					if (num5 == 1)
					{
						RectTransform component3 = inventorySlot.ui.Hover_StreamlinedUIAnchoredLeft.GetComponent<RectTransform>();
						component2.anchorMin = component3.anchorMin;
						component2.anchorMax = component3.anchorMax;
						component2.pivot = component3.pivot;
						component2.anchoredPosition = component3.anchoredPosition;
					}
					UnityUtils.visitGameObjectChildFirst(component2.gameObject, delegate(GameObject x)
					{
						if (x.TryGetComponent<HorizontalLayoutGroup>(out var component5))
						{
							component5.CalculateLayoutInputHorizontal();
							component5.CalculateLayoutInputVertical();
						}
						LayoutRebuilder.ForceRebuildLayoutImmediate(x.GetComponent<RectTransform>());
					});
					Canvas.ForceUpdateCanvases();
					if (inventorySlot.shouldHoverBeActiveFrameCount == -1)
					{
						inventorySlot.shouldHoverBeActiveFrameCount = Time.frameCount;
					}
					if (inventorySlot.shouldHoverBeActiveFrameCount + 3 < Time.frameCount)
					{
						inventorySlot.ui.Hover_StreamlinedUI.alpha = 1f;
					}
				}
				else
				{
					inventorySlot.shouldHoverBeActiveFrameCount = -1;
					inventorySlot.ui.Hover_StreamlinedUI.alpha = 0f;
				}
				inventorySlot.ui.Hover.gameObject.SetActive(flag2);
				inventorySlot.ui.Recenter.gameObject.SetActive(!flag2 && flag && examineRotationTarget != Vector2.zero && zoomContext.selectedType != ScreenTargetType.SharedZoom);
			}
		}
		zoomSlotUISelected.SetActive(isInTopZoom(zoomSlotOriginal));
		zoomSlotUIHover.SetActive(pointer.context.currentTargetType == ScreenTargetType.ZoomInventorySlot && !zoomSlotUISelected.activeInHierarchy);
		PointerEventData pointerEventData = new PointerEventData(EventSystem.current);
		pointerEventData.position = getMousePosition();
		List<RaycastResult> list = new List<RaycastResult>();
		EventSystem.current.RaycastAll(pointerEventData, list);
		foreach (RaycastResult item in list)
		{
			Button componentInParent = item.gameObject.GetComponentInParent<Button>();
			if (componentInParent != null && componentInParent.enabled)
			{
				zoomHoverButton = componentInParent;
				pc.cursor = cursorHand;
				pc.virtualCursorImage = pcCrosshairs[10];
				break;
			}
		}
		if (draggingInventoryIndex != -1)
		{
			Vector2 mousePositionViewport2 = getMousePositionViewport();
			Vector3 position = new Vector3(mousePositionViewport2.x - (float)(30 / Screen.width), mousePositionViewport2.y, 0.5f);
			Vector3 position2 = playerCamera.ViewportToWorldPoint(position);
			draggingInventoryImpostors.itemDragImpostorScreen.transform.position = position2;
			if (pointer.context.currentTargetType == ScreenTargetType.Slot && !pointer.context.overUI)
			{
				GameObject gameObject2 = inventory[draggingInventoryIndex].topGameObject();
				Slot component4 = pointer.context.currentTarget.GetComponent<Slot>();
				handlePlaceItemSlotForImpostors(gameObject2, draggingInventoryImpostors, component4);
				if (pc.pointer.gestureUp)
				{
					removeItemFromInventory(gameObject2);
					UnityEngine.Debug.LogError("When does this trigger? If you see this message, contact Jura.");
					activateSlotWithItemLocal(component4, gameObject2.GetComponent<Item>(), SlotPlacement.FromItemDrag);
					draggingInventoryIndex = -1;
					destroyDragImpostors(draggingInventoryImpostors);
				}
			}
			else
			{
				draggingInventoryImpostors.itemDragImpostorScreen.SetActive(value: true);
				draggingInventoryImpostors.itemDragImpostorWorld.SetActive(value: false);
				draggingInventoryImpostors.itemDragImpostorSlot.SetActive(value: false);
				if (pc.mouseLeftDown)
				{
					draggingInventoryIndex = -1;
					destroyDragImpostors(draggingInventoryImpostors);
				}
			}
		}
		if (Controller.isActive())
		{
			if (pc.pointer.gestureUp && pc.pointer.context.currentTargetType == ScreenTargetType.Slot && pc.pointer.context.currentTarget == pc.pointer.context.target && draggingInventoryIndex == -1 && !isInSlotInventoryAnimation && inventory.Count >= 1)
			{
				setupCenterInventory(pc, inventoryGridContainer);
				activateControllerSlotCanvas(activate: true);
			}
			else if (gameInputDispatcher.getDown(ControllerButtonActionType.UIMoveTabRight))
			{
				num2 = -1;
				if (pcSelectedItem < inventory.Count - 1)
				{
					num2 = pcSelectedItem + 1;
				}
			}
			else if (gameInputDispatcher.getDown(ControllerButtonActionType.UIMoveTabLeft))
			{
				num2 = inventory.Count - 1;
				if (pcSelectedItem >= 0)
				{
					num2 = pcSelectedItem - 1;
				}
			}
			if (!inSlotInventoryFocus || !inZoomMode())
			{
				inventoryGridContainer.hover = joystickZoomHoveredInventoryItem;
			}
			if (joystickZoomHoveredInventoryItem != -1)
			{
				if (pc.actionExamine)
				{
					InventoryItem inventoryItem = inventory[joystickZoomHoveredInventoryItem];
					if (zoomContext.selected != inventoryItem.topGameObject())
					{
						joystickZoomHoveredInventoryItem = -1;
						if (draggingInventoryIndex != -1)
						{
							draggingInventoryIndex = -1;
							destroyDragImpostors(draggingInventoryImpostors);
						}
						handleZoomEnter(inventoryItem.topGameObject(), ScreenTargetType.ItemInventory);
					}
				}
				else if (pc.actionModalDrag)
				{
					startZoomItemModalDrag(joystickZoomHoveredInventoryItem);
				}
			}
			if (pc.mouseLeftUp && zoomHoverButton != null)
			{
				zoomHoverButton.onClick.Invoke();
			}
		}
		if (Controller.controllerModeChanged)
		{
			if (!Controller.isActive())
			{
				if (draggingInventoryIndex != -1)
				{
					draggingInventoryIndex = -1;
					destroyDragImpostors(draggingInventoryImpostors);
				}
			}
			else if (joystickZoomHoveredInventoryItem != -1)
			{
				startZoomItemModalDrag(joystickZoomHoveredInventoryItem);
			}
		}
		if (num2 == -1)
		{
			if (!checkTopZoomType(ScreenTargetType.Zoomable) && !checkTopZoomType(ScreenTargetType.Item))
			{
				handleZoomLeave();
				PineFmod.playOneShotSound("event:/SFX/GENERAL/uiClick");
			}
			session.send(new ExamineItemPacket
			{
				examinedItem = zoomSlotOriginal,
				isEnteringExamineMode = true,
				cameraPosition = playerCamera.gameObject.transform.position,
				cameraRotation = playerCamera.gameObject.transform.rotation
			}, allowSendInMessageResponse: true);
		}
		if (num != num2 && num2 > -1)
		{
			bool flag3 = !isAnySlotInProgress(zoomContext.selected);
			if (zoomContext.selectedType == ScreenTargetType.NPC)
			{
				flag3 = false;
			}
			if (zoomState == ZoomState.Zoom && gameState.time < 0.75f)
			{
				flag3 = false;
			}
			if (flag3)
			{
				if (zoomContext.selectedType != ScreenTargetType.Zoomable && zoomContext.selectedType != ScreenTargetType.Item)
				{
					handleZoomLeave();
				}
				pcChangeItemSelectionIndex(num2);
				handleZoomEnter(inventory[num2].topGameObject(), ScreenTargetType.ItemInventory);
			}
		}
		else if (pc.mouseRightDown)
		{
			if (cursorOverInventorySlot(pointer.gesturePositionViewport, InventorySource.Inventory) != -1)
			{
				if (zoomContext.selected != pointer.context.target)
				{
					handleItemDragStart(pointer);
				}
			}
			else if (draggingInventoryIndex != -1)
			{
				draggingInventoryIndex = -1;
				UnityEngine.Object.Destroy(draggingInventoryImpostors.itemDragImpostorScreen);
				UnityEngine.Object.Destroy(draggingInventoryImpostors.itemDragImpostorSlot);
				UnityEngine.Object.Destroy(draggingInventoryImpostors.itemDragImpostorWorld);
				dragSlots.Clear();
			}
			else if (pc.pointer.context.currentTargetType == ScreenTargetType.PinnedItem)
			{
				PinnedItemInfo pinnedItemInfo = pinnedItems.Find((PinnedItemInfo x) => x.impostor == pc.pointer.context.currentTarget);
				if (isInTopZoom(pinnedItemInfo.originalItem))
				{
					unpinItemInExamine();
				}
				else
				{
					handleUnpinItem(pinnedItemInfo.originalItem, setItemInWorld: false);
				}
			}
			else if (lobbyZoomablesWithFrame.Find((Zoomable x) => x.gameObject == zoomContext.selected) == null)
			{
				handleZoomLeave();
			}
		}
		if (!pc.mouseLeftHold && toolZoomObject != null && zoomState == ZoomState.Zoom && zoomContext.transitionTime == 1f && zoomContext.toolZoomType == ToolZoomType.Hold)
		{
			handleZoomLeave();
		}
		if (gameInputDispatcher.getDown(KeyBindingAction.Down) && zoomContexts.Count > 0 && (zoomContexts[0].selectedType == ScreenTargetType.Zoomable || zoomContexts[0].selectedType == ScreenTargetType.NPC) && lobbyZoomablesWithFrame.Find((Zoomable x) => x.gameObject == zoomContexts[0].selected) == null)
		{
			handleZoomLeave();
		}
	}

	private void handlePCMenu(PCControlContext pc)
	{
		if (Controller.isActive())
		{
			if (!menuOptions.gameObject.activeInHierarchy && mainMenu.activeInHierarchy && (walkthrough == null || !walkthrough.isActive()) && !optionDialog.gameObject.activeSelf && (lobbyMenu == null || !lobbyMenu.inCoverScreen) && pc.mouseRightDown)
			{
				closeMainMenu();
			}
			if (Controller.controllerModeChanged)
			{
				_ = mainMenu.activeInHierarchy;
			}
		}
		if (pc.actionEscape)
		{
			onPressEscapeInMenu();
		}
		else if (pc.actionHostOptions && !mainMenu.activeSelf)
		{
			closeHostOptions();
		}
		else if (isRebindingEnterKeyOpen && Input.anyKeyDown)
		{
			KeyCode anyKeyDown = menuOptions.getAnyKeyDown();
			if (anyKeyDown != KeyCode.None && anyKeyDown != KeyCode.Escape)
			{
				menuOptions.resetIfKeybindingExists(menuOptions.currentKeyBindingActionToSet, anyKeyDown, false);
				menuOptions.keyBindingsSetKey(anyKeyDown);
				closeRebindingEnterKey();
			}
		}
		else if (pc.actionOpenWalkthrough && walkthrough.isActive())
		{
			closeWalkthrough();
		}
	}

	private void onPressEscapeInMenu()
	{
		if (optionDialog.gameObject.activeSelf)
		{
			optionDialog.hide();
		}
		else if (isChatOpen)
		{
			closeChat();
		}
		if (!menuOptions.gameObject.activeSelf && !isLobby())
		{
			walkthrough?.deactivate();
			closeMainMenu();
		}
	}

	public static bool isViewBlocked(Camera camera, int layers, ref float distance)
	{
		if (Physics.Raycast(camera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f)), out var hitInfo, 0.5f, layers, QueryTriggerInteraction.Ignore) && hitInfo.distance < distance)
		{
			distance = hitInfo.distance;
			return true;
		}
		return false;
	}

	private void performItemDrop(GameObject itemObject)
	{
		Item component = itemObject.GetComponent<Item>();
		if (component.backgroundUpdate)
		{
			return;
		}
		if (getItemState(component) == ItemState.SlotAnimation)
		{
			UnityEngine.Debug.Log("Trying to remove an item that is borrowed. This is not allowed");
			return;
		}
		float distance = ((gameState.current == GameState.Zoom) ? 0.001f : 0.5f);
		int layers = -5 & ~LayerMask.GetMask("IgnoreTrigger", "Teleportation", "VRHands");
		isViewBlocked(playerCamera, layers, ref distance);
		Vector3 vector = playerCamera.ViewportToWorldPoint(new Vector3(0.5f, 0.5f, distance));
		if (pcSelectedItemGhost != null && Vector3.Distance(pcSelectedItemGhost.transform.position, vector) < distance)
		{
			vector = pcSelectedItemGhost.transform.position;
			itemObject.transform.rotation = pcSelectedItemGhost.transform.rotation;
		}
		int num = ((pcSelectedItem != -1 && inventory[pcSelectedItem].gameObjects.Count > 1) ? pcSelectedItem : (-1));
		if (carryingItem?.gameObject != itemObject)
		{
			removeItemFromInventory(itemObject);
		}
		else
		{
			dropCarriableItem(component);
		}
		itemObject.transform.position = vector;
		if (num != -1)
		{
			pcChangeItemSelectionIndex(num, 1f, 0f, playSound: true, forceChangeSelection: true);
		}
		if (!achievementsEnabled)
		{
			return;
		}
		for (int i = 0; i < dropInTimeCount.Count; i++)
		{
			dropInTimeCount[i]++;
			int num2 = 10;
			if (dropInTimeCount[i] >= num2)
			{
				saveAchievement("ACHIEVEMENT_POCKETS_WITH_HOLES");
			}
		}
		DroppedTimers.Add(0f);
		dropInTimeCount.Add(1);
	}

	private void performItemThrow(GameObject itemObject)
	{
		performItemDrop(itemObject);
		Vector3 direction = playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f)).direction;
		Item component = itemObject.GetComponent<Item>();
		component.rbOverrides = new RigidbodyOverrides();
		component.rbOverrides.addForce = (direction + Vector3.up * 0.1f).normalized * 4f * component.mass;
		component.rbOverrides.addForceMode = ForceMode.Impulse;
		component.rbOverrides.addTorque = UnityEngine.Random.onUnitSphere * 0.01f;
		saveAchievement("ACHIEVEMENT_GOOD_THROW");
	}

	private void handleFocusMode(PCControlContext pc)
	{
		List<InventoryItem> list = null;
		if (inTrashInventoryFocus)
		{
			list = trashInventory;
		}
		else if (inSlotInventoryFocus)
		{
			list = inventory;
		}
		else if (inOtherPlayerInventoryFocus)
		{
			list = currentOtherPlayerInventory;
		}
		GridContainer gridContainer = null;
		if (inTrashInventoryFocus)
		{
			gridContainer = trashInventoryGridContainer;
		}
		else if (inSlotInventoryFocus)
		{
			gridContainer = inventoryGridContainer;
		}
		else if (inOtherPlayerInventoryFocus)
		{
			gridContainer = otherPlayerInventoryUI.Container;
		}
		cursorVisible.changeState(CursorVisibleState.Visible);
		pcCrosshair.gameObject.SetActive(value: false);
		gridContainer.columns = Mathf.CeilToInt(Mathf.Sqrt((inSlotInventoryFocus && slotFocusZoomedItemIndex != -1) ? (list.Count - 1) : list.Count));
		if (!inZoomMode())
		{
			setPCHoverActions("HoverAction_Select", "HoverAction_Close", "");
		}
		getObjectUnderViewportPosition(getMousePositionViewport(inSlotInventoryFocus), out var pointer);
		bool flag = false;
		if (pointer.context.currentTargetType == ScreenTargetType.ItemInventory)
		{
			GameObject itemObject = pointer.context.currentTarget;
			int index = (gridContainer.hover = list.FindIndex((InventoryItem inventoryItem2) => inventoryItem2.gameObjects.Contains(itemObject)));
			if (!inOtherPlayerInventoryFocus)
			{
				if (!pc.pointer.hover && !inTrashInventoryFocus && !inSlotInventoryFocus && (pc.pointer.gestureLongPress || pc.pointer.gestureMoved))
				{
					exitFocusMode();
					handleItemDragStart(pc.pointer, itemObject);
					flag = true;
				}
				if (!inTrashInventoryFocus && !inSlotInventoryFocus && (pc.actionExamine || pc.actionOpenInventory))
				{
					exitFocusMode();
					flag = true;
					handleZoomEnter(list[index].topGameObject(), ScreenTargetType.ItemInventory);
				}
				if (!inTrashInventoryFocus && !inSlotInventoryFocus && pc.mouseMiddleUp)
				{
					performItemDrop(itemObject);
					if (list.Count == 0)
					{
						exitFocusMode();
						flag = true;
					}
				}
			}
			pc.cursor = cursorHand;
			pc.virtualCursorImage = pcCrosshairs[10];
		}
		else
		{
			if (!Controller.isActive())
			{
				gridContainer.hover = -1;
			}
			if (!inTrashInventoryFocus && inSlotInventoryFocus)
			{
				setupItemUI(zoomItemUI, pc.pointer.context.currentTarget, canBeStreamlined: false);
			}
			else
			{
				setupItemUI(zoomItemUI, null, canBeStreamlined: false);
			}
		}
		GameObject transitionClone;
		if (!inTrashInventoryFocus && !inSlotInventoryFocus && !inOtherPlayerInventoryFocus && pc.pointer.gestureUp)
		{
			if (pointer.context.currentTargetType == ScreenTargetType.ItemInventory)
			{
				pcChangeItemSelection(pointer.context.currentTarget);
			}
			else
			{
				pcChangeItemSelectionIndex(-1);
			}
			exitFocusMode();
			flag = true;
		}
		else if (inTrashInventoryFocus || inSlotInventoryFocus || inOtherPlayerInventoryFocus)
		{
			if (Controller.isActive())
			{
				Vector3 vector = getControllerMove();
				if (vector == Vector3.zero)
				{
					Vector2 vector2 = -getControllerLook(canInvert: false);
					vector = new Vector3(vector2.x, 0f, vector2.y);
				}
				if (joystickTrashMoveCD <= 0f)
				{
					int num = gridContainer.hover;
					if ((double)vector.x > 0.5)
					{
						num++;
					}
					if ((double)vector.x < -0.5)
					{
						num--;
					}
					if ((double)vector.z < -0.5)
					{
						num += gridContainer.columns;
					}
					if ((double)vector.z > 0.5)
					{
						num -= gridContainer.columns;
					}
					num = Mathf.Clamp(num, 0, list.Count);
					if (num != gridContainer.hover)
					{
						joystickTrashMoveCD = 0.3f;
						gridContainer.hover = num;
					}
				}
				else
				{
					joystickTrashMoveCD -= Time.deltaTime;
					if (vector == Vector3.zero)
					{
						joystickTrashMoveCD = 0f;
					}
				}
				if (pc.pointer.gestureUp)
				{
					if (inTrashInventoryFocus && !inSlotInventoryFocus && trashInventoryGridContainer.hover != -1 && trashInventoryGridContainer.hover < trashInventory.Count)
					{
						takeItemFromTrash(trashInventory[trashInventoryGridContainer.hover].topGameObject(), ScreenTargetType.ItemInventory);
					}
					int slotFocusItemIndex = getSlotFocusItemIndex(inventoryGridContainer.hover);
					if (inSlotInventoryFocus && inventoryGridContainer.hover != -1 && slotFocusItemIndex < inventory.Count)
					{
						InventoryItem inventoryItem = inventory[slotFocusItemIndex];
						GameObject gameObject = inventoryItem.topGameObject();
						Item component = gameObject.GetComponent<Item>();
						Slot component2 = pointer.context.target.GetComponent<Slot>();
						if (component2 != null && canBePlacedInSlot(component2, component))
						{
							Slot slot = component2;
							exitFocusMode();
							removeItemFromInventory(gameObject);
							activateSlotWithItemLocal(slot, component, SlotPlacement.FromItemDrag);
						}
						else
						{
							transitionClone = ImpostorClone.create(impostorContext, gameObject, LayerMask.NameToLayer("UI"));
							Bounds localBounds = inventoryItem.localBounds;
							setParent(transitionClone.transform, playerCamera.transform);
							transitionClone.transform.localScale = inventoryItem.impostorClone.transform.localScale;
							transitionClone.transform.rotation = inventoryItem.impostorClone.transform.rotation;
							transitionClone.transform.position = inventoryItem.impostorClone.transform.position;
							Vector3 position = transitionClone.transform.localPosition;
							bool startedInZoom = inZoomMode();
							if (startedInZoom && component2 != null)
							{
								Vector3 position2 = playerCamera.WorldToScreenPoint(component2.transform.position);
								position2.z = Vector3.Distance(transitionClone.transform.position, playerCamera.transform.position);
								Vector3 position3 = playerCamera.ScreenToWorldPoint(position2);
								Vector3 vector3 = playerCamera.transform.InverseTransformPoint(position3);
								position.x = vector3.x;
								position.y = vector3.y;
							}
							else
							{
								position.x = 0f;
								position.y = 0f;
							}
							Vector3 pivotOffsetLocal = Vector3.Scale(transitionClone.transform.localScale, transitionClone.transform.localRotation * localBounds.center);
							Vector3 value = position - pivotOffsetLocal;
							isInSlotInventoryAnimation = true;
							UnityEngine.Object.Destroy(transitionClone.GetComponent<ImpostorClone>());
							float x = 0f;
							PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
							GameObject obj = transitionClone;
							Vector3? localPositionTo = value;
							gameplayTween.tween(obj, 0.15f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, localPositionTo, null, null, null, null, null, null, null, null, null, null, null, delegate
							{
								if (startedInZoom == inZoomMode())
								{
									bool endedAnimation = false;
									getGameplayTween().tween(transitionClone, 0.7f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, delegate(float t)
									{
										if (!endedAnimation)
										{
											if (startedInZoom == inZoomMode())
											{
												if (t > 0f && transitionClone.activeSelf)
												{
													x = getWobbleY(t, 25f, 1f, 20f);
													Vector3 vector4 = position;
													vector4.x += x;
													transitionClone.transform.localPosition = vector4 - pivotOffsetLocal;
												}
											}
											else
											{
												endedAnimation = true;
												endAnimation();
											}
										}
									}, delegate
									{
										if (!endedAnimation)
										{
											endAnimation();
										}
									});
								}
								else
								{
									endAnimation();
								}
							});
							exitFocusMode(enableCursor: false);
							cursorVisible.changeState(CursorVisibleState.Hidden);
						}
						flag = true;
					}
					if (inOtherPlayerInventoryFocus && otherPlayerInventoryUI.Container.hover != -1 && otherPlayerInventoryUI.Container.hover < currentOtherPlayerInventory.Count)
					{
						Item component3 = currentOtherPlayerInventory[otherPlayerInventoryUI.Container.hover].topGameObject().GetComponent<Item>();
						UnityEngine.Debug.Log("Pinging " + component3.name);
						session.sendToSpecificPlayer(new PingItemPacket
						{
							item = component3
						}, currentOtherPlayerInventoryId);
					}
				}
				else if (pc.mouseRightDown)
				{
					exitFocusMode();
					flag = true;
				}
			}
			else
			{
				if (gridContainer.hover != -1 && pointer.context.currentTargetType == ScreenTargetType.ItemInventory && pc.pointer.gestureUp)
				{
					if (inTrashInventoryFocus)
					{
						takeItemFromTrash(pointer.context.currentTarget, pointer.context.currentTargetType);
					}
					if (inOtherPlayerInventoryFocus)
					{
						Item component4 = currentOtherPlayerInventory[gridContainer.hover].topGameObject().GetComponent<Item>();
						UnityEngine.Debug.Log("Pinging " + component4.name);
						session.sendToSpecificPlayer(new PingItemPacket
						{
							item = component4
						}, currentOtherPlayerInventoryId);
					}
				}
				if ((pc.mouseRightDown && !pc.pointer.gestureLongPress && !pc.pointer.gestureLongPressFailed && !pc.pointer.gestureDownToLongPress) || ((pointer.context.currentTargetType != ScreenTargetType.ItemInventory || inSlotInventoryFocus) && pc.pointer.gestureUp))
				{
					exitFocusMode();
					flag = true;
				}
			}
		}
		if (!flag && (pc.actionEscape || pc.actionItemPicker || pc.mouseRightDown) && (!inTrashInventoryFocus || (!pc.pointer.gestureLongPress && !pc.pointer.gestureLongPressFailed && !pc.pointer.gestureDownToLongPress)))
		{
			pcChangeItemSelectionIndex(-1);
			setupItemUI(zoomItemUI, null, canBeStreamlined: false);
			exitFocusMode();
			flag = true;
		}
		if (!flag && !inTrashInventoryFocus && !inSlotInventoryFocus && selectItemKeyboard())
		{
			exitFocusMode();
		}
		void endAnimation()
		{
			UnityEngine.Object.Destroy(transitionClone);
			if (cursorVisible.current == CursorVisibleState.Hidden || cursorVisible.current == CursorVisibleState.VirtualHiddenButMovable)
			{
				cursorVisible.changeState(CursorVisibleState.VirtualVisible);
			}
			isInSlotInventoryAnimation = false;
		}
		static float getWobbleY(float t, float rate, float decay, float amp)
		{
			return Mathf.Sin(rate * t) * ((t - decay) * (t - decay) / amp);
		}
	}

	private void exitFocusMode(bool enableCursor = true)
	{
		UnityEngine.Debug.Log("Exiting focus mode");
		if (inTrashInventoryFocus)
		{
			inTrashInventoryFocus = false;
			trashInventoryGridContainer.hover = -1;
			activateTrashCanvas(activate: false);
		}
		if (inSlotInventoryFocus)
		{
			trashInventoryGridContainer.hover = -1;
			activateControllerSlotCanvas(activate: false);
		}
		if (inOtherPlayerInventoryFocus)
		{
			hideOtherPlayerInventory();
		}
		inInventoryFocus = false;
		inventoryGridContainer.hover = -1;
		inventoryGridContainer.columns = -1;
		inventoryGridContainer.cellScale = 1f;
		inventoryGridContainer.GetComponent<RectTransform>().anchorMin = Vector2.zero;
		inventoryGridContainer.GetComponent<RectTransform>().anchorMax = Vector2.zero;
		inventoryGridContainer.GetComponent<RectTransform>().pivot = Vector2.zero;
		inventoryGridContainer.preciseSelection = -1f;
		if (enableCursor)
		{
			cursorVisible.changeState(cursorVisible.last);
		}
	}

	private void takeItemFromTrash(GameObject gameObject, ScreenTargetType targetType)
	{
		removeItemFromTrash(gameObject.GetComponent<Item>());
		addItemToInventory(gameObject);
		if (targetType == ScreenTargetType.ItemInventory)
		{
			pcChangeItemSelection(gameObject);
		}
		else
		{
			pcChangeItemSelectionIndex(-1);
		}
		setupItemUI(zoomItemUI, null, canBeStreamlined: false);
		exitFocusMode();
	}

