		Vector3 vector2 = Vector3.one * component2.handScale * component2.examineScaleModifier * (component2.carriable ? 3f : 1f) * 0.17f;
		Vector3 vector3 = Vector3.Scale(itemImpostorScaleInitial, itemImpostorPoseInitial.rotation * (component2.examinePivotOffset + component2.handPivotOffset));
		Vector3.Scale(vector2, quaternion2 * (component2.examinePivotOffset + component2.handPivotOffset));
		float t2 = (Time.time - itemSwitchTimestamp + 0.2f) * 2f;
