			if (num7 >= 0f && num7 < stepBobDuration)
			{
				num6 = (0f - Mathf.Sin(num7 / stepBobDuration * MathF.PI)) * stepBobAmplitude * (isOnStairs ? 2f : 1f);
			}
		}
		Vector3 b4 = direction;
		b4.y += num6;
		itemBobPositionOffset = Vector3.Lerp(itemBobPositionOffset, b4, Time.deltaTime * 8f);
		Quaternion quaternion3 = Quaternion.Inverse(transform.rotation) * pose2.rotation;
		Quaternion rotation4 = Quaternion.Inverse(transform.rotation) * itemBobLastFramePose.rotation;
		(quaternion3 * Quaternion.Inverse(rotation4)).ToAngleAxis(out var angle, out var axis);
		angle = Mathf.Clamp((angle > 180f) ? (angle - 360f) : angle, -10f, 10f) * 0.2f;
		itemBobRotationOffset = Quaternion.Slerp(itemBobRotationOffset, Quaternion.AngleAxis(angle, axis.normalized), Time.deltaTime * 8f);
		itemBobLastFramePose = pose2;
		b3 += transform.parent.TransformDirection(itemBobPositionOffset);
		quaternion2 *= itemBobRotationOffset;
		timeCarriableIsDown = Mathf.MoveTowards(timeCarriableIsDown, flag9 ? 1 : 0, Time.deltaTime * 4f);
		b3 += Vector3.Lerp(Vector3.zero, -vector4 * 5f, Interpolation.SmootherStep.evaluate(timeCarriableIsDown));
		b3 += Vector3.Lerp(Vector3.zero, -vector4 * 5f, Interpolation.SmootherStep.evaluate((Mathf.Sin(Time.time) + 1f) / 2f) * 0.05f);
		GameObject[] array = pcSelectedItemImpostors;
		foreach (GameObject gameObject in array)
		{
			gameObject.transform.localRotation = Quaternion.Lerp(itemImpostorPoseInitial.rotation, quaternion2, t);
			gameObject.transform.localScale = Vector3.Lerp(itemImpostorScaleInitial, vector2, t);
			Vector3 vector5 = Vector3.Scale(gameObject.transform.localScale, gameObject.transform.localRotation * (component2.examinePivotOffset + component2.handPivotOffset));
			gameObject.transform.localPosition = Vector3.Lerp(itemImpostorPoseInitial.position - vector3, b3, t) + vector5;
		}
		if (flag)
		{
			itemObject.transform.rotation = pcSelectedItemGhost.transform.rotation;
		}
		if (itemImpostorInitialWeight < 0.75f)
		{
			shouldItemGhostBeVisible = false;
		}
		Vector3 position6 = playerCamera.ViewportToWorldPoint(new Vector3(0.5f, 0.5f, 1f - approachCamera * 0.75f));
		Vector3 vector6 = playerCamera.transform.InverseTransformPoint(position6);
		if (pcSelectedItemScreenSpace != null)
		{
			pcSelectedItemScreenSpace.transform.localPosition = vector6 - pcSelectedImpostorClonePivotOffsetLocal;
			pcSelectedItemScreenSpace.SetActive(!pcSelectedItemImpostors[0].activeSelf && !pcSelectedItemGhost.activeSelf && controlMode.current != ControlMode.VirtualGamepad && shouldItemScreenSpaceBeVisible);
		}
		shouldItemScreenSpaceBeVisible = true;
		static bool findTransformOnSurfaceAny(Camera camera, GameObject gameObject2, Item item, Bounds bounds, Vector3 hitPoint, out Vector3 reference, out Quaternion reference2)
		{
			bool result = false;
			reference = Vector3.zero;
			reference2 = Quaternion.identity;
			Vector3 vector7 = camera.transform.position - hitPoint;
			if (Mathf.Abs(vector7.x) < 0.001f && Mathf.Abs(vector7.z) < 0.001f)
			{
				Vector3 vector8 = -camera.transform.up;
				vector7.x = vector8.x;
				vector7.z = vector8.z;
			}
			Quaternion rotation5 = Quaternion.LookRotation(new Vector3(vector7.x, 0f, vector7.z), Vector3.up);
			if (item != null)
			{
				rotation5 *= Quaternion.Euler(0f, 180f, 0f);
				rotation5 *= Quaternion.Euler(item.examineBaseRotation) * Quaternion.Euler(item.groundRotation);
			}
			Quaternion rotation6 = gameObject2.transform.rotation;
			gameObject2.transform.rotation = rotation5;
			Vector3 vector9 = Vector3.Scale(gameObject2.transform.lossyScale, gameObject2.transform.rotation * bounds.center);
			Vector3 vector10 = Vector3.Scale(gameObject2.transform.localScale, gameObject2.transform.localRotation * bounds.extents);
			vector10.x = Mathf.Abs(vector10.x);
			vector10.y = Mathf.Abs(vector10.y);
			vector10.z = Mathf.Abs(vector10.z);
			Vector3 halfExtents = Vector3.Scale(gameObject2.transform.localScale, bounds.extents);
			int num8 = -5 & ~LayerMask.GetMask("ItemOverUI", "Zoom");
			Vector3 normalized = (hitPoint + Vector3.up * vector10.y - camera.transform.position).normalized;
			RaycastHit hitInfo = default(RaycastHit);
			if (Physics.BoxCast(camera.transform.position - normalized * halfExtents.z / 2f, halfExtents, normalized, out hitInfo, gameObject2.transform.rotation, float.PositiveInfinity, num8, QueryTriggerInteraction.Ignore))
			{
				Vector3 vector11 = camera.transform.position + normalized * hitInfo.distance;
				if (inReach(camera.transform.position, vector11))
				{
					DrawBoxCastBox(camera.transform.position, halfExtents, normalized, gameObject2.transform.rotation, hitInfo.distance, Color.yellow);
					UnityEngine.Debug.DrawLine(camera.transform.position, vector11, Color.cyan);
					float distance = hitInfo.distance;
					isViewBlocked(camera, num8, ref distance);
					Vector3 vector12 = camera.transform.position - normalized * halfExtents.z / 2f + normalized * distance;
					reference = vector12 - vector9;
					reference2 = gameObject2.transform.rotation;
					result = true;
				}
			}
			gameObject2.transform.rotation = rotation6;
			return result;
		}
	}

	private bool isPaintingWithItem(Pointer pointer)
	{
		if (pointer.context.targetType == ScreenTargetType.Paintable && pcSelectedItem != -1 && inventory[pcSelectedItem].topGameObject().TryGetComponent<Item>(out var component))
		{
			return pointer.context.target.GetComponent<Paintable>().itemCheck(component) == ItemCheck.Passes;
		}
		return false;
	}

	private bool canPaintWithItem(Pointer pointer)
	{
		if (pointer.context.currentTargetType == ScreenTargetType.Paintable && pcSelectedItem != -1 && inventory[pcSelectedItem].topGameObject().TryGetComponent<Item>(out var component))
		{
			return pointer.context.currentTarget.GetComponent<Paintable>().itemCheck(component) == ItemCheck.Passes;
		}
		return false;
	}

	private Item getUsableItem(Pointer pointer)
	{
		if (pcSelectedItem == -1)
		{
			return null;
		}
		if (!inventory[pcSelectedItem].topGameObject().TryGetComponent<Item>(out var component))
		{
			return null;
		}
		if (component.toolType == ItemTool.TargetActivated)
		{
			if (pointer.context.currentTarget == null)
			{
				return null;
			}
			if (!UnityUtils.contains(component.toolTargets, pointer.context.currentTarget.GetComponent<Interactive>()))
			{
				return null;
			}
		}
		return component;
	}

	private void handlePCSelectedItemMode(PCControlContext pc)
	{
		Item item = null;
		GameObject gameObject = null;
		InventoryItem inventoryItem = null;
		if (carryingItem != null)
		{
			item = carryingItem;
			gameObject = carryingItem.gameObject;
		}
		else
		{
			inventoryItem = inventory[pcSelectedItem];
			gameObject = inventoryItem.topGameObject();
			item = gameObject.GetComponent<Item>();
		}
		timeInSelectedMode += Time.deltaTime;
		Slot slot = null;
		if (pc.pointer.context.currentTarget != null)
		{
			slot = pc.pointer.context.currentTarget.GetComponent<Slot>();
			if (slot == null && pc.pointer.context.currentTarget.TryGetComponent<Item>(out var component))
			{
				slot = component.slot;
			}
			slot = ((!(slot != null) || !canBePlacedInSlot(slot, item)) ? null : (isSlotCloseEnough(slot) ? slot : null));
		}
		shouldItemScreenSpaceBeVisible = false;
		if (carryingItem == null)
		{
			if (canPaintWithItem(pc.pointer))
			{
				setPCHoverActions("HoverAction_Use", "", "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, null, item, pc.pointer);
			}
			else
			{
				string text = "HoverAction_Place";
				Item usableItem = getUsableItem(pc.pointer);
				if (usableItem != null && usableItem.toolType != ItemTool.None)
				{
					text = Localization.translate(usableItem.toolActionDescription);
					if (string.IsNullOrEmpty(text))
					{
						text = "HoverAction_Use";
					}
					if (toolHoldingTimer > 2f)
					{
						text = "HoverAction_Place";
					}
				}
				if (pc.pointer.context.currentTargetType == ScreenTargetType.Trashcan)
				{
					text = "DropToTrash";
				}
				setPCHoverActions(text, "HoverAction_Deselect", "HoverAction_Zoom", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, null, item, pc.pointer);
			}
		}
		else
		{
			setPCHoverActions("HoverAction_Place", "", "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, null, carryingItem);
		}
		float num = pc.pointer.gestureTimeSinceTap;
		float approachCamera = Mathf.Pow(40f, Mathf.Clamp01((pc.pointer.gestureTimeSinceTap - 0.3f) * 4f) - 1f);
		if (pc.pointer.context.targetType == ScreenTargetType.Tool || item.backgroundUpdate || isPaintingWithItem(pc.pointer))
		{
			num = 0f;
			approachCamera = 0f;
		}
		if (item.toolType != ItemTool.None && item.toolType == ItemTool.AlwaysActive)
		{
			if (Controller.isActive())
			{
				toolHoldingTotalMove += getControllerLook();
			}
			else
			{
				toolHoldingTotalMove += new Vector2(0f - Input.GetAxisRaw("Mouse X"), 0f - Input.GetAxisRaw("Mouse Y"));
			}
			if (toolHoldingTotalMove.magnitude > 3f)
			{
				toolHoldingTimer = 0f;
				toolHoldingTotalMove = Vector2.zero;
			}
			Interactive interactive = pc.pointer.context.currentTarget?.GetComponent<Interactive>();
			if (interactive != null)
			{
				if (interactive is Trashcan)
				{
					toolHoldingTimer = 3f;
				}
				else
				{
					toolHoldingTimer = 0f;
				}
			}
			else if (pc.pointer.context.interactionSessionId == 0)
			{
				float num2 = ((playerCamera.transform.rotation.eulerAngles.x >= 30f && playerCamera.transform.rotation.eulerAngles.x <= 90f && !item.disableLookDownFasterPlace) ? toolLookingDownMultiplier : 1f);
				toolHoldingTimer += Time.deltaTime * num2;
			}
		}
