		PCCrosshair setupHoverMessage(GameObject hoverTarget, ScreenTargetType hoverTargetType, InteractiveAnnotation hoverTargetAnnotation)
		{
			PCCrosshair pCCrosshair2 = defaultCrosshair;
			if (hoverTarget == null)
			{
				pCCrosshair2 = defaultCrosshair;
				setPCHoverActions("", rightClickOverride, "");
			}
			else if (interactionZoom == null)
			{
				switch (hoverTargetType)
				{
				case ScreenTargetType.OtherPlayer:
				{
					GamePlayerData gamePlayerData2 = netPlayers.Find((GamePlayerData x) => x.playerCollider.gameObject == pc.pointer.context.currentTarget);
					if (gamePlayerData2 == null)
					{
						gamePlayerData2 = localPlayerData;
					}
					previewPlayerId = gamePlayerData2.id;
					break;
				}
				case ScreenTargetType.Item:
				{
					pc.pointer.context.currentTarget.TryGetComponent<Item>(out var component6);
					bool flag7 = component6 != null && component6.slot == null && !component6.carriable;
					string left = ((component6 != null && component6.carriable) ? "Carry" : "HoverAction_Grab");
					setPCHoverActions(left, rightClickOverride, flag7 ? "HoverAction_Look" : "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				}
				case ScreenTargetType.Zoomable:
					if (isInPoseMode())
					{
						setPCHoverActions("", rightClickOverride, "");
					}
					else
					{
						setPCHoverActions("HoverAction_Zoom", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					}
					break;
				case ScreenTargetType.Slot:
					setPCHoverActions("HoverAction_Use", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.Draggable:
				case ScreenTargetType.InteractiveHinge:
				case ScreenTargetType.Slidable:
				case ScreenTargetType.SlidableGraphPiece:
				case ScreenTargetType.Rotatable:
				case ScreenTargetType.HorizontalSlider:
					pCCrosshair2 = PCCrosshair.Draggable;
					setPCHoverActions("HoverAction_Drag", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.OtherPlayerUsing:
					pCCrosshair2 = PCCrosshair.OtherPlayerUsing;
					setPCHoverActions("", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.SharedZoom:
					pCCrosshair2 = PCCrosshair.Zoomable;
					setPCHoverActions("HoverAction_SharedZoom", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.OtherPlayerInventoryBeltItem:
					pCCrosshair2 = PCCrosshair.Pickup;
					setPCHoverActions("HoverAction_Steal", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.SurfaceSlot:
					pCCrosshair2 = PCCrosshair.Regular;
					setPCHoverActions("", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.Trashcan:
					pCCrosshair2 = PCCrosshair.Trashcan;
					setPCHoverActions("HoverAction_Use", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.NPC:
					setPCHoverActions("Talk", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				case ScreenTargetType.CharacterPose:
					if (isInPoseMode())
					{
						setPCHoverActions("", rightClickOverride, "");
					}
					else
					{
						setPCHoverActions("HoverAction_Use", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					}
					break;
				case ScreenTargetType.ChessablePiece:
				{
					ChessablePiece component5 = hoverTarget.GetComponent<ChessablePiece>();
					setPCHoverActions(component5.getLocalizationKey(), rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				}
				case ScreenTargetType.ChessableTile:
				{
					ChessableTile component4 = hoverTarget.GetComponent<ChessableTile>();
					setPCHoverActions(component4.tileId, rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				}
				default:
					setPCHoverActions("HoverAction_Use", rightClickOverride, "", overrideStreamlinedLeft: false, overrideStreamlinedRight: false, overrideStreamlinedKeyE: false, hoverTarget);
					break;
				}
				Interactive component7 = hoverTarget.GetComponent<Interactive>();
				if (component7 != null)
				{
					pCCrosshair2 = ((!isInPoseMode() || hoverTargetType != ScreenTargetType.Zoomable || canEnterZoomFromCurrentPose(hoverTarget)) ? ((!(hoverTargetAnnotation != null) || hoverTargetAnnotation.getOverrideCursor() == PCCrosshair.Default) ? component7.getCursor() : hoverTargetAnnotation.getOverrideCursor()) : PCCrosshair.Regular);
					if (pCCrosshair2 == PCCrosshair.EvaluateInCallback)
					{
						pCCrosshair2 = evaluateCustomCursor(pc.pointer);
					}
					if (pCCrosshair2 == PCCrosshair.TargetDependent)
					{
						if (hoverTarget != null && hoverTarget.TryGetComponent<Interactive>(out var component8))
						{
							pCCrosshair2 = component8.getCursor();
						}
						if (pCCrosshair2 < PCCrosshair.Regular)
						{
							pCCrosshair2 = defaultCrosshair;
						}
					}
				}
			}
			if (pc.pointer.context.interactionSessionId == 0)
			{
				animateHoveredIfPossible(hoverTarget);
			}
			else
			{
				animateHoveredIfPossible(null);
			}
			changeCrosshair(pCCrosshair2);
			return pCCrosshair2;
		}
	}

	public void setIsHoverable(Interactive interactive, bool isHoverable)
	{
		if (isHoverable)
		{
			notHoverable.Remove(interactive.gameObject);
		}
		else
		{
			notHoverable.Add(interactive.gameObject);
		}
	}

	private void animateHoveredIfPossible(GameObject hoverTarget)
	{
		if (notHoverable.Contains(hoverTarget))
		{
			hoverTarget = null;
		}
		if (!(hoverTarget != lastHoveredInteractive))
		{
			return;
		}
		TweenState tweenState = null;
		MaterialState materialState = null;
		float speed = 1f;
		float speed2 = 1f;
		TweenState tweenState2 = null;
		MaterialState materialState2 = null;
		if (hoverTarget != null)
		{
			SwapperPiece component2;
			Dial component3;
			if (hoverTarget.TryGetComponent<Switch3D>(out var component))
			{
				speed = component.hoverSpeed;
				if (component.tweenState != null)
				{
					tweenState = component.tweenState;
				}
				if (component.materialState != null)
				{
					materialState = component.materialState;
				}
			}
			else if (hoverTarget.TryGetComponent<SwapperPiece>(out component2))
			{
				if (component2.swapper.firstPiece != component2)
				{
					speed = component2.hoverSpeed;
					if (component2.tweenState != null)
					{
						tweenState = component2.tweenState;
					}
					if (component2.materialState != null)
					{
						materialState = component2.materialState;
					}
				}
			}
			else if (hoverTarget.TryGetComponent<Dial>(out component3))
			{
				speed = component3.hoverSpeed;
				if (component3.tweenState != null)
				{
					tweenState = component3.tweenState;
				}
				if (component3.materialState != null)
				{
					materialState = component3.materialState;
				}
			}
		}
		if (lastHoveredInteractive != null)
		{
			SwapperPiece component5;
			Dial component6;
			if (lastHoveredInteractive.TryGetComponent<Switch3D>(out var component4))
			{
				speed2 = component4.hoverSpeed;
				if (component4.tweenState != null)
				{
					tweenState2 = component4.tweenState;
				}
				if (component4.materialState != null)
				{
					materialState2 = component4.materialState;
				}
			}
			else if (lastHoveredInteractive.TryGetComponent<SwapperPiece>(out component5))
			{
				speed2 = component5.hoverSpeed;
				if (component5.tweenState != null)
				{
					tweenState2 = component5.tweenState;
				}
				if (component5.materialState != null)
				{
					materialState2 = component5.materialState;
				}
			}
			else if (lastHoveredInteractive.TryGetComponent<Dial>(out component6))
			{
				speed2 = component6.hoverSpeed;
				if (component6.tweenState != null)
				{
					tweenState2 = component6.tweenState;
				}
				if (component6.materialState != null)
				{
					materialState2 = component6.materialState;
				}
			}
		}
		if (tweenState != null)
		{
			TweenState.TweenStateRecord tweenStateRecord = tweenState.tweenStateDataNeo.Find((TweenState.TweenStateRecord x) => x.name == "Hover");
			if (tweenStateRecord != null)
			{
				tweenState.transitionToStateAdditive(tweenStateRecord, speed);
			}
		}
		if (materialState != null)
		{
			MaterialState.MaterialStateRecord materialStateRecord = materialState.materialStateData.materialStates.Find((MaterialState.MaterialStateRecord x) => x.name == "Hover");
			if (materialStateRecord != null)
			{
				materialState.transitionToStateAdditive(materialStateRecord, speed);
			}
		}
		if (tweenState2 != null)
		{
			TweenState.TweenStateRecord tweenStateRecord2 = tweenState2.tweenStateDataNeo.Find((TweenState.TweenStateRecord x) => x.name == "Hover");
			if (tweenStateRecord2 != null)
			{
				tweenState2.transitionToStateAdditive(tweenStateRecord2, speed2, 0f);
			}
		}
		if (materialState2 != null)
		{
			MaterialState.MaterialStateRecord materialStateRecord2 = materialState2.materialStateData.materialStates.Find((MaterialState.MaterialStateRecord x) => x.name == "Hover");
			if (materialStateRecord2 != null)
			{
				materialState2.transitionToStateAdditive(materialStateRecord2, speed2, 0f);
			}
		}
		lastHoveredInteractive = hoverTarget;
	}

	private void changeCrosshair(PCCrosshair targetCrosshair)
	{
		if (targetCrosshair == currentCrosshair)
		{
			return;
		}
		Color white = Color.white;
		white.a = 0f;
		PCCrosshair pCCrosshair = currentCrosshair;
		if (pCCrosshair != PCCrosshair.Default && pCCrosshair != PCCrosshair.Regular)
		{
			Image image = UnityEngine.Object.Instantiate(pcCrosshair, pcCrosshair.transform.parent);
			PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
			GameObject obj = image.gameObject;
			Color? colorTo = white;
			gameplayTween.tween(obj, 0.1f, 0f, deactivate: false, activate: false, destroy: false, null, null, colorTo);
			UnityEngine.Object.Destroy(image.gameObject, 0.1f);
		}
		if (targetCrosshair != PCCrosshair.Default && targetCrosshair != PCCrosshair.Regular)
		{
			pcCrosshair.transform.localScale = Vector3.one;
			pcCrosshair.fillAmount = 1f;
			if (crosshairTween != null)
			{
				getGameplayTween().destroyTween(crosshairTween, performEvents: false, performFinalUpdate: false);
			}
			animateTween(0f);
			crosshairTween = getGameplayTween().animate(animateTween);
		}
		else
		{
			pcCrosshair.color = white;
			PineTweenSystemEnableNoHandles gameplayTween2 = getGameplayTween();
			GameObject obj2 = pcCrosshair.gameObject;
			Color? colorTo = Color.white;
			gameplayTween2.tween(obj2, 0.1f, 0.1f, deactivate: false, activate: false, destroy: false, null, null, colorTo);
		}
		pcCrosshair.sprite = pcCrosshairs[(int)targetCrosshair];
		currentCrosshair = targetCrosshair;
		bool animateTween(float t)
		{
			if (targetCrosshair != PCCrosshair.Throw)
			{
				pcCrosshair.transform.localScale = Vector3.Lerp(Vector3.zero, Vector3.one, t * 20f);
			}
			if (targetCrosshair == PCCrosshair.ArrowUp)
			{
				move(t, Vector2.up);
			}
			else if (targetCrosshair == PCCrosshair.ArrowDown)
			{
				move(t, Vector2.down);
			}
			else if (targetCrosshair == PCCrosshair.ArrowRight)
			{
				move(t, Vector2.right);
			}
			else if (targetCrosshair == PCCrosshair.ArrowLeft)
			{
				move(t, Vector2.left);
			}
			else if (targetCrosshair == PCCrosshair.Throw)
			{
				pcCrosshair.fillAmount = Mathf.Clamp01(t / 0.2f);
			}
			else
			{
				shake(t);
			}
			return t > 1f;
		}
		void move(float t, Vector3 direction)
		{
			Vector2 sizeDelta = roomCanvasUI.rectT().sizeDelta;
			Vector3 vector = -direction * 0.005f;
			Vector3 vector2 = Vector3.Scale(Vector2.Lerp(b: Vector2.zero, a: vector, t: t), sizeDelta);
			pcCrosshair.rectTransform.anchoredPosition = vector2;
		}
		void shake(float t)
		{
			Vector3 eulerAngles = pcCrosshair.transform.eulerAngles;
			eulerAngles.z = crosshairShakeAnimationCurve.Evaluate(t) * 15f;
			if (t > 1f)
			{
				eulerAngles.z = 0f;
			}
			pcCrosshair.transform.eulerAngles = eulerAngles;
		}
	}

