	private void setPCHoverActions(string left, string right, string keyE, bool overrideStreamlinedLeft = false, bool overrideStreamlinedRight = false, bool overrideStreamlinedKeyE = false, GameObject hoverObject = null, Item selectedItem = null, Pointer pointer = null)
	{
		bool flag = !Is.Editor || debugShowHints;
		pcStreamlinedHoverActions.SetActive(flag);
		if (!flag || controlMode.current == ControlMode.VirtualGamepad)
		{
			return;
		}
		if (Controller.controllerInputSetChanged)
		{
			hoverActionsObject.hoveredObject = null;
		}
		pcStreamlinedHoverActions.SetActive(value: true);
		hoverActionsItemHeld.gameObject.SetActive(value: false);
		if (hoverActionsObject != null && (hoverObject == null || hoverActionsObject.hoveredObject != hoverObject))
		{
			fadeOutActions.Add(hoverActionsObject);
			hoverActionsObject = null;
		}
		if (selectedItem == null)
		{
			bool flag2 = true;
			if (PlayerSave.getSettings().hideSimpleTutorials && ((left == "" && right == "") || (right == "" && keyE == "") || (left == "" && keyE == "")))
			{
				flag2 = false;
			}
			if (flag2 && hoverActionsObject?.hoveredObject != hoverObject)
			{
				HoverActions hoverActions = null;
				foreach (HoverActions fadeOutAction in fadeOutActions)
				{
					if (fadeOutAction.hoveredObject == hoverObject)
					{
						hoverActions = fadeOutAction;
						break;
					}
				}
				if (hoverActions == null)
				{
					hoverActions = UnityEngine.Object.Instantiate(streamlinedHoverActions, streamlinedHoverActions.transform.parent);
				}
				else
				{
					fadeOutActions.Remove(hoverActions);
				}
				assignHoverActions(hoverActions);
				if (hoverActions.itemUI != null)
				{
					setupItemUI(hoverActions.itemUI, hoverObject, canBeStreamlined: true);
				}
				hoverActionsObject = hoverActions;
				hoverActionsObject.hoveredObject = hoverObject;
			}
		}
		else
		{
			assignHoverActions(hoverActionsItemHeld);
			bool active = pcSelectedItemGhost.activeSelf || (pointer != null && (canPaintWithItem(pointer) || getUsableItem(pointer) != null)) || (pointer != null && pointer.context.currentTargetType == ScreenTargetType.Trashcan);
			hoverActionsItemHeld.pcHoverLeft.gameObject.SetActive(active);
			hoverActionsItemHeld.pcHoverCenteredLeft.gameObject.SetActive(value: false);
		}
		Image[] componentsInChildren = pcStreamlinedHoverActions.GetComponentsInChildren<Image>(includeInactive: true);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].rectT().sizeDelta = PlayerSave.getSettings().hoverUIScale * 20f * Vector2.one;
		}
		Text[] componentsInChildren2 = pcStreamlinedHoverActions.GetComponentsInChildren<Text>(includeInactive: true);
		for (int i = 0; i < componentsInChildren2.Length; i++)
		{
			componentsInChildren2[i].fontSize = (int)(PlayerSave.getSettings().hoverUIScale * 20f);
		}
		void assignHoverActions(HoverActions hoverActions2)
		{
			hoverActions2.gameObject.SetActive(value: true);
			bool flag3 = right == "" && keyE == "";
			hoverActions2.pcHoverLeft.gameObject.SetActive(!overrideStreamlinedLeft && !flag3 && left != "");
			hoverActions2.pcHoverCenteredLeft.gameObject.SetActive(!overrideStreamlinedLeft && flag3 && left != "");
			hoverActions2.pcHoverRight.gameObject.SetActive(!overrideStreamlinedRight && right != "");
			hoverActions2.pcHoverKeyE.gameObject.SetActive(!overrideStreamlinedKeyE && keyE != "");
			if (hoverActions2.pcHoverCarrying != null)
			{
				bool flag4 = selectedItem != null && selectedItem.carriable;
				hoverActions2.pcHoverCarrying.gameObject.SetActive(flag4);
				if (flag4)
				{
					string newValue = Localization.translate(selectedItem.displayName);
					hoverActions2.pcHoverCarryingLbl.text = Localization.lookupInDictionary("HoverAction_CarryingContext").Replace("[ItemName]", newValue);
				}
			}
			hoverActions2.pcHoverActionLeft.text = Localization.lookupInDictionary(left, left);
			hoverActions2.pcStreamlinedHoverActionLeftCentered.text = Localization.lookupInDictionary(left, left);
			hoverActions2.pcHoverActionRight.text = Localization.lookupInDictionary(right, right);
			hoverActions2.pcStreamlinedHoverActionKeyE.text = Localization.lookupInDictionary(keyE, keyE);
			setGlyph(hoverActions2.pcHoverActionLeft.transform, ControllerButtonActionType.GameQuickInteract);
			setGlyph(hoverActions2.pcStreamlinedHoverActionLeftCentered.transform, ControllerButtonActionType.GameQuickInteract);
			setGlyph(hoverActions2.pcHoverActionRight.transform, ControllerButtonActionType.GameBack);
			setGlyph(hoverActions2.pcStreamlinedHoverActionKeyE.transform, ControllerButtonActionType.GameEnterZoom);
			LayoutGroup[] componentsInChildren3 = hoverActions2.GetComponentsInChildren<LayoutGroup>(includeInactive: true);
			for (int j = 0; j < componentsInChildren3.Length; j++)
			{
				LayoutRebuilder.ForceRebuildLayoutImmediate(componentsInChildren3[j].rectT());
			}
		}
		static void setGlyph(Transform text, ControllerButtonActionType type)
		{
			Image componentInChildren = text.parent.GetComponentInChildren<Image>(includeInactive: true);
			componentInChildren.sprite = Controller.getGlyph(type);
			componentInChildren.gameObject.SetActive(componentInChildren.sprite != null);
			if (Controller.isActive())
			{
				Shadow shadow = componentInChildren.GetComponent<Shadow>();
				if (shadow == null)
				{
					shadow = componentInChildren.gameObject.AddComponent<Shadow>();
				}
				shadow.effectDistance = new Vector2(2f, -2f);
				componentInChildren.color = new Color(1f, 1f, 1f, 0.7f);
			}
			else
			{
				if (componentInChildren.TryGetComponent<Shadow>(out var component))
				{
					UnityEngine.Object.Destroy(component);
				}
				componentInChildren.color = Color.white;
			}
		}
	}

	private void callbackZoomEnterPC(GameObject target)
	{
		if (lobbyZoomablesWithFrame.Find((Zoomable x) => x.gameObject == target) != null)
		{
			disableInventory.addSource(value: true, DisableInventorySource.InLobbyZoomable);
		}
		setPCHoverActions("", "", "");
		Button[] componentsInChildren = zoomCanvasUI.GetComponentsInChildren<Button>();
		for (int num = 0; num < componentsInChildren.Length; num++)
		{
			componentsInChildren[num].navigation = new Navigation
			{
				mode = Navigation.Mode.None
			};
		}
		syncZoomButtons();
	}

	private void callbackZoomLeavePC(GameObject target)
	{
		inventorySlots.ForEach(delegate(InventorySlot x)
		{
			x.ui.Hover.gameObject.SetActive(value: false);
		});
		if (lobbyZoomablesWithFrame.Find((Zoomable x) => x.gameObject == target) != null)
		{
			disableInventory.removeSource(DisableInventorySource.InLobbyZoomable);
		}
		if (zoomContexts.Count == 0)
		{
			inventoryGridContainer.hover = -1;
		}
		else
		{
			syncZoomButtons();
		}
	}

	private void syncZoomButtons()
	{
		if (topZoomContextSafe(out var _))
		{
			zoomCanvasUI.NormalActions_PinLeft.gameObject.SetActive(value: false);
			zoomCanvasUI.NormalActions_PinRight.gameObject.SetActive(value: false);
		}
	}

	public void zoomUISelectBtn()
	{
		if (topZoomContextSafe(out var context))
		{
			if (!isInInventory(context.selected))
			{
				addItemToInventory(context.selected);
			}
			handleZoomLeave();
			pcChangeItemSelection(context.selected);
		}
	}

	public Vector3 getControllerMove(bool canInvert = true)
	{
		int num = 1;
		int num2 = 1;
		if (canInvert)
		{
			num = ((!PlayerSave.getSettings().controllerInvertLeftX) ? 1 : (-1));
			num2 = ((!PlayerSave.getSettings().controllerInvertLeftY) ? 1 : (-1));
		}
		ControllerAxisActionType type = ((gameState.current == GameState.Zoom) ? ControllerAxisActionType.UIMoveAndCursor : ControllerAxisActionType.GameMove);
		return new Vector3(Controller.getAxis(type).x * (float)num, 0f, Controller.getAxis(type).y * (float)num2);
	}

	public Vector3 getControllerLookWithoutClamping(bool canInvert = true)
	{
		int num = 1;
		int num2 = 1;
		if (canInvert)
		{
			num = ((!PlayerSave.getSettings().controllerInvertRightX) ? 1 : (-1));
			num2 = ((!PlayerSave.getSettings().controllerInvertRightY) ? 1 : (-1));
		}
		ControllerAxisActionType type = ((gameState.current == GameState.Zoom) ? ControllerAxisActionType.UIMoveAndRotate : ControllerAxisActionType.GameLook);
		return new Vector3(Controller.getAxis(type).x * (float)num, 0f, Controller.getAxis(type).y * (float)num2);
	}

	public Vector2 getControllerLook(bool canInvert = true)
	{
		int num = 1;
		int num2 = 1;
		if (canInvert)
		{
			num = ((!PlayerSave.getSettings().controllerInvertRightX) ? 1 : (-1));
			num2 = ((!PlayerSave.getSettings().controllerInvertRightY) ? 1 : (-1));
		}
		ControllerAxisActionType type = ((gameState.current == GameState.Zoom) ? ControllerAxisActionType.UIMoveAndRotate : ControllerAxisActionType.GameLook);
		float magnitude = Controller.getAxis(type).magnitude;
		if (magnitude < 0.75f)
		{
			deadZoneTime = Time.time;
		}
		float b = Mathf.Lerp(3f, 7f, (magnitude - 0.75f) / 0.100000024f);
		float num3 = Mathf.Lerp(3f, b, (Time.time - deadZoneTime) / 0.5f);
		float num4 = (isZoomedWithController ? 0.1f : 1f);
		return new Vector2((0f - Controller.getAxis(type).x) * (float)num, (0f - Controller.getAxis(type).y) * (float)num2) * (num3 * 0.2f) * num4;
	}

	public Vector2 getControllerLookRaw()
	{
		ControllerAxisActionType type = ((gameState.current == GameState.Zoom) ? ControllerAxisActionType.UIMoveAndRotate : ControllerAxisActionType.GameLook);
		return new Vector2(0f - Controller.getAxis(type).x, 0f - Controller.getAxis(type).y);
	}

