	public Vector3 getMousePosition()
	{
		if (Controller.isActive())
		{
			if (Is.Switch && Controller.touchStateController != InputState.None)
			{
				return new Vector2(Controller.touchPosition.x, (float)Screen.height - Controller.touchPosition.y);
			}
			Vector3 position = pcVirtualCursorRT.position;
			return new Vector3(position.x, position.y);
		}
		if (Cursor.lockState != CursorLockMode.Locked)
		{
			return Input.mousePosition;
		}
		return new Vector3((float)Screen.width * 0.5f, (float)Screen.height * 0.5f);
	}

	public Vector2 getMousePositionViewport(bool forceMoveVirtualCursor = false)
	{
		if (Controller.isActive() && (canMoveVirtualCursor() || forceMoveVirtualCursor))
		{
			Vector3 position = pcVirtualCursorRT.position;
			return new Vector2(position.x / (float)Screen.width, position.y / (float)Screen.height);
		}
		if (Cursor.lockState != CursorLockMode.Locked)
		{
			return new Vector2(Input.mousePosition.x / (float)Screen.width, Input.mousePosition.y / (float)Screen.height);
		}
		return new Vector2(0.5f, 0.5f);
	}

	public bool canMoveVirtualCursor()
	{
		if (cursorVisible.current != CursorVisibleState.VirtualVisible)
		{
			return cursorVisible.current == CursorVisibleState.VirtualHiddenButMovable;
		}
		return true;
	}

	public void resetVirtualCursorPosition()
	{
		pcVirtualCursorRT.anchoredPosition = Vector2.zero;
		if (cursorTrail.positionCount > 0)
		{
			cursorTrail.SetPosition(0, pcVirtualCursorRT.localPosition);
		}
	}

	public bool snapVirtualCursorToObject(GameObject gameObject)
	{
		bool result = false;
		Vector3 vector = playerCamera.WorldToScreenPoint(gameObject.transform.position);
		if (RectTransformUtility.ScreenPointToLocalPointInRectangle((RectTransform)pcVirtualCursorRT.parent, vector, playerCamera, out var localPoint))
		{
			pcVirtualCursorRT.anchoredPosition = localPoint;
			result = true;
		}
		else
		{
			UnityEngine.Debug.LogError("Cannot snap to " + gameObject);
		}
		return result;
	}

	public bool isDraggingAnyTypeOnAnyPointer()
	{
		bool result = dragData != null;
		foreach (Pointer pointer in pointers)
		{
			if (pointer.context.targetType == ScreenTargetType.Draggable || pointer.context.targetType == ScreenTargetType.Slidable || pointer.context.targetType == ScreenTargetType.HorizontalSlider || pointer.context.targetType == ScreenTargetType.SlidableGraphPiece || pointer.context.targetType == ScreenTargetType.Joystick || pointer.context.targetType == ScreenTargetType.Dial || pointer.context.targetType == ScreenTargetType.Turnable)
			{
				result = true;
				break;
			}
		}
		return result;
	}

	public bool isDraggingDraggableOnAnyPointer(GameObject gameObject)
	{
		foreach (Pointer pointer in pointers)
		{
			if (pointer.context.targetType == ScreenTargetType.Draggable && pointer.context.target == gameObject)
			{
				return true;
			}
		}
		return false;
	}

	private void updatePerformanceTester()
	{
		if (PerformanceTester.isActive && LoadingCanvas.get().isTransparent())
		{
			spotFPS.Add(1f / Time.unscaledDeltaTime);
			testerTimeInSpot += Time.deltaTime;
			if (testerTimeInSpot > 1f)
			{
				PerformanceTester.reportSpot(spotFPS);
				spotFPS.Clear();
				testerTimeInSpot = 0f;
				targetRotation.x += (float)PerformanceTester.currentSpot * (360f / (float)PerformanceTester.numOfSpots);
				currentRotation.x = targetRotation.x;
			}
		}
	}

	private bool canPinItem(Item item)
	{
		if (item.itemType == ItemType.Clue)
		{
			return !item.isPinningDisabled;
		}
		return false;
	}

