		{
			handleUnpinItem(selectedPinnedItem.originalItem, setItemInWorld: false);
		});
		pinCanvasUI.TitleBarLeft_ScaleDown.onClick.AddListener(delegate
		{
			applyScaleChange(selectedPinnedItem, -0.25f);
		});
		pinCanvasUI.TitleBarRight_ScaleDown.onClick.AddListener(delegate
		{
			applyScaleChange(selectedPinnedItem, -0.25f);
		});
		pinCanvasUI.TitleBarLeft_ScaleUp.onClick.AddListener(delegate
		{
			applyScaleChange(selectedPinnedItem, 0.25f);
		});
		pinCanvasUI.TitleBarRight_ScaleUp.onClick.AddListener(delegate
		{
			applyScaleChange(selectedPinnedItem, 0.25f);
		});
	}

	private void updatePins()
	{
		foreach (PinnedItemInfo pinnedItem in pinnedItems)
		{
			float num = Mathf.MoveTowards(pinnedItem.additionalScaleAnimated, pinnedItem.additionalScale, Time.deltaTime * 2f);
			if (pinnedItem.additionalScaleAnimated != num)
			{
				pinnedItem.additionalScaleAnimated = num;
				Vector3 vector = pinMiddleViewport(pinnedItem);
				Vector3 position = pinnedItem.pinnedInteractive.cornersLocal[1];
				if (vector.x < 0.5f)
				{
					position = pinnedItem.pinnedInteractive.cornersLocal[0];
				}
				Vector3 vector2 = playerCamera.WorldToViewportPoint(pinnedItem.impostor.transform.TransformPoint(position));
				pinnedItem.pinnedInteractive.transform.localScale = pinnedItem.pinnedInteractive.originalScale * pinnedItem.additionalScaleAnimated;
				Vector3 vector3 = playerCamera.WorldToViewportPoint(pinnedItem.impostor.transform.TransformPoint(position));
				pinnedItem.offset += -(vector3 - vector2);
				Vector3 position2 = new Vector3(Mathf.Clamp01(pinnedItem.viewportPosition.x + pinnedItem.offset.x), Mathf.Clamp01(pinnedItem.viewportPosition.y + pinnedItem.offset.y), 0.07f);
				pinnedItem.impostor.transform.position = playerCamera.ViewportToWorldPoint(position2);
				if (selectedPinnedItem == pinnedItem)
				{
					positionSelectedPinButtons(pinnedItem);
				}
			}
		}
		for (int num2 = unpinnedItems.Count - 1; num2 >= 0; num2--)
		{
			UnpinnedItem unpinnedItem = unpinnedItems[num2];
			unpinnedItem.time += Time.deltaTime * 10f;
			unpinnedItem.clone.localScale = Vector3.Lerp(unpinnedItem.startScale, Vector3.zero, unpinnedItem.time);
			if (unpinnedItem.time >= 1f)
			{
				unpinnedItems.RemoveAt(num2);
				UnityEngine.Object.Destroy(unpinnedItem.clone.gameObject);
			}
		}
		if (pinScaleChangedThisFrame)
		{
			pinScaleChangedThisFrame = false;
		}
	}

	private void unpinItemInExamine()
	{
		if (topZoomContextSafe(out var context))
		{
			handleUnpinItem(context.selected, setItemInWorld: false);
			closePinFirstBackgorund.gameObject.SetActive(value: false);
			setPinnedItemDimming(dimmed: false);
		}
	}

	private void pinItem(int prefferedIndex)
	{
		if (!topZoomContextSafe(out var context))
		{
			return;
		}
		ScreenTargetType selectedType = context.selectedType;
		if ((selectedType == ScreenTargetType.ItemInventory || selectedType == ScreenTargetType.Item) && !isItemPinned(context.selected))
		{
			if (context.selectedType == ScreenTargetType.Item)
			{
				addItemToInventory(context.selected);
				context.selectedType = ScreenTargetType.ItemInventory;
				handleZoomLeave();
				handleZoomEnter(context.selected, ScreenTargetType.ItemInventory);
			}
			pinItem(context.selected.GetComponent<Item>(), prefferedIndex);
			zoomCanvasUI.NormalActions_PinLeft.gameObject.SetActive(value: false);
			zoomCanvasUI.NormalActions_PinRight.gameObject.SetActive(value: false);
			removeVisualControlFromFrame("pinLeft");
			removeVisualControlFromFrame("pinRight");
		}
	}

	private void pinItem(Item item, int prefferedIndex = -1)
	{
		closePinFirstBackgorund.gameObject.SetActive(value: true);
		setPinnedItemDimming(dimmed: true);
		GameObject gameObject = item.gameObject;
		EventSystem.current.SetSelectedGameObject(null);
		pinnedItemThisFrame = item.gameObject;
		GameObject gameObject2 = ImpostorClone.create(impostorContext, gameObject, LayerMask.NameToLayer("PinnedItems"), strip: false, setupPinImpostorAction, "", ImpostorClone.StrippingFlags.AllowLights);
		setupPinImpostor(gameObject2.transform);
		Transform transform = new GameObject().transform;
		PinnedItem pinnedItem = transform.gameObject.AddComponent<PinnedItem>();
		transform.gameObject.name = "Pin Attachment";
		setParent(transform.transform, playerCamera.transform);
		setParent(gameObject2.transform, transform.transform);
		Transform obj = gameObject2.transform;
		Quaternion quaternion = Quaternion.Euler(0f - examineRotationCurrent.y, 0f, 0f) * Quaternion.Euler(0f, 0f - examineRotationCurrent.x, 0f);
		Vector3 position = playerCamera.ViewportToWorldPoint(new Vector3(0.5f, 0.5f, 0.07f));
		float num = item.examineScaleModifier * 0.1f * 0.6f;
		obj.localPosition = Quaternion.Euler(item.examineBaseRotation) * item.examinePivotOffset;
		obj.localRotation = Quaternion.Euler(item.examineBaseRotation);
		transform.rotation = playerCamera.transform.rotation * quaternion;
		transform.position = position;
		transform.localScale = Vector3.one * num;
		gameObject2.SetActive(value: true);
		Vector3[] array = new Vector3[8];
		Vector2 vector = new Vector2(float.MaxValue, float.MaxValue);
		Vector2 vector2 = new Vector2(float.MinValue, float.MinValue);
		Collider[] componentsInChildren = gameObject2.GetComponentsInChildren<Collider>();
		foreach (Collider collider in componentsInChildren)
		{
			if (!(collider == null) && collider.enabled)
			{
				Bounds bounds = getLocalBounds(collider);
				Vector3 min = bounds.min;
				Vector3 max = bounds.max;
				array[0] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(min.x, min.y, min.z)));
				array[1] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(min.x, min.y, max.z)));
				array[2] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(min.x, max.y, min.z)));
				array[3] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(min.x, max.y, max.z)));
				array[4] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(max.x, min.y, min.z)));
				array[5] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(max.x, min.y, max.z)));
				array[6] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(max.x, max.y, min.z)));
				array[7] = (Vector2)playerCamera.WorldToViewportPoint(collider.transform.TransformPoint(new Vector3(max.x, max.y, max.z)));
				for (int j = 0; j < 8; j++)
				{
					vector.x = Mathf.Min(vector.x, array[j].x);
					vector.y = Mathf.Min(vector.y, array[j].y);
					vector2.x = Mathf.Max(vector2.x, array[j].x);
					vector2.y = Mathf.Max(vector2.y, array[j].y);
				}
			}
		}
		Vector2 vector3 = new Vector2((vector2.x + vector.x) * 0.5f, (vector2.y + vector.y) * 0.5f);
		float y = vector2.y - vector3.y;
		float x = vector2.x - vector3.x;
		float x2 = vector.x - vector3.x;
		Vector2 vector4 = ((prefferedIndex == 0) ? (new Vector2(0f, 1f) - new Vector2(x2, y) + new Vector2(0.02f, -0.02f)) : (new Vector2(1f, 1f) - new Vector2(x, y) - new Vector2(0.02f, 0.02f)));
		pinnedItem.xLocal = transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(new Vector3((vector.x + vector2.x) * 0.5f, vector2.y, 0.07f)));
		pinnedItem.cornersLocal = new Vector3[4]
		{
			transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(new Vector3(vector.x, vector2.y, 0.07f))),
			transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(new Vector3(vector2.x, vector2.y, 0.07f))),
			transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(new Vector3(vector2.x, vector.y, 0.07f))),
			transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(new Vector3(vector.x, vector.y, 0.07f)))
		};
		transform.position = playerCamera.ViewportToWorldPoint(new Vector3(vector4.x, vector4.y, 0.07f));
		pinnedItem.originalScale = transform.localScale;
		gameObject2.tag = "PinnedItem";
		PinnedItemInfo pinnedItemInfo = new PinnedItemInfo
		{
			originalItem = gameObject,
			pinnedInteractive = pinnedItem,
			isWearable = false,
			impostor = transform.gameObject,
			viewportPosition = new Vector2(vector4.x, vector4.y)
		};
		pinnedItems.Add(pinnedItemInfo);
		syncPinnedDepths();
		selectPinItem(pinnedItemInfo);
		pcChangeItemSelectionIndex(-1);
		gameObject.SetActive(value: false);
		if (!isInInventory(gameObject))
		{
			addItemToInventory(gameObject);
		}
		static Bounds getLocalBounds(Collider col)
		{
			if (col is BoxCollider boxCollider)
			{
				return new Bounds(boxCollider.center, boxCollider.size);
			}
			if (col is SphereCollider sphereCollider)
			{
				float num2 = sphereCollider.radius * 2f;
				return new Bounds(sphereCollider.center, new Vector3(num2, num2, num2));
			}
			if (col is CapsuleCollider capsuleCollider)
			{
				Vector3 size = Vector3.one * capsuleCollider.radius * 2f;
				if (capsuleCollider.direction == 0)
				{
					size.x = capsuleCollider.height;
				}
				else if (capsuleCollider.direction == 1)
				{
					size.y = capsuleCollider.height;
				}
				else
				{
					size.z = capsuleCollider.height;
				}
				return new Bounds(capsuleCollider.center, size);
			}
			if (col is MeshCollider meshCollider && meshCollider.sharedMesh != null)
			{
				return meshCollider.sharedMesh.bounds;
			}
			Bounds bounds2 = col.bounds;
			Vector3 min2 = col.transform.InverseTransformPoint(bounds2.min);
			Vector3 max2 = col.transform.InverseTransformPoint(bounds2.max);
			Bounds result = default(Bounds);
			result.SetMinMax(min2, max2);
			return result;
		}
		void setupPinImpostor(Transform clone)
		{
			if (!(clone == null))
			{
				SkinnedMeshRenderer[] componentsInChildren2 = clone.gameObject.GetComponentsInChildren<SkinnedMeshRenderer>(includeInactive: true);
				for (int k = 0; k < componentsInChildren2.Length; k++)
				{
					componentsInChildren2[k].updateWhenOffscreen = true;
				}
				ImpostorClone.replaceMaterialsWithUnlit(clone.gameObject, fakeItemMaterial, fakeItemTransparentMaterial);
				Renderer[] componentsInChildren3 = clone.gameObject.GetComponentsInChildren<Renderer>(includeInactive: true);
				foreach (Renderer renderer in componentsInChildren3)
				{
					if (renderer.gameObject.CompareTag("DisableInPin"))
					{
						UnityEngine.Object.DestroyImmediate(renderer);
					}
				}
				Component[] componentsInChildren4 = clone.gameObject.GetComponentsInChildren<Component>(includeInactive: true);
				for (int num2 = componentsInChildren4.Length - 1; num2 >= 0; num2--)
				{
					Component component = componentsInChildren4[num2];
					bool flag = ImpostorClone.isComponentForStripping(component);
					bool flag2 = component is Collider;
					bool flag3 = component is ImpostorClone;
					bool flag4 = component is PinnedItem;
					if (flag && !flag2 && !flag3 && !flag4)
					{
						UnityEngine.Object.DestroyImmediate(component);
					}
					else if (component is Renderer)
					{
						Renderer renderer2 = (Renderer)component;
						for (int l = 0; l < renderer2.sharedMaterials.Length; l++)
						{
							Material[] materials = renderer2.materials;
							for (int m = 0; m < materials.Length; m++)
							{
								if (!renderer2.gameObject.CompareTag("PinDepthPunchException"))
								{
									materials[m].SetInt("_ZTest", 3);
								}
								materials[m].SetInt("_StencilComp", 8);
							}
							renderer2.materials = materials;
						}
					}
					if (flag2)
					{
						((Collider)component).isTrigger = true;
					}
				}
			}
		}
		void setupPinImpostorAction(ImpostorClone clone)
		{
			if (clone != null)
			{
				setupPinImpostor(clone.transform);
			}
		}
	}

	private void syncPinnedDepths()
	{
		float num = 0f;
		foreach (PinnedItemInfo pinnedItem in pinnedItems)
		{
			pinnedItem.pinnedInteractive.distanceExtender = num;
			num += 0.1f;
			Renderer[] componentsInChildren = pinnedItem.impostor.GetComponentsInChildren<Renderer>();
			fillRendererLists(componentsInChildren, pinnedItem.renderersOpaque, pinnedItem.renderersTransparent);
		}
	}

	[LuaAPI]
	public bool isItemPinned(GameObject item)
	{
		return pinnedItems.Find((PinnedItemInfo x) => x.originalItem == item) != null;
	}

	private void handleUnpinItem(GameObject pinnedItem, bool setItemInWorld)
	{
		unselectPinItem();
		PinnedItemInfo pinnedItemInfo = pinnedItems.Find((PinnedItemInfo x) => x.originalItem == pinnedItem);
		if (pinnedItemInfo != null)
		{
			if (topZoomContextSafe(out var context) && context.selected == pinnedItem)
			{
				zoomCanvasUI.NormalActions_PinLeft.gameObject.SetActive(value: true);
				zoomCanvasUI.NormalActions_PinRight.gameObject.SetActive(value: true);
			}
			pinnedItems.Remove(pinnedItemInfo);
			unpinnedItems.Add(new UnpinnedItem
			{
				clone = pinnedItemInfo.impostor.transform,
				startScale = pinnedItemInfo.impostor.transform.localScale
			});
			syncPinnedDepths();
		}
		if (setItemInWorld)
		{
			Physics.Raycast(playerCamera.transform.position, playerCamera.transform.forward, out var hitInfo);
			pinnedItem.transform.position = hitInfo.point;
		}
		if (!topZoomContextSafe(out var context2))
		{
			return;
		}
		bool flag = false;
		foreach (PinnedItemInfo pinnedItem2 in pinnedItems)
		{
			if (context2.selected == pinnedItem2.originalItem)
			{
				flag = true;
				break;
			}
		}
		if (!flag)
		{
			closePinFirstBackgorund.gameObject.SetActive(value: false);
			setPinnedItemDimming(dimmed: false);
		}
	}

	private void handlePinnedItem(Pointer pointer)
	{
		PinnedItem pinnedItem = pointer.context.target.GetComponent<PinnedItem>();
		PinnedItemInfo pinnedItemInfo = pinnedItems.Find((PinnedItemInfo x) => x.pinnedInteractive == pinnedItem);
		selectPinItem(pinnedItemInfo);
		if (pinnedItem.sessionId != pointer.context.interactionSessionId)
		{
			pinnedItem.sessionId = pointer.context.interactionSessionId;
		}
		pinnedItemInfo.offset += pointer.gestureMovementViewport;
		Vector3 position = new Vector3(Mathf.Clamp01(pinnedItemInfo.viewportPosition.x + pinnedItemInfo.offset.x), Mathf.Clamp01(pinnedItemInfo.viewportPosition.y + pinnedItemInfo.offset.y), 0.07f);
		pinnedItemInfo.impostor.transform.position = playerCamera.ViewportToWorldPoint(position);
		positionSelectedPinButtons(selectedPinnedItem);
	}

	private Vector3 pinMiddleViewport(PinnedItemInfo pin)
	{
		Vector3 position = pin.pinnedInteractive.xLocal;
		if (pinCanvasUI.TitleBarLeft.gameObject.activeSelf)
		{
			position = pin.pinnedInteractive.cornersLocal[0];
		}
		else if (pinCanvasUI.TitleBarRight.gameObject.activeSelf)
		{
			position = pin.pinnedInteractive.cornersLocal[1];
		}
		return playerCamera.WorldToViewportPoint(pin.impostor.transform.TransformPoint(position));
	}

	private void positionSelectedPinButtons(PinnedItemInfo pin)
	{
		Canvas.ForceUpdateCanvases();
		LayoutRebuilder.ForceRebuildLayoutImmediate((RectTransform)pinCanvasUI.root.transform);
		Vector3 vector = pinMiddleViewport(pin);
		RectTransform component = pinCanvasUI.TitleBarRight.GetComponent<RectTransform>();
		Vector3 position = pin.pinnedInteractive.cornersLocal[1];
		pinCanvasUI.TitleBarLeft.gameObject.SetActive(value: false);
		pinCanvasUI.TitleBarRight.gameObject.SetActive(value: true);
		if (vector.x < 0.5f)
		{
			component = pinCanvasUI.TitleBarLeft.GetComponent<RectTransform>();
			pinCanvasUI.TitleBarLeft.gameObject.SetActive(value: true);
			pinCanvasUI.TitleBarRight.gameObject.SetActive(value: false);
			position = pin.pinnedInteractive.cornersLocal[0];
		}
		Vector3 vector2 = playerCamera.WorldToScreenPoint(pin.impostor.transform.TransformPoint(position));
		Vector2 vector3 = rectTransformScreenSize(component, playerCamera) * 1.1f;
		vector2.x = Mathf.Clamp(vector2.x, vector3.x, (float)Screen.width - vector3.x);
		vector2.y = Mathf.Clamp(vector2.y, 0f, Screen.height);
		if (RectTransformUtility.ScreenPointToLocalPointInRectangle((RectTransform)pinCanvasUI.root.transform, vector2, playerCamera, out var localPoint))
		{
			component.anchoredPosition = localPoint;
			return;
		}
		pinCanvasUI.TitleBarLeft.gameObject.SetActive(value: false);
		pinCanvasUI.TitleBarRight.gameObject.SetActive(value: false);
		static Vector2 rectTransformScreenSize(RectTransform rectTransform, Camera camera)
		{
			Vector3[] array = new Vector3[4];
			rectTransform.GetWorldCorners(array);
			Vector3 vector4 = RectTransformUtility.WorldToScreenPoint(camera, array[0]);
			return (Vector3)RectTransformUtility.WorldToScreenPoint(camera, array[2]) - vector4;
		}
	}

	private void setPinnedItemDimming(bool dimmed)
	{
		if (examineExposureVolume.profile.TryGet<Dim>(out var component))
		{
			component.intensity.value = (dimmed ? 0.75f : 0f);
		}
	}

	private void selectPinItem(PinnedItemInfo pinned)
	{
		changePinSelection(pinned);
	}

	private void unselectPinItem()
	{
		changePinSelection(null);
	}

	private void changePinSelection(PinnedItemInfo pin)
	{
		if (pin != selectedPinnedItem)
		{
			UnityEngine.Debug.Log("changePinSelection");
			if (pin == null)
			{
				removeInteractiveHighlight();
				pinCanvasUI.TitleBarLeft.gameObject.SetActive(value: false);
				pinCanvasUI.TitleBarRight.gameObject.SetActive(value: false);
			}
			else
			{
				selectInteractiveHighlight(pin.pinnedInteractive);
				positionSelectedPinButtons(pin);
				pinnedItems.Remove(pin);
				pinnedItems.Add(pin);
				syncPinnedDepths();
			}
			selectedPinnedItem = pin;
		}
	}

	private void applyScaleChange(PinnedItemInfo pin, float scaleChange)
	{
		pin.additionalScale = Mathf.Clamp(pin.additionalScale + scaleChange, 0.5f, 1.5f);
		pinScaleChangedThisFrame = true;
	}

	private void updateInput()
	{
		clearRemovingPointers();
		if (session.connectionMode == ConnectionMode.Splitscreen && !hasControl)
		{
			return;
		}
		if (pointers.Count <= 1)
		{
			gestureComplexActive = false;
		}
		if (controlMode.current == ControlMode.MouseAndKeyboard)
		{
			PointerInput input = new PointerInput();
			if (Controller.isActive())
			{
				updateInputController(input);
			}
			else
			{
				updateInputPc(input);
			}
			updatePointerForInput(input);
			return;
		}
		if (controlMode.current == ControlMode.VR)
		{
			vr.updateVRSimulatorInput();
			{
				foreach (PointerInput vRPointerInput in getVRPointerInputs())
				{
					updatePointerForInput(vRPointerInput);
				}
				return;
			}
		}
		if (controlMode.current == ControlMode.VirtualGamepad)
		{
			foreach (PointerInput touchPointerInput in getTouchPointerInputs())
			{
				updatePointerForInput(touchPointerInput);
			}
			return;
		}
		if (controlMode.current == ControlMode.Touch)
		{
			for (int i = 0; i < Input.touchCount; i++)
			{
				Touch touch = Input.GetTouch(i);
				PointerInput pointerInput = new PointerInput();
				pointerInput.down = touch.phase == TouchPhase.Began;
				pointerInput.stationaryOrMoving = touch.phase == TouchPhase.Moved || touch.phase == TouchPhase.Stationary;
				pointerInput.up = touch.phase == TouchPhase.Ended || touch.phase == TouchPhase.Canceled;
				pointerInput.position = touch.position;
				pointerInput.fingerId = touch.fingerId;
				updatePointerForInput(pointerInput);
			}
			updateLegacyTouch();
		}
		void updateInputController(PointerInput pointerInput2)
		{
			if (controllerModalDrag.current == ButtonState.None && controllerModalDragChangedState == ButtonState.None)
			{
				if (!gameInputDispatcher.get(ControllerButtonActionType.GameHoldInteract, ControllerButtonActionType.UIConfirmSecondary))
				{
					pointerInput2.stationaryOrMoving = gameInputDispatcher.get(ControllerButtonActionType.GameQuickInteract, ControllerButtonActionType.UIConfirmPrimary);
					pointerInput2.down = gameInputDispatcher.getDown(ControllerButtonActionType.GameHoldInteract, ControllerButtonActionType.GameQuickInteract, ControllerButtonActionType.UIConfirmPrimary, ControllerButtonActionType.UIConfirmSecondary);
					pointerInput2.downJoystickStick = gameInputDispatcher.getDown(ControllerButtonActionType.GameQuickInteract, ControllerButtonActionType.UIConfirmPrimary);
					pointerInput2.up = gameInputDispatcher.getUp(ControllerButtonActionType.GameHoldInteract, ControllerButtonActionType.GameQuickInteract, ControllerButtonActionType.UIConfirmPrimary, ControllerButtonActionType.UIConfirmSecondary);
				}
				else
				{
					pointerInput2.stationaryOrMoving = true;
					pointerInput2.downJoystickStick = false;
					pointerInput2.up = gameInputDispatcher.getUp(ControllerButtonActionType.GameHoldInteract, ControllerButtonActionType.UIConfirmSecondary);
				}
			}
			else
			{
				pointerInput2.down = false;
				pointerInput2.stationaryOrMoving = true;
				pointerInput2.up = controllerModalDragChangedState != ButtonState.None;
				controllerModalDragChangedState = ButtonState.None;
			}
			pointerInput2.position = getMousePosition();
			if (Controller.touchStateController != InputState.None)
			{
				pointerInput2.down = Controller.touchStateController == InputState.Down;
				pointerInput2.downJoystickStick = false;
				pointerInput2.stationaryOrMoving = Controller.touchStateController == InputState.Hold;
				pointerInput2.up = Controller.touchStateController == InputState.Up;
				pointerInput2.position = getMousePosition();
				pointerInput2.fingerId = 0;
			}
		}
		void updateInputPc(PointerInput pointerInput2)
		{
			pointerInput2.down = getMouseButtonDown(0);
			pointerInput2.stationaryOrMoving = getMouseButton(0);
			pointerInput2.up = getMouseButtonUp(0) || !getMouseButton(0);
			pointerInput2.position = getMousePosition();
		}
		void updateLegacyTouch()
		{
			gesturePan = Vector3.zero;
			gesturePinch = 0f;
			if (pointers.Count >= 2 && controlMode.current != ControlMode.VR)
			{
				gestureComplexActive = true;
				Vector3 gestureMovementRaw = pointers[0].gestureMovementRaw;
				Vector3 gestureMovementRaw2 = pointers[1].gestureMovementRaw;
				Vector3 gesturePositionScreen = pointers[0].gesturePositionScreen;
				Vector3 gesturePositionScreen2 = pointers[1].gesturePositionScreen;
				Vector2 b = new Vector2(1f / (float)Screen.width, 1f / (float)Screen.height);
				Vector2 vector = Vector2.Scale(gestureMovementRaw, b);
				Vector2 vector2 = Vector2.Scale(gestureMovementRaw2, b);
				if (Vector3.Dot(gestureMovementRaw.normalized, gestureMovementRaw2.normalized) > 0.8f)
				{
					gesturePan = (gestureMovementRaw + gestureMovementRaw2) * 0.5f;
					gesturePanViewport = (vector + vector2) * 0.5f;
					gesturePanTotal += gesturePan;
					gesturePanViewportTotal += gesturePanViewport;
				}
				else
				{
					float sqrMagnitude = (gesturePositionScreen - gesturePositionScreen2).sqrMagnitude;
					float sqrMagnitude2 = (gesturePositionScreen + gestureMovementRaw - (gesturePositionScreen2 + gestureMovementRaw2)).sqrMagnitude;
					float num = ((sqrMagnitude <= sqrMagnitude2) ? 1f : (-1f));
					gesturePinch = num * (gestureMovementRaw - gestureMovementRaw2).magnitude;
				}
			}
			else
			{
				gesturePanTotal = Vector3.zero;
				gesturePanViewportTotal = Vector3.zero;
			}
		}
		void updatePointerForInput(PointerInput pointerInput2)
		{
			Pointer pointer = null;
			foreach (Pointer pointer3 in pointers)
			{
				if (pointer3.gestureFingerId == pointerInput2.fingerId)
				{
					pointer = pointer3;
					break;
				}
			}
			Vector3 inputPosition = pointerInput2.position;
			if (pointerInput2.down)
			{
				if (pointer != null)
				{
					pointers.Remove(pointer);
				}
				pointer = createPointer();
				pointer.gestureFingerId = pointerInput2.fingerId;
			}
			if (pointer != null && pointer.hover)
			{
				pointers.Remove(pointer);
				pointer = null;
			}
			if (pointer == null)
			{
				pointer = createPointer();
				pointer.hover = true;
				pointer.gestureFingerId = pointerInput2.fingerId;
				pointers.Add(pointer);
			}
			if (pointer != null)
			{
				pointer.gestureDown = false;
				if (pointerInput2.down)
				{
					pointers.Add(pointer);
				}
				if (pointerInput2.down)
				{
					pointer.gestureDown = true;
					pointer.gestureDownControllerStick = pointerInput2.downJoystickStick;
					pointer.gestureDownToLongPress = true;
					pointersCenter = Vector2.zero;
					foreach (Pointer pointer4 in pointers)
					{
						pointersCenter += pointer4.gesturePositionScreen;
					}
					pointersCenter /= (float)pointers.Count;
					foreach (Pointer pointer5 in pointers)
					{
						pointer5.gestureCenterOffset = pointer5.gesturePositionScreen - pointersCenter;
					}
				}
				if (pointerInput2.stationaryOrMoving)
				{
					if (!pointerInput2.down)
					{
						pointer.gestureTimeSinceTap += Time.deltaTime;
					}
					if (pointer.gestureTimeSinceTap > shortPressTime)
					{
						pointer.gestureShortPressFailed = true;
					}
					if (controlMode.current == ControlMode.MouseAndKeyboard && pointers.Count > 0 && Cursor.lockState == CursorLockMode.Locked)
					{
						if (Controller.isActive())
						{
							Vector3 vector = Vector3.zero;
							if (Controller.touchStateController == InputState.Hold)
							{
								if (Is.Switch)
								{
									vector = inputPosition - pointer.gesturePositionScreen;
								}
							}
							else
							{
								vector = getControllerMove() * 5f;
								vector.y = vector.z;
								vector.z = 0f;
								if (vector == Vector3.zero)
								{
									vector = -getControllerLook() * 5f;
								}
							}
							pointer.gestureMovementRaw = vector;
						}
						else
						{
							pointer.gestureMovementRaw = new Vector3(Input.GetAxisRaw("Mouse X"), Input.GetAxisRaw("Mouse Y")) * PlayerSave.getSettings().mouseSensitivity;
						}
					}
					else if (Controller.isActive())
					{
						Vector3 zero = Vector3.zero;
						if (Controller.touchStateController == InputState.Hold)
						{
							zero = inputPosition - pointer.gesturePositionScreen;
						}
						else
						{
							zero = getControllerMove() * 5f;
							zero.y = zero.z;
							zero.z = 0f;
							if (zero == Vector3.zero)
							{
								zero = -getControllerLook() * 5f;
							}
						}
						pointer.gestureMovementRaw = zero;
					}
					else
					{
						pointer.gestureMovementRaw = inputPosition - pointer.gesturePositionScreen;
					}
					pointer.gesturePositionViewport = new Vector3(inputPosition.x / (float)Screen.width, inputPosition.y / (float)Screen.height, 0f);
					pointer.gesturePositionScreen = new Vector3(inputPosition.x, inputPosition.y, 0f);
					pointer.gestureMovementTotalRaw += pointer.gestureMovementRaw;
					pointer.gestureRayPrevious = pointer.gestureRay;
					pointer.gestureRay = playerCamera.ScreenPointToRay(pointer.gesturePositionScreen);
					UnityEngine.Debug.DrawRay(pointer.gestureRayPrevious.origin, pointer.gestureRayPrevious.direction, Color.yellow);
					UnityEngine.Debug.DrawRay(pointer.gestureRay.origin, pointer.gestureRay.direction, Color.red);
					ControlMode current6 = controlMode.current;
					float num = ((current6 == ControlMode.MouseAndKeyboard || current6 == ControlMode.VR) ? 0.01f : 0.05f);
					bool flag = (pointer.gesturePositionViewport - pointer.gestureFirstPositionViewport).sqrMagnitude >= num * num;
					pointer.gestureMoved |= flag;
					if (!pointer.gestureLongPressFailed && !pointer.gestureLongPress)
					{
						if (pointer.gestureMoved)
						{
							pointer.gestureLongPressFailed = true;
							pointer.gestureDownToLongPress = false;
						}
						else if (pointer.gestureTimeSinceTap >= 0.25f && controlMode.current != ControlMode.VR)
						{
							pointer.gestureLongPress = true;
							pointer.gestureDownToLongPress = false;
						}
					}
					if (pointer.gestureLongPressFailed || pointer.gestureLongPress || (controlMode.current == ControlMode.MouseAndKeyboard && pointer.gestureDownToLongPress))
					{
						Vector3 vector2 = Vector3.zero;
						Vector3 vector3 = pointer.gestureMovementTotalRaw - pointer.gestureMovementTotal - pointer.gestureMovementRaw;
						float magnitude = vector3.magnitude;
						if (magnitude > 0f)
						{
							vector2 = vector3 * Mathf.Min(1f, Time.deltaTime * 1000f / magnitude);
						}
						pointer.gestureMovementScreen = pointer.gestureMovementRaw + vector2;
						pointer.gestureMovementTotal += pointer.gestureMovementScreen;
						float num2 = pointer.gestureMovementScreen.magnitude / Time.deltaTime;
						pointer.gestureSpeed = Mathf.MoveTowards(pointer.gestureSpeed, num2, Mathf.Abs(pointer.gestureSpeed - num2) * Time.deltaTime * 5f);
						pointer.gestureHighSpeed = pointer.gestureSpeed >= 1500f;
						if (pointer.gestureSpeed >= 600f)
						{
							pointer.gestureCalmTimer = -0.5f;
						}
						else
						{
							pointer.gestureCalmTimer += Time.deltaTime;
						}
						pointer.gestureCalm = pointer.gestureCalmTimer >= 0f;
					}
					pointer.gestureMovementViewport = new Vector3(pointer.gestureMovementScreen.x / (float)Screen.width, pointer.gestureMovementScreen.y / (float)Screen.height, 0f);
					pointer.gestureMovementViewportTotal += pointer.gestureMovementViewport;
				}
				if (pointerInput2.up && !pointer.hover)
				{
					pointer.gestureUp = true;
					pointersToRemove.Add(pointer);
				}
				if (pointer.hover)
				{
					pointer.gesturePositionViewport = new Vector3(inputPosition.x / (float)Screen.width, inputPosition.y / (float)Screen.height, 0f);
					pointer.gesturePositionScreen = new Vector3(inputPosition.x, inputPosition.y, 0f);
					pointer.gestureRayPrevious = pointer.gestureRay;
					pointer.gestureRay = playerCamera.ScreenPointToRay(pointer.gesturePositionScreen);
					UnityEngine.Debug.DrawRay(pointer.gestureRayPrevious.origin, pointer.gestureRayPrevious.direction, Color.yellow);
					UnityEngine.Debug.DrawRay(pointer.gestureRay.origin, pointer.gestureRay.direction, Color.red);
				}
			}
			Pointer createPointer()
			{
				Pointer pointer2 = new Pointer();
				pointer2.gestureMovementTotal = Vector3.zero;
				pointer2.gestureMovementTotalRaw = Vector3.zero;
				pointer2.gestureTimeSinceTap = 0f;
				pointer2.gestureMovementScreen = Vector3.zero;
				pointer2.gestureMovementViewport = Vector3.zero;
				pointer2.gestureMovementRaw = Vector3.zero;
				pointer2.gestureSpeed = 0f;
				pointer2.gestureHighSpeed = false;
				pointer2.gestureMoved = false;
				pointer2.gestureCalmTimer = 0f;
				pointer2.gestureShortPressFailed = false;
				pointer2.gestureLongPressFailed = false;
				pointer2.gestureLongPress = false;
				pointer2.gestureFirstPositionViewport = new Vector3(inputPosition.x / (float)Screen.width, inputPosition.y / (float)Screen.height, 0f);
				pointer2.gestureFirstPositionScreen = new Vector3(inputPosition.x, inputPosition.y, 0f);
				pointer2.gesturePositionViewport = new Vector3(inputPosition.x / (float)Screen.width, inputPosition.y / (float)Screen.height, 0f);
				pointer2.gesturePositionScreen = new Vector3(inputPosition.x, inputPosition.y, 0f);
				pointer2.gestureFirstRay = playerCamera.ScreenPointToRay(pointer2.gesturePositionScreen);
				pointer2.gestureRay = pointer2.gestureFirstRay;
				pointer2.gestureRayPrevious = pointer2.gestureFirstRay;
				UnityEngine.Debug.DrawRay(pointer2.gestureRayPrevious.origin, pointer2.gestureRayPrevious.direction, Color.yellow);
				UnityEngine.Debug.DrawRay(pointer2.gestureRay.origin, pointer2.gestureRay.direction, Color.red);
				return pointer2;
			}
		}
	}

	private void updatePointers()
	{
		foreach (Pointer pointer in pointers)
		{
			updateInteractionsForPointerBegin(pointer);
			if (controlMode.current == ControlMode.MouseAndKeyboard)
			{
				updatePCControls(pointer);
			}
			else if (controlMode.current == ControlMode.VR)
			{
				updateVRControls(pointer);
			}
			else if (controlMode.current == ControlMode.VirtualGamepad)
			{
				updateTouchControls(pointer);
			}
			else
			{
				dispatcher(pointer);
			}
			updateInteractionsForPointerEnd(pointer);
		}
	}

	private void pointerCleanup()
	{
		foreach (Pointer pointer in pointers)
		{
			if (!isPointerValid(pointer))
			{
				UnityEngine.Debug.Log("Killing invalid pointer");
				killPointer(pointer);
				clearDragLineRenderer();
			}
		}
		bool isPointerValid(Pointer pointer)
		{
			if (pointer.hover)
			{
				return true;
			}
			bool flag = true;
			string message = "";
			if (pointer.context.startingGameState != getCurrentGameState() || pointer.context.shouldKill)
			{
				message = $"POINTER NOT VALID: {pointer.context.startingGameState} {getCurrentGameState()} {pointer.hover}";
				flag = false;
			}
			if (pointer.context.targetType == ScreenTargetType.Item && !inZoomMode() && Vector3.Distance(pointer.context.currentTargetHitPoint, pointer.context.targetHitPoint) >= 0.2f)
			{
				message = "POINTER NOT VALID: Distance";
				flag = false;
			}
			if (!flag && pointer.context.doNotKill)
			{
				UnityEngine.Debug.Log("Not killing pointer because doNotKill is set");
				pointer.context.startingGameState = getCurrentGameState();
				flag = true;
			}
			if (!flag)
			{
				UnityEngine.Debug.Log(message);
			}
			return flag;
		}
	}

	public void setShouldKillPointers()
	{
		foreach (Pointer pointer in pointers)
		{
			pointer.context.shouldKill = true;
		}
	}

	public void killAllPointers()
	{
		foreach (Pointer pointer in pointers)
		{
			killPointer(pointer);
		}
	}

	public void killPointer(Pointer pointer)
	{
		if (pointer == null)
		{
			return;
		}
		if (!pointers.Contains(pointer))
		{
			UnityEngine.Debug.Log("Pointer not found in pointers list: " + pointer.gestureFingerId);
			return;
		}
		UnityEngine.Debug.Log("Killing pointer: " + pointer.gestureFingerId);
		pointer.gestureUp = true;
		gameState.changeState(pointer.context.startingGameState);
		gameState.update();
		if (pointer.context.startingGameState == GameState.Zoom)
		{
			zoomContexts.Add(zoomContextForInvalidPointer);
		}
		PointerContext context = pointer.context.copy();
		updateInteractionsForPointerBegin(pointer);
		pointer.context = context;
		dispatcher(pointer);
		updateInteractionsForPointerEnd(pointer);
		removeInteractiveHighlight();
		if (pointer.context.startingGameState == GameState.Zoom)
		{
			zoomContexts.Remove(zoomContextForInvalidPointer);
		}
		recalculateGameState();
		pointersToRemove.Add(pointer);
	}

	private void clearRemovingPointers()
	{
		foreach (Pointer item in pointersToRemove)
		{
			pointers.Remove(item);
		}
		pointersToRemove.Clear();
	}

	private void clearAllPointers()
	{
		pointers.Clear();
	}

