			bool flag7 = interactive4 != null && interactive4.isInternallyTargetable;
			bool flag8 = (interactive4 != null && !isAnyOtherPlayerInteracting(interactive4.gameObject)) || interactive4 is Zoomable;
			bool flag9 = interactive4 != null && !hasDeferred(interactive4);
			bool flag10 = interactive4 != null && !endInteractionUnconfirmedInteractives.Contains(interactive4);
			if (num6 && flag7 && flag8 && flag9 && flag10)
			{
				ItemCheck itemCheck = interactive4.itemCheck(item3);
				result = ((item3 == null) ? (itemCheck == ItemCheck.NotRequired) : (itemCheck == ItemCheck.Passes));
			}
			if (interactive4 != null && interactive4 is CharacterModels)
			{
				Vector2 a = new Vector2(interactive4.transform.position.x, interactive4.transform.position.z);
				Vector2 b = new Vector2(playerCamera.transform.position.x, playerCamera.transform.position.z);
				if (Vector2.Distance(a, b) < 0.75f)
				{
					result = false;
				}
			}
			return result;
		}
		(Interactive, InteractiveAnnotation) processInteractiveHitResults(int num6, RaycastHit[] hits, Item item3, ref Vector3 resultPoint, ref Vector3 resultNormal, ref float resultDistance, ref bool resultTargetValid)
		{
			if (interactiveHelperHit != null && item3 == null)
			{
				return (interactiveHelperHit, null);
			}
			cachedTargetStack.Clear();
			recordClickLogHeader($"Raycast: RaycastNonAlloc (Frame: {Time.frameCount}, Hits: {num6}, Item: {item3})");
			Transform transform2 = getRootTransform();
			bool flag7 = transform2 != null && isItemPinned(transform2.gameObject);
			Array.Sort(hits, 0, num6, interactiveRaycastComparer);
			Interactive interactive4 = null;
			InteractiveAnnotation item4 = null;
			for (int i = 0; i < num6; i++)
			{
				RaycastHit raycastHit = hits[i];
				if (!(raycastHit.collider.attachedRigidbody != null) || raycastHit.collider.attachedRigidbody.detectCollisions)
				{
					bool flag8 = false;
					int bestPriority2 = -1;
					Transform parent = raycastHit.collider.transform;
					if (transform2 != null)
					{
						bool flag9 = parent.IsChildOf(transform2);
						if ((flag9 && flag7) || (!flag9 && !parent.GetComponentInParent<PinnedItem>()))
						{
							continue;
						}
					}
					bool flag10 = false;
					do
					{
						cachedTargetStack.Add(parent.gameObject);
						flag10 = parent == transform2;
						bool flag11 = parent == raycastHit.collider.transform;
						Interactive interactive5 = (flag10 ? null : parent.GetComponent<Interactive>());
						if ((interactive5 != null && !interactive5.blocksRaycasts) || (!inPinModePC() && transform2 == null && interactive5 is PinnedItem))
						{
							break;
						}
						Collider component5;
						if (interactivePassesTest(interactive5, bestPriority2, item3))
						{
							bestPriority2 = interactive5.targetPriority;
							interactive4 = interactive5;
							resultPoint = raycastHit.point;
							resultNormal = raycastHit.normal;
							resultDistance = raycastHit.distance;
							resultTargetValid = true;
						}
						else if (parent.TryGetComponent<Collider>(out component5) && !component5.isTrigger && flag11)
						{
							flag8 = true;
							resultPoint = raycastHit.point;
							resultNormal = raycastHit.normal;
							resultDistance = raycastHit.distance;
							resultTargetValid = true;
						}
						parent = parent.parent;
					}
					while (!flag10 && parent != null);
					if ((bool)interactive4)
					{
						foreach (GameObject item7 in cachedTargetStack)
						{
							if (item7.TryGetComponent<InteractiveAnnotation>(out var component6) && component6.isAnnotationCompatible(interactive4.getTargetType()) && component6.targetable)
							{
								item4 = component6;
								break;
							}
						}
					}
					if (flag8 || interactive4 != null)
					{
						break;
					}
				}
			}
			return (interactive4, item4);
		}
	}

	private void updateInteractionsForPointerEnd(Pointer pointer)
	{
		if (pointer.gestureUp)
		{
			if (pointer.context.target != null && pointer.context.target.TryGetComponent<Interactive>(out var component))
			{
				component.sessionId = -1;
			}
			pointer.context.target = null;
			pointer.context.targetImpostor = null;
			pointer.context.targetType = ScreenTargetType.None;
		}
	}

	private void getObjectUnderViewportPosition(Vector3 viewportPos, out Pointer pointer)
	{
		pointer = new Pointer();
		pointer.hover = true;
		pointer.gesturePositionScreen = new Vector3((float)Screen.width * viewportPos.x, (float)Screen.height * viewportPos.y);
		pointer.gesturePositionViewport = viewportPos;
		pointer.gestureDown = true;
		pointer.gestureRayPrevious = pointer.gestureRay;
		pointer.gestureRay = playerCamera.ScreenPointToRay(pointer.gesturePositionScreen);
		updateInteractionsForPointerBegin(pointer);
		updateInteractionsForPointerEnd(pointer);
	}

