	private void updateReconnectingClient()
	{
		GamePlayerData gamePlayerData = netPlayers.Find((GamePlayerData player) => player.id == session.hostPlayerId);
		if (gamePlayerData != null)
		{
			bool activeSelf = reconnectingCanvas.activeSelf;
			float num = Time.time - gamePlayerData.lastKeepAliveTimestamp;
			reconnectingCanvas.SetActive(num > 10f);
			bool activeSelf2 = reconnectingCanvas.activeSelf;
			if (activeSelf && !activeSelf2)
			{
				UnityEngine.Debug.Log("[Level-Sync] Reconnected!");
				initLevelSync();
			}
			if (isVR() && !activeSelf && activeSelf2)
			{
				reconnectingCanvas.transform.position = vr.rig.mainMenuCanvas.transform.position;
				reconnectingCanvas.transform.rotation = Quaternion.LookRotation(reconnectingCanvas.transform.position - vr.rig.headCamera.transform.position, Vector3.up);
			}
			btnReconnectingBackToMenuController.SetActive(Controller.isActive() && num > 10f);
			btnReconnectingBackToMenu.SetActive(!Controller.isActive() && num > 10f);
			if (reconnectingCanvas.activeSelf && btnReconnectingBackToMenuController.activeSelf && Controller.getButtonDown(ControllerButtonActionType.UIBack))
			{
				quitToMenu(continueSession: false);
			}
		}
	}

