	public void initRendering()
	{
		uiCanvasScalers = new List<CanvasScaler>();
		if (levelUiCanvasScalers != null)
		{
			uiCanvasScalers.AddRange(levelUiCanvasScalers);
		}
		foreach (CustomPass customPass in afterPostProcessPassesVolume.customPasses)
		{
			if (customPass.name == "SelectionObject")
			{
				selectedInteractivePass = (PineCustomDrawOutlineGameObjects)customPass;
				selectedInteractivePass.enabled = false;
			}
			if (customPass.name == "SelectionFullscreen")
			{
				selectedInteractivePassFullscreen = (FullScreenCustomPass)customPass;
				selectedInteractivePassFullscreen.enabled = false;
			}
			if (customPass is PineCustomDrawPins pineCustomDrawPins)
			{
				customDrawPinsPass = pineCustomDrawPins;
				pineCustomDrawPins.game = this;
			}
		}
		if (Is.LowDevice)
		{
			foreach (GameObject turnOffOnLowDevice in turnOffOnLowDevices)
			{
				if (!(turnOffOnLowDevice == null))
				{
					turnOffOnLowDevice.SetActive(value: false);
					UnityEngine.Debug.Log("Disabled game-object '" + turnOffOnLowDevice.name + "' defined in 'turnOffOnLowDevices'.", turnOffOnLowDevice);
				}
			}
		}
		else if (isAnyPlayerOnLowDevice())
		{
			foreach (GameObject turnOffOnLowDevice2 in turnOffOnLowDevices)
			{
				if (!(turnOffOnLowDevice2 == null) && isNetworked(turnOffOnLowDevice2))
				{
					turnOffOnLowDevice2.SetActive(value: false);
				}
			}
		}
		if (Is.LowDevice)
		{
			foreach (GameObject turnOnOnLowDevice in turnOnOnLowDevices)
			{
				if (!(turnOnOnLowDevice == null))
				{
					turnOnOnLowDevice.SetActive(value: true);
					UnityEngine.Debug.Log("Enabled game-object '" + turnOnOnLowDevice.name + "' defined in 'turnOnOnLowDevices'.", turnOnOnLowDevice);
				}
			}
		}
		QualitySettings.globalTextureMipmapLimit = (int)getProperSettings().playerTextureLevel;
		UnityEngine.Debug.Log("Device Detected: " + SystemInfo.deviceModel + ", applying settings: \n- deviceFrameRateMax = " + deviceFrameRateMax + "\n- deviceAntiAliasingMax = " + deviceAntiAliasingMax + "\n");
		syncQualitySettings();
	}

