	private void updateRendering()
	{
		if (!qualitySettingsReduced && PlayerSave.getSettings().reduceSettingsOnLowFrameRate && UnityEngine.Application.isFocused)
		{
			float num = Time.realtimeSinceStartup - lastRealtimeSinceStartup;
			lastRealtimeSinceStartup = Time.realtimeSinceStartup;
			frameTimingRingBuffer[frameTimingCounter % frameTimingRingBuffer.Length] = num;
			frameTimingCounter++;
			if (Time.timeSinceLevelLoad > 5f && frameTimingCounter > frameTimingRingBuffer.Length)
			{
				int num2 = 0;
				for (int i = 0; i < frameTimingRingBuffer.Length; i++)
				{
					if ((double)frameTimingRingBuffer[i] < 0.05)
					{
						num2++;
					}
				}
				if ((float)num2 / (float)frameTimingRingBuffer.Length < 0.2f)
				{
					UnityEngine.Debug.Log("Reducing quality settings due to perf issues");
					syncQualitySettings();
					qualitySettingsReduced = true;
				}
			}
		}
		if (Time.time - thermalStateLastCheck >= 5f)
		{
			thermalStateLastCheck = Time.time;
		}
		_ = PlayerSave.getSettings().hoverEffectType;
		vr.isActive();
		switch (PlayerSave.getSettings().hdrpResolutionScaling)
		{
		case ResolutionScaling.Automatic:
			PineHDDynamicResolution.forcedScaleFactor = -1f;
			break;
		case ResolutionScaling.Fixed:
			PineHDDynamicResolution.forcedScaleFactor = PlayerSave.getSettings().hdrpResolutionScalingFixed;
			break;
		default:
			PineHDDynamicResolution.forcedScaleFactor = 1f;
			break;
		}
	}

	private void disableQualityManagement()
	{
		thermalsEnabled = false;
		respectDeviceMax = false;
		syncQualitySettings();
	}

	public void syncPostExposure()
	{
		if (globalSettingsVolume.profile.TryGet<ColorAdjustments>(out var component))
		{
			component.postExposure.value = PlayerSave.getSettings().hdrpPostExposure;
		}
	}

	public void syncQualitySettings()
	{
		screenPercentage = playerScreenPercentage;
		if (thermalsEnabled)
		{
			screenPercentage = Mathf.Min(screenPercentage, thermalScreenPercentage);
		}
		if (respectDeviceMax)
		{
			screenPercentage = Mathf.Min(screenPercentage, deviceScreenPercentageMax);
		}
		if (thermalsEnabled)
		{
			QualitySettings.antiAliasing = Mathf.Min(QualitySettings.antiAliasing, thermalAntiAliasing);
		}
		if (respectDeviceMax)
		{
			QualitySettings.antiAliasing = Mathf.Min(QualitySettings.antiAliasing, deviceAntiAliasingMax);
		}
		syncPostExposure();
		HDAdditionalCameraData component = playerCamera.GetComponent<HDAdditionalCameraData>();
		component.renderingPathCustomFrameSettings.SetEnabled(FrameSettingsField.MotionBlur, PlayerSave.getSettings().hdrpMotionBlur);
		component.renderingPathCustomFrameSettings.SetEnabled(FrameSettingsField.SSAO, PlayerSave.getSettings().hdrpScreenSpaceAmbientOcclusion);
		component.renderingPathCustomFrameSettings.SetEnabled(FrameSettingsField.SSR, PlayerSave.getSettings().hdrpScreenSpaceReflections && !isCustomLevel());
		component.renderingPathCustomFrameSettings.SetEnabled(FrameSettingsField.Bloom, PlayerSave.getSettings().hdrpBloom);
		component.renderingPathCustomFrameSettings.SetEnabled(FrameSettingsField.Volumetrics, PlayerSave.getSettings().hdrpVolumetrics);
		component.renderingPathCustomFrameSettings.SetEnabled(FrameSettingsField.Decals, PlayerSave.getSettings().hdrpDecals);
		component.renderingPathCustomFrameSettings.maximumLODLevelMode = MaximumLODLevelMode.OverrideQualitySettings;
		component.renderingPathCustomFrameSettings.maximumLODLevel = PlayerSave.getSettings().hdrpGeometry;
		if (gameState.current != GameState.Zoom && (!setupAntialiasing || prevAntialiasingMode != PlayerSave.getSettings().hdrpAntialiasingMode))
		{
			component.antialiasing = PlayerSave.getSettings().hdrpAntialiasingMode;
			prevAntialiasingMode = PlayerSave.getSettings().hdrpAntialiasingMode;
			setupAntialiasing = true;
		}
		foreach (CanvasScaler uiCanvasScaler in uiCanvasScalers)
		{
			uiCanvasScaler.referenceResolution = new Vector2(1920f / PlayerSave.getSettings().uiScaling, 1080f / PlayerSave.getSettings().uiScaling);
		}
	}

	private void initRolePicking()
	{
		if (roles.Count == 0)
		{
			spawnToPoint();
			return;
		}
		List<GamePlayerData> allPlayers = getAllPlayers();
		playerRoles = new Dictionary<NetPlayerId, Role>();
		foreach (GamePlayerData item in allPlayers)
		{
			UnityEngine.Debug.Log("Player: " + item.id);
			playerRoles.Add(item.id, null);
		}
		if (getPlayerCount() <= roles[0].spawnPoints.Count)
		{
			UnityEngine.Debug.Log("Not enough players for picking roles. All players spawned to role " + roles[0].roleName);
			chosenRole = roles[0];
			foreach (GamePlayerData item2 in allPlayers)
			{
				playerRoles[item2.id] = roles[0];
			}
			spawnToPoint();
			return;
		}
		GameObject gameObject = UnityEngine.Object.Instantiate(Resources.Load<GameObject>("RolePicking/RolePickerPrefab"), levelContainer.transform);
		gameObject.name = "Role Picker";
		gameObject.transform.localPosition = new Vector3(0f, -500f, 0f);
		rolePicker = gameObject.GetComponent<RolePicker>();
		teleportPlayer(gameObject.transform.position);
		rolePicker.currentPlayerNums = new List<int>();
		rolePicker.spotsToFill = new List<int>();
		int count = allPlayers.Count;
		int num = 0;
		for (int i = 0; i < rolePicker.spawnPointPlace.Count; i++)
		{
			if (i < roles.Count)
			{
				rolePicker.roleNameTexts[i].text = roles[i].roleName;
				rolePicker.currentPlayerNums.Add(0);
				rolePicker.spotsToFill.Add(0);
				int num2 = count - num;
				if (num2 > 0 && i < roles.Count)
				{
					int num3 = ((num2 < roles[i].spawnPoints.Count) ? num2 : roles[i].spawnPoints.Count);
					num += num3;
					rolePicker.spotsToFill[i] = num3;
					rolePicker.playerNumTexts[i].text = "0/" + num3;
				}
			}
			bool active = i < rolePicker.spotsToFill.Count && rolePicker.spotsToFill[i] > 0;
			rolePicker.spawnPointPlace[i].gameObject.SetActive(active);
		}
		if (num < count)
		{
			rolePicker.spotsToFill[0] += count - num;
			rolePicker.playerNumTexts[0].text = "0/" + rolePicker.spotsToFill[0];
		}
	}

	private void updateRolePicking()
	{
		if (rolePicker == null || !rolePicker.gameObject.activeInHierarchy)
		{
			return;
		}
		List<GamePlayerData> allPlayers = getAllPlayers();
		if (playerRoles.Count != allPlayers.Count)
		{
			List<NetPlayerId> list = new List<NetPlayerId>();
			foreach (KeyValuePair<NetPlayerId, Role> playerRole in playerRoles)
			{
				if (!allPlayers.Exists((GamePlayerData p) => p.id == playerRole.Key))
				{
					list.Add(playerRole.Key);
				}
			}
			foreach (NetPlayerId item in list)
			{
				playerRoles.Remove(item);
			}
		}
		foreach (GamePlayerData item2 in allPlayers)
		{
			int closestRoleForPlayer = getClosestRoleForPlayer(item2);
			int num = roles.IndexOf(playerRoles[item2.id]);
			if (closestRoleForPlayer == num)
			{
				continue;
			}
			if (closestRoleForPlayer >= 0)
			{
				if (item2.id == localPlayerData.id)
				{
					chosenRole = roles[closestRoleForPlayer];
					UnityEngine.Debug.Log($"Player {localPlayerData.id} chose Role: {chosenRole.roleName}");
				}
				playerRoles[item2.id] = roles[closestRoleForPlayer];
				updateRoleText();
			}
			else
			{
				if (item2.id == localPlayerData.id)
				{
					chosenRole = null;
				}
				playerRoles[item2.id] = null;
				updateRoleText();
			}
		}
		if (allChoseStartTime != -1f && Time.time - allChoseStartTime >= 5f)
		{
			allChoseStartTime = -1f;
			rolePicker.gameObject.SetActive(value: false);
			spawnToPoint();
		}
		if (allPlayersInRoles())
		{
			if (allChoseStartTime == -1f)
			{
				allChoseStartTime = Time.time;
			}
		}
		else
		{
			allChoseStartTime = -1f;
		}
	}

	private int getClosestRoleForPlayer(GamePlayerData player)
	{
		int result = -1;
		for (int i = 0; i < roles.Count; i++)
		{
			float num = ((isSplitscreen && session.netMode == NetMode.Client) ? getSplitscreenPositionOffset() : 0f);
			if (Vector3.Distance(player.lastTransformPose.position, rolePicker.spawnPointPlace[i].transform.position - Vector3.forward * num) <= 0.5f && (playerRoles[player.id] == roles[i] || rolePicker.currentPlayerNums[i] < rolePicker.spotsToFill[i]))
			{
				result = i;
				break;
			}
		}
		return result;
	}

	private void updateRoleText()
	{
		for (int i = 0; i < roles.Count; i++)
		{
			rolePicker.currentPlayerNums[i] = getPlayerCountInRole(i);
			rolePicker.playerNumTexts[i].text = rolePicker.currentPlayerNums[i] + "/" + rolePicker.spotsToFill[i];
		}
	}

	private List<NetPlayerId> getPlayersInRole(Role role)
	{
		List<NetPlayerId> list = new List<NetPlayerId>();
		if (playerRoles == null)
		{
			list.Add(localPlayerData.id);
		}
		else
		{
			foreach (KeyValuePair<NetPlayerId, Role> playerRole in playerRoles)
			{
				if (playerRole.Value == role)
				{
					list.Add(playerRole.Key);
				}
			}
		}
		return list;
	}

	private int getPlayerCountInRole(int roleIndex)
	{
		int num = 0;
		foreach (KeyValuePair<NetPlayerId, Role> playerRole in playerRoles)
		{
			if (playerRole.Value == roles[roleIndex])
			{
				num++;
			}
		}
		return num;
	}

	private bool allPlayersInRoles()
	{
		bool flag = true;
		foreach (KeyValuePair<NetPlayerId, Role> playerRole in playerRoles)
		{
			bool flag2 = !UnityUtils.closeEnough(getAllPlayers().Find((GamePlayerData p) => p.id == playerRole.Key).lastTransformPose.position.y, -500f, 1f);
			flag &= playerRole.Value != null || flag2;
		}
		return flag;
	}

	private void spawnToPoint()
	{
		if (roles.Count > 0)
		{
			UnityEngine.Debug.Log("Using new spawn points");
			UnityEngine.Debug.Log("selected role: " + chosenRole?.roleName);
			Role role = chosenRole ?? roles[0];
			List<NetPlayerId> playersInRole = getPlayersInRole(role);
			playersInRole.Sort();
			int index = playersInRole.IndexOf(localPlayerData.id) % role.spawnPoints.Count;
			UnityEngine.Debug.Log(localPlayerData.id?.ToString() + ": " + index);
			Transform point = role.spawnPoints[index].point;
			if (point != null)
			{
				spawnLocalPlayer(point, null);
			}
			CharacterPose assignedPose = role.spawnPoints[index].assignedPose;
			if (assignedPose != null)
			{
				handlePoseEnterLocal(assignedPose, transitionIn: false);
			}
		}
		else if (spawnPointsParent != null)
		{
			spawnPlayersByHost();
		}
		else
		{
			UnityEngine.Debug.LogWarning("SpawnPoints not found in scene");
		}
	}

	private void spawnPlayersByHost()
	{
		if (isSplitscreen)
		{
			spawnPlayerByHost(session.localPlayerId);
		}
		else
		{
			if (!isHost() && getPlayerCount() > 1)
			{
				return;
			}
			List<NetPlayerId> list = new List<NetPlayerId>(session.players.Count);
			foreach (NetPlayerData player in session.players)
			{
				if (!session.isLocalPlayer(player.id))
				{
					list.Add(player.id);
				}
			}
			list.Shuffle();
			list.Insert(0, session.localPlayerId);
			foreach (NetPlayerId item in list)
			{
				spawnPlayerByHost(item);
			}
		}
	}

	private void spawnPlayerByHost(NetPlayerId playerId)
	{
		if (persistentPlayers.Exists((PersistentPlayerData player) => player.id == playerId))
		{
			UnityEngine.Debug.Log(string.Format("[{0}] Player {1} (ID: {2}) is persistent, skipping spawn.", "spawnPlayerByHost", session.getUsername(playerId), playerId));
			return;
		}
		int num = assignSpawnPointToPlayer(playerId);
		UnityEngine.Debug.Log(string.Format("[{0}] Player {1} (ID: {2}) assigned spawn index {3}.", "spawnPlayerByHost", session.getUsername(playerId), playerId, num));
		if (num == -1)
		{
			return;
		}
		Transform child = spawnPointsParent.GetChild(num % spawnPointsParent.childCount);
		SpawnPointToPose component = child.GetComponent<SpawnPointToPose>();
		if (session.isLocalPlayer(playerId))
		{
			spawnLocalPlayer(child, component);
			return;
		}
		GamePlayerData gamePlayerData = netPlayers.Find((GamePlayerData playerData) => playerData.id == playerId);
		if (gamePlayerData != null)
		{
			gamePlayerData.lastTransformPose.position = child.position;
			gamePlayerData.currentRotation = new Vector2(child.rotation.eulerAngles.y, child.rotation.eulerAngles.x);
			if (component != null && component.characterPose != null && component.active)
			{
				CharacterPoseContext characterPoseContext = new CharacterPoseContext
				{
					pose = component.characterPose,
					poseState = CharacterPoseState.TransitionIn,
					transitionInPosition = gamePlayerData.lastTransformPose.position,
					transitionInRotation = gamePlayerData.lastTransformPose.rotation,
					pivotRotation = component.characterPose.eyeRotation,
					currentRotationOffset = Vector2.zero,
					transitionIn = false,
					lastPlayerPosition = gamePlayerData.lastTransformPose.position,
					lastPlayerRotation = targetRotation
				};
				component.characterPose.backgroundUpdate = true;
				gamePlayerData.characterPoseContext = characterPoseContext;
			}
			else
			{
				gamePlayerData.characterPoseContext = CharacterPoseContext.None;
			}
		}
		else
		{
			UnityEngine.Debug.LogError($"Could not find player data for player {session.getUsername(playerId)} (ID: {playerId})");
		}
	}

	private void spawnLocalPlayer(Transform spawnPoint, SpawnPointToPose toPose)
	{
		if (isHost() && (saveSystemLoadLatestSaveLevelId != null || loadLatestSave))
		{
			return;
		}
		if (isCustomLevel())
		{
			teleportPlayer(spawnPoint.position, spawnPoint.rotation.eulerAngles);
			if (spawnPoint.TryGetComponent<global::SpawnPoint>(out var component))
			{
				UnityEngine.Debug.Log($"Spawning on spawn point. Walk speed: {component.walkingSpeed} | Run speed: {component.runningSpeed}");
				localPlayerData.speedWalking = component.walkingSpeed;
				localPlayerData.speedRunning = component.runningSpeed;
			}
		}
		else
		{
			Vector3 eulerAngles = Quaternion.LookRotation(((spawnPointsLookTarget != null) ? spawnPointsLookTarget.position : levelContainerTransform.position) - spawnPoint.transform.position, Vector3.up).eulerAngles;
			eulerAngles.x = Mathf.DeltaAngle(0f, eulerAngles.x);
			teleportPlayer(spawnPoint.position, new Vector2(eulerAngles.x, eulerAngles.y));
			if (toPose != null && toPose.characterPose != null)
			{
				handlePoseEnterLocal(toPose.characterPose, transitionIn: false);
			}
		}
	}

	private int assignSpawnPointToPlayer(NetPlayerId playerId)
	{
		if (playerId == null)
		{
			UnityEngine.Debug.LogError("Cannot assign spawn point to null player.");
			return -1;
		}
		for (int i = 0; i < playersOnSpawnPoints.Length; i++)
		{
			if (playersOnSpawnPoints[i] == playerId)
			{
				UnityEngine.Debug.LogError(string.Format("[{0}] Already assigned spawn point to player {1} at index {2}.", "assignSpawnPointToPlayer", playerId, i));
				return i;
			}
			if (!(playersOnSpawnPoints[i] != null))
			{
				playersOnSpawnPoints[i] = playerId;
				return i;
			}
		}
		return -1;
	}

	private int getSpawnPointIndexForPlayer(NetPlayerId playerId)
	{
		if (playerId == null)
		{
			UnityEngine.Debug.LogError("Cannot get spawn point for null player.");
			return -1;
		}
		for (int i = 0; i < playersOnSpawnPoints.Length; i++)
		{
			if (playersOnSpawnPoints[i] == playerId)
			{
				return i;
			}
		}
		return -1;
	}

	private void removeSpawnPointFromPlayer(NetPlayerId playerId)
	{
		for (int i = 0; i < playersOnSpawnPoints.Length; i++)
		{
			if (!(playersOnSpawnPoints[i] != playerId))
			{
				playersOnSpawnPoints[i] = null;
			}
		}
	}

	private int getPointIndexForPlayer(NetPlayerId playerId, int numberOfPoints)
	{
		List<NetPlayerId> list = new List<NetPlayerId>();
		foreach (NetPlayerData player in session.players)
		{
			list.Add(player.id);
		}
		list.Sort();
		int num = list.IndexOf(playerId);
		if (num == -1)
		{
			UnityEngine.Debug.LogError("Player not found in session");
			return 0;
		}
		return num % numberOfPoints;
	}

	public int getId(GameObject levelObject)
	{
		return levelObjectToId.GetValueOrDefault(levelObject, -1);
	}

	public GameObject getLevelObject(int id)
	{
		return idToLevelObject.GetValueOrDefault(id, null);
	}

	public void setParent(Transform target, Transform newParent, bool worldPositionStays = true)
	{
		target.SetParent(newParent, worldPositionStays);
		if (saveableTransformParentIds != null)
		{
			int num = saveableTransforms.IndexOf(target);
			if (num >= 0)
			{
				saveableTransformParentIds[num] = ((newParent != null) ? getId(newParent.gameObject) : (-1));
			}
		}
	}

	private void initSaveSystem()
	{
		Stopwatch stopwatch = Stopwatch.StartNew();
		saveSystemSteps = new List<(Action<FastBinaryWriter>, Action<FastBinaryReader>)>
		{
			(saveHeader, loadHeader),
			(saveMaterialStates, loadMaterialStates),
			(saveTweenStates, loadTweenStates),
			(saveSequences, loadSequences),
			(saveTimers, loadTimers),
			(saveAnimations, loadAnimations),
			(saveGameObjects, loadGameObjects),
			(saveTransformParents, loadTransformParents),
			(saveTransforms, loadTransforms),
			(saveParticleSystems, loadParticleSystems),
			(saveVisualEffects, loadVisualEffects),
			(saveLineRenderers, loadLineRenderers),
			(saveSaveables, loadSaveables),
			(savePaintableTextures, loadPaintableTextures),
			(saveLevelLogic, loadLevelLogic),
			(saveTrashcan, loadTrashcan),
			(saveGame, loadGame),
			(saveHintSystem, loadHintSystem),
			(saveEnabledComponents, loadEnabledComponents),
			(saveTexts, loadTexts),
			(saveImages, loadImages),
			(saveSpriteRenderers, loadSpriteRenderers),
			(saveLua, loadLua),
			(savePlayers, loadPlayers)
		};
		saveSystemTransformAccessArray = new TransformAccessArray(saveableTransforms.ToArray());
		saveSystemTransformLocalPositions = new NativeArray<Vector3>(saveableTransforms.Count, Allocator.Persistent);
		saveSystemTransformLocalRotations = new NativeArray<Quaternion>(saveableTransforms.Count, Allocator.Persistent);
		saveSystemTransformLocalScales = new NativeArray<Vector3>(saveableTransforms.Count, Allocator.Persistent);
		initSaveSystemWriter();
		initSaveSystemLevelObjects();
		initSaveSystemSaveableObjects();
		UnityEngine.Debug.Log(string.Format("[{0}] Initialized in {1} ms.", "initSaveSystem", stopwatch.Elapsed.TotalMilliseconds));
	}

	private void initSaveSystemWriter()
	{
		if (!saveSystemWriter.IsInitialized)
		{
			saveSystemWriter = new FastBinaryWriter(65536, 1048576, Allocator.Persistent);
			if (saveSystemWriter.IsInitialized)
			{
				UnityEngine.Debug.Log(string.Format("[{0}] Initialized writer with {1} bytes.", "initSaveSystemWriter", 65536));
			}
			else
			{
				UnityEngine.Debug.LogError("[initSaveSystemWriter] Writer was not initialized properly.");
			}
			lastSaveSystemWriterInitTime = Time.time;
		}
	}

	private void initSaveSystemLevelObjects()
	{
		Dictionary<GameObject, int> dictionary = new Dictionary<GameObject, int>();
		for (int i = 0; i < persistentIdDatabase.Count; i++)
		{
			GameObject gameObject = persistentIdDatabase[i];
			if (gameObject != null)
			{
				dictionary[gameObject] = i;
			}
		}
		bool flag = Is.LowDevice && isCustomLevel();
		if (Is.Oculus && vrOculusCullingDistance > 0f)
		{
			flag = true;
			cullingDistance = vrOculusCullingDistance;
		}
		bool flag2 = persistentIdDatabase.Count == 0 || isCustomLevel();
		int num = ((!flag2) ? persistentIdDatabase.Count : 0);
		Stack<Transform> stack = new Stack<Transform>();
		stack.Push(levelContainerTransform);
		levelObjectToId.Clear();
		idToLevelObject.Clear();
		while (stack.Count > 0)
		{
			Transform transform = stack.Pop();
			GameObject gameObject2 = transform.gameObject;
			int value = num;
			if (flag2)
			{
				num++;
			}
			else if (!dictionary.TryGetValue(gameObject2, out value))
			{
				value = num++;
			}
			levelObjectToId[gameObject2] = value;
			idToLevelObject[value] = gameObject2;
			if (flag)
			{
				addOccludeeIfNeeded(gameObject2);
			}
			for (int num2 = transform.childCount - 1; num2 >= 0; num2--)
			{
				stack.Push(transform.GetChild(num2));
			}
		}
		UnityEngine.Debug.Log(string.Format("[{0}] Initialized {1} level-objects.", "initSaveSystemLevelObjects", levelObjectToId.Count));
	}

	private void initSaveSystemSaveableObjects()
	{
		saveables.Clear();
		for (int i = 0; i < saveableComponents.Count; i++)
		{
			Component component = saveableComponents[i];
			if (component == null)
			{
				UnityEngine.Debug.LogError(string.Format("{0}.{1}[{2}] is null. Please save scene to recalculate all save-system structures.", "GameStarter", "saveableComponents", i));
			}
			else if (!(component is ISaveable item))
			{
				UnityEngine.Debug.LogError(string.Format("Component '{0}' does not implement '{1}' interface.", component, "ISaveable"), component);
			}
			else
			{
				saveables.Add(item);
			}
		}
		HashSet<Type> hashSet = new HashSet<Type>();
		foreach (ISaveable saveable in saveables)
		{
			hashSet.Add(saveable.GetType());
		}
		saveableTransformParentIds = new int[saveableTransforms.Count];
		for (int j = 0; j < saveableTransforms.Count; j++)
		{
			Transform parent = saveableTransforms[j].parent;
			saveableTransformParentIds[j] = ((parent != null) ? getId(parent.gameObject) : (-1));
		}
		UnityEngine.Debug.Log(string.Format("[{0}] Found {1} '{2}' components:\n{3}", "initSaveSystemSaveableObjects", saveables.Count, "ISaveable", string.Join("\n", saveables)));
		UnityEngine.Debug.Log(string.Format("[{0}] Found {1} distinct '{2}' types:\n{3}", "initSaveSystemSaveableObjects", hashSet.Count, "ISaveable", string.Join("\n", hashSet)));
	}

	private void updateSaveSystem()
	{
		if (!isHost())
		{
			return;
		}
		if ((saveSystemLoadLatestSaveLevelId != null && levelIdentifier == saveSystemLoadLatestSaveLevelId) || loadLatestSave)
		{
			UnityEngine.Debug.Log("[updateSaveSystem] Loading latest save for level '" + levelIdentifier + "'.");
			loadLevel(getLatestSaveForLevel(levelIdentifier));
			saveSystemLoadLatestSaveLevelId = null;
			loadLatestSave = false;
		}
		if (levelReadyProcessCompleted)
		{
			if (autosavePuzzleSolved)
			{
				autosaveLevel();
				autosavePuzzleSolved = false;
			}
			loadedSavePlayTime += Time.deltaTime;
			autosaveTimer += Time.deltaTime;
			if (autosaveTimer >= 60f)
			{
				autosaveLevel();
			}
		}
		void autosaveLevel()
		{
			if (isLobby())
			{
				return;
			}
			try
			{
				saveLevel(shouldWriteToDisk: true);
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Exception while auto-saving: " + ex.Message);
				UnityEngine.Debug.LogException(ex);
			}
		}
	}

	public byte[] saveLevel(bool shouldWriteToDisk)
	{
		if (!isSaveSystemEnabledFor(SceneManager.GetActiveScene().name))
		{
			UnityEngine.Debug.LogError("Cannot save as save-system is not enabled for active scene '" + SceneManager.GetActiveScene().name + "'!");
			return null;
		}
		if (!UnityEngine.Application.isPlaying)
		{
			UnityEngine.Debug.LogError("Saving can only be performed while playing!");
			return null;
		}
		if (!saveSystemWriter.IsInitialized)
		{
			if (Time.time - lastSaveSystemWriterInitTime < 10f)
			{
				return null;
			}
			initSaveSystemWriter();
			if (!saveSystemWriter.IsInitialized)
			{
				return null;
			}
		}
		if (!isHost())
		{
			autosaveTimer = 60f;
			return null;
		}
		autosaveTimer = 0f;
		Dictionary<GameObject, (Transform, Vector3, Quaternion, Vector3)> dictionary = new Dictionary<GameObject, (Transform, Vector3, Quaternion, Vector3)>();
		foreach (ZoomContext zoomContext in zoomContexts)
		{
			GameObject selected = zoomContext.selected;
			if (!(selected == null))
			{
				Transform transform = selected.transform;
				if (!(transform == null))
				{
					dictionary.Add(selected, (transform.parent, transform.position, transform.rotation, transform.localScale));
					setParent(transform, zoomContext.originalParent);
					transform.position = zoomContext.originalPosition;
					transform.rotation = zoomContext.originalRotation;
					transform.localScale = zoomContext.originalLocalScale;
				}
			}
		}
		Dictionary<GameObject, bool> dictionary2 = new Dictionary<GameObject, bool>();
		foreach (GamePlayerData netPlayer in netPlayers)
		{
			if (!(netPlayer.zoomItem == null))
			{
				dictionary2[netPlayer.zoomItem] = netPlayer.zoomItem.activeSelf;
				netPlayer.zoomItem.SetActive(value: true);
				netPlayer.interactingObjects.Remove(netPlayer.zoomItem);
			}
		}
		Dictionary<Item, bool> dictionary3 = new Dictionary<Item, bool>();
		foreach (GamePlayerData allPlayer in getAllPlayers())
		{
			if (!(allPlayer.carriableItem == null))
			{
				dictionary3[allPlayer.carriableItem] = allPlayer.carriableItem.gameObject.activeSelf;
				allPlayer.carriableItem.gameObject.SetActive(value: true);
				allPlayer.interactingObjects.Remove(allPlayer.carriableItem.gameObject);
			}
		}
		ExtractTransformDataJob jobData = new ExtractTransformDataJob
		{
			localPositions = saveSystemTransformLocalPositions,
			localRotations = saveSystemTransformLocalRotations,
			localScales = saveSystemTransformLocalScales
		};
		extractTransformDataJobHandle = jobData.Schedule(saveSystemTransformAccessArray);
		Stopwatch stopwatch = Stopwatch.StartNew();
		StringBuilder saveStepsLogger = new StringBuilder().AppendLine();
		double num = 0.0;
		saveSystemWriter.Reset();
		int position = saveSystemWriter.Position;
		foreach (var saveSystemStep in saveSystemSteps)
		{
			double totalMilliseconds = stopwatch.Elapsed.TotalMilliseconds;
			saveSystemStep.saveStep(saveSystemWriter);
			double num2 = stopwatch.Elapsed.TotalMilliseconds - totalMilliseconds;
			num += num2;
			saveStepsLogger.AppendLine($"{saveSystemStep.saveStep.Method.Name,-32} {num2:F3} ms {saveSystemWriter.Position - position,8} bytes");
			position = saveSystemWriter.Position;
		}
		foreach (var (gameObject2, tuple2) in dictionary)
		{
			setParent(gameObject2.transform, tuple2.Item1);
			gameObject2.transform.position = tuple2.Item2;
			gameObject2.transform.rotation = tuple2.Item3;
			gameObject2.transform.localScale = tuple2.Item4;
		}
		foreach (GamePlayerData netPlayer2 in netPlayers)
		{
			if (!(netPlayer2.zoomItem == null))
			{
				netPlayer2.zoomItem.SetActive(dictionary2.GetValueOrDefault(netPlayer2.zoomItem, defaultValue: false));
				netPlayer2.interactingObjects.Add(netPlayer2.zoomItem);
			}
		}
		foreach (GamePlayerData allPlayer2 in getAllPlayers())
		{
			if (!(allPlayer2.carriableItem == null))
			{
				allPlayer2.carriableItem.gameObject.SetActive(dictionary3.GetValueOrDefault(allPlayer2.carriableItem, defaultValue: false));
				allPlayer2.interactingObjects.Add(allPlayer2.carriableItem.gameObject);
			}
		}
		saveStepsLogger.AppendLine($"{Environment.NewLine}Performed all save steps in {num:F3} ms.");
		byte[] levelSaveBytes = saveSystemWriter.ToArray();
		if (shouldWriteToDisk)
		{
			UnityEngine.Debug.Log($"Starting async save operation after {stopwatch.Elapsed.TotalMilliseconds} ms...");
			if (loadedSaveFilePath == null)
			{
				writeNewSaveFileAsync();
			}
			else
			{
				overwriteLoadedSaveFileAsync();
			}
		}
		return levelSaveBytes;
		async void overwriteLoadedSaveFileAsync()
		{
			try
			{
				string tempFilePath = Path.ChangeExtension(loadedSaveFilePath, ".bak");
				await File.WriteAllBytesAsync(tempFilePath, levelSaveBytes);
				if (File.Exists(loadedSaveFilePath))
				{
					File.Delete(loadedSaveFilePath);
				}
				File.Move(tempFilePath, loadedSaveFilePath);
				UnityEngine.Debug.Log($"Saved {levelSaveBytes.Length} bytes to existing file '{loadedSaveFilePath}' in {stopwatch.Elapsed.TotalMilliseconds} ms.{saveStepsLogger}");
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogError("Exception occured while saving level '" + levelIdentifier + "'.");
				UnityEngine.Debug.LogException(exception);
			}
		}
		async void writeNewSaveFileAsync()
		{
			try
			{
				Directory.CreateDirectory(Path.Combine(levelSavesRootPath, levelIdentifier));
				loadedSaveFilePath = Path.Combine(levelSavesRootPath, levelIdentifier, string.Format("{0:yyyy-MM-dd-HH-mm-ss}.{1}", DateTime.UtcNow, "sav"));
				await File.WriteAllBytesAsync(loadedSaveFilePath, levelSaveBytes);
				UnityEngine.Debug.Log($"Saved {levelSaveBytes.Length} bytes to new file '{loadedSaveFilePath}' in {stopwatch.Elapsed.TotalMilliseconds} ms.{saveStepsLogger}");
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogError("Exception occured while saving level '" + levelIdentifier + "'.");
				UnityEngine.Debug.LogException(exception);
			}
		}
	}

	private void saveHeader(FastBinaryWriter writer)
	{
		SaveFileHeader obj = new SaveFileHeader
		{
			gameVersion = Version.fullGameVersion,
			levelVersion = RoomDatabase.getVersion(levelIdentifier),
			levelIdentifier = levelIdentifier,
			playTimeInSeconds = loadedSavePlayTime,
			lastSaveTimeInTicks = DateTime.UtcNow.Ticks
		};
		writer.Write(JsonUtility.ToJson(obj, prettyPrint: false));
	}

	private void loadHeader(FastBinaryReader reader)
	{
		loadedSavePlayTime = readSaveFileHeader(reader).playTimeInSeconds;
	}

	private void savePlayers(FastBinaryWriter writer)
	{
		writer.Write((byte)Mathf.Max(1, session.players.Count));
		writer.WriteIReadWrite(new SaveFilePlayer
		{
			id = localPlayerData.id,
			position = playerLocation,
			rotation = currentRotation,
			isCrouching = localPlayerData.lastPlayerCrouch,
			inventory = extractItemsFromInventory(inventory),
			interactingObjects = localPlayerData.interactingObjects,
			customMode = localPlayerData.customMode,
			spawnPointIndex = getSpawnPointIndexForPlayer(localPlayerData.id),
			characterPoseContext = localPlayerData.characterPoseContext,
			postProcessingData = localPlayerData.postProcessingData,
			skyData = localPlayerData.skyData,
			fogData = localPlayerData.fogData,
			cloudData = localPlayerData.cloudData,
			oceanData = localPlayerData.oceanData,
			speedWalking = localPlayerData.speedWalking,
			speedRunning = localPlayerData.speedRunning,
			ladderData = localPlayerData.ladderData
		});
		foreach (GamePlayerData netPlayer in netPlayers)
		{
			writer.WriteIReadWrite(new SaveFilePlayer
			{
				id = netPlayer.id,
				position = netPlayer.lastTransformPose.position,
				rotation = netPlayer.currentRotation,
				isCrouching = netPlayer.lastPlayerCrouch,
				inventory = netPlayer.inventory,
				interactingObjects = netPlayer.interactingObjects,
				customMode = netPlayer.customMode,
				spawnPointIndex = getSpawnPointIndexForPlayer(netPlayer.id),
				characterPoseContext = netPlayer.characterPoseContext,
				postProcessingData = netPlayer.postProcessingData,
				skyData = netPlayer.skyData,
				fogData = netPlayer.fogData,
				cloudData = netPlayer.cloudData,
				oceanData = netPlayer.oceanData,
				speedWalking = netPlayer.speedWalking,
				speedRunning = netPlayer.speedRunning,
				ladderData = netPlayer.ladderData
			});
		}
	}

	private void loadPlayers(FastBinaryReader reader)
	{
		int num = reader.ReadByte();
		List<SaveFilePlayer> list = new List<SaveFilePlayer>(num);
		for (int i = 0; i < num; i++)
		{
			list.Add(reader.ReadIReadWrite<SaveFilePlayer>());
		}
		SaveFilePlayer host = list[0];
		if (session.players.Count == 1 || (host.id == Net.SINGLEPLAYER_ID && isHost()))
		{
			host.id = localPlayerData.id;
		}
		for (int j = 0; j < playersOnSpawnPoints.Length; j++)
		{
			playersOnSpawnPoints[j] = null;
		}
		List<GamePlayerData> allPlayers = getAllPlayers();
		foreach (GamePlayerData item in allPlayers)
		{
			item.wasLoadedFromSave = false;
		}
		foreach (SaveFilePlayer player in list)
		{
			if (localPlayerData.id == player.id)
			{
				loadLocalPlayer(player);
			}
			else
			{
				loadOtherPlayer(player);
			}
			if (localPlayerData.id == host.id)
			{
				loadPlayerSpawnPoint(player);
			}
			GamePlayerData gamePlayerData = allPlayers.Find((GamePlayerData x) => x.id == player.id);
			if (gamePlayerData != null)
			{
				gamePlayerData.wasLoadedFromSave = true;
			}
		}
		void loadLocalPlayer(SaveFilePlayer saveFilePlayer)
		{
			teleportPlayer(saveFilePlayer.position, new Vector2(saveFilePlayer.rotation.y, saveFilePlayer.rotation.x));
			if (saveFilePlayer.isCrouching)
			{
				forceLocalPlayerToCrouch();
			}
			List<GameObject> list2 = new List<GameObject>();
			foreach (InventoryItem item2 in inventory)
			{
				foreach (GameObject gameObject in item2.gameObjects)
				{
					list2.Add(gameObject);
				}
			}
			foreach (GameObject item3 in list2)
			{
				if (!saveFilePlayer.inventory.Contains(item3))
				{
					removeItemFromInventory(item3, isForDrag: false, syncMultiplayer: false);
					localPlayerData.interactingObjects.Remove(item3);
				}
			}
			foreach (GameObject item4 in saveFilePlayer.inventory)
			{
				if (!isInInventory(item4))
				{
					addItemToInventory(item4);
					localPlayerData.interactingObjects.Add(item4);
				}
			}
			CustomMode customMode = localPlayerData.customMode;
			CustomMode customMode2 = saveFilePlayer.customMode;
			if (customMode == null && customMode2 != null)
			{
				handleCustomModeEnter(customMode2);
			}
			else if (customMode != null && customMode2 == null)
			{
				handleCustomModeLeave(customMode);
			}
			else if (customMode != null && customMode2 != null && customMode != customMode2)
			{
				handleCustomModeLeave(customMode);
				handleCustomModeEnter(customMode2);
			}
			CharacterPoseContext characterPoseContext = saveFilePlayer.characterPoseContext;
			if (characterPoseContext != null)
			{
				CharacterPoseState poseState = characterPoseContext.poseState;
				if (poseState == CharacterPoseState.TransitionIn || poseState == CharacterPoseState.InPose)
				{
					localPlayerData.characterPoseContext = characterPoseContext;
					startInteraction(localPlayerData.characterPoseContext.pose.gameObject);
					goto IL_0279;
				}
			}
			localPlayerData.characterPoseContext = characterPoseContext;
			goto IL_0279;
			IL_0279:
			localPlayerData.postProcessingData = saveFilePlayer.postProcessingData;
			localPlayerData.skyData = saveFilePlayer.skyData;
			if (saveFilePlayer.skyData != null)
			{
				localPlayerData.skyData.cubemapStart = editorVolumeRefs.hdriSky.hdriSky.value;
				localPlayerData.skyData.cubemapGoal = saveFilePlayer.skyData.sourceSkybox.data.tempTexture;
			}
			localPlayerData.fogData = saveFilePlayer.fogData;
			localPlayerData.cloudData = saveFilePlayer.cloudData;
			localPlayerData.oceanData = saveFilePlayer.oceanData;
			updateRoomEditorVolume();
			localPlayerData.speedWalking = saveFilePlayer.speedWalking;
			localPlayerData.speedRunning = saveFilePlayer.speedRunning;
			localPlayerData.ladderData = saveFilePlayer.ladderData;
		}
		void loadOtherPlayer(SaveFilePlayer saveFilePlayer)
		{
			GamePlayerData gamePlayerData2 = netPlayers.Find((GamePlayerData p) => p.id == saveFilePlayer.id);
			if (gamePlayerData2 != null)
			{
				gamePlayerData2.lastTransformPose.position = saveFilePlayer.position;
				gamePlayerData2.currentRotation = saveFilePlayer.rotation;
				gamePlayerData2.lastPlayerCrouch = saveFilePlayer.isCrouching;
				gamePlayerData2.inventory = saveFilePlayer.inventory;
				gamePlayerData2.interactingObjects = saveFilePlayer.interactingObjects;
				gamePlayerData2.customMode = saveFilePlayer.customMode;
				gamePlayerData2.characterPoseContext = saveFilePlayer.characterPoseContext;
				gamePlayerData2.postProcessingData = saveFilePlayer.postProcessingData;
				gamePlayerData2.skyData = saveFilePlayer.skyData;
				gamePlayerData2.fogData = saveFilePlayer.fogData;
				gamePlayerData2.cloudData = saveFilePlayer.cloudData;
				gamePlayerData2.oceanData = saveFilePlayer.oceanData;
				gamePlayerData2.speedWalking = saveFilePlayer.speedWalking;
				gamePlayerData2.speedRunning = saveFilePlayer.speedRunning;
				gamePlayerData2.ladderData = saveFilePlayer.ladderData;
			}
			else
			{
				loadOtherPlayerThatIsInSaveButNotInGame(saveFilePlayer);
			}
		}
		void loadOtherPlayerThatIsInSaveButNotInGame(SaveFilePlayer saveFilePlayer)
		{
			if (localPlayerData.id == host.id)
			{
				foreach (GameObject item5 in saveFilePlayer.inventory)
				{
					addItemToInventory(item5);
					localPlayerData.interactingObjects.Add(item5);
				}
				return;
			}
			GamePlayerData gamePlayerData2 = netPlayers.Find((GamePlayerData p) => p.id == session.hostPlayerId);
			if (gamePlayerData2 == null)
			{
				UnityEngine.Debug.LogError($"Host player not found for player (session host ID: {session.hostPlayerId}).");
				return;
			}
			foreach (GameObject item6 in saveFilePlayer.inventory)
			{
				gamePlayerData2.inventory.Add(item6);
				gamePlayerData2.interactingObjects.Add(item6);
			}
		}
		void loadPlayerSpawnPoint(SaveFilePlayer saveFilePlayer)
		{
			if (session.players.Find((NetPlayerData p) => p.id == saveFilePlayer.id) != null)
			{
				if (saveFilePlayer.spawnPointIndex < 0 || saveFilePlayer.spawnPointIndex >= playersOnSpawnPoints.Length)
				{
					UnityEngine.Debug.LogError($"Player {saveFilePlayer.id} has invalid spawn point index {saveFilePlayer.spawnPointIndex}.");
				}
				else if ((object)playersOnSpawnPoints[saveFilePlayer.spawnPointIndex] == null)
				{
					playersOnSpawnPoints[saveFilePlayer.spawnPointIndex] = saveFilePlayer.id;
				}
				else
				{
					UnityEngine.Debug.LogError($"Multiple players ({saveFilePlayer.id} and {playersOnSpawnPoints[saveFilePlayer.spawnPointIndex]}) are on the same spawn point.");
				}
			}
		}
	}

	private void saveTrashcan(FastBinaryWriter writer)
