	private void loadTrashcan(FastBinaryReader reader)
	{
		List<GameObject> list = reader.ReadList((FastBinaryReader r) => r.ReadGameObject());
		List<GameObject> list2 = extractItemsFromInventory(trashInventory);
		foreach (GameObject item in list)
		{
			if (list2.Contains(item))
			{
				list2.Remove(item);
			}
			else
			{
				addItemToTrash(item.GetComponent<Item>());
			}
		}
		foreach (GameObject item2 in list2)
		{
			removeItemFromTrash(item2.GetComponent<Item>());
		}
		syncTrashcanVisuals();
	}

	private void saveGame(FastBinaryWriter writer)
	{
		writer.Write(in timerCurrentTime, default(FastBinaryWriter.ForPrimitives));
		writer.Write(in isLevelConvertedToSinglePlayer, default(FastBinaryWriter.ForPrimitives));
		foreach (LevelPredicate levelPredicate in levelPredicates)
		{
			writer.Write(in levelPredicate.type, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in levelPredicate.done, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in levelPredicate.doneCounter, default(FastBinaryWriter.ForPrimitives));
			writer.Write(in levelPredicate.timeAccumulator, default(FastBinaryWriter.ForPrimitives));
		}
	}

	private void loadGame(FastBinaryReader reader)
	{
		timerCurrentTime = reader.ReadSingle();
		isLevelConvertedToSinglePlayer = reader.ReadBoolean();
		foreach (LevelPredicate levelPredicate2 in levelPredicates)
		{
			_ = levelPredicate2;
			int type = reader.ReadInt32();
			bool done = reader.ReadBoolean();
			int doneCounter = reader.ReadInt32();
			float timeAccumulator = reader.ReadSingle();
			LevelPredicate levelPredicate = levelPredicates.Find((LevelPredicate predicate) => predicate.type == type);
			if (levelPredicate == null)
			{
				UnityEngine.Debug.LogError($"Level predicate of type '{type}' not found while loading save-file.");
				continue;
			}
			levelPredicate.done = done;
			levelPredicate.doneCounter = doneCounter;
			levelPredicate.timeAccumulator = timeAccumulator;
		}
	}

