	private void saveLua(FastBinaryWriter writer)
	{
		foreach (LuaExecutor allLuaExecutor in allLuaExecutors)
		{
			if (!(allLuaExecutor.lua.Globals["_G"] is Table table))
			{
				continue;
			}
			int position = writer.Position;
			int value = 0;
			writer.Write(in value, default(FastBinaryWriter.ForPrimitives));
			HashSet<string> hashSet = new HashSet<string>();
			foreach (TablePair pair in table.Pairs)
			{
				if (pair.Key.Type == DataType.String && !string.IsNullOrEmpty(pair.Key.String) && !luaDontSaveKeys.Contains(pair.Key.String))
				{
					switch (pair.Value.Type)
					{
					case DataType.Boolean:
						writer.Write(pair.Key.String);
						writer.Write(2);
						writer.Write<bool>(pair.Value.Boolean, default(FastBinaryWriter.ForPrimitives));
						hashSet.Add(pair.Key.String);
						value++;
						break;
					case DataType.Number:
						writer.Write(pair.Key.String);
						writer.Write(3);
						writer.Write<double>(pair.Value.Number, default(FastBinaryWriter.ForPrimitives));
						hashSet.Add(pair.Key.String);
						value++;
						break;
					case DataType.String:
						writer.Write(pair.Key.String);
						writer.Write(4);
						writer.Write(pair.Value.String);
						hashSet.Add(pair.Key.String);
						value++;
						break;
					case DataType.Table:
						writer.Write(pair.Key.String);
						writer.Write(6);
						writeLuaTable(pair.Value.Table);
						hashSet.Add(pair.Key.String);
						value++;
						break;
					}
				}
			}
			foreach (LuaVariable initialGlobalVariable in allLuaExecutor.initialGlobalVariables)
			{
				if (!hashSet.Contains(initialGlobalVariable.name))
				{
					DynValue dynValue = table.Get(initialGlobalVariable.name);
					if (dynValue == DynValue.Nil)
					{
						writer.Write(initialGlobalVariable.name);
						writer.Write(0);
						value++;
					}
					else
					{
						UnityEngine.Debug.LogError($"Cannot save Lua variable '{initialGlobalVariable.name}'. Initial type: {initialGlobalVariable.type} | Current type: {dynValue.Type}");
					}
				}
			}
			int position2 = writer.Position;
			writer.Seek(position);
			writer.Write(in value, default(FastBinaryWriter.ForPrimitives));
			writer.Seek(position2);
		}
		void writeLuaTable(Table table2, int recursionLevel = 0)
		{
			if (recursionLevel >= 10)
			{
				UnityEngine.Debug.LogError("Reached maximum recursion level while writing a Lua table. This might indicate a circular reference or too deep nesting.");
			}
			else
			{
				int position3 = writer.Position;
				int value2 = 0;
				writer.Write(in value2, default(FastBinaryWriter.ForPrimitives));
				foreach (TablePair pair2 in table2.Pairs)
				{
					DataType type = pair2.Key.Type;
					if (type == DataType.String || type == DataType.Number)
					{
						type = pair2.Value.Type;
						if (type == DataType.String || type == DataType.Number || type == DataType.Boolean || type == DataType.Table)
						{
							writer.Write((byte)pair2.Key.Type);
							if (pair2.Key.Type == DataType.String)
							{
								writer.Write(pair2.Key.String);
							}
							if (pair2.Key.Type == DataType.Number)
							{
								writer.Write<double>(pair2.Key.Number, default(FastBinaryWriter.ForPrimitives));
							}
							writer.Write((byte)pair2.Value.Type);
							if (pair2.Value.Type == DataType.String)
							{
								writer.Write(pair2.Value.String);
							}
							if (pair2.Value.Type == DataType.Number)
							{
								writer.Write<double>(pair2.Value.Number, default(FastBinaryWriter.ForPrimitives));
							}
							if (pair2.Value.Type == DataType.Boolean)
							{
								writer.Write<bool>(pair2.Value.Boolean, default(FastBinaryWriter.ForPrimitives));
							}
							if (pair2.Value.Type == DataType.Table)
							{
								writeLuaTable(pair2.Value.Table, recursionLevel + 1);
							}
							value2++;
						}
					}
				}
				int position4 = writer.Position;
				writer.Seek(position3);
				writer.Write(in value2, default(FastBinaryWriter.ForPrimitives));
				writer.Seek(position4);
			}
		}
	}

	private void loadLua(FastBinaryReader reader)
	{
		foreach (LuaExecutor allLuaExecutor in allLuaExecutors)
		{
			LuaExecutor luaExecutor = allLuaExecutor;
			if (!(luaExecutor.lua.Globals["_G"] is Table table))
			{
				continue;
			}
			int num = reader.ReadInt32();
			for (int i = 0; i < num; i++)
			{
				string text = reader.ReadString();
				DataType dataType = (DataType)reader.ReadByte();
				switch (dataType)
				{
				case DataType.Boolean:
					table.Set(text, DynValue.NewBoolean(reader.ReadBoolean()));
					break;
				case DataType.Number:
					table.Set(text, DynValue.NewNumber(reader.ReadDouble()));
					break;
				case DataType.String:
					table.Set(text, DynValue.NewString(reader.ReadString()));
					break;
				case DataType.Nil:
					table.Set(text, DynValue.NewNil());
					break;
				case DataType.Table:
					table.Set(text, DynValue.NewTable(readLuaTable()));
					break;
				default:
					UnityEngine.Debug.LogError($"Unsupported Lua global state type {dataType} for key '{text}' in level '{levelIdentifier}'.");
					break;
				}
			}
			Table readLuaTable(int recursionLevel = 0)
			{
				if (recursionLevel >= 10)
				{
					UnityEngine.Debug.LogError("Reached maximum recursion level while writing a Lua table. This might indicate a circular reference or too deep nesting.");
					return null;
				}
				Table table2 = new Table(luaExecutor.lua);
				int num2 = reader.ReadInt32();
				for (int j = 0; j < num2; j++)
				{
					byte num3 = reader.ReadByte();
					DynValue key = DynValue.Nil;
					if (num3 == 4)
					{
						key = DynValue.NewString(reader.ReadString());
					}
					if (num3 == 3)
					{
						key = DynValue.NewNumber(reader.ReadDouble());
					}
					byte num4 = reader.ReadByte();
					DynValue value = DynValue.Nil;
					if (num4 == 4)
					{
						value = DynValue.NewString(reader.ReadString());
					}
					if (num4 == 3)
					{
						value = DynValue.NewNumber(reader.ReadDouble());
					}
					if (num4 == 2)
					{
						value = DynValue.NewBoolean(reader.ReadBoolean());
					}
					if (num4 == 6)
					{
						value = DynValue.NewTable(readLuaTable(recursionLevel + 1));
					}
					table2.Set(key, value);
				}
				return table2;
			}
		}
	}

	public void loadLevel(string saveFilePath)
	{
		if (string.IsNullOrEmpty(saveFilePath))
		{
			return;
		}
		if (!UnityEngine.Application.isPlaying)
		{
			UnityEngine.Debug.LogError("Loading can only be performed while playing!");
			return;
		}
		if (!File.Exists(saveFilePath))
		{
			UnityEngine.Debug.LogError("Could not load level from non-existing save-file '" + saveFilePath + "'!");
			return;
		}
		if (!isSaveFileCompatibleWithLevel(saveFilePath, levelIdentifier))
		{
			UnityEngine.Debug.LogError("Save-file '" + saveFilePath + "' is incompatible with current level '" + levelIdentifier + "'!");
			return;
		}
		try
		{
			loadedSaveFilePath = saveFilePath;
			loadLevel(File.ReadAllBytes(saveFilePath));
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogError("Exception occured while loading level '" + levelIdentifier + "'.");
			UnityEngine.Debug.LogException(exception);
			loadedSaveFilePath = null;
		}
	}

	private void loadLevel(byte[] saveBytes)
	{
		if (saveBytes == null)
		{
			return;
		}
		if (!UnityEngine.Application.isPlaying)
		{
			UnityEngine.Debug.LogError("Loading can only be performed while playing!");
			return;
		}
		if (saveBytes.Length == 0)
		{
			UnityEngine.Debug.LogError("Cannot load from empty 'saveBytes'!");
			return;
		}
		try
		{
			if (gameState.current == GameState.Zoom)
			{
				handleZoomLeave();
			}
			Stopwatch stopwatch = Stopwatch.StartNew();
			StringBuilder stringBuilder = new StringBuilder().AppendLine();
			double num = 0.0;
			using FastBinaryReader obj = new FastBinaryReader(saveBytes);
			int position = obj.Position;
			isLoadingSaveFile = true;
			lastLoadLevelInvocationFrame = Time.frameCount;
			foreach (var saveSystemStep in saveSystemSteps)
			{
				double totalMilliseconds = stopwatch.Elapsed.TotalMilliseconds;
				saveSystemStep.loadStep(obj);
				double num2 = stopwatch.Elapsed.TotalMilliseconds - totalMilliseconds;
				num += num2;
				stringBuilder.AppendLine($"{saveSystemStep.loadStep.Method.Name,-32} {num2:F3} ms {obj.Position - position,8} bytes");
				position = obj.Position;
			}
			clearAllPointers();
			Interactive[] array = allInteractives;
			foreach (Interactive interactive in array)
			{
				if (interactive.sessionId != -1)
				{
					handleInteractiveCancel(interactive);
				}
			}
			foreach (InventoryItem item in inventory)
			{
				foreach (GameObject gameObject in item.gameObjects)
				{
					gameObject.SetActive(value: false);
				}
			}
			initTokensInLevel();
			foreach (GamePlayerData allPlayer in getAllPlayers())
			{
				if (!allPlayer.wasLoadedFromSave)
				{
					spawnPlayerByHost(allPlayer.id);
				}
			}
			UnityEngine.Debug.Log($"Loaded {saveBytes.Length} bytes from '{loadedSaveFilePath}' in {num:F3} ms.{stringBuilder}");
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogError("Exception occured while loading level '" + levelIdentifier + "'.");
			UnityEngine.Debug.LogException(exception);
		}
		finally
		{
			isLoadingSaveFile = false;
			levelLogic.onInitAfterLoad();
		}
	}

	private static List<GameObject> extractItemsFromInventory(List<InventoryItem> inventory)
	{
		List<GameObject> list = new List<GameObject>();
		HashSet<GameObject> hashSet = new HashSet<GameObject>();
		for (int num = inventory.Count - 1; num >= 0; num--)
		{
			foreach (GameObject gameObject in inventory[num].gameObjects)
			{
				if (hashSet.Add(gameObject))
				{
					list.Add(gameObject);
				}
			}
		}
		return list;
	}

	private static bool getComponentEnabled(Component component)
	{
		if (component == null)
		{
			UnityEngine.Debug.LogError("Cannot get enabled state of null component.");
			return false;
		}
		if (component is Behaviour behaviour)
		{
			return behaviour.enabled;
		}
		if (component is Renderer renderer)
		{
			return renderer.enabled;
		}
		if (component is Collider collider)
		{
			return collider.enabled;
		}
		UnityEngine.Debug.LogError($"Could not get enabled state of component '{component}' on game-object '{component.gameObject}'.", component.gameObject);
		return false;
	}

	private static void setComponentEnabled(Component component, bool isEnabled)
	{
		if (component == null)
		{
			UnityEngine.Debug.LogError("Cannot set enabled state for null component.");
		}
		else if (component is Behaviour behaviour)
		{
			behaviour.enabled = isEnabled;
		}
		else if (component is Renderer renderer)
		{
			renderer.enabled = isEnabled;
		}
		else if (component is Collider collider)
		{
			collider.enabled = isEnabled;
		}
		else
		{
			UnityEngine.Debug.LogError($"Could not set enabled state of component '{component}' on game-object '{component.gameObject}'.", component.gameObject);
		}
	}

	public static List<SaveFileHeader> getSaveFileHeaders(string levelId = "")
	{
		if (!Directory.Exists(levelSavesRootPath))
		{
			return new List<SaveFileHeader>();
		}
		string[] files = Directory.GetFiles(levelSavesRootPath, "*.sav", SearchOption.AllDirectories);
		List<SaveFileHeader> list = new List<SaveFileHeader>();
		bool flag = !string.IsNullOrEmpty(levelId);
		string[] array = files;
		foreach (string text in array)
		{
			try
			{
				if (!flag || !(Path.GetFileName(Path.GetDirectoryName(text)) != levelId))
				{
					SaveFileHeader saveFileHeader = readSaveFileHeader(text);
					if (isSaveFileCompatibleWithLevel(saveFileHeader, flag ? levelId : saveFileHeader.levelIdentifier))
					{
						list.Add(saveFileHeader);
					}
				}
			}
			catch (Exception)
			{
			}
		}
		return list;
	}

	public static SaveFileHeader readSaveFileHeader(string saveFilePath)
	{
		if (string.IsNullOrEmpty(saveFilePath))
		{
			return null;
		}
		Span<byte> span = stackalloc byte[4];
		using FileStream fileStream = File.Open(saveFilePath, FileMode.Open);
		fileStream.Read(span);
		int num = BitConverter.ToInt32(span);
		if (num > 1024)
		{
			UnityEngine.Debug.LogError($"Suspiciously large header string length of {num} for file {saveFilePath}.");
			return null;
		}
		Span<byte> buffer = stackalloc byte[num * 2];
		fileStream.Read(buffer);
		using FastBinaryReader reader = new FastBinaryReader(buffer);
		return readSaveFileHeader(reader, num);
	}

	public static SaveFileHeader readSaveFileHeader(FastBinaryReader reader, int length = 0)
	{
		return JsonUtility.FromJson<SaveFileHeader>((length == 0) ? reader.ReadString() : reader.ReadString(length));
	}

	public static string getLatestSaveForLevel(string levelId)
	{
		string path = Path.Combine(levelSavesRootPath, levelId);
		if (!Directory.Exists(path))
		{
			UnityEngine.Debug.LogWarning("Could not get latest save for level '" + levelId + "' as directory for that level does not exist.");
			return null;
		}
		string result = null;
		long num = -1L;
		string[] files = Directory.GetFiles(path);
		foreach (string text in files)
		{
			try
			{
				SaveFileHeader saveFileHeader = readSaveFileHeader(text);
				if (saveFileHeader != null && saveFileHeader.lastSaveTimeInTicks > num)
				{
					num = saveFileHeader.lastSaveTimeInTicks;
					result = text;
				}
			}
			catch
			{
			}
		}
		return result;
	}

	public static bool isSaveFileCompatibleWithLevel(string saveFilePath, string levelId)
	{
		if (string.IsNullOrEmpty(saveFilePath))
		{
			return false;
		}
		try
		{
			return isSaveFileCompatibleWithLevel(readSaveFileHeader(saveFilePath), levelId);
		}
		catch
		{
			return false;
		}
	}

	private static bool isSaveFileCompatibleWithLevel(SaveFileHeader header, string levelId)
	{
		if (header == null)
		{
			return false;
		}
		try
		{
			string gameVersion = header.gameVersion;
			string fullGameVersion = Version.fullGameVersion;
			if (gameVersion != fullGameVersion)
			{
				return false;
			}
			string levelVersion = header.levelVersion;
			string version = RoomDatabase.getVersion(levelId);
			if (levelVersion != version)
			{
				return false;
			}
			return header.levelIdentifier == levelId;
		}
		catch
		{
			return false;
		}
	}

