	public static void recalculateSaveableObjects(GameStarter gameStarter, HashSet<Component> referencedComponents = null, HashSet<GameObject> referencedGameObjects = null, HashSet<Transform> referencedTransforms = null, HashSet<ParticleSystem> referencedParticleSystems = null, HashSet<VisualEffect> referencedVisualEffects = null, HashSet<LineRenderer> referencedLineRenderers = null, HashSet<Text> referencedTexts = null, HashSet<TMP_Text> referencedTextsTMP = null, HashSet<Image> referencedImages = null, HashSet<SpriteRenderer> referencedSpriteRenderers = null, HashSet<Sprite> referencedSprites = null)
	{
		gameStarter.saveableGameObjects = new List<GameObject>();
		gameStarter.saveableComponents = new List<Component>();
		gameStarter.saveableEnabledComponents = new List<Component>();
		gameStarter.saveableTransforms = new List<Transform>();
		gameStarter.saveableParticleSystems = new List<ParticleSystem>();
		gameStarter.saveableVisualEffects = new List<VisualEffect>();
		gameStarter.saveableLineRenderers = new List<LineRenderer>();
		gameStarter.saveableTexts = new List<Text>();
		gameStarter.saveableTextsTMP = new List<TMP_Text>();
		gameStarter.saveableImages = new List<Image>();
		gameStarter.saveableSpriteRenderers = new List<SpriteRenderer>();
		GameStarter gameStarter2 = gameStarter;
		IEnumerable<Sprite> collection;
		if (referencedSprites == null)
		{
			IEnumerable<Sprite> enumerable = Array.Empty<Sprite>();
			collection = enumerable;
		}
		else
		{
			IEnumerable<Sprite> enumerable = referencedSprites;
			collection = enumerable;
		}
		gameStarter2.saveableSprites = new List<Sprite>(collection);
		HashSet<GameObject> breakableColliders = findAllBreakableColliders();
		HashSet<GameObject> turnableRoots = findAllTurnableRoots();
		HashSet<GameObject> dialRoots = findAllDialRoots();
		gameStarter.saveableTransforms.Add(gameStarter.levelContainer.transform);
		UnityUtils.visitGameObject(gameStarter.levelContainer, delegate(GameObject go)
		{
			Component[] components = go.GetComponents<Component>();
			Component[] array = components;
			foreach (Component component in array)
			{
				if (component is ISaveable)
				{
					gameStarter.saveableComponents.Add(component);
				}
			}
			array = components;
			foreach (Component component2 in array)
			{
				if ((component2 is Renderer || component2 is Collider || component2 is NavMeshObstacle || component2 is Animation || component2 is AnimationSampler || component2 is VisualEffect || component2 is Ladder || component2 is Trigger || component2 is Camera) && (referencedComponents == null || referencedComponents.Contains(component2)))
				{
					gameStarter.saveableEnabledComponents.Add(component2);
				}
			}
			bool num = go.GetComponent<Interactive>() != null;
			bool flag = referencedGameObjects == null || referencedGameObjects.Contains(go);
			bool flag2 = referencedTransforms == null || referencedTransforms.Contains(go.transform);
			bool flag3 = breakableColliders.Contains(go);
			bool flag4 = turnableRoots.Contains(go);
			bool flag5 = dialRoots.Contains(go);
			if (num || flag || flag3)
			{
				gameStarter.saveableGameObjects.Add(go);
			}
			if (num || flag2 || flag4 || flag5)
			{
				gameStarter.saveableTransforms.Add(go.transform);
			}
			if (go.TryGetComponent<ParticleSystem>(out var component3) && (referencedParticleSystems == null || referencedParticleSystems.Contains(component3)))
			{
				gameStarter.saveableParticleSystems.Add(component3);
			}
			if (go.TryGetComponent<VisualEffect>(out var component4) && (referencedVisualEffects == null || referencedVisualEffects.Contains(component4)))
			{
				gameStarter.saveableVisualEffects.Add(component4);
			}
			if (go.TryGetComponent<LineRenderer>(out var component5) && (referencedLineRenderers == null || referencedLineRenderers.Contains(component5)))
			{
				gameStarter.saveableLineRenderers.Add(component5);
			}
			if (go.TryGetComponent<Text>(out var component6) && (referencedTexts == null || referencedTexts.Contains(component6)))
			{
				gameStarter.saveableTexts.Add(component6);
			}
			if (go.TryGetComponent<TMP_Text>(out var component7) && (referencedTextsTMP == null || referencedTextsTMP.Contains(component7)))
			{
				gameStarter.saveableTextsTMP.Add(component7);
			}
			if (go.TryGetComponent<Image>(out var component8) && (referencedImages == null || referencedImages.Contains(component8)))
			{
				gameStarter.saveableImages.Add(component8);
				if (component8.sprite != null && !gameStarter.saveableSprites.Contains(component8.sprite))
				{
					gameStarter.saveableSprites.Add(component8.sprite);
				}
			}
			if (go.TryGetComponent<SpriteRenderer>(out var component9) && (referencedSpriteRenderers == null || referencedSpriteRenderers.Contains(component9)))
			{
				gameStarter.saveableSpriteRenderers.Add(component9);
				if (component9.sprite != null && !gameStarter.saveableSprites.Contains(component9.sprite))
				{
					gameStarter.saveableSprites.Add(component9.sprite);
				}
			}
		});
		UnityEngine.Debug.Log(string.Format("{0} saveable game-objects found.\n\n{1}", gameStarter.saveableGameObjects.Count, string.Join("\n", gameStarter.saveableGameObjects)));
		UnityEngine.Debug.Log(string.Format("{0} saveable components found.\n\n{1}", gameStarter.saveableComponents.Count, string.Join("\n", gameStarter.saveableComponents)));
		UnityEngine.Debug.Log(string.Format("{0} enabled-state components found.\n\n{1}", gameStarter.saveableEnabledComponents.Count, string.Join("\n", gameStarter.saveableEnabledComponents)));
		UnityEngine.Debug.Log(string.Format("{0} saveable transforms found.\n\n{1}", gameStarter.saveableTransforms.Count, string.Join("\n", gameStarter.saveableTransforms)));
		UnityEngine.Debug.Log(string.Format("{0} saveable particle systems.\n\n{1}", gameStarter.saveableParticleSystems.Count, string.Join("\n", gameStarter.saveableParticleSystems)));
		UnityEngine.Debug.Log(string.Format("{0} saveable visual effects.\n\n{1}", gameStarter.saveableVisualEffects.Count, string.Join("\n", gameStarter.saveableVisualEffects)));
		UnityEngine.Debug.Log(string.Format("{0} saveable line renderers.\n\n{1}", gameStarter.saveableLineRenderers.Count, string.Join("\n", gameStarter.saveableLineRenderers)));
		UnityEngine.Debug.Log(string.Format("{0} saveable texts.\n\n{1}", gameStarter.saveableTexts.Count, string.Join("\n", gameStarter.saveableTexts)));
		UnityEngine.Debug.Log(string.Format("{0} saveable TMP texts.\n\n{1}", gameStarter.saveableTextsTMP.Count, string.Join("\n", gameStarter.saveableTextsTMP)));
		UnityEngine.Debug.Log(string.Format("{0} saveable images.\n\n{1}", gameStarter.saveableImages.Count, string.Join("\n", gameStarter.saveableImages)));
		UnityEngine.Debug.Log(string.Format("{0} saveable sprite renderers.\n\n{1}", gameStarter.saveableSpriteRenderers.Count, string.Join("\n", gameStarter.saveableSpriteRenderers)));
		UnityEngine.Debug.Log(string.Format("{0} saveable sprites.\n\n{1}", gameStarter.saveableSprites.Count, string.Join("\n", gameStarter.saveableSprites)));
		static HashSet<GameObject> findAllBreakableColliders()
		{
			HashSet<GameObject> hashSet = new HashSet<GameObject>();
			Breakable[] array = UnityEngine.Object.FindObjectsByType<Breakable>(FindObjectsSortMode.None);
			foreach (Breakable breakable in array)
			{
				if (!(breakable == null) && breakable.additionalOriginalRenderers != null)
				{
					hashSet.UnionWith(breakable.additionalOriginalRenderers);
				}
			}
			return hashSet;
		}
		static HashSet<GameObject> findAllDialRoots()
		{
			HashSet<GameObject> hashSet = new HashSet<GameObject>();
			Dial[] array = UnityEngine.Object.FindObjectsByType<Dial>(FindObjectsSortMode.None);
			foreach (Dial dial in array)
			{
				if (!(dial == null) && !(dial.root == null))
				{
					hashSet.Add(dial.root.gameObject);
				}
			}
			return hashSet;
		}
		static HashSet<GameObject> findAllTurnableRoots()
		{
			HashSet<GameObject> hashSet = new HashSet<GameObject>();
			Turnable[] array = UnityEngine.Object.FindObjectsByType<Turnable>(FindObjectsSortMode.None);
			foreach (Turnable turnable in array)
			{
				if (!(turnable == null) && !(turnable.root == null))
				{
					hashSet.Add(turnable.root.gameObject);
				}
			}
			return hashSet;
		}
	}

