	public void quitToMenu(bool continueSession)
	{
		UnityEngine.Debug.Log(string.Format("{0}: {1} isHost: {2} players: {3}", "quitToMenu", continueSession, isHost(), getAllPlayers().Count));
		if (!continueSession)
		{
			session.send(new KickPlayerPacket
			{
				playerBeingKicked = session.localPlayerId
			});
			createNewSession();
			if (Is.Steam && !Is.perfTest())
			{
				session.startHost(LobbyType.SteamPine, ConnectionMode.SteamMessages);
			}
			else
			{
				session.startHost(LobbyType.Offline, ConnectionMode.Offline);
			}
			Menu.shouldEnterPoseInInit = true;
		}
		loadScene("Lobby1", shouldLoadLatestSave: true);
	}

	public void startSceneCheck(string levelId, SceneCheckPostEvent postEvent, NetPlayerId requestingPlayerId)
	{
		if (!isHost() || currentSceneCheck != null)
		{
			UnityEngine.Debug.LogError("Cannot start scene check, already in progress or not host.");
		}
		else if (ESUGC.current.isCustomLevel(levelId))
		{
			currentSceneCheck = new SceneCheck
			{
				sceneName = levelId,
				postCheckEvent = postEvent,
				requestingPlayerId = requestingPlayerId
			};
			ESUGC.current.getVersion(levelId, delegate(uint num)
			{
				string text = num.ToString();
				CanLoadSceneResult result2 = canSceneLoadLocally(levelId, text, text);
				addPlayerToSceneCheck(session.localPlayerId, result2);
				session.send(new SceneCheckRequestPacket
				{
					levelName = levelId,
					versionToCheck = text
				}, allowSendInMessageResponse: true);
			}, delegate(string error)
			{
				addPlayerToSceneCheck(session.localPlayerId, CanLoadSceneResult.CannotLoadUGCFail);
				UnityEngine.Debug.LogError("Failed to get version for custom level " + levelId + ": " + error);
			});
			UnityEngine.Debug.Log("startSceneCheck Custom Level ID: " + levelId);
		}
		else
		{
			string version = RoomDatabase.getVersion(levelId);
			currentSceneCheck = new SceneCheck
			{
				sceneName = levelId,
				postCheckEvent = postEvent,
				requestingPlayerId = requestingPlayerId
			};
			CanLoadSceneResult result = canSceneLoadLocally(levelId, version, version);
			addPlayerToSceneCheck(session.localPlayerId, result);
			UnityEngine.Debug.Log(string.Format("{0} Level ID: {1} | Local version: {2} | Post check event: {3} | Requested by: {4}", "startSceneCheck", levelId, version, postEvent, session.getUsername(requestingPlayerId)));
			session.send(new SceneCheckRequestPacket
			{
				levelName = levelId,
				versionToCheck = version
			}, allowSendInMessageResponse: true);
		}
	}

	private void addPlayerToSceneCheck(NetPlayerId playerId, CanLoadSceneResult result)
	{
		UnityEngine.Debug.Log(string.Format("{0} Player ID: {1}, Result: {2}", "addPlayerToSceneCheck", playerId, result));
		if (result == CanLoadSceneResult.CanLoad)
		{
			currentSceneCheck.validPlayers.Add(playerId);
		}
		else
		{
			currentSceneCheck.invalidPlayers.Add((playerId, result));
		}
		if (currentSceneCheck.validPlayers.Count == session.players.Count && currentSceneCheck.postCheckEvent != SceneCheckPostEvent.None)
		{
			loadScene(currentSceneCheck.sceneName, currentSceneCheck.postCheckEvent == SceneCheckPostEvent.LoadSceneAndSave);
		}
	}

	public void stopCurrentSceneCheck()
	{
		if (currentSceneCheck != null)
		{
			currentSceneCheck = null;
		}
	}

	public bool canSceneLoad(string sceneName)
	{
		if (currentSceneCheck == null)
		{
			return false;
		}
		if (currentSceneCheck.sceneName != sceneName)
		{
			return false;
		}
		if (currentSceneCheck.invalidPlayers.Count != 0)
		{
			return false;
		}
		if (currentSceneCheck.validPlayers.Count != session.players.Count)
		{
			return false;
		}
		return true;
	}

	private CanLoadSceneResult canSceneLoadLocally(string levelId, string localVersion, string neededVersion)
	{
		if (ESUGC.current.isCustomLevel(levelId))
		{
			if (ESUGC.current.customRoomState(levelId) == CustomRoomState.Installed)
			{
				return CanLoadSceneResult.CanLoad;
			}
			return CanLoadSceneResult.CannotLoadNotInstalled;
		}
		UnityEngine.Debug.Log("canSceneLoadLocally Level ID: " + levelId + " | Local version: " + localVersion + " | Needed version: " + neededVersion);
		if (localVersion != neededVersion)
		{
			return CanLoadSceneResult.CannotLoadWrongVersion;
		}
		if (levelId.Contains("Darkest") && session.isHost(session.localPlayerId) && !PlayerSave.isLevelFinished(levelId.Replace("Darkest", string.Empty)) && !Is.Editor)
		{
			return CanLoadSceneResult.CannotLoadDidntUnlockDarkest;
		}
		RoomDatabase.Room room = RoomDatabase.getRoom(levelId);
		if (room != null && !room.isInDemo && Is.Demo)
		{
			return CanLoadSceneResult.CannotLoadNotInDemo;
		}
		return CanLoadSceneResult.CanLoad;
	}

	public string calculateNextSceneName()
	{
		if (isDemoLobby())
		{
			string item = SceneManager.GetActiveScene().name;
			int num = demoGameLevelOrder.IndexOf(item);
			if (num >= 0 && num < demoGameLevelOrder.Count - 1)
			{
				return demoGameLevelOrder[num + 1];
			}
			return "Dracula1";
		}
		RoomDatabase.Room room = RoomDatabase.getRoom(levelIdentifier);
		return $"{getTitleCase(room.pack.name)}{room.index + 1}";
	}

