	public void requestLoadSceneFromHost(string sceneName, bool shouldLoadLatestSave = false)
	{
		session.sendToSpecificPlayer(new SceneLoadRequestPacket
		{
			sceneName = sceneName,
			shouldLoadLatestSave = shouldLoadLatestSave
		}, session.hostPlayerId);
