	public void loadScene(string sceneName, bool shouldLoadLatestSave)
	{
		UnityEngine.Debug.Log(string.Format("{0}: {1} | {2}: {3}", "loadScene", sceneName, "shouldLoadLatestSave", shouldLoadLatestSave));
		if (session != null && isHost())
		{
			session.send(new SceneLoadPacket
			{
				sceneName = sceneName
			}, allowSendInMessageResponse: true);
			foreach (NetPlayerData player in session.players)
			{
				if (!session.isLocalPlayer(player.id))
				{
					session.setUnsynced(player.id);
				}
			}
		}
		cleanUpScreenShared();
		string hintForScene = getHintForScene(sceneName);
		Texture2D texture2D = null;
		string title;
		if (ESUGC.current.isCustomLevel(sceneName))
		{
			if (ESUGC.cachedRoomData.ContainsKey(sceneName))
			{
				ESUGC.CachedRoomData cachedRoomData = ESUGC.cachedRoomData[sceneName];
				title = cachedRoomData.name;
				texture2D = Menu.loadTexture(Path.Combine(cachedRoomData.installLocation, "Preview.jpg"));
			}
			else
			{
				title = Localization.lookupInDictionary("CustomRoom");
			}
		}
		else
		{
			title = Localization.lookupInDictionary(RoomDatabase.roomNameToLocalizationKey(sceneName));
			texture2D = AssetBundleLoader.getAsset<Texture2D>(AssetBundleType.RoomMetaAssets, "Assets/_RoomMetaAssets/" + sceneName + ".jpg");
		}
		LoadingCanvas.EndCondition sceneLoadCondition = LoadingCanvas.get().enqueueEndCondition(Localization.lookupInDictionary("Toy1_Loading"), title, showSpinner: true, 1f, sceneName);
		if (sceneName == "Lobby1" || sceneName == "RoomEditor")
		{
			LoadingCanvas.get().stopDissolveEffectNextTime();
		}
		else
		{
			LoadingCanvas.get().useDissolveEffectNextTime();
		}
		loadSceneData = new LoadSceneData
		{
			sceneLoadCondition = sceneLoadCondition,
			sceneName = sceneName,
			title = title,
			hint = hintForScene
		};
		UnityEngine.Debug.Log(sceneName + " " + texture2D);
		LoadingCanvas.get().changeImage(texture2D);
		saveSystemLoadLatestSaveLevelId = ((shouldLoadLatestSave && !(sceneName == "Lobby1")) ? sceneName : null);
	}

	public void updateLoadScene()
	{
		if (loadSceneData != null && LoadingCanvas.get().isOpaque())
		{
			PineFmod.killSoundsInBus(PineFmod.getBus("bus:/Sound Effects"));
			PineFmod.killSoundsInBus(PineFmod.getBus("bus:/Music"));
			session.whitelist = null;
			loadSceneData.sceneLoadCondition.done = true;
			if (ESUGC.current != null && ESUGC.current.isCustomLevel(loadSceneData.sceneName))
			{
				CustomLevelLoader.data = new CustomLevelLoaderData
				{
					roomId = ESUGC.current.getId(loadSceneData.sceneName),
					path = ESUGC.current.getPath(loadSceneData.sceneName)
				};
				PineSceneManager.loadScene("CustomLevel", loadSceneData.title, loadSceneData.hint, null);
			}
			else
			{
				PineSceneManager.loadScene(loadSceneData.sceneName, loadSceneData.title, loadSceneData.hint, null);
			}
			loadSceneData = null;
		}
	}

	public void startTransitionLocal(Transform transform, float duration, float delay = 0f, Vector3? position = null, Quaternion? rotation = null, Vector3? scale = null, Interpolation interpolation = Interpolation.SmootherStep)
	{
		startTransitionInternal(new DefaultNoIdentifierTransition(), transform, duration, delay, position, rotation, scale, interpolation);
	}

	public void startTransitionGlobal(Transform transform, float duration, float delay = 0f, Vector3? position = null, Quaternion? rotation = null, Vector3? scale = null, Interpolation interpolation = Interpolation.SmootherStep)
	{
		startTransitionInternal(new DefaultNoIdentifierTransition(), transform, duration, delay, position, rotation, scale, interpolation, isGlobal: true);
	}

	public void startTransitionLocal(Transition transition, Transform transform, float duration, float delay = 0f, Vector3? position = null, Quaternion? rotation = null, Vector3? scale = null, Interpolation interpolation = Interpolation.SmootherStep)
	{
		startTransitionInternal(transition, transform, duration, delay, position, rotation, scale, interpolation);
	}

	public void startTransitionGlobal(Transition transition, Transform transform, float duration, float delay = 0f, Vector3? position = null, Quaternion? rotation = null, Vector3? scale = null, Interpolation interpolation = Interpolation.SmootherStep)
	{
		startTransitionInternal(transition, transform, duration, delay, position, rotation, scale, interpolation, isGlobal: true);
	}

	private void startTransitionInternal(Transition transition, Transform transform, float duration, float delay = 0f, Vector3? position = null, Quaternion? rotation = null, Vector3? scale = null, Interpolation interpolation = Interpolation.SmootherStep, bool isGlobal = false)
	{
		transition.transform = transform;
		transition.isGlobal = isGlobal;
		transition.interpolation = interpolation;
		transition.originalPosition = (isGlobal ? transform.position : transform.localPosition);
		transition.originalRotation = (isGlobal ? transform.rotation : transform.localRotation);
		transition.originalScale = transform.localScale;
		transition.targetPosition = position ?? transition.originalPosition;
		transition.targetRotation = rotation ?? transition.originalRotation;
		transition.targetScale = scale ?? transition.originalScale;
		startTimer(transition, duration, delay);
	}

	public void startTimer(Timer timer, float duration, float delay = 0f)
	{
		timer.time = 0f - delay;
		timer.duration = duration;
		timers.Add(timer);
	}

	public List<Timer> getTimers<T>(Predicate<T> filter = null) where T : Timer
	{
		List<Timer> list = new List<Timer>();
		foreach (Timer timer in timers)
		{
			if (typeof(T).IsAssignableFrom(timer.GetType()) && (filter == null || filter((T)timer)))
			{
				list.Add(timer);
			}
		}
		return list;
	}

	public void cancelTimers<T>(Predicate<T> filter = null) where T : Timer
	{
		foreach (Timer timer in timers)
		{
			if (typeof(T).IsAssignableFrom(timer.GetType()) && (filter == null || filter((T)timer)))
			{
				timer.isCancelled = true;
			}
		}
	}

	private void updateTimers(float deltaTime)
	{
		int count = timers.Count;
		int removalCount = 0;
		for (int i = 0; i < count; i++)
		{
			int index = i - removalCount;
			Timer timer = timers[index];
			if (timer.isCancelled)
			{
				finishTimer();
				continue;
			}
			timer.time = Mathf.Min(timer.duration, timer.time + deltaTime);
			if (!(timer.time < 0f))
			{
				if (timer is Transition transition)
				{
					updateTransition(transition);
				}
				levelLogic.onTimerUpdate(timer);
				if (timer.time >= timer.duration)
				{
					finishTimer();
				}
			}
			void finishTimer()
			{
				timers.RemoveAt(index);
				removalCount++;
				levelLogic.onTimerDone(timer);
			}
		}
	}

	private void updateTransition(Transition transition)
	{
		float t = transition.interpolation.evaluate(transition.unitTime);
		if (transition.isGlobal)
		{
			transition.transform.position = Vector3.Lerp(transition.originalPosition, transition.targetPosition, t);
			transition.transform.rotation = Quaternion.Lerp(transition.originalRotation, transition.targetRotation, t);
		}
		else
		{
			transition.transform.localPosition = Vector3.Lerp(transition.originalPosition, transition.targetPosition, t);
			transition.transform.localRotation = Quaternion.Lerp(transition.originalRotation, transition.targetRotation, t);
		}
		transition.transform.localScale = Vector3.Lerp(transition.originalScale, transition.targetScale, t);
	}

