	private void handleTrashcanTriggers()
	{
		foreach (Trashcan.Pair item in trashcanEnterLastFrame)
		{
			Rigidbody componentInParent = item.enter.GetComponentInParent<Rigidbody>();
			if (!(componentInParent == null) && !(componentInParent.mass >= 5f) && !(componentInParent.GetComponent<Breakable>() != null))
			{
				Item componentInParent2 = item.enter.GetComponentInParent<Item>();
				if (!(componentInParent2 == null) && hasAuthority(item.enter) && componentInParent.gameObject.layer != LayerMask.NameToLayer("Zoom") && componentInParent.gameObject.layer != LayerMask.NameToLayer("RoomEditorSpecialObject") && !componentInParent.gameObject.TryGetComponent<Trashcan>(out var _))
				{
					addItemToTrash(componentInParent2);
				}
			}
		}
		trashcanEnterLastFrame.Clear();
	}

	private void addItemToTrash(Item item)
	{
		if (item == null)
		{
			UnityEngine.Debug.LogError("Cannot add null item to trash.");
			return;
		}
		if (item.carriable)
		{
			UnityEngine.Debug.Log("Cannot add carriable item '" + item.name + "' to trash.", item);
			return;
		}
		if (isInTrashcan(item.gameObject))
		{
			UnityEngine.Debug.LogError("Cannot add item '" + item.name + "' to trash as it is already in trash.", item);
			return;
		}
		if (item.TryGetComponent<Breakable>(out var component) && component.isBrokenIntoPieces)
		{
			UnityEngine.Debug.LogError("Cannot add Breakable '" + item.name + "' to trash as it is broken into pieces.", item);
			return;
		}
		if (getItemState(item) == ItemState.SlotAnimation)
		{
			UnityEngine.Debug.LogError("Cannot add item '" + item.name + "' to trash as it is being animated towards slot.", item);
			return;
		}
		if (isLoadingSaveFile && !item.gameObject.activeInHierarchy)
		{
			setParent(item.transform, levelContainerTransform);
			item.gameObject.SetActive(value: true);
		}
		InventoryItem inventoryItem = null;
		foreach (InventoryItem item2 in trashInventory)
		{
			Item component2 = item2.gameObjects[0].GetComponent<Item>();
			if (!(component2 == null) && component2.collectionId != 0 && component2.collectionId == item.collectionId)
			{
				inventoryItem = item2;
			}
		}
		removeFromBehindObjectCommandBuffer(item.gameObject);
		Vector3 position = item.transform.position;
		Quaternion rotation = item.transform.rotation;
		Vector3 lossyScale = item.transform.lossyScale;
		Vector3 position2 = item.transform.position;
		Quaternion rotation2 = item.transform.rotation;
		Vector3 localScale = item.transform.localScale;
		Vector3 localScale2 = zoomAttachment.localScale;
		zoomAttachment.localScale = Vector3.one;
		setParent(item.transform, levelContainerTransform);
		zoomAttachment.localScale = localScale2;
		Bounds bounds = computeLocalBounds(item.gameObject);
		if (inventoryItem != null)
		{
			inventoryItem.gameObjects.Add(item.gameObject);
			inventoryItem.localBoundsCollection.Add(bounds);
			UnityEngine.Object.Destroy(inventoryItem.impostorClone);
			inventoryItem.impostorClone = createInventoryImpostor(item.gameObject);
			inventoryItem.impostorClone.gameObject.SetActive(value: false);
			inventoryItem.localBounds = bounds;
			inventoryItem.scenePosition = position;
			inventoryItem.sceneRotation = rotation;
			inventoryItem.sceneLocalScale = lossyScale;
		}
		else
		{
			createInventorySlot(InventorySource.Trash);
			InventoryItem inventoryItem2 = new InventoryItem
			{
				transitionTime = 1000f,
				transitionPosition = position2,
				transitionRotation = rotation2,
				transitionScale = localScale * (playerCamera.fieldOfView / defaultFOV)
			};
			inventoryItem2.scenePosition = position;
			inventoryItem2.sceneRotation = rotation;
			inventoryItem2.sceneLocalScale = lossyScale;
			inventoryItem2.localBounds = bounds;
			inventoryItem2.gameObjects.Add(item.gameObject);
			inventoryItem2.localBoundsCollection.Add(bounds);
			inventoryItem2.impostorClone = createInventoryImpostor(item.gameObject);
			inventoryItem2.impostorClone.gameObject.SetActive(value: false);
			inventoryItem2.transitionPosition = inventoryItem2.impostorClone.transform.localPosition;
			inventoryItem2.transitionRotation = inventoryItem2.impostorClone.transform.localRotation;
			inventoryItem2.transitionScale = inventoryItem2.impostorClone.transform.localScale;
			trashInventory.Add(inventoryItem2);
		}
		if (!isLoadingSaveFile && trashcans != null && trashcans.Length != 0)
		{
			Trashcan trashcan = findClosestTrashcan(item);
			if (trashcan.poofPosition != null)
			{
				UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(animationPoof, trashcan.poofPosition.position, Quaternion.identity, levelContainer.transform), 1f);
			}
			if (Time.time - lastTrashAudioPlayTime > 0.1f)
			{
				lastTrashAudioPlayTime = Time.time;
				PineFmod.playOneShotSoundAttached("event:/Sound Effects/00 General/Trash_Can_Throw_In", trashcan.gameObject);
			}
			updateTrashcanTrashPosition();
		}
		syncControllerInventorySlotPositions();
		if (!isLoadingSaveFile)
		{
			session.send(new AddItemToTrashPacket
			{
				item = item
			});
		}
		item.gameObject.SetActive(value: false);
	}

	private void removeItemFromTrash(Item item)
	{
		if (item == null)
		{
			UnityEngine.Debug.LogError("Cannot remove null item from trash.");
			return;
		}
		if (getItemState(item) == ItemState.SlotAnimation)
		{
			UnityEngine.Debug.LogError($"Trying to remove an item '{item}' that is animating towards slot.", item);
			return;
		}
		InventoryItem inventoryItem = trashInventory.Find((InventoryItem inventoryItem2) => inventoryItem2.gameObjects.Contains(item.gameObject));
		if (inventoryItem == null)
		{
			UnityEngine.Debug.LogError($"Cannot remove item '{item}' from trash as it is not in trash.", item);
			return;
		}
		if (!isLoadingSaveFile)
		{
			session.send(new RemoveItemFromTrashPacket
			{
				item = item
			});
		}
		if (inventoryItem.gameObjects.Count > 1)
		{
			int index = inventoryItem.gameObjects.IndexOf(item.gameObject);
			inventoryItem.gameObjects.RemoveAt(index);
			inventoryItem.localBoundsCollection.RemoveAt(index);
			inventoryItem.localBounds = inventoryItem.topLocalBounds();
			UnityEngine.Object.Destroy(inventoryItem.impostorClone);
			inventoryItem.impostorClone = createInventoryImpostor(inventoryItem.topGameObject());
			if (!isTrashFocusOpen)
			{
				inventoryItem.impostorClone.gameObject.SetActive(value: false);
			}
		}
		else
		{
			InventorySlot inventorySlot = trashInventorySlots[trashInventory.Count - 1];
			GameObject gameObject = inventorySlot.ui.Pocket.gameObject;
			if (trashInventory.Count > 1)
			{
				gameObject.transform.localScale = Vector3.zero;
			}
			gameObject.SetActive(controlMode.current != ControlMode.MouseAndKeyboard);
			GameObject gameObject2 = inventorySlot.ui.Circle.gameObject;
			PineTweenSystemEnableNoHandles gameplayTween = getGameplayTween();
			Vector3? scaleTo = Vector3.zero;
			gameplayTween.tween(gameObject2, 0.2f, 0f, deactivate: false, activate: false, destroy: false, null, null, null, null, null, null, null, null, null, null, null, null, null, scaleTo);
			InventorySlot inventorySlot2 = trashInventorySlots[trashInventory.Count];
			if (controlMode.current == ControlMode.MouseAndKeyboard)
			{
				getGameplayTween().destroyTweens(inventorySlot2.ui.gameObject);
				getGameplayTween().destroyTweens(inventorySlot2.ui.Circle.gameObject);
				getGameplayTween().destroyTweens(inventorySlot2.ui.Pocket.gameObject);
			}
			UnityEngine.Object.Destroy(inventorySlot2.ui.gameObject);
			UnityEngine.Object.Destroy(inventoryItem.impostorClone);
			trashInventory.Remove(inventoryItem);
			trashInventorySlots.Remove(inventorySlot2);
		}
		updateTrashcanTrashPosition();
		Vector3 localScale = zoomAttachment.transform.localScale;
		zoomAttachment.transform.localScale = Vector3.one;
		setParent(item.transform, levelContainerTransform);
		zoomAttachment.transform.localScale = localScale;
		item.gameObject.SetActive(value: true);
	}

	private bool isInTrashcan(GameObject go)
	{
		foreach (InventoryItem item in trashInventory)
		{
			foreach (GameObject gameObject in item.gameObjects)
			{
				if (gameObject == go)
				{
					return true;
				}
			}
		}
		return false;
	}

	private void updateTrashcanTrashPosition()
	{
		Trashcan[] array = trashcans;
		foreach (Trashcan trashcan in array)
		{
			if (trashcan.trashSequence == null)
			{
				UnityEngine.Debug.LogError("Trashcan sequence is null");
				break;
			}
			float goal = Mathf.Clamp01((float)trashInventory.Count / 3f);
			trashcan.trashSequence.play(-1f, goal);
		}
	}

