	private Trashcan findClosestTrashcan(Item itemThatEnteredTrash)
	{
		int num = 0;
		float num2 = float.MaxValue;
		Vector3 a = ((itemThatEnteredTrash != null) ? itemThatEnteredTrash.transform.position : playerCamera.transform.position);
		for (int i = 0; i < trashcans.Length; i++)
		{
			float num3 = Vector3.Distance(a, trashcans[i].transform.position);
			if (!(num3 >= num2))
			{
				num = i;
				num2 = num3;
			}
		}
		return trashcans[num];
	}

