	public void handleToolZoomEnter(Item tool, bool holdZoom)
	{
		zoomState = ZoomState.Zoom;
		if (!holdZoom)
		{
			cursorVisible.changeState(CursorVisibleState.VirtualVisible);
		}
		Transform transform = tool.transform;
		zoomAttachment.localScale = Vector3.one;
		zoomAttachment.localRotation = Quaternion.identity;
		transform.position = pcSelectedItemImpostors[0].transform.position;
		transform.rotation = pcSelectedItemImpostors[0].transform.rotation;
		GameObject gameObject = pcSelectedItemImpostors[0];
		zoomAttachment.rotation = transform.rotation * Quaternion.Inverse(Quaternion.Euler(tool.examineBaseRotation) * Quaternion.Euler(tool.toolZoomRotationOffset));
		zoomAttachment.transform.position = gameObject.transform.position;
		setParent(transform, zoomAttachment);
		zoomAttachment.transform.localScale = new Vector3(gameObject.transform.lossyScale.x / transform.lossyScale.x, gameObject.transform.lossyScale.y / transform.lossyScale.y, gameObject.transform.lossyScale.z / transform.lossyScale.z);
		transform.localPosition = Vector3.zero;
		transform.localRotation = Quaternion.Euler(tool.examineBaseRotation) * Quaternion.Euler(tool.toolZoomRotationOffset);
		zoomAttachment.transform.position += zoomAttachment.transform.position - transform.position;
		setParent(zoomAttachment.transform, playerCamera.transform);
		ZoomContext zoomContext = new ZoomContext();
		zoomContext.state = ZoomContextState.None;
		zoomContext.selected = tool.gameObject;
		zoomContext.counterWhenEntered = tool.zoomCounter;
		zoomContext.selectedType = ScreenTargetType.Tool;
		zoomContext.transitionPosition = zoomAttachment.localPosition;
		zoomContext.transitionRotation = zoomAttachment.localRotation;
		zoomContext.transitionScale = zoomAttachment.localScale.x;
		zoomContext.toolZoomType = ((!holdZoom) ? ToolZoomType.Modal : ToolZoomType.Hold);
		zoomContexts.Add(zoomContext);
		zoomContextForInvalidPointer = zoomContext;
		toolZoomObject = zoomContext.selected;
		if (controlMode.current == ControlMode.MouseAndKeyboard)
		{
			callbackZoomEnterPC(tool.gameObject);
		}
	}

	public bool canEnterZoomFromCurrentPose(GameObject zoom)
	{
		if (!isInPoseMode())
		{
			return true;
		}
		CharacterPose pose = localPlayerData.characterPoseContext.pose;
		if (pose.usableZoom == CharacterPose.UsableZoom.None)
		{
			return false;
		}
		if (pose.usableZoom == CharacterPose.UsableZoom.List && Array.IndexOf(pose.usableZoomList, zoom.GetComponent<Zoomable>()) == -1)
		{
			return false;
		}
		return true;
	}

