		}
		return false;
	}

	public ZoomContext handleZoomEnter(GameObject target, ScreenTargetType targetType)
	{
		UnityEngine.Debug.Log("handleZoomEnter " + target.name + " " + targetType);
		if (targetType == ScreenTargetType.Zoomable && !canEnterZoomFromCurrentPose(target))
		{
			return null;
		}
		Item component = target.GetComponent<Item>();
		if (isSelectedInPCMode(target) && itemImpostorInitialWeight < 0.9f)
		{
			return null;
		}
		if (component != null && getItemState(component) == ItemState.SlotAnimation)
		{
			return null;
		}
		if (component != null && (component.carriable || component.backgroundUpdate))
		{
			return null;
		}
		setShouldKillPointers();
		removeInteractiveHighlight();
		HDAdditionalCameraData component2 = playerCamera.GetComponent<HDAdditionalCameraData>();
		HDAdditionalCameraData.AntialiasingMode antialiasing = HDAdditionalCameraData.AntialiasingMode.SubpixelMorphologicalAntiAliasing;
		if (targetType == ScreenTargetType.Zoomable && target.TryGetComponent<Zoomable>(out var component3))
		{
			antialiasing = component3.antialiasingMode;
		}
		component2.antialiasing = antialiasing;
		if (targetType == ScreenTargetType.ItemInventory || targetType == ScreenTargetType.Item || targetType == ScreenTargetType.SharedZoom)
		{
			component2.renderingPathCustomFrameSettings.maximumLODLevel = 0;
		}
		crouchButtonTouch.gameObject.SetActive(value: false);
		isZoomedWithController = false;
		if (localPlayerData.selectedCharacter != null)
		{
			localPlayerData.isInZoom = true;
		}
		if (localPlayerData != null && targetType != ScreenTargetType.Zoomable && !isInInventory(target))
		{
			localPlayerData.lastPlayerPickUpItem = true;
		}
		PineFmod.playOneShotSound("event:/Sound Effects/00 General/Menu Sound Effects/Large/UI_ZoomIn");
		foreach (CanvasGroupHandler canvasHandler in canvasHandlers)
		{
			canvasHandler.zoomDisableInteraction(target.transform);
		}
		InventoryItem item = inventory.Find((InventoryItem inventoryItem) => inventoryItem.gameObjects.Contains(target));
		int num = inventory.IndexOf(item);
		joystickZoomHoveredInventoryItem = num;
		bool flag = lobbyZoomablesWithFrame.Find((Zoomable zoomable) => zoomable.gameObject == target) != null;
		if (debugMouseVisible && !flag)
		{
			cursorVisible.changeState(CursorVisibleState.VirtualVisible);
		}
		if (component != null && !component.soundOrbitLoop.IsNull)
		{
			zoomOrbitEmitter = target.AddComponent<StudioEventEmitter>();
			zoomOrbitEmitter.EventReference = component.soundOrbitLoop;
			PineFmod.set3DAttributes(zoomOrbitEmitter.EventInstance, PineFmod.to3DAttributes(base.transform));
		}
		if (component != null && !component.soundPickup.IsNull)
		{
			PineFmod.playOneShotSoundAttached(component.soundPickup, target.gameObject);
		}
		else
		{
			PineFmod.playOneShotSoundAttached("event:/SFX/GENERAL/zoom", target.gameObject);
		}
		Transform transform = target.transform;
		ZoomContext zoomContext = new ZoomContext();
		zoomContext.state = ZoomContextState.None;
		zoomContext.selected = target;
		zoomContext.counterWhenEntered = target.GetComponent<Interactive>().zoomCounter;
		zoomContext.originalParent = transform.parent;
		zoomContext.originalPosition = transform.position;
		zoomContext.originalRotation = transform.rotation;
		zoomContext.originalLocalScale = transform.localScale;
		zoomContext.cameraStartPosition = playerCamera.transform.position;
		if (gameState.current == GameState.Zoom)
		{
			zoomContext.initialTimeOffset = 1f;
			zoomContext.transitionTime = 1f;
		}
		zoomState = ZoomState.Zoom;
		bool flag2 = isItemPinned(target);
		closePinFirstBackgorund.gameObject.SetActive(flag2);
		setPinnedItemDimming(flag2);
		destroyGameplayTweens(zoomContext.selected);
		destroyGameplayAnimations(zoomContext.selected);
		destroyGameplayTweens(playerCamera.gameObject);
		zoomAttachment.localScale = Vector3.one;
		zoomAttachment.localRotation = Quaternion.identity;
		GameObject gameObject = null;
		if (targetType == ScreenTargetType.ItemInventory)
		{
			gameObject = ((pcSelectedItem == -1) ? inventory[0].impostorClone.gameObject : pcSelectedItemImpostors[0]);
			if (gameObject != null)
			{
				transform.position = gameObject.transform.position;
				transform.rotation = gameObject.transform.rotation;
			}
			else
			{
				transform.localPosition = playerCamera.transform.position + playerCamera.transform.TransformDirection(Vector3.forward) + Quaternion.Euler(component.examineBaseRotation) * component.examinePivotOffset;
				transform.localRotation = playerCamera.transform.rotation * Quaternion.Euler(component.examineBaseRotation);
			}
		}
		bool flag3 = targetType == ScreenTargetType.ItemInventory || targetType == ScreenTargetType.Item;
		bool flag4 = targetType == ScreenTargetType.ItemInventory || targetType == ScreenTargetType.Item;
		if (flag2)
		{
			flag4 = false;
			flag3 = false;
			PinnedItemInfo pinned = pinnedItems.Find((PinnedItemInfo pinnedItemInfo) => pinnedItemInfo.originalItem == target);
			selectPinItem(pinned);
		}
		if (targetType != ScreenTargetType.Zoomable && component != null)
		{
			GameObject gameObject2 = ((gameObject == null) ? transform.gameObject : gameObject);
			zoomAttachment.rotation = transform.rotation * Quaternion.Inverse(Quaternion.Euler(component.examineBaseRotation));
			zoomAttachment.transform.position = gameObject2.transform.position;
			setParent(transform, zoomAttachment);
			if (gameObject != null)
			{
				float x = gameObject2.transform.lossyScale.x / transform.lossyScale.x;
				float y = gameObject2.transform.lossyScale.y / transform.lossyScale.y;
				float z = gameObject2.transform.lossyScale.z / transform.lossyScale.z;
				zoomAttachment.transform.localScale = new Vector3(x, y, z);
			}
			transform.localPosition = Quaternion.Euler(component.examineBaseRotation) * component.examinePivotOffset;
			transform.localRotation = Quaternion.Euler(component.examineBaseRotation);
			zoomAttachment.transform.position += zoomAttachment.transform.position - transform.position;
		}
		if (!calculatedBoundsForZoom.ContainsKey(target))
		{
			bool useZoomFocusZone = zoomContext.selected.GetComponentInChildren<ZoomFocusZone>() != null;
			calculatedBoundsForZoom[target] = computeLocalBounds(target, overrideAcceptEditorSpecial: false, useZoomFocusZone);
		}
		zoomContext.localBounds = calculatedBoundsForZoom[target];
		if (targetType == ScreenTargetType.Zoomable || targetType == ScreenTargetType.SharedZoom)
		{
			zoomContext.transitionPosition = playerCamera.transform.position;
			zoomContext.transitionRotation = playerCamera.transform.rotation;
		}
		else
		{
			zoomContext.transitionPosition = zoomAttachment.position;
			zoomContext.transitionRotation = zoomAttachment.rotation;
			zoomContext.transitionScale = zoomAttachment.localScale.x;
			zoomContext.itemStartPos = zoomAttachment.position;
			zoomContext.itemStartRot = zoomAttachment.rotation;
		}
		if (targetType != ScreenTargetType.ItemInventory)
		{
			showZoomSlot = true;
			syncControllerInventorySlotPositions();
			zoomSlotOriginal = zoomContext.selected;
		}
		zoomContext.selectedType = targetType;
		zoomContext.onExit.Clear();
		if (component != null && component.retainZoomRotation)
		{
			examineRotationCurrent = component.retainedZoomRotation;
			examineRotationTarget = component.retainedZoomRotation;
		}
		else
		{
			examineRotationTarget = Vector2.zero;
			examineRotationCurrent = new Vector2(10f, 3f);
		}
		ZoomLod component4 = zoomContext.selected.GetComponent<ZoomLod>();
		if (component4 != null)
		{
			component4.syncLODs(isZoom: true);
		}
		zoomContexts.Add(zoomContext);
		zoomContextForInvalidPointer = zoomContext;
		setupItemUI(zoomItemUI, zoomContext.selected, canBeStreamlined: false);
		levelLogic.onZoomEnter(zoomContext.selected);
		updatePuzzleInteraction(target);
		lookTimer = 0f;
		if (controlMode.current == ControlMode.MouseAndKeyboard)
		{
			callbackZoomEnterPC(target);
		}
		bool flag5 = flag3 && canPinItem(component);
		bool flag6 = flag4 && canPinItem(component);
		zoomCanvasUI.NormalActions_PinLeft.gameObject.SetActive(flag5);
		zoomCanvasUI.NormalActions_PinRight.gameObject.SetActive(flag6);
		if (shouldInteractWithObjectInZoom(targetType))
		{
			startInteraction(target);
		}
		if (targetType != ScreenTargetType.SharedZoom)
		{
			session.send(new ExamineItemPacket
			{
				examinedItem = target,
				isEnteringExamineMode = true,
				cameraPosition = playerCamera.gameObject.transform.position,
				cameraRotation = playerCamera.gameObject.transform.rotation
			});
		}
		else
		{
			session.send(new ExamineItemSharedZoomPacket
			{
				itemBeingExamined = target,
				isEnteringExamineMode = true
			});
		}
		if (lobbyZoomablesWithFrame.Find((Zoomable zoomable) => zoomable.gameObject == target) == null)
		{
			string backLabel = "%close%";
			if (targetType == ScreenTargetType.Zoomable)
			{
				backLabel = "%leave%";
			}
			List<VisualControl> list = new List<VisualControl>();
			if (flag5)
			{
				VisualControl visualControl = new VisualControl("pinLeft", ControllerButtonActionType.UIPinLeft, "%pinLeft%", VisualControl.ControlType.Button, VisualControl.Position.BotRight);
				visualControl.hideOnMouseAndKeyboard = true;
				list.Add(visualControl);
			}
			if (flag6)
			{
				VisualControl visualControl2 = new VisualControl("pinRight", ControllerButtonActionType.UIPinRight, "%pinRight%", VisualControl.ControlType.Button, VisualControl.Position.BotRight);
				visualControl2.hideOnMouseAndKeyboard = true;
				list.Add(visualControl2);
			}
			updateDefaultZoomUiControls(targetType, component, backLabel, list.ToArray());
		}
		if (targetType == ScreenTargetType.ItemInventory)
		{
			handleZoomUpdate();
			updateItemStates();
		}
		return zoomContext;
	}

