	private bool shouldInteractWithObjectInZoom(ScreenTargetType targetType)
	{
		if (targetType != ScreenTargetType.ItemInventory && targetType != ScreenTargetType.SharedZoom && targetType != ScreenTargetType.Zoomable && targetType != ScreenTargetType.NPC)
		{
			return targetType != ScreenTargetType.Tool;
		}
		return false;
	}

	private void handleZoomUpdate()
	{
		if (!topZoomContextSafe(out var zoomContext))
		{
			return;
		}
		Interactive component = zoomContext.selected.GetComponent<Interactive>();
		if (component.zoomCounter != zoomContext.counterWhenEntered)
		{
			UnityEngine.Debug.Log("Leave zoom from interactive " + component.name + " counter diff");
			handleZoomLeave();
			return;
		}
		if (Controller.isActive() && zoomContext.selectedType != ScreenTargetType.SharedZoom && Controller.getButtonDown(ControllerButtonActionType.UIReset))
		{
			zoomRecenter();
		}
		foreach (ZoomContext zoomContext2 in zoomContexts)
		{
			zoomContext2.selected.SetActive(zoomContext == zoomContext2);
		}
		if (controlMode.current == ControlMode.VirtualGamepad)
		{
			UnityEngine.Debug.Log(gesturePinch);
			if (gesturePinch > 0f || Input.mouseScrollDelta.y > 0f)
			{
				isInZoomMode = true;
			}
			else if (gesturePinch < 0f || Input.mouseScrollDelta.y < 0f)
			{
				isInZoomMode = false;
			}
			if (isInZoomMode)
			{
				zoomContext.additionalZoom = Mathf.MoveTowards(zoomContext.additionalZoom, 0.7f, Time.deltaTime * 3f);
			}
			else
			{
				zoomContext.additionalZoom = Mathf.MoveTowards(zoomContext.additionalZoom, 0f, Time.deltaTime * 5f);
			}
		}
		Transform transform = zoomContext.selected.transform;
		zoomContext.time += Time.deltaTime;
		float num = 10f * Mathf.Clamp(zoomContext.time, 0.5f, 1f);
		if (zoomContext.time + zoomContext.initialTimeOffset >= 0.5f)
		{
			examineRotationCurrent += (examineRotationTarget - examineRotationCurrent) * (1f - Mathf.Exp((0f - num) * Time.deltaTime));
		}
		if (examineRotationChanges.TryFind((ChangeExamineRotationData changeExamineRotationData) => changeExamineRotationData.zoom == zoomContext.selected, out var element))
		{
			if (!element.started)
			{
				element.startRotation = examineRotationCurrent;
				element.started = true;
			}
			if (element.remainingTime > 0f)
			{
				Vector2 startRotation = element.startRotation;
				float value = 1f - element.remainingTime / element.totalTime;
				value = UnityUtils.smootherStep(0f, 1f, value);
				examineRotationCurrent = Vector2.Lerp(startRotation, element.endRotation, value);
				examineRotationTarget = examineRotationCurrent;
				element.remainingTime -= Time.deltaTime;
			}
			else
			{
				examineRotationCurrent = element.endRotation;
				examineRotationTarget = element.endRotation;
				examineRotationChanges.Remove(element);
			}
		}
		Quaternion quaternion = Quaternion.Euler(0f - examineRotationCurrent.y, 0f, 0f) * Quaternion.Euler(0f, 0f - examineRotationCurrent.x, 0f);
		Item component2;
		bool flag = zoomContext.selectedType == ScreenTargetType.Tool && transform.TryGetComponent<Item>(out component2) && component2.toolZoomType == ToolZoomType.Hold;
		float value2 = zoomContext.time * (flag ? 3f : 1.5f) + zoomContext.initialTimeOffset;
		float num2 = (zoomContext.transitionTime = UnityUtils.smootherStep(0f, 1f, value2));
		Zoomable component3 = zoomContext.selected.GetComponent<Zoomable>();
		ScreenTargetType selectedType = zoomContext.selectedType;
		if (selectedType == ScreenTargetType.Zoomable || selectedType == ScreenTargetType.NPC)
		{
			if (zoomContext.selectedType == ScreenTargetType.Zoomable && component3.scrollableZoom)
			{
				if (!Controller.isActive() && Mathf.Abs(Input.mouseScrollDelta.y) > 0.01f)
				{
					handleScrollZoom(zoomContext);
				}
				if (!Controller.isActive() && Input.GetMouseButton(0))
				{
					handleZoomDrag(zoomContext);
				}
				Transform transform2 = playerCamera.transform;
				Vector3 zoomInOffset = zoomContext.zoomInOffset;
				float value3 = Vector3.Dot(zoomInOffset, transform2.right);
				float value4 = Vector3.Dot(zoomInOffset, transform2.up);
				float num3 = Vector3.Dot(zoomInOffset, transform2.forward);
				float x = component3.scrollableZoomSize.x;
				float y = component3.scrollableZoomSize.y;
				float num4 = x / 2f;
				float num5 = y / 2f;
				value3 = spring(value3, num4);
				value4 = spring(value4, num5);
				if (!Input.GetMouseButton(0))
				{
					value3 = Mathf.MoveTowards(value3, Mathf.Clamp(value3, 0f - num4, num4), Time.deltaTime * 2f);
					value4 = Mathf.MoveTowards(value4, Mathf.Clamp(value4, 0f - num5, num5), Time.deltaTime * 2f);
				}
				zoomContext.zoomInOffset = transform2.right * value3 + transform2.up * value4 + transform2.forward * num3;
				zoomContext.zoomInOffsetSmooth = Vector3.Lerp(zoomContext.zoomInOffsetSmooth, zoomContext.zoomInOffset, Time.deltaTime * 10f);
			}
			Vector3 vector = Vector3.Scale(transform.localScale, transform.localRotation * zoomContext.localBounds.extents);
			UnityEngine.Debug.DrawLine(Vector3.zero, zoomContext.selected.transform.TransformPoint(zoomContext.localBounds.center), Color.blue);
			if (zoomContext.selectedType == ScreenTargetType.SharedZoom && component3 == null)
			{
				NetPlayerId playerId = getOtherZoomInPlayer(zoomContext.selected);
				if (playerId == null)
				{
					UnityEngine.Debug.LogError("Trying to get zoom player for item " + zoomContext.selected?.ToString() + " but it doesn't exists. Exiting shared zoom.", zoomContext.selected);
					handleZoomLeave();
				}
				else
				{
					GamePlayerData gamePlayerData = netPlayers.Find((GamePlayerData gamePlayerData2) => gamePlayerData2.id == playerId);
					zoomAttachment.localRotation = quaternion;
					Vector3 localPosition = Vector3.forward * 0.1f;
					if (zoomContext.positionOffset != Vector2.zero)
					{
						Vector2 vector2 = zoomOffsetLimit * Mathf.Max(zoomContext.additionalZoom, 0f);
						zoomContext.positionOffset.x = Mathf.Clamp(zoomContext.positionOffset.x, 0f - vector2.x, vector2.x);
						zoomContext.positionOffset.y = Mathf.Clamp(zoomContext.positionOffset.y, 0f - vector2.y, vector2.y);
						localPosition = new Vector3(0f - zoomContext.positionOffset.x, 0f - zoomContext.positionOffset.y, 1f);
					}
					float num6 = 1f;
					zoomAttachment.localPosition = localPosition;
					zoomAttachment.localScale = 2f * Vector3.one * Mathf.Lerp(1f, zoomItemSize / vector.magnitude * num6, num2) * Mathf.Exp(zoomContext.additionalZoomLerp);
					zoomContext.additionalZoomLerp = Mathf.MoveTowards(zoomContext.additionalZoomLerp, zoomContext.additionalZoom, Time.deltaTime * 10f);
					contestedCameraPosition.set(ContestedPose.Zoom, Vector3.Lerp(contestedCameraPosition.value(), gamePlayerData.zoomCameraPosition, num2), oneFrame: true);
					contestedCameraRotation.set(ContestedPose.Zoom, gamePlayerData.zoomCameraRotation, oneFrame: true);
				}
			}
			else if (zoomContext.selectedType == ScreenTargetType.Zoomable)
			{
				contestedCameraPosition.set(ContestedPose.Zoom, Vector3.Lerp(zoomContext.transitionPosition, component3.zoomableEyePosition + zoomContext.zoomInOffsetSmooth, num2), oneFrame: true);
				contestedCameraRotation.set(ContestedPose.Zoom, Quaternion.Lerp(zoomContext.transitionRotation, component3.zoomableEyeRotation, num2), oneFrame: true);
			}
			else
			{
				contestedCameraPosition.set(ContestedPose.Zoom, Vector3.Lerp(zoomContext.transitionPosition, component.eyePosition, num2), oneFrame: true);
				contestedCameraRotation.set(ContestedPose.Zoom, Quaternion.Lerp(zoomContext.transitionRotation, Quaternion.Euler(component.eyeRotation), num2), oneFrame: true);
			}
			contestedFov.set(ContestedFov.Zoom, Mathf.Lerp(defaultFOV, 60f, num2), oneFrame: true);
			if (Controller.isActive())
			{
				cursorTrail.gameObject.SetActive(num2 > 0.99f && pcVirtualCursor.gameObject.activeInHierarchy && pcVirtualCursor.sprite == pcCrosshairs[13]);
			}
		}
		else if (zoomContext.selectedType == ScreenTargetType.Tool)
		{
			Vector3 b = Vector3.zero;
			float b2 = 1f;
			if (transform.TryGetComponent<Item>(out var component4))
			{
				b = playerCamera.transform.InverseTransformPoint(playerCamera.ViewportToWorldPoint(new Vector3(0.85f, 0.3f, 0.3f) + component4.toolZoomPivotOffset));
				b2 = zoomContext.transitionScale * component4.toolZoomScale;
				transform.localRotation = Quaternion.Euler(component4.examineBaseRotation) * Quaternion.Euler(component4.toolZoomRotationOffset);
			}
			zoomContext.additionalZoomLerp = Mathf.MoveTowards(zoomContext.additionalZoomLerp, zoomContext.additionalZoom, Time.deltaTime * 10f);
			float num7 = Mathf.Lerp(zoomContext.transitionScale, b2, num2) * Mathf.Exp(zoomContext.additionalZoomLerp);
			zoomAttachment.localRotation = Quaternion.Lerp(zoomContext.transitionRotation, quaternion, num2);
			zoomAttachment.localPosition = Vector3.Lerp(zoomContext.transitionPosition, b, num2);
			zoomAttachment.localScale = Vector3.one * num7;
			contestedFov.set(ContestedFov.Zoom, Mathf.Lerp(defaultFOV, component4.toolZoomFov, num2), oneFrame: true);
		}
		else
		{
			Vector3 b3 = playerCamera.transform.position + playerCamera.transform.TransformDirection(Vector3.forward * 0.1f);
			float b4 = 1f;
			Item component5 = transform.GetComponent<Item>();
			if (component5 != null)
			{
				b4 = component5.examineScaleModifier * 0.1f;
				transform.localPosition = Quaternion.Euler(component5.examineBaseRotation) * component5.examinePivotOffset;
				transform.localRotation = Quaternion.Euler(component5.examineBaseRotation);
			}
			Vector3 vector3 = Vector3.zero;
			if (zoomContext.positionOffset != Vector2.zero)
			{
				Vector2 vector4 = zoomOffsetLimit * Mathf.Max(zoomContext.additionalZoom, 0f);
				zoomContext.positionOffset.x = Mathf.Clamp(zoomContext.positionOffset.x, 0f - vector4.x, vector4.x);
				zoomContext.positionOffset.y = Mathf.Clamp(zoomContext.positionOffset.y, 0f - vector4.y, vector4.y);
				vector3 = new Vector3(0f - zoomContext.positionOffset.x, 0f - zoomContext.positionOffset.y);
			}
			zoomContext.additionalZoomLerp = Mathf.MoveTowards(zoomContext.additionalZoomLerp, zoomContext.additionalZoom, Time.deltaTime * 10f);
			float b5 = (isItemPinned(zoomContext.selected) ? 0.5f : 1f);
			pinnedItemZoomScaleModifier = Mathf.Lerp(pinnedItemZoomScaleModifier, b5, Time.deltaTime * 5f);
			float num8 = Mathf.Lerp(zoomContext.transitionScale, b4, num2) * Mathf.Exp(zoomContext.additionalZoomLerp) * pinnedItemZoomScaleModifier;
			if (hasAuthority(component5.gameObject))
			{
				zoomAttachment.rotation = Quaternion.Lerp(zoomContext.transitionRotation, playerCamera.transform.rotation * quaternion, num2);
				if (isAnyPlayerZoomIn(component5.gameObject))
				{
					session.send(new SharedZoomRotationPacket
					{
						rotation = quaternion
					});
				}
				if (component5.retainZoomRotation)
				{
					component5.retainedZoomRotation = examineRotationCurrent;
				}
			}
			zoomAttachment.position = Vector3.Lerp(zoomContext.transitionPosition, b3, num2);
			zoomAttachment.localScale = Vector3.one * num8;
			zoomAttachment.localPosition += vector3 * 0.25f;
			contestedFov.set(ContestedFov.Zoom, Mathf.Lerp(defaultFOV, 60f, num2), oneFrame: true);
			if (Controller.isActive())
			{
				cursorTrail.gameObject.SetActive(pcVirtualCursor.gameObject.activeInHierarchy && pcVirtualCursor.sprite == pcCrosshairs[13]);
			}
		}
		Debug_drawBoundsLocal(zoomContext.localBounds, transform, Color.red, Color.yellow);
		static float spring(float num9, float limit)
		{
			if (Mathf.Abs(num9) <= limit)
			{
				return num9;
			}
			float num10 = Mathf.Abs(num9) - limit;
			float num11 = Mathf.Sign(num9);
			float num12 = 1f / (1f + num10 * 3f);
			return limit * num11 + num10 * num12 * num11;
		}
	}

