	private void updateDefaultZoomUiControls(ScreenTargetType targetType, Item item, string backLabel, params VisualControl[] additionalControls)
	{
		List<VisualControl> list = new List<VisualControl>();
		if (targetType == ScreenTargetType.Item || targetType == ScreenTargetType.ItemInventory)
		{
			if (item != null && isInInventory(item))
			{
				VisualControl visualControl = new VisualControl("drop", ControllerButtonActionType.UIExtra1, "%Drop%", VisualControl.ControlType.Button, VisualControl.Position.BotRight);
				visualControl.addKeybindAction(KeyBindingAction.Drop, menuOptions);
				list.Add(visualControl);
			}
			else
			{
				VisualControl visualControl2 = new VisualControl("take", ControllerButtonActionType.UIExtra1, "%take%", VisualControl.ControlType.Button, VisualControl.Position.BotRight);
				visualControl2.addKeybindAction(KeyBindingAction.Take, menuOptions);
				list.Add(visualControl2);
			}
		}
		list.AddRange(additionalControls);
		VisualControl visualControl3 = new VisualControl("back", ControllerButtonActionType.UIBack, backLabel, VisualControl.ControlType.Button, VisualControl.Position.BotRight);
		visualControl3.addEscape();
		visualControl3.addKeybindAction(KeyBindingAction.ExamineInventory, menuOptions);
		list.Add(visualControl3);
		addGameFrameSource(GameFrameSourceType.Zoom, list);
	}

	private void handleScrollZoom(ZoomContext zoomContext)
	{
		float y = Input.mouseScrollDelta.y;
		float num = Vector3.Dot(zoomContext.zoomInOffset, playerCamera.transform.forward);
		Interactive component = zoomContext.selected.GetComponent<Interactive>();
		float num2 = 0f;
		float num3 = 0f;
		float num4 = y * 0.1f;
		if (component is Zoomable zoomable)
		{
			num2 = Mathf.Max(0f, zoomable.minZoomIn);
			num3 = Mathf.Max(Vector3.Distance(zoomable.zoomableEyePosition, zoomable.transform.position) - 0.2f, zoomable.maxZoomIn);
			num4 = Mathf.Clamp(num + num4, num2, num3) - num;
		}
		Ray ray = playerCamera.ScreenPointToRay(Input.mousePosition);
		Plane plane = new Plane(-playerCamera.transform.forward, zoomContext.selected.transform.position);
		if (plane.Raycast(ray, out var enter))
		{
			Vector3 point = ray.GetPoint(enter);
			Vector3 vector = playerCamera.transform.forward * num4;
			zoomContext.zoomInOffset += vector;
			Vector3 origin = playerCamera.transform.position + vector;
			Ray ray2 = new Ray(origin, ray.direction);
			if (plane.Raycast(ray2, out var enter2))
			{
				Vector3 point2 = ray2.GetPoint(enter2);
				Vector3 vector2 = point - point2;
				zoomContext.zoomInOffset += vector2;
			}
		}
	}

	private void handleZoomDrag(ZoomContext zoomContext)
	{
		if (Input.GetMouseButtonDown(0))
		{
			Ray ray = playerCamera.ScreenPointToRay(Input.mousePosition);
			examineZoomInPlane = new Plane(-playerCamera.transform.forward, zoomContext.selected.transform.position);
			if (examineZoomInPlane.Raycast(ray, out var enter))
			{
				initialExamineDragWorldPoint = ray.GetPoint(enter);
				initialExamineMousePosition = Input.mousePosition;
			}
		}
		Vector3 vector = playerCamera.WorldToScreenPoint(initialExamineDragWorldPoint);
		Vector3 vector2 = Input.mousePosition - initialExamineMousePosition;
		Vector3 pos = vector + vector2;
		Ray ray2 = playerCamera.ScreenPointToRay(pos);
		if (new Plane(-playerCamera.transform.forward, initialExamineDragWorldPoint).Raycast(ray2, out var enter2))
		{
			Vector3 point = ray2.GetPoint(enter2);
			Vector3 vector3 = initialExamineDragWorldPoint - point;
			zoomContext.zoomInOffset += vector3;
			initialExamineDragWorldPoint = point;
			initialExamineMousePosition = Input.mousePosition;
		}
	}

	private void handleZoomOrbit(Pointer pointer, ZoomContext zoomContext)
	{
		if (zoomContext.sessionId != pointer.context.interactionSessionId)
		{
			zoomContext.sessionId = pointer.context.interactionSessionId;
			examineRotationTarget = examineRotationCurrent;
			examineRotationDownSign = ((Mathf.Sign(Mathf.Cos(examineRotationCurrent.y * (MathF.PI / 180f))) >= 0f) ? 1 : (-1));
		}
		Vector2 vector = pointer.gestureMovementViewport;
		if (Controller.isActive() && !isZoomedWithController)
		{
			Vector2 vector2 = getControllerLook() * Time.deltaTime * 0.5f;
			if (vector2 != Vector2.zero)
			{
				vector = vector2;
			}
		}
		int num = ((Mathf.Sign(Mathf.Cos(examineRotationCurrent.y * (MathF.PI / 180f))) >= 0f) ? 1 : (-1));
		if ((float)num != examineRotationDownSign)
		{
			num = 0;
		}
		examineRotationTarget.x += vector.x * 360f * (float)num;
		examineRotationTarget.y += (0f - vector.y) * 200f;
		Item component = zoomContext.selected.GetComponent<Item>();
		if (zoomOrbitEmitter != null)
		{
			if (vector != Vector2.zero)
			{
				if (!PineFmod.isPlaying(zoomOrbitEmitter))
				{
					PineFmod.play(zoomOrbitEmitter);
					if (component != null && !component.soundOrbitStart.IsNull && timeToStopOrbitEmitter <= 0f)
					{
						PineFmod.playOneShotSound(component.soundOrbitStart);
					}
				}
				timeToStopOrbitEmitter = 1f;
			}
			else
			{
				timeToStopOrbitEmitter -= Time.deltaTime;
				if (timeToStopOrbitEmitter <= 0f)
				{
					PineFmod.stop(zoomOrbitEmitter);
					if (component != null && !component.soundOrbitEnd.IsNull)
					{
						PineFmod.playOneShotSound(component.soundOrbitEnd);
					}
				}
			}
		}
		if (pointer.gestureUp)
		{
			zoomContext.state = ZoomContextState.None;
			if (zoomOrbitEmitter != null)
			{
				PineFmod.stop(zoomOrbitEmitter);
				timeToStopOrbitEmitter = 0f;
				if (component != null && !component.soundOrbitEnd.IsNull)
				{
					PineFmod.playOneShotSound(component.soundOrbitEnd);
				}
			}
		}
		if (!Controller.isActive() || !(vector == Vector2.zero))
		{
			return;
		}
		zoomContext.state = ZoomContextState.None;
		if (zoomOrbitEmitter != null)
		{
			PineFmod.stop(zoomOrbitEmitter);
			timeToStopOrbitEmitter = 0f;
			if (component != null && !component.soundOrbitEnd.IsNull)
			{
				PineFmod.playOneShotSound(component.soundOrbitEnd);
			}
		}
	}

	private void handleEnterSharedZoom(GameObject target)
	{
		if (target != null)
		{
			Zoomable component = target.GetComponent<Zoomable>();
			if (component != null)
			{
				if (isAnyPlayerZoomIn(component.gameObject))
				{
					handleZoomEnter(target, ScreenTargetType.SharedZoom);
				}
				return;
			}
			GameObject target2 = target.GetComponent<ImpostorClone>().targetRoot.gameObject;
			if (isAnyPlayerZoomIn(target2))
			{
				handleZoomEnter(target2, ScreenTargetType.SharedZoom);
			}
		}
		else
		{
			UnityEngine.Debug.LogWarning("Can't enter shared zoom because item is null");
		}
	}

	private List<Action<Interactive>> resolveStateChanges(Interactive interactable, byte[] stateBeforeEvent)
	{
		List<Action<Interactive>> list = new List<Action<Interactive>>();
		Vector3 localPosition = interactable.transform.localPosition;
		Quaternion localRotation = interactable.transform.localRotation;
		Vector3 localScale = interactable.transform.localScale;
		bool blocksRaycasts = interactable.blocksRaycasts;
		bool targetable = interactable.targetable;
		int targetPriority = interactable.targetPriority;
		RoomEditorTargetPriotity roomEditorTargetPriotity = interactable.roomEditorTargetPriotity;
		float interactionMaxDistance = interactable.interactionMaxDistance;
		float distanceExtender = interactable.distanceExtender;
		if (interactable is CharacterModels)
		{
			loadInteractable(interactable, stateBeforeEvent);
		}
		else if (interactable is CharacterPose characterPose)
		{
			bool lockedInPose = characterPose.lockedInPose;
			loadInteractable(interactable, stateBeforeEvent);
